pfDB["quests"]["plPL"] = {
  [1] = {
    ["D"] = "$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAIN",
    ["O"] = "Kill Kobold Vermin, 2 of em.",
    ["T"] = "The \"Chow\" Quest (123)aa",
  },
  [2] = {
    ["D"] = "Potężny gryf Sharptalon został zgładzony! Pazur poległej bestii stanowi świadectwo twojego zwycięstwa.$B$BSenani Thunderheart przebywająca w Posterunku Splintertree zapewne będzie chciała ujrzeć dowód twojego czynu.",
    ["O"] = "Przynieś Sharptalon\'s Claw do Senani Thunderheart przebywającej w Splintertree Post, Ashenvale.",
    ["T"] = "Pazur Sharptalona",
  },
  [5] = {
    ["D"] = "Ukrywam się w tym wymarłym mieście od tygodni. Przez ten czas nie jadłem niczego prócz korzonków i larw! Muszę zdobyć coś normalnego do jedzenia i jestem gotów sporo za to zapłacić.$B$BSpraw, abym mógł urządzić sobie małą ucztę, a sowicie cię wynagrodzę.$B$BSłyszałem, że Chef Grual, pracujący w Scarlet Raven Tavern w Darkshire przyrządza świetne Dusky Crab Cakes...",
    ["O"] = "Porozmawiaj z Chef Grual.",
    ["T"] = "Rosnący głód Trzęsiaka",
  },
  [6] = {
    ["D"] = "Garrick Padfoot - bandyta, który od dawna terroryzuje naszych farmerów oraz kupców - ukrywa się ponoć w chacie niedaleko winnicy. Jest ona położona na wschód od Opactwa, za rzeką. Przynieś mi głowę tego bandyty, a otrzymasz należną ci nagrodę!$B$BMusisz być $gostrożny:ostrożna;, $N. Garrick jest chroniony przez kilku zbirów. Nie będzie łatwo go dosięgnąć.",
    ["O"] = "Zabij Garricka Padfoota i przynieś jego głowę do Willema urzędującego w Northshire Abbey.",
    ["T"] = "Nagroda za Garricka Padfoota",
  },
  [7] = {
    ["D"] = "Twoim pierwszym zadaniem będzie oczyszczenie tutejszych terenów, $N. Grupa koboldów zasiedliła zagajnik na północ stąd. Udaj się tam, po czym zabij każdego szkodnika, jakiego napotkasz. Zredukuj ich liczbę, a być może pewnego dnia wypędzimy je z Northshire.",
    ["O"] = "Zabij 10 Kobold Vermin, po czym wróć do komendanta McBride.",
    ["T"] = "Oczyść obóz koboldów",
  },
  [8] = {
    ["D"] = "Hej, $gmłodzieńcze:młoda damo;! Wyświadcz przysługę mężczyźnie, który zawsze robił znacznie więcej niż wymagały tego obowiązki.$B$BMam tutaj wiadomość, którą trzeba dostarczyć do Brill... do oberżystki o imieniu Renee, czy coś w tym stylu. Jej nazwisko nie ma wielkiego znaczenia.$B$BW każdym razie, do bardzo przytulnego miejsca pełnego ofiar plagi, próbujących znaleźć swoje miejsce na tym świecie. Jest to także odpowiednie miejsce, aby wypocząć po trudach podróży. $gPowinieneś:Powinnaś; to sprawdzić... wykonaj zadanie, a odpowiednio cię wynagrodzę.",
    ["O"] = "Dostarcz Nondescript Letter do karczmarki Renee w Tirisfal Glades.",
    ["T"] = "Złodziejska sprawa",
  },
  [9] = {
    ["D"] = "Spójrz, co się stało z tym miejscem! Kiedyś na tych terenach żyli tylko spokojni wieśniacy. Lecz przeklęci złodzieje przepędzili ich wszystkich! Jednak nie mnie! Teraz sprawa ma się inaczej; żniwiarze przejęli kontrolę nad polami.$B$BJeśli zamierzasz mi pomóc, chciałbym, abyś $gpozbył:pozbyła; się przynajmniej dwudziestu z nich. Wróć do mnie, kiedy wykonasz zadanie, a otrzymasz swoją zapłatę. Gdy uporasz się z moim zagonem, zajmij się oczyszczaniem sąsiednich pól.",
    ["O"] = "Farmer Saldean chce, abyś $gzabił:zabiła; 20 Harvest Watchers.",
    ["T"] = "Pola śmierci",
  },
  [10] = {
    ["D"] = "To po prostu okropne! Wysłałem mojego najlepszego asystenta, Junior Surveyor Scrimshank, na południowo-wschodnią część pustyni. Nazywamy ten teren Gaping Chasm. Mój człowiek zaginął, a jego ostatni raport dotyczył głównie dziwacznego robactwa panoszącego się po pustyni. Czyżby te potwory opanowały już dwa największe rejony pustkowia?$B$BBłagam, udaj się do Gaping Chasm i znajdź Scrimshanka! Albo... przynajmniej jego przyrządy badawcze. Obawiam się, że mogą to być jedyne rzeczy, jakie pozostały po tym biednym gnojku.",
    ["O"] = "Odkryj, co stało się z Junior Surveyor Scrimshank i odstaw go lub jego sprzęt pomiarowy do Senior Surveyor Fizzledowser urzędującego w Gadgetzanie.",
    ["T"] = "Zakończenie misji Scrimshanka",
  },
  [11] = {
    ["D"] = "Gnolle, brutalne stworzenia, którym obca jest przyzwoita praca, były widziane na obrzeżach Puszczy Elwynn. Liczna grupa, zbyt duża, byśmy mogli sobie z nią poradzić, zajęła tereny w lasach na południe od wieży strażniczej. Inna grupa opanowała ziemie znajdujące się na wschodzie, w pobliżu jeziora Stone Cairn.$B$BArmia Stormwind najmie do pomocy każdego, kto będzie chętny pomóc wytępić tę zarazę. Przynieś mi kilka noszonych przez nie pomalowanych opasek jako dowód wypełnienia misji.",
    ["O"] = "Przynieś 8 Painted Gnoll Armbands do deputowanego Rainera z baraków.",
    ["T"] = "Nagroda za Rzecznołape gnolle",
  },
  [12] = {
    ["D"] = "Straż Obywatelska posiada tylko jeden cel: bronić terenów należących do Westfall oraz przywrócić spokój i porządek na pobliskich ziemiach. Niestety, bardzo często ceną za utrzymanie pokoju jest ludzkie życie.$B$BJeden ze zwiadowców doniósł mi o grupie traperów siejących spustoszenie w tej okolicy. Raporty donoszą, że członkowie Bractwa Defias byli widziani na północnym zachodzie, nieopodal kopalni Jangolode oraz farmy Molsenów i farmy dyń Furlbrow\'ów. Jeśli $gchciałbyś:chciałabyś; dołączyć do naszych szeregów, pozbądź się piętnastu traperów oraz piętnastu przemytników z Bractwa Defias, po czym wróć do mnie.",
    ["O"] = "Gryan Stoutmantle chce, abyś $gpozbył:pozbyła; się 15 Defias Trappers oraz 15 Defias Smugglers, a następnie $gwrócił:wróciła; do niego, do Sentinel Hill.",
    ["T"] = "Straż Obywatelska",
  },
  [13] = {
    ["D"] = "Widziano grupę rabusiów należących do Bractwa Defias, plądrującą Kamieniołom Złotego Brzegu, Moonbrook oraz farmę Alexstonów. Straż Obywatelska nie będzie dłużej tolerować takiego zachowania. Spiesz się, $N, pokaż, że Światłość nadal gości w Westfall!$B$BKamieniołom znajduje się blisko brzegu, na zachód od wieży strażniczej. Chcę, abyś w ramach następnego etapu swojego szkolenia $gzabił:zabiła; piętnastu z tych plugawych rabusiów oraz piętnastu grabieżców.",
    ["O"] = "Gryan Stoutmantle żąda, abyś $gpozbył:pozbyła; się 15 Defias Pillagers oraz 15 Defias Looters, a następnie $gwrócił:wróciła; do niego, do Sentinel Hill.",
    ["T"] = "Straż Obywatelska",
  },
  [14] = {
    ["D"] = "Umknęło nam kilku członków Bractwa Defias. Mój najbardziej zaufany zwiadowca doniósł mi, że właśnie ta grupa łupi i grabi ziemie całego południa Westfall. Najprawdopodobniej ukrywają się gdzieś na południu, planując swe następne posunięcie. Pozbądź się tych wyrzutków w imieniu Straży Obywatelskiej!",
    ["O"] = "Gryan Stoutmantle żąda, abyś $gpozbył:pozbyła; się 15 Defias Highwaymen, 5 Defias Pathstalkers i 5 Defias Knuckledusters, a następnie $gwrócił:wróciła; do niego, do Sentinel Hill.",
    ["T"] = "Straż Obywatelska",
  },
  [15] = {
    ["D"] = "$N, moi zwiadowcy donieśli mi, że oddziały koboldów są liczniejsze, niż nam się wydawało. Grupa koboldów pracowników rozbiła obóz w pobliżu Kopalni Kanionu Echa, na północ stąd.$B$BUdaj się w tamte rejony i zabij każdego kobolda, którego spotkasz. Wiemy, że jest ich tam przynajmniej dziesięć. Zabij je, sprawdź, czy jest ich więcej, i wróć, by złożyć raport.",
    ["O"] = "Zabij 10 Kobold Workers, po czym wróć do Marshal McBride.",
    ["T"] = "Zbadaj Kanion Echa",
  },
  [16] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Daj Gerardowi się napić",
  },
  [17] = {
    ["D"] = "Słyszałem o nowoodkrytej roślinie zwanej purpurowym kapeluszem. Rośnie ona w grupach, głęboko w ruinach Uldamanu. Jak dotąd jest to jedyne znane nam miejsce jej występowania. Chciałbym zbadać jej przydatność w sztuce alchemii i tutaj zaczyna się twoja rola, $N.$B$BZnajdź skupiska purpurowych kapeluszy i przynieś mi tuzin okazów. Musisz na nie przy tym uważać - potrząśnięte, mogą rozsiewać trujące zarodniki.$B$BZdobądź je dla mnie, a w zamian otrzymasz partię moich słynnych eliksirów wzmacniających!",
    ["O"] = "Przynieś 12 Magenta Fungus Caps do Ghaka Healtoucha z Thelsamaru.",
    ["T"] = "Wyprawa do Uldamanu po składniki",
  },
  [18] = {
    ["D"] = "Ostatnimi czasy w okolicach Northshire pojawiła się nowa grupa bandytów. Nazywają siebie Bractwem Defias. Można ich spotkać za rzeką, na wschód stąd.$B$BNie mam pojęcia, co zamierzają, ale jestem pewien, że nie wyniknie z tego nic dobrego! Przynieś mi chusty, które noszą członkowie tego ugrupowania. W nagrodę dostaniesz nowy oręż.",
    ["O"] = "Przynieś 12 Red Burlap Bandanas do deputowanego Willema przebywającego nieopodal Northshire Abbey.",
    ["T"] = "Bractwo złodziei",
  },
  [19] = {
    ["D"] = "Grupa wyrzutków i renegatów z klanu Czarnej Skały dokonuje napaści na drodze stąd do Twierdzy Stonewatch. Przywódcą tych bandytów jest ork o imieniu Tharil\'zun. Chcemy go dostać. Przynieś mi jego głowę!",
    ["O"] = "Przynieś Tharil\'zun\'s Head do komendanta Marrisa z Redridge.",
    ["T"] = "Tharil\'zun",
  },
  [20] = {
    ["D"] = "Orkowie z klanu Czarnej Skały przywędrowały na nasze tereny z Burning Steppes, po czym zajęły znajdującą się na północy Twierdzę Stonewatch. Przejęty budynek stał się ich główną bazą wypadową, co pozwoliło im na bezkarne grasowanie po tych terenach i uniemożliwiło mieszkańcom opuszczenie miasta, w którym są teraz stłoczeni niczym bydło.$B$BPomóż władzom Lakeshire pozbyć się tego zagrożenia. Przerzedź szeregi orków, a w dowód przynieś mi dziesięć ich toporów bitewnych.$B$BI choć orkowie z klanu Czarnej Skały niepokoją nas od północy, otrzymujemy raporty, iż gromadzą się także w południowo-wschodnim rejonie Redridge. Jeśli trafisz tam na któregoś z nich, jego również zabij.",
    ["O"] = "Dostarcz 10 Battleworn Axes do komendanta Marris z Lakeshire.",
    ["T"] = "Zagrożenie z Czarnej Skały",
  },
  [21] = {
    ["D"] = "Twoje poprzednie dochodzenie dowiodło, że Kopalnia Kanionu Echa musi zostać oczyszczona. Wróć do kopalni i oczyść ją z tych plugawych istot.$B$BNie trać czasu, $N. Im dłużej kopalnia jest w posiadaniu koboldów, tym silniejszy przyczółek zdobywają w Northshire.",
    ["O"] = "Zabij 12 Kobold Laborers, po czym wróć do marszałka McBride przebywającego w Northshire Abbey.",
    ["T"] = "Starcie w Kanionie Echa",
  },
  [22] = {
    ["D"] = "Obrałam cebulkę i posiekałam czosnek oraz koper. Pokroiłam rozmaryn. Ciasto prawie upieczone. Sos też już ugotowałam. Teraz potrzebuję jeszcze tylko ośmiu wątróbek krwistokła.",
    ["O"] = "Salma Saldean potrzebuje 8 Goretusk Livers, aby przygotować Goretusk Liver Pie.",
    ["T"] = "Wątróbka krwistokła w cieście",
  },
  [23] = {
    ["D"] = "Łapa potężnego niedźwiedzia, Ursangousa, stanowi twą zdobycz z tej części polowania w Ashenvale. Na łapie bestii znajduje się niewielki znak przedstawiający półksiężyc, jednak jego znaczenie owiane jest tajemnicą.$B$BŁapa powinna zostać dostarczona do Senani Thunderheart z Posterunku Splintertree na dowód zgładzenia bestii i ukończenia tej części polowania.",
    ["O"] = "Zanieś Ursangous\'s Paw do Senani Thunderheart z Splintertree Post, Ashenvale.",
    ["T"] = "Łapa Ursangousa",
  },
  [24] = {
    ["D"] = "Niegdyś zwinna Shadumbra spoczywa teraz bez ruchu, dowodząc twego zwycięstwa. Głowa pokonanej szablastozębnej pantery jest odpowiednim trofeum z tego etapu Polowania w Ashenvale. Senani Thunderheart z Splintertree Post zechce je ujrzeć, by wynagrodzić twe zasługi podczas tej części Polowania.",
    ["O"] = "Zanieś Shadumbra\'s Head do Senani Thunderheart w Splintertree Post, Ashenvale.",
    ["T"] = "Głowa Shadumbry",
  },
  [25] = {
    ["D"] = "Jeśli chcesz się przydać, czemu nie zrobisz czegoś w sprawie sytuacji niedaleko Ścieżki Talondeep?$B$BTransport między Ashenvale i Stonetalon stanął w miejscu z powodu ożywienia się jeziora, które atakuje wszystko, co się do niego zbliży... co oznacza każdego przebywającego na ścieżce. Co przydałoby się jeszcze bardziej niż tylko zatłuczenie młotem wodnych żywiołaków, to przeprowadzenie zwiadu w altance na Jeziorze Mystral - jest stamtąd niezły widok na miejscowy posterunek Przymierza.$B$B$gGotowy:Gotowa;, by pomóc?",
    ["O"] = "Zabij 12 Befouled Water Elementals z Mystral Lake, na wschód od Talondeep Path i na południowy zachód od Splintertree Post.$B$BZbadaj altanę na Mystral Lake, wychodzącą na pobliski posterunek Przymierza.$B$BWróć do Mastoka Wrilehissa w Splintertree Post, Ashenvale.",
    ["T"] = "Zastój w Stonetalon",
  },
  [26] = {
    ["D"] = "$N, obserwuję twoje poczynania z wielkim zachwytem. Stajesz się powoli $gobrońcą:obrończynią; przyrody.$B$BCzas nadszedł, abyś $gdowiedział:dowiedziała; się nieco o jednej ze zwierzęcych form, w które, dzięki Cenariusowi, możemy się zmieniać - tą, która pozwala ci opanować wodę. By to zrobić, udaj się do wioski Nighthaven w Moonglade i porozmawiaj z Dendritem Starblazem z Kręgu Cenariona. On powie ci co dalej.",
    ["O"] = "Porozmawiaj z Dendritem Starblazem w wiosce Nighthaven, w Moonglade.",
    ["T"] = "Lekcja do opanowania",
  },
  [27] = {
    ["D"] = "$N, z wielkim zadowoleniem śledzę twoje postępy. Zaprawdę, wyrastasz na $gcennego sojusznika:cenną sojuszniczkę; natury.$B$BNadszedł czas, abyś $gnauczył:nauczyła; się więcej o jednym z wielu aspektów zwierzęcych, których postać możemy przybierać dzięki błogosławieństwu Cenariusa - tym, dzięki któremu będziesz $gmógł:mogła; przewodzić i panować w wodzie. Dlatego musisz udać się do wioski Nighthaven w Moonglade i porozmawiać z Dendrite\'em Starblaze\'em z Kręgu Cenarionu. Wskaże ci dalszą drogę.",
    ["O"] = "Porozmawiaj z Dendrite\'em Starblaze\'em z wioski Nighthaven w Moonglade.",
    ["T"] = "Lekcja do pojęcia",
  },
  [28] = {
    ["D"] = "Twoja pierwsza próba polega na przeszukaniu głębin Jeziora Elune\'ara w celu odnalezienia świątynnej ozdoby. Niszczeje ona gwałtownie, więc zanieś ją prędko do Sanktuarium Remulosa. Użyj tam ozdoby, następnie porozmawiaj z Tajarri. To jedna z najbardziej doświadczonych i zaufanych wartowniczek Moonglade.$B$BMasz ograniczoną ilość czasu, by zakończyć zadanie i musisz liczyć się z tym, że możesz po drodze spotkać innych druidów, szukających tego samego co ty. Duchowa i fizyczna sprawność będą istotne, by osiągnąć sukces.$B$BPowodzenia, $N.",
    ["O"] = "Odnajdź Shrine Bauble w Jeziorze Elune\'ara i zanieś je do Shrine of Remulos w północno-zachodnim Moonglade. Bedąc tam, użyj znaleziska.$B$BNastępnie musisz porozmawiać z obecną w saktuarium Tajarri, by zakończyć próbę.",
    ["T"] = "Próba Jeziora",
  },
  [29] = {
    ["D"] = "W twojej pierwszej próbie, przeszukaj głębiny jeziora Lake Elune\'ara, aby znaleźć świątynną bańkę. Rozkłada się ona dość szybko, więc gdy już ją znajdziesz - jak najszybciej udaj się z nim do Świątyni Remulosa. Użyj tej bańki w sanktuarium, a następnie porozmawiaj z Tajarri, jest ona jedną z najbardziej zaufanych strażników Moonglade.$B$BMasz niewiele czasu, aby zakończyć zadanie, możesz też natknąć się na konkurentów - innych druidów również szukających tej bańki. Psychiczna i fizyczna sprawność będzie kluczem do osiągnięcia sukcesu.$B$BPowodzenia, $N!",
    ["O"] = "Znajdź Shrine Bauble w Lake Elune\'ara oraz przynieś go do Shrine of Remulos znajdującego się w północno-zachodniej części Moonglade. Gdy już tam będziesz, użyj Shrine Bauble.$B$BMusisz porozmawiać w sanktuarium z Tajarri, aby zakończyć próbę.",
    ["T"] = "Próba Jeziora",
  },
  [30] = {
    ["D"] = "Do drugiej próby będą ci potrzebne dwie połówki, które razem stworzą Medalion Morskiego Lwa. Jedna z nich czerpie moc ze zręczności tego aspektu, pozwalając przecinać morskie fale. Druga siłę swą wywodzi z jego niezwykłej wytrzymałości. Druidzi czerpią po równo z obu tych cech, by przybrać swą morską postać.$B$BPorozmawiaj z mieszkańcami Moonglade, by dowiedzieć się, gdzie poszukiwać zagubionych części. Zdobądź je i połącz je w tym miejscu. Gdy to uczynisz, zanieś medalion Dendrite\'owi Starblaze\'owi.",
    ["O"] = "Znajdź dwie połówki medalionu: Wodnej Zręczności i Wodnej Wytrzymałości. Porozmawiaj z mieszkańcami Moonglade by dowiedzieć się, gdzie te przedmioty mogą się znajdować.$B$BZe znalezionych połówek złóż Medalion Morskiego Lwa. Musisz być blisko Sanktuarium Remulosa, by móc tego dokonać.$B$BDostarcz kompletny medalion Dedrite\'owi Starblaze\'owi z wioski Nighthaven w Moonglade.",
    ["T"] = "Próba Morskiego Lwa",
  },
  [31] = {
    ["D"] = "$gUkończyłeś:Ukończyłaś; lekcję, przygotowującą do przybrania wodnej formy, niezbędną każdemu młodemu druidowi. Ruszaj teraz do swojego trenera, Turaka Runetotema w Thunder Bluff. Pokaż mu Medalion Morskiego Lwa na dowód twojej gotowości do nauki. Zakończy twe szkolenie, umożliwiając ci zdobycie jedności z wodą.$B$BDo zobaczenia, $gmłody druidzie:młoda druidko;. Jeszcze się spotkamy.",
    ["O"] = "Wróć do Thunder Bluff i pokaż Turakowi Runetotemowi Medalion Morskiego Lwa.",
    ["T"] = "Forma wodna",
  },
  [32] = {
    ["D"] = "Oto twój raport. Nalegam byś zabrał go do kogoś dysponującego odpowiednią wiedzą na ten temat.$B$BZnam uczonego trolla o imieniu Zilzibin Drumlore. Spędził on mnóstwo czasu badając formy życia nietypowe dla ekologii Azeroth; ponadto jest historykiem! Jeśli chcesz znaleźć kogoś, kto pomoże ci zrozumieć to zagrożenie i wymyślić, jak je powstrzymać, zanieś raport właśnie jemu. Będziemy potrzebować każdej pomocy, jakiej uda nam się uzyskać.$B$BZil mieszka w domu na drugim poziomie Drag in Orgrimmar.",
    ["O"] = "Zanieś raport do Zilzibina Drumlore\'a z Orgrimmaru.",
    ["T"] = "Odrodzenie silithidów",
  },
  [33] = {
    ["D"] = "Nienawidzę tych paskudnych szarych wilków! Za to z pewnością lubię wilcze steki... Przynieś mi twarde wilcze mięso, a wymienię je na coś, co się ci przyda.$B$BTwarde wilcze mięso łatwo jest zdobyć podczas polowania na szare wilki i młode szare wilki błąkające się wokół Northshire.",
    ["O"] = "Przynieś 8 Diseased Wolf Pelts do Eagana Peltskinner na zewnątrz Northshire Abbey.",
    ["T"] = "Wilki przechodzące granicę",
  },
  [34] = {
    ["D"] = "Kolejny raz mój ogród został zdeptany i ograbiony. I wiem, co za bydlę to robi. To ten samotny dzik, którego komendant Marris nazwał Bellygrub.$B$BNie będę mogła posadzić nowych narcyzów przed następnym sezonem. Zrujnowane! Wszystko zrujnowane przez jednego nieszczęsnego dzika. Zabij tego szkodnika! Pokaż mi jego kieł, a chętnie cię wynagrodzę. Zdaje się, że spędza czas, żerując na polach na południowy zachód stąd, ale od czasu do czasu zagląda też do mojego ogródka.",
    ["O"] = "Martie Jainrose z Lakeshire chce, byś $gzabił:zabiła; Bellygrub. Na dowód przynieś jej jego kieł.",
    ["T"] = "Nieproszony gość",
  },
  [35] = {
    ["D"] = "Jeśli chcesz sprawdzić, czy plotki o murlokach są prawdziwe, udaj się do mostu we wschodnim Elwynn i porozmawiaj ze strażnikiem Thomasem. Stacjonuje on przy moście od zeszłego tygodnia i będzie wiedział, co dzieje się w okolicy.$B$BPrzynieś mi jego raport.",
    ["O"] = "Marszałek Dughan chce, byś $gporozmawiał:porozmawiała; ze strażnikiem Thomasem.",
    ["T"] = "Dalsze problemy",
  },
  [36] = {
    ["D"] = "Nigdy nie myślałam, że nadejdzie dzień, gdy opuszczę farmę. Ale pola opanowali złodzieje i jest tu dla nas zbyt niebezpiecznie. Gdy tylko farmer Furlbrow naprawi wóz, ruszymy w drogę.$B$BMoże $gwyświadczyłbyś:wyświadczyłabyś; mi przysługę? Pozwól, że spiszę mój przepis na Westfalską Potrawkę. Proszę, zabierz go do Salmy Saldean, na jej farmę. Leży ona tuż za rozwidleniem dróg.",
    ["O"] = "Verna Furlbrow chce, byś $gdostarczył:dostarczyła; Salmie Saldean jej przepis na Westfallską Potrawkę.",
    ["T"] = "Westfallska potrawka",
  },
  [37] = {
    ["D"] = "Kilka dni temu wysłaliśmy dwóch strażników, Rolfa i Malakaiego, by zbadali teren przy rzece. Nadal nie wrócili. By ukończyć mój raport, muszę wiedzieć, co się z nimi stało.$B$BUdaj się na północ, wzdłuż rzeki i znajdź strażników... lub to, co po nich zostało.",
    ["O"] = "Strażnik Thomas chce, byś $gwyruszył:wyruszyła; wzdłuż rzeki na północ i $gposzukał:poszukała; dwóch zaginionych strażników, Rolfa i Malakaiego.",
    ["T"] = "Znajdź zaginionych strażników",
  },
  [38] = {
    ["D"] = "Pomóż zrobić mi trochę Westfallskiej Potrawki! Wróć z następującymi składnikami:$B$B3 kawałkami żylastego mięsa Sępa$B3 ryjami krwistokłów$B3 oczyma murloków$B3 owocami okry",
    ["O"] = "Salma Saldean chce 3 kawałków Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes, 3 owoce Okry.",
    ["T"] = "Westfallska potrawka",
  },
  [39] = {
    ["D"] = "Powiedz komendantowi Dughanowi o śmierci Malakaiego i Rolfa i zgłoś mu, że siły obecnie stacjonujące we wschodnim Elwynn nie są w stanie poradzić sobie z murlokami.$B$BWiem, że nie mamy wielu wolnych oddziałów, ale miejmy nadzieję, że Dughan kogoś znajdzie.",
    ["O"] = "Zgłoś się do komendanta Dughana w Goldshire.",
    ["T"] = "Dostarcz raport Thomasa",
  },
  [40] = {
    ["D"] = "$N, w Elwynn pojawiło się nowe zagrożenie! Murloki napływają strumieniami wschodniego Elwynn, odstraszając ryby i atakując niewinny lud!$B$BOstrzegałem komendanta Dughana, ale bardziej martwi się gnollami i bandytami. Nie jest przekonany, że murloki są niebezpieczne.$B$BProszę, porozmawiaj z Dughanem i nakłoń go do wysłania większych oddziałów na wschód!",
    ["O"] = "Remy <Two Times> chce, byś $gporozmawiał:porozmawiała; z komendantem Dughanem w Goldshire.",
    ["T"] = "Rybie zagrożenie",
  },
  [45] = {
    ["D"] = "Po dokładniejszym zbadaniu terenu znajdujesz ślady płetw prowadzące na wschód wzdłuż wybrzeża jeziora Stone Cairn. W oddali, na wschodzie, z ledwością dostrzegasz wioskę murloków.$B$BByć może przeznaczenie spotkało Rolfa właśnie tam...",
    ["O"] = "Poszukaj Rolfa lub znaku jego śmierci w wiosce murloków.",
    ["T"] = "Odkryj los Rolfa",
  },
  [46] = {
    ["D"] = "Armia Stormwind wyznaczyła nagrodę za przyczajców i szperaczy murloków z Elwynn. Zabij je i przynieś mi ich zdarte łuski, a armia Stormwind dobrze cię wynagrodzi.$B$BMurloki zbudowały wioskę na północ stąd, nad jeziorem Stone Cairn, i następną na południu, gdzie rozwidla się strumień.",
    ["O"] = "Przynieś strażnikowi Thomasowi na moście we wschodnim Elwynn 8 Torn Murloc Fins.",
    ["T"] = "Nagroda za murloki",
  },
  [47] = {
    ["D"] = "Koboldy z tych terenów czasem noszą przy sobie Złoty Proszek. Znalazłbym dla niego zastosowanie - przynieś mi jego ładunek, a dam ci zań najlepszą cenę w mieście... najlepszą cenę w mieście!$B$BKoboldy możesz znaleźć w kopalni Fargodeep na południu, i wokół kopalni Jasperlode na północnym wschodzie.",
    ["O"] = "Przynieś 10 porcji Gold Dust to Remy \"Two Times\" z Goldshire. Gold Dust posiadają koboldy z Elwynn Forest.",
    ["T"] = "Wymiana złotego proszku",
  },
  [48] = {
    ["D"] = "Na południe stąd, gdzie wiją i pełzają pnącza$BW ukrytej studni, płynie głęboko wiosenna woda$BBłyszcząc w ciemności żywym złotem$BPrzynieś mi ze źródła świętego wodę.",
    ["O"] = "Przynieś Holy Spring Water do Grimbooze\'a Thunderbrew.",
    ["T"] = "Słodki bursztyn",
  },
  [49] = {
    ["D"] = "Bursztyn jest moją ulubioną barwą$BPodobnie jak zmierzch słońca na niebie$BOdzyskaj go dla mnie, a moja miłość sie odrodzi$BPo jednym worku:",
    ["O"] = "Grimbooze Thunderbrew chce, abyś $gprzyniósł:przyniosła; mu Sack of Barley, Sack of Rye oraz Sack of Corn.",
    ["T"] = "Sweet Amber",
  },
  [50] = {
    ["D"] = "Będę próbował i próbował dopóki nie otrzymam tego$Bto będzie nasza prywatna skrytka$BMusi być zrobiona z silnego metalu$BPrzynieś mi trochę srebrytu, żebym mógł zakończyć piosenkę.",
    ["O"] = "Grimbooze Thunderbrew potrzebuje Truesilver.",
    ["T"] = "Słodki nektar",
  },
  [51] = {
    ["D"] = "Jeszcze nie filtrowana, ale świeżo destylowana.$BJak świeża ziemia czekająca na uprawę.$BDostarcz Sycamore Branch, to będzie twój następny cel.",
    ["O"] = "Zanieś Sycamore Branch do Grimbooze Thunderbrew",
    ["T"] = "Słodki nektar",
  },
  [52] = {
    ["D"] = "Witaj, $N. Im bardziej oddalamy się od Goldshire, tym bardziej agresywne robią się dzikie zwierzęta, a Tartak Eastvale cierpi z powodu nieustannych ataków wilków i niedźwiedzi!$B$BChcielibyśmy skorzystać z twojej pomocy.",
    ["O"] = "Zabij 8 Prowlers i 5 Young Forest Bears, następnie wróć do strażnika Thomasa przy wschodnim moście Elwynn.",
    ["T"] = "Ochrona granicy",
  },
  [53] = {
    ["D"] = "Ciecz jasna jak łzy dziecka$BZmienia piękny bursztyn od lat$BAle zanim przejdziemy dalej,$B$BBeczka ze zwęglonego drewna musi być zbudowana.",
    ["O"] = "Przynieś dla Grimbooze Thunderbrew snop Charred Oak.",
    ["T"] = "Sweet Amber",
  },
  [54] = {
    ["D"] = "$N, jesteś $C, $gktóry dowiódł:która dowiodła; swego zainteresowania obroną Northshire. Obarczam cię teraz zadaniem obrony otaczającej nas Puszczy Elwynn.$B$BJeśli akceptujesz ten obowiązek, mam przygotowane dokumenty, które należy dostarczyć do komendanta Dughana w Goldshire. Miasto leży za bramą graniczną, na końcu prowadzącej na południe drogi.",
    ["O"] = "Zanieś dokumenty marszałka McBride\'a do komendanta Dughana w Goldshire.",
    ["T"] = "Raport do Goldshire",
  },
  [55] = {
    ["D"] = "Morbent Fel przebywa w swojej kryjówce, w domu usytuowanym na wzgórzu na wschód stąd, górującym nad Cmentarzem na Raven Hill. Jego czas na tej ziemi dobiega końca...$B$BUżyj przeciw niemu Morbent\'s Bane. Uczyni jego obronną magię bezużyteczną.$B$BZabij go. Zabij go i ocal nas przed jego szaleństwem. Stań się narzędziem mojej zemsty i bohaterem Duskwood!",
    ["O"] = "Użyj Morbent\'s Bane do zabicia go, następnie wróć do Svena, do jego obozu.",
    ["T"] = "Morbent Fel",
  },
  [56] = {
    ["D"] = "Jako Dowódca Nocnej Straży poprzysięgłam chronić mieszkańców Darkshire. Stormwind odwołało swoich strażników z tutejszych posterunków, pozostawiając nas na pastwę losu.$B$BJeśli czujesz się na siłach, prosimy cię o pomoc! Pomóż Nocnej Straży, wyprawiając się do Tranquil Gardens, na południe od Darkshire, i zabijając 8 Szkieletów Wojowników i 6 Szkieletów Magów. Zagrożenie ze strony nieumarłych musi zostać zażegnane!",
    ["O"] = "Dowódca Althea Ebonlocke z Darkshire chce, byś zabił 8 Skeletal Warriors i 6 Skeletal Mages.",
    ["T"] = "Nocna Straż",
  },
  [57] = {
    ["D"] = "$N, dostaję raporty o inwazji nieumarłych na las! Jeśli jesteś gotowy, udaj się na cmentarz na Raven Hill i zabij 15 Szkieletów Horrorów i 15 Szkieletów Potworów. Mam też wieści o szkieletach na południe od Darkshire, nieopodal Tranquil Gardens Cemetery. Nieumarli muszą zostać wyplenieni z Duskwood!",
    ["O"] = "Dowódca Althea Ebonlocke z Darkshire chce, byś zabił 15 Skeletal Fiends i 15 Skeletal Horrors.",
    ["T"] = "Nocna Straż",
  },
  [58] = {
    ["D"] = "Raven Hill ciągle tonie w mrokach Plagi. Bezpieczeństwo Darkshire jest w twoich rękach, $N. Nie mam dość strażników, by zapewnić miastu ochronę. Chcielibyśmy, byś ponownie udał się do Raven Hill i oczyścił wschodnie mauzoleum z 20 Nosicieli Plagi!",
    ["O"] = "Dowódca Althea Ebonlocke z Darkshire chce, byś zabił 20 Plague Spreaders ze wschodniego mauzoleum Raven Hill.",
    ["T"] = "Nocna Straż",
  },
  [59] = {
    ["D"] = "Za twą bystrość i męstwo ofiarowuję ci znacznik odpowiadający jednej części zbroi. Chciałbym, byś $gzabrał:zabrała; go do Sary Timberlain z Tartaku Eastvale. Daj go jej, a ona zaprojektuje dla ciebie zbroję. A kiedy ją dostaniesz, $N, użyj jej do obrony Elwynn.$B$BTartak Eastvale znajduje się na wschodzie, za posterunkiem strażnika Thomasa.",
    ["O"] = "Daj Sarze Timberlain Stormwind Armor Marker.",
    ["T"] = "Zbroja skórzana i płócienna",
  },
  [60] = {
    ["D"] = "Witaj, $gmój Panie:moja Pani;! Masz odrobinę czasu?$B$BMój brat i ja prowadzimy aptekę w Stormwind; przybyłem tu, by zebrać kilka świec, gdyż potrzebny mi ich wosk. Czy $gmógłbyś:mogłabyś; mi pomóc?$B$BŚwiece możesz pozyskać od koboldów. Słyszałem pogłoski, że dużo się ich kręci w kopalniach na terenie Puszczy Elwynn... kopalni Fargodeep na południu i kopalni Jasperlode na wschodzie. Sugerowałbym poszukać świec w jednym z tych właśnie miejsc.",
    ["O"] = "Przynieś 8 Large Candles Williamowi Pestle\'owi z Goldshire.",
    ["T"] = "Świece koboldów",
  },
  [61] = {
    ["D"] = "Mój brat Morgan czeka w Stormwind na przesyłkę świec. Nie mam dość czasu, by osobiście wybrać się do niego, ale jeśli $gzechciałbyś:zechciałabyś; dostarczyć mu ten pakunek, sowicie cię wynagrodzi.$B$BZapakowałem już świece; Morgana znajdziesz w naszym sklepie - Aptece Pestla, w Dzielnicy Handlowej miasta Stormwind.",
    ["O"] = "Dostarcz William\'s Shipment do Morgana Pestle\'a w Trade District, Stormwind.",
    ["T"] = "Przesyłka do Stormwind",
  },
  [62] = {
    ["D"] = "Kopalnia w Northshire nie jest jedyną mającą problemy! Otrzymałem informację, że również kopalnia Fargodeep w Elwynn została zajęta przez koboldy.$B$BPrzeszukaj ją i sprawdź te doniesienia; potem wróć do mnie. Kopalnia znajduje się na południe od Goldshire, pomiędzy gospodarstwami Stonefield\'ów i Maclure\'ów.",
    ["O"] = "Zbadaj kopalnię Fargodeep, następnie wróć do marszałka Dughana w Goldshire.",
    ["T"] = "Kopalnia Fargodeep",
  },
  [63] = {
    ["D"] = "Na wybrzeżu lasu Silverpine, na zachód od Sepulcher, znajdziesz sanktuarium, które skaziła plaga. Tamtejsze duchy nie rozmawiają już z naszym ludem. Powierzam ci zadanie pokonania uosobienia skażenia i oczyszczenia tego miejsca.$B$BWeź bransolety żywiołaka i wraz z ostatnimi kroplami mikstury Brine złóż je na kaganku. Rytuał powinien wystarczyć, aby przyzwać nieskażonego ducha i porozumieć się z nim.$B$BPrzynieś mi dowód wykonania zadania, a nagrodzę cię totemem.",
    ["O"] = "Pokonaj Corrupt Manifestation of Water i umieść jej Corrupted Manifestation\'s Bracers wraz z Remaining Drops of Purest Water w Brazier of Everfount w Silverpine Forest.",
    ["T"] = "Zew wody",
  },
  [64] = {
    ["D"] = "To było straszne! Verna obudziła mnie, gdy usłyszała zamieszanie na polu. Nasze zagony były pełne wandali. Opuściliśmy dom w pośpiechu i zapomniałem zapakować mój kieszonkowy zegarek. Ojciec Verny dał mi go w dniu naszego ślubu i na myśl, że trafił w ręce złodziei, jest mi po prostu niedobrze. Zegarek zostawiłem w szafie w moim domu. Wypatruj pola z dyniami na zachodzie - nie możesz go przegapić. Jeśli przyniesiesz mi zegarek, będę ci dozgonnie wdzięczny!",
    ["O"] = "Farmer Furlbrow chce, byś $godzyskał:odzyskała; jego kieszonkowy zegarek z szafy w jego domu na farmie dyń, na zachód stąd.",
    ["T"] = "Zapomniana pamiątka rodzinna",
  },
  [65] = {
    ["D"] = "Banda wyrzutków, odpowiedzialna za wypędzenie dobrych mieszkańców Westfall z ich ziem, zwie się Bractwem Defias. Chciałbym, byś $gdowiedział:dowiedziała; się więcej o tej gromadzie bandytów. Musimy dowiedzieć się, kto nimi dowodzi i gdzie mają kryjówkę. W karczmie w Lakeshire przebywa łotrzyk imieniem Wiley, który jest mi winien przysługę.$B$BUdaj się do Lakeshire w Redridge Mountains, na wschód od Elwynn, i dowiedz się, ile się da.",
    ["O"] = "Gryan Stoutmantle chce, byś $gporozmawiał:porozmawiała; z Wileyem w Lakeshire.",
    ["T"] = "Bractwo Defias",
  },
  [66] = {
    ["D"] = "Ostatniej nocy nawiedziła mnie niesamowita, przerażająca wizja. Poczułam, że moja prawnuczka, Alyssa, jest w wielkim niebezpieczeństwie. Postawiłam karty i <Śmierć> spojrzała na mnie z blatu stołu.$B$BKiedy wydobyłam się z długiego i ponurego transu, znałam już klucz do tej przerażającej zagadki. Objawiło mi się imię; imię Stalvan.$B$BZnajdź Pisarza w Ratuszu i sprawdź, czy można dowiedzieć się czegoś więcej na temat tej postaci. Lękam się o nas wszystkich.",
    ["O"] = "Poszukaj Clerka Daltry\'ego w Town Hall, Darkshire.",
    ["T"] = "Legenda Stalvana",
  },
  [67] = {
    ["D"] = "Stalvan, hm? Niech no sprawdzę miejski rejestr...$B$BStalvan... Stalvan... popatrzmy. A, tu jest! Mam zapis o panie Stalvanie Mistmantle\'u. Jego ostatni znany adres to Szkoła w Moonbrook. Ależ to nieaktualne!$B$BMogę prosić cię o przysługę, przyjacielu? Gdybyś wybierał się do Moonbrook, daj znać, jeśli dowiesz się czegoś nowego na temat tego człowieka. Lubię mieć porządek w zapisach.",
    ["O"] = "Udaj się do Moonbrook Schoolhouse, zdobądź nowe informacje o Stalvanie i dostarcz je do Clerk Daltry.",
    ["T"] = "Legenda Stalvana",
  },
  [68] = {
    ["D"] = "W starej skrzyni znajdujesz Zakurzony Niewysłany List.",
    ["O"] = "Dostarcz Dusty Unsent Letter do Clerk Daltry.",
    ["T"] = "Legenda Stalvana",
  },
  [69] = {
    ["D"] = "O kurczę! Musiałem to przeoczyć za pierwszym razem. W rejestrze, zaraz poniżej pierwszego adresu Stalvana, widnieje kolejny, częściowo wymazany. Wygląda na to, że skierował się do The Lion\'s Pride Inn w Goldshire. Może powinieneś tam sprawdzić, $N.",
    ["O"] = "Udaj się do The Lion\'s Pride Inn w poszukiwaniu kogoś, kto słyszałby imię Stalvan.",
    ["T"] = "Legenda Stalvana",
  },
  [70] = {
    ["D"] = "Stalvan... coś mi świta. Aaa, teraz pamiętam.$B$BWiele lat temu, podczas wielkiej burzy, przybył posłaniec, szukając schronienia na noc. Około północy mężczyzna ten zbiegł po schodach, niesamowicie krzycząc, z twarzą bladą ze strachu. Wciąż odziany w strój do spania zniknął w mrokach ulewy.$B$BW tym pośpiechu zostawił swoje listy w skrzyni na górze. Nigdy po nie nie wrócił. Jeden pochodził od tego Stalvana, zaadresowano go do Dzielnicy Kanałów w Stormwind. Może Ci to w czymś pomoże.",
    ["O"] = "Zabierz Stalvan\'s Undelivered Letter ze skrzyni i zanieś go do Canal District w Stormwind.",
    ["T"] = "Legenda Stalvana",
  },
  [71] = {
    ["D"] = "Teraz, gdy masz już oba medaliony, zanieś je strażnikowi Thomasowi na moście, by poznał los zamordowanych strażników.",
    ["O"] = "Dostarcz medaliony Rolfa i Malakaia strażnikowi Thomasowi nieopodal wschodniego mostu w Elwynn.",
    ["T"] = "Raport dla Thomasa",
  },
  [72] = {
    ["D"] = "Mój ojciec był opiekunem majątku na długo, nim ja nim zostałem. To on musiał zmywać krew po masakrze. Ale to już nie ma znaczenia.$B$BSkończyły się ostatnie środki z funduszu Flintridge. Reszta rodzinnego dobytku trafi teraz na aukcję. Przeklęte sępy od podatków. Sądzę, że jeśli korci cię dowiedzieć się więcej, możesz przepatrzeć te śmieci. Kto wie, co tam znajdziesz.",
    ["O"] = "Przeszukaj spakowany dobytek w celu znalezienia wskazówek.",
    ["T"] = "Legenda Stalvana",
  },
  [73] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<TXT> No Reward",
  },
  [74] = {
    ["D"] = "W skrzyni znajdujesz różne przedmioty: poniszczone pamiątki, portret rodzinny, kilka trofeów myśliwskich i trochę starych ksiąg. Na dnie, pod porcelanową wazą, natrafiasz na Podartą Stronę z Dziennika.",
    ["O"] = "Znaleziona Podarta Strona z Dziennika zawiera kolejny trop.",
    ["T"] = "Legenda Stalvana",
  },
  [75] = {
    ["D"] = "Kiedy się tu wprowadziłem, w skrzyni na górze leżał plik papierów. Przeglądałem je, gdy przybyłem tu pierwszy raz, ale dałem spokój, gdy mgła przesłoniła me oczy.$B$BZrób staremu, niemalże ślepemu mężczyźnie przysługę i zajrzyj do skrzyni na piętrze w poszukiwaniu czegokolwiek, co mogłoby pomóc w twej misji dowiedzenia się czegoś więcej o postaci Stalvana. Jestem całkiem przekonany, że leży tam wyblakła strona z dziennika, który może cię zainteresować. Przynieś mi ją, a pomogę ci, jak tylko będę umiał.",
    ["O"] = "Marshal Haggard chce, byś sprawdził skrzynię na górze w poszukiwaniu Faded Journal Page.",
    ["T"] = "Legenda Stalvana",
  },
  [76] = {
    ["D"] = "Dzięki tobie wiemy, że kopalnia Fargodeep jest opanowana przez koboldy. Teraz musimy zbadać bardziej odległą kopalnią Jasperlode.$B$BPrzeszukaj ją i potwierdź ewentualną obecność koboldów. By dojść do kopalni, idź drogą na wschód póki nie znajdziesz się przy Wieży Azora. Stamtąd udaj się prosto na północ, a znajdziesz kopalnię u podnóża gór.",
    ["O"] = "Przeszukaj kopalnię Jasperlode, potem wróć z raportem do marszałka Dughana w Goldshire.",
    ["T"] = "Kopalnia Jaspisu",
  },
  [77] = {
    ["D"] = "Posiadam oryginalne materiały do zapakowania jabłecznika, którego szuka Dran Droffers. Pomogę ci w przygotowaniu pakunku dla irytującego ojca Maltona... w zamian za dwie dodatkowe butelki rzeczonego jabłecznika. Znajdują się one w skrzyniach w opuszczonej bazie Hordy w Skulk Rock.$B$BTo będzie ciężkie zadanie; obrzydliwe śluzaki i szlamy oblepiają tamtejsze ruiny; plotka głosi, że dowodzi nimi jakiś naczelny szlam. Nieważne, zdobądź jabłecznik i wróć do mnie, by go spakować.",
    ["O"] = "Odzyskaj 10 butelek Hinterlands Honey Ripple ze skrzynek położonych wokół porzuconej bazy Hordy w Skulk Rock.",
    ["T"] = "Lepka sytuacja",
  },
  [78] = {
    ["D"] = "Znam kogoś, kto mógłby ci pomóc. Gdy przewodziłem Strażnikom Stormwind, często popijaliśmy w Scarlet Raven Tavern w Darkshire. Tamtejszy właściciel karczmy, Smitts, był niemalże ekspertem w lokalnych sprawach. Pokaż mu tę stronę i zobacz, co o niej powie.",
    ["O"] = "Weź Faded Journal Page do Tavernkeep Smittsa.",
    ["T"] = "Legenda Stalvana",
  },
  [79] = {
    ["D"] = "Latami śledziłem legendę Stalvana. Gdy ci przejezdni szlachcice zostali kilka lat wcześniej zamordowani, razem z Haggardem postanowiliśmy to zbadać. Znalazłem te zabłocone kartki, ale nigdy nie udało nam się powiązać charakteru pisma z tym wariatem z lasu. Twój ciąg dowodów potwierdza jego winę. Natychmiast zabierz to do Commander Ebonlocke i powiadom ją o tym, co odkryłaś!",
    ["O"] = "Weź zabłoconą kartkę do Commander Ebonlocke.",
    ["T"] = "Legenda Stalvana",
  },
  [80] = {
    ["D"] = "Od pewnego czasu mam oko na tego dziwaka, Stalvana. Ale jeśli tą stronę zapisała ta sama ręka, dowiedzie to jego winy bez cienia wątpliwości.$B$BTe wszystkie dni prowadzenia Rejestru Miejskiego uczyniły z Clerka Daltry\'ego eksperta w identyfikowaniu ręcznego pisma. Pokaż mu tę stronę i sprawdź, czy jest ono zgodne z podpisem w rejestrze.",
    ["O"] = "Pokaż Clerkowi Daltry\'emu Bloodstained Journal Page.",
    ["T"] = "Legenda Stalvana",
  },
  [81] = {
    ["D"] = "Poczyniłem dodatkowe kroki w celu zabezpieczenia nie tylko zapakowanego do beczki jabłecznika Drana, ale również kilku dodatkowych butelek, których zażądał. Mogę nie cenić zbytnio Drana, ale nie ma nic gorszego niż wstrząśnięty jabłecznik. Proszę bardzo.$B$BTeraz, dostarcz beczkę do Drana Droffersa do jego uratowanego sklepiku w Orgrimmarze. Przekaż proszę moje najgorętsze pozdrowienia Maltonowi; powiedz mu, że gdy tylko będzie spragniony niezłego alkoholu i najlepszych do niego kompanów, będziemy zaszczyceni, jeśli nas odwiedzi.",
    ["O"] = "Dostarcz beczkę do Drana Droffersa z Orgrimmaru.",
    ["T"] = "Dostarczenie jabłecznika",
  },
  [82] = {
    ["D"] = "A teraz, co do tych raportów o robalach... Wiemy, że osuszają źródła wody, niegdyś znajdujące się na terenie obecnego Noxious Lair. A czego NIE wiemy, cóż, nie wiemy nic innego.$B$BNajpierw dowiedzmy się, kim jest nasz przeciwnik! Chciałbym byś udał się do Noxious Lair i zdobył nieco części tych stworzeń. Zdobądź pięć części Centipaar i zanieś je Alchemikowi Pestlezuggowi do zbadania. Dzięki niemu dowiemy się, z czym mamy do czynienia!",
    ["O"] = "Przynieś pięć części insektów Centipaar z Noxious Lair do Alchemika Pestlezugga z Gadgetzanu.",
    ["T"] = "Śledztwo w sprawie Trującego Leża",
  },
  [83] = {
    ["D"] = "Banda Defiasów z Northshire nosi grube maski, ale Defiasi z Elwynn noszą płócienne, których mogę użyć do zrobienia wspaniałych przedmiotów z płótna.$B$BPrzynieś mi czerwone płócienne bandany a coś ci z nich uszyję.$B$BObozy członków gangu Defias rozsiane są po całym Elwynn.",
    ["O"] = "Przynieś 6 Red Linen Bandanas Sarze Timberlain z Eastvale Logging Camp.",
    ["T"] = "Dobra z czerwonego płótna",
  },
  [84] = {
    ["D"] = "Proszę. A gdy dasz pasztet temu Billy\'emu, powiedz mu, że mam nadzieję, że się nim udławi!",
    ["O"] = "Przynieś pasztet do Billy\'ego Maclure z winiarni Maclure\'ów.",
    ["T"] = "Wróć do Billy\'ego",
  },
  [85] = {
    ["D"] = "Zgubiłam mój naszyjnik; myślę, że wziął go ten obrzydliwy Billy Maclure! Zwykle pomyka niczym szczur wokół winnicy Maclure\'ów na wschód stąd.$B$BOdzyskaj mój naszyjnik, a ogrzejesz serce starej wdowy.",
    ["O"] = "Porozmawiaj z Billy\'m Maclure.",
    ["T"] = "Zgubiony naszyjnik",
  },
  [86] = {
    ["D"] = "Może gdybym dostał pasztet, mógłbym powiedzieć, kto ma ten naszyjnik. Wiesz, ta stara pani Bernice z tamtej drugiej farmy robi wspaniały wieprzowy pasztet... $B$BMoże gdybyś $gdał:dała; jej kilka kawałów mięsa z dzików, które błąkają się wokół naszych farm i $gpowiedział:powiedziała; jej o co chodzi, upiekłaby dla ciebie ten pasztet.",
    ["O"] = "Przynieś 4 Chunks of Boar Meat do cioteczki Bernice Stonefield z farmy Stonefield\'ów.",
    ["T"] = "Pasztet dla Billy\'ego",
  },
  [87] = {
    ["D"] = "Bawiłem się niedaleko kopalni Fargodeep i wydaje mi się, że upuściłem, eee... znaczy się, widziałem, naszyjnik starszej pani. Nie pytaj mnie jak on się tam znalazł... To nie ja!$B$BW każdym razie, widziałem dużego kobolda ze złotymi zębami, podnoszącego naszyjnik i wbiegającego do kopalni. Znajdź tego kobolda, a znajdziesz i naszyjnik, przysięgam!",
    ["O"] = "Zanieś naszyjnik cioteczce Bernice Stonefield z farmy Stonefield\'ów.",
    ["T"] = "Złotoząb",
  },
  [88] = {
    ["D"] = "Brackwell\'owie mają świnię-medalistkę, Księżniczkę. Ta maciora jest OGROMNA, a to dzięki temu, że podkrada się tutaj i zjada moje warzywka!$B$BWięc nim pojawi się na naszych polach... Księżniczka musi umrzeć! Przynieś mi jej obrożę na dowód ukończenia zadania, a dam ci coś w zamian!$B$BKsiężniczka kręci się zwykle w pobliżu grządek dyń Brackwell\'ów, na wschód, aż za farmą Maclure\'ów. Zabij ją, nim znów zgłodnieje i wróci tutaj!",
    ["O"] = "Zabij Princess, zabierz jej obrożę i zanieś ją do Ma Stonefield z farmy Stonefield\'ów.",
    ["T"] = "Księżniczka musi umrzeć!",
  },
  [89] = {
    ["D"] = "Podczas ostatniej inwazji orków musieliśmy przetopić nasze żelazo na pociski, miecze i pancerze. Wysłaliśmy do Stormwind prośbę o dostawę nowych materiałów, ale banda gnolli z Redridge porwała karawanę i uciekła w góry za Lakeshire.$B$BTeraz kończą się nam surowce do odbudowy mostu. Jeśli przyniesiesz mi 5 żelaznych pik i 5 żelaznych nitów, wynagrodzę cię. $B$BA teraz do roboty!",
    ["O"] = "Przynieś 5 Iron Pikes i 5 Iron Rivets do brygadzisty Oslowa z Lakeshire.",
    ["T"] = "Most nad Everstill",
  },
  [90] = {
    ["D"] = "Przyprawione kebaby z wilka są tutejszym przysmakiem! Oczywiście, mogę przyrządzić kilka dla ciebie. Ale najpierw potrzebuję składników. Przynieś mi 10 Płatów z Chudego Wilka oraz Przyprawę Ziołową ze Stormwind. W lesie jest tak dużo wilków, iż jestem pewien, że bez problemu zdobędziesz płaty. Jeśli chodzi o zioła, poszukaj Felicii Gump i jej kwiaciarni w dzielnicy kanałów w Stormwind.",
    ["O"] = "Zdobądź 10 Lean Wolf Flanks oraz Stormwind Seasoning Herbs; potem wróć do Chef Grual z Darkshire.",
    ["T"] = "Przyprawione kebaby z wilka",
  },
  [91] = {
    ["D"] = "Wróg Stormwind zamieszkał na wschodnim podgórzu Redridge. Ten nikczemny łotr przy pomocy magii sprowadza trwogę i niedolę na naszych ludzi i miasto. Swoje mroczne rzemiosło uprawia pod imieniem Morganth.$B$BMorganth sprawuje teraz kontrolę nad klanem cienistoskórych gnolli, które są na jego rozkazy. Jak głosi prawo Lakeshire, pomoc przestępcom karana jest śmiercią.$B$BTe ohydne gnolle muszą zginąć!$B$BPrzynieś mi dziesięć wisiorów gnolli, a zostaniesz $gwynagrodzony:wynagrodzona;.",
    ["O"] = "Przynieś 10 Shadowhide Pendants do namiestnika Conachera z Town Hall w Lakeshire.",
    ["T"] = "Solomonowe prawo",
  },
  [92] = {
    ["D"] = "Nic nie sprawiłoby mi większej przyjemności, niż przyrządzenie dla ciebie gulaszu z Redridge. Jest jednak pewien drobny problem. W czasie ostatniego powstania orków zapewniałam posiłki całej brygadzie żołnierzy Stormwind i moja spiżarnia została ogołocona. Jeśli jednak $gdostarczyłabyś:dostarczyłbyś; składniki, byłabym zobowiązana.$B$BWystarczy, że przyniesiesz mi pięć kawałków twardego mięsa kondora, pięć pysków wielkich krwistokłów oraz pięć porcji kruchego pajęczego mięsa.",
    ["O"] = "Kucharka Breanna z Lakeshire chce 5 Tough Condor Meat, 5 Great Goretusk Snouts oraz 5 porcji Crisp Spider Meat.",
    ["T"] = "Gulasz z Redridge",
  },
  [93] = {
    ["D"] = "Zdradzę ci mały sekret - ciemne ciastka <z kraba> tak naprawdę robione są z odnóży pająków! Wiem, że to trochę obrzydliwe, ale ciastka mają smaczny, pikantny smak i stanowią wspaniałą przekąskę! Przynieś mi Gooey Spider Legs, a będziesz miał okazję spróbować kilku z nich.$B$BPodobno Venom Web Spiders stanowią doskonałe źródło tego surowca - gnieżdżą się na północ stąd, pomiędzy pagórkami a rzeką.",
    ["O"] = "Znajdź 6 Gooey Spider Legs i zanieś je Szefowi Kuchni Grualowi przebywającemu w gospodzie w Darkshire.",
    ["T"] = "Ciemne ciastka z kraba",
  },
  [94] = {
    ["D"] = "Mój rywal, Morganth, to podstępny mag o wielkiej mocy zamieszkujący Wieżę Ilgalara w Redridge. Opracowałem sposób na szpiegowanie jego ruchów. Za pośrednictwem Oka Azory mogę obserwować go z daleka.$B$BLecz aby przeniknąć do jego myśli... potrzebuję dodatkowej pomocy.$B$BJeśli jesteś $gzainteresowany:zainteresowana;, zabierz Glif Azory do Wieży Ilgalara. Umieść go na posągu lwa niedaleko wieży.$B$BGdy to uczynisz, moc Azory da mi wgląd w plany Morgantha.",
    ["O"] = "Zanieś Glyph of Azora do Lion Statue nieopodal Tower of Ilgalar w Redridge.",
    ["T"] = "Czujne oko",
  },
  [95] = {
    ["D"] = "Pracowałem niegdyś na jednej z farm na południowym wschodzie... do dnia, w którym podczas mojej nieobecności Mroczni Jeźdźcy z Deadwind Pass złożyli na niej niespodziewaną wizytę i uśmiercili moją rodzinę!$B$BGdy wróciłem, dostrzegłem cienistą sylwetkę zakopującą coś po kryjomu przy mojej stodole. Jej właściciel uciekł, zanim zdążyłem go złapać, a nie mogłem tracić czasu na ściganie go, gdyż nie chciałem stracić tropu Mrocznych Jeźdźców. Nigdy więc nie dowiedziałem się, co tam ukryto.$B$BJeśli możesz sprawdzić, co ten ktoś zakopał, byłbym bardzo wdzięczny. To miejsce znajduje się za starym pniem obok mojej stodoły.",
    ["O"] = "Udaj się na Farmę Svena i przekonaj się, co zakopano za starym pniakiem.",
    ["T"] = "Zemsta Svena",
  },
  [96] = {
    ["D"] = "Weź kamień. Weź kamień i daj życie.$B$BDaj życie i zrozum. Zrozum, że woda jest życiem... trucizna niszczy życie.$B$BChroń i dawaj życie mocą wody.",
    ["O"] = "Zanieś Shard of Water do Islen Waterseer z Barrens.",
    ["T"] = "Zew wody",
  },
  [97] = {
    ["D"] = "$N, niezwłocznie zawiadom Dowódcę Ebonlocke, że charakter pisma się zgadza! Jej podejrzenia były uzasadnione!",
    ["O"] = "Dostarcz Dowódcy Ebonlocke najnowsze informacje.",
    ["T"] = "Legenda Stalvana",
  },
  [98] = {
    ["D"] = "Stalvan Mistmantle prowadził zdeprawowane życie. Niewinni ludzie zginęli z jego rąk. Niewątpliwie winien jest niezliczonych zbrodni. Ten obłąkaniec zagraża Darkshire. Światłość tylko wie, jak paskudne czyny nadal knuje. $C, udaj się do jego domu, stojącego na północ od miasta, i skończ ze Stalvanem raz na zawsze.$B$BGdy wykonasz zadanie, zanieś jego rodzinny pierścień do Madame Evy. W końcu to dzięki jej przeczuciom doszło do tego makabrycznego odkrycia. Dzięki niej Darkshire jest bezpieczniejszym miejscem.",
    ["O"] = "Zabij Stalvana Mistmantle\'a i zanieś Madame Evie jego rodzinny pierścień.",
    ["T"] = "Legenda Stalvana",
  },
  [99] = {
    ["D"] = "Wraz z zrozumieniem magii Arguala rośnie również moja pogarda dla tego nieszczęsnego głupca. Jestem blisko ukończenia swoich badań nad jego tak zwanym lekarstwem.$B$BBędę posiadał kompletną wiedzę, gdy już dowiem się jakie zaklęcie powoduje te dziwne zachowania w Wiosce Pyrewood. Za dnia, chłopi wydają się być ludźmi. Lecz gdy tylko zachodzi słońce mieszkańcy zamieniają się w worgenów.$B$BMuszę pobrać energię z zaklętych przez Arguala kajdan. Przynieś mi sześć ich sztuk.",
    ["O"] = "Dostarcz 6 Pyrewood Shackles do Dalara Dawnweavera znajdującego się w Sepulcher.",
    ["T"] = "Szaleństwo Arguala",
  },
  [100] = {
    ["D"] = "Gdy kończysz inkantację, następuje wybuch światła. Odgłos wpadających w płomień kropel wody zamiera, a ty $gsam:sama; zatracasz się, kiedy otaczające cię skażone duchy zostają zniszczone.",
    ["O"] = "Porozmawiaj z Minor Manifestation of Water w Silverpine Forest.",
    ["T"] = "Zew wody",
  },
  [101] = {
    ["D"] = "Kiedy mistyczna skaza rozpełza się po lesie, konieczność samoobrony stała się niezaprzeczalna, $N. Słyszę wiatry mówiące o wielkim niebezpieczeństwie, które czeka na ciebie w niedalekiej przyszłości.$B$BJeśli pragniesz ochrony, szlachetny $C, przynieś mi 10 kłów ghula, 10 palców szkieletu i 5 fiolek pajęczego jadu. Wówczas stworzę dla ciebie Totem of Infliction, który skrzywdzi każdego pragnącego twej śmierci.",
    ["O"] = "Zdobądź 10 Ghoul Fangs, 10 Skeleton Fingers i 5 Vials of Spider Venom dla Madame Evy z Darkshire.",
    ["T"] = "Totem Krzywdzenia",
  },
  [102] = {
    ["D"] = "Stormwind nas porzuciło. Plugawy wiatr nieprawości szeleści pośród pól Westfall. Ta kraina jest mą ojczyzną i nie odwrócę się od mieszkańców, którzy postanowili tu pozostać. My, dawni farmerzy, będziemy stać na straży naszych ziem.$B$BTwoim zadaniem, jeśli się zgodzisz, będzie patrolowanie terenów Westfall. Wytrop i pozabijaj wstrętne gnolle, które wydają się współpracować ze złodziejami z Deadmines. Przynieś mi osiem łap gnolli, a wynagrodzę cię za twą dzielność.",
    ["O"] = "Przynieś 8 Gnoll Paws do kapitana Danuvina w Sentinel Hill.",
    ["T"] = "Patrol w Westfall",
  },
  [103] = {
    ["D"] = "Noc, w której zginęła rodzina latarników, była najgorszą nocą mego życia. Bezsilny patrzyłem, jak Old Murk-Eye prowadzi atak. Jednak co się stało, to się nie odstanie i teraz kłopotam się o żywoty załóg statków żeglujących po wodach Wielkiego Morza, blisko niebezpiecznych skał. Od kiedy nie ma tu nikogo, kto mógłby doglądać ognia, cała odpowiedzialność spadła na moje barki.$B$BPomóż mi utrzymać palący się ogień, przynosząc 5 butelek oleju ze żniwiarzy.",
    ["O"] = "Dostarcz 5 Flasks of Oil kapitanowi Graysonowi czekającemu przy Westfall Lighthouse.",
    ["T"] = "Strażnik płomienia",
  },
  [104] = {
    ["D"] = "Kiedy moje życie zakończyło się na tutejszych skałach, nie miałem pojęcia, co czeka mnie w zaświatach. Tej nocy latarnia nie rozjaśniała mroku, ponieważ Old Murk-Eye przepłoszył rodzinę odpowiedzialną za podtrzymywanie ognia. Wprawdzie wrócili i ponownie rozpalili ogień, lecz Old Murk-Eye zmusił głupsze murloki do ponownego ataku na latarnię. Tym razem rodzina nie miała już tyle szczęścia; wszyscy zginęli na moich oczach.$B$BJeśli uda ci się spotkać na brzegu Old Murk-Eye, zabij go i przynieś do mnie jedną z jego łusek, a sowicie wynagrodzę twój trud.",
    ["O"] = "Zdobądź łuskę Old Murk-Eye dla kapitana Graysona czekającego przy Westfall Lighthouse.",
    ["T"] = "Nadbrzeżne zagrożenie",
  },
  [105] = {
    ["D"] = "Więc cóż, nadszedł czas, by zaatakować Andorhal i przepędzić władającego nim lisza!$B$BRuiny miasta to miejsce, z którego lisz – Araj the Summoner – sprawuje władzę. Strzegą go liczne oddziały Plagi, otaczające szczątki dawnego centrum, a jego osobista świta strażników budzi niesamowitą grozę. Będziesz potrzebował wielu sprzymierzeńców, by mieć choćby szansę spotkania się z nim twarzą w twarz.$B$B$N, zniszcz Araja i przynieś mi kryształ z jego filakterii jako dowód!",
    ["O"] = "Przynieś Araj\'s Phylactery Shard do High Executor Derrington z Bulwark, Western Plaguelands.",
    ["T"] = "Więc cóż, Andorhal",
  },
  [106] = {
    ["D"] = "Och, jestem przeklęta! Moje serce należy do Tommy\'ego Joe Stonefielda, lecz nasze rodziny są zagorzałymi wrogami. Nie mogę się z nim więc widywać, choć moje oczy pragną wpatrywać się w jego przystojną twarz!$B$BProszę, dostarcz ten list Tommy\'emu Joe. Zazwyczaj można go spotkać nad rzeką, na zachód od farmy Stonefield\'ów; dokładnie na zachód stąd.",
    ["O"] = "Przekaż list miłosny Maybell Tommy\'emu Joe Stonefield\'owi.",
    ["T"] = "Młodzi kochankowie",
  },
  [107] = {
    ["D"] = "Idę o zakład, że William Pestle posiada eliksir mogący połączyć naszych młodych kochanków!$B$BProszę, zanieś tą wiadomość Williamowi. Możesz znaleźć go w karczmie \"Duma Lwa\" w Goldshire.",
    ["O"] = "Zanieś list babci Stonefield do Williama Pestle.",
    ["T"] = "Wiadomość dla Williama",
  },
  [108] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<TXT> Mystery Reward",
  },
  [109] = {
    ["D"] = "Wygląda na to, że w swoim życiu $gbrałeś:brałaś; udział w wielu walkach, $C. Jeśli jeszcze tego nie $gzrobiłeś, powinieneś:zrobiłaś, powinnaś; niezwłocznie udać się do Gryana Stoutmantle\'a. Dowodzi on Strażą Obywatelską, której celem jest obrona ziem Westfall. Z pewnością skorzysta z twojej pomocy. Zwykle można go znaleźć w kamiennej wieży na Sentinel Hill, w samym środku Westfall.",
    ["O"] = "Porozmawiaj z Gryanem Stoutmantle\'em. Zwykle można go znaleźć w kamiennej wieży na Sentinel Hill, w samym środku Westfall.",
    ["T"] = "Zgłoś się do Gryana Stoutmantle\'a",
  },
  [110] = {
    ["D"] = "Zamierzam spędzić trochę czasu, badając sprzęt pomiarowy Scrimshanka... przeglądając przy okazji uzyskane przezeń wyniki. Coś mi mówi, że nie była to jedyna strata, jaką ponieśliśmy przez te owady.$B$BChciałbym, żebyś zobaczył się z Alchemikiem Pestlezuggiem i zapytał, czy udało mu się przeanalizować części owadów, które mu posłaliśmy. Jeśli są już wyniki, dostarcz mi je jak najszybciej.",
    ["O"] = "Zajrzyj do Alchemika Pestlezugga w Gadgetzanie w sprawie jego analizy fragmentów owadów.",
    ["T"] = "Analiza owadów",
  },
  [111] = {
    ["D"] = "Proszę, $N, porozmawiaj z moją babcią. Jeśli ktokolwiek potrafi znaleźć sposób na połączenie mnie z Maybell, to właśnie ona.$B$BPrzebywa w domu na wschód stąd.",
    ["O"] = "Porozmawiaj z babcią Stonefield.",
    ["T"] = "Porozmawiaj z babcią",
  },
  [112] = {
    ["D"] = "Mogę wykonać eliksir niewidzialności dla Maybell, by mogła wymknąć się z Winnicy Maclure\'ów i spotkać się z Tommy\'m Joe. Do sporządzenia go potrzebuję trochę kryształowych wodorostów.$B$BChoć wodorosty rosną zwykle w morzu... czasem zbierają je murloki. Sprawdź, czy murloki znad Jeziora Kryształowego mają jakieś ich liście. Jezioro znajduje się na wschód od Goldshire.",
    ["O"] = "Przynieś 4 Crystal Kelp Fronds do Williama Pestle z Goldshire.",
    ["T"] = "Zbieranie wodorostów",
  },
  [113] = {
    ["D"] = "Senior Surveyor Fizzledowser musi natychmiast zobaczyć ten raport. Właściwie... każdy, kto umie czytać, musi go zobaczyć. Stoimy w obliczu śmiertelnego zagrożenia nie tylko dla Tanaris i Gadgetzanu, ale, jeśli pozostawimy je samemu sobie, może i dla całego południowego Kalimdoru. Niech to szlag, możliwe, że dla całego Azeroth; nie wygląda na to, żeby sytuacja miała się uspokoić.$B$BNiech Fizzledowser zrobi dla ciebie duplikat tego raportu do twojego osobistego użytku. Wszyscy muszą wiedzieć o nadchodzącym niebezpieczeństwie!",
    ["O"] = "Dostarcz raport do Senior Surveyor Fizzledowser z Gadgetzanu. Dopilnuj, żeby dał ci jego kopię, o co prosił Alchemik Pestlezugg.",
    ["T"] = "Analiza owadów",
  },
  [114] = {
    ["D"] = "Zanieś Maybell eliksir niewidzialności. Powinien działać wystarczająco długo, by mogła spotkać się z Tommy\'m Joe.",
    ["O"] = "Zanieś Maybell Maclure eliksir niewidzialności.",
    ["T"] = "Ucieczka",
  },
  [115] = {
    ["D"] = "Orkowie z klanu Czarnej Skały zwerbowali magów cienia do pomocy w swych atakach w Redridge, a ci z kolei sprowadzili z sobą urządzenia mrocznej mocy - kule północy. Kule te zadają potężne ciosy obrońcom Redrige, koniecznym jest więc wyłączenie tych skażonych przez demony przedmiotów z konfliktu.$B$BZnajdź i dostarcz mi kule północy uśmierconych magów cienia Czarnej Skały. Zniszczę je, kiedy tylko trafią w moje ręce! Świat będzie bez nich lepszym miejscem.",
    ["O"] = "Przynieś 3 Midnight Orbs do komendanta Marrisa z Lakeshire.",
    ["T"] = "Magia cienia",
  },
  [116] = {
    ["D"] = "Znalazłem się w niezłych tarapatach, $N. Trunki powoli się kończą. Nowa dostawa alkoholu mocno się spóźnia. Inwazja orków była piekłem.$B$BMoże $gmógłbyś:mogłabyś; wyświadczyć mi małą przysługę?$B$BCzy zechcesz przynieść mi baryłkę Grzmotówki od Grimbooze\'a Thunderbrewa ze wzgórz Westfall, beczkę Merlota ze Stormwind, butelkę Księżycówki z Darkshire i bukłak słodkiego rumu z Goldshire? Dostarcz mi wszystkie te trunki, a zostaniesz sowicie $gwynagrodzony:wynagrodzona;.",
    ["O"] = "Barman Daniels z Lakeshire potrzebuje baryłki Thunderbrew Lager, beczki Merlota, butelki Moonshine i bukłaka Sweet Rum.",
    ["T"] = "Czas posuchy",
  },
  [117] = {
    ["D"] = "By piwo nasze nam smakowało,$BPędź po składniki, nie po kakao.",
    ["O"] = "Przynieś 5 szyszek chmielu Grimbooze\'owi Thunderbrewowi, by mógł dokończyć produkcję swego specjalnego piwa.",
    ["T"] = "Grzmocące Jasne",
  },
  [118] = {
    ["D"] = "Zużywam tak wiele żelaza na wyekwipowanie straży Stormwind, że nie starcza mi go na podkowy dla koni ze stajni!$B$BZanieś tę wiadomość kowalowi Argusowi z Goldshire. Przedstawi mu mój problem i prośbę o przesyłkę podków.",
    ["O"] = "Zanieś Verner\'s Note do kowala Argusa z Goldshire.",
    ["T"] = "Cena podków",
  },
  [119] = {
    ["D"] = "Niech będzie, dam mu te 50 podków...$B$BOto one, spakowane i gotowe do wysłania. Powiedz Vernerowi, że to przyjemność robić z nim interesy, i upewnij się, że przeczyta list dołączony do skrzynki.",
    ["O"] = "Wróć do Vernera Osgooda w Redridge. Oddaj mu skrzynię z podkowami.",
    ["T"] = "Wróć do Vernera",
  },
  [120] = {
    ["D"] = "To ciężkie czasy, $C. Miasto jest pod ciągłym oblężeniem. Bez uzupełnień poniesiemy klęskę. Wiadomość, którą ci powierzam, jest najwyższego znaczenia. Natychmiast dostarcz ten raport do generała Marcusa Jonathana ze Stormwind. Gdy tylko otrzymasz odpowiedź, wróć do mnie jak najprędzej, nie ważne, z jaką nowiną, dobrą czy złą.$B$BA teraz ruszaj!",
    ["O"] = "Sędzia Solomon dał ci raport, który musi zostać dostarczony do generała Marcusa Jonathana ze Stormwind. Sędzia chce, abyś $gpowrócił:powróciła; do niego, gdy tylko dostarczysz przesyłkę.",
    ["T"] = "Posłaniec do Stormwind",
  },
  [121] = {
    ["D"] = "Podczas gdy ja będę oczekiwał na odpowiedź od króla, chciałbym, abyś $gzaniósł:zaniosła; ten list do sędziego Salomona.$B$BOdmaszerować, $C!",
    ["O"] = "Zanieś odpowiedź generała Marcusa Jonathana do sędziego Solomona z Lakeshire.",
    ["T"] = "Posłaniec do Stormwind",
  },
  [122] = {
    ["D"] = "Potrzebuję kilku łusek z podbrzuszy piskląt czarnych smoków, aby zapłacić za te podkowy, które Argus przysłał mi z Goldshire. Jeżeli udałoby ci się zdobyć sześć, mógłbym spłacić Argusa i zostałoby mi jeszcze tyle, aby wykonać coś dla ciebie.$B$BPisklęta często widuje się latające na południe od Lakeshire, ale lubią się przemieszczać. Musisz mieć oczy cały czas otwarte i korzystać z każdej okazji, aby je upolować.",
    ["O"] = "Zdobądź 6 Underbelly Whelp Scales z Black Dragon Whelps i przynieś je do Vernera Osgooda z Redridge.",
    ["T"] = "Łuski z podbrzuszy",
  },
  [123] = {
    ["D"] = "Kartka zawiera wykaz dni i godzin, kiedy osoba - opisana jako \"poborca\" - otrzyma przesyłkę złota z kopalń w Puszczy Elwynn.$B$BZ wykazu można wywnioskować, że poborca przebywa gdzieś nieopodal pola dyń Brackwell\'ów we wschodnim Elwynn.$B$BTo wygląda na ważne. $gPowinieneś:Powinnaś; poinformować o tym marszałka Dughana z Goldshire.",
    ["O"] = "Udaj się do marszałka Dughana z Goldshire i oddaj mu listę \"poborcy\".",
    ["T"] = "Poborca",
  },
  [124] = {
    ["D"] = "Jakby ataki orków nie wystarczyły! Teraz mam jeszcze brutali i mistyków gnolli skradających się wzdłuż urwiska na północ od mojej stajni, kradnących moje konie, gdy zabłądzą...$B$BJeżeli pozbędziesz się tych gnolli, moje konie i ja będziemy ci bardzo wdzięczni.",
    ["O"] = "Zabij 10 Redridge Brutes i 8 Redridge Mystics, następnie wróć do Vernera Osgooda.",
    ["T"] = "Ujadanie gnolli",
  },
  [125] = {
    ["D"] = "Wiesz, $N, naprawdę $gmógłbyś:mogłabyś; mi pomóc. Przy całym tym oblężeniu trudno jest cokolwiek zdobyć. Moje narzędzia miały zostać dostarczone wozem z Goldshire, ale most się rozpadł. Zapakowaliśmy je do łódki, ale orkowie trafili ją z katapulty. Po prostu mam pecha; moje narzędzia zatonęły na samym środku jeziora.$B$BOdzyskaj moją skrzynkę z narzędziami, $N, a wynagrodzę ci stracony czas.",
    ["O"] = "Brygadzista Oslow z Lakeshire chce, abyś $godzyskał:odzyskała; jego skrzynkę z narzędziami z dna Jeziora Everstill.",
    ["T"] = "Zgubione narzędzia",
  },
  [126] = {
    ["D"] = "$N, gnolle wciąż tam są. Słyszę, jak ujadają podczas polowania na wzgórzach. A jeden głos wybija się ponad inne - to Yowler, ich przywódca.$B$BZabij go, a jego stado się rozpadnie! Przynieś mi jego łapę jako dowód.$B$BI bądź $gostrożny:ostrożna;, ten gnoll nie przewodzi swymi pobratymcami bez powodu. To nie jakiś kundel...",
    ["O"] = "Przynieś Yowler\'s Paw do Vernera Osgooda z Lakeshire.",
    ["T"] = "Wycie pośród wzgórz",
  },
  [127] = {
    ["D"] = "Jezioro Everstill słynie ze swych pstrych okoni. Zawsze jest na nie popyt... a ja mam ich za mało!$B$BPrzynieś mi 10 sztuk, a dobrze cię wynagrodzę. Jeżeli nie potrafisz złowić ich $gsam:sama;, to może murloki będą jakieś miały?",
    ["O"] = "Przynieś 10 Spotted Sunfish do dokmistrza Barena z Lakeshire.",
    ["T"] = "Sprzedaż ryb",
  },
  [128] = {
    ["D"] = "Klan Czarnej Skały musi zostać zniszczony! Wróg zaatakował nasze ziemie. Te góry są pod władaniem korony Stormwind! Nasze źródła mówią, że każdym oddziałem w obrębie klanu dowodzi jego czempion. Odnajdziesz ich w obozowisku na północy, na zachód od drogi na Burning Steppes.$B$BSędzia Solomon pragnie ujrzeć tych cuchnących brutali martwymi. Zabij piętnastu czempionów Czarnej Skały i wróć do mnie.",
    ["O"] = "Zabij 15 Blackrock Champions, a strażnik Howe z Lakeshire wręczy ci nagrodę.",
    ["T"] = "Polowanie na orków z Czarnej Skały",
  },
  [129] = {
    ["D"] = "Możesz coś dla mnie zrobić? Mam tu obiad dla strażnika Parkera, ale wysłano go na patrol... To duży, silny mężczyzna, który na pewno potrafi się obronić, ale dla takiego mieszczucha jak ja poza miastem jest stanowczo zbyt niebezpiecznie. Więc... jeśli $gmógłbyś:mogłabyś; zanieść mu ten obiad, przygotowałabym darmowy posiłek na twój powrót! Parker patroluje okolicę drogi prowadzącej do Duskwood.",
    ["O"] = "Przynieś strażnikowi Parkerowi jego obiad. Strażnik patroluje drogę prowadzącą do Darkshire.",
    ["T"] = "Darmowy posiłek",
  },
  [130] = {
    ["D"] = "Kiedy wrócisz do Darcy, $gmógłbyś:mogłabyś; jej przynieść kwiaty ode mnie? Na pewno dostaniesz je u zielarki w Lakeshire, na zachodnim końcu miasta.$B$BAle jak już pójdziesz po kwiaty... nie mów przypadkiem zielarce... Martie... od kogo są, ani dla kogo...",
    ["O"] = "Porozmawiaj z Martie Jainrose, zielarką z Redridge.",
    ["T"] = "Wizyta u zielarki",
  },
  [131] = {
    ["D"] = "Oto twój bukiet. Wybrałam żonkile - moje ulubione.",
    ["O"] = "Zanieś Darcy bukiet żonkili.",
    ["T"] = "Dostarczenie żonkili",
  },
  [132] = {
    ["D"] = "To, co ci powiem, może kosztować mnie życie. Bractwo Defias knuje coś naprawdę dużego... Kiedy ostatnio o nich słyszałem, współpracowali z gnollami, koboldami, a nawet goblinami.$B$BWeź ten list do Stoutmantle\'a. Jest tam wszystko, co wiem.",
    ["O"] = "Zanieś Wiley\'s Note do Gryana Stoutmantle\'a w Westfall.",
    ["T"] = "Bractwo Defias",
  },
  [133] = {
    ["D"] = "Żyję tak daleko poza granicami miasta, że to prawdziwy cud, że ghule i ożywione zwłoki jeszcze mnie nie pożarły! Zaledwie wczoraj były pod moim domem; grupa Bone Chewers tłukła w ściany mego domu!$B$BChcę zrobić straszak; coś w rodzaju <stracha na wróble> na ghule. Potrzeba mi do tego Ghoul Ribs. Na pewno uda ci się zdobyć je od Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones i Plague Spreaders.",
    ["O"] = "Zbierz 7 Ghoul Ribs i przynieś je do chaty Abercrombiego.",
    ["T"] = "Strach na ghule",
  },
  [134] = {
    ["D"] = "Kilka tygodni temu zbierałem zioła z dala od mej chaty, kiedy nagle zaatakowała mnie banda ogrów! Uciekłem, ale musiałem zostawić moją skrzynię z cennymi narzędziami i ziołami.$B$BGdy już przestały mnie ścigać, pewnie wróciły do swego kopca w południowym Duskwood. Jestem pewien, że gdzieś tam musi być moja skrzynia!$B$BProszę cię, $N, odzyskaj ją; jest mi bardzo potrzebna.",
    ["O"] = "Zwróć Abercrombiemu jego Skrzynię.",
    ["T"] = "Ogrze złodziejaszki",
  },
  [135] = {
    ["D"] = "Zastanawiam się, co miał na myśli Wiley, pisząc \"Kamieniarze\". Mogło to być tylko przejęzyczenie. Czy Bractwo Defias mogłoby być związane z Kamieniarzami? Jest tylko jedna osoba, która może to wiedzieć: Mathias Shaw, dowódca SI:7. Pokaż mu notatkę Wiley\'a i dowiedz się, czy wie coś, co może pomóc w rozwiązaniu tej zagadki. Jeżeli nie będziesz $gmógł:mogła; go znaleźć, sprawdź baraki w starym mieście.",
    ["O"] = "Zanieś Wiley\'s Note do Mathiasa Shawa ze Stormwind.",
    ["T"] = "Bractwo Defias",
  },
  [136] = {
    ["D"] = "Jeżeli to czytasz, to znaczy, że stary wilk morski, kapitan Sander, leży już trupem w swoim morskim grobie. A więc mój skarb jest teraz twój, starczy, że pójdziesz za wskazówkami. Najpierw musisz odnaleźć mój kuferek. Pewnie leży zagrzebany w piasku, gdzieś w pobliżu wraku na zachodnim brzegu Westfall. Tam jest kupa wraków, ale tylko jedna zardzewiała kotwica. Odnajdziesz kotwicę, odnajdziesz mój kufer i kolejną wskazówkę.",
    ["O"] = "Znajdź kuferek kapitana Sandera i poszukaj w nim kolejnej wskazówki.",
    ["T"] = "Ukryty skarb kapitana Sandera",
  },
  [137] = {
	["D"] = "Jeśli zyskałeś wyróżnienie od jednego z naszych marszałków, to przynieś je do mnie. Zasłużysz na jedno z naszych Lion Emblem gloves.",
	["O"] = "Generał Marcus Jonathan w Stormwind, zaakceptuje wyróżnienia z Elwynn Forest. Przyniesienie mu takiego dokumentu będzie nagradzane wyborem zbroi.",
	["T"] = "<NYI> <TXT> Stormwind Commendation",
  },
  [138] = {
    ["D"] = "Na pergaminie napisano: Dobra robota, szczurze lądowy. Teraz trza ci udać się na wschód. Na wschód, na klify; na wschód, w stronę drogi. Poszukaj ruin komina po tej stronie drogi; znajdziesz tam starą beczkę, a w niej następną wskazówkę.",
    ["O"] = "Odnajdź starą beczkę nieopodal zrujnowanego komina i poszukaj w niej kolejnej wskazówki.",
    ["T"] = "Ukryty skarb kapitana Sandera",
  },
  [139] = {
    ["D"] = "Przeszukując beczkę, $gnatknąłeś:natknęłaś; się na kolejny skrawek pergaminu. Na tym napisano: A teraz od tej beczki na północ - prosto, jak w mordę strzelił. Idź, aż ujrzysz dzban koło samotnego wiatraka na nadmorskim klifie, może tam znajdziesz to, czego szukasz.",
    ["O"] = "Przeszukaj pusty dzban niedaleko opuszczonego młyna, aby zdobyć kolejną wskazówkę.",
    ["T"] = "Ukryty skarb kapitana Sandera",
  },
  [140] = {
    ["D"] = "Z pewnością na dnie starego dzbana kryje się następny trop do skarbu Sandera. W niektórych miejscach tusz zdążył już wyblaknąć, zaś papier wonie whisky, ale udaje ci się odczytać fragmenty tekstu: jakżeś $gznalazł:znalazła; mój stary dzban, twoja jedna łapa leży już na skarbie! Po prostu idźta na zachód od butelki i zleźta na brzeg. Jak już dojdziesz do wody, dalej naprzód! Płyńta prosto na zachód, aż będzie wyspa z moją skrzynią skarbów!",
    ["O"] = "Znajdź skrzynię kapitana Sandera i zabierz z niej swą nagrodę.",
    ["T"] = "Ukryty skarb kapitana Sandera",
  },
  [141] = {
    ["D"] = "Gildią Kamieniarzy kierował mężczyzna o imieniu Edwin VanCleef. Był on odpowiedzialny za odbudowę Stormwind po tym, jak orkowie zrównały je z ziemią podczas Pierwszej Wojny. Najwidoczniej VanCleef i jego ludzie nie byli zadowoleni ze sposobu, w jaki potraktował ich król po zakończeniu ich pracy. To może wyjaśniać jedną czy dwie kwestie.$B$BNapisałem bardziej szczegółowe sprawozdanie dla twego mistrza z Westfall. Natychmiast mu je dostarcz!",
    ["O"] = "Dostarcz raport Shawa do Gryana Stoutmantle w Westfall.",
    ["T"] = "Bractwo Defias",
  },
  [142] = {
    ["D"] = "Musimy znaleźć kryjówkę Defiasów. $N, mój zwiadowca doniósł, że na drodze pomiędzy Moonbrook, a Kamieniołomem Złotego Brzegu i Kopalnią Jangolode widziano posłańca Defiasów. Chcę, byś go $gschwytał:schwytała;. Jeśli będzie się opierać, zabij go i przynieś mi wszystko, co przy nim znajdziesz.",
    ["O"] = "Wytrop w Westfall Defiaskiego Posłańca i dostarcz Stoutmantle\'owi jego wiadomość.",
    ["T"] = "Bractwo Defias",
  },
  [143] = {
    ["D"] = "Coś dziwnego dzieje się z armią Stormwind. Jej siły już dawno powinny tu przybyć. Czas jest luksusem, na który nas nie stać. Nie będę stać biernie i patrzyć, jak ludzie z Lakeshire oddają swe życie; spróbuję uzyskać pomoc. Zdobyłem informacje o oddziałach Straży Obywatelskiej formujących się w Westfall.$B$BZabierz ten apel do ich dowódcy, Gryana Stoutmantle\'a. Być może jego ludzie będą mogli nam pomóc, dopóki król nie przyśle tu armii.",
    ["O"] = "Sędzia Solomon pragnie, byś $gdostarczył:dostarczyła; jego apel do Gryana Stoutmantle\'a w Westfall.",
    ["T"] = "Posłaniec do Westfall",
  },
  [144] = {
    ["D"] = "Wiadomość od sędziego Solomona sprawiła mi ból. Lecz oczywistym jest, że nie wie o wojnie, która toczy się w Westfall. W innym wypadku wiedziałby, że nie może oczekiwać naszej pomocy. Gdyby Stormwind również nas nie porzuciło, nie musielibyśmy powoływać Straży Obywatelskiej.$B$B$C, weź tę odpowiedź do swego mistrza w Redridge. Niech wie, że moje serce przepełnia ból po stracie dobrych ludzi.",
    ["O"] = "Wróć do sędziego Solomona z odpowiedzią Gryana Stoutmantle\'a.",
    ["T"] = "Posłaniec do Westfall",
  },
  [145] = {
    ["D"] = "Po raz kolejny potrzebuję twojej pomocy. Napisałem do Lorda Ebonlocke\'a z prośbą o wysłanie jego wyszkolonych ludzi - Nocnej Straży, by wspomogli obronę Lakeshire. Musisz koniecznie dopilnować, by szybko otrzymał on tę wiadomość. I musisz zachować przy tym szczególną ostrożność. Ebonlocke jest burmistrzem Darkshire w samym sercu Duskwood. Nie oddalaj się od drogi.",
    ["O"] = "Sędzia Solomon pragnie, byś $gdostarczył:dostarczyła; ten list Lordowi Ebonlocke\'owi z Darkshire.",
    ["T"] = "Posłaniec do Darkshire",
  },
  [146] = {
    ["D"] = "Gdybym nie znał osobiście sędziego Solomona, powiedziałbym, że ten człowiek zwariował. Wysłać Nocną Straż do Lakeshire, ponieważ Stormwind odmówiło pomocy? Sformowano ją, gdyż Stormwind opuściło nas, gdy plugawa magia przeniknęła do tej ziemi. Gdybym wysłał Nocną Straż, siły zła opanowałyby to miasto, nim dotarłaby ona do granic lasu.$B$BWeź ten list z odpowiedzią do twego mistrza z Lakeshire.",
    ["O"] = "Wróć do sędziego Solomona z odpowiedzią Lorda Ebonlocke\'a.",
    ["T"] = "Posłaniec do Darkshire",
  },
  [147] = {
    ["D"] = "Jeżeli \"poborca\" zabiera złoto z naszych kopalń, okrada tym samym królestwo! Wymierz mu sprawiedliwość i zwróć mi pierścień wymieniony w spisie, który mi $gdałeś:dałaś;. Może nam powiedzieć, dla kogo pracuje \"poborca\"...$B$BWykaz mówi, że ukrywa się na polu dyń Brackwell\'ów. $gPowinieneś:Powinnaś; go tam poszukać.",
    ["O"] = "Odszukaj i zgładź \"poborcę\" i wróć do marszałka Dughana z jego pierścieniem.",
    ["T"] = "Polowanie na ludzi",
  },
  [148] = {
    ["D"] = "Och, co ma zrobić biedny stary człowiek? Potrzebuję paru rzeczy z Darkshire, ale wioska jest tak daleko, a ja jestem taki stary i słaby... Nigdy nie dotarłbym do celu.$B$BMożesz udać się do Darkshire i przynieść mi trochę Ghost Hair Thread? Dostaniesz je od Madame Evy; jej dom mieści się przy placu w Darkshire.",
    ["O"] = "Porozmawiaj z Madame Evą.",
    ["T"] = "Zapasy z Darkshire",
  },
  [149] = {
    ["D"] = "Istnieje pewien biedny, smutny duch - Blind Mary, nawiedzający dom na starej farmie na wzgórzach na południu od Darkshire.$B$BTrzymaj, oto Spectral Comb; zaproponuj Blind Mary, aby uczesała nim swoje włosy. Potem przynieś mi grzebień z powrotem, a ja zbiorę zeń Włosy Ducha potrzebne na nić.$B$BLecz uważaj, mroczne istoty czają się niedaleko tego domu...",
    ["O"] = "Dostarcz Spectral Comb do Blind Mary.",
    ["T"] = "Nić z włosów ducha",
  },
  [150] = {
    ["D"] = "Murloki zaczynają stanowić problem. Coraz większe grupy rybaków zarzucają kotwice u brzegów Jeziora Everstill i wyciągają puste sieci! Musimy sprawić, by te stwory odeszły, zanim zjedzą wszystkie ryby w jeziorze!$B$BUdaj się na polowanie na murloki! Dostarcz mi osiem ich płetw, a być może znajdę coś dla ciebie...",
    ["O"] = "Dostarcz 8 Murloc Fins do dokmistrza Barena z Lakeshire.",
    ["T"] = "Kłusujące murloki",
  },
  [151] = {
    ["D"] = "Biedna Stara Siwka! Taka zmęczona po ciężkiej pracy, którą musiała wykonać. Nakarmiłam ją, nim opuściłyśmy farmę, ale nie spodziewałyśmy się, że wóz się zepsuje. Jeśli $gmógłbyś:mogłabyś; przynieść jej kilka garści owsa z roli, byłabym wdzięczna.$B$BZ pewnością znajdziesz owies na większości farm w Westfall, jeśli tylko zdołasz utrzymać się z daleka od tych przerażających maszyn, które opanowały ten obszar. Kilka farm znajduje się na południowy zachód stąd.",
    ["O"] = "Verna Furlbrow z Westfall chce, by dostarczyć jej 8 Handfuls of Oats.",
    ["T"] = "Biedna Stara Siwka",
  },
  [152] = {
    ["D"] = "Pewnie $gzauważyłeś:zauważyłaś; wszystkie te wraki wzdłuż wybrzeża. Wielkie Morze jest zaiste zdradliwe. Należy oczyszczać wybrzeże Westfall, aby żeglarze pragnący odnaleźć drogę na nasze plaże byli bezpieczni. Murloki rzeczywiście stanowią problem.$B$BZabij 7 łowców fal, 7 wojowników, 7 wyroczni i 7 plażobiegaczy, a nie odejdziesz bez nagrody.",
    ["O"] = "Zabij 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners i wróć do kapitana Graysona obok Westfall Lighthouse.",
    ["T"] = "Nieoczyszczone wybrzeże",
  },
  [153] = {
    ["D"] = "Front walk z Defiasami ciągle się zmienia. Śledzę ich ruchy od dłuższego czasu. Ustaliłem, że wielu członków gangu można rozpoznać po czerwonych skórzanych chustach, które noszą.$B$BDostarcz mi 15 tych chust, a zostaniesz odpowiednio $gwynagrodzony:wynagrodzona;.",
    ["O"] = "Przynieś 15 Red Leather Bandanas do zwiadowcy Galiaana w Sentinel Hill.",
    ["T"] = "Czerwone skórzane chusty",
  },
  [154] = {
    ["D"] = "NIE!!!!! $B$BZabierz to, zabierz ten grzebień jak najdalej ode mnie!$B$BJestem potworem i nikt już nigdy nie pomyśli, że jestem ładna!",
    ["O"] = "Zwróć Ghost Hair Comb do Madame Eva z Darkshire.",
    ["T"] = "Zwróć grzebień",
  },
  [155] = {
    ["D"] = "A więc Stoutmantle wysyła takiego nieudacznika jak ty, aby mnie strzegł? Chyba będziesz się $gmusiał:musiała; postarać. Lepiej zbierz jakichś przyjaciół.$B$BZnasz warunki umowy? Pilnujesz mnie jak oka w głowie, a ja prowadzę cię do kryjówki Defiasów. Ale lepiej trzymaj się blisko mnie. Gang Defias chce teraz mojej głowy. Jeśli zobaczą mnie w twoim towarzystwie, będą chcieli mnie zabić.$B$BDaj znać, gdy zbierzesz przyjaciół i będziecie gotowi do drogi.",
    ["O"] = "Eskortuj Defias Traitor do sekretnej kryjówki Bractwa Defias. Gdy tylko pokaże ci, gdzie ukrywają się VanCleef i jego ludzie, zanieś tę informację Gryanowi Stoutmantle.",
    ["T"] = "Bractwo Defias",
  },
  [156] = {
    ["D"] = "Jeśli dostarczysz mi gnijące kwiaty, będę mógł zaparzyć porcję soku żywych trupów.$B$BGnijące kwiaty rosną w dziwnych miejscach. Słyszałem, że najczęściej można je znaleźć w czaszkach Skeletal Horrors i Skeletal Fiends... ale nigdy nie zbliżyłem się do nich dość blisko, by to sprawdzić.$B$BRaven Hill Cemetery są pełne tych szkieletów. Szukając gnijących kwiatów, możesz jednocześnie je zgładzić. Miasto Darkshire będzie ci wdzięczne.",
    ["O"] = "Zbierz 8 Rot Blossoms i dostarcz je do Tavernkeep Smitts w Darkshire.",
    ["T"] = "Zbierz gnijące kwiaty",
  },
  [157] = {
    ["D"] = "Oto i nić, $N. Ma tysiące zastosowań, od wiązania złych duchów do ożywiania martwych przedmiotów.",
    ["O"] = "Dostarcz Ghost Hair Thread do Abercrombiego, do jego szopy na północ od Raven Hill Cemetery.",
    ["T"] = "Dostarcz nić",
  },
  [158] = {
    ["D"] = "Potrzebuję flaszki pewnego napoju - Zombie Juice. Oberżysta Smitts z Scarlet Raven Tavern w Darkshire powinien go mieć.$B$BI proszę, pospiesz się, $N. Noce stają się coraz chłodniejsze i potrzebuję napoju, który z powrotem rozpali mą krew!",
    ["O"] = "Porozmawiaj z Tavernkeep Smitts.",
    ["T"] = "Sok z żywych trupów",
  },
  [159] = {
    ["D"] = "Oto twój Zombie Juice...$B$B...i lepiej z nim uważaj. Ma dość siły, by postawić umarłego na nogi!",
    ["O"] = "Dostarcz Zombie Juice do Abercrombiego w jego szopie.",
    ["T"] = "Dostawa soku",
  },
  [160] = {
    ["D"] = "Zanieś tę notatkę do Ella Ebonlocke\'a, Burmistrza Darkshire.$B$BOn i ja jesteśmy starymi przyjaciółmi... a kiedy to przeczyta i odkryje, co dla mnie zrobiłeś... jestem pewien, że będzie równie szczęśliwy, co ja! Hahahaha!",
    ["O"] = "Zanieś Abercrombie\'s Letter do Ello Ebonlocke\'a, Burmistrza Darkshire.",
    ["T"] = "Notka dla Burmistrza",
  },
  [161] = {
    ["D"] = "Jeśli moje podejrzenia są słuszne, jest to pewien rodzaj prochu wybuchowego. Musi przeanalizować go ekspert od materiałów wybuchowych, żebyśmy wiedzieli, z czym naprawdę mamy do czynienia. Ashlan Stonesmirk został przydzielony do oddziału strzegącego Dun Modr i Przęsła Thandol. Chcę, $N, byś $gudał:udała; się w ważną, acz niebezpieczną podróż.$B$BPrzekrocz Bramę Algaz, po czym kieruj się drogą przez Wetlands i znajdź Stonesmirka w Dun Modr. Wysłuchaj mej rady: trzymaj się traktu i w żadnym wypadku się nie zatrzymuj!",
    ["O"] = "Główny inżynier Hinderweir chce, byś $gzaniósł:zaniosła; dziwnie pachnący proszek Ashlanowi Stonesmirkowi, ekspertowi od materiałów wybuchowych z Dun Modr.",
    ["T"] = "Nadciąga mroczne zagrożenie",
  },
  [162] = {
    ["D"] = "Zależy mi, byś dostarczył ten raport komuś posiadającemu praktyczne doświadczenie w tej sprawie.$B$BZnam uczoną nocną elfkę, Gracinę Spiritmight. Poświęciła mnóstwo czasu badaniom form życia unikalnych dla ekologii Azeroth; ponadto jest historyczką! Jeśli chcesz znaleźć kogoś, kto wyjaśni ci prawdziwy charakter tego zagrożenia i, co więcej, powie jak je powstrzymać, zanieś jej ten raport. Przyda się nam pomoc.$B$BOstatnim razem, kiedy o niej słyszałem, przebywała w Temple of the Moon, w Darnassus.",
    ["O"] = "Dostarcz Insect Analysis Report do Graciny Spiritmight z Darnassus.",
    ["T"] = "Odrodzenie silithidów",
  },
  [163] = {
    ["D"] = "Coś jest nie w porządku w Raven Hill, $N. Calor przysięga, że ktoś -lub coś - nawiedza tamtejsze budynki. Dwie noce z rzędu widział tam poruszające się cienie, a twierdzi, że jeszcze jedną wcześniej widział światło w jednym z okien.$B$BJeśli, jak mówisz, troszczysz się o bezpieczeństwo Duskwood, dowiedz się, jaka okropność straszy w Raven Hill.",
    ["O"] = "Dowiedz się, co straszy w Raven Hill.",
    ["T"] = "Krucze Wzgórze",
  },
  [164] = {
    ["D"] = "Znasz Svena? No, oto człowiek, który służy Światłości! Wraz ze swoimi towarzyszami rozbił obóz na północno-zachodnim krańcu Duskwood.$B$BNiestety, ponieważ jest ich tak niewielu, nie mogą sobie pozwolić na wysyłanie nikogo po zapasy do miasteczka. Może ty mogłabyś dostarczyć zaopatrzenie do Svena?",
    ["O"] = "Dostarcz Svenowi zaopatrzenie.",
    ["T"] = "Przesyłka dla Svena",
  },
  [165] = {
    ["D"] = "Niegdyś pewien starzec zjawiał się często w miasteczku po zaopatrzenie, lecz od jakiegoś czasu go nie widziałam. Zamieszkuje chałupę powyżej cmentarza w Raven Hill, o ile dobrze pamiętam. Może powinnaś pójść tam i sprawdzić, czy wszystko jest w porządku?",
    ["O"] = "Odszukaj starca z chałupy obok cmentarza w Raven Hill.",
    ["T"] = "Pustelnik",
  },
  [166] = {
    ["D"] = "Jest jeszcze jedno zadanie, które musisz wykonać. Trzeba zabić Edwina VanCleefa. Choć zawsze smuci mnie wydawanie na kogoś wyroku śmierci, dobro mieszkańców Westfall wymaga, by VanCleef opuścił ten świat raz na zawsze. Po wykonaniu zadania przynieś mi głowę tego złoczyńcy.",
    ["O"] = "Zabij Edwina VanCleefa i przynieś Gryanowi Stoutmantle\'owi jego głowę.",
    ["T"] = "Bractwo Defias",
  },
  [167] = {
    ["D"] = "Znajdowaliśmy się głęboko w rozległej kopalni w Westfall, ukrytej pod stodołą w Moonbrook. Nie mam pojęcia, skąd pojawili się ci cuchnący rabusie. Niemniej jednak, tunel kopalni zawalił się na nas. Zdołałem się wydostać, ale inni... cóż... o innych nikt już nic nie słyszał.$B$BWyglądasz na kogoś, kto może mieć tam więcej szczęścia. Jeśli mógłbyś odnaleźć mojego brata, byłbym wdzięczny. Zawsze nosił przy sobie swą Odznakę Ligi Odkrywców. Jeśli nie znajdziesz jego samego, ta odznaka pozwoli mi przynajmniej odzyskać spokój.",
    ["O"] = "Zanieś Foreman Thistlenettle\'s Explorers\' League Badge do Wilder Thistlenettle w Stormwind.",
    ["T"] = "Och, bracie...",
  },
  [168] = {
    ["D"] = "Wielu moich przyjaciół zginęło tego strasznego dnia, gdy tunel kopalni się zapadł. Jeśli twe przygody zawiodą cię do tamtej części kopalni w Moonbrook, proszę, rozejrzyj się za czymkolwiek, co mogłoby ich zidentyfikować. Jeśli natkniesz się na którąś z Kart Związku Górników, przynieś ją mnie, a dopilnuję, by do rodzin zmarłych dotarło wyjaśnienie tego okropnego wypadku.",
    ["O"] = "Odzyskaj 4 Miners\' Union Cards i zwróć je Wilderowi Thistlenettle\'owi ze Stormwind.",
    ["T"] = "Zbierając wspomnienia",
  },
  [169] = {
    ["D"] = "Poszukiwany! Gath\'Ilzogg, Przywódca ataków Czarnej Skały na Twierdzę Stonewatch i rajdów przeciwko powiatowi Lakeshire.$B$BGath\'Ilzogg jest bardzo niebezpieczny. Z raportów wynika, że przesiaduje on w niedawno podbitej twierdzy snując plany kolejnych zbrodni klanu Czarnej Skały wymierzonych przeciwko ludzkości. Plaga orków musi zostać stłumiona za wszelką cenę. Sprawiedliwa nagroda zostanie przekazana któremukolwiek wojownikowi o odważnej duszy, który zdoła przynieść głowę Gath\'Ilzogga do sędziego Solomona.",
    ["O"] = "Zabij Gath\'Ilzogga i przynieś jego głowę sędziemu Solomonowi w Lakeshire, aby otrzymać nagrodę.",
    ["T"] = "Poszukiwany: Gath\'Ilzogg",
  },
  [170] = {
    ["D"] = "Mam nadzieję, że jesteś tu, by udzielić nam pomocy, $C. Po ostatnim ataku troggów przyda nam się każde wsparcie.$B$BSłyszałem, że te zarazy pokazały się w całej krainie i wygląda na to, że Dolina Coldridge nie jest wyjątkiem. Widziano ich w wielu miejscach na wzgórzach na południowym wschodzie i niedaleko zamarzniętego jeziora.$B$BI to jeszcze nie wszystko, zaledwie kilka nocy wcześniej zaatakowali i opanowali nasz obóz na zachodzie!$B$BBrakuje nam ludzi i każda para rąk przyda się, by odepchnąć troggi.",
    ["O"] = "Balir Frosthammer pragnie śmierci 6 Rockjaw Troggs i 6 Burly Rockjaw Troggs.",
    ["T"] = "Nowe zagrożenie",
  },
  [171] = {
    ["D"] = "$gByłeś dla mnie taki miły:Byłaś dla mnie taka miła;, $N. Nigdy nie marzyłem, że będę się tak dobrze bawić podczas Dziecięcego Tygodnia. Dziękuję ci.$B$BChciałbym, by wszystkie dzieci z sierocińca miały tyle szczęścia, by mogły robić te same rzeczy co my. Myślisz, że możemy znów znaleźć Craggle Wobbletop i zdobyć piankowy miecz od niego? Chyba nadal taszczy swój wózek wzdłuż kanałów na zewnątrz Dzielnicy Handlowej. Dzięki niemu wszyscy w sierocincu będą też miali ubaw!$B$BPo tym będę już musiał iść do domu.",
    ["O"] = "Kup Foam Sword Rack od Craggle Wobbletop, następnie odprowadź swojego wychowanka do sierocińca w Stormwind rozmawiając z Orphan Matron Nightingale w Cathedral District.",
    ["T"] = "Opiekunka Przymierza",
  },
  [172] = {
    ["D"] = "Chcesz pomóc nam tutaj w sierocińcu? Zyskasz naszą wdzięczność $gprzyjacielu:przyjaciółko;; twoja pomoc w czasie Dziecięcego Tygodnia będzie bezcenna.$B$BWeź ten gwizdek. Będziesz $gmógł:mogła; używać go tylko przez siedem dni - okres trwania Dziecięcego Tygodnia. Kiedy nim zagwiżdżesz, będziesz $gmógł:mogła; porozmawiać z dzieckiem, którym $gzgodziłeś:zgodziłaś; się opiekować. Gdy użyjesz go ponownie, dziecko się oddali.$B$BA teraz, $N, zrób to! Jestem przekonana, że chłopak nie może się doczekać tego spotkania.",
    ["O"] = "Użyj Orcish Orphan Whistle, by porozmawiać z dzieckiem, którym będziesz się opiekować w ciągu Dziecięcego Tygodnia.",
    ["T"] = "Dziecięcy Tydzień",
  },
  [173] = {
    ["D"] = "Wygląda na to, że ciemność nieuchronnie zbliża się do Duskwood. Zadaniem Mistrza Carevina jest wykrzewienie zła i herezji. Dzięki naszym wysiłkom ludzie z Darkshire są bezpieczni.$B$BUważasz, że jesteś godny, by do nas dołączyć?$B$BKiedyś myślałem właśnie tak jak ty. Rozczarowany samozadowoleniem Straży przyłączyłem się do Mistrza Carevina. Jeśli chcesz się wykazać, słowa nie wystarczą.$B$BWypróbuj swoje umiejętności, zwalczając Nightbane Shadow Weaver w Brightwood Grove - Jasnych, ha! - oraz w Rotting Orchard.",
    ["O"] = "Calor z Darkshire chce śmierci 6 Nightbane Shadow Weaver.",
    ["T"] = "Wilkołaki w puszczy",
  },
  [174] = {
    ["D"] = "Mój przyjaciel, gnom Cog, obiecał pomóc mi w budowie urządzenia, które pozwoli mi dokładniej przyjrzeć się gwiazdom. Poza magią istnieje prawda tłumacząca dziwne przemiany w lesie.$B$BPrzynieś mi tubę z brązu, którą może wykonać tylko wykwalifikowany inżynier. Zgodnie z projektem Coga jest to pierwszy krok.",
    ["O"] = "Viktori Prism\'Antras z Darkshire chce, byś przyniósł mu tubę z brązu.",
    ["T"] = "Popatrz w gwiazdy",
  },
  [175] = {
    ["D"] = "Zgodnie z projektem Coga potrzebuję teraz czegoś, co odbija światło. Pamiętam kobietę o imieniu Mary, dobrze znaną w tych okolicach ze względu na to, że zawsze nosiła przy sobie lusterko. Może mógłbyś odnaleźć ją i dowiedzieć się, czy użyczy go nam na potrzeby projektu? Wydaje mi się, że mieszkała kiedyś na południu Duskwood...",
    ["O"] = "Znajdź Mary i przekonaj ją, by oddała swe lusterko na potrzeby projektu Viktoriego.",
    ["T"] = "Popatrz w gwiazdy",
  },
  [176] = {
    ["D"] = "Poszukiwany: Hogger.$B$BWielki gnoll, Hogger, grasuje w południowo-zachodniej części Elwynn. Udało mu się uniknąć wszelkich prób pochwycenia.$B$BArmia Stormwind oferuje hojną nagrodę za jego złapanie. Aby ją zdobyć, łowcy nagród powinni dostarczyć dowód upadku Hoggera do marszałka Dughana w Goldshire.",
    ["O"] = "Zabij gnolla Hoggera i zanieś jego wielki pazur do marszałka Dughana.",
    ["T"] = "Poszukiwany: \"Hogger\"",
  },
  [177] = {
    ["D"] = "Lusterko było jednym z moich najcenniejszych skarbów do czasu... pewnego incydentu. Po tym, co się stało, wyrzuciłam je za stodołę. Włóczył się tam pewien obłąkany ghul. Może on je zabrał. Plotka głosi, że ta diabelska bestia grasuje na Tranquil Gardens Cemetery.",
    ["O"] = "Odzyskaj Blind Mary\'s Looking Glass od Insane Ghoul i zanieś je Viktoriemu z Darkshire.",
    ["T"] = "Popatrz w gwiazdy",
  },
  [178] = {
    ["D"] = "<Słyszysz jakiś bezcielesny głos...>$B$BNie bój się. Jestem Theocritus, Wielki Mag z Wieży Azory w Elwynn Forest. Wisiorek, który trzymasz, to środek komunikacji między cienistoskórymi gnollami a ich mistrzem, Morganthem.$B$BPo miesiącach badań przypuszczam, że również potrafię porozumiewać się przez te wisiorki. Jeśli słyszysz tę wiadomość, moje zaklęcie okazało się skuteczne.$B$BPrzynieś mi ten wisiorek, a wynagrodzę cię za tę usługę.",
    ["O"] = "Przynieś Faded Shadowhide Pendant do Maga Theocritusa.",
    ["T"] = "Poszukiwania dla Theocritusa",
  },
  [179] = {
    ["D"] = "Co my tu mamy? Wyglądasz, jakbyś $gpotrzebował:potrzebowała; czegoś do ogrzania dłoni, co?$B$BPowiem ci, co może ci pomóc: para pięknych, ciepłych rękawic. I, będąc tak wspaniałomyślną duszyczką, jaką jestem, z radością postaram się o odpowiednią parę dla ciebie. Jednakże pod jednym warunkiem.$B$BChciałbym, żebyś $gzdobył:zdobyła; dla mnie trochę wilczego mięsa. Kusząca umowa, co? Ty przynosisz mi wilcze mięso, a ja sprawiam, że nie stracisz żadnego palca przez odmrożenie. No i co na to powiesz?",
    ["O"] = "Sten Stoutarm chciałby otrzymać 8 płatów Tough Wolf Meat.",
    ["T"] = "Krasnoludzcy subiekci",
  },
  [180] = {
    ["D"] = "Poszukiwany: porucznik Fangore$B$BZnany lider klanu cienistoskórych gnolli, współpracujący z wrogiem miasteczka oraz królestwa, Morganthem. Z nakazu sędziego Salomona, ten nikczemny zdrajca Stormwind jest poszukiwany, martwy. Jako dowód jego zgładzenia, dostarcz jego łapę do sędziego.",
    ["O"] = "Zabij porucznika Fangore\'a, a następnie dostarcz jego łapę do sędziego Solomona znajdującego się w Lakeshire.",
    ["T"] = "Poszukiwany: porucznik Fangore",
  },
  [181] = {
    ["D"] = "Teraz już tylko jeden przedmiot jest potrzebny do ukończenia urządzenia. Z jakiegoś powodu plany Cog\'a wymagają soczewki. Jedyna soczewka, która będzie na tyle duża będzie trudna do zdobycia.$B$BJest pewien ogr, imieniem Zzarc\'Vul, który przebywa na południu Duskwood. Jeśli możesz przynieść mi jego monokl to użyje go jako soczewki!",
    ["O"] = "Zlokalizuj Zzarc\'Vula w południowej części kopca ogrów w Duskwood i zwróć jego monokl Viktorii w Darkshire.",
    ["T"] = "Spójrz w gwiazdy",
  },
  [182] = {
    ["D"] = "Ja i mój brat zostaliśmy wysłani w różne części Dun Morogh, by prześledzić zagrożenie ze strony trolli. Senat ma ręce pełne roboty przez troggi, więc nie potrzebują, by zaprzątał ich głowy kolejny kłopot.$B$BZ tego co widziałem, trolle nie radzą sobie za dobrze w dolinie, większość z nich znajduje się w jaskini na południu. Rzekłbym nawet, że nie potrzebujemy wielu żołnierzy, by się z nimi uporać. Wystarczy kilku silnych wojowników.$B$BByć może ty zechcesz pomóc? Jestem w stanie sowicie cię wynagrodzić.",
    ["O"] = "Grelin Whitebeard chce, byś $gzabił:zabiła; 14 Frostmane Troll Whelps.",
    ["T"] = "Jaskinia trolli",
  },
  [183] = {
    ["D"] = "Nie ma to jak dzień polowania na dziki, eh?$B$BTutaj, w Dolinie Coldridge, jest wiele dzików, że poluje się na nie głównie dla zabawy. Nie musisz ich rozbudzać. Wszystkie są głodne i gotowe do ataku. Niedawno nie było tu ich tak wielu. Teraz nawet moje dzienne polowanie staje się niebezpieczne.$B$BJeśli chcesz mi pomóc, zabij kilka dzików, byłbym wdzięczny.",
    ["O"] = "Talin Keeneye chce, abyś $gzabił:zabiła; 12 Small Crag Boars.",
    ["T"] = "Łowca dzików",
  },
  [184] = {
    ["D"] = "To stary akt własności pól uprawnych w Westfall. Jest podpisany przez Theodore Furlbrowa i jego żonę, Vernę. Na odwrocie jest nabazgrane:$B$B\"Mamy akt własności Furlbrowa. Pomyśleliśmy, że moglibyście podrobić jeden dla własnej farmy.$B$BPaństwo Furlbrow nie sprawią kłopotów. Ostatni raz widziałam ich kiedy chcieli wyjechać z Westfall, ale ich wóz się rozbił\".$B$BMyślisz, że chcą z powrotem swoje dokumenty...",
    ["O"] = "Przynieś Furlbrow\'s Deed do Farmer Furlbrow.",
    ["T"] = "Akt własności Furlbrowa",
  },
  [185] = {
    ["D"] = "Kiedy byłam jeszcze małą dziewczynką, mój ojciec szkolił mnie w sztuce polowania na tygrysy.$B$BNajłatwiej będzie Ci wytropić i zabić te młodsze. W ten sposób zaczniemy na spokojnie. Można je znaleźć w pobliżu obozu.$B$BSprawdź swoje umiejętności tropienia i upoluj kilka bestii. Zacznij od okolic naszego obozu na południu. Rozpocznij polowanie w pobliżu naszego obozu na południu.",
    ["O"] = "Ajeck Rouack z Ekspedycji Nesingwary\'ego chce, abyś zabił 10 Young Stranglethorn Tigers.",
    ["T"] = "Polowanie na tygrysy",
  },
  [186] = {
    ["D"] = "Uczysz się, $C. Pozwól nam teraz przetestować twoje umiejętności z dojrzałymi kotami. Tym razem zabij 10 tygrysów Stranglethorn.",
    ["O"] = "Ajeck Rouack z ekspedycji Nesingwary\'ego chce, żebyś zabił 10 Stranglethorn Tigers.",
    ["T"] = "Mistrzostwo w polowaniach na tygrysy",
  },
  [187] = {
    ["D"] = "Teraz podniosę stawkę i naprawdę przetestuję twoje umiejętności. Udowodnij mi, że możesz zabić 10 starszych tygrysów Stranglethorn. Jeśli zdołasz to zrobić, będziesz $ggotowy:gotowa; na ostatnie wyzwanie, zanim ogłoszę cię mistrzem łowców tygrysów w obecności Mistrza Nesingwary\'ego.$B$BStarsze tygrysy Stranglethorn są nie tylko najtrudniejsze do znalezienia, ale także najtrudniejsze do pokonania.",
    ["O"] = "Ajeck Rouack z ekspedycji Nesingwary\'ego chce, żebyś zabił 10 Elder Stranglethorn Tigers.",
    ["T"] = "Mistrzostwo w polowaniach na tygrysy",
  },
  [188] = {
    ["D"] = "Oto ostatnie wyzwanie, które ci postawię. Śledzimy nieuchwytnego tygrysa od tygodni. Nazywamy bestię Sin\'Dall. Sprawdź, czy możesz zrobić to, czego wcześniej nie zrobił żaden $R: wytrop i zabij Sin\'Dall.$B$BPrzynieś mi jej łapę jako dowód twojego osiągnięcia.$B$BWytropienie jej nie będzie łatwym zadaniem.",
    ["O"] = "Ajeck Rouack z Ekspedycji Nesingwarego chce byś $gzabił:zabiła; Sin\'Dall i $gwrócił:wróciła; z jej łapą.",
    ["T"] = "Władza nad tygrysami",
  },
  [189] = {
    ["D"] = "Przeklęte trole! Zabijają naszych ludzi w dżungli. Straciłem już kilku z moich najlepszych strażników w potyczkach z nimi. Koszty rosną! Jak to wyjaśnię Baronowi Revilgazowi?$B$BZdecydowane działania... Myśl, Kebok... nie zostałeś zatrudniony po to, by siedzieć i nic nie robić... Mam to! Ty... $N, dobrze mówię? Pomożesz mi, prawda? Mam pieniądze!$B$BOto propozycja... Przyniesiesz mi 15 uch tych Bloodscalp troli, a ja ci się zrekompensuję pieniężnie.",
    ["O"] = "Zdobądź 15 Bloodscalp Ears i zanieś je do Keboka w Booty Bay.",
    ["T"] = "Uszy Bloodscalp",
  },
  [190] = {
    ["D"] = "Jeśli chcesz być częścią grupy, która poluje pod przewodnictwem Hemeta Jr., będziesz $gmusiał:musiała; udowodnić jak zdolnym myśliwym jesteś. Zaczniemy od podstaw, bez obaw! Na start zabij 10 Young Panthers.$B$BTropienie ich to dopiero połowa wyzwania...",
    ["O"] = "Sir S.J. Erlgadin z Ekspedycji Nesingwary chce, byś zabił 10 Young Panthers.",
    ["T"] = "Mistrzostwo W Polowaniu Na Pantery",
  },
  [191] = {
    ["D"] = "Jesteś już gotowy na coś trudniejszego. Jeśli chcesz udowodnić, że jesteś godzien przebywania w gronie myśliwych wielkich zdobyczy, musisz pokazać, że jesteś wstanie zabić 10 panter.$B$BTe gadziny są twardsze. Nie są już tak łatwe jak te młode, które zabijałeś niedawno.",
    ["O"] = "Sir S.J. Erlgadin z Ekspedycji Nesingwary chce, byś zabił 10 Panter",
    ["T"] = "Mistrzostwo W Polowaniu Na Pantery",
  },
  [192] = {
    ["D"] = "Teraz ta trudna część. Prawdziwy myśliwy panter może pokazać swoje umiejętności powalając Shadowmaw Panther, najbardziej zabójcze w Stranglethorn. Udowodnij nam, że umiesz zabić 10 tych bestii.$B$BJeśli myślisz, że trudno je wytropić, poczekaj aż spróbujesz jakąś ukatrupić...",
    ["O"] = "Sir S.J. Erlgadin z Ekspedycji Nesingwary chce, byś zabił 10 Shadowmaw Panther.",
    ["T"] = "Mistrzostwo W Polowaniu Na Pantery",
  },
  [193] = {
    ["D"] = "Już prawie $gudowodniłeś:udowodniłaś;, że jesteś $gmistrzem:mistrzynią; polowania na pantery. Ostatnio pantera o imieniu Bhag\'thera grasuje po dżungli. Do teraz wymykała się naszej zgrai. Sprawdź czy umiesz wykorzystać swoje umiejętności, by zabić wielką Bhag\'therę.$B$BPrzynieś mi Fang of Bhag\'thera wtedy zasłużysz na mój szacunek!",
    ["O"] = "Sir S.J. Erlgadin z Ekspedycji Nesingwary chce, byś przyniósł mu Fang of Bhag\'thera.",
    ["T"] = "Mistrzostwo W Polowaniu Na Pantery",
  },
  [194] = {
    ["D"] = "Więc myślisz, że twoje umiejętności łowieckie są na najwyższym poziomie? Sprawdzę je w momencik. Wyrusz do dżungli i zabij 10 Stranglethorn Raptor. Zobaczymy jak $gdobrym łowcą:dobrą łowczynią; jesteś.$B$BI nie, nie powiem Ci gdzie możesz je znaleźć! Znalezienie ich jest połową zadania.",
    ["O"] = "Hemet Nesingwary Jr. chce, byś $gzabił:zabiła; 10 Stranglethorn Raptor.",
    ["T"] = "Mistrzostwo W Polowaniu Na Raptory",
  },
  [195] = {
    ["D"] = "Pora podnieść poprzeczkę i sprawdzić, czy sobie poradzisz. Wyrusz do dżungli i ukatrup 10 Lashtail Raptor. Pokaż na co Cię stać!",
    ["O"] = "Hemet Nesingwary Jr. chce, byś $gzabił:zabiła; 10 Lashtail Raptor.",
    ["T"] = "Mistrzostwo W Polowaniu Na Raptory",
  },
  [196] = {
    ["D"] = "Zobaczmy jak poradzisz sobie z tym zadaniem. W tej dżungli znajdują się pewne szczególnie przebiegłe raptory. Nazywamy je Jungle Stalkerami. Są o wiele trudniejsze do wytropienia i zabicia, niż inne rasy, na które już $gpolowałeś:polowałaś;. Zabij 10 Jungle Stalker, a dam Ci cynk na temat pewnego interesującego polowania.",
    ["O"] = "Hemet Nesingwary Jr. chce, $gbyś zabił:byś zabiła; 10 Jungle Stalker.",
    ["T"] = "Mistrzostwo W Polowaniu Na Raptory",
  },
  [197] = {
    ["D"] = "Ponieważ udowodniłeś swoją przebojowość w dżungli, pozwól mi opowiedzieć o morderczym raptorze, którego nie dałem rady zabić. Ajack nazywa tego podstępnego raptora imieniem Tethis.$B$BJeśli chcesz udowodnić, że jesteś prawdziwym mistrzem, zabij Tethisa i przynieś mi jego szpon. Byłby to wyczyn, którego żaden inny łowca grubego zwierza nie osiągnął.",
    ["O"] = "Hemet Nesingwary Jr. chce, abyś zabił Tethisa, nieuchwytnego, niebezpiecznego raptora w Stranglethorn.",
    ["T"] = "Mistrzostwo w polowaniu",
  },
  [198] = {
    ["D"] = "Hmm. Tak, mam dla ciebie coś do zrobienia. Lieutenant Doren i jego ludzie na północy potrzebują od nas regularnych zapasów.$B$BNie zostały dostarczone z powodu atakujących trolli i będę potrzebował kogoś kto to zrobi. Obóz Dorena leży na północny-zachód od drogi, przy wejściu do Stranglethorn z Duskwood. Dostarcz te zasoby do Private Thorsen, jeśli nie będzie go w obozie, to będzie on patrolował południe. Zajmie się nimi.$B$BPamiętaj, jeśli zawiedziesz, będziesz musiał to naprawić .",
    ["O"] = "Dostarcz Miscellaneous Goblin Supplies do Private Thorsen.",
    ["T"] = "Dostawy do Private Thorsen",
  },
  [199] = {
    ["D"] = "Weź tę próbkę o dziwnym zapachu.",
    ["O"] = "Wróć do głównego inżyniera Hinderweira i pokaż mu znaleziony trop.",
    ["T"] = "Nadciąga mroczne zagrożenie",
  },
  [200] = {
    ["D"] = "Jeśli Kurzen zna tajemnicę Thorsena, oznacza to, że mamy wśród nas szpiega. Musimy ustalić, jak wyciekły te informacje.$B$BKontaktem Thorsena w obozie Kurzena był Bukmacher Herod. Herod jest oficerem logistycznym Kurzena i wie wszystko o tym, co dzieje się w obozie. Gdybyś mógł odnaleźć notatki lub zapiski Heroda, może udałoby się nam odkryć, w jaki sposób Thorsen został zdemaskowany.$B$BKiedy jeszcze służyliśmy u Kurzena, biuro Bukmachera znajdowało się na wyższym piętrze jedynego dwukondygnacyjnego budynku w obozie. Jego zapiski prawdopodobnie nadal tam są.",
    ["O"] = "Znajdź Bookie Herod\'s Records.",
    ["T"] = "Bukmacher Herod",
  },
  [201] = {
    ["D"] = "Dostałem raport o grupie łowców, którzy rozstawili obóz w górę rzeki od obozu górniczego Venture Company nad Jeziorem Nazferiti. Cóż, normalnie bym się tym nie przejmował, ale słyszałem niewyobrażalną wieść - mianowicie: jednym z tamtejszych łowców jest Hemet Nesingwary! On z pewnością ma szerokie koneksje, jeśli łapiesz, o co mi chodzi, a ostrożności nigdy za wiele.$B$BMoże przejdziesz się do obozu, $N, i zobaczysz, co się tam dzieje?",
    ["O"] = "Znajdź obóz myśliwych i donieś Krazekowi w Booty Bay o jego położeniu.",
    ["T"] = "Zbadaj obóz",
  },
  [202] = {
    ["D"] = "Wielokrotnie już dowiodłeś swych umiejętności, a pomysłowością możesz rywalizować z samym Kurzenem. Możesz ocalić naszą rebelię... jeśli jesteś w stanie przeciwstawić się Kurzenowi i zwyciężyć!$B$BDowodzi on swoimi ludźmi z głębi Stockpile. Musisz wejść do tej jaskini, stawić czoła jego obrońcom, a następnie Kurzenowi i jego dowódcom.$B$BŻegnaj, $N. Moja nadzieja, a także los moich ludzi, jest w twoich rękach.",
    ["O"] = "Zabij 6 Kurzen Elite, 4 Kurzen Subchiefs i dostarcz Głowę Kurzena do Porucznika Dorena do Rebel Camp.",
    ["T"] = "Pułkownik Kurzen",
  },
  [203] = {
    ["D"] = "Toczymy z góry przegraną walkę z Colonel Kurzenem. Jest on nie tylko błyskotliwym taktykiem; ma nad nami jeszcze liczebną przewagę, co najmniej dziesięciokrotną! By przeżyć, musimy zastosować przeciw niemu jego własną technikę walki z ukrycia.$B$BDostań się do jego obozu na wschód stąd i wybij jego ludzi. Zabij wielu z nich. I zniknij, nim dopadną cię posiłki.",
    ["O"] = "Zabij 15 Kurzen Jungle Fighters.$B$BWróć do Sergeant Yohwa w Rebel Camp.",
    ["T"] = "Drugie powstanie",
  },
  [204] = {
    ["D"] = "By mieć szansę przeciwko Kurzenowi, musimy zneutralizować jego lecznicze wsparcie. Zgromadził wokół siebie dużą liczbę Medyków, którzy leczą jego ludzi za pomocą Lekarstw z Dżungli, zaś naszych trują dzięki Wyciągowi z Jadowitej Paproci.$B$BPotrzebujemy tych leków, by leczyć własnych ludzi, oraz próbki tego wyciągu do badań nad odtrutką. Poszukaj tych substancji w Kurzen Compound - Medycy powinni mieć lekarstwa, zaś wyciąg prawdopodobnie przechowywany jest w jakiejś skrzyni z zaopatrzeniem.",
    ["O"] = "Przynieś 7 Jungle Remedies and 1 Venom Fern Extract do Sergeant Yohwa w Rebel Camp.",
    ["T"] = "Złe lekarstwo",
  },
  [205] = {
    ["D"] = "Podczas, gdy ja będę studiował legendy, które mi dostarczyłeś, zajmij się gromadzeniem narzędzi złej magii trolli. Wkrocz na terytorium szczepu Skullsplitter, drugiego plemienia z dalekiego południa, i zdobądź Skullsplitter Fetishes od ich Szamanów i Mistyków.",
    ["O"] = "Przynieś 4 Skullsplitter Fetishes braku Nimetz z Obozu Rebeliantów.",
    ["T"] = "Uroki Trolli",
  },
  [206] = {
    ["D"] = "Kurzen może nie żyć, jednak... przyczyna, która pchnęła go ku złu, wciąż istnieje! Dzięki moim badaniom odkryłem, co następuje: Mag Ogrów - Mai\'Zoth - zamieszkuje Ogre Mound we wschodnich górach Stranglethorn. Powiadają, iż stosuje on magię kontrolującą umysły i jestem przekonany, że to on skaził umysł Kurzena.$B$BJeśli pozwoli się żyć Mai\'Zothowi, jego zło może wywrzeć wpływ na innych, a nawet stać się przyczyną pojawienia się następnego Kurzena.$B$BZabij go i przynieś mi jego Mind\'s Eye, artefakt, dzięki któremu deprawuje innych.",
    ["O"] = "Przynieś Mind\'s Eye Bratu Nimetzowi z Rebel Camp.",
    ["T"] = "Mai\'zoth",
  },
  [207] = {
    ["D"] = "Pułownik Kurzen był kiedyś dostojnym, szanowanym mężczyzną- muszę znaleźć przyczynę przez którą stoczył się w nieprawość. Może znajdować się pod wpłwem uroków trolli. Aby to potwierdzić muszę przestudiować część ich legend.$B$BW rozsianych po Stranglethorn ruinach trolli znajdują się cztery tablice. Muszę dowiedzieć się co jest na nich zapisane! Przepisz znajdująe się na tablicach znaki i przynieś je do mnie.$B$BPierwsza tablica znajduje się w Bal\'lal Ruins, druga w Vile Reef, a trzecia i czwarta w Ruins of Zul\'Kunda.",
    ["O"] = "Odnajdź cztery tablice i spisz dla Brata Nimetza zawarte na nich legendy.",
    ["T"] = "Tajemnica Kurzena",
  },
  [208] = {
    ["D"] = "$N, jesteś łowcą wartym naszego towarzystwa. Od pól bitewnych Lordaeronu aż po najgłębszą dżunglę rzadko byłem świadkiem takiej sprawności we władaniu bronią, jaką ty $gzademonstrowałeś:zademonstrowałaś;.$B$B$gZabiłeś:Zabiłaś; straszliwego Sin\'Dalla, nieuchwytną Bag\'therę oraz zdradzieckiego Tethisa. Jednak prawdziwym trofeum jest głowa Króla Bangalasha. Ten biały tygrys jest powodem, dla którego tu jestem. Od jakiegoś czasu mam na niego oko. Zabij Króla Bangalasha, a będzie to dowodem, że nie ustępujesz nikomu w swej biegłości łowieckiej.",
    ["O"] = "Hemet Nesingwary Jr. chce, byś $gprzyniósł:przyniosła; mu głowę Króla Bangalasha, wielkiego białego tygrysa.",
    ["T"] = "Łowy na grubego zwierza",
  },
  [209] = {
    ["D"] = "Zabicie dostatecznej ilości tygrysów, by utrzymać eksport kłów tygrysa na wyspy Mórz Południowych, to kosztowne i trudne zajęcie. Na szczęście rozwinęliśmy technologię pozwalającą nam przekształcić zwykłe rogo-podobne obiekty w niemożliwe do odróżnienia falsyfikaty.$B$BNajodpowiedniejszymi do tego celu przedmiotami, ku naszemu zdumieniu, okazały się kły trolli Skullsplitter.$B$BHej, zanim coś powiesz, czego oczy nabywcy nie widzą, tego jego sercu nie żal, mam rację? Przynieś mi dużą ilość kłów, byśmy mogli przygotować miesięczny transport.",
    ["O"] = "Zdobądź 18 Skullsplitter Tusks i dostarcz je Kebokowi.",
    ["T"] = "Kły Łupaczy Czaszek",
  },
  [210] = {
    ["D"] = "Odwalam większość kucharskiej roboty w obozie. Było jej naprawdę mnóstwo do czasu, gdy kupiłem mechaniczny garnek do gotowania u goblińskiego sprzedawcy w Booty Bay. Jest wspaniały! Oszczędzał mi niezliczonych godzin pracy... dopóki się nie popsuł!$B$BMógłbyś zanieść dla mnie garnek z powrotem do tego goblina, by mógł go naprawić? Nazywa się Krazek.",
    ["O"] = "Przynieś Krazek\'s Crock Pot goblinowi Krazekowi.",
    ["T"] = "Kucharstwo Krazeka",
  },
  [211] = {
    ["D"] = "Więc cóż, nadszedł czas, by zaatakować Andorhal i przepędzić władającego nim lisza! $B$BRuiny miasta to miejsce, z którego lisz - Araj the Summoner - sprawuje władzę. Strzegą go liczne oddziały Plagi, otaczające szczątki dawnego centrum, a jego osobista świta strażników budzi niesamowitą grozę. Będziesz potrzebował wielu sprzymierzeńców, by mieć choćby szansę spotkania się z nim twarzą w twarz. $B$B$N, zniszcz Araja i przynieś mi kryształ z jego filakterii jako dowód!",
    ["O"] = "Przynieś Araj\'s Phylactery Shard do Commander Ashlam Valorfist z Chillwind Camp, Western Plaguelands.",
    ["T"] = "Więc cóż, Andorhal",
  },
  [212] = {
    ["D"] = "Jedną z mych najbardziej znanych potraw jest Mrożony Bazyliszek w Limonkowym Sosie. Ale problem polega na tym, że... to mięso nie zachowuje świeżości, a ja muszę przyrządzić danie na dziś wieczór, na urodziny szlachcica!$B$BWięc gdybyś $gmógł:mogła; prędko dostarczyć mi udziec ze świeżo zabitego bazyliszka będę ci dłużny królewską ucztę!$B$BWiadomo, że bazyliszki włóczą się na wydmach w północno-zachodniej części Stranglethorn, więc masz sporo drogi przed sobą. Spiesz się!",
    ["O"] = "Zabij Cold Eye Basilisk, zdobądź jego Chilled Basilisk Haunch i zanieś go do Angusa Sterna, do Blue Recluse.",
    ["T"] = "Posiłek podawany na zimno",
  },
  [213] = {
    ["D"] = "Zrobił to tym razem! Nie dość, że Gelriz przepędził magnatów wyznaczonych przez książąt handlu, to próbuje jeszcze przeszkadzać jednemu z najsławniejszych piratów! $B$BRevilgaz tego nie zniesie; powiedział mi, żebym rozwiązał ten problem na swój sposób.$B$BMój sposób? Kradzież. Geolodzy Venture Co. z okolic Lake Nazferiti są bardzo zainteresowani tymi dziwnymi, niebieskimi kryształami, które znajdują w swoich kopalniach. Odbierz im i przynieś do mnie próbki tych kamieni; nie obchodzi mnie, co będziesz musiał zrobić, by je zdobyć.",
    ["O"] = "Odzyskaj 8 Tumbled Crystals i oddaj je Kebokowi z Booty Bay.",
    ["T"] = "Wrogie przejęcie",
  },
  [214] = {
    ["D"] = "Nie jest tajemnicą, że znakiem rozpoznawczym Gangu Defiasów są ich czerwone bandany. Ale dowiedzieliśmy się, że materiał, z którego jest zrobiona bandana, zależy od stopnia członka bandy.$B$BTo powiedziawszy, chcę, byś wyeliminował tylu wysoko postawionych Defiasów, ilu zdołasz. Najwyżsi rangą członkowie z całą pewnością będą znajdować się w tajnej kryjówce VanCleefa. Kiedy skończysz, przynieś mi 10 Red Silk Bandanas na dowód ich śmierci, a wynagrodzę cię. Powodzenia, $N.",
    ["O"] = "Scout Riell z Sentinel Hill Tower chce, byś przyniósł jej 10 Red Silk Bandanas.",
    ["T"] = "Czerwone jedwabne bandany",
  },
  [215] = {
    ["D"] = "Dzięki za ocalenie mnie, $N. Wiem, jak to wygląda, ale... pozwól wyjaśnić.$B$BDostałem rozkaz od Porucznika Dorena, by ponownie dołączyć do ludzi Kurzena, abym mógł ich szpiegować i dostarczać rebeliantom bezcenne informacje. To co tu widziałeś miało być moją szansą na zinfiltrowanie Kurzen\'s Compound. Myliłem się, i jeszcze raz dziękuję za uratowanie mnie.$B$BTo była ściśle tajna misja, więc nie wolno ci nikomu o tym mówić. Ale jeśli porozmawiasz z Dorenem, otrzymasz wyjaśnienia.",
    ["O"] = "Porozmawiaj z Lieutenantem Dorenem w Rebel Camp.",
    ["T"] = "Tajemnice dżungli",
  },
  [216] = {
    ["D"] = "Furbolgi Kolcogrzbiete zagrażają naszej ekspansji! Leżąca na wschód stąd wioska Kolcogrzbietów blokuje drogę pomiędzy nami, a posterunkiem Splintertree. Ta ścieżka pozwoli nam ominąć Astranaar; pozostawiona bez nadzoru stanie się dodatkową ścieżką ekspansji Przymierza.$B$B$N, nie wolno nam pozwolić... na przerwę na drodze ekspansji!$B$BZaatakuj wioskę Kolcogrzbietów i wyrżnij furbolgi. Damy ci wynagrodzenie za twe zadanie, ale co ważniejsze, wypełnisz swą powinność wobec Hordy!",
    ["O"] = "Zlikwiduj 8 Thistlefur Avengers i 8 Thistlefur Shaman; większość z nich mieszka na wschód od Zoram Strand w wiosce Thistlefur. Kiedy skończysz, wróć do Karanga Amkkara w Zoram\'gar Outpost, Ashenvale.",
    ["T"] = "Między skałą a Kolcogrzbietami",
  },
  [217] = {
    ["D"] = "$N, nasi zwiadowcy zidentyfikowali przywódcę niedawnego najazdu troggów. Wygląda na to, że na terenie Loch Modan dowodzi nimi niejaki Grawmug. Grawmug jest jednak silnie strzeżony. Dwoje spośród jego najlepszych strażników, Gnasher i Brawler, nigdy go nie odstępuje.$B$BJeśli czujesz się na siłach, $N, chciałbym, byś $gpoprowadził:poprowadziła; misję zabicia Grawmuga i jego dwóch zbirów. Po śmierci przywódcy troggów staniemy przed szansą na zepchnięcie tych potworów z powrotem pod ziemię.",
    ["O"] = "Zabij przywódcę troggów, Grawmuga, oraz jego strażników, Gnashera i Brawlera, potem zdaj raport kapitanowi Rugelfussowi z południowej wieży strażniczej.",
    ["T"] = "W obronie królewskich ziem",
  },
  [218] = {
    ["D"] = "Mój dziennik! Zabrali go do jaskini. Ten, który go miał... To było wielkie bydlę z dziwnymi znakami na skórze i twarzy. Nie przyjrzałem się mu dokładniej.$B$BMasz szczęśliwą rękę do trolli, może $gmógłbyś:mogłabyś; iść i odzyskać mój dziennik?",
    ["O"] = "Grelin Whitebeard chce, byś $gzabił:zabiła; Grik\'nir the Cold i $godzyskał:odzyskała; jego dziennik.",
    ["T"] = "Skradziony dziennik",
  },
  [219] = {
    ["D"] = "W końcu, przyjaciel Przymierza!$B$BProszę... pomóż...$B$BOstatnie co pamiętam to tych głupich orków pokonujących nasz oddział. Większość ludzi zginęła. Oberwałem potężnie w głowę i wszystko pochłonął mrok. Teraz jestem więziony w tej jaskini. Pomóż mi, jestem ciężko ranny.$B$BBędę potrzebował pomocy, aby przedostać się z powrotem do miasta... proszę... jesteś moją ostatnią nadzieją...",
    ["O"] = "Chroń kaprala Keeshana w jego drodze powrotnej przez Redridge.",
    ["T"] = "Zaginiony w akcji",
  },
  [220] = {
    ["D"] = "Nim Islen nagrodzi cię kolejnym totemem, będzie mieć dla ciebie jeszcze jedno zadanie. Fiolka wody, którą ci dałam, jest jego nieodłączną częścią.$B$BA teraz ruszaj odnaleźć Islen. Pewnego dnia znów się spotkamy.",
    ["O"] = "Przynieś Vial of Purest Water do Islen Waterseer mieszkającej w Barrens.",
    ["T"] = "Zew wody",
  },
  [221] = {
    ["D"] = "Pewnie zauważyłeś kilka większych wilkołaków włóczących się po lesie wraz z Shadow Weavers? Z tego, co wiemy, ci Dark Runners stanowią przeważającą część sił wilkołaków.$B$BZ mego stanowiska udało mi się dostrzec, że opanowały one Rotting Orchard na południowy zachód od miasta. Te wilkołaki są silniejsze od tych, z którymi ostatnio się zmierzyłeś.$B$BMiej się na baczności.",
    ["O"] = "Zabij 12 Nightbane Dark Runner dla Calora z Darkshire.",
    ["T"] = "Wilkołaki w puszczy",
  },
  [222] = {
    ["D"] = "Twoje poprzednie dokonania przekonały mnie, że jesteś gotowy podjąć się walki z najsilniejszymi z wilkołaków, od których roi się w lasach.$B$BZ wilkołaków, które się tutaj zadomowiły, Vile Fangs i Tainted Ones udowodniły, że są najbardziej niebezpieczne. Osiedliły się one w rejonie jaskiń i w kopalni na południu.$B$BMożesz nawet zobaczyć z oddali światło z ich ognisk...",
    ["O"] = "Zabij 8 Nightbane Vile Fang i 8 Nightbane Tainted One dla Calora z Darkshire.",
    ["T"] = "Wilkołaki w puszczy",
  },
  [223] = {
    ["D"] = "Proszę, $N. Zanieś tę wiadomość do Mistrza Carevina.$B$B<Szybko odrywa kawałek wyblakłego pergaminu i wręcza ci go.>$B$BJeszcze kilku takich jak ty, a będzie nas więcej niż Nocnej Straży! Być może wtedy uda nam się zakończyć sprawę, z którą dziś boryka się nasza garstka.",
    ["O"] = "Zanieś list Calora Jonathanowi Carevinowi.",
    ["T"] = "Wilkołaki w puszczy",
  },
  [224] = {
    ["D"] = "Musimy chronić jezioro, $N! Przy tak dużej ilości królewskich żołnierzy walczących dzielnie na odległych polach, przeciwnik zalewa nasze ojczyste ziemie. Troggi wyłaniają się z każdej szczeliny w ziemi! Ich plaga stanowi największe zagrożenie dla Ironforge. Te odrażające mutanty muszą zostać zniszczone!$B$B$gDzielny poszukiwaczu:Dzielna poszukiwaczko; przygód, potrzebujemy, abyś $gudał:udała; się na wyprawę i $gpozbył:pozbyła; się stanowionego przez troggi zagrożenia. Zabij po dziesięć troggów z każdego z dwóch rodzajów, a następnie zamelduj się tu z powrotem.",
    ["O"] = "Góral Cobbleflint z południowej wieży strażniczej chce, byś $gzabił:zabiła; 10 Stonesplinter Troggs i 10 Stonesplinter Scouts.",
    ["T"] = "W obronie królewskich ziem",
  },
  [225] = {
    ["D"] = "Na zniszczonym grobie widnieje krótki napis:$B$BMORGAN LADIMORE$B$B<Po dalszych oględzinach zauważasz, że ziemia nad grobem została niedawno poruszona i duża jej część uległa przemieszczeniu...>",
    ["O"] = "Porozmawiaj z Sirrą Von\'Indi z Darkshire.",
    ["T"] = "Zniszczony grób",
  },
  [226] = {
    ["D"] = "Svena i mnie czekają ciężkie dni z tym nekromantą na wschodzie i w ogóle. A ponieważ jesteśmy tu sami, musimy też sami polować, by mieć co jeść. Zdaje się, że za każdym razem, gdy wracam z mięsem do obozu, wygłodniałe i wściekłe wilki wychodzą z lasu, szukając kęsa. Szkoda nawet gadać, życie tu to niebezpieczna robota.$B$BAle gdybyś mógł uwolnić nas od kilku wilków, stałoby się łatwiejsze. Najczęściej grasują one na północ i na wschód stąd, w pobliżu rzeki.",
    ["O"] = "Zabij 12 Starving Dire Wolves i 8 Rabid Dire Wolves, a następnie wróć do Larsa w Sven\'s Camp u zachodniej granicy Duskwood.",
    ["T"] = "Wilki u naszych pięt",
  },
  [227] = {
    ["D"] = "<Przeszukuje półki w poszukuwaniu skórzanej książki>$B$BJeśli chcesz wiedzieć więcej, możesz zapytać Althea.",
    ["O"] = "Porozmawiaj z Commander Althea Ebonlocke w Darkshire.",
    ["T"] = "Morgan Ladimore",
  },
  [228] = {
    ["D"] = "Moi zwiadowcy powiedzieli mi, że Mor\'Ladim włóczy się po Duskwood, podążając dziwną, wijącą się trasą przez cmentarz. Pochowaliśmy go za domem na wzgórzu; wiesz, gdzie to jest?$B$BNie mogę nic zrobić, by ci pomóc, ale życzę ci powodzenia.",
    ["O"] = "Zabij Mor\'Ladima i zanieś jego czaszkę Dowódcy Althei Ebonlocke z Darkshire.",
    ["T"] = "Mor\'Ladim",
  },
  [229] = {
    ["D"] = "Powinnam powiedzieć ci to wcześniej...$B$BJak to powiedzieć...$B$BMorgan mógł wierzyć, że cała jego rodzina nie żyje, ale tak naprawdę jego córka, Sarah Ladimore, jest teraz Strażnikiem. Zawsze kłopotały ją... okoliczności... związane ze śmiercią jej ojca. Może mógłbyś zanieść jej wiadomość...",
    ["O"] = "Porozmawiaj ze Strażniczką Sarah Ladimore w Darkshire.",
    ["T"] = "Córka, która przeżyła",
  },
  [230] = {
    ["D"] = "Kopiąc w kopczyku ziemi, znajdujesz małą, zabrudzoną książkę.$B$BNie ma ona tytułu, ale... zawiera informacje, które Sven chciałby poznać.",
    ["O"] = "Przynieś Svenowi książkę z jego farmy.",
    ["T"] = "Obóz Svena",
  },
  [231] = {
    ["D"] = "Masz, weź to i połóż na jego grobie. Może... jakoś dowie się, że ze mną wszystko w porządku i że nikt z nas nie wini go za to, co się stało.$B$B<Kiedy zsuwa pierścień ze swej prawej dłoni i wciska go w twoją, w jej oczach błyszczą łzy.>$B$BI... dziękuję ci, $N.",
    ["O"] = "Zabierz pierścień Sarah Ladimore na grób Morgana Ladimore.",
    ["T"] = "Miłość córki",
  },
  [232] = {
    ["D"] = "Królewskie Stowarzyszenie Aptekarzy potrzebuje twojej pomocy. Słuchaj uważnie, a oboje możemy zyskać na moim planie.$B$BAptekarz Keever, którego znajdziesz w następnym pomieszczeniu jest być może nieco... stuknięty... ale jego badania mogą odnieść sukces, jeśli byłyby kontynuowane przez bystrego naukowca. Szczęśliwie, jestem takim właśnie naukowcem. Pragnę, byś $gzaniósł:zaniosła; to zlecenie zakupu do Alessandro Luca, właściciela \"Blue Moon Odds and Ends\"; otrzymasz od niego zestaw testowy. Przyjdź z nim do mnie, a ja szczegółowo przedstawię ci twoje zadanie.",
    ["O"] = "Zabierz to zlecenie zakupu do Alessandro Luca w Undercity.",
    ["T"] = "Sprawa dla aptekarki Zingi",
  },
  [233] = {
    ["D"] = "Hmm, nie sądzę, $gchłopcze, byś chciał:młoda damo, byś chciała; wyświadczyć mi przysługę? Stos listów dotarł dziś przez przełęcz, ale nie mam czasu, by przekazać je dalej.$B$BWszystkie zaadresowano do Talina Keeneye\'a. Znajdziesz go przy drodze na zachód stąd. Rozbił obóz obok zamarzniętego jeziora.$B$BCo na to powiesz?",
    ["O"] = "Dostarcz paczkę listów do Talina Keeneye\'a.",
    ["T"] = "Dostarczenie listów w Dolinie Coldridge",
  },
  [234] = {
    ["D"] = "Jeśli dobrze pamiętam, obóz Grelina znajduje się przy drodze, na południowy wschód stad. Bez wątpienia niecierpliwie czeka na ten list.",
    ["O"] = "Dostarcz list do Grelina Whitebearda.",
    ["T"] = "Dostarczenie listów w Dolinie Coldridge",
  },
  [235] = {
    ["D"] = "Uwaga, młodzi poszukiwacze przygód! Knieje Ashenvale czekają na was!$B$BHorda zajęła silną pozycję na ziemiach na północ od Barrens. Nasze dwa posterunki – Posterunek Splintertree i Placówka Wybrzeża Zoram – pragną przynieść chwałę Hordzie! Pragnący dowieść swych umiejętności winni zasięgnąć tam informacji. Uwaga: Senani Thunderheart z Posterunku Splintertree , dokładnie na północ od Barrens, szuka śmiałków chętnych wziąć udział w wielkim polowaniu w Ashenvale!",
    ["O"] = "Porozmawiaj z Senani Thunderheart w Splintertree Post, Ashenvale.",
    ["T"] = "Polowanie w Ashenvale",
  },
  [236] = {
    ["D"] = "A few weeks ago, I dispatched Watcher Callahan and a few others to the northern border of Duskwood to deal with the wolf infestation. I haven\'t heard word from him for quite some time. If he followed my instructions, he\'ll be camped out on the road north from Darkshire. $B$BIf it\'s on your way, please check up on him and inform him that I am awaiting a progress report from him.",
    ["O"] = "Speak with Watcher Callahan.",
    ["T"] = "Awaiting Word",
  },
  [237] = {
    ["D"] = "Góral Cobbleflint nie miał nic oprócz dobrych rzeczy do powiedzenia o tobie, $R7. Z tego powodu ja powierzam tobie najważniejszą misję. Musimy utrzymywać presję na atakujących fortecę troggach, dopóki nasi krasnoludzccy bracia nie powrócą z frontu Przymierza.$B$BPójdź więc na południowe wzgórza i zabij dziesięciu łupaczy czaszek i dziesięciu wieszczy. Twój atak da nam trochę czasu. Zgłoś się z powrotem kiedy ukończysz misję.",
    ["O"] = "Góral Gravelgaw w południowej wieży obronnej chce, żebyś $gzabił:zabiła; 10 Stonesplinter Skullthumpers i 10 Stonesplinter Seers, a następnie byś $gzgłosił:zgłosiła; się z powrotem do niego.",
    ["T"] = "W obronie ziem króla",
  },
  [238] = {
    ["D"] = "Zestaw jest gotów, $N. Bez wątpienia aptekarka Zinge będzie chciała dostać go tak szybko, jak to możliwe. Zanieś jej go bez zwłoki i powiedz, że koszt zestawu dopiszę do rachunku Stowarzyszenia. Proszę, przekaż jej również moje najgorętsze pozdrowienia.$B$BNo co, nie stój tak. Taki jest los zwykłego posłańca, czyż nie?",
    ["O"] = "Przynieś Field Sampling Kit aptekarce Zinge z Undercity.",
    ["T"] = "Zlecenie od aptekarki Zinge",
  },
  [239] = {
    ["D"] = "Garnizon z naszej zachodniej granicy przesłał wiadomość o rosnącej liczbie gnolli i aktywności złodziei. Poproszono nas o przysłanie posiłków ze Stormwind... ale my po prostu nie mamy kogo wysłać!$B$BGdybyś $gchciał:chciała; pomóc, chętnie skorzystamy. Udaj się do Garnizonu Zachodniego Strumyka, porozmawiaj z deputowanym Rainerem i dowiedz się, jakiej pomocy potrzebuje.$B$BGarnizon znajduje się przy drodze na zachód. Kiedy przejdziesz przez most nad małym strumykiem, znajdziesz go po swej prawej stronie.",
    ["O"] = "Udaj się do Westbrook Garrison i porozmawiaj z deputowanym Rainerem.",
    ["T"] = "Garnizon nad Zachodnim Strumieniem potrzebuje pomocy!",
  },
  [240] = {
    ["D"] = "I gotowe - <Krabowe> Ciastka a\'la Grual!",
    ["O"] = "Wróć do Trzęsiaka z Dusky Crab Cakes.",
    ["T"] = "Powrót do Trzęsiaka",
  },
  [241] = {
    ["D"] = "Description",
    ["O"] = "Log",
    ["T"] = "<TEST> HEY MISTER WILSON!",
  },
  [242] = {
    ["D"] = "Throm-ka, $c. There is no time to waste. Orcs of the Dragonmaw clan have fortified themselves in the valley to the south of here. $b$bThey have denied the Warchief\'s mandate, leaving us only one course of action. We will eliminate them so that they will no longer dirty the name of the Horde.",
    ["O"] = "Kill 8 Dragonmaw Raiders, 3 Dragonmaw Bonewarders, and a Dragonmaw Battlemaster.",
    ["T"] = "<UNUSED>",
  },
  [243] = {
    ["D"] = "Skierujesz się na pustynię Tanaris, gdzie zbadasz tkanki miejscowych bazyliszków, skorpionów i hien. Zdobądź próbki tkanek i zbadaj je pozyskanym zestawem testującym; spodziewaj się utraty wielu próbek. Potrzebuję ośmiu zdatnych do użycia próbek z każdego rodzaju tych stworzeń.$B$BCo więcej, gobliny z Gadgetzanu posiadają źródło energii, którego należy używać przy tak zmodyfikowanym zestawie testującym. Porozmawiaj z Chief Engineer Bilgewhizzle i nabądź jedno z nich.$B$BWróć do mnie, gdy z powodzeniem zakończysz misję.",
    ["O"] = "Porozmawiaj z Chief Engineer Bilgewhizzle z Gadgetzanu w sprawie zdobycia źródła energii do zestawu testującego.",
    ["T"] = "W warunkach polowych",
  },
  [244] = {
    ["D"] = "Witaj, $C. Zostałem wyznaczony do patrolowania tego odcinka drogi. Chociaż jest ona jak na razie bezpieczna, widziałem obozowiska gnolli na wschód i północ stąd.$B$BLakeshire musi wiedzieć o gromadzących się siłach gnolli! Zgłoś się do zastępcy Feldona w Lakeshire i opowiedz mu o gnollach. Wykonaj polecenie, a jestem pewien, że wypłaci ci żołd zwiadowcy.$B$BFeldon zwykle dogląda obszaru na południe od mostu do Lakeshire.",
    ["O"] = "Złóż sprawozdanie zastępcy Feldonowi.",
    ["T"] = "Gnolle szabrownicy",
  },
  [245] = {
    ["D"] = "Witaj, $C. Chyba widziałeś już pająki, które opanowały zachodnie pogranicze? Ta ośmionożna groźba to zbyt wiele na nasze możliwości, a Dowódca nie ma wystarczającej ilości ludzi, aby wysłać posiłki z Darkshire.$B$BŹle się czuję, prosząc cię o to, lecz wyglądasz na zdolnego podołać tym bestiom. Nie mogę obiecać niczego drogocennego, ale mogę cię nagrodzić, jeśli tylko pomożesz wytępić to ohydne robactwo.$B$BOch, i drobna rada. Unikaj ich jadu, jeśli tylko będziesz mógł.",
    ["O"] = "Zabij 15 Pygmy Venom Web Spiders i zgłoś się do Watchera Doddsa z Duskwood.",
    ["T"] = "Ośmionożna groźba",
  },
  [246] = {
    ["D"] = "Nie mamy dość ludzi, ale coś trzeba zrobić odnośnie gnolli, o których $gwspomniałaś:wspominałeś;.$B$BZbadaj południowe Redridge w poszukiwaniu gnolli. Przepędź je, zabij te, które możesz, i zdaj mi raport o liczbie zgładzonych i zagrożeniu, jakie stanowią. Ich obozy znajdziesz wzdłuż całej południowej drogi przez Redridge.$B$BZrób to dla armii Stormwind, $N, a zostaniesz $gnagrodzony:nagrodzona;.",
    ["O"] = "Zabij 10 Redridge Mongrels i 6 Redridge Poachers, po czym zgłoś się do zastępcy Feldona w Lakeshire.",
    ["T"] = "Ocena zagrożenia",
  },
  [247] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Polowanie zakończone",
  },
  [248] = {
    ["D"] = "Obserwowałem Wieżę Ilgalara i odkryłem, że Morganth pozostaje w konflikcie z orkami z Twierdzy Stonewatch. Nie znam powodu ich sporu, lecz możesz mi pomóc w rozwiązaniu tej zagadki.$B$BWeź kolejny Glif Azory i udaj się na szczyt nienaruszonej wieży obserwacyjnej obok Twierdzy Stonewatch.$B$BZnajdź pojemnik, odpowiedni do umieszczenia w nim glifu. Skrzynka lub słój - miejsce, w którym glif pozostanie niezauważony - posłuży memu celowi.",
    ["O"] = "Wespnij się na nienaruszoną wieżę obserwacyjną obok Stonewatch Keep.$B$BZnajdź pojemnik, odpowiedni do umieszczenia w nim Glyph of Azora.",
    ["T"] = "Bliższe obserwacje",
  },
  [249] = {
    ["D"] = "Po długich obserwacjach odkryłem plany Morgantha.$B$BPoszukuje on Kosy Elune... i być może już ją odnalazł! Jeśli mu się udało, Redridge Mountains i królestwo Stormwind wkrótce poczują jego mroczną moc.$B$BNie jestem przygotowany do starcia z Morganthem, ale boję się, że musi on zostać natychmiast pokonany. Dlatego musisz dostać się do Wieży Ilgalara i zmierzyć się z Morganthem.$B$BPokonaj go i dostarcz mi jego Wisior Cienia. Dokonaj tego, a królestwo będzie ci dłużne.",
    ["O"] = "Pokonaj Morgantha.$B$BDostarcz jego Pendant of Shadow do Theocritusa z Tower of Azora w Elwynn Forest.",
    ["T"] = "Morganth",
  },
  [250] = {
    ["D"] = "Dzięki niebiosom ktoś martwi się o dobry stan tamy. Najpierw zniszczenie Przęsła Thandol, a następnie grabież Dun Modr! Nie mam wątpliwości, że tama będzie następnym celem Czarnorytnych. Większość tutejszej ochrony została przeniesiona na front Przymierza, łącznie z moim czołowym inspektorem.$B$BDlatego cię potrzebuję, $N. Zauważyłem kilku saperów Czarnorytnych kręcących się niedaleko wschodniego podjazdu tamy. Zbadaj ten rejon i przynieś mi jakąś wskazówkę.",
    ["O"] = "Zbadaj rejon w pobliżu wschodniego podjazdu na tamę i dostarcz do głównego inżyniera Hinderweira wskazówkę, która mogłaby ujawnić plany Czarnorytnych.",
    ["T"] = "Nadciąga mroczne zagrożenie",
  },
  [251] = {
    ["D"] = "Zanieś list, który mi dałeś, Sirze Von\'Indi\'emu. Jest on biegły w językach i starożytnej sztuce - jeśli ktokolwiek potrafi przetłumaczyć tę wiadomość, to jedynie on.",
    ["O"] = "Zanieś List do Ella Sirza Von\'Indi\'emu.",
    ["T"] = "Przetłumacz notatkę Abercrombiego",
  },
  [252] = {
    ["D"] = "A niech mnie! Jeśli to, co napisano na tej kartce, jest prawdą, Abercrombie dokonał czegoś... niewyobrażalnego.$B$BLepiej zanieś przetłumaczoną notkę z powrotem do Ella.$B$BI zrób to szybko, gdyż obawiam się, że zagłada zmierza już do naszego miasta...",
    ["O"] = "Dostarcz Translated Letter do Lorda Ella Ebonlocke\'a.",
    ["T"] = "Tłumaczenie dla Ella",
  },
  [253] = {
    ["D"] = "Embalmer to imię wzięte z jednej z dziecięcych opowieści. Był dobrotliwym alchemikiem, lecz po śmierci swej żony Elizy oszalał. Aby ją odzyskać, przy pomocy czarnej magii umieścił własne serce w piersi zmarłej małżonki.$B$BTo wskrzesiło Elizę... przeklinając ją głodem ludzkiego mięsa i zmuszając Embalmera do pochowania jej.$B$BJego serce to jego moc. Odnajdź grób jego żony, odzyskaj serce i wciąż bijące przynieś do mnie. Dokonaj tego, a jego moc zostanie ostatecznie zniszczona.",
    ["O"] = "Znajdź grób Elizy. Odzyskaj od niej Embalmer\'s Heart i wróć z nim do Ello Ebonlocke\'a.",
    ["T"] = "Oblubienica Balsamisty",
  },
  [254] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Przekopując ziemię",
  },
  [255] = {
    ["D"] = "Czekałem dwa miesiące, by usłyszeć, że Ironforge wspomoże naszą obronę swymi oddziałami, lecz przybędą one za kolejne dwa miesiące! Nie dość, że nasze miasto pozostaje bez ochrony, to jeszcze wykopaliska i tama - tama! - również są bezbronne wobec ataków.$B$BWygląda na to, że nie mam wyboru. Muszę zatrudnić najemników.$B$BA co z tobą? Wyglądasz na $grasowego:rasową; $C. Grupa ogrów założyła obóz na północny wschód od jeziora. Być może uda ci się wynająć jeszcze kogoś i pomóc usunąć to zagrożenie dla naszego miasta?",
    ["O"] = "Sędzia Bluntnose z Thelsamaru wynajął cię do zabicia 4 Mo\'grosh Ogres, 4 Mo\'grosh Brutes i 4 Mo\'grosh Enforcers.",
    ["T"] = "Najemnicy",
  },
  [256] = {
    ["D"] = "List gończy wydany z rozkazu sędziego Thelsamaru:$B$BWyznacza się nagrodę za głowę ogra imieniem Chok\'sul, uważanego za przywódcę i koordynatora ataków na miasto Thelsamar, tamę Stonewrought oraz teren wykopalisk. Technika dowolna.$B$BWynagrodzenie pieniężne zostanie wypłacone po okazaniu dowodu śmierci ogra sędziemu.$B$BChok\'sul był ostatnio widziany w obozowisku ogrów w północno-wschodniej części Loch Modan.",
    ["O"] = "Zabij Chok\'sula i przynieś jego głowę sędziemu Bluntnose\'owi w Thelsamarze.",
    ["T"] = "POSZUKIWANY: Chok\'sul",
  },
  [257] = {
    ["D"] = "Myślisz, że możesz się mierzyć z legendą, Darylem Odważnym, co? Zdecydowanie wątpię! Oczywiście, bardzo zachęcam do próby. Oto wyzwanie, które, jak się przekonasz, jest ponad twoje siły, toteż nie bądź $gprzybity:przybita;, jeśli mu nie podołasz.$B$BStado Myszołowów zagnieździło się tutaj, w Loch Modan. Może $gspróbowałbyś:spróbowałabyś; ustrzelić kilka tych bestii? Wiesz co, jeśli sprostasz memu zadaniu w ciągu piętnastu minut, odstąpię ci swój łuk lub strzelbę.$B$B<Spogląda na ciebie pogardliwie.>$B$BWygląda na to, że ty w każdym razie nie masz nic do stracenia.",
    ["O"] = "Zgładź 6 Mountain Buzzards i wróć do Daryla the Youngling w Farstrider Lodge w przeciągu 15 minut.",
    ["T"] = "Przechwałki łowieckie",
  },
  [258] = {
    ["D"] = "$N, co? Widzę, że kipisz od dumy po przejściu pierwszego sprawdzianu, co? Jak już powiedziałem, nie był to wielki wyczyn.$B$B$gPowinieneś:Powinnaś; sprawdzić swe umiejętności w polowaniu na dziki. Wierz mi, to nie jest to samo, co polowanie na dziki z Doliny Coldridge, dlatego lepiej się do niego przyłóż. Tym razem daję ci jedynie dwanaście minut.$B$BNie czuj się $gzrażony:zrażona; niepowodzeniem. Jeśli ci się powiedzie, oddam ci koszulę zdjętą z mych własnych pleców!$B$B$gSłyszałeś:Słyszałaś; już opowieść o mojej sławnej bliźnie? Nie? Zdarzyło się to dwa lata temu...",
    ["O"] = "Zabij 5 Elder Mountain Boars i wróć do Daryla the Youngling z Farstrider Lodge w przeciągu 12 minut.",
    ["T"] = "Wyzwanie dla łowcy",
  },
  [259] = {
    ["D"] = "Hello there, $n. I\'ve heard much about your exploits, and must say I\'m honored to meet you. I don\'t suppose you\'ve heard the story of Ol\' Kelt? Ah, well, Ol\' Kelt--Kelt Thomasin, that is--was once considered one of the finest hunters in all the realm. There wasn\'t much he hadn\'t done, but then, one day, he became obsessed with an ancient story... a myth, really. Well, as the stories go, a huge threshadon lives in the waters of the lake. Hogwash, if you ask me. If you\'re interested, you might talk to Kelt.",
    ["O"] = "Talk to Kelt Thomasin.",
    ["T"] = "<UNUSED>",
  },
  [260] = {
    ["D"] = "Now, this will no doubt convince you that I am, as they say--and don\'t deny it, I know what they say--of an addled mind, obsessed with an impossible legend. An old dwarven legend, it is, of an enormous monster that lives in the depths of the Loch. I spent a good bit of my life trying to track it down, and I believe I got close, but alas, I fear old age has caught up to me. If you would like to try hunting down the monster of the Loch, bring me some treshadon teeth and claws.$B$B<He smiles mysteriously.>",
    ["O"] = "Collect 5 Threshadon Teeth and 5 Threshadon Claws, then bring them to Kelt Thomasin.",
    ["T"] = "<UNUSED>",
  },
  [261] = {
    ["D"] = "Będę szczery. Toczymy wojnę z Plagą. Jest to zło, które zatruwa naszych ludzi i zanieczyszcza nasze ziemie. Musi zostać zatrzymane, zanim nas pochłonie i wciągnie nasz świat w cień. My, ze Szkarłatnej Krucjaty poprzysięgliśmy walczyć z Plagą ciałem i duszą.$B$BJeśli jesteś z nami, zgromadź odwagę i dowiedź lojalności - na południu, w Valley of Bones, zniszcz nieumarłych grabieżców z Desolace.$B$BDokonaj tego, a Krucjata cię przygarnie.",
    ["O"] = "Zniszcz 30 Undead Ravagers i wróć do Brata Antona w Nijel\'s Point.",
    ["T"] = "Podążając szkarłatną ścieżką",
  },
  [262] = {
    ["D"] = "Muszę wiedzieć, kogo widziałem czającego się w mroku, tamtej nocy, gdy moja rodzina została zamordowana!$B$BProszę $N, dowiodłeś już swej zaradności. Błagam, odnajdź właściciela tej cienistej sylwetki. Muszę wiedzieć, jakie sekrety przechowuje!$B$BNie posiadam wskazówek, których byś już nie znał, ale proszę - weź książkę, którą znalazłeś na mojej farmie. Może któryś z mieszkańców miasta skojarzy tę książkę z jej właścicielem.",
    ["O"] = "Weź książkę, którą znalazłaś na farmie Svena i pokaż ją ludziom z Darkshire.",
    ["T"] = "Cienista sylwetka",
  },
  [263] = {
    ["D"] = "Górale twierdzą, że jesteś dość $gdzielny i zdolny:dzielna i zdolna;, $N. Potrzebujemy tutaj takich ludzi, jak ty. Sytuacja z troggami wcale się nie poprawia. Rezerwy zostały wezwane na front i pozostaliśmy tutaj zdani na własne siły. Ale skoro teraz mamy tutaj $gdoświadczonego:doświadczoną; $C, zobaczmy, co możesz zrobić.$B$BIdź zabić dziesięciu szamanów i dziesięciu łamaczy kości. Zobaczmy, czy zasługujesz na swoją reputację, Zabójco Troggów.",
    ["O"] = "Góral Wallbang z południowej wieży strażniczej chce, abyś $gzabiła:zabił; 10 Stonesplinter Shaman i 10 Stonesplinter Bonesnappers.",
    ["T"] = "W obronie królewskich ziem",
  },
  [264] = {
    ["D"] = "Plugawa szumowina! Zostawił mnie dla swojej przeklętej krucjaty. Ponieważ \"Światłość jest najważniejszą bronią, jaką mamy, przeciwko zagrożeniu stanowionemu przez nieumarłych\".$B$BA co z dziećmi?! Co ze MNĄ?! Dzień po dniu cierpliwie go wyczekiwałam... zawsze mniej ważna od jego przeklętej służby!$B$BCóż, popatrz sobie, jak wygląda \"sprawiedliwość\", $N! On nie żyje, a ja jestem nosicielką tego, co tak bardzo chciał powstrzymać!$B$BZabierz ten śmieć i połóż go na jego grobowcu w Sepulcher. Nie chcę mieć z tym już nic wspólnego... ani z nim!",
    ["O"] = "Umieść Clarice\'s Pendant na Grobie Yuriva w Silverpine.",
    ["T"] = "Dopóki śmierć nas nie rozłączy",
  },
  [265] = {
    ["D"] = "Oddaję ci twoją książkę; życzę szczęścia w dalszych poszukiwaniach. Popytaj innych mieszkańców miasteczka, może będą mogli doradzić ci coś więcej.$B$BA, jeszcze coś - mimo, że autor książki nie jest mieszkańcem Darkshire, została ona tutaj zakupiona.",
    ["O"] = "Sprawdź, czy inni mieszczanie nie wiedzą czegoś o tajemniczej postaci.",
    ["T"] = "Trwają poszukiwania Cienistej Sylwetki",
  },
  [266] = {
    ["D"] = "Oto twoja książka; powodzenia w rozwiązaniu tej sprawy.$B$BMożesz popytać w karczmie. Jeśli osoba, której szukasz, była w mieście, są szanse, że właśnie tam ją widziano.",
    ["O"] = "Sprawdź karczmę w poszukiwaniu wskazówek na temat cienistej sylwetki.",
    ["T"] = "Dochodzenie w karczmie",
  },
  [267] = {
    ["D"] = "Możesz być, lub nie, $gświadomy:świadoma;, że zagrożenie ze strony troggów rozprzestrzenia się po ziemiach krasnoludów. Ponieważ rezerwy Ironforge skierowano na front Przymierza, zostaliśmy tu z ledwie cząstką sił obronnych, niezbędnych do zapewnienia bezpieczeństwa tym ziemiom. Mój pułk został przydzielony do pełnienia warty przy tutejszej bramie i nie możemy opuścić naszego posterunku z obawy przed inwazją.$B$BAle musimy przycisnąć te przeklęte troggi czające się w górach. Jeśli chcesz podjąć się tego zadania, przypuść na nie atak. Na dowód przynieś mi osiem kamiennych zębów troggów.",
    ["O"] = "Przynieś 8 Trogg Stone Teeth kapitanowi Rugelfussowi z południowej wieży strażniczej.",
    ["T"] = "Zagrożenie ze strony troggów",
  },
  [268] = {
    ["D"] = "Książka, którą znalazłeś, była ukończona tylko w połowie. Musiałem ją zostawić na farmie Svena, gdy tam uciekłem...$B$BMasz. Zanieś Svenowi mój kompletny dziennik. O wiele pełniej wyjaśnia, co zdarzyło się na farmie.$B$BChoć dziennik ten był moim jedynym towarzyszem w ciągu ostatnich tygodni, z chęcią oddam go, jeżeli to uratuje mnie przed spotkaniem twarzą w twarz ze Svenem i jego gniewem!",
    ["O"] = "Wróć do Svena z kompletnym dziennikiem Trzęsiaka.",
    ["T"] = "Wróć do Svena",
  },
  [269] = {
    ["D"] = "Udaj się do Stormwind i porozmawiaj z Biskupem Farthingiem z Cathedral of Light. Daj mu Dziennik Trzęsiaka i powiedz, że zamierzasz stawić czoła Morbentowi Felowi.$B$BChoć Stormwind porzuciło Darkshire, Farthing ma dobrą duszę i jest bardzo mądry. Może pomóc ci w misji ocalenia nas.$B$BTwoja misja jest niebezpieczna, lecz spiesz się. Z każdą mijającą godziną cienie Duskwood stają się coraz mroczniejsze.",
    ["O"] = "Zanieś Jitters\' Completed Journal do Bishop Farthinga ze Stormwind.",
    ["T"] = "Poszukując mądrości",
  },
  [270] = {
    ["D"] = "Wiele lat temu Trzecia Flota Kul\'Tiras zatonęła u wybrzeży The Wetlands w bezmiarze moczarów na północ od krasnoludzkiego królestwa Ironforge. Na pokładzie jednego ze statków znajdował się ładunek Lightforge Iron.$B$BTen metal jest tak cenny, gdyż wykonane z niego przedmioty rażą prawdziwą świętością. Jeśli masz stawić czoła Morbentowi Felowi, będziesz potrzebować właśnie takiej broni.$B$BUdaj się do Menethil Harbor i porozmawiaj z moim krasnoludzkim przyjacielem, Glorinem Steelbrowem. Jeśli można odnaleźć ten drogocenny metal, on będzie wiedział, gdzie szukać.",
    ["O"] = "Udaj się do Menethil Harbor w The Wetlands i porozmawiaj z Glorinem Steelbrowem.",
    ["T"] = "Potępiona flota",
  },
  [271] = {
    ["D"] = "Nie przypuszczam, $gbyłbyś zainteresowany:byłabyś zainteresowana; małą zemstą na Jego Zuchwałości? Z bólem przyznaję, że Daryl posiada pewne umiejętności.$B$BRok temu w Leśniczówce Farstrider polowano na olbrzymiego niedźwiedzia, ale żaden z myśliwych nie miał szczęścia go pokonać. Więc Daryl postanowił, że on spróbuje. Jedynym, co zyskał w zamian za swoje wysiłki, jest ta paskudna blizna nad jego okiem.$B$BZabij niedźwiedzia, a jestem pewna, że nawet Daryl w końcu zaniemówi.$B$BTego niedźwiedzia, Starego Sooty, można spotkać w okolicy jego leża, we wzgórzach nieopodal Thelsamaru.",
    ["O"] = "Zabij Ol\' Sooty, następnie pokaż swoje dzieło Darylowi Młodziakowi z Farstrider Lodge.",
    ["T"] = "Zemsta Vyrina",
  },
  [272] = {
    ["D"] = "Do twojej drugiej próby będziesz potrzebować dwóch części, które tworzą Wisior Foki. Pierwsza połówka pobiera moc ze zręczności aspektu morskiego lwa sunącego przez wodę; druga połowa pobiera moc z ogromnej wytrzymałości aspektu morskiego lwa. Druidzi nawiązują równo do obu tych cech, aby wcielić się w ich wodną formę.$B$BPorozmawiaj z mieszkańcami Moonglade, aby dowiedzieć się, gdzie mogą leżeć te części i przynieś je tutaj, aby połączyć je razem. Kiedy już to zrobisz, zanieś wisiorek do Dendrite Starblaze.",
    ["O"] = "Znajdź Half Pendant of Aquatic Agility i Half Pendant of Aquatic Endurance. Porozmawiaj z mieszkańcami Moonglade, aby znaleźć wskazówki, gdzie mogą być ukryte te przedmioty.$B$BStwórz Pendant of the Sea Lion z dwóch części wisiorka. Aby to zrobić, musisz być blisko Shrine of Remulos.$B$BPrzynieś złączony wisiorek do Dendrite Starblaze w wiosce Nighthaven w Moonglade.",
    ["T"] = "Próba Lwa Morskiego",
  },
  [273] = {
    ["D"] = "Jeszcze nie jest za późno, będę wdzięczny, jeśli pójdziesz poszukać Huldara. Nie może być daleko; nawet przy swej sile Miran i Saean nie mogą poruszać się zbyt szybko obładowani tymi beczkami.$B$BObrali normalną drogę do wykopalisk, opuszczając miasto z południowej strony i podążając wzdłuż brzegu jeziora.$B$BNie $gpowinieneś:powinnaś; mieć problemów ze znalezieniem ich, chyba, że już tam dotarli.",
    ["O"] = "Porozmawiaj z Huldarem.",
    ["T"] = "Zaopatrywanie wykopalisk",
  },
  [274] = {
    ["D"] = "To nie jest zwykły proch wybuchowy. Patrz na te malutkie srebrne kryształki. I wyraźny zapach! To jasne jak słońce, że to proch Seaforium. Seaforium jest całkiem nieszkodliwe. Ale jeśli namoknie, mogłoby wysadzić całe Ironforge.$B$BMożna zneutralizować tę reakcję chemiczną przez zmieszanie czterech składników: jadu przyczajców, skruszonego kryształu Mo\'Grosh, krokodylej łzy i tego rozbrajającego roztworu. A teraz opowiedz o wszystkim Hinderweirowi, zanim będzie za późno!",
    ["O"] = "Ashlan Stonesmirk chce, byś $gwrócił:wróciła; do głównego inżyniera Hinderweira i $gpoinformował:poinformowała; go o nowym odkryciu.",
    ["T"] = "Nadciąga mroczne zagrożenie",
  },
  [275] = {
    ["D"] = "Nie wiem dlaczego, ale coś jątrzy się w Wetlands. Pojawiły się bagienne stwory. Są one chorymi wykwitami gorączki tych ziem i by je z niej wyleczyć, muszą zostać odesłane w odmęty bagien.$B$BBagienne stwory człapią pośród strumieni Wetlands.",
    ["O"] = "Zabij 8 Fen Creepers, następnie wróć do Rethiela the Greenwarden w Wetlands.",
    ["T"] = "Wykwity krainy",
  },
  [276] = {
    ["D"] = "Mszystoskóre gnolle żyły w pokoju w Wetlands przez wiele lat, ale teraz jest ich coraz więcej. Ich łapy tratują krzaki i kwiaty moczarów, a ich odrażające topory ścinają zdecydowanie zbyt wiele drewna do podsycania ognisk.$B$BNie żyją już w harmonii z tą krainą. Jeśli Wetlands mają przetrwać, liczba gnolli musi zostać uszczuplona.$B$BZabij 15 mszystkoskórych gnolli i 10 mszystkoskórych łajdaków. Znajdziesz je na południu, w pobliżu krasnoludzkiej bramy Algaz. Gdy już to zrobisz, wróć do mnie.",
    ["O"] = "Zabij 15 Mosshide Gnolls i 10 Mosshide Mongrels, następnie wróć do Rethiel the Greenwarden w Wetlands.",
    ["T"] = "Tratujące łapska",
  },
  [277] = {
    ["D"] = "Mszystkoskóre ścinają drzewa Wetlands; używają ich drewna do ogrzewania samych siebie. Nie ścierpię tego dłużej!$B$BPozbaw mszystkoskórych ich krzemieni - narzędzi, którymi wzniecają ogień. Krzemienie noszą wszystkie mszystkoskóre, poza mniejszymi gnollami i kundlami.",
    ["O"] = "Przynieś 9 Crude Flints do Rethiel the Greenwarden.",
    ["T"] = "Ogniste tabu",
  },
  [278] = {
    ["D"] = "Natychmiast zacznij zbierać materiały rozbrajające, $N. Jad znajdziesz w miejscowych pająkach z Loch Modan. Łzę krokodyla również tutaj znajdziesz. Ale kryształ Mo\'grosh będzie bardzo ciężko zdobyć. Wydobywają je ogry na północnym wschodzie, ale kryształy te to bardzo rzadki klejnot.$B$BMusimy być przygotowani na odparcie ataku klanu Czarnorytnych! Wróć do mnie, gdy zbierzesz potrzebne składniki, a przygotuję wtedy miksturę.",
    ["O"] = "Główny inżynier Hinderweir chce, żebyś $gzebrał:zebrała; Lurker Venom, Mo\'grosh Crystal i Crocolisk Tear.",
    ["T"] = "Nadciąga mroczne zagrożenie",
  },
  [279] = {
    ["D"] = "Murloki wypełzają z morskich głębin i budują swoje wioski wzdłuż wybrzeża. Dręczą naszych rybaków i kupców. Muszą zostać powstrzymane.$B$BJeden z nich, Gobbler, wraz z resztą błękitnoskrzelich murloków czatuje przy trakcie na kupców, by złupić ich, a następnie uciec do bezpiecznych schronień w pobliżu. Nasi kupcy są w niebezpieczeństwie, a my jesteśmy gotowi zapłacić za ich ochronę.$B$BGobbler grasuje nad dopływem rzeki na północ stąd. Znajdź go, wyrżnij jego krewniaków i przynieś mi jego łeb.",
    ["O"] = "Zabij 12 Bluegill Murlocs.$B$BZabij Gobblera i zabierz jego głowę.$B$BPrzynieś Głowę Gobblera do Karla Borana w Menethil Harbor.",
    ["T"] = "Pazury z głębin",
  },
  [280] = {
    ["D"] = "Dzisiejszego dnia zauważyłem kilku powstańców Czarnorytnych płynących w stronę tamy z wielką beczką. W okolicy nie było żadnego górala, który mógłby ich powstrzymać! Obawiam się, że zamontowali Seaforium u podstawy tamy, a wybuch może nastąpić w każdej chwili! Pozwól, że zmieszam wszystkie składniki w miksturę rozbrajającą. Gotowe.$B$BChcę, żebyś $gwziął:wzięła; tę miksturę i $gwlał:wlała; ją do beczki, zanim będzie za późno! Prędko!",
    ["O"] = "Główny inżynier Hinderweir chce, żebyś $gpopłynął:popłynęła; do podstawy tamy, $gzlokalizował:zlokalizowała; beczkę prochu i $gwlał:wlała; do niej Miksturę Rozbrajającą, by zapobiec eksplozji.",
    ["T"] = "Nadciąga mroczne zagrożenie",
  },
  [281] = {
    ["D"] = "Statek kupiecki \"Ślepa Księżniczka\" został niedawno zaatakowany przez murloki. Choć sam statek się uratował, poczwary ściągnęły za burtę znaczną część ładunku, w tym niezwykle wartościowy posążek Terenasa Menethila. Chcemy go odzyskać.$B$BPrzeszukaj nadbrzeżne chaty murloków w poszukiwaniu skrzyń, beczek i innych śladów zgrabionego ładunku. Znajdź posążek i zwróć mi go.",
    ["O"] = "Przeszukaj skrzynie i beczki w nadbrzeżnych obozach murloków.",
    ["T"] = "Odbijanie dóbr",
  },
  [282] = {
    ["D"] = "Miałem zamiar wysłać swojego ucznia z raportem do mego brata Senira, ale czułbym się dużo lepiej, powierzając go w bardziej... rzetelne ręce. Znaczy, oczywiście, jeśli nie masz nic przeciwko?$B$BHmm... będziesz $gmusiał:musiała; przejść tunelem, by dostać się do Kharanos.$B$BPrzed wejściem do tunelu porozmawiaj z góralem Thalosem. Wprost roi się tam teraz od troggów.$B$BUdaj się drogą z powrotem w kierunku Anvilmaru, potem rusz na wschód do tunelu. Thalos stacjonuje w pobliżu.",
    ["O"] = "Porozmawiaj z góralem Thalosem.",
    ["T"] = "Obserwacje Senira",
  },
  [283] = {
    ["D"] = "Beczka cicho syczy.",
    ["O"] = "Mikstura Rozbrajająca najwyraźniej zadziałała. Wróć do głównego inżyniera Hinderweira, by przekazać dobre wieści.",
    ["T"] = "Nadciąga mroczne zagrożenie",
  },
  [284] = {
    ["D"] = "Dokładnie przeszukujesz grupę murlokich szałasów, ale nie natrafiasz na żaden ślad figurki.$B$BMoże jedna z pobliskich chat na północy i północnym wschodzie będzie kryła jakąś wskazówkę?",
    ["O"] = "Znajdź Menethil Statuette.",
    ["T"] = "Poszukiwanie trwa",
  },
  [285] = {
    ["D"] = "To osiedle chat murloków, po dogłębnym sprawdzeniu, nie kryje niczego.$B$B...ale jesteś $gpewien:pewna;, że następna wskazówka, na którą natrafisz, przyniesie owoce.$B$BJedna z chat na północy musi skrywać figurkę!",
    ["O"] = "Kontynuuj poszukiwania Menethil Statuette w chatach murloków.",
    ["T"] = "Przeszukaj więcej chat",
  },
  [286] = {
    ["D"] = "Po otwarciu wyciągniętej z błota beczki twoim oczom ukazuje się srebrzysta figurka owinięta w słomę. Przedstawia młodego, długowłosego paladyna z uniesionym młotem.$B$BTo musi być statuetka Menethila! Musisz teraz zwrócić ją Karlowi Boranowi z portu.",
    ["O"] = "Przynieś Karlowi Boranowi Menethil Statuette.",
    ["T"] = "Zwróć figurkę",
  },
  [287] = {
    ["D"] = "Zalegam ze sprawozdaniem, $N, toteż przydałaby mi się twoja pomoc. Właśnie udało mi się odnaleźć kryjówkę trolli, lecz było ich tak wiele, że nie odważyłem się do niej zbliżyć.$B$BOto czego chcę... zejdź w głąb jaskini, rozejrzyj się w środku, zabij kilka trolli, po czym wróć z powrotem.$B$BSkieruj się szlakiem wychodzącym z Kharanos na północ, aż dojdziesz do mostu, następnie podążaj zamarzniętym korytem rzeki na zachód, aż dotrzesz do jeziora Iceflow. Na jego zachodnim brzegu znajdziesz Wioskę Brewnall. A siedziba trolli jest na południowy wschód od wioski.",
    ["O"] = "Zbadaj Frostmane Hold i zabij 5 Frostmane Headhunters na zlecenie Senira Whitebearda z Kharanos.",
    ["T"] = "Siedziba Lodowych Grzyw",
  },
  [288] = {
    ["D"] = "Byłem niegdyś pierwszym oficerem na \"Pani Fal\", flagowym statku Trzeciej Floty Kul Tiras. Przeklętej Floty. Przeklętej, gdyż podczas swego ostatniego rejsu została zaatakowana przez czerwone smoki. Smoki kontrolowane przez orków!$B$BW starciu ze smoczym ogniem nie mieliśmy najmniejszych szans... nasza flota została spalona i zatonęła u tych wybrzeży. Jestem jedynym ocalałym z tej katastrofy...$B$B...Och, ależ mi głowa pęka! Jeśli mam przetrwać tego kaca i dokończyć mą opowieść potrzebuję świeżego drinka.",
    ["O"] = "Kup dzban miodu pierwszemu oficerowi Fitzsimmons\'owi.",
    ["T"] = "Trzecia Flota",
  },
  [289] = {
    ["D"] = "<Wzmocniwszy się, Fitzsimmons kontynuuje swą opowieść...>$B$BJestem jedynym ocalałym z załogi nieszczęsnej Trzeciej Floty Kul Tiras, której statki spoczywają przy brzegu na północy. Lecz choć jestem jedynym, który ciągle oddycha, nie jestem jedynym, który wciąż kroczy po ziemi! Bowiem w jednym z naszych statków ukryto wielki i jednocześnie przerażający skarb, a jego upiorna moc więzi dusze mych braci pośród gnijących desek kadłuba.$B$BLecz może uwalniając mych braci, złamiesz ciążącą na nich klątwę.",
    ["O"] = "Zabij 13 Cursed Sailors, 5 Cursed Marines i First Mate Snellig. Przynieś Snellig\'s Snuffbox do First Mate Fitzsimmons w Menethil Harbor.",
    ["T"] = "Przeklęta załoga",
  },
  [290] = {
    ["D"] = "Aby zdjąć klątwę i wyswobodzić innych marynarzy, to...coś...znajdujące się na moim statku musi zostać zeń zabrane i oczyszczone! Nie wiem, co to takiego, lecz jestem pewien, że zostało schowane w sejfie statku, do którego dostęp ma wyłącznie kapitan Halyndor.$B$BMój stary kapitan wciąż nawiedza moje sny. Wiem, że przemierza pokład mego przeklętego okrętu, \"Nieustraszonego\". Odbierz mu klucz i użyj do go do otwarcia sejfu.$B$BGdy już będziesz mieć to przeklęte coś, zanieś je do miejscowego kapłana Glorina Steelbrowa.",
    ["O"] = "Odbierz kapitanowi Halyndorowi klucz.$B$BUżyj klucza, aby otworzyć sejf.",
    ["T"] = "Zdjęcie klątwy",
  },
  [291] = {
    ["D"] = "Wspaniale! Zabierz mój raport do senatora Barina Redstone\'a. To zgorzkniały gość, toteż nie pozwól, aby jego pochmurne usposobienie cię zraziło. Przebywa w Ironforge, pośród osób otaczających króla Magniego.$B$BNie znasz drogi do Ironforge? Skieruj się na północ drogą wychodzącą z Kharanos, przejdź przez most i udaj się traktem na wschód - są tam spore tablice wskazujące kierunki - po zboczu góry.$B$B$gMógłbyś:Mogłabyś; przy okazji nie wspominać, w jaki sposób mi $gpomogłeś:pomogłaś;? Nie chcę, aby pomyśleli, że się tutaj nie staram, $gsam:sama; wiesz.",
    ["O"] = "Dostarcz raport Senira do senatora Barina Redstone\'a z Ironforge.",
    ["T"] = "Raporty",
  },
  [292] = {
    ["D"] = "We wnętrzu skrzyni spoczywa sczerniała kula, pulsująca upiornym blaskiem. To skarb, o którym mówił Fitzsimmons: przeklęte Oko Paletha.$B$BZabierz je do krasnoludzkiego kapłana Glorina Steelbrowa z portu Menethilów. Dowiedz się od niego, jak zdjąć klątwę z Oka.",
    ["O"] = "Zanieś Cursed Eye of Paleth do Glorina Steelbrowa.",
    ["T"] = "Oko Paletha",
  },
  [293] = {
    ["D"] = "Nie mogę zdjąć klątwy z Oka Paletha. Oczy są dziełem kapłanów ludzi, więc aby znaleźć kogoś, kto ci pomoże, musisz udać się do Stormwind. Porozmawiaj z arcybiskupem Benedictusem. Jest przeorem Katedry Światła w Stormwind. On pomoże.$B$BMam nadzieję, dla twojego dobra.",
    ["O"] = "Zanieś Cursed Eye of Paleth do arcybiskupa Benedictusa, przebywającego w Cathedral of Light w mieście Stormwind.",
    ["T"] = "Oczyszczenie Oka",
  },
  [294] = {
    ["D"] = "Sytuacja jest poważna, co do tego nie ma wątpliwości. Kiedy odsłoniliśmy te kości, przyciągnęły one uwagę jaszczurów. Te ohydne bestie zabiły mych ziomków i uwięziły mnie, Merrina i biednego poszukiwacza tu na górze.$B$BPomóż oczyścić Wetlands z jaszczurów, $N. Jaszczury przebywają zaraz na zachód od urwiska. Zabij 10 sztuk z każdego rodzaju, jeśli tylko dasz radę.$B$BTo dobry początek dla zemsty, którą dla nich zaplanowałem.",
    ["O"] = "Ormer Ironbraid z Whelgar Excavation Site chce, abyś $gzabił:zabiła; 10 Mottled Screechers i 10 Mottled Raptors.",
    ["T"] = "Zemsta Ormera",
  },
  [295] = {
    ["D"] = "Nadszedł czas, aby te przerażające jaszczury pożałowały swej żądzy krwi. Tam na dole przebywają ich stada. Odpłać tym przebrzydłym stworzeniom zabijając 10 sztuk z każdego rodzaju!",
    ["O"] = "Ormer Ironbraid chce, abyś $gzabił:zabiła; jaszczury: 10 Mottled Scytheclaw i 10 Mottled Razormaw, po czym $gwrócił:wróciła; do niego, na Whelgar Excavation Site.",
    ["T"] = "Zemsta Ormera",
  },
  [296] = {
    ["D"] = "Gdy $gdziałałeś:działałaś; tam na dole, zauważyłem pewną bestię, wyróżniającą się z całego stada. Miała większe rozmiary i budziła większą grozę. Założę się, że to ona sprowadziła tu pozostałe, aby spowodować wstrzymanie prac.$B$BProszę cię o wykonanie ostatniego zadania, $N. Wymierz Sarltoothowi sprawiedliwość. A biorąc pod uwagę ciężar jego zbrodni, sprawiedliwość oznaczać może jedynie śmierć! Przynieś mi jeden z jego pazurów na jej dowód.",
    ["O"] = "Ormer Ironbraid z Whelgar Excavation Site chce, abyś $gzabił:zabiła; Sarltootha i wrócił do niego z jednym z jego pazurów, kiedy już zadanie zostanie wykonane.",
    ["T"] = "Zemsta Ormera",
  },
  [297] = {
    ["D"] = "Ostatnio, chwilę przed tym, nim troggi pojawiły się na terenie wykopalisk, odkryliśmy ogromną liczbę dziwnych rzeźbionych posążków. Niestety nie mieliśmy szans, aby je zbadać, gdyż wkrótce po dokonaniu odkrycia troggi przegoniły nas z ruin! A te posążki wywierają na nie dziwny wpływ. Sprawiają, że wpadają w szał!$B$BPrzynieś mi 8 posążków - chcę je zbadać i co ważniejsze - trzymać je z dala od troggów! Znajdziesz je przy troggach, które opanowały wykopaliska.",
    ["O"] = "Przynieś Magmarowi Fellhewowi 8 Carved Stone Idols.",
    ["T"] = "Zbieranie posążków",
  },
  [298] = {
    ["D"] = "Muszę zanieść raport postępu do Thelsamar - raport z postępów, oraz ponowne rozpatrzenie mojej prośby o więcej prochu wybuchowego! Tutaj masz raport. Zabierz go do Jern Hornhelm. To nasz lokalny kontakt w Thelsamar.$B$BTo nie jest trudne zadanie, ale musi zostać wykonane!",
    ["O"] = "Przynieś Ironband\'s Progress Report dla Jern Hornhelm, który znajduje się w Thelsamar.",
    ["T"] = "Raport z postępów wykopalisk",
  },
  [299] = {
    ["D"] = "Chwilę przed inwazją odkryłem dużą tablicę zwaną kamieniem Goaz. Tłumaczony tekst rozpadł się w 4 miejscach. Napis głosił o \"Boskim planie\" oraz o \"utraconym proroctwie\".$B$BObawiam się, że zaczyna brakować nam czasu. Jestem już za stary by tam iść i walczyć z tymi bestiami. Lecz ty jesteś $gsilny:silna;.$B$BPrzeszukaj obszar wykopalisk i odkryj 4 zaginione odłamki tablicy: Ados, Modr, Golm i Neru. Szukaj ich w starożytnych artefaktach lub tam, gdzie gleba jest luźna. Przynieś mi je, bym mógł zacząć zgłębiać ich tajemnice.",
    ["O"] = "Poszukiwacz Whelgar chce, byś przeszukał obszar wykopalisk i $gznalazł:znalazła; 4 odłamki zaginionej tablicy: Ados, Modr, Golm i Neru.",
    ["T"] = "Odkrywanie przeszłości",
  },
  [301] = {
    ["D"] = "Będziemy potrzebować zgody, aby pozyskać dla Ironbanda więcej prochu. Będziesz $gmusiał:musiała; zanieść ten raport do kwatery dowodzenia Ligii Odkrywców w Ironforge.$B$BOto on. Przekaż go poszukiwaczowi Stormpike i nie zapomnij jak najszybciej się stamtąd ulotnić. Stormpike jest narwany i nie będzie szczęśliwy słysząc o wolnym postępie pracy Ironbanda w terenie. Stormpike\'a znajdziesz w Zgromadzeniu Odkrywców.",
    ["O"] = "Zanieś Ironband\'s Progress Report do poszukiwacza Stormpike\'a.",
    ["T"] = "Raport do Ironforge",
  },
  [302] = {
    ["D"] = "Jeśli Ironband wciąż chce prochu, będzie musiał zdobyć go przez Magniego. Wysłałem posłańca do Jerna Hornheala w Thelsamar. Przygotuje proch i inne materiały, które weźmiesz do Ironbanda.$B$BI jeszcze jedno. Chcę, żebyś $gzobaczył:zobaczyła; jak osobiście odbiera przesyłkę! Ostatnia nie dotarła, więc musisz mieć oczy i uszy szeroko otwarte.",
    ["O"] = "Porozmawiaj z Jernem Hornhelm w Thelsamar.",
    ["T"] = "Proch dla Ironbanda",
  },
  [303] = {
    ["D"] = "Wojna grzmi i w domu i poza nim. Podczas, gdy wielcy krasnoludzcy wojownicy oddają swoje życie w imię Przymierza na ziemiach położonych daleko stąd, nasze własne tereny stają się łupem dla niecnych uczynków klanu Czarnorytnych. Udało im się całkowicie zniszczyć Przęsło Thandola, a Dun Modr padło niedługo potem.$B$BPotrzebujemy, abyś $gzebrał:zebrała; siły i $gprzepchnął:przepchnęła; do tyłu linie frontu. Jeśli uda ci się zabić 10 krasnoludów Czarnorytnych, 5 kopaczy , 5 sabotażystów i 5 ekspertów od wybuchów, nasza rezerwa być może dotrze na czas, aby zakończyć pościg.$B$BA teraz się pospiesz!",
    ["O"] = "Motley Garmason w Dun Modr chce, abyś $gzabił:zabiła; 10 Dark Iron Dwarves, 5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs i 5 Dark Iron Demolitionists.",
    ["T"] = "Wojna Czarnorytnych",
  },
  [304] = {
    ["D"] = "Wielu moich żołnierzy poległo w walce o Dun Modr. Mój własny brat zginął, kiedy zachodni most rozciągający się nad Przęsłem Thandola został zniszczony. W rzeczy samej, krasnoludy Czarnorytne to diabelna rasa. Z tego, co Roggo zdążył się dowiedzieć, przywódcą tych zbirów w Wetlands jest czarnoksiężnik o imieniu Balgaras Plugawy. Dosyć z niego tchórz, wysyła swoich żołnierzy, aby wypełniali jego polecenia, a sam chowa się w swoim obozie na Wzgórzu Direforge na południowym-wschodzie.$B$BJeśli uda ci się znaleźć tą tchórzliwą szumowinę, zgładź go i przynieś mi jego ucho. Sowicie cię za to wynagrodzę, $C.",
    ["O"] = "Zabij Balgaras the Foul i przynieś jego ucho do Longbraid the Grim znajdującego się na obrzeżach Dun Modr.",
    ["T"] = "Ponure zlecenie",
  },
  [305] = {
    ["D"] = "O ja, ty musisz być tym zwiadowcą, o którym mówił Longbraid. Nie potrafisz sobie wyobrazić jak się martwiłem.$B$BMoja żona, Merrin, wysyłała mi listy każdego tygodnia przez ostatni miesiąc. Jest ona częścią załogi ekipy wydobywczej Whelgara. Ale minęło już dwa tygodnie od ostatniej wiadomości. Na pewno coś się stało!$B$BLongbraid powiedział, że wyśle zwiadowcę, by sprawdzić sprawę jeśli wkrótce nie otrzymamy od załogi wiadomości. Zakładam, że wysłał ciebie, $N. Znajdź Merrin na obszarze wykopalisk na wschód.",
    ["O"] = "Tarrel Rockweaver chce, abyś $gposzedł:poszła; do Excavation Site i $gskontaktował:skontaktowała; się z Merrinem Rockweaver.",
    ["T"] = "W poszukiwaniu ekipy wydobywczej",
  },
  [306] = {
    ["D"] = "To było okropne! Odkryliśmy kilka rzadkich artefaktów i zaczęliśmy odkrywać te wielkie kości.$B$BZanim dowiedzieliśmy się co się stało, te jaszczury zdominowały miejsce wykopów. Wielu straciło życie.$B$BOrmer tutaj - jakiż on odważny - ocalił poszukiwacza i mnie. Ochraniał nas jak biegliśmy się schronić. Teraz jesteśmy w pułapce i nasza ciężka praca leży w gruzach.$B$BMasz, weź tę notatkę z powrotem do mojego słodkiego Tarrela. To wyjaśni mu zaistniałą sytuację.",
    ["O"] = "Wróć do Tarrel\'a Rockweaver z notatką od Merrin.",
    ["T"] = "W poszukiwaniu ekipy wydobywczej",
  },
  [307] = {
    ["D"] = "Położona na wschodzie Kopalnia Srebrnego Strumienia dawno temu uległa wyczerpaniu. Liga Górników przerobiła ją na magazyn, ale teraz wprowadziły się tam Koboldy i położyły swe brudne łapska na porządnych krasnoludzkich narzędziach!$B$BWkrótce wyplenimy to robactwo, ale Liga chce, by ktoś $gzabrał:zabrała; stamtąd jej sprzęt, zanim my, wojownicy, wpadniemy tam i coś zniszczymy. To będzie ciężkie zadanie - możliwe, że uznasz, że chcesz mieć całą armię u swego boku.$B$BSprzęt jest przechowywany w Skrzynkach Ligi Górników na terenie całej kopalni. Powodzenia.",
    ["O"] = "Idź do Silver Stream Mine i zbierz 4 ładunki Miners\' Gear.$B$BWróć do górala Stormpike\'a.",
    ["T"] = "Brudne łapska",
  },
  [308] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Odwrócenie uwagi Jarvena",
  },
  [309] = {
    ["D"] = "$gGotów:Gotowa; do drogi, $N?$B$BPrzede wszystkim musimy dostarczyć ten proch Ironbandowi. Będę miał sporo do dźwigania, a te części mogą być niebezpieczne - a kto wie, co jeszcze mają dla mnie w zanadrzu Czarnorytni.$B$BW twoim towarzystwie czuję się znacznie lepiej.",
    ["O"] = "Dopilnuj, aby Miran i jego ładunek dotarli bezpiecznie do strefy wykopaliskowej, potem poinformuj poszukiwacza Ironbanda.",
    ["T"] = "Ochrona towaru",
  },
  [310] = {
    ["D"] = "Muszę przyznać, ci Thunderbrewowie pędzą kilka dobrych napitków. Ale muszą się nauczyć, że ich trunek nie jest jedynym słusznym! Może ty pomożesz mi udzielić im tej lekcji...$B$BMasz, weź tą beczkę Barleybrew Scalder. Zakradnij się do piwnicy destylarni Thunderbrewów w Kharanos i podmień ją na jedną z ich beczek Thunder Ale. Potem okaże się, o ile bardziej bywalcy gospody wolą mój trunek od ich wyrobów!$B$BA jeśli beczki będą strzeżone, może będziesz $gmusiał:musiała; odwrócić uwagę strażnika...",
    ["O"] = "Podmień beczkę Barleybrew Scalder na beczkę Thunder Ale w piwnicy Thunderbrew Distillery w Kharanos.",
    ["T"] = "Zawzięci rywale",
  },
  [311] = {
    ["D"] = "Umieściwszy beczkę Marletha w piwnicy destylarni w Kharanos, zabierasz beczkę Piorunowego Piwa na dowód wykonania zadania...",
    ["O"] = "Zanieś beczkę Thunder Ale do Marletha Barleybrew z Brewnall Village.",
    ["T"] = "Powrót do Marleth",
  },
  [312] = {
    ["D"] = "Miałem miesięczne zapasy suszonego mięsa, osolone i schowane na zimną porę roku. Trzymałem je zamknięte, by niedźwiedzie się do nich nie dobrały! Ale kiedy polowałem na jelenie, ta bestia, Stary Icebeard, zwiał z całą moją spiżarką. Co prawda, nie da rady przebić się przez thorium. Ale jeśli nie uda mi się odzyskać mojego mięsa, czeka mnie głód.$B$BWydajesz się $gzwinniejszy:zwinniejsza; niż ja. Może mógłbyś odzyskać moje zapasy? Przy mojej poparzonej nodze nigdy nie uda mi się wejść i wyjść z tej jaskini dostatecznie szybko.",
    ["O"] = "Odzyskaj suszone mięso Tundry MacGrann\'a ze skradzionej spiżarki z jamy starego Icebearda.",
    ["T"] = "Skradzione zapasy Tundry MacGranna",
  },
  [313] = {
    ["D"] = "Kierowanie Czołgiem Szturmowym to zajęcie nie dla każdego. Wymaga żelaznego chwytu i nerwów ze stali... na szczęście mam to i to! A ty? Jak tam z twoim charakterem? Chcesz mi coś udowodnić?$B$BCóż... chcę przerobić mój czołg, Trollplow, na bardziej przytulny. $gMógłbyś:Mogłabys; przynieść mi stosik grzyw wondigo z Pieczary Siwowłosych, na zachód od Kharanos? Zrobiłbym z nich wspaniały dywanik do wnętrza Trollplow!",
    ["O"] = "Zbierz 8 Wendigo Manes i przynieś je pilotowi Stonegearowi.",
    ["T"] = "Pieczara Siwowłosych",
  },
  [314] = {
    ["D"] = "W środku nocy usłyszeliśmy hałas. Następnego ranka okazało się, że ze stada zniknęły dwa barany. Ta nikczemna bestia, znana jako Vagash, pozbawia nas środków do życia. A ponieważ większość armii króla Magniego walczy teraz w odległych krainach u boku Przymierza, nie ma nikogo, kto trzymałby Vagasha z dala od nas.$B$BMoże ty jesteś dość $godważny:odważna;, by odnaleźć tę bestię i zabić ją. Przynieś mi jeden z jego kłów, a wynagrodzę cię. Vagash czai się ponad naszym ranczem, lecz uważaj, jest śmiertelnie niebezpieczny.",
    ["O"] = "Rudra Amberstill chce, byś $gzabił:zabiła; Vagasha i $gprzyniósł:przyniosła; jej jego kieł na farmę baranów.",
    ["T"] = "Ochrona stada",
  },
  [315] = {
    ["D"] = "Postawiłem sobie pewne zadanie, zadanie stworzenia idealnego portera. Wiem, że dam radę - warzenie piwa mam we krwi. Muszę tylko znaleźć odpowiedni przepis...$B$BNa grzbietach wzgórz na wschodzie, trolle hodują pewną roślinę - lśniące ziele. Używają jej do swych dziwnych, plemiennych obrzędów. My, krasnoludy, nie znaleźliśmy dla niej wielu zastosowań, ale ma wyjątkowy smak... i zamierzam poeksperymentować z nią przy moich trunkach!$B$BZdobądź dla mnie trochę tej rośliny od wieszczy Lodowych Grzyw, albo podwędź trochę z ich koszy.",
    ["O"] = "Przynieś 6 liści Shimmerweeds do Rejolda Barleybrewa w Brewnall Village.",
    ["T"] = "Idealny porter",
  },
  [316] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [317] = {
    ["D"] = "Przygotowuję się do misji dla Brygady Szturmowej. Potrwa dość długo, toteż muszę zaopatrzyć parodrzut w miesięczną rację zapasów. Więc podczas gdy Steelgrill pracuje nad moim czołgiem, może $gmógłbyś:mogłabyś; dla mnie coś upolować?$B$BBędę potrzebował trochę futer na posłanie i mięso do jedzenia. Mięso możesz zdobyć z dzików, a futra z niedźwiedzi. Jedne i drugie znajdziesz na zaśnieżonych równinach na południe od Pieczary Siwowłosych.",
    ["O"] = "Zbierz 4 Chunks of Boar Meat i 2 Thick Bear Furs i dostarcz je do pilota Bellowfiza, do Steelgrill\'s Depot.",
    ["T"] = "Zapasy dla parodrzuta",
  },
  [318] = {
    ["D"] = "Rejold Barleybrew eksperymentuje ze swoimi trunkami. Niektóre smakują dobrze, niektóre źle, a niektóre... no, niektóre kładą na łopatki wszystkich, poza najtęższymi krasnoludzkimi głowami.$B$BMieszka we Wiosce Brewnall, na zachód od Kharanos, zaś jeden z jego produktów - Piorunówka - jest tym, czego chcę. Pomoże mi się ogrzać, kiedy będę podróżować na mrozie.$B$BI... ten boski napój pali tak mocno, że mogę wrzucić go do pieca odrzutowca, by dodać mu mocy! Ta mała sztuczka wyciągnęła mnie nie raz z tarapatów.",
    ["O"] = "Zdobądź baryłkę Evershine od Rejolda Barleybrewa z wioski Brewnall.",
    ["T"] = "Piorunówka",
  },
  [319] = {
    ["D"] = "Mam na zbyciu baryłkę Piorunówki, ale... czy $gmógłbyś:mogłabyś; wyświadczyć mi przysługę? Wiosce Brewnall przydałaby się pomoc przy dzikich zwierzętach, włóczących się wśród okolicznych śniegów. Czasem docierają do jej granic.$B$BNie obawiamy się tych niedźwiedzi, ani kotów, ani dzików - żaden szanujący się krasnolud się ich nie boi - ale gdybyś $gmógł:mogła; zająć się nimi za nas, mielibyśmy więcej czasu na rzemiosło i warzenie piwa.",
    ["O"] = "Zabij 6 Ice Claw Bears, 8 Elder Crag Boars i 8 Snow Leopards, następnie wróć do Rejolda Barleybrewa, do Brewnall Village.",
    ["T"] = "Przysługa za Piorunówkę",
  },
  [320] = {
    ["D"] = "Oto twoja baryłka Piorunówki, $N. I jeszcze raz dziękuję za poprzednie łowy.",
    ["O"] = "Przekaż baryłkę Evershine pilotowi Bellowfizowi w Steelgrill\'s Depot.",
    ["T"] = "Powrót do Bellowfiza",
  },
  [321] = {
    ["D"] = "Wraki statków przy tutejszym wybrzeżu to potępiona Trzecia Flota Kul\'Tiras, spalona i zatopiona przez czerwone smoki podczas ostatniej Wielkiej Wojny.$B$BFlota należała do Lordaeronu, ale płynął z nią pewien statek, elfi niszczyciel: The Flying Osprey. Miał na pokładzie ładunek Świetlistego Żelaza i dołączył do Trzeciej Floty dla bezpieczeństwa. Jak na ironię, zatopiły go te same smoki...$B$BDość historii. The Flying Osprey spoczywa na południe od Menethil Harbor. Jeśli znajdziesz tam Świetliste Żelazo, przynieś mi je.",
    ["O"] = "Poszukaj wraku The Flying Osprey w Wetlands.",
    ["T"] = "Świetliste żelazo",
  },
  [322] = {
    ["D"] = "W Dwarven District w Stormwind mieszka pewien kowal, który potrafi przekuwać świetliste żelazo. Na imię ma Grimand Elmore.$B$BZapakowałem znalezione przez ciebie żelazo do skrzyni. Zabierz je do Grimanda i opowiedz mu swoją historię. Jestem pewien, że wyświadczy przysługę komuś realizującemu taką misję i sporządzi dla ciebie broń - broń, której ulęknie się nawet Morbent Fel!",
    ["O"] = "Zanieś Crate of Lightforge Ingots do Grimanda Elmore\'a w Stormwind.",
    ["T"] = "Błogosławione ramię",
},
  [323] = {
    ["D"] = "Morbent Fel jest nekromantą i sojusznikiem czarnych jeźdźców. Posłałbym cię do walki z mocami tego ohydnego potwora, ale nie uczynię tego, nie oceniwszy wpierw twoich sił.$B$BUdowodniłeś już swą odwagę, ale jeśli naprawdę chcesz zmierzyć się z nekromantą, musisz jeszcze dowieść swych umiejętności w walce z jego sługami.",
    ["O"] = "Zabij 15 Skeletal Raiders, 3 Skeletal Healers i 3 Skeletal Warders, następnie wróć do Svena.",
    ["T"] = "Udowodnij swą wartość",
  },
  [324] = {
    ["D"] = "Wyciągnąwszy samotną świetlistą sztabkę z zalanej skrzyni dochodzisz do oczywistego wniosku, że resztę ukradły murloki. Zapoluj na murloki napastników kręcące się w pobliżu wraku Flying Osprey, by odzyskać zaginione świetliste żelazo.",
    ["O"] = "Zbierz 5 Lightforge Ingots, następnie wróć do Glorina Steelbrowa w Wetlands.",
    ["T"] = "Zaginione sztabki",
  },
  [325] = {
    ["D"] = "Oto broń przeciwko nikczemnikowi, o którym $gmówiłeś:mówiłaś;. Jesteś teraz w pełni $gprzygotowany:przygotowana;, $N. Życzę ci powodzenia i oczekuję na opowieść o twojej chwale!",
    ["O"] = "Zanieś Morbent\'s Bane do Svena w Duskwood.",
    ["T"] = "Uzbrojony i przygotowany",
  },
  [328] = {
    ["D"] = "Choć w zapiskach brak jakiejkolwiek wzmianki o Private Thorsenie, w oprawie jednego z rejestrów ukryto mały mosiężny klucz. $B$BW trakcie dalszej lektury znajdujesz kilka odnośników dotyczących <bezpiecznej skrzyni>. Spoczywa gdzieś w Stockpile - kompleksie jaskiń, położonym za Kurzen\'s Compound.$B$BJeśli znajdziesz skrzynię i klucz będzie do niej pasował, być może tajemnica związana z odkryciem tożsamości Thorsena zostanie rozwiązana.",
    ["O"] = "Użyj klucza Small Brass Key, aby otworzyć skrzynię Bookie Herod\'s Strongbox.",
    ["T"] = "Ukryty klucz",
  },
  [329] = {
    ["D"] = "Pomiędzy skarbami w skrzyni spoczywa ubłocone, nagryzmolone pismo. Choć ledwie czytelne, wygląda na rozpiskę działań szeregowego Thorsena. Zawiera trasy jego patroli, informacje o tym z kim rozmawiał i co robił wśród rebeliantów. Podpisano je tylko jedną literą: -M. $B$BJednakże ktokolwiek sporządził to pismo, musiał przebywać bardzo blisko Thorsena. Autor tej notki jest zdrajcą pośród rebeliantów.",
    ["O"] = "Zabierz Muddy Note do Lieutenanta Dorena z Rebel Camp.",
    ["T"] = "Szpieg zdemaskowany!",
  },
  [330] = {
    ["D"] = "Pismo, które mi dałeś, podpisano literą: - M... Nie wiem, co może ona oznaczać. $B$BAle... pismo mówi też, że ta osoba w ostatnim tygodniu patrolowała tą samą trasę, co Thorsen. Więc ktokolwiek to był, musi być zdrajcą. Idź do Kaprala Sethmana. On zajmuje się harmonogramem patroli i powie ci, kto pełnił służbę wspólnie z Thorsenem.",
    ["O"] = "Porozmawiaj z Kapralem Sethmanem.",
    ["T"] = "Harmonogram patroli",
  },
  [331] = {
    ["D"] = "Czy Lieutenant Doren chciał, byś wrócił do niego z informacjami o patrolach?",
    ["O"] = "Porozmawiaj z Lieutenantem Dorenem.",
    ["T"] = "Zgłoś się do Dorena",
  },
  [332] = {
    ["D"] = "Jeśli $grozmawiałeś:rozmawiałaś; z kimś o winie, wiesz że my Gallinas, sprzedajemy najlepsze wino w Stormwind. I nie jesteśmy daleko, nadal w Dystrykcie Handlowym wzdłuż uroczych kanałów miasta.$B$BMasz, weź tę broszurkę. Zanieś ją mojej siostrze Suzetcie i zamień na bezpłatną butelkę naszego sławnego Pinot Noir. Nie będziesz $gżałował:żałowała;!",
    ["O"] = "Idź do winiarza Gallina i zamień Suzette Galina Wine Ticket na darmową butelkę wina.",
    ["T"] = "Reklama sklepu z winem",
  },
  [333] = {
    ["D"] = "Ostatnio interes nieźle się kręci. Wygląda na to, że wszyscy kupują zbroje i ciepłe ubrania. Zupełnie jakby nadchodziła zimna, pochmurna pora roku.$B$BJednak to są zmartwienia na przyszłość. Teraz martwię się o to, że kończy mi się wełniana odzież. Potrzebuję kolejnej dostawy od naszego zaopatrzeniowca.$B$BByłbym bardzo wdzięczny, gdybyś $gzaniósł:zaniosła; to zamówienie do Remy Schneider, do krawcowej z kanałów.",
    ["O"] = "Idź do krawca z kanałów i zanieś do Remie\'go Schneider\'a zamówienie na wełnianą odzież od Harlana Bagleya.",
    ["T"] = "Harlan potrzebuje zaopatrzenia",
  },
  [334] = {
    ["D"] = "Mój syn Thurman jest czeladnikiem w sklepie \"Larson Clothiers\" w Dzielnicy Magów. Dziś rano tak mu się spieszyło, że zapomniał swoich nożyc i igieł. Wiem, że tak $gwspaniały wojownik:wspaniała wojowniczka; jak ty ma pewnie ważniejsze sprawy na głowie, ale bez nich Thurman nie może wykonywać swojej pracy!$B$BProszę, $N, czy możesz zanieść mojemu synowi jego zestaw krawiecki? Sklep odzieżowy Larsona jest jednym z dwóch sklepów krawieckich w Dzielnicy Magów - to ten bardziej w głębi, obok Wieży Magów.",
    ["O"] = "Idź do sklepu \"Larson Clothiers\" w Dzielnicy Magów w Stormwind i daj Thurmanowi Schneiderowi jego przyrządy krawieckie.",
    ["T"] = "Paczka dla Thurmana",
  },
  [335] = {
    ["D"] = "Lord Wishock wzbudził znaczne poruszenie w Izbie Szlachciców. Zdobył informacje o naszej małej \"instytucji\" i domaga się oficjalnego śledztwa. Mam pomysł, jak sprawić, że pozostanie \"zaprzątnięty\" czym innym, ale potrzebuję twojej pomocy.$B$BW Ogrodach Stalvana, na obrzeżach Darkshire, rośnie pewna roślina. Ten mały, biały kwiat znany jest jako Łza Tilloy. Będę też potrzebować Korzenia Musquash, który występuje wyłącznie w Wetlands, u podnóży wodospadów przelewających się przez tamę Stonewrought.",
    ["O"] = "Zardeth the Black Claw chce, abyś $gprzyniósł:przyniosła; mu Tear of Tilloa z Darkshire oraz Musquash Root z Wetlands.",
    ["T"] = "Szlachetny trunek",
  },
  [336] = {
    ["D"] = "Lord Wishock, jak wszyscy ludzie, ma swoje słabości. Tak się składa, że przejawia sentyment do alkoholu. Jego hipokryzja jest zdumiewająca. Ten głupiec spędza dni na próbach zamknięcia naszej małej \"gospody\", a noce w izbie na górze, popijając na rachunek, którego nigdy nie spłaca. Cóż, zobaczmy, czy Wischock polubi ten wyjątkowy trunek, który dla niego przygotowałem - porter Czarnego Pazura. Ma niezłego kopa, $N.$B$BZanieś mu go i przekonaj się, czy będzie mu smakował. Zazwyczaj ten stary głupiec przesiaduje w Hali Składnia Petycji.",
    ["O"] = "Zanieś Black Claw Stout do Lorda Wishocka, do Hali Składnia Petycji.",
    ["T"] = "Szlachetny trunek",
  },
  [337] = {
    ["D"] = "Choć okładka jest zadrapana i poplamiona błotem, słowa <Historia Storwind> są wciąż czytelne. Po otwarciu książki na pierwszej stronie twoim oczom ukazuje się wyraźna pieczęć Biblioteki Stormwind.$B$BWygląda na to, że ktoś kiedyś wypożyczył tę księgę i nigdy jej nie zwrócił...",
    ["O"] = "Zwróć książkę <The History of Stormwind> do Biblioteki Stormwind.",
    ["T"] = "Stara księga historyczna",
  },
  [338] = {
    ["D"] = "Mistrz Nesingwary wyjdzie z siebie, jak to zobaczy!$B$BPowierzył mi do przeczytania i sprawdzenia manuskrypt jego powieści, <Zielonych wzgórz Stranglethorn>. Wszystko było dobrze, dopóki silny podmuch wiatru nie porwał stron!$B$BZnalazłem większość z nich, ale sporo nadal jest gdzieś w dżungli... Proszę, zbierz te strony, by złączyć je w cztery rozdziały...$B$BPomogę ci je ułożyć. Przynieś mi je, gdy uzbierasz wszystkie cztery.",
    ["O"] = "Zbierz brakujące strony manuskryptu <The Green Hills of Stranglethorn>. Wróć do Barnila, gdy wszystkie cztery rozdziały będą kompletne.",
    ["T"] = "<Zielone wzgórza Stranglethorn>",
  },
  [339] = {
    ["D"] = "Rozdział I był całkiem interesujący. Mistrz Nesingwary buduje tło całej historii i pisze o swoich towarzyszach, w tym o mnie!$B$BAle to na marginesie... Niech spojrzę, których to stron wciąż nie mam... Wydaje mi się, że... Pierwszej, czwartej, szóstej i... ósmej... Muszą być gdzieś w dżungli!",
    ["O"] = "Przynieś Barnilowi Stonepotowi 1, 4, 6, i 8 stronę <Zielonych Wzgórz Stranglethorn> Nesingwary\'ego, by skompletować Rozdział I.",
    ["T"] = "Rozdział I",
  },
  [340] = {
    ["D"] = "Rozdział drugi był pełen ekscytujących opowieści o panterach i polowaniu na tygrysy. Pluję sobie w brodę za to, że pozwoliłem tym stronom tak po prostu odlecieć!$B$BAle... znalazłem ich trochę... Brakuje mi tylko dziesiątej, jedenastej, czternastej oraz szesnastej.",
    ["O"] = "Przynieś Barnilowi Stonepotowi 10, 11, 14 i 16 stronę <Zielonych Wzgórz Stranglethorn> Nesingwary\'ego, by skompletować Rozdział II.",
    ["T"] = "Rozdział II",
  },
  [341] = {
    ["D"] = "Rozdział trzeci... Mój ulubiony. Opowiada o pierwszej zwierzynie upolowanej przez sir Erlgadina i lady Rouack za pomocą krasnoludzkich strzelb! A zakończenie rozdziału trzeciego... cóż za zwrot akcji!$B$BWygląda na to, że cały czas brakuje nam paru stron... Osiemnastej... Dwudziestej... Hmm... No i dwudziestej pierwszej oraz dwudziestej czwartej... Muszą być gdzieś w dżungli...",
    ["O"] = "Przynieś Barnilowi Stonepotowi 18, 20, 21 oraz 24 stronę <Zielonych wzgórz Stranglethorn> Nesingwary\'ego, by skompletować Rozdział III.",
    ["T"] = "Rozdział III",
  },
  [342] = {
    ["D"] = "Ach... Rozdział czwarty... Cóż to było za zakończenie!$B$BBrakuje nam tylko trzech stron z tego rozdziału. Są to strony dwadzieścia pięć, dwadzieścia sześć... oraz dwadzieścia siedem. Gdy je zbierzesz, będę miał rozdział czwarty w całości!",
    ["O"] = "Przynieś Barnilowi Stonepotowi 25, 26 i 27 stronę <Zielonych wzgórz Stranglethorn> Nesingwary\'ego, by skompletować Rozdział IV.",
    ["T"] = "Rozdział IV",
  },
  [343] = {
    ["D"] = "Wygłaszam przemowę o Harcie Ducha i chciałbym zacytować ustęp z pewnej książki o metalurgii, noszącej tytuł \"Właściwości żelaza\". Egzemplarz tej książki można znaleźć w Królewskiej Bibliotece w Twierdzy Stormwind. Możesz ją dla mnie zdobyć? Jeśli tak, niech łaska Światłości będzie z tobą! $B$BKrólewska Biblioteka jest bardzo duża, ale główny bibliotekarz, Milton Sheaf, zna tam każdą półkę jak własne dziecko. Porozmawiaj z nim, a znajdzie dla ciebie tę książkę.",
    ["O"] = "Udaj się do Królewskiej Biblioteki w Twierdzy Stormwind i porozmawiaj z Miltonem Sheafem. Znajdzie dla ciebie książkę o metalurgii, której brat Kristoff potrzebuje do swojej przemowy.",
    ["T"] = "Przemowa o harcie ducha",
  },
  [344] = {
    ["D"] = "\"Właściwości żelaza\"? Tak, znam tę książkę. Całkiem niezła, spisana przez krasnoludzkiego górnika Margulfa Blaggona kilkadziesiąt lat temu. Autor spędził większość życia w głębi gór Khaz Modan, wydobywając rudę. Mądry gość!$B$BO czym to ja mówiłem? A tak, \"Właściwości żelaza\"! Obawiam się, że książka trafiła do Opactwa Northshire. Opiekun tamtejszej biblioteki, brat Paxton, chciał skopiować ją na potrzeby własnej kolekcji.$B$BAle to było miesiące temu. Zastanawiam się, dlaczego zajmuje mu to tyle czasu...",
    ["O"] = "Porozmawiaj z Bratem Paxtonem w Northshire Abbey.",
    ["T"] = "Brat Paxton",
  },
  [345] = {
    ["D"] = "Starałem się ukończyć moja kopię \"Właściwości żelaza\", ale...$B$BWidzisz, sam robię atrament do kopiowania książek. To mój prywatny przepis; nie rozmazuje się i wysycha bardzo szybko. Jak się okazało - za szybko! Moja ostatnia partia wyschła zanim skończyłem pracę, a nie miałem możliwości zrobić więcej atramentu!$B$BAby go sporządzić potrzebuję Rudy Rethbana z Redridge Mountains. Zazwyczaj zaopatruję się u brygadzisty Oslowa w Lakeshire.",
    ["O"] = "Porozmawiaj z brygadzistą Oslowwm w Lakeshire i spytaj go o Rethban Iron Ore.",
    ["T"] = "Zapasy atramentu",
  },
  [346] = {
    ["D"] = "Wreszcie skończyłem swoją kopię; a oto oryginał \"Właściwości żelaza\". Dziękuję za twą cierpliwość. Jeśli spotkasz Miltona, przeproś go ode mnie za przetrzymanie książki.",
    ["O"] = "Wróć do Brata Kristoffa, na Cathedral Square, i wręcz mu <Właściwości żelaza>.",
    ["T"] = "Powrót do Kristoffa",
  },
  [347] = {
    ["D"] = "Ruda Rethbana nosi nazwę po człowieku, który ją odkrył - Barcie Rethbanie. Przetopiona nie jest tak mocna jak żelazo, ale jej ciemny, jednolity kolor jest wykorzystywany przez niektórych pisarzy w ich barwnikach. Możesz ją znaleźć w Jaskiniach Rethbana na północ stąd.$B$BZwykle mam trochę w magazynie, jednak jesteśmy teraz zbyt zajęci przygotowaniami na ataki orków, by jakąś wydobywać. Poza tym... obecnie w Jaskiniach Rethbana żyją gnolle z Redridge i ich kopacze sami gromadzą tę rudę.$B$BWięc jeśli jej potrzebujesz, $gsam:sama; musisz ją zdobyć.",
    ["O"] = "Zbierz 5 ładunków Rethban Ore i dostarcz je do brata Paxtona, w Northshire Library.",
    ["T"] = "Ruda Rethbana",
  },
  [348] = {
    ["D"] = "Chory...bardzo...bardzo ch-chory...$B$B...zarażony gorączką dławicierni...śmiertelnym w-w-wirusem...$B$B...jedyne lekarstwo...to...to...serce M-m-m-m-mokka Dzikusa...nieuchwytnej białej bestii...$B$B... Znachor Unbagwa...jedyny który może p-p-przywołać.$B$B...odszukaj Unbagwę w jaskini ukrytej na południowym przylądku...$B$B...spiesz się...umieram...umieram...",
    ["O"] = "Znajdź znachora Unbagwa i rozkaż mu przywołać Mokk the Savage. Przynieś Heart of Mokk Finowi Fizracketowi.",
    ["T"] = "Febra Dławiących Cierni",
  },
  [349] = {
    ["D"] = "Hej, $N!$B$BPorozmawiaj z mój przyjaciel Szaman Unbagwa.",
    ["O"] = "Porozmawiaj z Szamanem Unbagwa.",
    ["T"] = "Cierniodława gorączka",
  },
  [350] = {
    ["D"] = "Ten Marzon kontaktował się z Defiasami i jest powiązany z Lescovarem.$B$BPo śmierci VanCleefa i Thredda trudno będzie wymierzyć Lescovarowi sprawiedliwość, bowiem Twoje dowody są niczym bez ich zeznań. Nie wspominając o znajomościach Lescovara i fakcie, że jest szlachcicem. To skutecznie stawia go ponad prawem. $B$BBędziesz $gpotrzebował:potrzebowała; czyjejś pomocy. Nie jestem tym zachwycony, ale znam kogoś, kto może nam pomóc. Triasa znajdziesz w Dzielnicy Handlowej miasta.",
    ["O"] = "Porozmawiaj z Ellingiem Triasem w Stormwind.",
    ["T"] = "Poszukać starego przyjaciela",
  },
  [351] = {
    ["D"] = "$gZnalazłeś:Znalazłaś; jakieś dziwne, metalowe urządzenie o kształcie jajka. Manipulując jednym z pokręteł aktywujesz jajko, które okazuje się być jakimś gnomim wynalazkiem! Z jego środka wydobywa się trzeszczący głos:$B$B<Nazywam się Oglethorpe i mój robot samonaprowadzający zaginął! Zapłacę ci za jego naprawę; proszę, zabierz ten nadajnik do robota! Doskonale, obliczam dla ciebie jego koordynaty! Rozbił się w pobliżu Ziejącej Otchłani w Tanaris!>",
    ["O"] = "Przynieś nadajnik ratunkowy do samonaprowadzającego robota Oglethorpe\'a.",
    ["T"] = "Znajdź OOX-17/TN!",
  },
  [352] = {
    ["D"] = "Great Mammoda. Enormous, she was, with claws and teeth like swords. Now, I was caught off my guard, but I don\'t think being ready would have helped my cause much. One swipe and poof! Darkness. They say I\'m lucky to walk now...$b$bWell, not much enjoyment to be had in hearing that old story now, is there? Anyways, $n, if you\'d like to try yourself against her, the Lady of the Loch,",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [353] = {
    ["D"] = "Burzowe Piki to szanowany krasnoludzki klan znany z dobrego gustu. Nic więc w tym dziwnego, że Gringer Stormpike, góral z Ironforge, mnie właśnie zlecił wykonanie broni.$B$BJest już gotowa, ale... góral Stormpike przebywa daleko stąd, w odległej krainie Loch Modan. Jeśli planujesz podróż na północ, może $gdostarczyłbyś:dostarczyłabyś; mu tę paczkę?$B$BW ostatniej wiadomości, jaką od niego otrzymałem, donosił, że stacjonuje w północnej wieży strażniczej w Loch Modan.",
    ["O"] = "Dostarcz paczkę Stormpike\'a do górala Stormpike\'a z Loch Modan.",
    ["T"] = "Paczka dla Stormpike\'a",
  },
  [354] = {
    ["D"] = "Rodzina Agamandów była najbogatszą rodziną na Tirisfal Glades. Niegdyś pracowałem w ich młynach... nim nadeszła Plaga.$B$BKiedy tu dotarła, Agamandowie zabarykadowali swoje włości i przekonali swych pracowników, by zostali i pomogli zorganizować obronę. Byliśmy głupcami, ale przynajmniej lojalnymi głupcami.$B$BAgamandowie w swojej dumie skazali nas na Plagę... A teraz są jej sługami!$B$BPrzysłuż się Opuszczonym likwidując rodzinę Agamandów! Przysłuż się mi, przynosząc tu ich szczątki!",
    ["O"] = "Przynieś szczątki Gregora, Nissy i Thurmana do Colemana Farthinga z Brill.",
    ["T"] = "Śmierci w rodzinie",
  },
  [355] = {
    ["D"] = "$gDostarczyłeś:Dostarczyłaś; mi szczątki Agamandów i $gnasyciłeś:nasyciłaś; moją żądzę zemsty. Lecz Młyny Agamandów stanowią zagrożenie dla wszystkich Opuszczonych, nie tylko dla mnie.$B$BRozmawiałem z sędzią Sevrenem o twoich czynach przeciwko Agamandom. Pragnie on porozmawiać z tobą osobiście.",
    ["O"] = "Porozmawiaj z sędzią Sevrenem w Brill.",
    ["T"] = "Porozmawiaj z Sevrenem",
  },
  [356] = {
    ["D"] = "Obrońcy Bulwark, oddzielającego Tirisfal od Ziem Plagi zachowują ciągłą czujność. Jednak czasem Plaga prześlizguje się między nimi.$B$BNasze sukcesy w Bulwark zależą od utrzymania jednego frontu. Nie możemy sobie pozwolić na atak od tyłu, ani na odcięcie naszych sił defensywnych od zaopatrzenia.$B$BWspomóż Bulwark. Udaj się na wschód na patrol i zabij każdego sługę Plagi na jakiego trafisz. Szczególną uwagę poświęć farmie Balnirów na wschodzie. Stała się ona przystanią dla intruzów.",
    ["O"] = "Zabij 8 Bleeding Horrors oraz 8 Wandering Spirits i zamelduj się w obozie Linnei.",
    ["T"] = "Tylnia straż",
  },
  [357] = {
    ["D"] = "Na północ, na wyspie na Jeziorze Brightwater, mieszka pewien lisz. Choć jest obdarzonym wolną wolą Opuszczonym, sądzi, że wszyscy inni Nieumarli są sługusami Plagi, rozkazał więc swoim podwładnym atakować każdego, kto tylko się zbliży.$B$BAle ponieważ jest Opuszczonym, Królowa go zechce. A jeżeli jest uzdolnionym nekromantą, jego wiedza będzie dla nas całkiem... użyteczna.$B$BBy poznać jego tożsamość i umiejętności, muszę zobaczyć jego księgę zaklęć. Prześliźnij się do jego obozu i zdobądź ją, po czym przekaż mi!",
    ["O"] = "Przynieś Lich\'s Spellbook do Bethora Icesharda z Undercity.",
    ["T"] = "Tożsamość lisza",
  },
  [358] = {
    ["D"] = "Masowe groby, położone na południowy zachód od leżącego na północy Garren\'s Haunt, powstały, by sprostać... dość znacznej... liczbie zgonów, które nastąpiły w Tirisfal, kiedy Plaga rozpostarła tu swe macki.$B$BJak dotąd tamtejszym zwłokom oszczędzono ożywienia, ale teraz Plaga wysyła tam zgniłoskóre gnolle z zadaniem pozyskania ciał, które zasilą szeregi jej armii. Nie można na to pozwolić!$B$BTwoje zadanie jest podwójne: masz wybić zgniłoskóre z masowych grobów i pozyskać balsamującą posokę, która daje im życie.",
    ["O"] = "Wyrżnij Rot Hide Graverobbers oraz Rot Hide Mongrels.$B$BPrzynieś 8 porcji ich Embalming Ichors do sędzi Sevrena z Brill.",
    ["T"] = "Hieny cmentarne",
  },
  [359] = {
    ["D"] = "Potrzebuję aktualnego raportu z położonego na wschód stąd posterunku Straży Śmierci.$B$BMuszę wiedzieć, czy jeszcze więcej sił Plagi przedostało się obok Bulwark w Tirisfal. Należy zachować czujność - nie możemy zezwolić Pladze na zdobycie tu silniejszego przyczółku!$B$BObierz drogę na południe. Na rozdrożach skręć na wschód, prosto do naszego posterunku. Porozmawiaj ze strażniczką śmierci Linneą. Ma informacje, których potrzebuję.",
    ["O"] = "Porozmawiaj ze strażniczką śmierci Linneą.",
    ["T"] = "Obowiązki Opuszczonych",
  },
  [360] = {
    ["D"] = "Przekaż sędziemu moje słowa. Najszybciej, jak się da.$B$BAha, jeżeli po drodze zobaczysz jakichś sługusów Plagi - zabij. Nie możemy pozwolić, by pałętali się po naszych ziemiach.",
    ["O"] = "Powróć do sędzi Servena z Brill.",
    ["T"] = "Powrót do sędziego",
  },
  [361] = {
    ["D"] = "Oto list napisany przez Thurmana, pierworodnego syna Gregora Agamanda. Zaadresowany jest do Yvette Farthing, lecz wydaje się, że nigdy do niej nie dotarł...",
    ["O"] = "Znajdz Yvette Farthing i dostarcz jej list od Thurmana Agamanda.",
    ["T"] = "Niedostarczony list",
  },
  [362] = {
    ["D"] = "Devlin Agamand był młodszym z dwóch synów Agamandów. Bracia nie mogli bardziej się od siebie różnić. Podczas gdy Thurman był wysoki i uprzejmy, jego młodszy brat był słabowity i ostry w słowach.$B$BKiedy Plaga opanowała Młyny Agamandów, nie zdziwiłem się, słysząc, że Devlin pierwszy uległ presji. Jego wariacki bełkot wciąż słychać nieopodal drogi wiodącej do młynów. $B$BZbieram szczątki Agamandów. Chcę również naszego biednego Devlina. Znajdź go, zniszcz i przynieś mi jego kości.",
    ["O"] = "Zabij Devlina Agamanda i przynieś jego szczątki Colemanowi Farthingowi z Brill.",
    ["T"] = "Nawiedzone młyny",
  },
  [363] = {
    ["D"] = "Rychło w czas żeś się $gobudził:obudziła;! Już mieliśmy cię wrzucać do ognia, razem z całą resztą ciał, ale widzę, że ci się udało!$B$BJestem Mordo, opiekun krypty w Deathknell. A ty nie jesteś już dłużej $gniewolnikiem:niewolnicą; Króla Lisza.$B$BPorozmawiaj z kapłanem cienia Sarvisem. Jest w kaplicy u stóp wzgórza. Wytłumaczy ci, co musisz wiedzieć.",
    ["O"] = "Porozmawiaj z kapłanem cienia Sarvisem.",
    ["T"] = "Gwałtowne przebudzenie",
  },
  [364] = {
    ["D"] = "My, Opuszczeni, toczymy wojnę z Królem Liszem i jego Plagą, armią wskrzeszanych przez nekromantów trupów, paskudnych bestii i udręczonych widm.$B$BPółnocna część wioski została opanowana przez Bezmyślnych. Musimy się z nimi rozprawić! Zniszcz ich! Nie miej litości, choćby kiedyś mogli być naszymi braćmi i siostrami. Upadli nie są niczym więcej niż niewolnikami Króla Lisza!",
    ["O"] = "Kapłan cienia Sarvis chce, byś $gzabił:zabiła; 8 Mindless Zombies oraz 8 Wretched Zombies.",
    ["T"] = "Bezmyślni",
  },
  [365] = {
    ["D"] = "Kogo my tu mamy? No... żółtodziób... Jeśli zamierzasz dowieść swej wartości w oczach Mrocznej Pani, najpierw musisz nauczyć się, jak postępują Opuszczeni.$B$BNa zachodzie znajdziesz farmę. Ludzie obleźli ją niczym robale gnijące ciało. A co gorsza, Szkarłatna Krucjata patroluje okolicę z tamtejszej wieży. Daj temu ścierwu nauczkę; ukradnij 10 dyń, które tak cenią.$B$BKiedy zdobędziesz wszystkie, zabierz je do aptekarza Johaana z Brill.",
    ["O"] = "Ukradnij 10 dyń z farmy na zachodzie, na północ od Deathknell, po czym zabierz je do aptekarza Johaana z Brill.",
    ["T"] = "Pola żalu",
  },
  [366] = {
    ["D"] = "Dawno temu Gunther i ja, oraz obecny Nekromanta Plagi, Thule Ravenclaw, byliśmy przyjaciółmi i studentami. Należeliśmy do Kirin Toru - stowarzyszenia magów w Dalaranie.$B$BGunther i ja padliśmy ofiarą Plagi. Ale myślałem, że pozostał martwy lub tkwi cały czas w szponach Króla Lisza. Dobrze wiedzieć, że jest wolny.$B$BMusimy go mieć w naszych szeregach. Rzuciłem na jego księgę czar. Kiedy ją zobaczy, ukaże mu, że ja również jestem wolny od władzy Króla Lisza. Mam nadzieję, że to go przekona, by do nas dołączył.",
    ["O"] = "Zwróć księgę Guntherowi na jego wyspie.",
    ["T"] = "Zwrot księgi",
  },
  [367] = {
    ["D"] = "Pani Sylvanas wezwała Królewskie Stowarzyszenie Aptekarzy. Mroczna Pani sądzi, że nasza wiedza w połączeniu z nowo zdobytymi umiejętnościami magicznymi stanowi klucz do zabicia Arthasa. Kazała nam spreparować nową zarazę. Zarazę groźniejszą niż jakakolwiek inna choroba na Azeroth. Ona obróci w niwecz Plagę Arthasa. $B$BMoje badania wykazują, że krew bestii może być tym, czego szukamy. Przynieś mi pięć fiolek krwi ogarów ciemności, bym mógł sprawdzić moje przypuszczenia.",
    ["O"] = "Aptekarz Johaan z Brill chce, byś $gzebrał:zebrała; dla niego 5 Vials of Darkhound Blood.",
    ["T"] = "Nowa Plaga",
  },
  [368] = {
    ["D"] = "Kiedy $gwykonywałeś:wykonywałaś; moje poprzednie zlecenie, odkryłem, że aby odpowiednio rozprzestrzenić zarazę, potrzebnych będzie mi więcej składników. Otrucie pechowej ofiary jest dziecinnie proste. Zarażenie całego świata to trochę bardziej skomplikowane zadanie.$B$BBędę potrzebować pięciu łusek tutejszych plugawopłetwych murloków. Znajdziesz je na wybrzeżach na północy i na zachodzie.",
    ["O"] = "Aptekarz Johaan z Brill potrzebuje 5 Vile Fin Scales z murloków w Tirisfal Glades.",
    ["T"] = "Nowa Plaga",
  },
  [369] = {
    ["D"] = "Kiedy $gzbierałeś:zbierałaś; składniki w jednym z moich tomów odkryłem pewien tekst mówiący o starożytnej pladze, która uśmierciła tysiące istnień. Później stwierdzono, że śmiertelny składnik choroby przetrwał w jadzie nocnych przędzarzy.$B$BPrzynieś mi trochę tego jadu, a będę mógł ukończyć mój eksperyment. Chcę sprawdzić, czy czynnik zakaźny jadu podziała z resztą mojej nowej mikstury. Mówi się, że pająki te można znaleźć we wschodniej części Tirisfal Glades.",
    ["O"] = "Aptekarz Johaan z Brill chce, byś $gdostarczył:dostarczyła; mu 4 próbki jadu zdobytych z Vicious Night Web Spider.",
    ["T"] = "Nowa Plaga",
  },
  [370] = {
    ["D"] = "Dokumenty od Egzekutora Arrena zawierają wszystkie szczegóły, których potrzebujemy, by oczyścić nasze ziemie z inwazji ludzi. Zgodnie z tymi informacjami, Szkarłatna Krucjata przydzieliła Kapitana Perrine\'a wraz z brygadą do zniszczonej wieży na południowy zachód z Brill.$B$BZabij Kapitana oraz 3 fanatyków i 3 misjonarzy, a następnie zdaj mi raport.",
    ["O"] = "Egzekutor Zygand z Brill chce, byś $gzabił:zabiła; Kapitana Perrine\'a, 3 Scarlet Zealots oraz 3 Scarlet Missionaries.",
    ["T"] = "Wojna ze Szkarłatną Krucjatą",
  },
  [371] = {
    ["D"] = "Wciąż toczymy wojnę, zaś Szkarłatna Krucjata rośnie w siłę. Raport Egzekutora Arrena mówi, że Szkarłatni Krzyżowcy prowadzą wypady ze zrujnowanej wieży w okolicach farmy Balnirów na południowo-wschodnich Tirisfal Glades, dowodzonej przez Kapitana Vachona.$B$BZabij Vachona oraz 5 Szkarłatnych zakonników. To powinno zadać druzgoczący cios Krucjacie!",
    ["O"] = "Egzekutor Zygand z Brill zlecił ci zabić Kapitana Vachona oraz 5 Scarlet Friars.",
    ["T"] = "Wojna ze Szkarłatną Krucjatą",
  },
  [372] = {
    ["D"] = "Szkarłatna Krucjata atakuje nas z ruin wieży za Spoczynkiem Faola w północnych Tirisfal. Z informacji, które mamy wynika, że tamtejszą załogą dowodzi bezlitosny Kapitan Melrache.$B$BPowierzam ci niebezpieczną misję o wyjątkowym znaczeniu. Zabij Merlache\'a i jego dwóch ochroniarzy w imię Mrocznej Pani.",
    ["O"] = "Egzekutor Zygand z Brill zlecił ci zabicie Kapitana Melrache\'a i jego dwóch ochroniarzy.",
    ["T"] = "Wojna ze Szkarłatną Krucjatą",
  },
  [373] = {
    ["D"] = "Przeszukując ciało Edwina VanCleefa, pośród innych przedmiotów znajdujesz nie wysłany list. Zaadresowano go do Barosa Alexston, miejskiego architekta Stormwind; do Ratusza, Plac Katedralny.$B$BZdaje się, że list napisano i zapieczętowano całkiem niedawno.",
    ["O"] = "Dostarcz Letter to the City Architect do Barosa Alexstona ze Stormwind.",
    ["T"] = "Niewysłany list",
  },
  [374] = {
    ["D"] = "Egzekutor Zygand wspomniał, że $gzabijałeś:zabijałaś; Szkarłatnych Krzyżowców. Roi się od nich na Tirisfal Glades.$B$BVarimathras, doradca Mrocznej Pani, osobiście dogląda tego, by rasa ludzi, ten wrzód na Azeroth, została starta z powierzchni ziemi. Tu, na Tirisfal Gladesl, spotykamy się z jej wyjątkowo irytującą odmianą: Szkarłatnymi Krzyżowcami.$B$BOpuść miasto, $C, i zaatakuj Krzyżowców. Przynieś mi dziesięć ich pierścieni na dowód swej lojalności Varimathrasowi i Mrocznej Pani.",
    ["O"] = "Przynieś 10 Scarlet Insignia Rings do strażnika śmierci Burgessa z Brill.",
    ["T"] = "Dowód zgonu",
  },
  [375] = {
    ["D"] = "Tak mi zimno. Plaga Martwoty pełznie mymi żyłami niczym lodowaty wąż. Wkrótce zatracę swą świadomość. Jednak żadne ponure fatum nie powstrzyma mnie od służby naszej Mrocznej Pani. Gdy nadszedł zew, szyłam pokrowce na zwłoki poległych żołnierzy potężnej armii Sylvanas. $B$BTeraz moje ręce trzęsą się z zimna. Gdybyś $gprzyniósł:przyniosła; mi pięć skór nocarzy i trochę grubej nici, uszyłabym sobie koc. Pomóż mi, $N; pomóż mi, bym mogła dalej służyć sprawie.",
    ["O"] = "Przynieś Gretchen Dedmar z Brill 5 Duskbat Pelts oraz trochę Coarse Thread.",
    ["T"] = "Chłód śmierci",
  },
  [376] = {
    ["D"] = "Moje obowiązki obejmują opiekę nad rannymi wojownikami, szycie zbroi i odzieży oraz asystowanie kapłanowi cienia Sarvisowi we wszystkim, przy czym może potrzebować pomocy.$B$BNa ile go znam, wygląda na to, że zwerbuje cię na potrzeby... polowania na Bezmózgich. Cóż, jeśli $gwolałabyś:wolałabyś; pozostać w jednym kawałku - a nie mam co do tego wątpliwości - może potrafię pomóc. Moje zapasy łap i skrzydeł są na wykończeniu, więc jeśli mi je dostarczysz, znajdę dla ciebie jakąś zbroję. Na południe stąd występuje spora liczba wilków i nietoperzy.",
    ["O"] = "Nowicjuszka Elreth potrzebuje 6 Scavenger Paws oraz 6 Duskbat Wings.",
    ["T"] = "Potępieni",
  },
  [377] = {
    ["D"] = "Jak gdyby zaniedbywanie mieszkańców Duskwood nie było wystarczającym złem, teraz Izba Szlachciców pluje w twarz Radzie Darkshire swą decyzją, by uwięzić Dextrena Warda w Stormwind, miast ściąć tego łajdaka zgodnie z wyrokiem Lorda Ebonlocke\'a.$B$BWard został przyłapany na sprzedawaniu ciał z cmentarza Morbentowi Felowi, a zbrodnia ta karana jest śmiercią. Jednak ci ze Stormwind ogłosili go swoim więźniem.$B$BZabij Warda w Więzieniu Stormwind - i przynieś mi jego dłoń - a zostaniesz wynagrodzony.",
    ["O"] = "Councilman Millstipe z Darkshire chce, byś dostarczył mu dłoń Dextrena Warda.",
    ["T"] = "Zbrodnia i kara",
  },
  [378] = {
    ["D"] = "Dowiodłeś swej lojalności wobec Króla Magniego, $C. Zaś twa nienawiść do szumowin z klanu Dark Iron dorównuje mej własnej.$B$BIstnieje zadanie, które chciałbym własnoręcznie zrealizować, lecz więzy honoru nakazują mi trwać przy Longbraidzie. Roggo zebrał informacje dowodzące uczestnictwa Kama Deepfury\'ego w spisku, który doprowadził do ataku na Thandol Span. To przez matactwa Deepfury\'ego Longbraid stracił swą rodzinę.$B$BZ przyczyn politycznych Deepfury przetrzymywany jest w Więzieniu Stormwind. Chcę jego śmierci, $N. Za Longbraida! Przynieś mi jego głowę!",
    ["O"] = "Motley Garmason pragnie, by przynieść mu do Dun Modr głowę Kama Deepfury\'ego.",
    ["T"] = "Gniew trawi głęboko",
  },
  [379] = {
    ["D"] = "Chcesz źródła zasilania. Mogę ci pomóc. A wiesz, czego ja chcę? Chcę czegoś do picia! Przynieś mi pięć Bukłaków Włóczęgów, a otrzymasz 4711-FTZ.$B$BTeraz... pomyślmy, gdzie możesz znaleźć Bukłaki Włóczęgów! Czemu nie podejdziesz do jednego z wędrownych Wastewander, wałęsających się na wschód stąd i nie poprosisz o jeden? $B$BDaj znać, jak podziałało.",
    ["O"] = "Przynieś 5 Wastewander Water Pouches do Chief Engineer Bilgewhizzle\'a z Gadgetzanu.",
    ["T"] = "Ugaś to pragnienie",
  },
  [380] = {
    ["D"] = "Jednym z naszych największych problemów jest pozyskiwanie surowców naturalnych, niezbędnych nam do przetrwania. Złoto było rzadkością, nawet gdy Przymierze było u szczytu swej potęgi.$B$BNa północny zachód stąd znajduje się kopalnia złota, którą opanowały pająki. Potrzebujemy złota z tej kopalni, nie możemy jednak skutecznie go wydobywać, póki one snują tam swe sieci. Nie dysponuję dostateczną liczbą ludzi, których mógłbym skierować do tego zadania, musimy więc realizować je etapami.$B$BUdaj się tam, $N i zobacz, co możesz dla nas zrobić.",
    ["O"] = "Executor Arren chce, byś zabił 10 Young Night Web Spiders i 8 Night Web Spiders.",
    ["T"] = "Pieczara nocnych przędzarzy",
  },
  [381] = {
    ["D"] = "Będziesz $gzadowolony:zadowolona; wiedząc, iż czynimy postępy w kopalni; w znacznej mierze dzięki twym wysiłkom. Możemy teraz skupić się na innych kwestiach.$B$BMoi zwiadowcy donoszą, że oddział Szkarłatnej Krucjaty buduje obóz na południowy wschód stąd. Szkarłatna Krucjata to nikczemna organizacja, której członkowie polują na nas i nie spoczną, nim każdy nieumarły - z Plagi Króla Lisza czy nie - nie zostanie unicestwiony. Musimy zaatakować pierwsi!$B$BBądź $gostrożny:ostrożna;, ich bezbożny zapał czyni z nich groźnych przeciwników.",
    ["O"] = "Przynieś egzekutorowi Arrenowi 12 Scarlet Armbands zdartych ze Scarlet Converts lub Scarlet Initiates.",
    ["T"] = "Szkarłatna Krucjata",
  },
  [382] = {
    ["D"] = "Listy od moich przełożonych z Brill donoszą, że agent Szkarłatnej Krucjaty wyruszył ze Szkarłatnego Klasztoru i skierował się tutaj, do Deathknell. Według doniesień, posłaniec posiada przy sobie ważne informacje. Nie znam bliższych szczegółów, jednak czymkolwiek są te dane, musimy je zdobyć!$B$BSpośród osób którymi dysponuję, ty, $N, jesteś najbardziej $gkompetentny:kompetentna; do wykonania tego zadania. Znajdź tego posłańca i przynieś mi wszystkie informacje, jakie znajdziesz.",
    ["O"] = "Zabij posłańca Mevena Korgala w obozie Krucjaty; następnie wróć do egzekutora Arrena ze wszystkimi informacjami, na jakie natrafisz.",
    ["T"] = "Czerwony posłaniec",
  },
  [383] = {
    ["D"] = "Trzeba je zabrać do mojego przełożonego, egzekutora Zyganda z Brill. Mając te informacje będziemy mogli zadać decydujący cios Szkarłatnej Krucjacie. Tu, w Deathknell, $gokazałeś się użyteczny:okazałaś się użyteczna;, potrzebuję jednak kogoś, kto dostarczy pisma Zygandowi, a sądzę, że on potrafi znaleźć dla ciebie odpowiedniejsze zajęcie.$B$BUdaj się drogą wychodzącą na północ z Deathknell. Wkrótce po wkroczeniu do właściwego Tirisfal natrafisz na rozdroże. Wybierz wschodnie odgałęzienie i ciągle idź na wschód. Po drodze miniesz Cold Hearth Manor.",
    ["O"] = "Dostarcz Scarlet Crusade Documents do egzekutora Zyganda z Brill.",
    ["T"] = "Ważne informacje",
  },
  [384] = {
    ["D"] = "Stali bywalcy gospody niczego nie cenią sobie bardziej niż żeberka z dzika w sosie piwnym! Problem w tym, że dostarczający mi zapasy miejscowy łowca wstąpił do Armii Królewskiej, by wesprzeć Przymierze na wojennym froncie.$B$BMoże ty zechcesz mi pomóc? Jeśli przyniesiesz mi sześć żeber skalnego dzika oraz Rhapsody Malt z tutejszej gospody, zdradzę ci rodzinny przepis na słynne żeberka, nie wspominając o darmowej porcji! Sekret tkwi w piwie!",
    ["O"] = "Ragnar Thunderbrew z Kharanos potrzebuje 6 Crag Boar Ribs oraz kufel Rhapsody Malt.",
    ["T"] = "Żeberka z dzika w sosie piwnym",
  },
  [385] = {
    ["D"] = "Loch Modan przyciąga wielu łowców perspektywą polowania na nasze słynne krokodyle. Zawsze znajdą się kupcy zainteresowani przeróbką ich skór na odzież i zbroje; podobnie jak smakosze krokodylego mięsa.$B$BKrokodyle są groźnymi przeciwnikami, władającymi położonymi na jeziorze wyspami, więc choć handlujemy ich skórą i mięsem, nie odbywa się to na masową skalę. Nie pozwól jednak się zniechęcić, siłowanie się ze szczękami tych bestii to prawdziwe przeżycie.$B$BPrzynajmniej do czasu...",
    ["O"] = "Zdobądź 5 kawałków Crocolisk Meat oraz 6 Crocolisk Skins dla Mareka Ironhearta z Farstrider Lodge.",
    ["T"] = "Polowanie na krokodyle",
  },
  [386] = {
    ["D"] = "Targorr the Dread służył Gath\'Ilzoggowi jako naczelny kat. Jego metody były bezlitosne, nawet jak na standardy śmierdzących orków. Dzielnie walczący w obronie królestwa ludzie byli przezeń dla kaprysu torturowani. Obecnie skazany na śmierć przebywa w Więzieniu Stormwind. Jednak coś jest nie w porządku. Jeden z tych biurokratów, szlachciców, odwleka jego egzekucję. Toczy się jakaś nieczysta gra.$B$BSkończ z Targorrem the Dreadem, $N. Udaj się do Więzienia i zetnij mu głowę, nim zwycięży zdrada.",
    ["O"] = "Przynieś głowę Targorr the Dread do Guarda Bertonia z Lakeshire.",
    ["T"] = "Pięknym za nadobne",
  },
  [387] = {
    ["D"] = "Bunt musi zostać stłumiony! Potrzebuję twojej pomocy. Stracę pracę, jeśli wieść o opanowaniu więzienia się rozniesie! Ktoś musiał maczać w tym palce, jeśli chcesz znać moją opinię. Jednak dla bezpieczeństwa Stormwind najważniejsze w tym momencie jest zmuszenie tych więźniów do posłuszeństwa.$B$BKarą za bunt jest śmierć. Zabij kilku z tych wykolejeńców! To powinno przywrócić nam kontrolę nad sytuacją.",
    ["O"] = "Warden Thelwater chce śmierci 10 Defias Prisoners, 8 Defias Convicts i 8 Defias Insurgents, przebywających w Więzieniu.",
    ["T"] = "Zdław rebelię",
  },
  [388] = {
    ["D"] = "Gorycz płynie mymi żyłami niczym zimna rzeka. Mój wnuczek, Mac, był takim dobrym chłopcem. Miał tylko czternaście lat. Kiedy armię posłano na front, Mac chwycił za broń, by bronić miasta. Był strażnikiem w Więzieniu, gdzie zamknięto gang Defiasów.$B$BMac udzielił nagany kilku więźniom, którzy darli swe wełniane koce na chusty, symbol swego gangu. Za to dźgnięto go nożem w plecy.$B$BPragnę zemsty. Przynieś mi 10 ich cennych Wełnianych Chust. Są koloru krwi.",
    ["O"] = "Nikova Raskol ze Stormwind pragnie, byś zdobył 10 Red Wool Bandanas.",
    ["T"] = "Kolor krwi",
  },
  [389] = {
    ["D"] = "VanCleef i ja byliśmy członkami Gildii Kamieniarzy. Naszym głównym projektem była powojenna odbudowa Stormwind.$B$BGdy wypełniliśmy swój obowiązek, oszukano nas. Arystokracja odmówiła zapłaty za naszą pracę. Niektórym z wyżej postawionych członków gildii zaproponowano posady rządowe, lecz VanCleef odmówił objęcia takowej z lojalności względem wszystkich Kamieniarzy. Wszczął bunt i opuścił miasto, przysięgając zemstę.$B$BJego doradca, Bazil Thredd, może wiedzieć więcej o planach VanCleefa. Jest przetrzymywany w Więzieniu.",
    ["O"] = "Udaj się do Stockade porozmawiać z nadzorcą Thelwaterem.",
    ["T"] = "Bazil Thredd",
  },
  [390] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [391] = {
    ["D"] = "Wyjaśnijmy sobie jedno; nie ufam ci $N. Jednak w obecnej sytuacji nie ma to większego znaczenia.$B$BSłuchaj więc, jak będzie: zejdziesz tam i utniesz sobie pogawędkę z Threddem. Następnie, jeśli naprawdę jesteś z nami, zabijesz go i po skończeniu roboty przyniesiesz mi jego głowę. A jeśli okaże się, że jesteś po jego stronie i nie wyjdziesz... kiedy cię znajdziemy, zdechniesz razem z resztą tego robactwa.",
    ["O"] = "Zabij Bazila Thredda i przynieś jego głowę Nadzorcy Thelwaterowi z Więzienia.",
    ["T"] = "Buntownicy z Więzienia",
  },
  [392] = {
    ["D"] = "W ciągu pierwszych lat odsiadki Thredda nikt go nie odwiedzał. Uznałem, że Bractwo porzuciło go, kiedy stracił dla nich swą użyteczność.$B$BW każdym razie kilka miesięcy temu sytuacja uległa zmianie; zaczął przyjmować regularne wizyty... jedną, góra dwie tygodniowo. Odwiedzał go dziwny człowiek - taki cichy typ. Podejrzewałem coś, ale wszystkie papiery miał w porządku.$B$BZ dokumentów wynikało, że nazywa się Maelik; oto jego opis. Nie sądzę, by miał jeszcze kiedykolwiek odwiedzić Thredda.",
    ["O"] = "Zanieś Sealed Description of Thredd\'s Visitor do Barosa Alexstona ze Stormwind.",
    ["T"] = "Intrygujący gość",
  },
  [393] = {
    ["D"] = "Naprawdę, nie mam pojęcia $N. Istnieje jednak ktoś, kto może ci pomóc i tak się składa, że jest mi winien przysługę - cóż, nie wnikajmy. To mistrz Mathias Shaw z SI:7, można go znaleźć w koszarach na starymmieście. Shaw macza palce w większości szemranych interesów w tym mieście.$B$BJeśli ktokolwiek będzie wiedział, to właśnie on.",
    ["O"] = "Zanieś Sealed Description of Thredd\'s Visitor do mistrza Mathiasa Shawa ze Stormwind.",
    ["T"] = "Cienie przeszłości",
  },
  [394] = {
    ["D"] = "Znajdź Shawa na starym mieście. Powiedz mu, że Lescovar nie stanowi już zagrożenia i opisz swój udział w unieszkodliwieniu spisku Lorda, wymierzonego przeciw miastu. Jestem pewien, że będzie dumny z obecności kolejnego bohatera między mieszkańcami Stormwind.$B$BJest więcej niż pewne, że wyśle cię na spotkanie z księciem, albo jakimś innym szlachcicem. $N, nie daj sobie namieszać w głowie. Arystokratom może się wydawać, że rządzą miastem jak im się podoba, pewne rzeczy jednak pozostają poza ich zasięgiem.",
    ["O"] = "Porozmawiaj z Mathiasem Shawem w Stormwind.",
    ["T"] = "Głowa bestii",
  },
  [395] = {
    ["D"] = "Ach, prawie zapomniałem. Kiedy cię nie było, zajrzał tu Alexston; życzył sobie z tobą rozmawiać. Jestem pewien, że pragnie poinformować szlachtę o występkach Bractwa Defias.$B$BMała rada: jeśli będą zainteresowani, złożę szczegółowe zeznania, lecz to z twojej ręki zginął Lescovar. Zaufaj mi. Jestem... zaznajomiony... z biegiem takich spraw.$B$BA jeśli chodzi o Triasa... cóż, po prostu nie rozmawiaj o nim z nikim... nigdy... jeśli wiesz co to znaczy trzymać język za zębami.",
    ["O"] = "Porozmawiaj z Barosem Alextonem w Stormwind.",
    ["T"] = "Koniec Bractwa",
  },
  [396] = {
    ["D"] = "Przygotowałem raport dla króla. Sądzę, że to ty $gpowinieneś:powinnaś; go dostarczyć, wraz z wynikami twoich pozostałych odkryć. Nie martw się, nie ma wątpliwości, że doceni cię za spełnienie powinności wobec ludu Stormwind.$B$BAudiencja wkrótce się rozpocznie, więc $gpowinieneś:powinnaś; się pospieszyć; do Twierdzy Stormwind jest kawałek drogi.",
    ["O"] = "Dostarcz raport Barosa Alexstona o Bractwie Defias do Króla Variana Wrynna w Twierdzy Stormwind.",
    ["T"] = "Audiencja u króla",
  },
  [397] = {
    ["D"] = "Słyszałem, że Lord Wishock zasmakował w swoim napoju.$B$BDobrze nam $gsłużyłeś:służyłaś;, $N. Dzięki tobie czarnoksiężnicy ze Stormwind będą mogli bez przeszkód oddawać się swojej sztuce. W podzięce za twe wysiłki przygotowałem dla ciebie specjalny prezent. Porozmawiaj z moim sługą, Zggim, i odbierz swoją nagrodę.",
    ["O"] = "Porozmawiaj ze Zggim, sługą Zardeth the Blackclaw, aby odebrać swoją nagrodę.",
    ["T"] = "Dobrze nam służyłeś",
  },
  [398] = {
    ["D"] = "Poszukiwany: Maggot Eye!$B$BObrzydliwa bestia, nawet na standardy gnolli, Maggot Eye został skazany za swoje przestępstwa przeciwko nieumarłym. Ten wstrętny łajdak kradł zwłoki do armii Króla Lisza. Maggot Eye był ostatnio widziany grabiąc tereny blisko Garren\'s Haunt na północ od Brill.$B$BMiasto Brill niniejszym oferuje nagrodę zdolnej duszy, która wykona egzekucję. Pokaż egzekutorowi Zygandowi łapę łajdaka, kiedy śmierć zostanie wymierzona.$B$BŁaska jest dla słabych.",
    ["O"] = "Zabij Maggot Eye i wróć do egzekutora Zyganda w Brill z jego łapą po nagrodę.",
    ["T"] = "Poszukiwany: Maggot Eye",
  },
  [399] = {
    ["D"] = "Zdaje się, że wieki minęły od czasu, gdy byłem chłopcem pracującym na polach Westfall. Mówią, że nie można zawrócić z raz obranej drogi i mają rację. W moim przypadku nawet podwójną, gdyż mój rodzinny dom został spalony i opanowany przez złodziei.$B$BRozmawiałem z ojcem o losie niektórych moich rzeczy, w tym mojego pierwszego kompasu. Nie był w stanie ich ocalić. Jednakże wspomniał też, że powinny być ukryte na farmie.$B$BFarma Alexstonów leży na zachód od Sentinel Hill. Może $gmógłbyś:mogłabyś; tam pójść i odzyskać go dla mnie?",
    ["O"] = "Udaj się do domu Barosa Alexstona w Westfall i poszukaj jego kompasu, następnie przynieś mu go na Cathedral Square w Stormwind.",
    ["T"] = "Skromne początki",
  },
  [400] = {
    ["D"] = "Beldin Steelgrill prowadzi tutejszy warsztat i jest najlepszym na świecie inżynierem od czołgów parowych! Niestety, nie odpuszcza swoim narzędziom. Przysiągłbym, że łamie więcej kluczy nastawnych, niż jesteśmy w stanie mu dostarczyć!$B$BWłaśnie zrealizowaliśmy jego ostatnie zlecenie na narzędzia. Jeśli mu je dostarczysz, jestem pewien, że stosownie wynagrodzi twój wysiłek.$B$BJego sklep, Składzik Steelgrilla, znajduje się na północno-wschodnich obrzeżach Kharanos. Pełni też funkcję lokalnej speluny dla weteranów pilotów czołgów parowych, więc kiedy tam będziesz, trzymaj oczy otwarte w poszukiwaniu okazji.",
    ["O"] = "Dostarcz Steelgrill\'s Tools do Beldina Steelgrilla.",
    ["T"] = "Narzędzia dla Steelgrilla",
  },
  [401] = {
    ["D"] = "Już prawie skończyłam tłumaczyć tą notatkę. Jeśli wrócisz za chwile powinna być gotowa.",
    ["O"] = "Poczekaj chwilę, potem porozmawiaj z Sirra Von\'Indi ponownie.",
    ["T"] = "Poczekaj na Sirra aż skończy",
  },
  [403] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Strzeżona baryłka Grzmocącego",
  },
  [404] = {
    ["D"] = "Plaga przeniknęła w głąb Tirisfal Glades i zaatakowała pola na zachód od Brill, nieopodal starego mostu.$B$BUdaj się tam i zniszcz wszystkie gnijące trupy oraz obdarte zwłoki, jakie napotkasz. Rozrzuć ich kości i przynieś ich gnijące szpony, a Straż Śmierci cię wynagrodzi.",
    ["O"] = "Przynieś 7 Putrid Claws do strażnika śmierci Dillingera z Brill.",
    ["T"] = "Brudna robota",
  },
  [405] = {
    ["D"] = "Bethor Iceshard, potężny mag wysokiej rangi mieszkający na południu, w Undercity, nakazał, bym przysłał mu agenta, który dowiódł swej wartości w walce z Plagą. Ty będziesz tym agentem, $N.$B$BPrzekaż Bethorowi te rozkazy. Wtedy przedstawi ci twoje zadanie. Nie znam szczegółów, lecz wiąże się ono ze zwerbowaniem pewnego samowolnego Lisza. I będzie bardzo niebezpieczne.$B$BTak więc przygotuj się, $C. Nie wolno ci zawieść.$B$BBethora znajdziesz w Dzielnicy Magii, w Undercity.",
    ["O"] = "Przekaż Sevren\'s Orders do Bethora Icesharda z Undercity.",
    ["T"] = "Lisz marnotrawny",
  },
  [406] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [407] = {
    ["D"] = "Nieszkodliwe dynie, prawda? A przynajmniej na takie wyglądają. Jeśli mamy odeprzeć natarcie Arthasa z północy i inwazję ludzi z południa, musimy zacząć wykorzystywać pełen potencjał naszego daru martwoty.$B$BDzięki odrobinie pomysłowości prosta dynia posłuży celom Mrocznej Pani. Nafaszerowana moim najnowszym eliksirem zapewni nam całkiem sporo radości.$B$BSchwytano kolejnego Szkarłatnego fanatyka; obecnie przetrzymywany jest w piwnicy tawerny \'Gallow\'s End\'. Zanieś tę dynię temu głupcowi.",
    ["O"] = "Zabierz Laced Pumpkin do Captured Scarlet Zealot, więzionego w piwnicach Gallow\'s End Tavern.",
    ["T"] = "Pola żalu",
  },
  [408] = {
    ["D"] = "Okolice Młynów Agamandów stały się przyczółkiem Plagi. Jej najsilniejszym punktem jest krypta rodzinna Agamandów, gdzie ma swoją kwaterę ich lokalny dowódca, szkielet imieniem Kapitan Dargol. Posługując się nekromancją wskrzesił on przodków Agamandów i chce wykorzystać ich przeciwko nam.$B$BTen plan nie może się powieść i to ty musisz temu zapobiec. Udaj się do krypty i pokonaj ożywionych przodków Agamandów.$B$BA, tak, przynieś mi też czaszkę Kapitana Dargola.",
    ["O"] = "Zabij 8 Wailing Ancestors i 8 Rotting Ancestors.$B$BZabij też Kapitana Dargola i przynieś jego czaszkę sędziemu Sevrenowi z Brill.",
    ["T"] = "Rodzinna krypta",
  },
  [409] = {
    ["D"] = "Powiadasz, że nie jesteś $gspętany:spętana; wolą Króla Lisza, zaś urok, który Bethor rzucił na moją księgę, ma to potwierdzać. Lecz zanim ci uwierzę, musisz dowieść, że naprawdę jesteś wrogiem Plagi.$B$BNa skraju południowego wybrzeża tej wyspy znajduje się stary, zakrwawiony ołtarz. Jest wykorzystywany przez potężną przedstawicielkę Plagi, Lillith Nefarę.$B$BWeź świecę przywoływań z tej oto skrzyni. Zapal ją na ołtarzu, a Lillith się przebudzi. Zniszcz ją, a uwierzę, że jesteś wrogiem Króla Lisza.",
    ["O"] = "Zdobądź Candle of Beckoning.$B$BPrzyzwij Lillith Nefarę i zabij ją.$B$BWróć do Gunthera, na jego wyspę.",
    ["T"] = "Dowód lojalności",
  },
  [410] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Drzemiący cień",
  },
  [411] = {
    ["D"] = "Zabierz ten klejnot pustki do mojego starego kamrata Bethora. Umożliwi nam rozmowę... a mam mu wiele do powiedzenia.",
    ["O"] = "Przynieś Nether Gem do Bethora Icesharda z Undercity.",
    ["T"] = "Powrót lisza marnotrawnego",
  },
  [412] = {
    ["D"] = "Z dalszych analiz sytuacji w Gnomereganie wynika, że nie tylko nie udało się nam wyplenić troggów, ale także przemieniliśmy większość gnomiej rasy w przerażające, bezmyślne, złośliwe, trędowate gnomy.$B$BOzzie i ja planujemy odwrócić ten straszliwy efekt przy pomocy naszego najnowszego wynalazku: Rekombobulatora. Maszyna jest niemal gotowa, lecz koniecznie potrzebne nam są zębatki stabilizujące oraz układy żyromechaniczne. Zdobądź dla nas kilka od trędowatych gnomów, przebywających u bram Gnomereganu.",
    ["O"] = "Przynieś 8 Restabilization Cogs and 8 Gyromechanic Gears do Razzle\'a Sprysprocketa z Kharanos.",
    ["T"] = "Operacja rekombobulacja",
  },
  [413] = {
    ["D"] = "Chciałbym, aby mój brat Wellart spróbował mojego najnowszego wynalazku - migoczącego piwa. Jest góralem stacjonującym w południowej wieży strażniczej, jednej z dwóch wież na granicy z Loch Modan.$B$BMoże nie jest piwowarem, jak reszta rodziny Barleybrewerów, ale kocha rozmaite trunki i jestem pewien, że ten przypadnie mu do gustu.$B$BMożesz dostarczyć mu ode mnie tę beczkę?",
    ["O"] = "Zanieś Barrel of Shimmer Stout do górala Barleybrewa.",
    ["T"] = "Migoczące piwo",
  },
  [414] = {
    ["D"] = "Wypiłem więcej tego migoczącego piwa, które zrobił mój brat - jest wspaniałe! Chcę, by spróbował go mój znajomy góral. Nazywa się Kadrell; zazwyczaj patroluje teren Thelsamaru nad Loch Modan.$B$BAby dotrzeć do miasta, udaj się tunelem na południowy wschód, a kiedy tylko ścieżka się rozwidli, skręć na północny wschód. Dojdziesz tą drogą prosto do Thelsamaru.$B$BDaj góralowi Kadrellowi tę beczkę piwa i przekonaj się, co o nim myśli!",
    ["O"] = "Zanieś Cask of Shimmer Stout do górala Kadrella w Loch Modan.",
    ["T"] = "Piwo dla Kadrella",
  },
  [415] = {
    ["D"] = "Rejold Barleybrew z Wioski Brewnall pytał o ciebie.$B$BChce pogadać z tobą o nowym napoju, który niedawno uwarzył... wspomniał coś o tym, że bardzo mu $gpomogłeś:pomogłaś;. Może $gchciałbyś:chciałabyś; wrócić do wioski i przekonać się, co ma ci do powiedzenia.$B$BSądzę, że znalazłby się tam dla ciebie jakiś darmowy trunek...",
    ["O"] = "Porozmawiaj z Rejoldem Barleybrewem.",
    ["T"] = "Nowe piwo Rejolda",
  },
  [416] = {
    ["D"] = "Na zachodzie przeżywamy prawdziwy najazd szkodników. Koboldy - szczury tunelowe przeniosły się na podgórze, wykopały sobie nory i kalają nasze ziemie swoim plugastwem!$B$BChcemy je usunąć. Zapoluj na nie, przynieś mi ich uszy i odbierz nagrodę.$B$BKoboldy - szczury tunelowe można spotkać na zachód od Thelsamaru, w norach rozsianych wzdłuż podnóża gór.",
    ["O"] = "Przynieś 12 Tunnel Rat Ears do górala Kadrella z Thelsamaru.",
    ["T"] = "Łapanie szczurów",
  },
  [417] = {
    ["D"] = "Hildelve napisał w swoim dzienniku, że został zaatakowany przez Mangeclawa, \"olbrzymiego Lodowego Pazurzastego Niedźwiedzia\". Odpędził bestię, ale ta przedtem okrutnie go poturbowała.$B$BSądząc po stanie ciała Hildelve\'a, Mangeclaw musiał później wrócić i go zabić.$B$BJednakże Hildelve zapisał w swoim dzienniku swoje ostatnie życzenie:$B$BJest nim zemsta na Mangeclaw.",
    ["O"] = "Zabij Mangeclawa.$B$BPrzynieś Mangy Claw i Hildelve\'s Journal do pilota Hammerfoota.",
    ["T"] = "Zemsta pilota",
  },
  [418] = {
    ["D"] = "Tu, w Thelsamarze, nigdy nie brakuje pustych brzuchów - dzieci ganiają tam i z powrotem, a pracownicy z wykopalisk schodzą się po ciężkim dniu pracy. Jesteśmy znani z naszych krwistych kiełbasek. Nie wydaje mi się, żebyś ich kiedyś $gpróbował:próbowała;?$B$BNie $gpróbowałeś:próbowałaś;? No więc tutaj zapracowuje się na swój posiłek i nie myśl, że skoro jesteś $gtakim wspaniałym:taką wspaniałą; $C, zrobię dla ciebie wyjątek.$B$BPotrzebuję niedźwiedziego mięsa, jelit dzika na osłonę i posoki pająka jako przyprawy. Przynieś mi te rzeczy, a gotowanie zostaw Vidrze!",
    ["O"] = "Przynieś 3 kawałki Bear Meat, 3 Boar Intestines i 3 Spider Ichor do Vidry Hearthstove z Thelsamaru.",
    ["T"] = "Thelsamarskie krwiste kiełbaski",
  },
  [419] = {
    ["D"] = "Mój przyjaciel i zarazem pilot czołgu parowego, Mori Hildelve, zaginął w górach. Szukaliśmy rzadkiej rudy, potrzebnej do sporządzenia wysokiej jakości prochu, ale podczas naszych poszukiwań Hildelve wjechał swoją maszyną na strome wzgórze i ją zepsuł!$B$BWciąż przekonany, że w tych górach jest ruda, kazał mi pilnować maszyn, a sam ruszył kontynuować poszukiwania na piechotę.$B$BOd tego czasu upłynęło kilka dni. Słyszałem zwierzęce ryki, dobiegające nocą ze wzgórz. Mori jest twardy jak skała, ale martwię się o niego.$B$BProszę, $N. Znajdź go.",
    ["O"] = "Znajdź Pilota Hildelve\'a.",
    ["T"] = "Zaginiony pilot",
  },
  [420] = {
    ["D"] = "Troggi z tunelu są bardzo wrogo nastawione i nie wahają się atakować przemierzających go podróżników. Lecz ty wyglądasz na dość $gtwardego:twardą;, więc prawdopodobnie nic ci nie grozi.$B$BWskazówki? Jeśli chcesz porozmawiać z Senirem, znajdziesz go w Kharanos.$B$BPrzejdź przez tunel, a kiedy znajdziesz się po drugiej stronie, po prostu trzymaj się drogi; doprowadzi cię prosto do Kharanos.",
    ["O"] = "Dostarcz raport Grelina Senirowi Whitebeardowi z Kharanos.",
    ["T"] = "Obserwacje Senira",
  },
  [421] = {
    ["D"] = "Lady Sylvanas zleciła Varimathrasowi zadanie podbicia ludzkich i krasnoludzkich ziem na południu.$B$BJednak ten głupiec, Arugal - szarlatan z Dalaranu, obecnie przeklęta bestia z Twierdzy Shadowfang - pozwolił swoim lekkomyślnym zaklęciom spustoszyć strategiczną fortecę Silverpine Forest.$B$BPotrzebuję kogoś biegłego w walce, by pomógł posprzątać bałagan po Arugalu. Dowiedź swej wartości zabijając 5 worgenów białych skalpów. Te nikczemne bestie można znaleźć zaraz za drogą, w dole, u stóp wzgórza.",
    ["O"] = "Dalar Dawnweaver z Sepulcher chce, byś $gzabił:zabiła; 5 Moonrage Whitescalps.",
    ["T"] = "Dowiedź swej wartości",
  },
  [422] = {
    ["D"] = "W głowie mi się nie mieści, jakim cudem Arugal zdobył akceptację Kirin Tor. Jego zaklęcia są równie łatwe do przejrzenia, co mydlana bańka.$B$BTeraz chodzi o to, by dowiedzieć się, którym dokładnie rodzajem magii posłużył się Arugal. Wówczas będę mógł odwrócić jego własne czary przeciw niemu i zabezpieczyć Silverpine Lekarstwo Arugala. Znajdziesz je w tamtych księgach.",
    ["O"] = "Zdobądź Remedy of Arugal dla Dalara Dawnweavera z Sepulcher.",
    ["T"] = "Szaleństwo Arugala",
  },
  [423] = {
    ["D"] = "Analiza pracy Arugala potwierdziła moje najgorsze podejrzenia. Ten stary pisarzyna nie miał dość kwalifikacji, by opróżniać nocniki w Dalaranie, a co dopiero w pojedynkę reprezentować Kirin Tor w jej najstraszliwszej godzinie. Głupcy!$B$BArugal używał zaczarowanych przedmiotów, by wzmacniać swą słabowitą magię. Muszę własnoręcznie zbadać te przedmioty. Zapuść się w las i poluj na księżycowych żarłoków i księżycowe czarne dusze, dopóki nie uzbierasz dostatecznej ilości ich kajdan do moich badań. Te plugawe bestie znajdziesz na północ i wschód stąd.",
    ["O"] = "Przynieś 6 Glutton Shackles i 3 Darksoul Shackles do Dalara Dawnweavera z Sepulcher.",
    ["T"] = "Szaleństwo Arugala",
  },
  [424] = {
    ["D"] = "Odkrycie mrocznych tajemnic, kryjących się za użytymi przez Arugala zaklęciami, zajmie mi w rzeczy samej więcej czasu, niż się spodziewałem.$B$BChcę, byś w międzyczasie $gzajął:zajęła; się drobnym problemem, na który natrafili nasi Umarli Tropiciele. Wygląda na to, że magia Arugala przeniknęła do Kopalni Elem w górach na południowy wschód stąd.$B$BTa kopalnia byłaby dobrym źródłem surowców dla ofensywy Varimathrasa.$B$BChcę, byś $gpozbawił:pozbawiła; głowy skażonego zarządcę kopalni, Grimsona Bladego. Po jego śmierci kopalnia będzie nasza.",
    ["O"] = "Zabij Grimson the Pale i przynieś jego głowę Dalarowi Dawnweaverowi z Sepulcher.",
    ["T"] = "Szaleństwo Arugala",
  },
  [425] = {
    ["D"] = "Mój brat Quinn i ja otrzymaliśmy zadanie przeprowadzenia zwiadu w Silverpine Forest i przekazania naszych spostrzeżeń wysokiemu egzekutorowi Hadrecowi. Ale nie zaszliśmy zbyt daleko - gdy przemierzaliśmy tę farmę, zostaliśmy zaatakowani przez ghula, Ivara Plugawego.$B$BUciekliśmy mu, ale Quinn odniósł poważną ranę. Dzięki miksturze, którą mu $gdałeś:dałaś;, ma się już lepiej, ale Ivar może wrócić, nim Quinn do końca wyzdrowieje.$B$BZabij Ivara, by Quinn miał wystarczająco dużo czasu, by wydobrzeć. Ghul czai się zwykle za tamtą stodołą, czekając na chwilę mojej nieuwagi.",
    ["O"] = "Zabij Ivar the Foul i przynieś jego głowę do Rane Yorick z Ivar Patch.",
    ["T"] = "Plugawy Ivar",
  },
  [426] = {
    ["D"] = "Plaga próbuje stworzyć bazę w Młynach Agamandów. Jeśli się im to uda, będą mogli organizować dalsze ataki na Tirisfal.$B$BWydano rozkazy. Plaga z młynów musi zostać zniszczona.$B$BUdaj się tam. Zbierz strzałkowate żebra z żołnierzy i czaszki z kościstych zaklinaczy.$B$BBy dotrzeć do młynów, podążaj drogą na zachód. Na pierwszym rozwidleniu za mostem skręć na północ i trzymaj się tego kierunku. Gdy zobaczysz wiatraki, rozpocznie się bitwa.",
    ["O"] = "Zdobądź 5 Notched Ribs i 3 Blackened Skulls, a następnie wróć do strażnika śmierci Dillingera z Brill.",
    ["T"] = "Opanowanie młynów",
  },
  [427] = {
    ["D"] = "Dokumenty, które dostarczył nam Egzekutor Arren, stanowią przełom, którego potrzebowaliśmy w naszej wojnie z nikczemną Szkarłatną Krucjatą. Znamy teraz ich dokładne pozycje w Tirisfal Glades.$B$BAle Straż Śmierci ma większe problemy. Armia Króla Lisza rośnie w siłę z każdym dniem. Potrzebujemy kogoś z <inicjatywą>, kogoś takiego jak ty, by wpędzić Krucjatę do grobu.$B$BUdowodnij mi swą zdolność do służby Mrocznej Pani, udając się na zachód, do wieży za farmą Sollidenów, i zabijając 10 Szkarłatnych wojowników.",
    ["O"] = "Egzekutor Zygand z Brill chce, byś $gzabił:zabiła; 10 Scarlet Warriors.",
    ["T"] = "Wojna ze Szkarłatną Krucjatą",
  },
  [428] = {
    ["D"] = "Kilka tygodni temu dwoje naszych Umarłych Tropicieli- Rane i Quinn Yorick - zostało wysłanych na rekonesans północnej części Silverpine Forest. Słuch po nich zaginął.$B$BMogli paść ofiarą Plagi, lecz jeśli to prawda, chcę mieć pewność. Znajdź ich.$B$BIch pierwszym celem były farmy w północnej części Silverpine Forest. Tam właśnie $gpowinieneś:powinnaś; rozpocząć poszukiwania.",
    ["O"] = "Odnajdź Umarłych Tropicieli: Quinna oraz Rane Yorick.",
    ["T"] = "Zaginieni Umarli Tropiciele",
  },
  [429] = {
    ["D"] = "Mój brat Quinn odniósł poważną ranę z rąk ghula, Ivara Plugawego, i nie jestem pewna, czy uda mu się wrócić do zdrowia bez magicznej pomocy. Choć nie jestem aptekarką, wiem, że nasi aptekarze potrafią robić mikstury leczące z odbarwionych serc worgów.$B$BZdobądź takie serca i zanieś je aptekarzowi Renferrelowi z Sepulcher, na południe stąd. Potem wróć tutaj z miksturą.$B$BMnóstwo worgów kręci się między tym miejscem, a leżącym na wschód stąd Sadem Maldena.",
    ["O"] = "Zbierz 6 odbarwionych serc worgów i zanieś je do aptekarza Renferrela z Sepulcher.",
    ["T"] = "Dzikie serca",
  },
  [430] = {
    ["D"] = "Oto mikstura, która pomoże Quinnowi Yorickowi odzyskać siły.$B$BA teraz wybacz, czeka na mnie zajęcie nie cierpiące zwłoki...",
    ["O"] = "Zanieś miksturę Quinna do Quinna Yoricka, na Ivar Patch, na północ od Sepulcher.",
    ["T"] = "Wróć do Quinna",
  },
  [431] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Świece przywołania",
  },
  [432] = {
    ["D"] = "Te cholerne troggi obracają moje wykopaliska w ruinę! Patrz, tam idzie kolejny bydlak!$B$BOchhh, jakże chciałbym iść tam na dół i ukręcić każdą z tych ich kościstych małych szyjek! Zabić ich wszystkich!$B$BTen cały stres i nerwy, nie wyjdzie mi na zdrowie, ... Z czym oni mnie zostawili? Z niczym!$B$BZabiłbym je własnoręcznie, ale to już nie dla mnie! Ty pójdziesz do kamieniołomu i ubijesz trochę tych śmierdzących krętaczy! Zapłacę ci! Tylko zrób im krzywdę, pozabijaj ich!",
    ["O"] = "Zabij 6 Rockjaw Skullthumpers dla majstra Stonebrowa z kamieniołomu Gol\'Bolar.",
    ["T"] = "Te cholerne troggi!",
  },
  [433] = {
    ["D"] = "Jako członek Senatu i Ligi Odkrywców wziąłem na siebie obowiązek zajęcia się troggami, grabiącymi tę część naszych ziem.$B$BNarobiły niezłego zamieszania w kamieniołomie Gol\'Bolar i to bez powodu. Gdy dokopaliśmy się do głębszych partii gruntu, wylazły, zniszczyły nasz sprzęt i przepędziły górników. Nie pozostaje nam nic innego, jak tylko wybić je, wszystko odbudować i wracać do pracy.$B$BJeśli pomożesz mi z troggami, z chęcią zrekompensuję ci stracony czas.",
    ["O"] = "Zabij 10 Rockjaw Bonesnappers dla senatora Mehra Stonehallowa z kamieniołomu Gol\'Bolar.",
    ["T"] = "Sługa społeczeństwa",
  },
  [434] = {
    ["D"] = "Kiedy nałożę przebranie na bota szpiegującego, pójdzie porozmawiać z Lescovarem. Strażnicy powinni go bez problemów przepuścić.$B$BKiedy ty zbierałeś dla mnie materiały, ja zadałem sobie trudu poinformowania Marzona, że to już czas by spotkał się z Lescovarem. Nawet pozwoliłem sobie podrzucić fałszywą wiadomość.$B$BLescovar odeśle swoich strażników i będzie czekał na Marzona w ogrodach. Kiedy usłyszysz, że rozmawiają o Defiasach, wkroczysz do akcji. Musisz zabić ich obu, zanim wrócą straże! Gdy ukończysz zadanie, porozmawiaj z Tirasem.",
    ["O"] = "Pozostań w ogrodzie, dopóki Lord Gregor Lescovar i Marzon the Silent Blade nie skończą swej rozmowy. Następnie zabij ich obu, a potem wróć do Ellinga Triasa ze Stormwind.",
    ["T"] = "Do ataku!",
  },
  [435] = {
    ["D"] = "Tamte wilki nie odejdą; łypią na mnie za każdym razem, gdy tylko wystawię nogę za próg. Muszą być niewiarygodnie głodne, jeśli sądzą, że nadaję się na posiłek.$B$BMuszę zgłosić się do członkini mojej grupy, Umarłej Tropicielki Rane Yorick. A żeby się do niej dostać, będę potrzebował pomocy, by przebić się przez tę watahę.$B$BProszę, pomóż mi przejść! Na zewnątrz czyha mnóstwo wilków, więc będziemy mieć większe szanse, jeśli przyprowadzisz przyjaciół, którzy mogliby nam pomóc...",
    ["O"] = "Przeprowadź Erlanda przez stada wilków, do Rane Yorick.",
    ["T"] = "Eskorta Erlanda",
  },
  [436] = {
    ["D"] = "Poszukiwacz Ironband kieruje wykopaliskami w starożytnych ruinach na wschód od jeziora. Ostatnio jego postępy uległy spowolnieniu, zwłaszcza jeśli wziąć pod uwagę zaopatrzenie, które mu wysłaliśmy.$B$BIronband to tęgi, serdeczny krasnolud, który ceni wyniki, dlatego lękam się, że spotkały go jakieś kłopoty.$B$BUdaj się do wykopalisk Ironbanda i porozmawiaj z Magmarem Fellhewem. Zajmuje się organizacją pracy w strefie i będzie znał przyczynę opóźnienia.$B$BAby się tam dostać, okrąż południowy brzeg jeziora, następnie skieruj się na wschód.",
    ["O"] = "Porozmawiaj z poszukiwaczem Fellhewem.",
    ["T"] = "Wykopaliska Ironbanda",
  },
  [437] = {
    ["D"] = "Pierwsze raporty naszych zwiadowców w Silverpine Forest wykazały, że zgniłoskóre rozbiły obóz na Martwych Polach - starej farmie na północy. Przypuściliśmy na nie kilka ataków, ale za każdym razem przychodziła im z pomocą banshee Nightlash i za pomocą magii rozgramiała nasze oddziały.$B$BChcemy, by Nightlash została zniszczona.$B$BIdź na Martwe Pola i zaatakuj zgniłoskóre. Jeśli nie zobaczysz Nightlash od razu, zabijaj je dopóty, dopóki się nie pojawi, a wówczas zniszcz ją.$B$BEsencja jej ciała powinna obrócić się w proch. Przynieś mi go na dowód, iż została ostatecznie pokonana.",
    ["O"] = "Zabij nieumarłe gnolle w Dead Fields.$B$BGdy pojawi się Nightlash, zabij ją.$B$BPrzynieś Essence of Nightlash do wysokiego egzekutora Hadreca, który przebywa w Sepulcher.",
    ["T"] = "Martwe Pola",
  },
  [438] = {
    ["D"] = "Odkryliśmy nowy ośrodek działań Plagi: jest nim Zmurszały Prom. Znajduje się on na wschód od Sepulcher i jest silnie strzeżony przez nieumarłych; między innymi przez gnolle.$B$BMusi istnieć powód, dla którego Plaga zajęła ten teren. Udaj się do Zmurszałego Promu i dowiedz się, na czym on polega.",
    ["O"] = "Idź do Decrepit Ferry.$B$BWyjaśnij przyczynę obecności Plagi w tamtym miejscu.",
    ["T"] = "Zmurszały Prom",
  },
  [439] = {
    ["D"] = "Spomiędzy ciał wystaje nieowinięta ręka. Jest to ręka kobiety, naznaczona śladami plagi, ale stosunkowo świeża.$B$BNa ręce znajduje się pierścień. Po zdjęciu go i oglądnięciu dostrzegasz znajdujący się na nim wygrawerowany napis: \"Dla Deliah\"",
    ["O"] = "Zanieś Deliah\'s Ring do wysokiego egzekutora Hadreca z Sepulcher.",
    ["T"] = "Wskazówki o zgniłoskórych",
  },
  [440] = {
    ["D"] = "Jeżeli chcesz znaleźć męża lub ukochanego, który dał Deliah ten pierścień... porozmawiaj z sędzią Sevrenem z Brill. Powinien posiadać spis niedawno zmarłych osób, więc przy odrobinie szczęścia może dowiesz się, kim jest Deliah.$B$BNie liczyłbym jednak na sukces. Ktokolwiek dał Deliah ten pierścień, zapewne już nie żyje. A jeśli stał się nieumarłym, raczej nie martwi się już o Deliah.",
    ["O"] = "Dostarcz Deliah\'s Ring do sędziego Sevrena z Brill.",
    ["T"] = "Grawerowany pierścień",
  },
  [441] = {
    ["D"] = "Deliah miała męża, Raleigha, który mieszka teraz w Undercity. Jeżeli właścicielka pierścienia to ta sama Deliah, która żyła w Brill, Raleigh będzie to wiedział.$B$BRaleigh przebywa w Dzielnicy Handlowej miasta Undercity.",
    ["O"] = "Zanieś Deliah\'s Ring do Raleigha.",
    ["T"] = "Raleigh i Undercity",
  },
  [442] = {
    ["D"] = "Nadszedł czas, aby przypuścić szturm na fortecę Plagi w Silverpine Forest: Wyspę Fenris.$B$BMusisz ponownie udać się na wyspę i zniszczyć Thule\'a Ravenclawa. Chcę jego głowy!$B$BTa misja jest równie niebezpieczna co znacząca, $N. Nie możesz zawieść.",
    ["O"] = "Przynieś Thule\'s Head do wysokiego egzekutora Hadreca z Sepulcher.",
    ["T"] = "Szturm na Wyspę Fenris",
  },
  [443] = {
    ["D"] = "Przed szturmem na Wyspę Fenris musimy dowiedzieć się, kto stoi za zgniłoskórymi gnollami. Nasi aptekarze wierzą, że sekret ich pochodzenia spoczywa w dziwnej cieczy płynącej w ich ciałach.$B$BUdaj się na Wyspę Fenris, na wschód od Zmurszałego Promu i zbierz posokę z tamtejszych zgniłoskórych gnolli. Zanieś ją aptekarzowi Renferrelowi, przebywającemu na zewnątrz Sepulcher.",
    ["O"] = "Przynieś 8 butelek posoki zgniłoskórych do aptekarza Renferrela z Sepulcher.",
    ["T"] = "Posoka zgniłoskórych",
  },
  [444] = {
    ["D"] = "Udało mi się zredukować posokę, którą mi $gprzyniosłeś:przyniosłaś;, do jej podstawowych składników. Nie uzyskałem jeszcze ostatecznych wyników, ale jestem pewny, że do utworzenia posoki użyto magii czarnoksięskiej i nekromanckiej.$B$BChciałbym, byś $gzaniósł:zaniosła; próbkę posoki Bethorowi Iceshardowi z Undercity, podczas gdy ja będę kontynuował swe badania. Bethor nie jest aptekarzem, ale jego wiedza na temat magii może pomóc nam rozwikłać zagadkę zgniłoskórych.$B$BIdź. Znajdziesz Bethora w Dzielnicy Magii miasta Undercity.",
    ["O"] = "Zanieś Sample Ichor do Bethora Icesharda z Undercity.",
    ["T"] = "Pochodzenie zgniłoskórych gnolli",
  },
  [445] = {
    ["D"] = "Czas jest luksusem, na który my, pracujący w służbie Lady Sylvanas, nie możemy sobie pozwolić. Z pewnością już o tym wiesz.$B$BMoim obowiązkiem jako członka Królewskiego Stowarzyszenia Aptekarzy jest dzielić się wiedzą z moimi kolegami, by nasze wspólne wysiłki mogły któregoś dnia zaowocować Nową Plagą, której Mroczna Pani tak bardzo pożąda.$B$BZabierz te znaleziska do aptekarza Renferrela stacjonującego w Sepulcher, w Silverpine Forest. Podążaj drogą na południe od Brill. Przy Undercity skręć na południowy zachód.",
    ["O"] = "Zabierz odkrycia aptekarza Johaana do aptekarza Renferrela z Silverpine Forest.",
    ["T"] = "Przesyłka do Lasu Srebrzystych Sosen",
  },
  [446] = {
    ["D"] = "Tę posokę sporządził mój stary znajomy: Thule Ravenclaw. Przed wybuchem wielkiej wojny był młodym i dobrze zapowiadającym się magiem, lecz kiedy Król Lisz wzrósł w siłę, zdradził swoich braci i sprzymierzył się z Plagą.$B$BNie miałem pojęcia, że on ciągle żyje, ani że dowodzi najazdami zgniłoskórych na nas!$B$BZnam wiele jego zaklęć i potrafię sporządzić miksturę, by je zneutralizować. Zabierz ten zwój z powrotem do aptekarza Renferrela. Zawiera inkantacje niezbędne do stworzenia mikstury.",
    ["O"] = "Zanieś Bethor\'s Scroll Aptekarzowi Renferrelowi z Sepulcher w Silverpine Forest.",
    ["T"] = "Thule Ravenclaw",
  },
  [447] = {
    ["D"] = "Legiony Arthasa zalewają nas. Ale dzięki Nowej Pladze będziemy mogli raz na zawsze wyeliminować zarówno Armię Plagi jak i ludzkie robactwo.$B$BMoje badania dowiodły, że krew pająków zmieszana z toksyną odsączoną z serc zdziczałych niedźwiedzi przemienia się w śmiercionośny eliksir. Zdobądź próbki z pająków ze Smyrgającej Ciemności na północnym zachodzie oraz z niedźwiedzi błąkających się po całym Silverpine Forest. Dostarcz składniki do mistrza aptekarza Faranella z Królewskiego Stowarzyszenia Aptekarzy w Undercity.",
    ["O"] = "Zbierz 6 Grizzled Bear Hearts i 6 próbek Skittering Blood. Dostarcz je mistrzowi aptekarzowi Faranellowi z Undercity.",
    ["T"] = "Przepis na śmierć",
  },
  [448] = {
    ["D"] = "Zanim dokonasz napadu na Wyspę Fenris Isle, się do starszego egzekutora Hadreca. Może on posiadać dodatkowe informacje lub sprzęt, który ci się przyda.",
    ["O"] = "Zgłoś się do starszego egzekutora Hadreca w Sepulcher.",
    ["T"] = "Zgłoś się do Hadreca",
  },
  [449] = {
    ["D"] = "Chociaż rany Quinna goją się, chcę, by nasz raport trafił do starszego egzekutora tak szybko, jak to tylko możliwe. Zawiera on informacje istotne dla pobytu Opuszczonych w Silverpine Forest.",
    ["O"] = "Dostarcz Deathstalker Report do starszego egzekutora Hadreca z Sepulcher.",
    ["T"] = "Raport Umarłych Tropicieli",
  },
  [450] = {
    ["D"] = "Możesz wyświadczyć dalsze usługi Królewskiemu Stowarzyszeniu Aptekarzy, $N.$B$BKiedy Arugal rzucił swe nędzne zaklęcia na las, przeklął jednego z naszych najbardziej obiecujących członków - aptekarza Berarda. Jako bezmyślny sługus Arugala, Berard jest dla nas bezużyteczny. Jednakże wyniki jego badań mogą okazać się cenne. Studiował on starożytną plagę, która wieki temu wybiła całe wodne życie w Jeziorze Lordamere.$B$BOdzyskaj dziennik Berarda z jego gabinetu w gospodzie w Wiosce Pyrewood i dostarcz go aptekarzowi Renferrelowi.",
    ["O"] = "Odzyskaj dziennik aptekarza Berarda z Pyrewood Village i odnieś go aptekarzowi Renferrelowi z Sepulcher.",
    ["T"] = "Przepis na śmierć",
  },
  [451] = {
    ["D"] = "Zgodnie z dziennikiem Berarda, mech z Jeziora Creeper i Jeziora Skulker może okazać się użyteczny w naszej misji stworzenia nowej plagi. Stwory te zamieszkują wyspy na Jeziorze Lordamere na wschód stąd.$B$BWspomina on również o bardzo rzadkiej narośli, którą odkrył na ciele murloka. Widocznie guz jest aż taką rzadkością, że Berardowi udało się znaleźć tylko jedną sztukę.$B$BZdobądź próbki mchu oraz rzadki stwardniały guz i zabierz je do mistrza aptekarza Faranella z Undercity.",
    ["O"] = "Dostarcz 6 próbek Lake Creeper Moss, 6 próbek Lake Skulker Moss i Hardened Tumor mistrzowi aptekarzowi Faranellowi z Undercity.",
    ["T"] = "Przepis na śmierć",
  },
  [452] = {
    ["D"] = "$gZnalazłeś:Znalazłaś; się tu w samą porę, $N!$B$BRada Pyrewood może się tu zjawić w każdej chwili. Arugala zajmują teraz inne sprawy. Używa Radnych jak marionetek, aby utrzymać pod swą kontrolą bezmyślne sługi z Pyrewood. Wierzę jednak, iż bez nadzoru Rady Pyrewood, synowie Arugala obrócą się przeciwko swemu panu.$B$BSama nie sprostam im wszystkim. Potrzebuję twej pomocy. Razem możemy unicestwić Radę dla Pani Sylvanas.",
    ["O"] = "Pomóż Umarłej Tropicielce Faerleii zabić Radę Pyrewood.",
    ["T"] = "Zasadzka w Pyrewood",
  },
  [453] = {
    ["D"] = "Powodzenia, $N. Mam nadzieję, że znajdziesz tego gościa i mam też nadzieję, że znajdziesz go żywego.$B$BJeśli opuścił bezpieczne Darkshire, mógł paść ofiarą dzikich bestii.",
    ["O"] = "Znajdź Shadowy Figure. Twoje wskazówki:$B$BNie jest mieszkańcem Darkshire.$B$BJest nerwową i roztrzęsioną osobą.$B$BOpuścił Darkshire i ruszył na zachód.",
    ["T"] = "Odnalezienie Cienistej Sylwetki",
  },
  [454] = {
    ["D"] = "Transportowaliśmy beczułki proszku tam i z powrotem, nim rozkręciliśmy ten... interes. Teraz musimy rozdzielić pracę; Miran zabiera beczki, a ja doglądam pozostałych.$B$BNie jest bezpiecznie pozwalać Miranowi przewozić całą dostawę samemu. Kiedy będzie gotowy wyruszyć, może $gmógłbyś:mogłabyś; eskortować go do punktu docelowego?",
    ["O"] = "Porozmawiaj z Miranem.",
    ["T"] = "Po zasadzce",
  },
  [455] = {
    ["D"] = "Orkowie z klanu Smoczych Paszcz mają schronienie w Wetlands. A teraz rozprzestrzenili się nawet na Dun Algaz! Nie możemy pozwolić im się tutaj obwarować, doprowadziłoby to bowiem do odcięcia Loch Modan od portu Menethilów - naszego portu i warowni w Wetlands.$B$BPrzedrzyj się w Wetlands przez Dun Algaz i zabij kilku orków dla dobra sprawy! Donieś o tym Valstagowi Ironjawowi z portu Menethilów.$B$BAby dostać się do portu, udaj się przez Dun Algaz, potem rusz na północ wzdłuż drogi, następnie zaś na zachód przy rozwidleniu traktu.$B$BLiczmy na ciebie, $N. Nie zawiedź.",
    ["O"] = "Przemierz Dun Algaz.$B$BZabij 8 Dragonmaw Scouts i 6 Dragonmaw Grunts.$B$BZgłoś to Valstagowi Ironjawowi w Menethil Harbor.",
    ["T"] = "Wyzwanie Algazu",
  },
  [456] = {
    ["D"] = "Witaj, $N. Jestem opiekunem Ilthalaine. Przebywam w Shadowglen, aby zapewnić utrzymanie równowagi w naturze.$B$BWiosenne opady były tego roku szczególnie silne i doprowadziły do tego, że populacje niektórych leśnych stworzeń znacznie się rozrosły, podczas gdy inne tylko na tym ucierpiały.$B$BNiestety, nocne pantery oraz ostrowłose dziki zbytnio się rozmnożyły. Shadowglen może dostarczyć jedynie określoną ilość pożywienia dla zwierząt. Ruszaj, $gmłody:młoda; $C, i przerzedź populacje dzików i nocnych panter, aby zachować harmonię w naturze.",
    ["O"] = "Zabij 7 Young Nightsabers i 4 Young Thistle Boars, po czym wróć do opiekuna Ilthalaine.",
    ["T"] = "Równowaga w naturze",
  },
  [457] = {
    ["D"] = "Tu, w Shadowglen, uszczuplenie młodszej populacji zwierząt było dobrym początkiem, ale chyba $gsam:sama; widzisz, $N, że wciąż pozostaje wiele do zrobienia.$B$BJeśli nikt nie zajmie się tym problemem, zasoby lasu skurczą się zbyt szybko. Zabijanie leśnych istot to zło konieczne dla dobra wszystkich zamieszkujących te tereny. Udaj się w głąb lasu i w imię równowagi zabij liniejące nocne pantery i ostrowłose dziki.",
    ["O"] = "Opiekun Ilthalaine chce, abyś $gzabił:zabiła; 7 Mangy Nightsabers i 7 Thistle Boars.",
    ["T"] = "Równowaga w naturze",
  },
  [458] = {
    ["D"] = "Całe szczęście, że jesteś tutaj, $C. Duchy lasu szepczą dziwne wieści.$B$BTajemnicza obrończyni kniei, Tarindrella, powróciła do Shadowglen. Od lat nie odnotowano obecności driad w lasach Kalimdoru. Coś musi być nie w porządku, skoro jedna z nich ponownie zawędrowała na te ziemie.$B$BZnajdź Tarindrellę i dowiedz się, jakie sprawy przywiodły ją do naszego gaju. Jedna z Wartowniczek doniosła, iż widziano ją na południowy zachód od Aldrassilu.",
    ["O"] = "Znajdź driadę imieniem Tarindrella.",
    ["T"] = "Obrończyni kniei",
  },
  [459] = {
    ["D"] = "Coś niedobrego dzieje się w lasach Teldrassilu. Przeszukaj podnóża wzniesień aż do miejsca zamieszkanego niegdyś przez spokojne furbolgi. Opuściły one swe domostwa i zebrały się pod znakiem plemienia Sękatej Sosny.$B$BJedynie zatrucie ohydnym spaczonym mchem mogło doprowadzić do takiej transformacji. Obszar ten opanowały grelly i grellkiny; zagrażają one teraz mieszkańcom Shadowglen.$B$BZajmij się nimi, $N, i sprawdź, czy rzeczywiście znalazły się pod wpływem wstrętnego, spaczonego mchu.",
    ["O"] = "Zbierz 8 sztuk Fel Moss i dostarcz je Tarindrelli.",
    ["T"] = "Obrończyni kniei",
  },
  [460] = {
    ["D"] = "Nie wyglądasz na $gzgniłoskórego:zgniłoskórą;. Dobrze. Straciłem już nadzieję...$B$BNazywam się Alaric i byłem niegdyś głównym sługą i strażnikiem Thule\'a. Użył on swej magii, by \"ochronić\" mnie przed Plagą Nieśmierci, ale zamiast tego czar obdarzył mnie nieżyciem, od którego nie mogę się uwolnić. Zaś po stworzeniu przeklętych zgniłoskórych gnolli, Thule ściął mi głowę... i dał ją gnollom jako zabawkę!$B$BProszę, zanieś mnie do mego ciała. Wierzę, iż gnolle zakopały je tutaj, w Twierdzy Fenris, niedaleko stajni, w nieoznaczonym grobie.",
    ["O"] = "Przynieś Alaric\'s Head na jego grób.",
    ["T"] = "Spoczywając w kawałkach",
  },
  [461] = {
    ["D"] = "Wiem o ukrytej w głębi warowni wnęce, w której przechowywany jest przedmiot cenny dla Thule\'a i jego dawnych kompanów. Jest tam również coś, co może ci się przydać. Zabierz mnie tam!$B$BWnęka znajduje się w południowo-zachodniej wieży warowni, za zakurzoną półką.$B$BZabierz moje ciało, ale zostaw buty. I tak nigdy na mnie nie pasowały...",
    ["O"] = "Zabierz Alarica do ukrytej wnęki.",
    ["T"] = "Ukryta nisza",
  },
  [462] = {
    ["D"] = "Other than you, we sent two scouts through Algaz.  Only one returned.  Here\'s what he discovered:$B$BThe Dragonmaws sent one of their Lieutenants, Maruk Wyrmscale, to organize a crew of orcs in Algaz and cut off the land route to Menethil Harbor!$B$BWe have to stop this, now.  Take out Maruk, and then report to Valstag Ironjaw in Menethil Harbor.$B$BMaruk is headquartered in a small cave, across a pond between the second and third tunnels of Algaz.  Menethil is through Algaz, then west along the road.",
    ["O"] = "Kill Maruk Wyrmscale$B$BReport to Valstag Ironjaw in Menethil Harbor.",
    ["T"] = "<UNUSED>",
  },
  [463] = {
    ["D"] = "$gSłyszałeś:Słyszałaś; o Zielonym Strażniku? Nie szukasz go, prawda? Cóż, powiem, że jesteś $gszalony:szalona;, jeśli tak, ale kim ja jestem, by powstrzymać głupca od śmierci?$B$BJeśli szukasz tej bestii, to słyszałem, że jest na moczarach, na wschód od rozwidlenia prowadzącego do Dun Modr. Czai się pośród krokodyli... i gorzej!$B$BZostaw tu swoje pieniądze. Nie będziesz ich $gpotrzebował:potrzebowała; tam, dokąd idziesz... Nie chcesz chyba wybić staremu Greeniemu zęba, kiedy cię ugryzie prawda?",
    ["O"] = "Znajdź Greenwarden.",
    ["T"] = "Zielony Strażnik",
  },
  [464] = {
    ["D"] = "Klan orków Smoczych Paszcz o mało co nie został zniszczony pod koniec Drugiej Wojny, po tym jak stracili kontrolę nad swoimi czerwonymi smokami. Smoki nie były zbytnio szczęśliwe co ich starzy władcy robili z nimi i zajadle polowały na Smocze Paszcze. Niewielu co pozostało, uciekło z Grim Batol w góry, na wschód od wykopalisk Whelgara.$B$BTeraz urośli w siłę i mają obozowisko na północny wschód od portu Menethilów.$B$BChcemy, abyś $gzaatakował:zaatakowała; ich obóz. Zbierz i przynieś do mnie ich sztandary wojenne jako dowód.",
    ["O"] = "Przynieś 8 Dragonmaw War Banners do kapitana Stoutfist\'a.",
    ["T"] = "Sztandary Wojenne",
  },
  [465] = {
    ["D"] = "Kiedy $gwalczyłeś:walczyłaś; ze Smoczymi Paszczami, odkryliśmy więcej ich planów.$B$BNek\'rosh zbudował katapulty i zamierza oblężony port Menethilów! Przez walki w Dun Algaz jesteśmy odcięci od posiłków!$B$BMusisz usunąć te katapulty. Znajdują się w obozie Smoczych Paszcz.$B$BMasz, weź tę podpałkę. Wywalcz drogę do katapult i podpal je.$B$BJak już to zrobisz, znajdź i zabij Nek\'rosha. Musimy zniszczyć te bestie... w zarodku.",
    ["O"] = "Zniszcz katapulty Smoczych Paszcz.",
    ["T"] = "Zagrywka Nek\'rosha",
  },
  [466] = {
    ["D"] = "Słyszałem, że głęboko w jaskini na północny zachód od Algaz Gate na mokradłach Wetlands znaleziono rzadką rudę zwaną incendicytem. To substancja lotna i niełatwo ją eksploatować, nie wysadzając się przy tym w powietrze. Ale coś mi mówi, że po przetopieniu w odpowiedni sposób mogłaby posłużyć do stworzenia kul armatnich, które każdego rzucą na kolana!$B$BZdobądź mi rudę incendicytu, a ja już się postaram, żeby znaleźć śmiałka, który by zechciał przy niej poeksperymentować.$B$BAch, i jeszcze jedno. Wiesz, że żeby wydobyć tę rudę ze złoża, przydałoby ci się liznąć nieco górnictwa. Jeśli żaden z ciebie szuflowy... to może weź lepiej tam ze sobą kogoś, kto się na tym zna.",
    ["O"] = "Przynieś 6 porcji Incendicite Ore pilotowi Stonegear w Dun Morogh",
    ["T"] = "Rudy są wredne",
  },
  [467] = {
    ["D"] = "Pilot Stonegear kocha silniki machin oblężniczych, jak powinien każdy pilot! I zawsze chętnie zastosuje nowe techniki by ulepszyć strzał jego czołgu!$B$BSłyszał pogłoski o rzadkiej rudzie i szuka kogoś, kto wydobyłby ją dla niego. Jeśli cię nogi swędzą, znajdź Stonegear\'a w jego składziku w Dun Morogh i zobacz co chce.",
    ["O"] = "Porozmawiaj z pilotem Stonegearem.",
    ["T"] = "Szukanie Stonegear\'a",
  },
  [468] = {
    ["D"] = "Góral Rockgar poszukuje ochotników z poselstwem do Wetlands przez Dun Algaz.$B$BJeśli chcesz umoczyć buty w tym rozmokłym hrabstwie na północy, to porozmawiaj z Rockgarem w Dun Algaz. Dun Algaz jest na północ, w górę drogi, za wieżą strażniczą.",
    ["O"] = "Porozmawiaj z góralem Rockgarem.",
    ["T"] = "Złóż raport góralowi Rockgarowi",
  },
  [469] = {
    ["D"] = "Witaj, $gpodróżniku:podróżniczko;!$B$BPrzypuszczam, że zmierzasz w kierunku portu, prawda? Jeśli nie, sugeruję zatrzymać się tam, to dobre miejsce, by kupić jakieś towary, a nawet wypić duże piwo i zrelaksować się.$B$BOtóż, jeśli tak będzie, że zmierzasz w tym kierunku, nie sądzę byś $gmiał:miała; coś przeciwko zabrania tej wiązki krokodylich skór do Jamesa Hallorana, garbarza, prawda?$B$BZrobiłbym to sam, ale moja żona była ostatnio w niezłym nastroju i wolałbym wstrzymać się z oglądaniem jej tak długo jak to możliwe.",
    ["O"] = "Dostarcz Bundle of Crocolisk Skins do Jamesa Hallorana, garbarza w Menethil Harbor.",
    ["T"] = "Codzienna dostawa",
  },
  [470] = {
    ["D"] = "Na mojej cotygodniowej wizycie do Grobowca Ironbearda zostałam zaatakowana przez straszne, ociekające śluzem szlamy! Naturalnie, spanikowałam.$B$BRzuciłam moją torbą w jedną, ale to nic nie pomogło! Szlam po prostu ją wchłonął... Szczęśliwie, dało mi to wystarczająco dużo czasu by uciec.$B$BZła wiadomość jest taka, że naprawdę potrzebuję zawartość mojej torby!$B$BNie wiem, w którą szlamę rzuciłam torebką; one wszystkie wyglądały tak samo! Grobowiec Ironbearda jest na północny wschód stąd, niedaleko Dun Modr. Bardzo ci dziękuję!",
    ["O"] = "Jedna z Ooze w Ironbeard\'s Tomb ma Sida\'s bag, odzyskaj torbę i przynieś z powrotem do niej w Menethil Harbor.",
    ["T"] = "Babrając się w szlamach",
  },
  [471] = {
    ["D"] = "Wysłałem swojego ucznia na bagna, aby przyniósł mi kilka skór z naszych sławnych olbrzymich krokodyli w Wetlands. Kiedy nie wrócił, zacząłem go szukać... Powiedzmy, że nie był to piękny widok.$B$BPołożna mówi, że jakoś sobie poradzi, ale w międzyczasie ja wciąż potrzebuje moich skór!$B$B...Jeśli $gchciałbyś:chciałabyś; zabić jeszcze kilku tych bydlaków, nie miałbym nic przeciwko. Krokodyle znajdziesz na północy wzdłuż wybrzeża, za szałasami murloków.",
    ["O"] = "Zdobądź 6 Giant Crocolisk Skins i przynieś je do Jamesa Hallorana w Menethil Harbor.",
    ["T"] = "Uczniowskie obowiązki",
  },
  [472] = {
    ["D"] = "Dun Modr zostało zajęte przez krasnoludy Czarnorytne!$B$BMoje rany są śmiertelne, $C. Większość regimentu została zabita! Oprychy z klanu Czarnorytnych zaatakowały nas zanim zdążyliśmy się przegrupować z zasadzki na Przęśle Thandola.$B$BNasz przywódca, Longbraid, zadął w róg do odwrotu. Kiedy opuszczaliśmy miasto zostałem trafiony zabłąkanym toporem w plecy. Zrobiło mi się czarno przed oczami.$B$BObudziłem się tutaj, w porcie, ale martwię się o swoich towarzyszy. Wciąż jednak tli się we mnie nadzieja. Być może Longbraid wciąż żyje! Zobacz, czy uda ci się go znaleźć w pobliżu Dun Modr, $R7!",
    ["O"] = "Udaj się na poszukiwanie krasnoluda Longbraida blisko miasta Dun Modr.",
    ["T"] = "Upadek Dun Modr",
  },
  [473] = {
    ["D"] = "$N. Klan orków Smoczych Paszcz pokazuje swoją siłę na większym obszarze niż tylko w Algaz. Kapitan Stoutfist prosi o rozmowę z tymi, którzy chcą zaoferować pomoc w walce z tymi orkami. Znajduje się on wewnątrz twierdzy, w sali wojennej.",
    ["O"] = "Porozmawiaj z kapitanem Stoutfistem.",
    ["T"] = "Zamelduj się u kapitana Stoutfista",
  },
  [474] = {
    ["D"] = "Teraz, gdy katapulty zostały spalone, znajdź i zabij herszta Nek\'rosha.",
    ["O"] = "Zabij herszta Nek\'rosha$B$BPrzynieś Nek\'rosh\'s Head do kapitana Stoutfist.",
    ["T"] = "Pokonaj Nek\'rosha",
  },
  [475] = {
    ["D"] = "Niepokojąca bryza wieje przez las.$B$BGaerolas Talvethren służy jako Wielki Strażnik dla hibernujących Druidów Szponów w kurhanie Ban\'ethil. Jego zadaniem jako obrońcy jest zapewnienie bezpieczeństwa śniącym druidom i upewnienie się, że ich pakt z Yserą pozostaje nienaruszony.$B$BJednakże Gaerolas spóźnia się z przysłaniem wieści, co zaczyna mnie martwić. Udaj się na wschód do wioski Starbreeze, przynieś wieści od Gaerolasa, abym mógł w końcu odetchnąć z ulgą wiedząc, że moi pobratymcy śnią w spokoju.",
    ["O"] = "Poszukaj Gaerolasa Talvethrena w Starbreeze Village.",
    ["T"] = "Niepokojąca bryza",
  },
  [476] = {
    ["D"] = "Plemię Sękatej Sosny zostało spaczone!$B$BSpokojni niegdyś furbolgowie obrócili się przeciwko obrońcom lasu. Urządzili na mnie zasadzkę zaraz po tym, gdy opuściłem kurhan Ban\'ethil i udałem się w stronę wioski Starbreeze. Coś w lesie spaczyło Ursala, ich wodza, który korzysta teraz z mrocznych sił spaczonego torfowiska doprowadzając resztę plemienia do szaleństwa.$B$BJestem zbyt ranny, aby wrócić do Athridasa i donieść mu o tych grobowych wieściach. Zadanie zostaje powierzone tobie, $gmłody:młoda; $C. Możemy jedynie mieć nadzieję, że obłąkani furbolgowie nie dotarli jeszcze do Ban\'ethil!",
    ["O"] = "Wróć do Athridasa Bearmantle w Dolanaar.",
    ["T"] = "Spaczenie Sękatej Sosny",
  },
  [477] = {
    ["D"] = "Jak może wiesz, miasto Ambermill jest źródłem ludzkiej opozycji, głównie poprzez wsparcie, które otrzymują od magów Dalaranu.$B$BNie wiem jaki jest ich plan, ale zainteresowanie wioską jak Ambermill znaczy, że ma to jakieś większe znaczenie.$B$BPrzesyłają skrzynie wozami z Hillssbrad. Wiele z tych zasobów zostaje wyładowana w małym obozie na północ od Wioski Pyrewood. Odzyskaj zawartość skrzyń i przynieś je do mnie.",
    ["O"] = "Odzyskaj zawartość jednej z Dalarańskich skrzyń magów. Znajdziesz je w Pyrewood Village na południu.",
    ["T"] = "Skrzyżowanie granic",
  },
  [478] = {
    ["D"] = "<Szybkim ruchem wyciągasz wisiorek ze skrzynki i zamykasz wieko.>",
    ["O"] = "Zanieś tajemniczy wisiorek do Sepulcher, do Allistera, kapłana cienia.",
    ["T"] = "Mapy i runy",
  },
  [479] = {
    ["D"] = "Dalar stara się zlokalizować źródło zaklęć czarodziejów. My zaś musimy użyć wszystkich możliwych sposobów, by spowolnić ich postępy...$B$BTo pewne, że magowie, wywoływacze i obrońcy noszą wisiorki. Odbierz je im i dostarcz tutaj.$B$BBy dotrzeć do Ambermill udaj się główną drogą na południe, a następnie skręć na wschód.",
    ["O"] = "Zdobądź 8 Dalaran Pendants dla kapłana cienia Allistera z Sepulcher.",
    ["T"] = "Śledztwo w sprawie Ambermill",
  },
  [480] = {
    ["D"] = "Arcymag o wielkiej mocy nadzoruje reaktywację węzłów linii energetycznych. Biorąc pod uwagę poczynione przez nich postępy, zabicie go jest naszą jedyną nadzieją na ich powstrzymanie. Nie będzie to łatwe; bez wątpienia chronią go strażnicy i inni magowie.$B$BMusisz iść i szybko z nim skończyć. Gdy zginie, przynieś mi jego laskę. Idź już.",
    ["O"] = "Zabij arcymaga z Dalaranu i zabierz jego laskę do kapłana cienia Allistera z Sepulcher.",
    ["T"] = "Tkacz",
  },
  [481] = {
    ["D"] = "Zanieś ten wisiorek Dalarowi Dawnweaverowi, może on potrafi rzucić trochę światła na plany czarodziejów.",
    ["O"] = "Zanieś pokryty runami wisiorek Dalarowi Dawnweaverowi z Sepulcher.",
    ["T"] = "Analiza Dalara",
  },
  [482] = {
    ["D"] = "Oczywiście! Jak mogłem zapomnieć?$B$BAmbermill był jednym z miejsc szczególnego zainteresowania Kirin Toru, ponieważ znajdował się tam uśpiony węzeł linii magicznych. Najwyraźniej czarodzieje zaplanowali jego reaktywację i wykorzystanie jego mocy do jakiegoś większego celu.$B$BNie możemy na to pozwolić...$B$BAktywacja linii energetycznych będzie wymagała ogromnych nakładów mocy; możemy ją opóźnić odbierając czarodziejom wisiory.$B$BPrzekaż te informacje Allisterowi; on zdecyduje, co robić dalej.",
    ["O"] = "Porozmawiaj z kapłanem cienia Allisterem w Sepulcher.",
    ["T"] = "Zamiary Dalarańczyków",
  },
  [483] = {
    ["D"] = "Dostrzeżono najeźdźców z plemienia Sękatej Sosny pustoszących schowany na wzgórzu, na zachodzie kurhan Ban\'ethil.$B$BJeśli nie pomożemy, uśpieni druidzi zostaną na wieczność uwięzieni w Szmaragdowym Śnie, nieświadomi swego losu. Nie można przerwać delikatnego rytualnego śnienia bez Relikwii Przebudzenia.$B$BUdaj się do legowiska i odzyskaj kruczy szponi talizman, czarne pióro, szafir nieba i runę gniazda. Druidzi złożyli je w poświęconych skrzyniach. Przynieś mi je, a przygotuję rytuał przebudzenia.",
    ["O"] = "Odzyskaj Relics of Wakening i zanieś je do Athridasa Bearmantle\'a, do Dolanaar.",
    ["T"] = "Relikwie Przebudzenia",
  },
  [484] = {
    ["D"] = "Jestem James Halloran, garbarz. Wyprawione przeze mnie krokodyle skóry rozchodzą się na pniu; na pokładach statków mkną do wszystkich portów świata.$B$B$gSpotkałeś:Spotkałaś; Einara? Jest jednym z łowców dostarczających mi krokodyle skóry.$B$BKończą mi się te bardziej miękkie, zdzierane z młodych krokodyli.$B$BDlatego właśnie dam ci dobrą cenę za wiązkę takich skór. Młode krokodyle znajdziesz na bagnach zaraz za miastem.",
    ["O"] = "Zdobądź 4 Young Crocolisk Skins dla Jamesa Hallorana z Menethil Harbor.",
    ["T"] = "Skóry młodych krokodyli",
  },
  [485] = {
    ["D"] = "$gZnalazłeś:Znalazłaś; jakieś dziwne, metalowe urządzenie o kształcie jajka. Manipulując jednym z pokręteł aktywujesz jajko, które okazuje się być jakimś gnomim wynalazkiem! Z jego środka wydobywa się trzeszczący głos. $B$B\"Nazywam się Oglethorpe i mój robot samonaprowadzający zaginął! Zapłacę ci za jego naprawę; proszę, zabierz ten nadajnik do robota!\"$B$B\"Obliczam dla ciebie jego koordynaty! Rozbił się u ujścia rzeki, w pobliżu Skały Czat!\"",
    ["O"] = "Przynieś nadajnik ratunkowy do samonaprowadzającego robota Oglethorpe\'a, przebywającego w Hinterlands, u ujścia rzeki, w pobliżu Skulk Rock.",
    ["T"] = "Znajdź OOX-09-OS",
  },
  [486] = {
    ["D"] = "Nadeszła pora, aby ocalić Druidów Szponów. Jeśli teraz zawiedziemy, $N, na wieki pozostaną pogrążeni we śnie.$B$BPrzygotuję Relikwie Przebudzenia i odprawię rytuał. Aby moja praca przyniosła owoce, należy zgładzić przeklętą bestię, odpowiedzialną za tę okropną sytuację. Tylko wówczas rytuał zostanie dopełniony.$B$BTo Ursal Młóckarz zakłócił działania naszych braci i to on musi ponieść koszt zwrócenia im wolności. Udaj się na południowy zachód, do ostoi Sękatych Sosen i zabij go.",
    ["O"] = "Zabij Ursal the Mauler i wróć do Athridasa Bearmantle\'a z Dolanaaru.",
    ["T"] = "Ursal Młóckarz",
  },
  [487] = {
    ["D"] = "Droga do Darnassus musi pozostać bezpieczna. Podróżnicy kierujący się z Dolanaaru do Darnassus meldowali o zaciętych atakach ze strony skażonych furbolgów z plemienia Sękatej Sosny.$B$BKażdego dnia drogą tą podróżują towary i wieści do Darnassus, oraz z powrotem w głąb krainy. Nie możemy pozwolić, aby prymitywna banda łotrów zastraszała ludzi.$B$B$C, dobądź broni w imię świętego lasu. Kryjówka furbolgów leży gdzieś w okolicach tej północnej ścieżki. Zgładź 6 napastników ze szczepu Sękatej Sosny i zamelduj się u mnie.",
    ["O"] = "Zabij 6 Gnarlpine Ambushers i wróć do Wartowniczki Amary Nightwalker, na obrzeża Dolanaaru.",
    ["T"] = "Droga do Darnassus",
  },
  [488] = {
    ["D"] = "Widzę, żeś jesteś $gchętny:chętna; do pracy. Na szczęście dla ciebie nie zdarza się, bym pogardziłbym świeżo $gupieczonym:upieczoną; $C, $ggotowym:gotową; spełnić moje polecenie.$B$BWidzisz, $N, mogę uczynić cię bardzo $gszczęśliwym:szczęśliwą;; dostarczyć ci przedmioty, o których posiadaniu nigdy nie $gśniłeś:śniłaś;. Jednak by tak się stało, musisz przynieść mi określone rzeczy.$B$BMoje sprawy w tym lesie często wymagają pewnych... materiałów. Zdobądź mi 3 kły nocnej pantery, 3 pióra puszczyka i 3 próbki wydzieliny leśnego przędzarza.$B$BNiech to będzie nasz mały sekret, $R7.",
    ["O"] = "Dostarcz Zennowi Foulhoofowi 3 Nightsaber Fangs, 3 Strigid Owl Feathers i 3 próbki Webwood Spider Silk na obrzeża Dolanaaru.",
    ["T"] = "Polecenie Zenna",
  },
  [489] = {
    ["D"] = "Rada Puszczy dowiedziała się, że $gpomogłeś:pomogłaś; Zennowi Foulhoofowi. Satyr jest wrogiem lasu. Jako $R $gpowinieneś:powinnaś; wiedzieć, iż nie powinno się brukać kniei uśmiercając dzieci Natury.$B$BJeśli chcesz pozostać $gprzyjacielem:przyjaciółką; Teldrassilu, musisz odkupić swój czyn w oczach Rady.$B$BDaj Foulhoofowi lekcję, a zostaniesz $gzrehabilitowany:zrehabilitowana;. Spaczone Szyszki to zatrute nasiona, spadające z drzew. Unosi się z nich zielony dym.$B$BZanieś kilka Foulhoofowi. Pomyśli, że $gprzyniosłeś:przyniosłaś; mu niegroźną przekąskę.",
    ["O"] = "Zbierz 3 Fel Cones i daj je Zennowi Foulhoofowi, przebywającemu na obrzeżach Dolanaaru.",
    ["T"] = "Odpokutuj swój czyn!",
  },
  [490] = {
    ["D"] = "By strict orders from the Council of Darnassus, I am commissioning a bounty on the Gnarlpine Tribe. They are no longer friends of the forest. Their corruption has left them mindless threats to our people and the creatures of the glade.$b$bAs decreed by the Council, you shall be rewarded for removing the furbolg menaces from Kalidar. Bring to me their fangs as proof of your deeds.",
    ["O"] = "Shayla Nightbreeze outside of Darnassus wants you to bring her 20 Gnarlpine Fangs.",
    ["T"] = "<UNUSED>",
  },
  [491] = {
    ["D"] = "Thule powiedział mi kiedyś, że dawno temu wraz ze swymi dwoma kolegami stworzył magiczną różdżkę, splecioną z uczniowskich różdżek każdego z nich. Stanowiła ona symbol ich przyjaźni, i choć Thule zaczął nią gardzić, nie mógł się jej pozbyć, ani pozwolić, by trafiła w ręce pozostałych. Tak więc ukradł różdżkę i ukrył ją w Twierdzy Fenris.$B$BMasz. Zabierz ją do Bethora Icesharda, jednego z niegdysiejszych przyjaciół Thule\'a. Jestem pewien, że ją zechce.",
    ["O"] = "Zabierz Woven Wand do Bethora Icesharda, do Dzielnicy Magii miasta Undercity.",
    ["T"] = "Różdżka dla Bethora",
  },
  [492] = {
    ["D"] = "Strażnicy Śmierci poinformowali mnie, że właśnie schwytano kolejnego z tych tępych krasnoludzkich górali. Zwykle używają piwnicy Tawerny \"Pod Szubienicą\" jako celi do przetrzymywania więźniów, w oczekiwaniu na moment, kiedy będzie można się nimi \"odpowiednio\" zająć. $B$BDlaczego nie wybierzesz się sprawdzić, jak schwytanemu góralowi zasmakuje specjalny napój, który dla niego przygotowałem? Zawiera on subtelną wskazówkę losu, jaki Mroczna Pani zaplanowała dla reszty Azeroth.",
    ["O"] = "Zanieś Johaan\'s Special Drink do Captured Mountaineer.",
    ["T"] = "Nowa Plaga",
  },
  [493] = {
    ["D"] = "Mroczna Pani wywiera intensywny nacisk na Królewskie Stowarzyszenie Aptekarzy w sprawie opracowania Nowej Plagi. Pracujemy bez wytchnienia i poczyniliśmy znaczne postępy. Jesteśmy przekonani, że szybciej osiągniemy sukces, jeśli będziemy dzielić się między sobą wiedzą.$B$BDlatego chciałbym, byś $gdostarczył:dostarczyła; wyniki moich najnowszych badań aptekarzowi Lydonowi z Tarren Mill, małego miasta położonego w Hillsbrad Foothills. Podróż będzie długa.$B$BSkieruj się na południe i trzymaj się drogi. Uważnie śledź drogowskazy!",
    ["O"] = "Dostarcz odkrycia aptekarza Renferrela aptekarzowi Lydonowi z miasta Tarren Mill w Hillsbrad Foothills.",
    ["T"] = "Podróż na Podgórze Hillsbrad",
  },
  [494] = {
    ["D"] = "Bądź cicho i słuchaj, $C.$B$BPrzysłano mnie tu, bym obserwowała miasto Hillsbrad. Moja misja ma charakter rekonesansu. Jest ogromnie ważne, byś natychmiast $gdostarczył:dostarczyła; wiadomość do Wysokiej Egzekutorki Darthalii z Tarren Mill. Powiedz jej, że ja, Umarła Tropicielka Lesh, przekazuję, co następuje:$B$B\"Z zachodu rozbrzmiewa krzyk kruka.\"$B$BPodążaj drogą na wschód i zwracaj uwagę na drogowskazy. Teraz spiesz się! Ruszaj do Tarren Mill i nie zatrzymuj się, nawet na chwilę!",
    ["O"] = "Udaj się do to Tarren Mill, aby dostarczyć wiadomość Umarłej Tropicielki Lesh do Wysokiej Egzekutorki Darthalii.",
    ["T"] = "Pora uderzyć",
  },
  [495] = {
    ["D"] = "Mug\'Thol i jego banda ogrów zostali wysłani do Alteraku w celu zdobycia Korony Woli dla Lady Sylvanas. Niestety, zamiast ją zwrócić, ten idiota postanowił ją założyć... Przypuszczam, że ogry nie potrafią oprzeć się niczemu, co błyszczy i świeci.$B$BJego kretyńskie działania spowodowały jednak pewien problem. Korona Woli pozwoliła mu wyzwolić się spod kontroli, narzuconej mu wcześniej przez Lady Sylvanas.$B$BMroczna Pani chce uczynić z jego losu przykład; udaj się do Tarren Mill i zgłoś się do mojej podwładnej, Melisary.",
    ["O"] = "Zgłoś się do Melisary w Tarren Mill w Hillsbrad Foothills.",
    ["T"] = "Korona Woli",
  },
  [496] = {
    ["D"] = "Ach, kolejny smętny dzień w Tarren Mill. Całe to czyste powietrze przyprawia mnie o paskudny nastrój, $N.$B$BIm szybciej uda nam się zarazić tutejszych ludzi, tym lepiej. Prowadzę wytężone studia nad zabójczymi odczynnikami, które mogłyby znaleźć zastosowanie w moich miksturach, lecz nie miałem czasu na zebranie ich wszystkich.$B$BJeżeli chcesz się przydać, zdobądź dla mnie następujące rzeczy: 10 języków szarych niedźwiedzi oraz bardzo rzadką i trudną do znalezienia posokę pełzacza. Zarówno niedźwiedzie jak i pełzacze znajdziesz tuż za miastem.",
    ["O"] = "Aptekarz Lydon z Tarren Mill chce 10 Gray Bear Tongues i trochę Creeper Ichor.",
    ["T"] = "Eliksir cierpienia",
  },
  [497] = {
    ["D"] = "As a child, raised as a gladiator at Durnholde Keep, I was befriended by Taretha, the daughter of my wet nurse and mistress of the damned bastard Blackmoore.$b$bThe past is the past, $n, but reports of human movements in Hillsbrad reminded me of that time. I dispatched a small party to the area to investigate and to retrieve an... item... given to me by Taretha, if they could.$b$bA fruitless task, no doubt, but perhaps...$b$bThey should have returned by now, I want you to go to Tarren Mill to investigate.",
    ["O"] = "Go to Tarren Mill and find out the status of the party sent by Thrall.",
    ["T"] = "<UNUSED>",
  },
  [498] = {
    ["D"] = "Wraz z kilkoma innymi wojownikami zostałem wysłany przez Wodza, aby odzyskać pewien przedmiot z Durnholde oraz zbadać tak zwany Syndykat.$B$BUdaliśmy się na zwiad do Durnholde, ale zostaliśmy zaskoczeni przez dużą grupę ludzi. Dzielnie walczyliśmy, ale było ich tak wielu, że udało im się nas pokonać. Wzięli kilku z nas jako jeńców, ale mnie udało się uciec.$B$BDurnholde leży na południowy wschód stąd, tuż za rzeką. Drull i Tog\'thar ciągle tam są, musisz ich uratować.",
    ["O"] = "Krusk z Tarren Mill chce, abyś $guwolnił:uwolniła; Drulla i Tog\'thara z Durnholde Keep.",
    ["T"] = "Ratunek",
  },
  [499] = {
    ["D"] = "Zmieszanie tych składników w to, co jak sądzę, jest Eliksirem Cierpienia, zajmie tylko chwilę.$B$BOto jest! Ach, nic tak nie rozjaśnia ponurego dnia na tym nieszczęsnym podgórzu, jak danie światu odrobiny cierpienia.$B$BZobaczmy, czy nasza mała miksturka osiągnie zamierzony efekt.$B$BDaj mojej asystentce, Umpi, posmakować tego, co Mroczna Pani zaplanowała zarówno dla ludzi, jak i dla Plagi.",
    ["O"] = "Daj Umpi Eliksir Cierpienia.",
    ["T"] = "Eliksir cierpienia",
  },
  [500] = {
    ["D"] = "Ogry Graniołamacze wzniosły swój kopiec w Górach Alterak, nieopodal zniszczonego miasta Alterak. Moi zwiadowcy donieśli mi, że opanowały również same ruiny.$B$BNie możemy pozwolić, aby się tam zadomowiły; jeżeli poczują się tam bezpieczne, ich kolejnym krokiem będzie przeniesienie się na podgórze, czyli dokładnie pod nasze progi!$B$BUdaj się na północ, w Góry Alterak i zapoluj na ogry. Przynieś mi ich brudne palce, a zgarniesz niezłą nagrodę.",
    ["O"] = "Zbierz 9 Dirty Knucklebones z Crushridge Ogres w Alterac Mountains. Przynieś je komendantowi Redpathowi z Southshore.",
    ["T"] = "Polowanie na Graniołamaczy",
  },
  [501] = {
    ["D"] = "Och, $N... kwiaty kwitną w Hillsbrad, a powietrze jest takie świeże i rześkie. Nie mogę nic na to poradzić, że nurzam się w tej nędzy. Spoglądam przez me zapaskudzone okno i z utęsknieniem czekam na dzień, w którym nasza Nowa Plaga przyniesie temu światu śmierć na którą zasługuje.$B$BChoć tak bardzo chciałbym całymi dniami siedzieć i rozmyślać, wzywają mnie moje obowiązki wobec Mrocznej Pani. Pomóż mi, dobrze? Moje badania skłaniają mnie ku przekonaniu, że mogę stworzyć najcudowniejszy napój śmierci z krwi pumy. Przynieś mi ją, a nieco się zabawimy.",
    ["O"] = "Dostarcz 10 fiolek Mountain Lion Blood do aptekarza Lydona z Tarren Mill.",
    ["T"] = "Eliksir bólu",
  },
  [502] = {
    ["D"] = "Ach, uwielbiam zapach świeżej krwi na podgórzu! $B$BTeraz dodamy do niej nieco tego i owego, i zacznie się prawdziwa zabawa! Wynik naszych działań chciałbym nazwać Eliksirem Bólu. Jeżeli moje obliczenia są właściwe, to ten wywar może być zaczątkiem czegoś wspaniałego dla Lady Sylvanas. Lecz potrzebny nam test.$B$BZabierz ten eliksir na farmę na północy pól Hillsbrad, na południowy wschód stąd. Zobaczymy, czy Stanley, maleńki piesek farmera Raya, polubi ten \"przysmak\".",
    ["O"] = "Napój Stanleya Eliksirem Bólu.",
    ["T"] = "Eliksir bólu",
  },
  [503] = {
    ["D"] = "Wnioskując z dokumentów, które $gzdobyłeś:zdobyłaś;, Gol\'dir jest przetrzymywany w wielkiej bazie Syndykatu na północy, najprawdopodobniej w Górak Alterak. Zbyt długo już jest więźniem, musi zostać uwolniony!",
    ["O"] = "Uwolnij Gol\'dira, a następnie wróć do Kruska, do Tarren Mill.",
    ["T"] = "Gol\'dir",
  },
  [504] = {
    ["D"] = "Teraz, gdy $gzakosztowałeś:zakosztowałaś; już walki z ogrami Graniołamaczy, chcę, abyś $gspuścił:spuściła; im prawdziwe lanie...$B$BRuszaj do Ruin Alteraku i znajdź bojowników Graniołamaczy. Chcę, abyś $gwyrżnął:wyrżnęła; sporą ich ilość - to jedyna droga, aby pojęli, że mają trzymać się z dala od ziem Przymierza.",
    ["O"] = "Zabij 10 Crushridge Warmongers, a potem wróć do komendanta Redpatha, do Southshore.",
    ["T"] = "Bojownicy Graniołamaczy",
  },
  [505] = {
    ["D"] = "Jestem nowym sędzią Southshore, wybranym niedawno po zabójstwie mojego poprzednika. Zabójców nigdy nie odnaleziono, ale w drodze dochodzenia ustaliliśmy, że niemal na pewno zostali wynajęci przez Syndykat - grupę złodziei, dowodzoną przez nikczemnych szlachciców z upadłego królestwa Alterak.$B$BSyndykat ma swoje obozy na Cyplu Sofery i Sztylecie Corahna, na północ i zachód od pozostającego pod kontrolą Hordy miasta Tarren Mill. Zabij wszystkich członków Syndykatu, których tam znajdziesz.",
    ["O"] = "Zabij 12 Syndicate Footpads i 8 Syndicate Thieves, potem wróć do sędzi Henry\'ego Maleba z Southshore.",
    ["T"] = "Zabójcy Syndykatu",
  },
  [506] = {
    ["D"] = "Dzień czy dwa temu odwiedził mnie przywódca Syndykatu. Nazywał się Aliden Perenolde i przedstawił się jako władca tych ziem. Podzielił się ze mną swymi planami, obejmującymi uczynienie z opierających się mu orków niewolników, jak to zamierzał jego ojciec i mentor, pogardzany Blackmoore.$B$BCo ważniejsze, towarzyszyła mu jego kochanka, wątła dziewka o imieniu Elysa. Na szyi miała świecidełko, którego tak pragnie Wódz.$B$BTeraz idź. Poradzę sobie sam, gdy tylko wyrównam tu rachunki.",
    ["O"] = "Przekaż zdobyte przez Gol\'dira wiadomości Kruskowi z Tarren Mill.",
    ["T"] = "Spuścizna Blackmoore\'a",
  },
  [507] = {
    ["D"] = "To jasne, że Perenolde musi zginąć; to plugastwo musi zniknąć z powierzchni ziemi. Jego posiadłość leży na północ stąd, na brzegu Jeziora Lordamere. Spełń swą powinność, $N, następnie zdobądź świecidełko, którego pragnie Wódz i wróć tutaj.",
    ["O"] = "Zabij Lorda Alidena Perenolde\'a i zdobądź wisiorek Tarethy od jego kochanki Elysy.",
    ["T"] = "Lord Aliden Perenolde",
  },
  [508] = {
    ["D"] = "Wisiorek? Oczywiście, możesz go wziąć... Bierz go! Nie chcę po nim żadnej pamiątki... tylko błagam, błagam, zostaw mnie w spokoju...",
    ["O"] = "Zwróć wisiorek Tarethy Kruskowi z Tarren Mill.",
    ["T"] = "Podarunek Tarethy",
  },
  [509] = {
    ["D"] = "Kolejny dzień, kolejny eliksir do sporządzenia. Gdyby to ode mnie zależało, pozwoliłbym Pladze i tym żałosnym ludziom wyrżnąć się nawzajem. Wygląda na to, że wykazują znaczną determinację w tym kierunku.$B$BNiestety, nasza Mroczna Pani chce nieco przyspieszyć ten proces, dlaczego by więc nie spędzić tych ponurych dni rozsiewając nieco zarazy i śmierci nad tą krainą? $B$BOto plan, $N: udaj się do Nethander Stead, na południe od Tarren Mill i na wschód od rzeki i Southshore. Na tamtejszym polu zbierz dla mnie 6 kwiatów mułoryjków do mego kolejnego eliksiru.",
    ["O"] = "Przynieś 6 Mudsnout Blossoms aptekarzowi Lydonowi z Tarren Mill.",
    ["T"] = "Eliksir agonii",
  },
  [510] = {
    ["D"] = "Wśród tych dokumentów znajduje się lista niezbędnego zaopatrzenia. Zawiera ona zarówno typowe przedmioty (jedzenie, broń, ubrania), jak również rzadziej spotykany sprzęt (maski, olej, trucizny).$B$BAle warta uwagi jest przede wszystkim pilność tej prośby - to zaopatrzenie miało być wkrótce potrzebne do celu przedsięwzięcia akcji, opisanej w dokumentach jako \"ważna misja przeciwko Southshore\".",
    ["O"] = "Zanieś Foreboding Plans do sędziego Maleba w Southshore.",
    ["T"] = "Złowróżbne plany",
  },
  [511] = {
    ["D"] = "Jeden z leżących na stole listów został zaszyfrowany. Budzi on twoje zainteresowanie.",
    ["O"] = "Zanieś Encrypted Letter mędrcowi Dibbsowi z Southshore.",
    ["T"] = "Zaszyfrowany list",
  },
  [512] = {
    ["D"] = "Obawiam się, że dowództwo Syndykatu pragnie ujrzeć Southshore w ruinach. Musimy wymierzyć silny cios dowództwu tej bandy, zanim ich plany zostaną zrealizowane.$B$BZapuść się w ruiny Strahnbradu, w Górach Alteraku na północy. Sądzimy, że znajduje się tam kwatera główna Syndykatu.$B$BWiemy, że tym gangiem morderców dowodzą dawni szlachcice z Alteraku. Mogą ukrywać się pośród szeregowych członków Syndykatu, ale poznasz ich po sygnetach, który noszą.$B$BPrzynieś mi te sygnety.",
    ["O"] = "Zanieś 7 Alterac Signet Rings sędziemu Malebowi z Southshore.",
    ["T"] = "Śmierć szlachty",
  },
  [513] = {
    ["D"] = "Kiedy już myślałem, że przyjdzie mi spędzić kolejny dzień wyprany z jakiejkolwiek radości, ty przynosisz mi te cudowne kwiaty.$B$BNajpierw zrobię z nich jednolitą papkę. Następnie będziemy potrzebować mistrza aptekarzy Faranella z Undercity, by wzbogacił ją o swój koloid gnicia i będziemy już gotowi na kawał dobrej zabawy!$B$BWeź tę mieszankę i natychmiast dostarcz ją do mistrza Faranella, $N.",
    ["O"] = "Zanieś Mudsnout Composite do mistrza aptekarzy Faranella, w Undercity.",
    ["T"] = "Eliksir agonii",
  },
  [514] = {
    ["D"] = "Mam kolegę w Ironforge, który może będzie potrafił pomóc w rozszyfrowaniu tego listu. Idź do biblioteki w Hali Odkrywców w Ironforge i porozmawiaj z badaczem Stormpike\'em. Powiedz mu, że ja cię przysyłam, i pokaż mu ten list. Jeśli jest ktoś na północ od Iglicy Czarnej Skały, kto potrafi to odczytać, to właśnie on.",
    ["O"] = "Zanieś Cleverly Encrypted Letter badaczowi Stormpike\'owi z Ironforge.",
    ["T"] = "List do Stormpike\'a",
  },
  [515] = {
    ["D"] = "Roztarte Mułoryjki? Genialnie! Dlaczego wcześniej o tym nie pomyślałem?$B$BPozwól, że dodam do tego diabelskiego wywaru nieco mego koloidu gnicia.$B$BAby aktywować składniki zarażające zawarte w tej miksturze, Lydon będzie potrzebował silnej mikstury z krwi trolla, a także kilka łusek Sztyletokręgich oraz oczu Zdartopłetwych z południowego wybrzeża Hillsbrad. Będzie wiedział, co robić, wystarczy tylko, że dostarczysz mu wszystkie reagenty. Ach, z jakąż niecierpliwością czekam, by usłyszeć, jak wypadł eksperyment!",
    ["O"] = "Przynieś Mudsnout Mixture, Strong Troll\'s Blood Potion, 5 Daggerspine Scales i 5 Torn Fin Eyes aptekarzowi Lydonowi z Tarren Mill.",
    ["T"] = "Eliksir agonii",
  },
  [516] = {
    ["D"] = "Otrzymałem raport, że grupa nieumarłych przygotowuje się do ataku na nas. Dzięki tej informacji możemy odwrócić sytuację i zaatakować ich pierwsi, paląc ich mały plan na panewce.$B$BNiestety, te informacje są w najlepszym razie niepewne. Ponoć nieumarli ukrywają się w miejscu zwanym Jarem Berena. Dokładne położenie tego miejsca nie jest znane, jednak przypuszczalnie jest to jaskinia we wzgórzach, w pobliżu placówki czarodziejów z Dalaranu.$B$BWierzę w twoją zaradność. Znajdź ich i zabij.",
    ["O"] = "Zlokalizuj Beren\'s Peril, następnie zabij 6 Ravenclaw Drudgers i 6 Ravenclaw Guardians, na koniec wróć do kapłana cienia Allistera z Sepulcher.",
    ["T"] = "Jar Berena",
  },
  [517] = {
    ["D"] = "Ten nowy eliksir jest wreszcie gotowy, by sprawdzić jego działanie. Ale dlaczego mielibyśmy pozwalać, by idealnie dopracowana, wysoce zakaźna plaga marnowała się na zwykłej żabie albo psie? Zabawmy się w imię Pani Sylvanas.$B$BUdaj się do Dun Garok. Kojarzysz koszary, gdzie kręcą się te małe, śmierdzące krasnale? Wykradnij im beczkę Shindigger Stout. Gdy ją otrzymam, urządzimy sobie niezłą imprezę, $N.",
    ["O"] = "Przynieś beczkę Shindigger Stout aptekarzowi Lydonowi z Tarren Mill.",
    ["T"] = "Eliksir agonii",
  },
  [518] = {
    ["D"] = "Mug\'Thol i jego ogry Graniołamacze opanowały ruiny Alteraku. Trudno będzie wymierzyć mu jakąkolwiek poważniejszą karę nie uszczupliwszy jego gromady ogrów.$B$BPo osłabieniu ich, będziemy kontynuować.$B$BZrozumiano? Dobrze. A teraz idź.",
    ["O"] = "Melisara z Tarren Mill chce, byś $gzabił:zabiła; 10 Crushridge Maulers.",
    ["T"] = "Korona Woli",
  },
  [519] = {
    ["D"] = "Targ, Muckrake i Glommus są porucznikami Mug\'Thola. Są lojalni wobec niego; choć kto wie od czego zależy lojalność ogrów.$B$BPrzynieś mi ich głowy, $N, a pozostanie nam jedynie obciąć głowę Mug\'Thola i zabrać koronę.",
    ["O"] = "Zabij Targa, Muckrake\'a i Glommusa i przynieś ich głowy Melisarze z Tarren Mill.",
    ["T"] = "Korona Woli",
  },
  [520] = {
    ["D"] = "Po śmierci poruczników Mug\'Thola, pozostało jedynie zabić samego Mug\'Thola i odzyskać Koronę Woli. Nie ma cienia wątpliwości, że ogr nie będzie chciał w tym uczestniczyć. Najprawdopodobniej będzie się ciebie spodziewał, wszak $gprzyczyniłeś:przyczyniłaś; się do... odejścia... jego kompanów.$B$BOdnajdź Mug\'Thola i przynieś mi jego głowę i Koronę. Opór Graniołamaczy dobiegnie końca.",
    ["O"] = "Zabij Mug\'Thola i przynieś jego głowę oraz Crown of Will do Melisara z Tarren Mill.",
    ["T"] = "Korona Woli",
  },
  [521] = {
    ["D"] = "Pozostało nam jedynie dostarczyć Koronę Woli do Sharlindry, w Undercity. Zadba o to, by trafiła w ręce Lady Sylvanas. Ostrzegam cię przed myślami o użyciu korony do własnych celów, $N, los Mug\'Thola powinien odwieść cię od takich zamiarów.",
    ["O"] = "Zanieś Crown of Will do Sharlindry, w Undercity.",
    ["T"] = "Korona Woli",
  },
  [522] = {
    ["D"] = "To jest kontrakt na zamordowanie sędziego Henry\'ego Maleba. Został zapieczętowany przy użyciu czerwonego wosku i charakterystycznego sygnetu.",
    ["O"] = "Zanieś Assassin\'s Contract do sędziego Maleba w Southshore.",
    ["T"] = "Kontrakt zabójcy",
  },
  [523] = {
    ["D"] = "Kontrakt, który $gzdobyłeś:zdobyłaś;, nosi podpis Barona Vardusa, szlachcica z dawnego królestwa Alterak, znanego z zimnego serca i brutalnych zwyczajów. Nie jestem zaskoczony, że stał za tym ktoś taki jak Baron.$B$BZnajdź tego człowieka. Znajdź go i wymierz mu sprawiedliwość. Musi być wśród tych szumowin z Syndykatu - może w ruinach Strahnbradu, a może w dolinie na północ od nich.",
    ["O"] = "Przynieś Head of Baron Vardus sędziemu Malebowi z Southshore.",
    ["T"] = "Zgon barona",
  },
  [524] = {
    ["D"] = "W domu obok Strażnicy Śmierci przetrzymują kilku pojmanych rolników jako zakładników. Wysoka Egzekutorka Darthalia podejrzewała, że ukrywa się między nimi jeden z wojskowych strategów ze Stormwind. Okazuje się, że ten wojskowy został zeszłej nocy znaleziony martwy na Ziemiach Plagi. Darthalia, która zawsze o mnie pamięta, zadecydowała, że więźniowie są do mojej dyspozycji.$B$BMyślę, że nadszedł czas na urządzenie rolnikom przyjęcia. Brzmi rewelacyjnie, jak za dawnych czasów!$B$BPostaw tę skażoną beczkę na dywaniku w ich pokoju. Skażone piwo dla wszystkich!",
    ["O"] = "Postaw przeznaczoną dla pojmanych rolników Tainted Keg na dywaniku.",
    ["T"] = "Eliksir agonii",
  },
  [525] = {
    ["D"] = "Rozszyfrowałem list, ale nie wiem, co o nim sądzić. $gZnalazłeś:Znalazłaś; go u złodziei z podgórza Alteraku? Bardzo dziwne...$B$B$gPowinieneś:Powinnaś; zabrać go do sędziego z Southshore. Chociaż list nic nie tłumaczy, to jego miasto leży najbliżej Alteraku; jeśli coś złego wisi w powietrzu, powinien o tym wiedzieć.",
    ["O"] = "Zanieś Decrypted Letter do sędziego Maleba z Southshore.",
    ["T"] = "Kolejne tajemnice",
  },
  [526] = {
    ["D"] = "Mogłeś znaleźć jeden Lightforge Ingot w tym pudełeczku, ale to nie wystarczy do zrobienia czegoś porządnego!$B$BPowinieneś poszukać ich więcej. Może Murloki do okoła wraku statku je mają.",
    ["O"] = "Zbierz 5 Lightforge Ingots, potem wróć z powrotem do Glorin Steelbrow w Wetlands.",
    ["T"] = "Lightforge Ingots",
  },
  [527] = {
    ["D"] = "Stań na baczność, gdy się do mnie zwracasz, $C.$B$BPodlegam bezpośrednio Varimathrasowi. Naszym zadaniem jest zdławić opór ludzkiego robactwa, póki nasi aptekarze nie opracują nowej plagi.$B$BPozyskane informacje pozwalają wnioskować, że miasto Hillsbrad nie jest przygotowane na atak. Twoje pierwsze zadanie będzie miało na celu zniszczenie infrastruktury i odcięcie ich od zapasów żywności.$B$BUdaj się na zachód. Zaatakuj farmy wysunięte najbardziej na północ pól Hillsbrad. Dopilnuj, by właściciele tych ziem - farmer Ray i farmer Getz - również zostali straceni.",
    ["O"] = "Zabij 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmera Raya i Farmera Getza, a następnie zamelduj się u Darthalii w Tarren Mill.",
    ["T"] = "Bitwa o Hillsbrad",
  },
  [528] = {
    ["D"] = "Wieść o ataku na północne farmy wywołała panikę wśród mieszkańców miasta. Doskonale.$B$BNasi Umarli Tropiciele donoszą, że chłopi uciekli na pola na południu Hillsbradu. Głupcy; myślą, że mogą schować się w sadach i umknąć zagładzie.$B$BUdowodnij, że się mylą, $N. Wróć na pola Hillsbrad i znajdź ukrywających się chłopów. Zniszcz ich w imię naszej Mrocznej Pani.$B$BOdmaszerować!",
    ["O"] = "Zabij 15 Hillsbrad Peasants i zamelduj się u Darthalii w Tarren Mill.",
    ["T"] = "Bitwa o Hillsbrad",
  },
  [529] = {
    ["D"] = "Ludzie z Hillsbrad stawiają nieoczekiwany opór. Problem w tym, że tamtejszy kowal zbroi miejscowych. Musimy odciąć wszystkie linie zaopatrzenia.$B$BTwoją misją jest uśmiercić kowala Verringtana. Zabij też jego uczniów. Gdy będziesz na miejscu, zabierz też ładunek żelaza z ich zapasów. Przyda się, gdy skończymy z Hillsbrad i rozpoczniemy atak na Southshore.",
    ["O"] = "Zabij Blacksmith Verringtan i 4 Hillsbrad Apprentice Blacksmiths.$B$BOdzyskaj ładunek żelaza i zamelduj się u Darthalii w Tarren Mill.",
    ["T"] = "Bitwa o Hillsbrad",
  },
  [530] = {
    ["D"] = "Valdred, niegdyś mój dobry przyjaciel, zabił moją żonę. Chociaż nie potrafię już odczuwać żalu, pragnę zemsty. Jeśli zabijesz Valdreda i przyniesiesz mi jego przeklęte ręce, stosownie cię wynagrodzę.$B$BKiedy ostatnio o nim słyszałem, przebywał u podnóża Muru Szarogrzywego w południowych Silverpine Forest, próbując przedostać się do królestwa Gilneas.",
    ["O"] = "Zabij Valdreda Moraya.$B$BPrzynieś jego dłonie Raleighowi Andreanowi z Undercity.",
    ["T"] = "Zemsta męża",
  },
  [531] = {
    ["D"] = "Światłości! Nie przynoś takich rzeczy do leśniczówki... to niehigieniczne, niewyobrażalne, nie... nie... niehigieniczne!$B$BPo prostu zabieraj to stąd, dobra? Nikt nie chce oglądać twoich małych krwawych trofeów, słowo!",
    ["O"] = "Zanieś głowę Ol\' Sooty\'s do Vyrin Swiftwind z Farstrider Lodge.",
    ["T"] = "Zemsta Vyrin",
  },
  [532] = {
    ["D"] = "Miasto Hillsbrad ogarnął chaos. Wierzymy, że wkrótce upadnie. Jednakże nie możemy ustawać w naszych wysiłkach, dopóki ludzkie ścierwa na zawsze nie znikną z Podgórza.$B$BPomimo druzgoczących porażek, ludzie zbierają się wokół swoich przywódców i kontynuują opór. Musimy wyeliminować ich przywódcę, burmistrza Burnside\'a, a także radę miasta. Zniszcz również Proklamację Hillsbradu, ich szacowny polityczny dokument. A gdy już tam będziesz, wykradnij też miejski rejestr.",
    ["O"] = "Zabij Magistrate Burnside i 4 Hillsbrad Councilmen. Zniszcz Proklamację Hillsbrad. Wykradnij Rejestr Miasta Hillsbrad. Następnie zamelduj się u Darthalii w Tarren Mill.",
    ["T"] = "Bitwa o Hillsbrad",
  },
  [533] = {
    ["D"] = "Nareszcie wpadliśmy na jakiś ślad Gol\'dira i możemy w końcu spróbować odkryć miejsce jego pobytu. Ludzie wciąż go przenoszą, lecz ograniczymy nasze poszukiwania i skupimy się na dużym obozie Syndykatu na północ stąd.$B$BUdaj się tam, $N, i przynieś wszystkie informacje, jakie wpadną ci w ręce.",
    ["O"] = "Zdobądź informację o miejscu pobytu Gol\'dira dla Kruska z Tarren Mill.",
    ["T"] = "Infiltracja",
  },
  [534] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [535] = {
    ["D"] = "Urrgh... Ranny, umierający, i twarzą w twarz z wrogiem.$B$BBez wątpienia i tak mnie zabijesz, ale jeśli przyniesiesz mi trochę portera z Southshore - wasza rasa też pije, prawda? - powiem ci, co zechcesz wiedzieć.",
    ["O"] = "Przynieś kufel Southshore Stout do Valika, do obozu Syndykatu.",
    ["T"] = "Valik",
  },
  [536] = {
    ["D"] = "Przeniesiony ze straży miasta Stormwind do Southshore, miasta, które sprawia wrażenie opuszczonego... Smród portu w dzień i w noc.$B$BNie wspominając o starym Redpath\'cie... chce, bym zajął się murlokami. Ha!$B$BWzdragam się na samą myśl o wyprawie do kryjówki tych przerośniętych ryb na Western Strand. Gdybyś $gzechciał:zechciała; się tam udać i zająć się nimi za mnie, byłbym wdzięczny.",
    ["O"] = "Zabij 10 Torn Fin Tidehunters i 10 Torn Fin Oracles dla porucznika Farrena Orinelle\'a z Southshore.",
    ["T"] = "W dół wybrzeża",
  },
  [537] = {
    ["D"] = "List, który mi $gprzyniosłeś:przyniosłaś;, został napisany przez istotę, zwącą się Nagazem, członkiem Przebudzenia Argusa. Nie wiem, czym jest owo Przebudzenie, ale jeśli sprzymierzyli się z Syndykatem, stanowią dla nas zagrożenie.$B$BChcę, byś $godnalazł:odnalazła; Nagaza i wspomnianych w liście Magów Cienia Argusa Shadow. Chcę, byś ich $godnalazł i zabił:odnalazła i zabiła;.$B$BPrzeszukaj Uplands, tam, gdzie Syndykat jest najsilniejszy. To na północ od Strahnbradu.$B$BPrzy odrobinie szczęścia, znajdziesz tam wysłanników Przebudzenia Argusa.",
    ["O"] = "Zabij 4 Argus Shadow Mages.$B$BPrzynieś Head of Nagaz do sędziego Maleba z Southshore.",
    ["T"] = "Ciemna Rada",
  },
  [538] = {
    ["D"] = "$N, jeśli nie masz nic przeciwko długiej podróży, to mam dla ciebie zadanie. Chciałbym, byś ponownie $gpomógł:pomogła; uzupełnić zbiory biblioteki Stormwind.$B$BStare królestwo Alteraku upadło po wielkiej wojnie, a posiadało wielką kolekcję ksiąg. To straszne, że miasto zostało obrócone w ruiny, ale jeszcze straszniejsze jest to, że cała ta wiedza zaginęła! Musimy odzyskać, co się tylko da.$B$BNajbliżej Ruin Alteraku leży miasteczko Southshore. Udaj się tam i porozmawiaj z mędrcem Dibbsem. Skieruje cię do ruin i powie, jakie księgi można tam znaleźć.",
    ["O"] = "Porozmawiaj z mędrcem Dibbsem w Southshore.",
    ["T"] = "Southshore",
  },
  [539] = {
    ["D"] = "Rejestr miasta Hillsbrad wskazuje, że Kopalnia Azurelode znajduje się pod kontrolą Przymierza. Co więcej, jest głównym źródłem żelaza dla jego zbrojowni.$B$BChoć zadaliśmy krytyczny cios miastu Hillsbrad, Przymierze wciąż usilnie wspomaga i chroni Kopalnię Azurelode.$B$BLeży ona na południe od Hillsbrad. Udaj się tam i zabij miejscowego brygadzistę, człowieka nazwiskiem Bonds. Zabij też jego górników. To powinno przesłać Przymierzu jednoznaczną wiadomość.",
    ["O"] = "Zabij Foreman Bonds i 10 Hillsbrad Miners, a następnie zamelduj się u Darthalii w Tarren Mill.",
    ["T"] = "Bitwa o Hillsbrad",
  },
  [540] = {
    ["D"] = "Teraz w obrębie Alteraku mieszkają te bestialskie ogry i lękam się myśleć, co robią z drogocennymi księgami, które tam pozostały. Musisz odzyskać, co tylko się da!$B$BUdaj się do Ruin Alteraku i poszukaj ksiąg zagrabionych przez ogry. Zbierz wszystko, co wpadnie ci w ręce i przynieś do mnie, ale rozejrzyj się też za jedną konkretną księgą: \"Ramieniem Gri\'leka\". Zawiera starożytną wiedzę trolli, którą muszę poznać, a Ruiny Alteraku były ostatnim znanym miejscem pobytu jej kompletnego egzemplarza.",
    ["O"] = "Przynieś 5 Recovered Tomes i Worn Leather Book, zawierającą \" Arm of Gri\'lek\", mędrcowi Dibbsowi z Southshore.",
    ["T"] = "Ratowanie wiedzy",
  },
  [541] = {
    ["D"] = "Krasnoludy wspierają ludzi? Szlag by trafił te wstrętne małe potworki.$B$BPoddamy próbie siłę tego tak zwanego Przymierza. Zobaczymy, jak chętne do pomocy ludziom będą te kurduple, kiedy już poczują nasz gniew. Znamy dokładne położenie ich fortecy na tych ziemiach.$B$BW południowo-wschodnim Hillsbrad, pod Murem Thoradina, wybudowali koszary zwane Dun Garok. Szturm na nie to ostatnia misja tej bitwy, $C. Ich dowódca, kapitan Ironhill, musi umrzeć.",
    ["O"] = "Udaj się do Dun Garok i zabij 8 Mountaineers, 4 Riflemen, 2 Priests oraz Captain Ironhill, a następnie zamelduj się u Darthalii w Tarren Mill.",
    ["T"] = "Bitwa o Hillsbrad",
  },
  [542] = {
    ["D"] = "Potrzebuję trochę czasu na lekturę \"Ramienia Gri\'leka\", którą mi $gdostarczyłeś:dostarczyłaś;, lecz jestem pewien, że Milton pali się z niecierpliwości, by włączyć resztę odzyskanych ksiąg do zbiorów w Stormwind.$B$BOto książki, które $gzdobyłeś:zdobyłaś; w Ruinach Alteraku; zapakowane i skatalogowane. Zabierz je do Miltona Sheafa, do Stormwind; jestem pewien, że będzie bardzo wdzięczny.",
    ["O"] = "Zanieś Tomes of Alterac do Miltona Sheafa ze Stormwind.",
    ["T"] = "Wróć do Miltona",
  },
  [543] = {
    ["D"] = "Tiara Perenoldów to stare dziedzictwo \"szlachty\" z rodu Perenolde - dynastii władającej Alterakiem, nim królestwo obróciło się w ruinę. Powiadają, że wykonali go najlepsi jubilerzy z Ironforge, którzy osadzili w nim najpiękniejszy ze szmaragdów.$B$BDiadem przepadł wraz ze zniszczeniem Alteraku, jednak wieść niesie, że znalazł go mag ogrów, Grel\'borg Chciwy, obecnie wałęsający się po ruinach Alteraku w poszukiwaniu innych skarbów.$B$BPragniemy, byś $gzdobył:zdobyła; dla nas ten diadem.",
    ["O"] = "Przynieś Perenolde Tiara do Remingtona Ridgewella ze Stormwind.",
    ["T"] = "Diadem Perenoldów",
  },
  [544] = {
    ["D"] = "Przybyłem do Tarren Mill w celach badawczych, teraz jednak muszę zaradzić kryzysowi. Widzisz, parę miesięcy temu czworo Opuszczonych uciekło z Undercity. Odwrócili się od swego rodzaju, lecz co gorsza... okradli Mroczną Panią.$B$BOwi złodzieje włamali się do strzeżonego skarbca i wynieśli stamtąd cztery artefakty, przedmioty niezbędne naszym aptekarzom do pewnych badań. Sylvanas pragnie je odzyskać.$B$BOpuściwszy Undercity złodzieje zbiegli do Dalaranu, zaś tamtejsi czarodzieje poddali ich kwarantannie w obozie dla internowanych w Lordamere.",
    ["O"] = "Znajdź zdrajców i odzyskaj ich artefakty, następnie wróć do Maga Voidglare\'a, do Tarren Mill.",
    ["T"] = "Włamanie do więzienia",
  },
  [545] = {
    ["D"] = "Czarodzieje z Dalaranu otoczyli centrum swego miasta ogromną, magiczną kopułą. Niektórzy uważają, że zrobili to dla ochrony przed brutalnością dzisiejszych czasów, inni - że po prostu zapragnęli odosobnienia, by prowadzić swe badania i intrygi.$B$BNie interesuje mnie powód. Znaczenie ma dla mnie fakt, że leżące poza kopułą zrujnowane przedmieścia Dalaranu mogą skrywać cenne magiczne przedmioty.$B$BNiestety, obszar ten patrolują czarodzieje i spętane przez nich żywiołaki.$B$BZapoluj na nich i wróć, gdy dostatecznie zredukujesz ich liczbę.",
    ["O"] = "Zabij 6 Dalaran Summoners i 12 Elemental Slaves, następnie wróć do Tarren Mill, do maga Voidglare\'a.",
    ["T"] = "Patrole Dalarańczyków",
  },
  [546] = {
    ["D"] = "Słyszałem, że Darthalia zwerbowała cię do oddziałów toczących wojnę z ludźmi z Hillsbrad. Tak ci zazdroszczę...$B$BPodczas gdy tobie przypadnie w udziale cała zabawa - wyżynanie ludzi, plądrowanie miasta, terroryzowanie niewinnych - ja ugrzęzłem tutaj, na straży Tarren Mill.$B$BMoże ulitujesz się nad starym Umarłym Strażnikiem? Widzisz, zbieram ludzkie czaszki. A ty przez pewien czas będziesz walczyć z ludźmi. W trakcie tej długiej walki zbierz dla mnie 30 czaszek, a wynagrodzę ci twój czas.",
    ["O"] = "Umarły Strażnik Samsa z Tarren Mill chce 30 Hillsbrad Human Skulls.",
    ["T"] = "Pamiątki zgonu",
  },
  [547] = {
    ["D"] = "Wielka Egzekutorka Darthalia zleciła mi obserwację Dun Garok. Rozbiłem obóz zaraz poza zasięgiem wzroku. Ale o poranku musiałem zagotować wodę, więc poszedłem nazbierać chrustu. $B$BGdy wróciłem do obozu, odkryłem brak mojego ekwipunku. $B$BNajwyraźniej jacyś krasnoludzcy zwiadowcy z Dun Garok przechodzili tamtędy i go zabrali. Potrzebuję mojego miecza! Gdybyś $gmógł:mogła; go dla mnie odzyskać, byłbym bardzo wdzięczny. Tam jest dużo krasnoludów... ciężko będzie znaleźć tego małego, paskudnego złodzieja, który go ukradł.",
    ["O"] = "Odzyskaj miecz Strażnika Śmierci Humberta z Dun Garok i przynieś mu go do Tarren Mill.",
    ["T"] = "Miecz Humberta",
  },
  [548] = {
    ["D"] = "This will start the Bloodstone Pendant quest line...<NYI>",
    ["O"] = "",
    ["T"] = "<NYI> <TXT> Bloodstone Pendant",
  },
  [549] = {
    ["D"] = "Z rozkazu Lady Sylvanas, wszyscy członkowie organizacji znanej jako Syndykat mają być zabici. Osoby doprowadzone do aresztu lub wzięte w niewole zostaną stracone. Obecnie wiadomo, że mają zgromadzenie w ruinach Twierdzy Durnholde, na południowy wschód od Tarren Mill.$B$BPokaźna nagroda dla wszystkich, którzy przyniosą dowód ich czynów do Wysokiej Egzekutorki Darthalii.",
    ["O"] = "Zabij 10 Syndicate Rogues i 10 Syndicate Watchmen. Wróć do Wysokiej Egzekutorki Darhalii w Tarren Mill po nagrodę.",
    ["T"] = "Poszukiwany: Grupa Syndicate",
  },
  [550] = {
    ["D"] = "Z uwagi na twą dzielność i wytrwałość okazane podczas Bitwy o Hillsbrad, przygotowałam ten list polecający, chwalący twe czyny bitewne, przeznaczony do wiadomości najwyższego dowództwa.$B$BZabierz ten zapieczętowany dokument do Varimathrasa, do Undercity. Krocz z dumą, $C.",
    ["O"] = "Zabierz Darthalia\'s Sealed Commendation do Varimathrasa z Undercity.",
    ["T"] = "Bitwa o Hillsbrad",
  },
  [551] = {
    ["D"] = "Na pergamin nałożone jest zaklęcie, uniemożliwiające jego odszyfrowanie. Można jednak odczytać jedno słowo z początku strony:$B$BNagaz",
    ["O"] = "Zanieś Ensorcelled Parchment do mędrca Dibbsa z Southshore.",
    ["T"] = "Zaklęty pergamin",
  },
  [552] = {
    ["D"] = "Mistrz Helcular niemalże ukończył swą transformację w lisza, kiedy ludzka tłuszcza odnalazła kryjówkę we wzgórzach, w której odprawiał rytuał, i dokonała na nim brutalnego linczu. Jakby tego było mało, pochowali jego ciało na cmentarzu w Southshore. $B$BTaki brak szacunku w stosunku do wielkiego czarodzieja jest nie do przyjęcia. Jako jego uczeń dopilnuję, by nawałnica zemsty spadła na miasto Southshore.$B$BPo pierwsze, będziemy potrzebować Różdżki Helculara. Yeti opanowały kryjówkę, w której odprawiał obrzęd. Bez wątpienia jeden z nich ma różdżkę.",
    ["O"] = "Odzyskaj Helcular\'s Rod z łap yeti i zanieś ją do nowicjusza Thaivanda z Tarren Mill.",
    ["T"] = "Zemsta Helculara",
  },
  [553] = {
    ["D"] = "Proszę, weź Różdżkę Helcular. Będzie ci potrzebna.$B$BNa potrzeby swego najpotężniejszego zaklęcia Helcular rozpalił 3 ceremonialne ognie. Ogień Azela i Ogień Veraza znajdziesz w Jaskini Foothill. Ogień Uzela znajduje się w jaskini ponad grotami, na północ, głębiej w górach.$B$BRóżdżkę Helculara trzeba napełnić mocą każdego z tych trzech płomieni. Kiedy ukończysz obrzęd, zanieś ją na grób Helculara w Southshore - leżącym na południu, silnie strzeżonym mieście ludzi. Zemsta będzie należeć do nas!",
    ["O"] = "Napełnij Rod of Helcular mocą zawartą w płomieniach: Flame of Azel, Flame of Veraz i Flame of Uzel.$B$BZanieś naładowaną różdżkę na grób Helculara w Southshore.",
    ["T"] = "Zemsta Helculara",
  },
  [554] = {
    ["D"] = "Badacz Stormpike to mistrz łamania kodów i szyfrów. Jeśli zaniesiesz mu znaleziony pergamin, przy odrobinie szczęścia będzie mógł wydobyć z niego jakiś sens. Stormpike prowadzi obecnie swe badania w kwaterze głównej Poszukiwaczy w Ironforge.$B$BKiedy go spotkasz, powiedz mu, że przychodzisz ode mnie - ostatnio przesyłam mu całkiem sporo rzeczy.",
    ["O"] = "Zabierz Ensorcelled Parchment do badacza Stormpike\'a z Ironforge.",
    ["T"] = "Odczytanie przez Stormpike\'a",
  },
  [555] = {
    ["D"] = "Jeśli chodzi o Southshore, możesz być $gpewien:pewna; jednego - mamy tu jedną z najlepszych kuchni na północ od Stormwind!$B$BWeźmy na przykład mój przepis na żółwiową zupę. Są ludzie, którzy przyjeżdżają tu aż z Darkshire, tylko po to, by zjeść jej talerz. Choć skoro już o tym mowa, nie miałem ostatnio możliwości jej przygotować. Niegdyś zapuszczałem się za Dalaran, nad Jezioro Lordamere, by osobiście polować na kłapioszczęki, teraz jednak jest to zbyt niebezpieczne. Jeśli dostarczysz mi nieco żółwiego mięsa z kłapioszczęków z północy oraz przyprawy, trochę jej nagotuję!",
    ["O"] = "Przynieś 10 kawałków Turtle Meat do szefa kuchni Jessena z Southshore.",
    ["T"] = "Delikatna żółwiowa zupa",
  },
  [556] = {
    ["D"] = "Godnym uwagi talentem czarodziejów z Dalaranu jest ich zażyłość z żywiołkami - potężnymi stworami z innych wymiarów. Czarodzieje ci używają magicznych symboli jako środka kontroli tych istot. Mag Voidglare chciałby zbadać kilka z nich.$B$BUdaj się na zachód od Hillsbrad, na terytorium Dalaranu, by zdobyć kamienne symbole tamtejszych czarodziejów.$B$BPrawdopodobnie znajdziesz je u każdego napotkanego mieszkańca Dalaranu, lecz osobiście doradzałbym polowanie na terenie obozu internowania. Jest bezpieczniejszy, niż sam Dalaran.",
    ["O"] = "Przynieś 10 Worn Stone Tokens do opiekuna Bel\'varila z Tarren Mill.",
    ["T"] = "Kamienne symbole",
  },
  [557] = {
    ["D"] = "Mag będzie zajęty studiowaniem tych kamiennych symboli, które $gzebrałeś:zebrałaś;, lecz wiedz, że w końcu będzie chciał ich odpowiednik: naramienniki związania. Są one umiejscowione na nadgarstkach żywiołaków i przyłączone do nich za sprawą magii.$B$BWytrop te żywiołaki w ruinach Dalaranu i zbierz ich naramienniki, a wtedy mag będzie zadowolony.",
    ["O"] = "Przynieś 4 Braces of Earth Binding opiekunowi Bel\'varilowi w Tarren Mill.",
    ["T"] = "Naramienniki związania",
  },
  [558] = {
    ["D"] = "Mówią, że Lady Jaina Proudmoore z Theramore jest jednym z największych bohaterów w historii Alliance. Kiedy dorosnę też chcę zostać bohaterem!$B$BZnasz Jaine, $N? Mógłbyś wyświadczyć mi przysługę? Mógłbyś zdobyć dla mnie jej autograf? Nie wiem jak ją o to zapytać, pewnie będzie zbyt zajęta dla kogoś takiego jak ja... ale ty! Ty jesteś poszukiwaczem przygód tak samo jak ona! Jestem przekonany, że da ci swój autograf bez żadnego problemu!$B$BProszę, zrobisz to dla mnie?",
    ["O"] = "Udaj się do Theramore, aby zobaczyć, czy uda ci się zdobyć autograf Jainy Proudmoore dla swojego pupila.",
    ["T"] = "Autograf Jainy",
  },
  [559] = {
    ["D"] = "Możesz w to uwierzyć, $N? Redpatch nie był usatysfakcjonowany zabiciem przez nas wszystkich tych murloków - och, nie bądź $gskromny, też miałeś:skromna, też miałaś; w tym udział. Teraz chcę, abyś $gprzyniósł:przyniosła; mu dowód ich śmierci, zimne, śliskie, odrąbane głowy, w celu zdobycia jego uznania.",
    ["O"] = "Zbierz 10 Murloc Heads z murloków na zachodnim brzegu dla porucznika Farrena Orinelle w Southshore.",
    ["T"] = "Dowód Farrena",
  },
  [560] = {
    ["D"] = "Wiesz, $N, wolałbym naprawdę nie brać tych głów... Skoro już $gpodjąłeś:podjęłaś; tą pracę, to może zaniesiesz je Redpathowi?",
    ["O"] = "Dostarcz torbę głów murloków marszałkowi Redpathowi w Southshore.",
    ["T"] = "Dowód Farrena",
  },
  [561] = {
    ["D"] = "Proszę, poinformuj porucznika Orinelle, iż chciałbym, aby skupił swoje wysiłki na zagrożeniu nag na Eastern Strand. Kiedy osiągnie rezultaty, powiedz mu, żeby zgłosił się do mnie osobiście.",
    ["O"] = "Porozmawiaj z porucznikiem Farrenem Orinelle w Southshore.",
    ["T"] = "Dowód Farrena",
  },
  [562] = {
    ["D"] = "Mój poprzedni mentor z miasta Stormwind wysłał do mnie wiadomość, że dowództwo Przymierza coraz bardziej martwi się zagrożeniem ze strony nag. Z tego co słyszał, są duże szanse na awans - albo chociaż na zmianę stanowisk - dla każdego, kto udowodni swoją wartość w tej sprawie.$B$BJest tylko jeden mały problem... Nie dam sobie rady z nagami, $N. Och, z pewnością, mógłbym wywołać karczmienną bójkę albo rozwalić nos napastliwemu żebrakowi, ale nagi to dla mnie za wiele. Musisz mi pomóc, $N!",
    ["O"] = "Zabij 10 Daggerspine Shorehunters i 10 Daggerspine Sirens dla porucznika Farrena Orinelle w Southshore.",
    ["T"] = "Stormwind Ho!",
  },
  [563] = {
    ["D"] = "Nie powinno być problemu z dostarczeniem mojego listu. Nowy kapitan straży, major Samuelson, był moim mentorem, kiedy stacjonowałem w Stormwind. Powinno to być dla niego wystarczającym powodem, żeby przenieść mnie z powrotem do miasta. Jednak będę potrzebował, abyś $gzaniósł:zaniosła; mu mój raport... nie chciałbym, żeby stary Redpath mnie z nim zobaczył.",
    ["O"] = "Dostarcz Farren\'s report do majora Samuelsona w Stormwind Keep.",
    ["T"] = "Zmiana stanowiska",
  },
  [564] = {
    ["D"] = "Nie ma nic co drażni mnie bardziej niż strata tych pięknych koni. A możesz mi wierzyć, straciliśmy ich dość sporo z powodu tych upierdliwych nieumarłych odmieńców, cholernego gangu Syndykatu i innych, do niczego nie przydatnych bestii.$B$BAle przysięgam na grób mojego staruszka i matuchny, że nie ma większego zagrożenia dla naszych koni niż te górskie lwy z Alteraku. Zawsze schodzą z tych wzgórz utrudniając mi życie!$B$BLubisz zwać się $gbohaterem:bohaterką;? Więc idź tam i zrób coś!",
    ["O"] = "Darren Malvew w Southshore chce, abyś $gzabił:zabiła; 8 Mountain Lions i 10 Hulking Mountain Lions.",
    ["T"] = "Kosztowne Zagrożenie",
  },
  [565] = {
    ["D"] = "Ja, wielki Bartolo, uszyję ci światowej sławy płaszcz ze skór yeti!$B$BZaklinam cię, przemierz cały świat i znajdź lepszy płaszcz, jeśli tylko się odważysz. Czekaj, cóż ja słyszę, $R7? \"Bartolo, nie ma na świecie lepszego płaszcza!\" Tak, tak! Już to wcześniej słyszałem.$B$BPotrzebuje kłębka wełny, płaszcza Hillmana zrobionego przez utalentowanego rymarza, ozdobną nić i skóry yeti! Przynieś mi te przedmioty, a staniesz się szczęśliwym nabywcą!",
    ["O"] = "Przynieś do Bartolo Ginsetti z Southshore: Bolt of Wool, Hillman\'s Cloak, Fine Thread i 10 Yeti Fur.",
    ["T"] = "Płaszcz Bartolo ze skóry yeti",
  },
  [566] = {
    ["D"] = "Z rozkazu Wysokiej Egzekutorki Darthalii, człowiek znany jako Baron Vardus jest poszukiwany za zbrodnie przeciwko Opuszczonym. Vardus jest wysoko postawionym członkiem organizacji znanej jako Syndykat.$B$BOstatnio widziano go w Uplands w Górach Alterak na północy od Tarren Mill.$B$BJest on poszukiwany tylko martwy. Przynieś dowód jego śmierci Wysokiej Egzekutorce Darthalii by uzyskać nagrodę.",
    ["O"] = "Zabij Barona Vardusa i przynieś jego głowę do Wysokiej Egzekutorki Darthalii w Tarren Mill.",
    ["T"] = "POSZUKIWANY: Baron Vardus",
  },
  [567] = {
    ["D"] = "Niebezpieczeństwo!$B$BPoniżej wymienione osoby z Hillsbrad zostały uznane jako niebezpieczne i Wysoki Egzekutor Darthalia wyznaczyła za nich nagrody:$B$BHorrace Whitesteed. Poszukiwany za morderstwo Strażnika Śmierci Toma.$B$BObywatel Wilkes. Poszukiwany za morderstwo aptekarza Eli.$B$BGórnik Hackett. Poszukiwany za morderstwo Umarłego Tropiciela Fry.$B$BFarmer Kalaba. Poszukiwany za zasadzkę na zapasy z Undercity.$B$BWszyscy z nich są wrogami, których ciężko znaleźć. Nagroda zostanie przyznana po zawiadomieniu o ich śmierci.",
    ["O"] = "Wielki Egzekutor Darthalia z Tarren Mill oferuje nagrodę za Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett i Farmer Kalaba.",
    ["T"] = "Niebezpieczeństwo!",
  },
  [568] = {
    ["D"] = "Throm\'ka, $C!$B$BPrzybyłeś do Grom\'gol w samą porę. Jako komandor bazy naszego Wodza, tutaj w dżungli, jestem zobligowany na honor do zapewnienia bezpieczeństwa wszystkim członkom Hordy. Nasza misja polegająca na zapewnieniu bezpiecznego łańcucha dostaw do Stonard jest zagrożona poprzez działalność tutejszej fauny.$B$B Powierzam ci zadanie, by nieco przerzedzić populacje Raptorów grasujących w okolicy. Gdy tylko poczynisz znaczące postępy, zgłoś się do mnie po kolejne zadanie.",
    ["O"] = "Komandor Aggro\'gosh z bazy Grom\'gol chce, byś zabił 15 Lashtail Raptors.",
    ["T"] = "Obrona Grom\'gol",
  },
  [569] = {
    ["D"] = "Gdy przybyliśmy do tej wioski, nie mieliśmy zamiaru toczyć wojny z miejscowymi plemionami. Naszym głównym zadaniem było zaopatrzenie Stonard. Ale pojawiły się pewne... komplikacje. Miejscowe ogry zajmują ruiny Mizjah na południowym - wschodzie od Grom\'gol. Pomimo ostrzeżeń, wciąż atakują nasze karawany z dostawami.$B$BLiczę, że poradzisz sobie z tymi niechcącymi współpracować ogrami.$B$BUdaj się do tych ruin i spróbuj pozbyć się ich stamtąd. To powinni zrozumieć.",
    ["O"] = "Dowódca Aggro\'gosh z obozu Grom\'gol chce, byś zabił 10 Ogre Brutes i 5 Ogre Witch Doctors.",
    ["T"] = "Obrona Grom\'gol",
  },
  [570] = {
    ["D"] = "Moc dżungli musi zostać okiełznana, a następnie wykorzystana przez Hordę. Moje dotychczasowe rytuały okazały się wielkim sukcesem. Mogę rzucać potężne zaklęcia. Mogę dla Ciebie, dzielny $C przygotować specjalny przedmiot.$B$BPrzynieś mi trochę Shadowmaw Panther claws oraz Tigress fang. Jednak pamiętaj, że byle pazur nie wystarczy. Musi być w idealnym stanie.$B$BBestie czają się w całej dżungli, ale najbliższe znajdziesz po drugiej stronie rzeki na południowy wschód od Mizjah Ruins.",
    ["O"] = "Widzący Mok\'thardin z bazy Grom\'gol chce dostać 8 Shadowmaw Claws oraz Pristine Tigress Fang.",
    ["T"] = "Zaklinanie Mok\'thardin\'a",
  },
  [571] = {
    ["D"] = "To czego teraz od ciebie potrzebuję jest bardzo ciężkie do zdobycia.$B$BAby utrzymać pióra, pazury, oraz pierwotny kieł w miejscu potrzebuję specjalnej, magicznej linki. Tylko ścięgno Elder Mistvale Gorilla się do tego nada.$B$BMusisz znaleźć Elder Mistvale Gorilla, a następie zdobyć jego ścięgno. Z tego co wiem występują one na wschodzie Booty Bay, jednak pamiętaj, że ścięgno musi być idealne. Znalezienie go może wymagać zabicia wielu zwierząt, jednak efekt będzie warty swej ceny.",
    ["O"] = "Far Seer Mok\'thardin z Grom\'gol chce, żebyś mu przyniósł Aged Gorilla Sinew",
    ["T"] = "Zaklęcie Mok\'thardina",
  },
  [572] = {
    ["D"] = "Przedmioty zebrane przez Ciebie z kocich bestii to tylko pierwszy składnik wymagany do stworzenia potężnego przedmiotu. Te drobiazgi w połączeniu z moim rytuałem dostarczą ci wielu pożytecznych narzędzi do wspierania Hordy, oraz naszego Wodza.$B$BAle teraz musisz zebrać dla mnie trochę Jungle Stalker Feathers. Na południe od Grum\'gol, niedaleko wielkiej areny, znajdziesz plemię raptorów, które tradycyjnie nosi pióra na swoich opaskach.",
    ["O"] = "Far Seer Mok\'thardin z bazy Grom\'gol prosi Cię o zebranie 10 Jungle Stalker Feathers",
    ["T"] = "Zaklęcie Mok\'thardina",
  },
  [573] = {
    ["D"] = "Do ukończenia zaklęcia potrzebuję jeszcze jednego składnika.$B$BNa południu, w pobliżu zachodniego wybrzeża, ponad urwiskami znajduje się Holy Spring. Jest ono przedmiotem olbrzymiego konfliktu między badaczami religii i magii. Każda rasa Azeroth twierdzi, że bogowie stworzyli jego święte wody właśnie dla niej.$B$BMoja ostatnia prośba brzmi następująco: przynieś mi wodę ze Świętego Źródła. Lecz uważaj. Ekspedycja nag odkrywców dotarła prawie pod samo źródło. Korzystając z okazji należy się nimi zająć.",
    ["O"] = "Jasnowidz Mok\'thardin z Bazy Grom\'gol potrzebuje Holy Spring Water. Chce także, byś zabił 10 Naga Explorers.",
    ["T"] = "Zaklęcie Mok\'thardina",
  },
  [574] = {
    ["D"] = "Teraz, gdy duża część jego podstawowych oddziałów została zniszczona, musisz zmierzyć się z jego lepiej wyszkolonymi siłami. Gdy nie są zajęci mordowaniem w dziczy naszych żołnierzy, przebywają głęboko na tyłach Kurzen Compound, w jaskini, którą nazywają Stockpile.$B$BZnam wielu z nich osobiście i wiem, że są zdolni, lojalni i okrutni. Powierzam ci niełatwe zadanie, $N.$B$BJak tylko ich pokonasz, zamelduj się u mojego dowódcy , Lieutenanta Dorena. Zechce usłyszeć o tym z pierwszej ręki.",
    ["O"] = "Zabij 10 Kurzen Commandoes i 6 Kurzen Headshrinkers.$B$BZamelduj się u Lieutenanta Dorena, w Rebel Camp.",
    ["T"] = "Oddziały specjalne",
  },
  [575] = {
    ["D"] = "\"Najlepszy kuśnierz Mórz Południowych oraz starego i nowego świata\". Tak mnie nazywają. Mnie! Drizzlika! Najlepszy kuś... Ekhm. Cóż.$B$BMoje wyroby ze skóry znane są wzdłuż i wszerz ze swej jakości, to wybór koneserów!$B$BWłaśnie otrzymałem zamówienie od Kierownika Riddlevoxa z Cechu Majsterkowiczów na tuzin jego ulubionych butów z kolekcji Excelsior. Prawdę mówiąc to nasz najlepiej sprzedający się model.$B$BBy w ogóle zacząć, potrzebuję krokodylich skór znad rzeki w północnej części Doliny Stranglethorn.",
    ["O"] = "Przynieś 2 Large River Crocolisk Skins do Drizzlika z Booty Bay.",
    ["T"] = "Podaż i popyt",
  },
  [576] = {
    ["D"] = "Stać! Kto idzie?$B$BArgh, bez mojego specjalnego magicznego oka prawie do niczego się nie nadaję. Przede wszystkim miałem pecha, że straciłem moje oczy w bitwie! Ale szczęśliwy traf pchnął nas do Przystani Menethil, gdzie wędrujący czarodziej zaczarował dla mnie specjalne szklane oko, które pozwoliło mi znów widzieć.$B$BZeszłej nocy po drodze napadli mnie Bloodsail Buccaneers. Zabrali moje oko, właśnie tak! Wygląda na to, że ci goście znaleźli jakieś wejście do Booty Bay.$B$BPomożesz staremu wilkowi morskiemu odzyskać jego oko?",
    ["O"] = "Jednooki Dizzy z Booty Bay chce, byś odzyskał jego oko od Bloodsail Buccaneers.",
    ["T"] = "Trzymaj oko na wierzchu",
  },
  [577] = {
    ["D"] = "Cóż, mam już ogólny kształt butów; wyglądają coraz lepiej, ale skóry, którą przyniosłeś, nie wystarczy na wewnętrzne warstwy.$B$B\"I co teraz zrobimy, Drizzliku\"? Bez wątpienia to pytanie ciśnie ci się na usta, więc czyż to nie szczęście że rozmawiasz z Drizzlikiem, ponieważ on zaraz ci powie, co teraz zrobimy!$B$BWewnętrznych warstw tak naprawdę nigdy nie widać, więc do wypełnienia użyjemy grubszych, tańszych skór krokodyli znad Jeziora Nazferiti.",
    ["O"] = "Przynieś 5 Snapjaw Crocolisks Skins do Drizzlika z Booty Bay.",
    ["T"] = "Niezbędny montaż",
  },
  [578] = {
    ["D"] = "Jeśli wyspę rzeczywiście nawiedził gobliński mag i żywiołaki wody, oznacza to, że Stone of the Tides może być mój!$B$BChcę byś odszukał tę nawiedzoną wyspę... wywiedział się, co się tam dzieje. Och, a jeśli chcesz dowiedzieć się więcej o Stone of the Tides, zabierz tę kartę do Biblioteki Stormwind; powinni móc załatwić ci kopię książki, w której po raz pierwszy spotkałem się z tą legendą.$B$BCzy to możliwe, by Gazban naprawdę odnalazł Kamień...?",
    ["O"] = "Odszukaj nawiedzoną wyspę dla Barona Revilgaza z Booty Bay.",
    ["T"] = "Kamień Fal",
  },
  [579] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Biblioteka Stormwind",
  },
  [580] = {
    ["D"] = "Raczyliśmy się czymś mocniejszym, a na horyzoncie wznosiły się Strzeliste Klify starego dobrego Hinterlands. Myśleliśmy, że morze połknie nas w całości.$B$BStary Slim wie wszystko o odwadze w płynie! Kapitan miał skrzynkę Porto Pupellyverbosa, którą zarekwirowaliśmy korsarzom w drodze do Stormwind.$B$BWięc gdy dorwała nas burza z Hinterlands, ja dorwałem się do trunku. Ale uderzyła w nas wielka fala i butelki wypadły za pokład. Kapitan pokaże mi gdzie raki zimują, jeśli nie pomożesz mi ich odzyskać!",
    ["O"] = "Whiskey Slim z Booty Bay chce, byś przyniósł mu butelki Porto Pupellyverbosa, które zgubił.",
    ["T"] = "Zaginiony trunek Whiskeya Slima",
  },
  [581] = {
    ["D"] = "Biada, zaiste biada. Klątwa spadła na Yenniku, najmłodszego syna mojego wodza. Jak to jest u nas w zwyczaju, został poddany pod opiekę trollom Gurubashi z Zul\'Gurub, lecz po tym jak moje plemię, Darkspear, wyruszyło z orkiem Thrallem, straciliśmy biedaka. Wysłano mnie z dalekiego Orgrimmaru z powrotem do Doliny Stranglethorn, bym odnalazł syna mego dowódcy. $B$BI sądzę, że wpadł w ręce Bloodscalp.$B$BJeśli chcesz mi pomóc, zapoluj na Bloodscalp. Znajdziesz ich na północy. Zbierz ich kły i wróć do mnie.",
    ["O"] = "Przynieś Nimboyi z Bazy Grom\'gol 9 Bloodscalp Tusks.",
    ["T"] = "W poszukiwaniu Yenniku",
  },
  [582] = {
    ["D"] = "Musimy się dowiedzieć, czy Yenniku jest martwy.$B$BWybij Bloodscalp Headhunters i zabierz im ich Shrunken Heads. Musisz zdobyć dużo, dużo głów, a ja sprawdzę, czy między nimi nie ma przypadkiem głowy Yenniku.$B$BA jeśli Yenniku został zabity przez Bloodscalp, niech sześćsetletnia klątwa spadnie na duszę ich wodza, Gan\'zulaha!$B$BIdź, $N. Wielu Headhunters znajdziesz w ruinach Zuuldaia i Zul\'Kunda, u wybrzeża na północy.",
    ["O"] = "Przynieś Nimboyi z Bazy Grom\'gol 20 Shrunken Heads.",
    ["T"] = "Polowanie na głowy",
  },
  [583] = {
    ["D"] = "Witaj w Dolinie Stranglethorn!$B$BMoże nie jesteś tego $gświadom:świadoma;, ale tamten krasnolud to syn, właśnie tego Hemeta Nesingwary\'ego, sławnego bohatera wojennego Przymierza i mistrza polowania na grubego zwierza. Jak jego ojciec, niezbyt chętnie widzi obcych w swoim obozie, ale ty wyglądasz, jakbyś $gwidział:widziała; całkiem sporo bitew w swoim życiu, $C.$B$BIdź z nim porozmawiać. To nieodrodny syn swego ojca, więc może będzie mógł dać ci kilka łowieckich wskazówek.",
    ["O"] = "Porozmawiaj z Hemetem Nesingwarym Juniorem.",
    ["T"] = "Witamy w dżungli",
  },
  [584] = {
    ["D"] = "Głowy Yenniku nie było pośród tych, które mi przyniosłeś, za co zanoszę dzięki Wielkiemu Wężowi. Jednak wcale nie przybliżyliśmy się do odnalezienia Yenniku.$B$BMusimy poznać prawdę, a obawiam się, że znają ją tylko wódz szczepu Bloodscalp i jego znachor. Są wrogami szczepu Darkspear i nie zdradzą jej nam dobrowolnie, więc musimy wydrzeć ją z ich martwych warg!$B$BPrzynieś mi głowy Gan\'zulaha i Nezzlioka Straszliwego i umieść je w tym kotle.$B$BPrzebywają w głębi Zul\'Kundy. Przynieś ich głowy... sprawimy, że przemówią.",
    ["O"] = "Przynieś głowy Gan\'zulaha i Nezzlioka do wrzącego kotła w Bazie Grom\'gol.",
    ["T"] = "Głowy szczepu Krwawych Skalpów",
  },
  [585] = {
    ["D"] = "\"Głowa Nezzlioka odzywa się\".$B$BTo prawda. Wiem, gdzie zabrano dziecko Darkspears. Pokonałeś mnie i uwięziłeś mą duszę, ale nic nie powiem, póki mnie nie udobruchasz!$B$BBloodscalps wojują z Skullsplitters. By zdobyć moje względy, ukradnij Skullsplitters ich trzy zdobyczne czaszki i wrzuć je tutaj, do nas, dzięki czemu moja dusza będzie miała sługusów w Otchłani. Jedna z czaszek musi pochodzić ze stosu trofeów w Balia\'mah, druga z Ziata\'jai, a trzecia z Zul\'Mamwe.",
    ["O"] = "Przynieś Trofeum z Balia\'mah, Trofeum z Ziata\'jai i Trofeum z Zul\'Mamwe do Wrzącego Kotła w Bazie Grom\'gol.",
    ["T"] = "Rozmowa z Nezzliokiem",
  },
  [586] = {
    ["D"] = "\"Głowa Gan’zulaha przemawia\".$B$BPrzeklinam cię! I twoich przodków!!$B$BTylko krew i zemsta może ostudzić mą wściekłość, więc jeśli tego sobie życzysz, to... zrób to:$B$BWedrzyj się do serca ziem szczepu Skullsplitters na wschodzie. Zabij najbardziej zajadłych spośród nich, a jeśli przeżyjesz... staw czoła ich wodzowi, Ana\'thekowi Bezlitosnemu. Hah! Przynieś mi jego strzaskany pancerz, jeśli potrafisz!$B$BNiech rozedrze cię na strzępy i pozostawi, byś zgnił, a zwierzęta szarpały twe zwłoki.",
    ["O"] = "Zabij 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters i 4 Skullsplitter Berserkers.$B$BPrzynieś Broken Armor of Ana\'thek do Wrzącego Kotła w Bazie Grom\'gol.",
    ["T"] = "Rozmowa z Gan\'zulahem",
  },
  [587] = {
    ["D"] = "Ach, życie morskie. Nie mogę powiedzieć, żeby było dobre, ale to moje życie.$B$BKiedy dopływam do portu, lubię, gdy czeka na mnie łyknę butelka dobrego grogu i wspaniała tabaka. Paskudne nałogi, lecz kimże jest pirat bez jego wad, racja?$B$BWyobraź sobie więc moje niepocieszenie, gdy okazało się, że zielarz z tego miasta wyprzedał towar i odjechał. Powiedział, że jego dostawy zostały przechwycone przez tych parszywych Bloodsail Raiders.$B$BZałożę się, że odważny $C taki jak ty potrafi ich przekonać, aby podzielili się towarem, co?",
    ["O"] = "Deeg z Booty Bay chciałby, abyś dostarczył mu 15 Porcji Tabaki.",
    ["T"] = "Wysokiej jakości towar",
  },
  [588] = {
    ["D"] = "\"Nezzliok przemawia.\"$B$BUradowałeś mnie i wodza, dlatego powiem ci czego szukasz…$B$BMłody Yenniku jest stracony dla swego ludu.$B$BZostał uprowadzony przez znachora Zanzil the Outcast. Zanzil kontroluje jego ciało i duszę i jedynie potężna magia może go uwolnić.$B$BMagia, którą nie władasz, $C.$B$BMoże twoi sprzymierzeńcy z klanu Darkspear znajdą szansę na ocalenie Yenniku. Ale wątpię w to.",
    ["O"] = "Porozmawiaj z Kin\'weelayem.",
    ["T"] = "Los Yenniku",
  },
  [589] = {
    ["D"] = "Legendy wspominają o klejnocie, ukrytym głęboko w sercu Stranglethorn. Nazywamy je Okiem Umysłu (Mind\'s Eye), posiada ono wielką moc. Gdybyś zdobył Oko, być może udałoby się przy jego pomocy wyprowadzić Yenniku z ciemności.$B$BRozmówię się z duchami dżungli, aby zlokalizować Oko Umysłu. W tym czasie ty udasz się do Crystalvein Mine na południowy wschód stąd i zbierzesz Pulsing Blue Shards z Ironjaw Basilisks. Kryształy są rzadkością, lecz będziemy potrzebowali ich magii, aby podporządkować Oko Umysłu naszej woli.",
    ["O"] = "Przynieś 3 Pulsing Blue Shards do Kin\'weelaya z Bazy Grom\'gol.",
    ["T"] = "Śpiewające kryształy",
  },
  [590] = {
    ["D"] = "Co?$B$BCo?!$B$BChcesz pieniędzy? Nie jestem ci nic winien.$B$BList? Jaki list? Och, więc chcesz walczyć? Dobra, herosie... zaczynajmy! Że niby ci wiszę...",
    ["O"] = "Pokonaj Calvina Montague\'a w Deathknell.",
    ["T"] = "Złodziejska sprawa",
  },
  [591] = {
    ["D"] = "Oko Umysłu posiada mag ogrów, przebywający na wschód stąd, głęboko w kopcu ogrów Mosh\'Ogg. Jego imię to Mai\'Zoth. Znam go z czasów, gdy klan Darkspears mieszkał w Stranglethorn - jest okrutny, a jego magia potężna.$B$BA skoro posiada Oko Umysłu, będzie jeszcze potężniejsza.$B$BMusisz zmierzyć się z Mai\'Zothem i wydrzeć mu Oko Umysłu. To niebezpieczne zadanie, ale to jedyna nadzieja na uratowanie Yenniku.",
    ["O"] = "Przynieś Oko Umysłu Kin\'weelayowi z Bazy Grom\'gol.",
    ["T"] = "Oko Umysłu",
  },
  [592] = {
    ["D"] = "Przekształciłem Oko Umysłu w Klejnot Duszy. Użyjesz go dwa razy: ogłuszysz nim Yenniku, a następnie umieścisz klejnot na jego głowie, aby schwytać jego duszę.$B$BNastępnie dostarczysz klejnot do Nimboyi.$B$BYenniku przebywa wraz z Zanzil the Outcast pośród Ruins of Aboraz, położonych wzdłuż Crystal Shore na odległym Cape of Stranglethorn.",
    ["O"] = "Dostarcz Filled Soul Gem do Nimboya.",
    ["T"] = "Na ratunek Yenniku",
  },
  [593] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Napełnienie Klejnotu Duszy",
  },
  [594] = {
    ["D"] = "Na kartce napisano eleganckim pismem:$B$BDo każdego, kto może mi pomóc -$B$BProszę, ogromnie potrzebuję ratunku. Wielki Skymane przetrzymuje mnie na wyspie na South Seas. $B$BGwiazdy na niebie są mi obce i zakrywają je drzewa z dżungli, lecz w pogodne dni dostrzegam Wild Shore na północnym zachodzie oraz coś przypominającego wielkie żaglowce na południowym zachodzie.$B$BBłagam, mój przyszły wybawicielu, pomóż mi.",
    ["O"] = "Znajdź autora wiadomości z butelki.",
    ["T"] = "List w butelce",
  },
  [595] = {
    ["D"] = "Wyglądasz, jak ktoś, kto pali się do roboty. Nie rozumiem, dlaczego jakiś $R $C, typowy szczur lądowy, oferuje swą pomoc Blackwater Raiders, lecz nie odrzucę twej propozycji.$B$BNasz statek właśnie dopłynął do Booty Bay i przyniósł wiadomość, że nasi wrogowie - ci przeklęci, plugawi Bloodsail Buccaneers - rozprzestrzenili się w całym południowym Stranglethorn.$B$BChłopcy z załogi są zbyt zajęci popijaniem grogu i rozglądaniem się za panienkami! A ja potrzebuję zwiadowcy.$B$BZbadaj zatoczkę na północ od Booty Bay, leżącą obok Savage Coast i spróbuj się czegoś dowiedzieć.",
    ["O"] = "First Mate Crazz chce, abyś zbadał zatoczkę na północ od Booty Bay.",
    ["T"] = "Piraci Krwawych Żagli",
  },
  [596] = {
    ["D"] = "Przysłano mnie do Grom\'gol, bym pomógł Nimboyi w wykonaniu jego zadania, lecz... mam też swoje powody, aby tu przebywać.$B$BSzczep Bloodscalp jest wrogiem naszego plemienia. Zbieranie trofeów z naszego wroga czyni nas silniejszymi od niego. Możesz wspomóc nasze plemię polując na naszych wrogów.$B$BMieszkają na północy. Zabijaj trolli Bloodscalp i zabierz im ich naszyjniki z krwawych kości. Zbierz ich wiele, a nagroda będzie okazała.",
    ["O"] = "Przynieś 25 Bloody Bone Necklaces do Kin\'weelaya z Bazy Grom\'gol.",
    ["T"] = "Naszyjniki z krwawych kości",
  },
  [597] = {
    ["D"] = "Mapa pokazuje Booty Bay z czerwonym \"X\" nakreślonym dokładnie w miejscu, w którym się znajdujesz.$B$BNagryzmolony tekst mówi:$B$B\"Załóżcie obóz w tym miejscu i siedźcie cicho. Czekajcie na sygnał do ataku z południowego posterunku. Jeśli ktokolwiek się zbliży - zabijcie.\"",
    ["O"] = "Donieś o okryciu First Mate Crazzowi z Booty Bay.",
    ["T"] = "Piraci Krwawych Żagli",
  },
  [598] = {
    ["D"] = "Teraz, gdy już zebrałeś trofea Bloodscalp, mam dla ciebie kolejne zadanie. Plemię Skullsplitter zamieszkuje obszary na południowym wschodzie; przez lata toczyliśmy z nimi wojny. Chociaż Darkspears nie mieszkają już w Stranglethorn, ciągle jesteśmy w konflikcie z Skullsplitters.$B$BWięc zapoluj na nich. Zbierz ich Split Bone Necklaces i wróć do mnie. Dopomóż nam w naszej wojnie, a zaskarbisz sobie przyjaźń Darkspears.",
    ["O"] = "Przynieś 25 Split Bone Necklaces do Kin\'weelaya z Bazy Grom\'gol.",
    ["T"] = "Naszyjniki z łupanych kości",
  },
  [599] = {
    ["D"] = "O żesz! Więc Bloodsail Buccaneers planują jakiś atak na Booty Bay? Mają tupet. Booty Bay na zawsze pozostanie pod kontrolą Blackwater Raiders!$B$BTo poważniejsza sprawa niż mi się wydawało. Natychmiast przekaż wieści Dowódcy Floty Seahornowi! Stary wilk morski na pewno kręci się gdzieś po mieście...",
    ["O"] = "Donieś o planowanym ataku Bloodsail do Fleet Master Seahorna.",
    ["T"] = "Piraci Krwawych Żagli",
  },
  [600] = {
    ["D"] = "Venture Company rozwinęła w Stranglethorn sieć działań, które przeszkadzają uczciwie zarabiać ciężko pracującym goblinom, takim jak ja! Proszę, musisz mi pomóc!$B$BVenture Company kopie niedaleko Crystalvein Mine na północy. Nie mogą przedostać się do kopalni z powodu tych wszystkich bazyliszków, ale dają radę wydobywać Singing Crystals z okolicznych wzgórz.$B$BZabierz im te kryształy i pokaż, że nie rządzą dżunglą.$B$BI... ee... przynieś mi te kryształy jako dowód!",
    ["O"] = "Przynieś 10 Singing Blue Crystals do Cranka Fizzlebuba z Booty Bay.",
    ["T"] = "Oddział Górniczy Venture Company",
  },
  [601] = {
    ["D"] = "Nie ma wątpliwości, że żywiołaki wody zostały przyzwane przez Gazbana, goblińskiego czarodzieja, który ponoć odnalazł Kamień Fal. Jak wiesz, Kamień Fal przeklina jego właściciela sprawiając, że ten przenika z bytu w nicość...$B$BByć może znajdziemy sposób na zdjęcie klątwy. Mag z Dalaranu mógłby przestudiować magiczne pozostałości na jednej z obręczy żywiołaków wody. Chciałbym, abyś udał się na wyspę i zdobył kilka okazów.",
    ["O"] = "Zdobądź 6 Water Elemental Bracers dla Barona Revilgaza z Booty Bay.",
    ["T"] = "Żywiołaki wody",
  },
  [602] = {
    ["D"] = "Z tego co słyszałem, magowie z Dalaranu są zajęci odbudową ich zniszczonego miasta, ale jestem pewien, że jeden z nich poświęci trochę czasu, żeby obejrzeć te karwasze. Jedno wiem o magach na pewno - nie potrafią oprzeć się zagadkom magii.$B$BWeź torbę z obręczami żywiołaków wody i sprawdź, czy rzucą trochę światła na sprawę klątwy Kamienia. Odszukaj Arcymaga Ansirema Runeweavera. Miałem z nim już do czynienia - jego wiedza jest ogromna.",
    ["O"] = "Zanieś obręcze żywiołaków wody do Arcymaga Ansirema Runeweavera z Dalaranu.",
    ["T"] = "Magiczne badania",
  },
  [603] = {
    ["D"] = "Mag będący w posiadaniu Kamienia wzmacnia jego moc przez jakieś punkty skupienia... jakiś rodzaj ołtarza. Powinieneś być w stanie to przerwać, przeciwstawiając mu inną moc.$B$BTak się składa, że znam odpowiedni przedmiot: starożytny sztylet, kolejny relikt trolli. Jest tylko... jeden mały problem.$B$BWidzisz, znalazłem sztylet podczas badań w Dolinie Stranglethorn, ale dałem go mojej córce, Catelyn, która uciekła do Booty Bay, by zostać piratem.",
    ["O"] = "Porozmawiaj z Catelyn z Booty Bay.",
    ["T"] = "Klucz Ansirema",
  },
  [604] = {
    ["D"] = "Crazz wyraża się pochlebnie o twoim oddaniu Blackwater Raiders. Zamierzam powierzyć ci misję o ogromnym znaczeniu dla floty. $B$BPrzeniknij do tak zwanego południowego stanowiska dowodzenia, które Bloodsail Buccaneers założyli w Wild Shore. Zaatakuj ten obóz. Przynieś mi ich mapy morskie oraz pisma z rozkazami. Zobaczymy co dokładnie kombinują te szumowiny.",
    ["O"] = "Fleet Master Seahorn w Booty Bay chce, abyś zabił 10 Bloodsail Swashbucklers i przyniósł z powrotem Bloodsail Charts (28,83) i Bloodsail Orders (27,83).",
    ["T"] = "Piraci Krwawych Żagli",
  },
  [605] = {
    ["D"] = "Singing Crystals występują tylko w Stranglethorn i dla niektórych są bardzo cenne. Mógłbym przewieźć Kryształy, ale ta przeklęta Venture Company utrudnia ich zbieranie uczciwym przedsiębiorcom, takim jak ja!$B$BChciałbym cię zatrudnić.$B$BBazyliszki ze Stranglethorn zjadają kryształy. Dzięki temu mają twardą skórę, i czasami można z niej zebrać kryształy dobrej jakości.$B$BMożesz je zdobyć na dowolnych bazyliszkach, ale te mniej groźne znajdziesz na północ stąd, wzdłuż wybrzeża na południe od Zul\'Kundy.",
    ["O"] = "Przynieś 10 Singing Crystal Shards do Cranka Fizzlebuba.",
    ["T"] = "Śpiewające niebieskie odłamki",
  },
  [606] = {
    ["D"] = "Jeśli jest coś, czego nienawidzę, to ludzie, którzy nie płacą swoich długów hazardowych! A jest wielu takich, którzy są moimi dłużnikami. Sądzisz, że możesz pomóc mi ściągnąć długi?$B$BNa początek, w dokach przebywa \"Shaky\" Phillipe. Sporo mi wisi po zeszłotygodniowej grze i chcę moją należność! Jednak żeby ją dostać, musimy go przestraszyć.$B$BIdź za miasto i zapoluj na Elder Mistvale Gorillas. Znajdź ładną partię wnętrzności, potem zanieś je do \"Shaky\". Nie daj mu poznać, że są ze zwierząt; niech myśli o najgorszym.",
    ["O"] = "Przynieś 5 Mistvale Giblets do \"Shaky\" Phillipe\'a z Booty Bay.",
    ["T"] = "Wystraszyć Drżączkę",
  },
  [607] = {
    ["D"] = "Masz, weź tę sakiewkę i oddaj ją Wilkowi Morskiemu. Powiedz mu, że naprawdę chciałem spłacić dług! Przysięgam!!$B$BTylko trochę się upiłem, straciłem orientację, i... wiesz jak to jest. Zrozumie - nie musisz być taki nieuprzejmy!",
    ["O"] = "Zanieś Shaky\'s Payment do \"Sea Wolf\" MacKinleya.",
    ["T"] = "Wróć do MacKinleya",
  },
  [608] = {
    ["D"] = "Ależ ten Firallon ma tupet! Nie potrafiłby przepłynąć łódeczką po Kryształowym Jeziorze, a co dopiero poprowadzić przeciwko nam całej floty.$B$BBloodsail Buccaneers zapłacą za swoją bezmyślność. Teraz, gdy znamy ich plany ataku, możemy ich poprowadzić swój, zanim zorientują się, co się dzieje.$B$BJednak po co wysyłać całą flotę, by wykonała robotę odpowiednią dla jednego odważnego oddziału poszukiwaczy przygód? $N, zabierz swoich najzręczniejszych towarzyszy na miejsce desantu Firallona i zamorduj przywódców Bloodsail. Ich flota zatonie chwilę później...",
    ["O"] = "Fleet-Master Seahorn z Booty Bay chce, byś zabił Captain Stillwater, Captain Keelhaul i Fleet Master Firallon.",
    ["T"] = "Piraci Krwawych Żagli",
  },
  [609] = {
    ["D"] = "Moja lista się skraca, ale są jeszcze ludzie, którzy są mi coś winni.$B$BDalej mamy Maury\'ego \"Club Foot\" Wilkinsa, Jon-Jona Kruka i Chucky\'ego \"Ten Thumbs\".$B$BTe podłe psy nie płacą swoich długów od miesięcy i sądziłem, że opuścili miasto by uniknąć zapłaty! Później usłyszałem, że zostali przeklęci i włóczą się teraz po ruinach w dżungli. Mnie jednak nie obchodzi ich los - chcę tego, co moje!$B$BSą w Ruins of Aboraz i w Ruins of Jubuwal na północny wschód stąd. Znajdź ich i odbierz należność.",
    ["O"] = "Przynieś Maury\'s Clubbed Foot, Jon-Jon\'s Golden Spyglass, i Chucky\'s Huge Ring do \"Sea Wolf\" MacKinleya z Booty Bay.",
    ["T"] = "Długi voodoo",
  },
  [610] = {
    ["D"] = "Mój OJCIEC Cię wysłał? Myślałam że ten staruch już zrezygnował.$B$BTo naprawdę nie jego wina, że uciekłam, nie powinien oczekiwać, że będę gotowa na nudne życie, czytanie zatęchłych książek oraz spotykanie się ze szpakowatymi, sztywnymi magami!$B$BJeśli potrzebujesz mojego sztyletu musisz go odzyskać od \"Pretty Boy\" Duncan, jednego z Bloodsail Buccaneers. Jestem pewna, że odda ci go jeśli użyjesz odpowiednich argumentów.",
    ["O"] = "Daj Catelyn sztyler z \"Pretty Boy\" Duncan.",
    ["T"] = "\"Pretty Boy\" Duncan",
  },
  [611] = {
    ["D"] = "Więc szukasz jakiegoś rodzaju ołtarza? No, nie jestem takim ekspertem od ruin trolli jak mój ojciec, ale słyszałam o zatopionym mieście trolli niedaleko tej wyspy, której szukasz. Może tam powinieneś spróbować?$B$BPrzyniosłeś mi moje ostrze, więc myślę, że możesz je pożyczyć... ale chcę je z powrotem kiedy skończysz!",
    ["O"] = "Zniszcz Altar of the Tides przy pomocy Catelyn\'s Blade, zabij Gazbana i zanieś Stone of the Tides oraz Catelyn\'s Blade do Barona Revilgaza.",
    ["T"] = "Klątwa Fal",
  },
  [613] = {
    ["D"] = "Do diabła! Maury założył zamek na swoją nogę i nie mogę go otworzyć! Łup, który jest mi dłużny, jest wewnątrz nogi.$B$BMusimy znaleźć klucz, żeby otworzyć zamek. Maury\'ego znano z tego, że uprawiał hazard z ogrami z klanu Mosh\'Ogg, na ich pagórku, na północny wschód stąd. Gdy jeszcze żył, powiedział mi, że ostatnim razem, gdy był na tym pagórku, został przegoniony po tym, jak wygrał zbyt dużo. Może tamtejsze ogry mają jego klucz.$B$BJeśli tak, może będziesz musiał zabić ich całe mnóstwo, by znaleźć tego właściwego.",
    ["O"] = "Przynieś Maury\'s Key do \"Sea Wolf\" MacKinleya z Booty Bay.",
    ["T"] = "Włamanie do nogi Maury\'ego",
  },
  [614] = {
    ["D"] = "Kiedyś pływałem statkiem stąd aż do Ratchet w Kalimdorze. Byłem świetnym kapitanem o doskonałej reputacji.$B$BDopóki...$B$BPrzeklęte morskie olbrzymy zrujnowały mnie! Rozbiły mój statek, zabiły załogę, a mnie posłały w szalupie w kierunku Booty Bay. Jeden z olbrzymów, Gorlash, ukradł moją kapitańską skrzynię. Powiedział, że chce ją na tabakierkę. Jak śmiał!$B$BSłyszałem, że Gorlash włóczy się po wybrzeżu na wschód stąd. Znajdź go i odzyskaj moją skrzynię! Zrób to, a zasłużysz na kapitańską wdzięczność.",
    ["O"] = "Przynieś Smotts\' Chest do Hecklebury Smottsa w Booty Bay.",
    ["T"] = "Skrzynia kapitana",
  },
  [615] = {
    ["D"] = "Kiedy z powodu olbrzymów straciłem pierwszy statek, kupiłem następny. Nazwałem go \"Zemsta Smottsa\", zapełniłem go zapasami, dobrałem załogę i wypłynąłem szukać tych łotrów. Znalazłem ich, ale... mnie pokonali. Strzaskali \"Zemstę Smottsa\", zabili drugą załogę, a mnie znów odesłali w szalupie.$B$BTym razem inny olbrzym, Negolash, ukradł mój pałasz.$B$BZmierz się z Negolashem i przynieś mi go!$B$BPorozmawiaj ze Sproggerem. Był kucharzem na \"Zemście Smottsa\" i przeżył ostatni atak. Pomoże ci znaleźć olbrzyma.",
    ["O"] = "Porozmawiaj ze Sproggerem.",
    ["T"] = "Kapitański pałasz",
  },
  [616] = {
    ["D"] = "Baron Revilgaz kazał mi zwracać uwagę na plotki o dziwnych miejscach w Booty Bay i dolinie Stranglethorn. Zwykle nie daję wiary opowieściom o duchach, ale słyszałem, jak kilku marynarzy opowiadało w tawernie o nawiedzonej wyspie obok wybrzeża. Mówili o żywiołakach wody i obłąkanym duchu goblina.$B$BJeśli zamierzasz porozmawiać z Revilgazem, może przekażesz mu tę historię?",
    ["O"] = "Porozmawiaj z Baronem Revilgazem z Booty Bay.",
    ["T"] = "Nawiedzona wyspa",
  },
  [617] = {
    ["D"] = "Szukasz pracy, $N? Może mam coś, o ile szukasz wyzwań.$B$BMam przyjaciela, nazywa się Groy, który obławia się, sprzedając coś, co nagi nazywają akirisową trzciną: to pewien rodzaj cennej trzciny morskiej. Nie jestem pewien, na co mu ona, ale dobrze płaci za wiązki tego towaru.$B$BPrzynieś mi dziesięć łodyg tej trzciny, a ubijemy interes. Nagi ostatnio widziano wzdłuż plaży na północ stąd.",
    ["O"] = "Przynieś 10 Bundles of Akiris do Privateera Bloadsa z Booty Bay.",
    ["T"] = "Wiązka akirisu",
  },
  [618] = {
    ["D"] = "Negolash to kawał pasibrzucha.$B$BPodczas gdy inne olbrzymy niszczyły nasz statek, Negolash udał się prosto do kuchni. Nie miał ochoty na załogę, jak tamte. Negolash miał ochotę na wino... i na moją specjalność, grillowane myszołowie skrzydełka. Wyobraź sobie, że po przepis musiałem się pofatygować aż do Badlands!$B$BJeżeli chcesz go zwabić, weź trochę wina i górę skrzydełek myszołowów i umieść je w naszej szalupie. Stoi na południowy wschód stąd, idąc wzdłuż wybrzeża. Kiedy Negolash zwęszy taką wyżerkę, na pewno nią nie pogardzi!",
    ["O"] = "Przynieś 10 Barbecued Buzzard Wings i 5 butelek Junglevine Wine do Szalupy Kapitana Smottsa.$B$BZabij Negolasha i przynieś Smotts\' Cutlass do Kapitana Smottsa w Stranglethorn.",
    ["T"] = "Staw czoła Negolashowi",
  },
  [619] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Wabienie Negolasha",
  },
  [620] = {
    ["D"] = "This fine sash has the letters \"HS\" embroidered along its hem.",
    ["O"] = "Return the Monogrammed Sash to its owner.",
    ["T"] = "The Monogrammed Sash",
  },
  [621] = {
    ["D"] = "Zanzil Wygnaniec zamieszkuje wraz ze swoimi poplecznikami Ruiny Jubuwai i Aboraz, na północny wschód od Booty Bay. Został wygnany ze swojego plemienia. Dlaczego? Cóż...$B$BZanzil zna metody, które pozwalają przenikać cudze umysły i jego przywódcy się go boją. Używa na swoich poplecznikach mikstury z roślin z dżungli, która osłabia ich wolę i wzmacnia ciało.$B$BJego mikstura ma wielką wartość dla tych, którzy chcą kontrolować innych.$B$BPrzynieś mi jej próbki, a znajdę dla niej zastosowanie.",
    ["O"] = "Przynieś 12 próbek Mikstury Zanzila do Cranka Fizzlebuba z Booty Bay.",
    ["T"] = "Sekret Zanzila",
  },
  [622] = {
    ["D"] = "Gdy cię nie było, naprawiłem kociołek, który mi przyniosłeś. Dodałem nawet ekstra gwizdek na parę, ale spójrz! Na dole zamontowałem nowy tasak, którym bez problemu przetniesz kości!$B$BTak tak, Mechaniczny Garnek Krazeka to 100% satysfakcji dla kucharza! Jestem pewien, że właściciel będzie zadowolony.",
    ["O"] = "Przynieś Krazek\'s Fixed Pot do Corporala Kaleba z Rebel Camp.",
    ["T"] = "Powrót do Kaprala Kaleba",
  },
  [623] = {
    ["D"] = "$N, kiedy cię nie było, dostałem wiadomość od Groya. Wspomniał, że jest zadowolony z ostatniej przesyłki i ma klienta, który chce więcej tego towaru.$B$BNie zamierzam wybrać się do Theramore w ciągu najbliższego tygodnia, ale jeżeli planujesz podróż, nie ma przeciwwskazań, żebyś dostarczył przesyłkę.$B$BGotów na przygodę? Wiesz gdzie leżą Dustwallow Marsh, nie? Jednak uważałbym, dla niektórych Theramore może być niebezpiecznym miejscem.",
    ["O"] = "Przynieś Bundle of Akiris Reeds do Privateera Groya w Theramore.",
    ["T"] = "Wiązka akirisu",
  },
  [624] = {
    ["D"] = "Zdobiony, przejezdny most jest przez bród$BNa południe od Redridge, od Przełęczy na wschód$BCoś czeka na ciebie pod deskowym stropem$BNazwij to wskazówką, lub nazwij to tropem$BPoleży tam wieki, spływ dni nic nie znaczy$BPoczeka cierpliwie na Bagnach Rozpaczy",
    ["O"] = "Rozwiąż zagadkę!",
    ["T"] = "Zagadka Cortella",
  },
  [625] = {
    ["D"] = "Daleka kraina w Kalimdorze czeka$BGdzie los odbiera nadzieję człowieka$BNa wschód od Pustkowi wiecznie zła pogoda$BW Pylistych Moczarach groza dłoń ci poda$BLecz jest tam wskazówka dla tych, co się odważą$BNa południowym zachodzie spoczywa w pieczarze",
    ["O"] = "Rozwiąż zagadkę!",
    ["T"] = "Zagadka Cortella",
  },
  [626] = {
    ["D"] = "Do Lordaeronu! Kraju zawieruchy$BGdzie dzielni żołnierze padają jak muchy$BSpróbuj znaleźć drogę przez te niepokoje$BA wreszcie zakończysz to zadanie swoje$BWzdłuż brzegów Ostępów, pod wodospadami$BSkarb czeka znalazcy pod wody masami!",
    ["O"] = "Rozwiąż zagadkę!",
    ["T"] = "Zagadka Cortella",
  },
  [627] = {
    ["D"] = "Daleko na północy, w Arathi Highlands, w Drywhisker Gorge leży pewna jaskinia. W tej jaskini znajduje się rzadka ruda: krwawnik. Tamtejsze krwawniki nie są najwyższej jakości, ale nawet te są drogocenne... dla tych, którzy wiedza jak ich użyć.$B$BChciałbym kilka.$B$BNaprawię twój garnek, ale kiedy będę nad nim pracował... przynieś mi próbki krwawnika. Przynieś ich wystarczająco dużo, a dostaniesz ode mnie coś więcej.$B$BOch, a jeśli nie umiesz ich wykopać... znajdź kogoś kto potrafi!",
    ["O"] = "Przynieś 4 ładunki Lesser Bloodstone Ore do Krazeka z Booty Bay.",
    ["T"] = "Przysługa dla Krazeka",
  },
  [628] = {
    ["D"] = "Wnętrze skończone, jeszcze tylko zewnętrzna warstwa. Do tego używam tylko najlepszej krokodylej skóry. Jest o wiele wytrzymalsza; stanowi też lepszy podkład pod - jeśli sobie tego życzysz - rysunek znaków i akcentów typowych dla mojej linii Excelsior.$B$BCiężko znaleźć odpowiednią skórę; jedyną, która będzie pasowała do mojego planu, jest skóra starszego słonowodnego krokodyla. Starsze wychodzą jedynie, by bronić młodszych słonowodnych krokodyli, więc będziesz musiał zabić kilka, by zwabić jednego.",
    ["O"] = "Przynieś Elder Crocolisk Skin do Drizzlika z Booty Bay.",
    ["T"] = "Excelsior",
  },
  [629] = {
    ["D"] = "Dawno temu wielkie trzęsienie ziemi zatopiło stare miasto trolli pod wodami Savage Coast na północnym zachodzie. Nazywamy to miejsce Vile Reef, gdyż obecnie ruiny te zamieszkują murloki, atakujące każdego, kto się zbliży.$B$BPośród tych ruin znajduje się tablica, opowiadająca historię Gri\'leka, bohatera trollich legend. Ta opowieść jest święta dla szczepu Darkspear, lecz tablica jest zbyt duża by ją przenieść. Chcę odłamek tej tablicy, aby móc czcić go w naszym nowym domu - Orgrimmarze.",
    ["O"] = "Przynieś Tablet Shard (25,33) do Kin\'weelaya z Grom\'gol Base Camp.",
    ["T"] = "Potworna Rafa",
  },
  [630] = {
    ["D"] = "$N, pokładam nadzieję w tobie i w każdym, kogo możesz sprowadzić, aby mnie uwolnić. Wielki Skymane King Mukla jest tym, który mnie tu więzi. Dowodzi on bestiami na tej wyspie i za pomocą tych łańcuchów trzyma mnie tutaj wbrew mej woli. Jeśli możesz zabić go i znaleźć klucz do tych zamków, będę ci niezmiernie wdzięczna.$B$BCzęsto słyszę go od południowo-wschodniej strony wyspy, ale proszę, uważaj: nie można go lekceważyć.",
    ["O"] = "Zabij Króla Muklę i wróć do Princess Poobah z Kluczem, aby ją uwolnić.",
    ["T"] = "List w butelce",
  },
  [631] = {
    ["D"] = "Wzgórzami wstrząsnęła olbrzymia eksplozja. To było straszne, mówię ci!$B$BDobrzy żołnierze zginęli broniąc Przęsła Thandola. Longbraid mówi, że nim to wszystko się skończy, zemścimy się na klanie Czarnorytnych.$B$BLecz nie jest nam lekko, a do tego nie widzę żadnych posiłków. Longbraid wysłał Starego Rustlocke\'a na wschodni most, żeby sprawdził czy można go zabezpieczyć.$B$BTo było kilka dni temu. Nie mamy wystarczająco ludzi, aby szukać go, kiedy Dun Modr jest oblężone.$B$BMoże ty spróbujesz go znaleźć...",
    ["O"] = "Rhag Garmason chce, byś $gznalazł:znalazła; Ol\' Rustlocke.",
    ["T"] = "Przęsło Thandola",
  },
  [632] = {
    ["D"] = "Wygląda na to, że biedny stary Rustlocke wpadł w zasadzkę klanu Czarnorytnych. Obok jego zaciśniętej pięści znajdujesz zapisany pergamin.$B$BZgłoś tą ponurą wiadomość Rhagowi Garmasonowi i pokaż mu, co $gznalazłeś:znalazłaś;.",
    ["O"] = "Wróć do Rhaga Garmasona i pokaż mu pergamin, który $gznalazłeś:znalazłaś; przy ciele Rustlocke\'a.",
    ["T"] = "Przęsło Thandola",
  },
  [633] = {
    ["D"] = "Niebiosa, nie! Biedny Rustlocke. To prawdziwa tragedia.$B$BNie możemy pozwolić, by jego śmierć poszła na marne. Znaleziony przez ciebie pergamin wskazuje, że stojący za pierwotnym atakiem Kam Deepfury zorganizował tuż za Przęsłem Thandola, w Arathi Highlands, zapas materiałów wybuchowych. $B$BJeśli wybuchną i zniszczą most, nasz główny szlak zaopatrzeniowy na północ zostanie przerwany! Musisz zniszczyć ten skład, $N! Wróć do mnie po zakończeniu swej misji.$B$BJesteś naszą jedyną nadzieją.",
    ["O"] = "Zniszcz zapas ładunków wybuchowych.",
    ["T"] = "Przęsło Thandola",
  },
  [634] = {
    ["D"] = "Proszę cię, $C, o jeszcze jedną drobną przysługę. Czekamy na posiłki z Ironforge. Niemniej Roggo słyszał o obozie Przymierza położonym na północ stąd, o Obozie Uchodźców w Arathi Highlands.$B$BUdaj się tam i odszukaj panią kapitan Nials. Poproś dobrą panią kapitan o użyczenie kilku żołnierzy, którzy pomogliby nam odzyskać Dun Modr i Przęsło Thandola.",
    ["O"] = "Odszukaj kapitana Nials w Refuge Pointe.",
    ["T"] = "Apel do Przymierza",
  },
  [635] = {
    ["D"] = "Odłamek pulsuje w twej dłoni...$B$BOdczuwasz emanujące z kryształu błaganie, jakby ktoś starał się skontaktować; ktoś, komu desperacko potrzebna jest twa pomoc.$B$BW twych myślach pojawia się obraz gór na północy Arathi oraz lśniącego kryształu, wyrastającego z tamtejszej ziemi.$B$BTo miejsce cię wzywa.",
    ["O"] = "Odnajdź kryształ ze swojej wizji.",
    ["T"] = "Kryształ w sercu gór",
  },
  [636] = {
    ["D"] = "This book tells the tale of an elemental princess, Myzrael, and of her imprisonment deep underneath the Arathi Highlands.$B$BIt also tells of a secret outcropping of crystals in the highlands.  These crystals, the Shards of Myzrael, are a window to the princess\' prison.$B$BIf a brave soul found the Shards of Myzrael, the perhaps $ghe:she; could speak with her...",
    ["O"] = "Find the Shards of Myzrael.",
    ["T"] = "Legends of the Earth <NYI>",
  },
  [637] = {
    ["D"] = "Podniszczona, nasiąknięta wodą koperta rozpada się w twych dłoniach, pozostawiając po sobie kilka zapisanych maczkiem stron listu.$B$BList zaadresowano do Pani Sary Balloo z Ironforge; rozpoczyna się słowami \"Kochana Saro...\"",
    ["O"] = "Dostarcz Sarze Balloo List Sully\'ego Balloo.",
    ["T"] = "List Sully\'ego Balloo",
  },
  [638] = {
    ["D"] = "Po śmierci Thorasa Trollbane\'a i zburzeniu Stromgarde Vol\'jin polecił nam podjąć wszelkie niezbędne działania, by wykraść legendarny miecz Trol\'kalar z rąk ludzi, abyśmy mogli użyć go w nadchodzących bitwach z trollami z Zul\'Gurub.$B$BZengu, nasz doświadczony łowca, został skierowany do położonego w północno-wschodniej części Arathi Highlands - Hammerfallu. Ma nadzorować to przedsięwzięcie.",
    ["O"] = "Udaj się do Hammerfallu w Arathi Highlands i pomów z Zengu.",
    ["T"] = "Trollbane",
  },
  [639] = {
    ["D"] = "W dawnych czasach, gdy trolle walczyły z Imperium Arathor, naszym najgroźniejszym przeciwnikiem był Lord Ignaeus, pan na Strom, zwany Trollbane. Ruszał on w bój dzierżąc Trol\'kalar - co w dawnym języku ludzi znaczyło \"pogromca trolli\".$B$BDziś jednak synowie Trollbane\'a są słabi, zaś ich forteca popadła w ruinę.$B$BMiecz chroni kilka pieczęci, które rozdzielono między ocalałych mieszkańców Stromgarde; musimy je odzyskać.$B$BPierwszą z nich zabrał Syndykat; któryś z jego agentów w Stromgarde powinien ją mieć.",
    ["O"] = "Zdobądź Sigil of Strom dla Zengu z Hammerfallu.",
    ["T"] = "Pieczęć Strom",
  },
  [640] = {
    ["D"] = "Grobowiec Thorasa Trollbane\'a chronią trzy pieczęcie - pierwszą z nich zabrałeś Syndykatowi. Pozostałe będą trudniejsze do zdobycia, są bowiem w posiadaniu okopanych w Stormgarde bojowników.$B$BSyn Thorasa, Galen, podzielił pieczęć Thoradina na pięć części i rozdzielił je pośród obrońców Stromgarde. Odzyskaj te kawałki i zanieś do Tor\'gana, trollowego szamana; potrafi połączyć je w całość.",
    ["O"] = "Odbierz obrońcom Stromgarde 5 Sigil Fragments i zanieś je do Tor\'gana z Hammerfallu.",
    ["T"] = "Rozbita pieczęć",
  },
  [641] = {
    ["D"] = "Proces rekonstrukcji przebiegł bez błędów. Pieczęć może zostać użyta do otwarcia grobowca Trollbane\'a. Zanieś ją Zengu; bez wątpienia ma dla ciebie kolejne zadanie do wykonania.",
    ["O"] = "Zanieś odnowioną Sigil of Thoradin do Zengu z Hammerfallu.",
    ["T"] = "Pieczęć Thoradina",
  },
  [642] = {
    ["D"] = "Jestem Myzrael. Jestem księżniczką ziemi, zaś olbrzymy, które mnie schwytały, uwięziły mnie głęboko pod Arathi Highlands. Te odłamki kryształów są moim jedynym sposobem kontaktu z powierzchnią.$B$BProszę, pomóż mi. Sojusznicy olbrzymów, Drywhisker Kobolds, mają podobny kryształ w swojej Drywhisker Gorge, na wschód stąd. By zasilić wiązkę, musisz zabrać im Motes of Myzrael i przyłożyć je do niej.$B$BBłagam cię, $N, pomóż mi!",
    ["O"] = "Zbierz 12 Motes of Myzrael i zanieś je do Iridescent Shards w Drywhisker Gorge.",
    ["T"] = "Uwięziona księżniczka",
  },
  [643] = {
    ["D"] = "Choć trudno powiedzieć, żeby ludzie kontrolowali Stromgarde, nie wspominając o reszcie Arathi Highlands, ich książę rozsyła po okolicy resztki swej kawalerii. Nie potrafię pojąć, dlaczego to czyni, któż jednak zrozumie ludzki sposób myślenia?$B$BPomijając przyczyny, ważniejsze, że dał jedną z pieczęci dowódcy tej kawalerii, Porucznikowi Valorcallowi. Znajdź go i przynieś mi ją.",
    ["O"] = "Odzyskaj Sigil of Arathor i wróć z nią do Zengu, do Hammerfallu.",
    ["T"] = "Pieczęć Arathor",
  },
  [644] = {
    ["D"] = "Ostatnią z pieczęci niezbędnych do otwarcia grobowca Thorasa Trollbane\'a nosi przy sobie jego syn. Przebywa on w głębi Stromgarde, w kaplicy na obszarze kontrolowanym przez bojowników. Książę Galen ma silną ochronę, sam też nie należy do ułomków, toteż to zadanie może okazać się najtrudniejsze.",
    ["O"] = "Zabij Księcia Galena Trollbane\'a i przynieś Sigil of Trollbane do Zengu z Hammerfallu.",
    ["T"] = "Pieczęć Trollbane\'a",
  },
  [645] = {
    ["D"] = "A cóż to? Zebrane razem cztery pieczęcie połączyły się w jedność. Nie ma wątpliwości, że ta pieczęć będzie w stanie przełamać zabezpieczenia umieszczone na grobowcu Trollbane\'a.$B$BSzczątki Trollbane\'a pochowano w Sanktuarium na tyłach kaplicy w Stromgarde. Odzyskaj Trol\'kalar.",
    ["O"] = "Zabierz Trol\'kalar z grobowca Trollbane\'a w Stromgarde.",
    ["T"] = "Trol\'kalar",
  },
  [646] = {
    ["D"] = "Światło z wolna przygasa; uwięziony w kamiennej pochwie miecz Trol\'kalar jest wolny.",
    ["O"] = "Zanieś Trol\'kalar do Zengu, do Hammerfallu.",
    ["T"] = "Trol\'kalar",
  },
  [647] = {
    ["D"] = "Popiłem sobie wczoraj wieczór księżycówki! Longbraid urwałby mi głowę, gdyby wiedział, że odpłynąłem w trakcie warty.$B$BStrasznie mnie łupie pod czaszką. Jakby cała brygada czołgów parowych jeździła mi po głowie.$B$BRany, patrz która godzina! Obiecałem piwoszowi Bilgerowi z Południowego Wybrzeża, że spłacę dług, który mam u niego, przesyłając mu nieco księżycówki.$B$BJednak zostało mi na to tylko 15 minut! Zanieś mu tę partię, dobrze? I pośpiesz się!",
    ["O"] = "Zabierz MacKreel\'s Moonshine do piwosza Bilgera z Southshore.",
    ["T"] = "Księżycówka MacKreela",
  },
  [648] = {
    ["D"] = "Z robota ponownie dobywa się trzeszczący głos gnoma:$B$B\"Należy przenieść OOX-17-TN w bezpieczne otwarte miejsce, gdzie mógłby rozpocząć długą procedurę startową. Ma wbudowane maskowanie, ale potrzebuję czasu, by zdalnie doprowadzić je do ponownego użytku. Chciałbym, byś $geskortował:eskortowała; robota z jego obecnej lokacji w okolice – powiedzmy - Portu Steamwheedle! To powinno być idealne miejsce, położone dość daleko, bym zdążył poskładać wszystko do kupy!”$B$B\"Odprowadź go bezpieczne do portu i wpadnij pogadać do Booty Bay! Oglethorpe Obnoticus - bez odbioru!\"",
    ["O"] = "Odprowadź OOX-17-TN do Portu Steamwheedle, potem zgłoś się do Oglethorpe\'a Obnoticusa w Booty Bay.",
    ["T"] = "Uratuj OOX-17-TN",
  },
  [649] = {
    ["D"] = "Pragnę zlecić ci odzyskanie pewnej rzeczy; jeśli jesteś takim miłośnikiem dobrego jabłecznika jak ja, zadanie na pewno ci się spodoba. Jabłecznika!$B$BTo alkohol, ty $ggłupi:głupia;!$B$BW opuszczonej placówce Hordy znajduje się zapas Miodowego Jabłecznika z Hinterlands z czasów, kiedy siedzieli w interesie. Nigdzie już nie można dostać tak dobrego jabłecznika! Jeden z tępych pomocników Maltona zna szczegóły; udasz się więc tam i dostarczysz mi skrzynkę zapakowanego jabłecznika oraz dwie butelki do mojej prywatnej kolekcji! Porozmawiaj z Maltonem, wprowadzi cię w szczegóły.",
    ["O"] = "Porozmawiaj z Maltonem Droffersem w Orgrimmarze.",
    ["T"] = "Odzyskanie jabłecznika",
  },
  [650] = {
    ["D"] = "Elf, z którym musisz pogadać, to Gilveradin Sunchaser. Potrafi rozpoznać każde wino, rocznik i tak dalej po samym zapachu!$B$BPotrafi zapakować jabłecznik, którego potrzebujemy, więc musisz z nim pogadać. Potrzebujemy sześciu butelek na paczkę, dwóch dla taty, i jeszcze tylu, ile on będzie chciał... a wierz mi, trochę tego będzie. Wróć tu, gdy zapakujesz jabłecznik i zdobędziesz dwie butelki ekstra dla taty!$B$BObóz Gilveradina leży w Hinterlands, w pobliżu leśniczówki wysokich elfów. A to nie są dobre wysokie elfy. Wierz mi.",
    ["O"] = "Porozmawiaj z Gilveradinem Sunchaserem; jego obóz znajduje się w Hinterlands.",
    ["T"] = "Odzyskanie jabłecznika",
  },
  [651] = {
    ["D"] = "Po Arathi rozsiano cztery Kamienie Więzów. To one trzymają mnie zamkniętą pod powierzchnią ziemi.$B$BBy je otworzyć, musisz zrobić to z najsilniejszym z nich: Stone of Inner Binding. W tym celu musisz zebrać klucze z pozostałych trzech.$B$BKamieni pilnują strażnicy, jeśli jednak jesteś sprytny, lub masz szczęście, możesz znaleźć sposób, by ich przepędzić.",
    ["O"] = "Zabierz Burning Key, Cresting Key i Thundering Key z kamieni West Binding, East Binding i Outer Binding.$B$BZanieś je do kamienia Inner Binding.",
    ["T"] = "Kamienie Więzów",
  },
  [652] = {
    ["D"] = "Otwarcie Kamieni Więzów znacznie osłabiło me więzienie, jednak wciąż trzyma mnie tu jego zamek. Jest nim Keystone, który widzisz pośród kamieni tego kręgu. Zaś klucz do niego jest w posiadaniu jednego z tych, którzy mnie uwięzili - kamiennego strażnika Fozruka.$B$BKamienni strażnicy nazwali ów klucz Rod of Order. Musisz zdobyć go od Fozruka i użyć do otwarcia Keystone.$B$BUczyniłeś tak wiele, by mi pomóc. Jeszcze tylko troszkę... a moja wdzięczność wstrząśnie najgłębszymi filarami ziemi!",
    ["O"] = "Znajdź i zabij Fozruka (61,48). Przynieś Rod of Order do Rygla na Arathi Highlands.",
    ["T"] = "Złamanie Rygla",
  },
  [653] = {
    ["D"] = "<Myzrael mówi.>$B$BWolna! JESTEM WOLNA! Wolna, by zebrać siły, ukryte przed mymi oprawcami! Gdyby bowiem teraz stanęli przeciwko mnie, z pewnością zostałabym obezwładniona i ponownie uwięziona.$B$BW swoim czasie jednak zmierzę się z olbrzymami, a wówczas pożałują opieki, jaką mi zapewnili!$B$BJesteś szlachetnym sojusznikiem, $N. Wkrótce będę ponownie potrzebowała twojej pomocy. Gdy będę gotowa, przyzwiesz mnie na powierzchnię. $B$BPorozmawiaj z Gerrigiem Bonegripem. Przebywa w Ironforge, w sklepie w Forlorn Cavern. On wie, jak mnie zawezwać.",
    ["O"] = "Porozmawiaj z Gerrigiem Bonegripem w Forlorn Cavern, w Ironforge.",
    ["T"] = "Sprzymierzeńcy Myzrael",
  },
  [654] = {
    ["D"] = "Uruchomienie źródła energii sprawia, że maszyna zaczyna świecić i wibrować. Wygląda na to, że działa zgodnie z przeznaczeniem.$B$BWedług słów Chief Engineer Bilgewhizzle\'a masz dwie godziny na pozyskanie niezbędnych danych z pustyni Tanaris. Jeżeli nie uda ci się zmieścić w czasie, wszystkie informacje przepadną i będziesz musiał kupić od niego kolejny zasilacz.$B$BWróć do niego, gdy wykonasz już zadanie.",
    ["O"] = "Zdobądź odpowiednie próbki z 8 bazyliszków, 8 hien i 8 skorpionów. Przynieś zestaw testujący do Chief Engineer Bilgewhizzle\'a z Gadgetzanu nim wyczerpie się źródło energii.",
    ["T"] = "Próbki z Tanaris",
  },
  [655] = {
    ["D"] = "Wydaje mi się, jakby to było wczoraj... Tyle lat pozbawiony nadziei, drewnem i stalą związany z tym okropnym miejscem. Aż w końcu, w końcu! Pojawił się Wódz. Doomhammer w swej czarnej zbroi, trzymając wysoko swój młot.$B$BTo... zbyt okropne... Żeby cios tchórza powalił naszego największego bohatera. Od tyłu zaszarżował na swym rumaku, a potem jego lanca przeszyła bohatera na wylot... Upadłem na kolana. Jakaż nadzieja była wówczas? Jakaż nadzieja jest teraz...",
    ["O"] = "Porozmawiaj z Tor\'ganem w Hammerfallu.",
    ["T"] = "Hammerfall",
  },
  [656] = {
    ["D"] = "Musisz pokonać Myzrael, nim wzrośnie w siłę. Jeśli tego nie zrobisz, zebrawszy dość mocy rzuci wyzwanie tym, którzy ją schwytali! Istnieją tacy, co myślą, że mogą ją kontrolować, lecz jeśli to jest możliwe, to dlaczego olbrzymy uwięziły ją na samym początku??$B$BPokrętna logika, nie?$B$BBy ją zwyciężyć, przyzwij ją przy Shards of Myzrael, gdzie pierwszy raz rozmawialiście. Pokonaj ją i zabierz jej Eldritch Shackles, potem skuj nimi Shards of Myzrael.$B$BUczyń to, a ponownie znajdzie się w pułapce.",
    ["O"] = "Udaj się do Shards of Myzrael, przyzwij ją i pokonaj.$B$BZabierz jej Eldritch Shackles i przykuj je do Shards of Myzrael.",
    ["T"] = "Przyzwanie księżniczki",
  },
  [657] = {
    ["D"] = "<Quae szpera w teczce.>$B$BTo JEST interesujące. Wygląda na to, że aptekarz Jorell prowadzi tu, w Go\'Shek, jakieś zabójcze eksperymenty. Nie wiem co to ma wspólnego z Hillsbrad, ale Phin nie chciałby, żebyśmy pozwolili, aby nadal trwało.$B$BPodczas twej nieobecności miałyśmy małe spotkanie z orkami i nie czuję się na tyle dobrze, aby pomóc Kinelory. Jeśli się na to piszesz - będzie potrzebowała pomocy, gdy uda się na farmę, aby ukraść jakiekolwiek wyniki, których Jorell jeszcze nie wysłał do Tarren Mill.",
    ["O"] = "Porozmawiaj z Kinelory.",
    ["T"] = "Oznaki nowej plagi?",
  },
  [658] = {
    ["D"] = "Więc Phin wysłał cię, byś $gsprawdził:sprawdziła; co się z nami dzieje? Nie jestem zaskoczona – zbyt dużo się martwi.$B$BOd wielu dni obserwujemy farmę i Kin mówi, że niedawno widziała kurierkę wychodzącą z małego domu na południu.$B$BOna sporo mówi, ale w niebezpiecznym terenie zawsze polegam na jej zmysłach.$B$BNie jesteś przypadkiem $guzdolnionym tropicielem:uzdolnioną tropicielką;? Sądzimy, że kurierka niesie listy do Tarren Mill. Gdybyśmy zdobyli te dokumenty, może rzuciłoby to trochę światła na zdarzenia w Hillsbrad.",
    ["O"] = "Odnajdź Forsaken Courier i przynieś jej Sealed Folder do Quae, niepodal Farmy Go\'Shek.",
    ["T"] = "Oznaki nowej plagi?",
  },
  [659] = {
    ["D"] = "Chwała ci i dobrze cię widzieć, $N. Dowodzę grupą poszukiwaczy przygód, badających dziwne zdarzenia na tym obszarze.$B$BMój kuzyn z Hillsbrad zabił ostatnio swego psa, Stanleya, gdyż zwierzę w tajemniczy sposób urosło do niezwykłych rozmiarów i z furią atakowało każdego, kto zbytnio się doń zbliżył.$B$BWierzę, że są w to zamieszani nieumarli i szukam na to dowodu.$B$BDwie moje towarzyszki, Quae i Kinelory, ruszyły na Farmę Go\'Shek w Arathi Highlands i od dłuższego czasu nie dają znaku życia. Znajdziesz je dla mnie? Coraz bardziej się o nie martwię.",
    ["O"] = "Znajdź Quae i Kinelory nieopodal Farmy Go\'Shek w Arathi Highlands.",
    ["T"] = "Oznaki nowej plagi?",
  },
  [660] = {
    ["D"] = "Dobrze, $N. Jestem gotowa.$B$BZaczynamy?",
    ["O"] = "Chroń Kinelory, aż powróci ona do Quae.",
    ["T"] = "Oznaki nowej plagi?",
  },
  [661] = {
    ["D"] = "Widywałam Kinelory w znacznie gorszym stanie po nocy w tawernie, niż teraz. $gOdwaliłeś:Odwaliłaś; kawał dobrej roboty chroniąc ją.$B$BRzeczy, które przyniosła z farmy, powinny przynajmniej podsunąć Phinowi jakiś pomysł odnośnie tego, co dzieje się tutaj, w Arathi. Zamierzamy zostać tutaj nieco dłużej, aby upewnić się, że nie będzie żadnego odwetu za twój atak. Udasz się do Southshore i zobaczysz się z Phinem?",
    ["O"] = "Znajdź Phina Odelica w Southshore.",
    ["T"] = "Oznaki nowej plagi?",
  },
  [662] = {
    ["D"] = "O\'Breen wpłynął statkami do zatoczki. Byliśmy pewni, że to tu można znaleźć skarb. \"Zwiastun\" zacumował bezpiecznie, lecz gdy nadpłynęły \"Maiden\'s Folly\" i \"Spirit of Silverpine\" poziom wód zaczął opadać. Najdziwniejsza rzecz, jaką dane mi było widzieć!$B$BTe dwa statki uderzyły w coś... coś w rodzaju świątyni w rafie. Zatonęły tak szybko. To prawdziwa tragedia.$B$BNim odpłyniemy musimy odzyskać ich Mapy oraz Dzienniki. Nie możemy zostawić takich informacji dla wścibskich oczu.",
    ["O"] = "First Mate Nilzlix chce, abyś odzyskał Mapy i Dzienniki z \"Maiden\'s Folly\" i \"Spirit of Silverpine\".",
    ["T"] = "Mienie na dnie morza",
  },
  [663] = {
    ["D"] = "Lolo widzi maleńkiego krwawego elfa! Lolo jest zawsze uważny!$B$BWitaj w Faldir\'s Cove.. Kapitan O\'Breen powiedział, że zostaniemy tu tylko przez parę godzin. Tylko tyle, żeby zwinąć skarb i wracać do Booty Bay.$B$BAle Lolo sądzi, że będziemy tu dużo dłużej. Straciliśmy pozostałe dwa statki. Biedny \"Spirit of Silverpine\" i \"Maiden\'s Folly\". Na dnie morza spoczywają teraz!$B$BJeżeli masz zamiar się trochę tu poszwendać, Lolo radzi, abyś porozmawiał z Kapitanem O\'Breenem.",
    ["O"] = "Porozmawiaj z Kapitanem O\'Breenem w Faldir\'s Cove.",
    ["T"] = "Ziemia na horyzoncie!",
  },
  [664] = {
    ["D"] = "Argh, jakież cholerne jest to życie. Powinienem leżeć w wodnym grobie, a nie siedzieć se tutaj i dychać świeżym powietrzem.$B$BZałoga tak bardzo chciała ocalić mój śliczny \"Maiden\'s Folly\". Błogosławieństwo dla chłopców, błogosławieństwo ich sercom.$B$BO\'Breen bezpiecznie dotarł do brzegu, ale myśmy nie mieli tyle szczęścia. Wody dosłownie nas otoczyły, przysięgam!$B$BW jednej chwili płynęliśmy, a w następnej już byliśmy pod wodą. I te bestie! Zabiły wszystkich ocalałych. Cholerne nagi. Straciłem przytomność i trafiłem tutaj, bezpieczny.$B$BChcę żeby zdechły.",
    ["O"] = "Kapitan Steelgut z Faldir\'s Cove chce, abyś zabił 10 Daggerspine Raiders i 3 Daggerspine Sorceresses.",
    ["T"] = "Zatopione smutki",
  },
  [665] = {
    ["D"] = "No, teraz gdy jesteśmy Blackwater Raiders pełną gębą, naszym obowiązkiem jest pomóc panu O\'Breenowi zlokalizować zagubiony elfi skarb. $B$BNiemalże niemożliwe jest odnalezienie tych klejnotów w mroku morza bez odpowiedniej pomocy. Doktor skonstruował gogle, które nam pomogą. Należy naładować je energią z magicznego kamienia w jaskini we wzgórzu.$B$BAle jaskinia jest przeklęta! Gdy się zbliżymy, wpadniemy w zasadzkę. Chroń mnie, podczas gdy ja będę ładował gogle energią z magicznego kamienia.",
    ["O"] = "Eskortuj Profesora Phizzlethorpe\'a do jaskini i z powrotem.",
    ["T"] = "Zatopiony skarb",
  },
  [666] = {
    ["D"] = "Skarb spoczywał na dnie morza tak długo, że klejnoty przeobraziły się w grube kamienie. Ale moc zawarta w goglach pozwoli ci je z łatwością odnaleźć.$B$BTrochę gnomiej pomysłowości zawsze się przyda!$B$BA więc weź Gogle Szukania Klejnotów, $N, i zobacz czy będziesz w stanie zebrać choć część skarbu dla Kapitana O\'Breena.$B$BWiesz, zanurkowałbym sam, ale... umm... cóż... są sprawy naukowe wielkiej wagi, ktorymi muszę się zająć tu, na bezpiecznym suchym lądzie... eee... tak, właśnie.",
    ["O"] = "Doktor Draxlegauge z Faldir\'s Cove chce, abyś zebrał 10 Elven Gems i po skończeniu oddał Goggles of Gem Hunting.",
    ["T"] = "Zatopiony skarb",
  },
  [667] = {
    ["D"] = "Jest źle. Wygląda na to, że Daggerspines szykują atak. $B$BNagi są znane z bezwzględności podczas walki. Będą atakować tak długo, aż padnę trupem. $B$BNie przekładam swego życia ponad życie mej załogi, ale musisz mi pomóc się obronić. Bez mej wiedzy na temat mórz załoga nie będzie w stanie wrócić do Booty Bay.$B$BNagi nadejdą od morza. Potrzebuję cię tutaj, aby odeprzeć atak. Do dział! Odepchniemy je, skąd przyszły.$B$BJesteś gotów, $N?",
    ["O"] = "Chroń Shakesa O\'Breena podczas ataku.",
    ["T"] = "Śmierć z głębin",
  },
  [668] = {
    ["D"] = "Nie pozwólmy Kapitanowi O\'Breenowi czekać. Będzie chciał je natychmiast zobaczyć. Jakby nie patrzeć, po to tu jesteśmy!$B$BA po kilku tygodniach przebywania z tymi piratami, profesor i ja zrozumieliśmy, że ostatnią rzeczą korzystną dla naszego zdrowia byłoby przyłapanie z ich skarbem w rękach.$B$BTrzymaj, $N, zabierz je do O\'Breena.",
    ["O"] = "Zanieś Elven Gems do Kapitana O\'Breena.",
    ["T"] = "Zatopiony skarb",
  },
  [669] = {
    ["D"] = "Dowódca Floty Seahorn będzie chciał natychmiast usłyszeć o naszym znalezisku.$B$BAle jak widzisz, niewielkie są szanse, że szybko się stąd wydostaniemy. Nie dość, że przypływ jest tak niski, to jeszcze te cholerne bestie, które obudziliśmy, ciągle nas obserwują.$B$BWyświadczysz wielką przysługę Blackwater Raiders, jeżeli dostarczysz wiadomość Dowódcy Floty Seahornowi z Booty Bay. Powiedz mu, że znaleźliśmy skarb i próbujemy zdobyć coś więcej. Weź ten klejnot jako dowód.",
    ["O"] = "Pokaż Sample Elven Gem Dowódcy Floty Seahornowi w Booty Bay.",
    ["T"] = "Zatopiony skarb",
  },
  [670] = {
    ["D"] = "Powiedz, $N, jesteś typem podróżnika? Moja flota utknęła w Booty Bay do czasu, gdy będziemy mogli uzupełnić zapasy.$B$BWażą się tutaj pewne sprawy i potrzebuję przesłać ściśle tajne informacje do Shakesa O\'Breena, który utknął na wybrzeżu Arathi.$B$BMogę ufać, że zaniesiesz mu tą wiadomość nie zwracając na siebie uwagi?",
    ["O"] = "Zanieś Seahorn\'s Letter do Shakesa O\'Breena w Arathi Highlands.",
    ["T"] = "Zatopiony skarb",
  },
  [671] = {
    ["D"] = "Czułem coś dziwnego w powietrzu... coś jakby gotowała mi się krew. Miałem pewne podejrzenia. Wyruszyłem żeby znaleźć źródło moich niepokojów i odkryłem na zachodzie, w Northfold Manor, ślady po przyzywaniu demonów. Gdy się zbliżyłem, moja krew zaczęła wrzeć, a gniew wzrósł we mnie.$B$BNa ziemi znalazłem amulet krwawego kamienia, używany przy wzywaniu demonów. Jednak jedyny jaki znalazłem był wyczerpany. Potrzebuję kolejnego żeby go przebadać, ale nie śmiem tam wrócić. Czy możesz poszukać jakiegoś za mnie?",
    ["O"] = "Zdobądź 10 Bloodstone Amulets dla Tor\'gana z Hammerfall.",
    ["T"] = "Cuchnąca Magia",
  },
  [672] = {
    ["D"] = "Próbowaliśmy go zadomowić, rozweselić go, opowiadając mu historie o naszym potężnym mieście Orgrimmar w Kalimdorze, ale nic nie mogło go poruszyć.$B$BOpowieści o naszym młodym Wodzu, Thrallu, który nosi zbroję i młot Orgrima... ale, może... Może! Demonstracja naszej nowo odkrytej szamanistycznej magii da mu nową nadzieję. Warto tego spróbować!$B$BMały przedmiot, który możemy dla niego zrobić, tak... Przynieś mi kilka sztuk oczu raptorów i zobaczę co mogę zrobić.",
    ["O"] = "Zdobądź 10 Highland Raptor Eyes z Highland Striders i Highland Thrashers dla Tor\'gana w Hammerfall.",
    ["T"] = "Podnoszenie Duchów",
  },
  [673] = {
    ["D"] = "Nie mam wątpliwości, że potężny warlock zasiada między murami Stromgarde. Od czasu do czasu, używając tajemnego magicznego reliktu owy Warlock wzywał ogromne ilości potwornych demonów. Musimy pozbawić go z jego źródła energii.$B$BZnajdź tego warlocka i go zabij. Przynieś mi jakikolwiek magiczny obiekt, który przy nim znajdziesz, a ja postaram się go zniszczyć i dopilnuję, aby jego moc nie plugawiła tych ziem.",
    ["O"] = "Odzyskaj Bloodstone Orb Mareza Cowla i przynieś go do Tor\'gan w Hammerfall.",
    ["T"] = "Wstrętna magia",
  },
  [674] = {
    ["D"] = "Weź ten amulet do Gor\'mula i sprawdź czy może obudzić ogień wojownika, który kiedyś płonął w jego żyłach.",
    ["O"] = "Daj Raptor Talon Amulet Gor\'mulowi.",
    ["T"] = "Raising Spirits",
  },
  [675] = {
    ["D"] = "<Gor\'mul rzuca amulet na ziemie.>$B$BTor\'gan Cię przysłał, nieprawdaż? Pah! Dlaczego on czuje jakieś miłosierdzie wobec mnie, nie potrafię tego zrozumieć. Miłosierdzie się mnie wyparło, kiedy nie pozwolono mi umrzeć u boku mojego Wodza w bitwie. Okrutny los zadał mi cios...",
    ["O"] = "Porozmawiaj z Tor\'ganem.",
    ["T"] = "Powstanie Duchów",
  },
  [676] = {
    ["D"] = "Słabeusze... wszyscy. Ty, $C, na co się gapisz? Myślisz, że jest w tobie coś niezwykłego, huh? Może to udowodnisz?$B$BPlacówka Hammerfall w Arathi została zaatakowana. Jeśli im nie pomożemy, ich upadek będzie nieunikniony.$B$BAle przed tym nim wyruszysz, musisz sprawdzić swoje umiejętności tutaj. Na północny wschód od Stromgarde, w Arathi zamieszkały ogry z plemienia Skalnej Pięści. Kiedy poradzisz sobie z ogrami i egzekutorami, zgłoś to do Drum Fel w Hammerfall.",
    ["O"] = "Zabij 8 Boulderfist Ogres i 10 Boulderfist Enforcers, a następnie znajdź Drum Fel w Hammerfall Outpost w Arathi Highlands.",
    ["T"] = "Młot może upaść",
  },
  [677] = {
    ["D"] = "Trole Witherbark i ogry Boulderfist z Arathi współpracują, aby nas przegonić z tych ziem, ale nie będą oni decydować o naszym losie. Wymordujemy ich i pokażemy im, że my też mamy tu swój dom.$B$BTrole zwróciły się przeciwko nam; a ogry chętnie by nas ugotowały i zrobiły z nas posłania - nigdy do tego nie dojdzie.$B$BRozpoczniemy nasz atak na trole Witherbark na północ stąd. Wyrżnij ich w pień i wróć dopiero jak ich wioska będzie tonęła we krwi.",
    ["O"] = "Zgładź 10 Witherbark Axe Throwers, 10 Headhunterów i 8 Witch Doctors, a potem wróć do Drum Fel w placówce Hammerfall.",
    ["T"] = "Wezwanie do broni",
  },
  [678] = {
    ["D"] = "Drzemie w tobie siła, widać to, $N. Teraz sprawdźmy jak poradzisz sobie przeciwko prawdziwym wrogom.$B$BKlan Boulderfist ma pieczarę na południowy zachód stąd w kierunku krasnoludzkiego mostu i jeśli się nie mylę, Maulers i Magi mogą stanowić dla Ciebie większe wyzwanie tak jak robili to nam.$B$BZabij ich tyle, ile tylko zdołasz i przyjdź do mnie kiedy Ci się uda, lub przybądź duchem, gdy zawiedziesz. Tak czy siak, pochwalam twą wytrwałość w walce.",
    ["O"] = "Zabij 10 Boulderfist Brutes i 4 Boulderfist Magi, i wróć do Drum Fel w Hammerfall Outpost.",
    ["T"] = "Wezwanie do broni",
  },
  [679] = {
    ["D"] = "Głowa bestii jest gotowa do ścięcia... niech moc będzie z tobą, $N. Udowodniłeś, że jesteś w stanie nam pomóc z finałowym ciosem. Liderzy tych ataków mają swoje legowisko w ruinach Stromgarde, symbolu ludzkiej słabości.$B$BZnajdź i zabij tych lordów Boulderfist i ich pachołkowatych szamanów, którzy próbowali wypędzić nas z tych ziem.",
    ["O"] = "Zabij 7 Boulderfist Shaman oraz 3 Boulderfist Lords i wróć do Drum Fel w wysuniętej placówce Hammerfall",
    ["T"] = "Wezwanie do broni",
  },
  [680] = {
    ["D"] = "Dobrze służyłeś mojemu mężowi, $C, ale on nie wiedział, dlaczego Hammerfall jest atakowane.$B$BOr\'Kalar, pionek Mug\'thola w Stromgarde, nienawidzi mojego męża i nic niczego nie pragnie bardziej, niż śmierci mojego męża za to, że ten pokonał go lata temu.$B$BPrzeczucie mówi mi, że Or\'Kalar przygotował pułapkę na mojego męża, więc ukryłam przed nim ślady obecności ogra.$B$BMój mąż ruszy bezmyślnie, jeśli dowie się o miejscu pobytu ogra i chciałabym prosić cię o pomoc w zabiciu tej kreatury.",
    ["O"] = "Zabij Or\'Kalara i przynieś jego głowę do Korina Fela w Hammerfall outpost.",
    ["T"] = "Prawdziwe zagrożenie",
  },
  [681] = {
    ["D"] = "Prowadzimy wojnę o Stromgarde i przegrywamy. Ogry, Syndicate i my podzieliliśmy nasze wielkie niegdyś miasto. Teraz każdy z nas walczy z innym w krwawym pacie.$B$BAle nasze siły maleją, a siły naszych przeciwników rosną.$B$BPotrzebujemy pomocy z Southshore, jednak ciężko otrzymać zaopatrzenie, kiedy Syndicate kontroluje terytorium między nami.$B$BUdaj się do bazy Syndicate w Northfold Manor i zabij ich. Wtedy, prawdopodobnie, ataki na nasze pociągi z zaopatrzeniem osłabną i więcej z nich do nas dotrze.",
    ["O"] = "Zabij 10 Syndicate Highwaymen i 6 Syndicate Mercenaries.$B$BWróć do Captain Nials w Refuge Pointe.",
    ["T"] = "Northfold Manor",
  },
  [682] = {
    ["D"] = "Syndykat ze Stromgarde prowadzi zaciętą walkę z naszym kontyngentem oddziałów tam stacjonujących. W rozporządzeniu mającym na celu zachęcenie motłochu do walki z naszymi zdyscyplinowanymi oddziałami, liderzy Syndykatu wyznaczyli nagrodę w złocie za każdą odznakę zrabowaną z ciał naszych żołnierzy.$B$BNie możemy pozwolić, żeby jacyś szabrownicy okradali ciała naszych poległych braci! Te odznaczenia powinny wrócić do rodzin poległych!$B$BWejdź na obszar Stormgrade kontrolowany przez Syndykat i odzyskaj je!",
    ["O"] = "Zbierz 7 Stromgarde Badges dla Captaina Nialsa z Refuge Pointe.",
    ["T"] = "Odznaki Stromgarde",
  },
  [683] = {
    ["D"] = "$N, mam dla ciebie małe zadanko.$B$BZanieś tą notatkę, którą sporządziłam naszemu wielkiemu władcy Ironforge, królowi Magniemu. Takie zadanie to nic wielkiego dla kogoś takiego jak ty. Kogoś, kto zrobił tyle dobrego dla Sojuszu.$B$BPójście przed oblicze króla w moim opłakanym stanie nie przysłuży się mojej sprawie. Z pewnością rozumiesz.",
    ["O"] = "Zanieś zapiski Sary Balloo do króla Magniego Bronzebearda w Ironforge.",
    ["T"] = "Prośba Sary Balloo",
  },
  [684] = {
    ["D"] = "Ogłaszam nagrodę za głowę Marez Cowl, doradcy wysokiego szczebla, oraz działacza Syndykatu. Ostatnio widziano ją w Stormgrade, na terenie kontrolowanym przez Syndykat.$B$BNagroda do odebrania u Captain Nials.$B$BBądźcie czujni: Marez jest przebiegła i wykwalifikowana w sztukach czarnoksięskich. Zaleca się szczególną ostrożność podczas próby pokonania jej.",
    ["O"] = "Przynieś głowę Marez do Captaina Nials w Refuge Pointe.",
    ["T"] = "Poszukiwana! Marez Cowl",
  },
  [685] = {
    ["D"] = "Stromgarde Militia wystawiła zlecenie na głowy Lorda Falconcrest i jego ochroniarza Otto. Falconcrest przewodzi działaniom Syndicate w Arathi Highlands i jego śmierć spowoduje spory rozłam w tych działaniach.$B$BJego ochroniarz Otto, mimo, iż nie jest strategicznym celem, jest naszym zawziętym przeciwnikiem i zabił dziesiątki naszych obrońców.$B$BPremie za nich można będzie odebrać u Captain Nials.",
    ["O"] = "Przynieś Otto\'s Head i Falconcrest\'s Head do Captain Nials w Refuge Pointe.",
    ["T"] = "Poszukiwani! Otto i Falconcrest",
  },
  [686] = {
    ["D"] = "Nie oczekuję, że dobre krasnoludy jak Pani Balloo zrozumieją dlaczego wojny muszą trwać dla dobra naszych ludzi. Strata jej męża, ale także strata każdego gnoma, który walczył w imię Sojuszu, ciąży na mojej duszy.$B$BNie mogę ściągnąć jej męża z zaświatów, ale mogę oddać mu hołd.$B$BZamierzam zlecić budowę memoriału poświęconego Sully Balloo, który zostanie zbudowany przez najlepszego kamieniarza Marblestena.$B$BSzepnij mu słówko, $C. $gPowinieneś:Powinnaś; dopilnować by moje rozkazy zostały wypełnione.",
    ["O"] = "Król Magni Bronzebeard chce, byś $gporozmawiał:porozmawiała; z najlepszym kamieniarzem Marblestenem.",
    ["T"] = "Hołd Króla",
  },
  [687] = {
    ["D"] = "Theldurin the Lost był niegdyś członkiem naszego stowarzyszenia, Twilight\'s Hammer. Jednak postradał zmysły i wzgardził naszymi naukami. A nim od nas uciekł, ukradł zwój Myzrael! Nie mogliśmy go schwytać, wieść jednak niesie, że ten bełkoczący szaleniec ukrywa się w Badlands.$B$BBy na powrót sprowadzić do nas Panią, musisz odnaleźć zwój. Zaś by to uczynić, musisz odnaleźć Theldurina.",
    ["O"] = "Odnajdź Theldurin the Lost.",
    ["T"] = "Theldurin Zagubiony",
  },
  [688] = {
    ["D"] = "<Myzrael mówi.>$B$BWolna! JESTEM WOLNA! Wolna, by zebrać siły, ukryte przed mymi oprawcami! Gdyby bowiem teraz stanęli przeciwko mnie, z pewnością zostałabym obezwładniona i ponownie uwięziona.$B$BW swoim czasie jednak zmierzę się z olbrzymami, a wówczas pożałują opieki, jaką mi zapewnili!$B$BJesteś szlachetnym sojusznikiem, $N. Wkrótce będę ponownie potrzebowała twojej pomocy. Gdy będę gotowa, przyzwiesz mnie na powierzchnię. $B$BPorozmawiaj z Zarukiem w Hammerfallu. On wie, jak mnie zawezwać.",
    ["O"] = "Porozmawiaj z Zarukiem w Hammerfall.",
    ["T"] = "Sprzymierzeńcy Myzrael",
  },
  [689] = {
    ["D"] = "Więc nasz dobry Król chce zbudować pomnik żołnierzowi zwanemu Sully Balloo? I mówisz, że zginął podczas tragedii w Thandol Span?$B$BCzy w Azeroth będzie kiedyś pokój? Niemniej jednak każde zadanie od króla jest sprawą najwyższej wagi. Aby zbudować prawdziwie epicki i trwały pomnik potrzebuje jeden z najlepszych kamieni. Jedź do Darrow Hill w Hillsbrad i zdobądź dla mnie trochę Alterac Granite.",
    ["O"] = "Grand Mason Marblesten of Ironforge żąda 5 części z Alterac Granite.",
    ["T"] = "A King\'s Tribute",
  },
  [690] = {
    ["D"] = "Witaj, $N. Wyglądasz na osobę lubiącą przygody, a ja mam właśnie dla kogoś takiego zadanie.$B$BArcymag Trelane, mój mistrz, odleciał do Stromgarde w Wyżynach Aratorskich nie tak dawno temu i poprosił mnie, abym pomogła mu odnaleźć pewnie przedmioty, które pozostawił.$B$BMiasto upadło się pod oblężeniem, a on zdołał obronić Wieżę Aratorską, jednak na próżno. Wysłałam już swoich wysłanników na wyżyny, ale poprosili mnie o przysłanie im pomocnika. Jesteś $gzainteresowany:zainteresowana;?",
    ["O"] = "Znajdź Skuerto w Refuge Pointe w Arathi Highlands.",
    ["T"] = "Prośba Malina",
  },
  [691] = {
    ["D"] = "Arcymag Malin wysłał tutaj Skuerto i mnie, byśmy zebrali dla niego materiały. Nie wiedziałem, w jaki sposób miałem zdobyć te materiały, ale teraz ty tu jesteś. Myślę, że to rozwiązuje mój problem.$B$BMuszę zdobyć: Witherbark Tusks, Witherbark Medicine Pouches i Shadow Hunter Knife.$B$BCzy możesz to dla mnie zdobyć? Witherbark żyją na południowym wschodzie Arathi.",
    ["O"] = "Znajdź 10 Witherbark Tusks, 4 Witherbark Medicine Pouches i Shadow Hunter Knife dla Apprentice Kryten w Refuge Pointe.",
    ["T"] = "Na wagę złota",
  },
  [692] = {
    ["D"] = "Zwój Myzrael... Zwój Myzrael?! Nie chcesz tego! Jego magia może wydobyć Myzrael na powierzchnię ziemi, a jeśli tak się stanie, będziemy mieć kłopoty!$B$BAlbo... jest już za późno. Może już się uwolniła. Może jedynie zbiera siły, nim użyje ich przeciwko nam. A jeśli tak, będziesz POTRZEBOWAŁ zwoju!$B$B...szkoda, że został zniszczony. Rozwścieczone żywiołaki ukradły go i podarły, a teraz walczą o jego fragmenty.$B$BLecz gdybyś dał radę je zebrać, może moglibyśmy go naprawić...",
    ["O"] = "Przynieś Torn Scroll Fragment, Crumpled Scroll Fragment i Singed Scroll Fragment do Theldurin the Lost.",
    ["T"] = "Zaginione fragmenty",
  },
  [693] = {
    ["D"] = "Hej, $N. Przepraszam że wcześniej tak krótko z tobą byłam... I nie, to nie jest żadna gra słów.$B$BOdkryłam gdzie jest pierwszy przedmiot Trelane: posiada go Kor\'gresh w Boulderfist Hall. Swoją drogą używał lodowych podmuchów, aby utrzymać swoich krewnych pod kontrolą, musi być blisko nauczenia się jak używać wszystkich swoich mocy.$B$BBoulderfist Hall jest na południe stąd i potem na wschód od Thandol Span. Znajdź tego ogra i przynieś z powrotem tę różdżkę.$B$BPodczas gdy ty będziesz się tym zajmował, ja się dowiem co powinniśmy zrobić ze Stromgarde.",
    ["O"] = "Znajdź Tralane\'s Wand of Invocation i przynieś ją do Skuerto w Refuge Pointe.",
    ["T"] = "Różdżki ponad pięści",
  },
  [694] = {
    ["D"] = "Wypoczęty?$B$BTo jest nasz następny krok: wszędzie wokół Wieży Arathor w Stormgarde znajdują się ogry. Musimy aktywować obronę wieży, jeśli chcesz mieć przeciwko nim szansę i dotrzeć do przedmiotów żywy. Aby to zrobić, potrzebujemy klejnoty, do których upodobanie znaleźli sobie szamani Boulderfist. Oni wzięli je z wieży, ale nie zostaną w ich posiadaniu na długo.$B$BZdobądź od jednego z nich klejnot i przynieś go do Krytena - on zna zaklęcie, które zaczaruje klejnoty tak, aby działały jak klucz.",
    ["O"] = "Znajdź Azure Agate i przynieś go do Apprentice Kryten w Refuge Pointe.",
    ["T"] = "Obrona Trelane\'a",
  },
  [695] = {
    ["D"] = "Tutaj jesteś, $N. Klejnot musi tylko zostać wciśnięty w jeden z piedestałów u podstawy wieży, aby aktywować obronę. Użyj tego, gdy będziesz gotowy, by wejść do wieży i znajdź pozostałe przedmioty Trelane\'s.$B$BPowodzenia. Będę czekał na twój powrót tutaj w obozie. Oh, i porozmawiaj z Skuerto zanim odejdziesz. Da ci resztę informacji, których będziesz potrzebował.",
    ["O"] = "Porozmawiaj z Skuerto.",
    ["T"] = "Zaklęcie Praktykanta",
  },
  [696] = {
    ["D"] = "Tutaj jest to czego szukasz: Trelane\'s phylactery, Trelane\'s Orb, Trelane\'s Ember Agate.$B$BWszystkie trzy powinny być w skrzyni wewnątrz wieży i nie powinieneś mieć problemu z jej otwarciem po swojemu; musisz tylko uważać na ogry.$B$BObroną wież nie zajmą się same; musisz mieć swoja broń w gotowości. Te ogry odkryją, że tam jesteś i ich okradasz, i nie zawahają się, by zadać ci ból.$B$BBądź ostrożny i powodzenia.",
    ["O"] = "Znajdź Trelane\'s Phylactery, Trelane\'s Orb, i Trelane\'s Ember Agate, następnie odnieś je do Skuerto przy Refuge Pointe.",
    ["T"] = "Atak na Wieżę",
  },
  [697] = {
    ["D"] = "Zanieś ten list do Stormwind i daj Malinowi znać, że Kryten i ja będziemy wkrótce w domu. Dobrze Cię nagrodzi za to, że nam tu pomogłeś, $N, nie mam co do tego wątpliwości.$B$BBezpiecznej podróży.",
    ["O"] = "Zanieś zapieczętowany list do Arcymaga Malina znajdującego się w dzielnicy Mage Quarter w Stormwind.",
    ["T"] = "Prośba Malina",
  },
  [698] = {
    ["D"] = "Pracuję nad przywróceniem dostaw dla naszej placówki w pobliżu plaży na wschodzie. Tok\'kar robi co może, ale między zmianami na straży i gotowaniem dla żołnierzy nie ma wiele wolnego czasu.$B$BZnajduje przyjemność w gotowaniu Sawtooth Meat kiedy tylko może, tylko że ja nie magę mu teraz zagwarantować kolejnej dostawy produktów. Czy mógłbyś nam pomóc?$B$BMłode Sawtooths nie są tak smaczne jak te starsze, więc trzymaj się z dala od nich; daj im rok-dwa, aby nabrały odpowiednio dużych rozmiarów.",
    ["O"] = "Przynieś 8 Unprepared Sawtooth Flanks do Tok\'Kar w Swamp of Sorrows.",
    ["T"] = "Brak Nadwyżki",
  },
  [699] = {
    ["D"] = "Z zagrożeniem ze strony murloków wzdłuż całej zatoki, stacjonujemy tutaj by bronić - lub ostrzec, jeśli wrogie siły będą zbyt wielkie - Stonard przed wszelkimi nadchodzącymi zagrożeniami. Nie mamy zbyt wiele czasu na relaks i przydałaby nam się twoja pomoc.$B$BWłaściwie przygotowane Sawtooth Snappers\' Claws idealnie nadają się na broń. Przynieś mi ich trochę, a ja nagrodzę cię jedną z naszych broni w podzięce za Twoje trudy i dobre towarzystwo.",
    ["O"] = "Przynieś 6 Sawtooth Snapper Claws do Tok\'Kar w Swamp z Sorrows.",
    ["T"] = "Brak Nadwyżki",
  },
  [700] = {
    ["D"] = "Ach, taki wspaniały kamień pochodzi z Lordaeronu. Cóż za szkoda, że z tą ziemią się stało, jak się stało.$B$BAle memoriał wyszedł całkiem nieźle! Zakładam, że król będzie z niego zadowolony.$B$BA teraz jeśli pozwolisz, proszę daj znać Jego Wysokości, że ukończyłem pomnik, tak jak kazał.",
    ["O"] = "Zdaj raport do króla Magniego Bronzebearda.",
    ["T"] = "Królewski Hołd",
  },
  [701] = {
    ["D"] = "Z paroma dodatkowymi rzeczami, będę zdolny do stworzenia przedmiotu, który przepełni Gor\'mula przebiegłością raptora! Z mocą bestii płynącą w nim, ork pozna nasz nowy potencjał i ponownie odkryje wojownika, który drzemie wewnątrz niego!$B$BBędę potrzebował serc raptorów by dopracować oręż i zaklęcie.",
    ["O"] = "Zdobądź 12 Raptor Hearts z ciał wyżynowych tropicieli dla Tor\'gana.",
    ["T"] = "Podstępność raptorów",
  },
  [702] = {
    ["D"] = "Weź to i użyj, żeby dać Gor\'mulowi esencję raptora. To z pewnością orzeźwi jego ducha i da mu nowy powód do życia. Kiedy wróci do normalności, wyjaśnimy mu nasz aktualny stan i zyskamy wsparcie wielkiego wojownika w naszych nieustannych bitwach.",
    ["O"] = "Dostarcz Tor\'gan\'s Orb do Gor\'mula.",
    ["T"] = "Chytrość Raptora",
  },
  [703] = {
    ["D"] = "Oh tak, moje Skrzydełka Myszołów z grilla są najlepsze! Sos jest bogaty, a mięso jest ostre. Zapach będzie się niósł daleko stąd!$B$BMam wszytko co potrzebuję do gotowania. Wszystko... poza samymi The Buzzard Wings!$B$BJeśli chcesz parę, przynieś mi Buzzard Wings. Przynieś mi wystarczająco, a ja podzielę się z tobą przepisem!",
    ["O"] = "Przynieś 4 Buzzard Wings do Rigglefuzz.",
    ["T"] = "Grilowane Skrzydełka Buzzard",
  },
  [704] = {
    ["D"] = "Ostatni raport jaki odebrałem od Agmonda był niepokojący, co więcej teraz już nie żyje! Wspominał, że jego górnicy odkryli \"antyczne urny\" po stronie wykopalisk w Uldaman. Boje się, że te urny pobudziły troggsów, tak jak ten bożek, którego tu znalazłem.$B$BPotrzebuję ciebie, abyś mi przyniósł te urny, są nam potrzebne do badań. Idź po te urny i przynieś mi je.",
    ["O"] = "Przynieś 4 Carved Stone Urns do Prospector Ironband w Loch Modan.",
    ["T"] = "Los Agmonda",
  },
  [705] = {
    ["D"] = "Badlands to przykre miejsce, wypełnione złośliwymi drapieżnikami i zuchwałymi padlinożercami. Straszne, w szczególności dla niskiego małego goblina. Aby przetrwać, muszę być podstępny!$B$BZnam recepturę na bomby błyskowe. Używam ich, aby straszyć dzikie stworzenia. Niestety kończy mi się jeden ze składników: proszek z niebieskich pereł. Przynieś mi go trochę, a sprawię, że nie pożałujesz swojego wysiłku.$B$BHeh, mam też nadzieję, że masz dobre buty. Blue Pearls, które potrzebuję znajdują się w małżach na Vile Reef.$B$BTak, Vile Reef w Stranglethorn!",
    ["O"] = "Przynieś 9 Blue Pearls do Rigglefuzza w Badlands.",
    ["T"] = "Perłowe nurkowanie.",
  },
  [706] = {
    ["D"] = "Jako uczeń Feranor\'a Steeltoe\'a, nauczyłem się jego specjalnej techniki zaklinania broni ognistymi zaklęciami. Ostatnio jak o nim słyszałem, pracował w kuźni z grupą łowiecką w Lordaeron\'ie.$B$BNie mogę Ci przekazać zbyt wielu szczegółów na temat tego procesu, ale powinieneś wiedzieć, że wymaga on krwi z rzadkich, wciąż bijących serc młodych czarnych smoków. Nie mam zbyt wiele do roboty czekając na list z Ironforge. Jeżeli przyniesiesz mi serca tych stworzeń, pokaże Ci moje umiejętności!",
    ["O"] = "Zdobądź Black Drake Heart dla Sigrun\'a Ironhew\'a.",
    ["T"] = "Zaklęcie Ognistego Błysku",
  },
  [707] = {
    ["D"] = "$N. Odebrałem raport od poszukiwacza Ironbanda z jego miejsca wykopalisk w Loch Modan - potrzebuje wykonać trochę pracy dotyczącej naszego kolejnego wykopaliska.$B$BNie posiadam więcej informacji na ten temat, ale jeśli $gchciałbyś:chciałabyś; rozprostować trochę nogi, to idź porozmawiać z Ironbandem.",
    ["O"] = "Porozmawiaj z poszukiwaczem Ironbandem w Ironband\'s Excavation Site położonym w Loch Modan.",
    ["T"] = "Ironband cię potrzebuje!",
  },
  [708] = {
    ["D"] = "Powierzchnia tej metalowej skrzynki jest mocno podziobana, jakby była zanurzona w kwasie - musiała być w żołądku potężnego kondora od dłuższego czasu.$B$BObracając skrzynke na drugą stronę, można zauważyć symbol opieczętowany na dnie. Pod symbolem znajdują się słowa:$B$B Silnik #19 - Oblężnicza Brygarda Ironforge",
    ["O"] = "Weź zardzewiałą czarną skrzynkę (Corroded Black Box) do Hall of Arms w Ironforge.",
    ["T"] = "Czarna skrzynka",
  },
  [709] = {
    ["D"] = "O nie! O nie! Klątwa nadchodzi. Śledź mnie! Klątwa!$B$BNie, nie mogę o tym mówić... Nie mogę wymawiać ich imion, mogą mnie usłyszeć! Ale jeśli... tak! Jeśli dowiedzielibyśmy się o nich więcej... może byśmy się dowiedzieli jak ich powstrzymać!$B$BMoże.$B$BIdź do Uldaman. Nie! Powiedziałem to! Musisz znaleźć... znaleźć Tablet of... Ryun\'eh. Tak, znajdź to! I nie zmuszaj mnie do wypowiedzenia tego słowa ponownie!$B$BTo znajduje się głęboko w tym miejscu, w antycznej skrzyni. Tam się ukrywa... W skrzyni stworzonej zanim jakikolwiek krasnolud pracował.",
    ["O"] = "Przynieś Tablet of Ryun\'eh do Theldurin the Lost.",
    ["T"] = "Rozwiązanie na fatum",
  },
  [710] = {
    ["D"] = "Tu w Badlands zatrzymałem się, by pracować nad moim najnowszym projektem: moich kajdan żywiołowego pętania.$B$BPo ukończeniu, pozwolą magom na przyzywanie potężniejszych żywiołaków i to w większych ilościach. Na początek potrzebuję małych odłamków kamienia, by przetestować kilka najnowszych zaklęć ofensywnych wraz z paroma złożonymi przeze mnie ustrojstwami.$B$BOdłamki łatwo zdobędziesz z pomniejszych skalnych żywiołaków na zachód stąd. Mógłbyś mi parę przynieść?",
    ["O"] = "Znajdź 10 Small Stone Shards i zanieś je Lotwil Veriatus w Badlands.",
    ["T"] = "Zgłębianie żywiołów: Skała",
  },
  [711] = {
    ["D"] = "$N, już udowodniłeś, że jesteś bardziej przydatny od wszystkich moich uczniów razem wziętych.$B$BNastępne części, których potrzebuję wymagają nieco więcej siły. Large Stone Slabs możesz znaleźć na Rock Elementals jeśli jesteś wystarczająco uważny. Ich ciała są większe i silniejsze, i dlatego są bardziej potrzebne do moich testów. Możesz je znaleźć idąc dalej na zachód stąd albo na południowy-wschód wzdłuż krawędzi górskich.$B$BMasz trochę czasu; będę potrzebował trochę czasu na zbadanie tych, które już mi przyniosłeś.",
    ["O"] = "Przynieś 3 Large Stone Slabs do Lotwil Veriatus znajdującego się w Badlands.",
    ["T"] = "Nauka o elementach: Skała",
  },
  [712] = {
    ["D"] = "$N, jest jeszcze jedna część, której będę potrzebował od elementali z Badlands: Bracers of Rock Binding od większych elementali skalnych. Zgodnie z moimi obliczeniami, te bransolety powinny wystarczyć do sprawdzenia siły moich własnych klamr.$B$BMoje próby poszukiwań większych elementali skał ukazały ich grupę na południowy zachód stąd, niedaleko ogrów, jeśli dobrze pamiętam.$B$BZdobądź dla mnie 5 ich bransolet, bym miał tu coś extra. Servo notorycznie zapodziewa gdzieś moje składniki i badania.",
    ["O"] = "Przynieś 5 Bracers of Rock Binding do Lotwil Veriatus w Badlands.",
    ["T"] = "Zgłębianie Tajników Elementów: Skała",
  },
  [713] = {
    ["D"] = "Pozwól, że powiem Ci coś o Frost Oil: nic tak jak on nie ochroni od przegrzania silnika czy przekładni.$B$BJego właściwości chłodzące są niesamowite, a żaden smar nie może się z nim równać w długowieczności. To nie wszystko: pomaga także w utrzymaniu zaklęć na magicznych przedmiotach.$B$BPotrzebuję fiolkę, by zwiększyć magiczne zdolności moich kajdan, by stały się na tyle potężne, aby powstrzymać przywołanego przyjaciela od zabicia nas.$B$BBro\'kin, mój przyjaciel goblin, może nauczyć Cię jak go zrobić. Znajdziesz go w Alterac.",
    ["O"] = "Znajdź Frost Oil i przynieś go do Lotwil Veriatus w Badlands.",
    ["T"] = "Chłodziwo Heads Prevail",
  },
  [714] = {
    ["D"] = "$N, Wykonałeś swoją robotę prawidłowo poza wszelkimi normami.$B$B<Lotwil jest rozproszony przez jego pracę>$B$BJeśli kiedykolwiek spotkamy się w Kharanos, śmiało zapytaj o pracę$B$BUps! Szybko, weź... tak, to. Dzięki.$B$BPotrzebuję jeszcze jedną rzecz. Niewielka część, ale raczej istotna. $B$BJeśli mógłbyś pójść i przynieść mi taką, powinienem być gotowy, aby to skończyć.",
    ["O"] = "Przynieś Gyrochronatom do Lotwil Veriatus w Badlands.",
    ["T"] = "Gyro... Co?",
  },
  [715] = {
    ["D"] = "Myślę, że przedmioty, które zdobyłeś dla Lotwil będą Twoim najmniejszym zmartwieniem, $N. Z drugiej strony, udowodniłeś więcej niż adept nauk Lotwila uważany za świętego, więc co powiesz na to, abyś mi pomógł?$B$BPotrzebuję Invisibility Potion oraz Healing Potion; obydwie mogą być wkrótce bardzo przydatne, jeśli będziemy z tym zwlekać.$B$BW zamian, oddam Tobie przepis na miksturę, którą wynalazłem podczas nauk u Lotwila. Bazuje ona na niektórych badaniach, które wykonywał tu w Badlands.",
    ["O"] = "Przynieś Healing Potion oraz Lesser Invisibility Potion dla Lucien Tosselwrench w Badlands.",
    ["T"] = "Płynny Kamień",
  },
  [716] = {
    ["D"] = "Wiem jak tani Lotwil może być, $N, więc pozwól mi zrobić coś na wszystkie Twoje problemy. Może to nawet pomoże uchronić Cię przed nadciągającym okrucieństwem jakim jest najnowsze odkrycie Lotwil\'a.$B$BPracowałem ze wszystkimi dodatkowymi kamieniami, które zebrałeś dla mnie i mogę zrobić dobre bransolety, które możesz chcieć użyć. Oczywiście są zaczarowane.$B$BBędę tylko potrzebował zdobionych bransolet z brązu zrobionych przez kowala, żebym mógł skończyć te, które robię dla Ciebie.",
    ["O"] = "Przynieś zdobione bransolety z brązu do Lucien Tosselwrench w Badlands.",
    ["T"] = "Skała jest lepsza niż tkanina",
  },
  [717] = {
    ["D"] = "Staje się oczywistym, że nie możemy zapewnić, iż Blacklash i Hematus pozostaną uwięzieni w Lethlor. Te czarne smoki się tam osiedliły i dlatego ogry zdołały ukraść Sign, co wskazuje, że więcej znaczących przedmiotów może być zabranych.$B$BWięzienie smoków jest utrzymywane przez trzy kamienie runiczne, które mogą być pozyskane przez użycie Sign of the Earth. Te kamienie runiczne mogą być potem użyte do złamania pieczęci, która je więzi.$B$B$N... upewnij się, że ich sen będzie wieczny.",
    ["O"] = "Użyj Sign of the Earth do aktywacji Pillars of Amethyst, Opal i Diamond oraz pozyskaj Runestones.$B$BUmieść kamienie runiczne w Seal of the Earth, by uwolnić Blacklasha i Hematusa.$B$BZabij ich i zwróć Blacklash\'s Bindings, Chains of Hematus i Sign of the Earth do Gareka.",
    ["T"] = "Drgania Ziemi.",
  },
  [718] = {
    ["D"] = "Kiedy w pośpiechu opuszczaliśmy wykopalisko w Ulduman\'ie, byliśmy zmuszeni pozostawić wiele z naszych wagonów i skrzyń z zaopatrzeniem po drodze. Miejscowe ogry z Camp Kosh rzuciły się na nasz porzucony ekwipunek jak sępy na gnijące ciała. Zapach nie był o wiele lepszy. Lepszy niż zapach ciał, mam na myśli.$B$BW każdym razie, zabrali też wagon, w którym były wszystkie nasze bronie... więc tak... to trochę niezręczne... Nie jesteśmy w stanie zdobyć nic do jedzenia.$B$BMamy tu mały problem i czy nie zechciałbyś nam z nim pomóc?",
    ["O"] = "Odzyskaj Supply Crate dla Sigrun\'a Ironhew\'a.",
    ["T"] = "Iluzje",
  },
  [719] = {
    ["D"] = "Hej, $N. Miej oczy dookoła głowy. Wszędzie roi się od krasnoludów z Dark Iron - wyglądają jak członkowie klanu Shadowforge. Zaatakowali wykopalisko, w którym pracowałem i zabili prawie wszystkich tam przebywających, w tym mojego szefa Hammertoe\'a. Ledwo uciekłem żywy.$B $BTo wykopalisko jest niedaleko stąd, na północ, więc próbuję obmyślić plan jak wydobyć choć część naszych zapasów, zwłaszcza mój szczęśliwy kilof.$B$BWyglądasz na kogoś kto byłby w stanie mi pomóc, prawda? Jeden z tych przeklętych Dark Iron\'ów ma mój kilof! Może być to którykolwiek z nich.",
    ["O"] = "Znajdź Ryedol\'s Lucky Pick i zwróć go Prospector\'owi Ryedo\'owi znajdującemu się na południe od Hammertoe\'s Dig Site.",
    ["T"] = "Krasnolud i jego narzędzia",
  },
  [720] = {
    ["D"] = "<Na mapie widnieje w pośpiechu nakreślony tekst.>$B$B\"Ryedol$BZabierają mnie do Uldamanu. Przyślij pomoc.$B-Hammertoe\"",
    ["O"] = "Znajdź Prospectora Ryedola i powiedz mu, że Hammertoe Grez żyje.",
    ["T"] = "Znak nadziei",
  },
  [721] = {
    ["D"] = "$N, możesz go znaleźć? Możesz znaleźć Hammertoe\'a w Uldamanie?$B$BJeśli nędzne krasnoludy z klanu Shadowforge trzymają go jako zakładnika, żeby dowiedzieć się, co wie na temat prac wykopaliskowych w sprawie tytanów, Ironforge może być w wielkim niebezpieczeństwie.$B$BOd dawna krasnoludy Dark Irons poszukiwały magii zdolnej tworzyć potężniejsze golemy. Hammertoe rzecz jasna robił to samo, ale tylko po to, by ich powstrzymać.$B$BPrawdopodobnie zatrzymają go przy życiu, póki nie dowiedzą się tego, co wie. Musisz się pospieszyć, jeśli chcesz go uratować!",
    ["O"] = "Znajdź w Uldamanie Hammertoe Greza.",
    ["T"] = "Znak nadziei",
  },
  [722] = {
    ["D"] = "Jesteś odważny... <kaszle>... żeby przyjść do Uldamanu po mnie, $C.$B$BJeśli naprawdę jesteś tu, by pomóc... staremu Hammertoe, to... <kaszle>... będziesz musiał znaleźć... mój amulet.$B$BMa go Deepshadow... Magregan Deepshadow. Gdzieś tu się kręci... pewnie w ruinach. Ten amulet zaprowadzi ich... <kaszle>... prosto do zwojów, jeśli nikt go nie powstrzyma. To zadanie dla ciebie, $N. Proszę... zdobądź ten amulet.$B$BZwoje na pewno pomogą krasnoludom Dark Irons stworzyć jeszcze potężniejsze golemy. Po prostu wiem o tym. Czuję to w kościach.",
    ["O"] = "Znajdź Hammertoe\'s Amulet i odnieś mu go do Uldamanu.",
    ["T"] = "Amulet tajemnic",
  },
  [723] = {
    ["D"] = "<Hammertoe zaciska dłoń na ranie i przez chwilę stara się uspokoić, nim odzywa się ponownie.>$B$BZnajdź Ryedola, $N. Zanieś mu mój amulet. <kaszle> On... <kaszle> wymyśli, co dalej. Wie, że szukałem prawdy o pochodzeniu naszego ludu i... <kaszle> wie, że moją misją było również zatrzymanie klanu Shadowforge. Nie można pozwolić, by odnaleźli zwoje... <kaszle>",
    ["O"] = "Zanieś Hammertoe\'s Amulet do Prospectora Ryedola w Badlands.",
    ["T"] = "Perspektywa wiary",
  },
  [724] = {
    ["D"] = "Spokojnie, tylko spokojnie... kto może wiedzieć, co dalej?$B$BHistoryk Karnik! Tak jest!$B$BZnajdziesz go w Ironforge. Będzie w stanie ci pomóc. On i Hammertoe razem pracowali nad poszukiwaniem zaginionych artefaktów w Uldamanie.$B$BZapewne Shadowforge zorientowała się, że ci dwaj wiedzieli więcej niż powinni.$B$BOpowiedz Karnikowi, co stało się Hammertoe\'owi, i daj mu amulet - powie ci, co zrobić dalej.",
    ["O"] = "Zabierz Hammertoe\'s Amulet do Historyka Karnika w Ironforge.",
    ["T"] = "Perspektywa wiary",
  },
  [725] = {
    ["D"] = "$N, biegnij znaleźć Advisora Belgruma tak szybko, jak tylko potrafisz. Powiedz mu, czego byłeś świadkiem i zapytaj, co mamy dalej robić. Ten list powie mu więcej.$B$BW międzyczasie porozmawiam z duchem Hammertoe\'ego. Może będzie wiedział coś, co pomoże nam w zatrzymaniu działań tych durni z Shadowforge w Badlands. Pozostaje nam się modlić.",
    ["O"] = "Znajdź Advisora Belgruma i przekaż mu list.",
    ["T"] = "Wieść o zagrożeniu",
  },
  [726] = {
    ["D"] = "<Advisor Belgrum osiąga koniec notatki i jego oczy rozszerzają się na chwilę.>$B$BOch, to są złe wieści.$B$B$N, proszę wróć do Historian Karnik i powiedz mu, że ma dzięki władzy królewskiej działać na podstawie tych informacji szybko i zdecydowanie. Musi powstrzymać działalność Shadowforge w Badlands.",
    ["O"] = "Porozmawiaj z Historian Karnik.",
    ["T"] = "Przelotne Słowo Groźby",
  },
  [727] = {
    ["D"] = "Ta tablica dużo mówi. Ale nie wystarczająco dużo! Nawet się do tego nie zbliża!$B$BJest taka księga, kompendium, które Yagyin napisał wieki temu. Ludzie... przed którymi uciekłem... trzymają tę księgę w wielu miejscach. Najmędrsi z nich studiowali ją. Zawiera obszerną wiedzę. Wiedzę, jak nas ochronić!$B$BUdaj się do Gerriga Bonegripa. Znajdziesz go w sklepie w Forlorn Cavern w Ironforge. Pokaż mu tę pieczęć, a pomyśli, że jesteś jednym z nich. Poproś go o \"Yagyin\'s Digest\"... I przynieś mi je!",
    ["O"] = "Daj Sigil of the Hammer Gerrigowi Bonegripowi z Forlorn Cavern Ironforge.",
    ["T"] = "Do Ironforge po &quot;Kompendium Yagyina&quot;",
  },
  [728] = {
    ["D"] = "Ta tablica dużo mówi. Ale nie wystarczająco dużo! Nawet się do tego nie zbliża!$B$BJest taka księga, kompendium, które Yagyin napisał wieki temu. Ludzie... przed którymi uciekłem... trzymają tę księgę w wielu miejscach. Najmędrsi z nich studiowali ją. Zawiera obszerną wiedzę. Wiedzę, jak nas ochronić!$B$BUdaj się do Keepera Bel\'dugura, do Undercity of Lordaeronu. Pokaż mu tę pieczęć, a pomyśli, że jesteś jednym z nich. Poproś go o \"Yagin\'s Digest\"... I przynieś mi je!",
    ["O"] = "Przynieś Sigil of the Hamme Opiekunowi Bel\'dugurowi z Undercity.",
    ["T"] = "Do Podmiasta po &quot;Kompendium Yagyina&quot;",
  },
  [729] = {
    ["D"] = "Gdy mistrz Greywhisker przydzielił mnie do pracy pod kierownictwem wielkiego poszukiwacza Remtravela, był to dla mnie wielki zaszczyt. W akademii w Ironforge każdy słyszał o jego wspaniałych odkryciach.$B$BAle poszukiwacz jest ostatnimi czasy jakoś... yy... niepomny... na otoczenie.$B$BOdkryliśmy ślady po wielkiej społeczności. Straszliwe golemy wyłoniły się z ziemi i opanowały teren wykopalisk. Remtravel nawet tego nie zauważył. Pobiegłam do Auberdine po pomoc.$B$BProszę, udaj się na południe i sprawdź, czy z nim wszystko w porządku!",
    ["O"] = "Udaj się na południe i sprawdź, co dzieje się z poszukiwaczem Remtravelem.",
    ["T"] = "Roztargniony poszukiwacz",
  },
  [730] = {
    ["D"] = "Jak miło widzieć $C $gzainteresowanego:zainteresowaną; wspaniałymi cudami archeologicznymi naszego świata.$B$BNasza praca jest często lekceważona przez naszych przyjaciół z Przymierza, którzy uważają ją za zwykłe dziwactwo. Lecz, co wielu z nich bagatelizuje, nasze ostatnie odkrycia w rejonie Khaz Modan niezbicie dowodzą istnienia wielkiej i potężnej siły zagrażającej całemu Azeroth, od Lordaeronu po Kalimdor.$B$BMartwię się o moją ekipę, którą wysłałem do Darkshore. Od tygodni nie dali znaku życia.$B$BUdaj się do Auberdine i dowiedz się, gdzie się podziali.",
    ["O"] = "Udaj się do Auberdine i poszukaj śladów krasnoludzkiej ekipy archeologicznej.",
    ["T"] = "Kłopoty w Darkshore?",
  },
  [731] = {
    ["D"] = "A więc, Hollee... Och, racja, nie jesteś Hollee. Gdzie jest Hollee?$B$BEch, mniejsza o to. Musimy odnaleźć pędzelek do kamieni... To znaczy, tajemniczą skamieniałość! Tak, musimy odnaleźć skamieniałość. Liga Odkrywców w Darnassus będzie chciała zobaczyć jakieś wyniki tutejszych prac.$B$BPowiedz mi, gdy będziesz $ggotowy:gotowa;, to wyruszymy na poszukiwanie tego pędzelka... Znaczy, skamieniałości! Musimy mieć odkrycie czegoś na piśmie, by zadowolić Ligę.$B$BTo jesteś już $ggotowy:gotowa;?",
    ["O"] = "Chroń poszukiwacza Remtravela podczas poszukiwań tajemniczej skamieniałości, potem wróć do archeologa Hollee w Auberdine.",
    ["T"] = "Roztargniony poszukiwacz",
  },
  [732] = {
    ["D"] = "Słyszałem od Sigruna, że byłeś dla niego bardzo pomocny. Prawdopodobnie ja też skorzystam z twojej pomocy. Zostałem tu skierowany przez mojego mistrza, Krasusa z Kirin Toru, aby zakończyć ten wiszący w powietrzu problem w Lethlor Ravine.$B$BNie mogę zdradzać dokładnego charakteru mojego zadania lub zadań jakie muszę podjąć, lecz gwarantuję Ci, że to sprawa ma ogromne znaczenie.$B$BBanda wędrownych ogrów, widywana nieopodal Camp Boff, ukradła przedmiot zwany Sign of the Earth; Muszę go mieć. Przynieś go do mnie, a powiem Ci więcej.",
    ["O"] = "Odzyskaj Sign of the Earth dla Gareka.",
    ["T"] = "Trzęsienia Ziemi",
  },
  [733] = {
    ["D"] = "Będzie tu naprawdę gorąco, jeżeli jakimś cudem nie uda mi się skombinować trochę materiałów do budowy osłony i innych potrzebnych nam rzeczy. Zauważyłem, że okoliczne ogry noszą przy sobie nieco złomu. Może historie o silnikach w Badlands nie były wcale taką bujdą...$B$BTak czy siak, Poszukiwacz martwi się o stan naszego małego obozu, więc wolałbym się szybko zabrać do roboty.$B$BGłówny obóz ogrów to Dustbelch Grotto, kawał drogi na zachód stąd.",
    ["O"] = "Zdobądź siedem Scrap Metal dla Sigruna.",
    ["T"] = "Kombinowanie",
  },
  [734] = {
    ["D"] = "Cudownie, cudownie.$B$B<Lotwil spogląda na ciebie przez chwilę, po czym wraca do swoich kajdan.>$B$BIdź porozmawiać z Lucienem, $N. Potrzebuję zębatki nr 5. Przynieś mi ją, dobrze?",
    ["O"] = "Porozmawiaj z Lucienem Tosselwrenchem w Badlands.",
    ["T"] = "To nie będzie łatwe",
  },
  [735] = {
    ["D"] = "\"Kompendium Yagyina\", co? Czyżbyś planował założyć nową siedzibę naszego bractwa? Nieważne, to nie moja sprawa.$B$BPomogę ci, gdyż posiadam nadliczbowy egzemplarz. Musimy sobie nawzajem pomagać, nieprawdaż? Właśnie dzięki temu rośniemy w siłę.$B$BPotrzebuję trzech przedmiotów mocy. Dostarcz mi je, a dam ci kompendium.$B$BNie wymówię ich imion. Ktoś może nas podsłuchiwać. Spójrz jednak tutaj, wypiszę je na kartce.",
    ["O"] = "Dostarcz przedmioty zawarte w Bonegrip\'s Note do Gerriga Bonegripa z Ironforge.",
    ["T"] = "Gwiazda, Ręka i Serce",
  },
  [736] = {
    ["D"] = "Potrzebujesz \"Kompendium Yagyina\"? A więc planujesz powiększyć naszą trzódkę? Pewnie, że tak... i oczywiście, że ci pomogę, $gbracie:siostro;.$B$BAle ty też musisz mi pomóc.$B$BPotrzebuję trzech przedmiotów mocy. Dostarcz mi je, a kompendium będzie twoje.$B$BNie mogę wymówić ich nazw, dlatego ci je napiszę.$B$BPrzynieś mi przedmioty z tej listy. Jeśli uda ci się tego dokonać, zaprawdę $ggodny:godna; jesteś otworzyć własną placówkę naszego zakonu.",
    ["O"] = "Dostarcz przedmioty zawarte w Bel\'dugur\'s Note do strażnika Bel\'dugura z Undercity.",
    ["T"] = "Gwiazda, Ręka i Serce",
  },
  [737] = {
    ["D"] = "$N, mam dla ciebie kompendium. Chyba nie muszę mówić, że należy się z nim obchodzić z wielką ostrożnością. I trzymać je z dala od nieprzyjaznych rąk.$B$BTa książka zawiera wiele prawd...$B$B...A prawda może zostać spalona.",
    ["O"] = "Zabierz \"Kompendium Yagyina\" do Theldurina.",
    ["T"] = "Zakazana wiedza",
  },
  [738] = {
    ["D"] = "Poszukiwacz Agmond dowodził wykopaliskami w Badlands, na południowy zachód stąd. Powiedziałem \"dowodził\", gdyż... cóż, nie kontaktował się już od tygodni. Chcę, abyś odnalazła Agmonda, abym mógł otrzymać jego raport.$B$BKiedy ostatnim razem słyszałem o Agmondzie, przebywał w wysuniętej najbardziej na południe strefie wykopaliskowej w Badlands. Chodzi o niewielkie przedsięwzięcie w pobliżu Fortecy Angor. Na twoim miejscu tam właśnie rozpocząłbym poszukiwania.",
    ["O"] = "Odnajdź Agmonda.",
    ["T"] = "Odnajdź Agmonda",
  },
  [739] = {
    ["D"] = "Ślady Agmonda prowadzą na zachód. Po rozmazanej na skałach i piasku krwi łatwo stwierdzić, że krasnolud czołgał się przez pewną odległość.$B$BA tutaj skonał.$B$BBliższe oględziny ujawniają słowo \"Murdaloc\", nabazgrane niewyraźnie na kawałku piaskowca.$B$BTuż obok martwej ręki Agmonda.",
    ["O"] = "Zgładź Murdaloca - mordercę Agmonda.$B$BZabij 12 Stonevault Bonesnappers.$B$BZamelduj się u Prospectora Ironbanda w Loch Modan.",
    ["T"] = "Murdaloc",
  },
  [741] = {
    ["D"] = "A więc poszukiwacz chce wysłać tajemniczą skamieniałość do Ligi Odkrywców w Darnassus? Nie czułabym się dobrze opuszczając Darkshore bez niego.$B$BTrzymaj $N; zabierz tę tajemniczą skamieniałość do głównego archeologa Greywhiskera w Darnassus.",
    ["O"] = "Zabierz tajemniczą skamieniałość do głównego archeologa Greywhiskera w Darnassus.",
    ["T"] = "Roztargniony poszukiwacz",
  },
  [742] = {
    ["D"] = "Uwaga, młodzi poszukiwacze przygód! Knieje Ashenvale czekają na was!$B$BHorda zajęła silną pozycję na ziemiach na północ od Barrens. Nasze dwa posterunki – Warownia Splintertree i Placówka Zoram Strand – pragną przynieść chwałę Hordzie! Pragnący dowieść swych umiejętności winni zasięgnąć tam informacji. Uwaga: Senani Thunderheart z Warowni Splintertree, dokładnie na północ od Barrens, szuka śmiałków chętnych wziąć udział w wielkim polowaniu w Ashenvale!",
    ["O"] = "Porozmawiaj z Senani Thunderheart z Splintertree Post w Ashenvale.",
    ["T"] = "Polowanie w Ashenvale",
  },
  [743] = {
    ["D"] = "Dziękuję, że $gznalazłeś:znalazłaś; chwilę na rozmowę ze mną, $N. Jestem Ruul, wojownik i nauczyciel.$B$BNajwyraźniej $gosiągnąłeś:osiągnęłaś; już wiek, w którym pora ci przygotować się do prób, jeśli masz zamiar opuścić Mulgore.$B$BJeśli szukasz możliwości sprawdzenia swej siły, zacznij od znalezienia harpii Wietrznej Furii na południowym wschodzie. Gnieżdżą się na górskich graniach z dala od drogi.$B$BSą jednym z naszych miejscowych naturalnych wrogów. Będą dobrym sprawdzianem twych umiejętności.",
    ["O"] = "Przynieś 8 Windfury Talons do Ruula Eagletalon z wioski Bloodhoof.",
    ["T"] = "Niebezpieczne Wietrzne Furie",
  },
  [744] = {
    ["D"] = "$N, mój brat wkrótce stanie przed wodzem Bloodhoofem, i przypadł mi zaszczyt przygotowania dla niego pióropusza.$B$BChciałbym prosić cię, byś $gwyświadczył:wyświadczyła; mi pewną przysługę, podczas gdy ja będę kończył garbować te skóry. Nie mam już czasu szukać piór na własną rękę i zastanawiałem się, czy nie $gmógłbyś:mogłabyś; mi ich dostarczyć?$B$BPióra odpowiedniej wielkości zdobędziesz na harpiach zamieszkujących Thunder Bluff w znacznej odległości na północ i północny zachód. By ukończyć me dzieło potrzebuję jeszcze tylko 6 lazurowych i 6 brązowych piór.",
    ["O"] = "Zbierz 6 Azure Feathers i 6 Bronze Feathers, a następnie przynieś je Eyahnowi Eagletalon z Thunder Bluff.",
    ["T"] = "Przygotowania do ceremonii",
  },
  [745] = {
    ["D"] = "$N, wiele konfliktów rozdziera tę krainę. Mam nadzieję, że nie będzie ci dane widzieć tak wielu, jak mnie. Wszakże pragnę, byś $gzajął:zajęła; się jednym z nich. Pozwoli ci to zrozumieć, jak wiele krzywdy potrafi wyrządzić tej ziemi nie zażegnany w porę konflikt.$B$BGnolle Wypłowiałej Grzywy osiedliły się na południe od wioski oraz w jaskini na zachodzie. Wzgardziły naszymi próbami porozumienia się i bez opamiętania wyrzynają miejscową zwierzynę.$B$BRozmowy nie są już dłużej rozwiązaniem.",
    ["O"] = "Zabij 10 Palemane Tanners, 8 Palemane Skinners i 5 Palemane Poachers, następnie wróć do Baine\'a Bloodhoofa, w Bloodhoof Village.",
    ["T"] = "Wspólna kraina",
  },
  [746] = {
    ["D"] = "Krasnoludy przygotowują strefę wykopaliskową na północnym zachodzie. Sądzą, że ziemia skrywa tajemnice - to prawda, lecz dziurawienie jej i plugawienie nie prowadzi do poznania jej nauk.$B$BZbierz służące do kopania narzędzia krasnoludów, uszkodź je i zwróć mi w postaci zniszczonych narzędzi.$B$BMożesz tego dokonać w kuźni. Jedna stoi w Thunder Bluff, lecz nada się każda - nawet ta w obozie krasnoludów.",
    ["O"] = "Zbierz 5 Prospector\'s Picks.$B$BPrzekuj je w kuźni, by uzyskać Broken Tools.$B$BPrzynieś 5 Broken Tools do Baine Bloodhoofa z wioski Bloodhoof Village.",
    ["T"] = "Wykopy krasnoludów",
  },
  [747] = {
    ["D"] = "Wydaje mi się, że na wiele cię stać, i dowiedziesz tego w oczach plemienia. Być może pewnego dnia w bliskiej przyszłości zostaniesz $gpowitany:powitana; we wspaniałym mieście Thunder Bluff. Lecz zanim to nastąpi, musisz dowieść swej wartości w oczach mego ojca, Wodza Hawkwinda.$B$BTutaj, w Red Cloud Mesa, szczycimy się naszymi zdolnościami łowieckimi. Tauren poluje zarówno z potrzeby, jak i dla rozrywki. Nasze zapasy mięsa się wyczerpują, a i piór na ubrania również nie zostało wiele. Zapoluj na okoliczne stepochodźce i dowiedź swych umiejętności zaopatrując wioskę.",
    ["O"] = "Grull Hawkwind z Camp Narache potrzebuje 7 Plainstrider Feathers i 7 kawałków Plainstrider Meat.",
    ["T"] = "Rozpoczyna się polowanie",
  },
  [748] = {
    ["D"] = "Gobliny i ich słudzy zatruwają nasze święte studnie! Nie możemy na to pozwolić.$B$BAby oczyścić każdą ze studni, muszę stworzyć dla niej totem oczyszczenia. Następnie będziesz $gmusiał:musiała; zanieść totem do odpowiadającej mu studni i odprawić rytuał oczyszczenia.$B$BNajpierw przygotujemy totem oczyszczenia dla studni Zimowych Kopyt. Abyśmy mogli tego dokonać, ziemia musi udzielić swej pomocy. Zapoluj na preriowe wilki, aby zdobyć ich łapy, oraz na dorosłe stepochodźce dla ich pazurów. Znajdziesz je na południowym zachodzie.$B$BWróć do mnie z łapami i pazurami, $N.",
    ["O"] = "Przynieś 6 Prairie Wolf Paws i 4 Plainstrider Talons do Mulla Thunderhorna z Bloodhoof Village.",
    ["T"] = "Zatruta woda",
  },
  [749] = {
    ["D"] = "Kilka dni temu natrafiliśmy na wozy Venture Co., wędrujące pod strażą wzdłuż północnego brzegu Jeziora Stonebull. We wcześniejszej bitwie straciliśmy dwóch wojowników, toteż zdecydowaliśmy się na szybki atak i spaliliśmy karawanę.$B$BPorzuciliśmy ich skrzynie z zaopatrzeniem, przekonani, że nasze pochodnie zniszczą wszystko co cenne. Jednak biorąc pod uwagę, iż w pobliżu płonących wozów dostrzeżono zbieraczy Venture Co,, chyba byliśmy w błędzie.$B$BMoże $gmógłbyś:mogłabyś; wybrać się do karawany i zbadać zawartość skrzyń.",
    ["O"] = "Morin Cloudstalker chce, abyś $gzbadał:zbadała; zawartość skrzyń z zaopatrzeniem ze zniszczonej karawany.",
    ["T"] = "Spustoszona karawana",
  },
  [750] = {
    ["D"] = "Tauren biegły w sztuce łowów wie, iż jego ofiara jest nie tylko zwykłym trofeum. Zwierzyna z równin dostarcza nam środków do przetrwania. Wywrzesz spore wrażenie na starszyźnie, jeśli przyniesiesz kilka cenionych skór górskich kuguarów. Bestie te czają się na południowych wzgórzach.$B$BNasze dzieci potrzebują ubrań, a namioty naprawy.",
    ["O"] = "Grull Hawkwind z Camp Narache chce, abyś $gdostarczył:dostarczyła; mu 10 Mountain Cougar Pelts.",
    ["T"] = "Polowanie trwa",
  },
  [751] = {
    ["D"] = "Wyważenie pokrywy ukazuje twoim oczom ciasno upakowany asortyment rudy i minerałów, kolejne dowody na działalność wydobywczą Venture Co. w Mulgore. Na szczycie stosu kruszcu, który $godsłoniłeś:odsłoniłaś; znajduje się ciasno związany plik papierów.$B$BOd zboczy gór na wschodzie docierają do ciebie odgłosy pracy oraz widzisz dym unoszący się znad sporego paleniska.",
    ["O"] = "Zanieś dokumenty Venture Co. do Morina Cloudstalkera nieopodal Bloodhoof Village.",
    ["T"] = "Spustoszona karawana",
  },
  [752] = {
    ["D"] = "Wszyscy członkowie plemienia żyją w harmonii. Żyjemy razem i pracujemy razem.$B$BNasze zobowiązania wobec innych wiążą się z dużą odpowiedzialnością. Chcę powierzyć ci teraz drobne zadanie.$B$BMoja matka wyruszyła dziś rano, by przynieść wodę ze studni na południowy wschód od Narache. To już trochę trwa. Może $gmógłbyś:mogłabyś; sprawdzić, co się z nią dzieje, podczas gdy ja zajmę się sprawami plemienia?",
    ["O"] = "Wódz Hawkwind chce, byś $godszukał:odszukała; jego matkę niedaleko studni na południowy wschód od Camp Narache.",
    ["T"] = "Drobne zadanie",
  },
  [753] = {
    ["D"] = "Przebyłam w mym życiu wiele dróg i te stare nogi straciły już wigor, jaki niegdyś posiadały. Wciąż mogę pełnić moje obowiązki względem plemienia. Po prostu czasem zajmuje to starej kobiecie nieco więcej czasu.$B$BZa to ty wyglądasz krzepko. Poddajmy testowi twoją młodzieńczą witalność. Weź dzban wody ze studni i zanieś go do mego syna, Wodza, w Obozie Narache.$B$BPamiętaj, że nawet najskromniejsze zadanie może zaowocować uznaniem wśród starszyzny.",
    ["O"] = "Weź Water Pitcher ze studni.$B$BZanieś go do Wodza Hawkwinda, w Camp Narache, który znajduje się na północny zachód od studni.",
    ["T"] = "Drobne zadanie",
  },
  [754] = {
    ["D"] = "Sporządziłem totem do oczyszczenia studni Zimowych Kopyt. Teraz musisz go zanieść do tej studni i przeprowadzić rytuał oczyszczenia. Znajdziesz ją na południowym wschodzie, strzeżoną przez ohydne gobliny!$B$BNie będzie to proste zadanie, ale musisz je wykonać, jeśli mamy jeszcze kiedyś korzystać z jej wód.$B$BŻyczę szczęścia, $N.",
    ["O"] = "Użyj Winterhoof Cleansing Totem przy Winterhoof Water Well, a następnie wróć do Mulla Thunderhorna.",
    ["T"] = "Oczyszczenie studni Zimowych Kopyt",
  },
  [755] = {
    ["D"] = "Twoja gotowość do wykonywania nawet skromnych zadań dla taurenów z Narache oraz ochota do nauki są szlachetnymi cechami. Wierzę, że pewnego dnia w Thunder Bluff powitają cię jako $gwielkiego:wielką; $C.$B$BPrzedtem jednak musisz przystąpić do Prób Matki Ziemi, których jest trzy.$B$BPierwszym sprawdzianem jest Próba Siły. Udaj się do Widzącego Graytongue\'a i powiedz mu, że Wódz Hawkwind cię przysyła.$B$BJego siedzibę odnajdziesz dokładnie na południe od Camp Narache, ukrytą głęboko w górach.",
    ["O"] = "Udaj się do Widzącego Graytongue\'a, który żyje w górach dokładnie na południe od Camp Narache.",
    ["T"] = "Próby Matki Ziemi",
  },
  [756] = {
    ["D"] = "By stworzyć oczyszczający totem Grzmiących Rogów, musisz zdobyć pazury drapieżników z równin Mulgore. Zapoluj na preriowych tropicieli i równinne kuguary, by zdobyć ich pazury, a potem wróć do mnie.$B$BDrapieżniki te znajdziesz na wschód i zachód stąd.",
    ["O"] = "Przynieś 6 Stalker Claws i 6 Cougar Claws do Mulla Thunderhorna.",
    ["T"] = "Totem Grzmiących Rogów",
  },
  [757] = {
    ["D"] = "Próby Matki Ziemi są krokami, które musi uczynić $gmłody tauren:młoda taurenka;, by zyskać szacunek w Thunder Bluff.$B$BJako pierwszą musisz przejść Próbę Siły. W tym sprawdzianie musisz dowieść swojej odwagi mordując wrogów plemienia.$B$BNajeżaki z parowu na wschodzie naruszają granice naszych plemiennych ziem. Urządzają zasadzki na naszych łowców i okradają wioskę po zapadnięciu zmierzchu.$B$BDowiedź swego męstwa zabijając tych łotrów, a potem wróć do Wodza Obozu Narache z ich pasami, jako dowodem swego wyczynu.",
    ["O"] = "Zabij Bristlebacks z Brambleblade Ravine i przynieś 12 Bristleback Belts do Wodza Hawkwinda z Camp Narache.",
    ["T"] = "Próba Siły",
  },
  [758] = {
    ["D"] = "Totem jest gotowy. I znowu twoim zadaniem jest odprawić rytuał oczyszczenia.$B$BUdaj się do studni Grzmiących Rogów, na północ od wioski, i użyj totemu oczyszczającego Grzmiących Rogów do swego rytuału. Kiedy to uczynisz, wróć do mnie.$B$BNiech cię duchy prowadzą.",
    ["O"] = "Użyj Thunderhorn Cleansing Totem przy Thunderhorn Water Well, a potem wróć do Mulla.",
    ["T"] = "Oczyszczenie studni Grzmiących Rogów",
  },
  [759] = {
    ["D"] = "Pozostała jeszcze jedna studnia do oczyszczenia, nazwana imieniem klanu Dzikich Grzyw. Aby to źródło stało się czyste, ziemia musi ofiarować zęby zajadłego drapieżnika, samca preriowego wilka. Samce wilków znajdziesz na północ stąd; wróć do mnie, gdy twoje polowanie dobiegnie końca.$B$BWilki te często wędrują wokół podnóża naszego potężnego miasta, Thunder Bluff.",
    ["O"] = "Przynieś 8 Prairie Alpha Teeth do Mulla Thunderhorna z Bloodhoof Village.",
    ["T"] = "Totem Dzikich Grzyw",
  },
  [760] = {
    ["D"] = "Oczyszczenie przez ciebie studni Zimowego Kopyta i Grzmiących Rogów jest tematem rozmów między duchami, $gmłody:młoda; $N. Totem Dzikiej Grzywy jest gotowy, a twoje ostatnie zadanie czeka na ciebie.$B$BStudnia Dzikiej Grzywy leży na północ od Thunder Bluff. Odpraw rytuał! Ulecz ziemie z trucizny goblinów! Pozwól czystej wodzie znów płynąć!",
    ["O"] = "Użyj Wildmane Cleansing Totem przy Wildmane Water Well, a następnie wróć do Mulla Thunderhorna.",
    ["T"] = "Oczyszczenie studni Dzikich Grzyw",
  },
  [761] = {
    ["D"] = "Sęponury to przebiegłe ptaki, trudne do znalezienia i upolowania. Kolekcja piór sęponurów to oznaka sprytu i determinacji łowcy.$B$BJeśli chcesz podjąć się tego zadania, wkrocz na równiny i zapoluj na nie.$B$BPrzynieś mi ich pióra, przynieś zaszczyt swemu klanowi.$B$BSeponury można znaleźć w całym Mulgore, ale twe oczy muszą być bystre, by je zauważyć, a twe kopyta muszą być szybkie, by je złapać.",
    ["O"] = "Przynieś 8 Trophy Swoop Quills do Harkena Windtotema z Bloodhoof Village.",
    ["T"] = "Polowanie na sęponury",
  },
  [762] = {
    ["D"] = "Ambasador Infernus został wysłany do Fortecy Angor przez samego Ragnarosa, by nadzorować klan Shadowforge w jego poszukiwaniach zaginionych artefaktów w Uldamanie.$B$BJuż teraz oznacza to niebywałe straty dla naszego ludu, a wkrótce będzie jeszcze gorzej. Nie chcę nawet zgadywać, jak dużo artefaktów uda im się znaleźć i użyć przeciwko Ironforge.$B$BNasz cel jest prosty. Wróć do Badlands i zniszcz Ambasadora Infernusa. Gdy zagrożenie zostanie wyeliminowane, wróć do Advisor Belgrum z dowodem twojego zwycięstwa.$B$BWszystko jest teraz w twoich rękach.",
    ["O"] = "Zabij Ambasadora Infernusa w Fortecy Angor i przynieś dowód jego śmierci do Doradcy Belgruma w Ironforge.",
    ["T"] = "Ambasador zła",
  },
  [763] = {
    ["D"] = "W ramach kontynuowania Prób Matki Ziemi musisz przejść jeszcze dwa sprawdziany. Nadszedł czas, byś $gposzerzył:poszerzyła; swoje doświadczenie.$B$BIdź do Wioski Bloodhoof i odnajdź Wodza, Baine\'a Bloodhoofa, syna Cairne\'a. Tam będziesz $gmógł:mogła; kontynuować swą podróż i zyskać akceptację starszyzny Thunder Bluff.$B$BZabierz ten totem do Baine\'a. Rozpozna moje rzeźbienia i pomoże ci w dalszej drodze.$B$BUdaj się drogą wychodzącą z Camp Narache i nie zwalniaj kroku. Nie błąkaj się, bo zgubisz drogę.",
    ["O"] = "Weź Totem Hawkwinda do Baine\'a Bloodhoofa z Bloodhoof Village. Podążaj drogą z Camp Narache.",
    ["T"] = "Próby Matki Ziemi",
  },
  [764] = {
    ["D"] = "To wyjaśnia nagromadzenie pracowników Venture Co. i ekwipunku, który widzieliśmy w Mulgore. Te gobliny... Ich kompania poszerza pole działania zbyt szybko. Jak to mówią, pokaż coś goblinowi, a usłyszysz brzdęk monet w tle.$B$BChciwe pokurcze. Na nieszczęście dla ich interesów, my, taureni, nie możemy pozwolić im na prowadzenie działań na naszych ziemiach. Udaj się do ich kopalni na północny wschód od spustoszonej karawany i przekaż im wiadomość.",
    ["O"] = "Zabij 14 Venture Co. Workers i 6 Venture Co. Supervisors dla Morina Cloudstalkera z Bloodhoof Village.",
    ["T"] = "Venture Company",
  },
  [765] = {
    ["D"] = "Zgodnie z dokumentami, które $gocaliłeś:ocaliłaś; z karawany, Venture Co. opracowało wiele sposobów przepędzenia nas z naszym ziem, aby móc bezkarnie je plądrować.$B$BGotowość, by posunąć się tak daleko, by osiągnąć swe cele, brzydzi mnie i przeraża. Chcę, by główny autor i wykonawca tych planów został zabity. To nadzorca Fizsprocket; znajdziesz go w kopalni na wschód od spustoszonej karawany. Przynieś mi jego notatnik, przekonamy się, czy znajdziemy tam coś użytecznego.",
    ["O"] = "Zabij nadzorcę Fizsprocketa i przynieś jego notatnik do Morina Cloudstalkera z Bloodhoof Village.",
    ["T"] = "Nadzorca Fizsprocket",
  },
  [766] = {
    ["D"] = "Mój dziadek opowiedział mi kiedyś historię o swych walkach ze stepochodźcem imieniem Mazzranache. Mówił mi o jego demonicznych oczach, szponach ostrych niczym brzytwa i jadowitym dziobie.$B$BLos zdecydował, że natknąłem się na niego, przemierzając równiny. Bestia ugryzła mnie w ramię. Była tak przerażająca, jak opisywał ją mój dziadek.$B$BTeraz, by oczyścić ranę z infekcji, będę potrzebował dość trudnych do pozyskania organów zwierząt: serca wilka, kości udowej kuguara, łuski stepołaza i żołądka sęponura.$B$BSpiesz się, czas jest na wagę złota.",
    ["O"] = "Przynieś Prairie Wolf Heart, Flatland Cougar Femur, Plainstrider Scale i Swoop Gizzard do Maura Raincaller z Bloodhoof Village.",
    ["T"] = "Mazzranache",
  },
  [767] = {
    ["D"] = "Próba Wizji, jedna z Prób Matki Ziemi, wprowadzi cię na drogę do zdobycia szacunku starszych z Thunder Bluff.$B$BNasz lud nauczył się, że ziemia jest naszym najświętszym żywicielem. Aby wziąć udział w rytualnej wizji, musisz porozmawiać z duchowym przywódcą wioski, Zarlmanem Two-Moons.",
    ["O"] = "Porozmawiaj z Zarlmanem Two-Moons z Bloodhoof Village.",
    ["T"] = "Próba Wizji",
  },
  [768] = {
    ["D"] = "Witaj, $gmłodzieńcze:młoda damo;. Masz iskrę w oku, widać, że masz ochotę znowu zapolować na równinach. Obyś $gprzyniósł:przyniosła; honor swemu klanowi!$B$BZajmuję się skórami zwierząt, szyję z nich ubrania i pancerze dla mieszkańców Thunder Bluff.$B$BJeśli upolujesz zwierzynę i przyniesiesz mi skóry, wtedy i dla ciebie coś uszykuję.",
    ["O"] = "Przynieś 12 kawałków Light Leather do Verena Tallstridera z Thunder Bluff.",
    ["T"] = "Zbieranie skór",
  },
  [769] = {
    ["D"] = "Kodo z Mulgore są silne i krzepkie - budzą nasz szacunek. Jeśli jesteś wprawnym kuśnierzem i chcesz się dowiedzieć, jak wykonać torbę ze skór kodo, przynieś mi niezbędne przedmioty.$B$BZrób to, a podzielę się z tobą mą wiedzą.",
    ["O"] = "Przynieś 4 kawałki Light Leather i 4 Coarse Thread do Verena Tallstridera z Thunder Bluff.",
    ["T"] = "Torba ze skór kodo",
  },
  [770] = {
    ["D"] = "Postrzępiona skóra Ghost Howl wciąż nosi straszliwą ranę, pochodzącą z czasów walk wilka z Płonącym Legionem.$B$BMoże ktoś z Wioski Bloodhoof powinien dowiedzieć się o śmierci wilka...",
    ["O"] = "Znajdź kogoś, kto słyszał o Ghost Howl.",
    ["T"] = "Futro pobliźnione przez demona",
  },
  [771] = {
    ["D"] = "By przejść Próbę Wizji, musisz najpierw zebrać składniki potrzebne do sporządzenia Wody Jasnowidzenia.$B$BPotrzebne będą kamienie, które możesz znaleźć w okolicach studni w Mulgore. Połączę je z bursztynowymi nasionami, które spadają z potężnych drzew naszych ziem.$B$BTe składniki zawierają magiczne pierwiastki; uwarzone i spożyte przy plemiennym ogniu - wywołają wizję. Idź za nią, a zaprowadzi cię ona do następnego etapu tej świętej misji.",
    ["O"] = "Zbierz 2 Well Stones i 2 Ambercorn, zanieś je Zarlmanowi Two-Moons z Bloodhoof Village.",
    ["T"] = "Próba Wizji",
  },
  [772] = {
    ["D"] = "Oto jest Woda Jasnowidzenia.$B$BKiedy będziesz $ggotów:gotowa;, wypij ją przy plemiennym ogniu. Po kilku chwilach przed płomieniami zmaterializuje się wizja.$B$BOd tego momentu od ciebie będzie zależeć, czy podążysz za swoim przeznaczeniem...",
    ["O"] = "Wypij Wodę Jasnowidzenia przy plemiennym ogniu w Bloodhoof Village i podążaj za wizją, którą wywołasz.",
    ["T"] = "Próba Wizji",
  },
  [773] = {
    ["D"] = "By zyskać akceptację starszych z Thunder Bluff, musisz teraz przejść Próbę Mądrości.$B$BSkoro $gprzeszedłeś:przeszłaś; już Próbę Wizji, duchy praojców z Czerwonych Skał obdarzą cię błogosławieństwem naszych przodków. Jedynie ci, którzy pili Wodę Jasnowidzenia, mogą je otrzymać.$B$BUdaj się na wschód od Thunder Bluff, do Czerwonych Skał i odnajdź Ducha Przodka, $N.",
    ["O"] = "Udaj się do Red Rocks na wschód od Thunder Bluff i porozmawiaj z Ancestral Spirit.",
    ["T"] = "Próba Mądrości",
  },
  [774] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [775] = {
    ["D"] = "Będziesz teraz $gszanowany:szanowana; w naszym wspaniałym mieście. $gKażdy:Każda; $R $gzdolny:zdolna; przejść Próby Matki Ziemi doświadcza tego zaszczytu.$B$BOdnajdź naszego szlachetnego przywódcę, Cairne\'a Bloodhoofa, który zamieszkuje najwyższy z płaskowyżów Thunder Bluff.",
    ["O"] = "Porozmawiaj z Cairne\'em Bloodhoofem w Thunder Bluff.",
    ["T"] = "Podróż do Thunder Bluff",
  },
  [776] = {
    ["D"] = "$gPrzeszedłeś:Przeszłaś; Próby Matki Ziemi i $gzapracowałeś:zapracowałaś; na uznanie w Thunder Bluff.$B$BJednak by zachować poważanie, o które tak ciężko $gwalczyłeś:walczyłaś;, musisz wciąż dowodzić swej wartości dla swego ludu.$B$BJesteśmy myśliwymi, $N. Na łąkach Mulgore żyje potężne kodo o imieniu Arra\'chea. Dowiedź swych zdolności tropienia i polowania, przynosząc mi Róg Arra\'chei.",
    ["O"] = "Cairne Bloodhoof z Thunder Bluff chce, byś $gprzyniósł:przyniosła; mu Róg Arra\'chei.",
    ["T"] = "Próby Matki Ziemi",
  },
  [777] = {
    ["D"] = "Dobrze, proszę bardzo.$B$BBędę tutaj... za osłoną.$B$BNie krępuj się do mnie dołączyć.",
    ["O"] = "Przynieś Zębatkę nr 5 do Lotwila Veriatusa.",
    ["T"] = "To nie będzie łatwe",
  },
  [778] = {
    ["D"] = "Haha! Zrobione! Kajdany skończone!$B$BJuż czas, Lucienie. Już czas, Servo!$B$B$N, jesteś gotów być świadkiem działania perfekcyjnej mieszanki alchemii, inżynierii i magii?$B$BPrzyzwę teraz potężnego żywiołaka. Ten dzień to prawdziwy przełom dla nas wszystkich.",
    ["O"] = "Pokonaj Fam\'retor Guardiana i przynieś Lotwil\'s Shackles of Elemental Binding z powrotem do Lotwila Veriatusa.",
    ["T"] = "To nie będzie łatwe",
  },
  [779] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Pieczęć Ziemi",
  },
  [780] = {
    ["D"] = "Bojowe dziki z położonego na wschodzie Brambleblade Ravine wkraczają na tereny łowieckie naszego plemienia. Są szkolone do walki, przez kolcozwierze Najeżaki, z którymi toczymy wojnę.$B$BIdź i wyrżnij te ohydne stwory i przynieś mi trochę ich pysków i połci mięsa, byśmy mogli zrobić gulasz dla naszych młodych.",
    ["O"] = "Grull Hawkwind z Camp Narache chce, byś $gzabił:zabiła; Battleboars i $gprzyniósł:przyniosła; 8 Battleboar Snouts i 8 Battleboar Flanks.",
    ["T"] = "Bojowe dziki",
  },
  [781] = {
    ["D"] = "Po dokładnej ocenie mapy, zdajesz sobie sprawę, że $gznalazłeś:znalazłaś; plany szerokiego ataku na Obóz Narache, wykonane przez wodza Najeżaków.$B$BWódz Hawkwind z pewnością wykorzysta te informacje!",
    ["O"] = "Przynieś plany ataku Bristleback do Wodza Hawkwinda z Camp Narache.",
    ["T"] = "Atak na Obóz Narache",
  },
  [782] = {
    ["D"] = "Podczas Drugiej Wojny Blacklash i Hematus, dwaj porucznicy sprzymierzonego wówczas z nami smoka Deathwinga, zostali uwięzieni w Lethlor Ravine daleko na wschodzie. Musimy uciszyć naszych dawnych zdradzieckich sojuszników, aby przywrócić honor Hordzie!$B$BZatrudniliśmy Tho\'gruna i jego ogrzych najemników do pomocy w zdobyciu Znaku Ziemi; klucza, niezbędnego do uwolnienia smoków. Jednak Tho\'grun nas zdradził, pokonał nasze siły i przywłaszczył sobie Znak Ziemi. Idź do Camp Boff i odzyskaj go!",
    ["O"] = "Zabij Bossa Tho\'gruna i przynieś Sign of the Earth do Gorna z Kargath.",
    ["T"] = "Zerwane sojusze",
  },
  [783] = {
    ["D"] = "Mam nadzieję, że palisz się do pracy, $gmłody:młoda; $C, gdyż tu, w Northshire, jest trochę roboty do wykonania.$B$BI wcale nie mam na myśli pracy w polu.$B$BStrażnicy Stormwind mają sporo roboty z utrzymaniem tu spokoju, gdyż wielu z nas przebywa w odległych krajach, a zagrożenia są coraz bliżej. Z tego powodu zbieramy wszystkich chętnych do obrony swego domu oraz Przymierza.$B$BJeśli jesteś tutaj, aby odpowiedzieć na wezwanie, porozmawiaj z moim przełożonym, komendantem McBride\'em. Jest wewnątrz klasztoru za moimi plecami.",
    ["O"] = "Porozmawiaj z komendantem McBride.",
    ["T"] = "Wewnętrzne zagrożenie",
  },
  [784] = {
    ["D"] = "Prowadzeni przez Admirała Proudmoore\'a ludzie z Kul Tiras wtargnęli do Durotaru, łamiąc postanowienia paktu ustanowionego przed laty między wodzem a Jainą Proudmoore w celu pokonania Archimonda.$B$BInwazja ludzi została odparta, a Twierdza Tiragarde upadła. Lecz ostatnio rezerwiści Admirała, dowodzeni przez porucznika Benedicta, odbili twierdzę i po raz kolejny zagrażają naszej ojczystej ziemi. Ci ludzie dyplomację mają sobie za nic.$B$BDowiedź swego honoru udając się na południe, do Twierdzy Tiragarde, aby wyeliminować ludzkich najeźdźców.",
    ["O"] = "Zabij 10 Kul Tiras Sailors, 8 Kul Tiras Marines i Lieutenant Benedict i wróć do Gar\'Thoka z Razor Hill.",
    ["T"] = "Wytęp zdrajców",
  },
  [785] = {
    ["D"] = "Thrall jest najmądrzejszym i najszlachetniejszym przywódcą. Jego wytrwałości na polu bitwy dorównuje tylko jego takt dyplomatyczny. Trolle Mrocznej Włóczni okazały się być bezcennymi sojusznikami orków. Z lojalnością i honorem zawarliśmy pakt wzajemnej ochrony. Wódz rozkazał upewnić się, czy nasi przyjaciele z Mrocznej Włóczni w Wiosce Sen\'jin nie podlegają bezpośredniemu zagrożeniu. Jeden z naszych najbardziej zaufanych zwiadowców, Lar Prowltusk bacznie obserwuje ich zachodnią flankę. Odszukaj Lara i pomóż mu w razie potrzeby.",
    ["O"] = "Odszukaj Lara Prowltuska na zachodnim skrzydle Sen\'jin Village.",
    ["T"] = "Strategiczne przymierze",
  },
  [786] = {
    ["D"] = "Zniż głos, $C. Centaury Kolkary przebywają zaraz za grzbietem na zachodzie, na Grani Kolkarów.$B$BOstatniej nocy, gdy wyszły łupić, wkradłem się do ich wioski i odkryłem, iż te plugawe bestie mają trzystopniowy plan ataku na trolle i orków Durotaru.$B$BNie możemy pozwolić, aby zrealizowały ów plan. Może potrafisz odnaleźć w sobie odwagę potrzebną do wejścia na grań i zniszczenia planów ataku.$B$BZ tego, co widziałem, podzieliły je między trzech dowódców.",
    ["O"] = "Lar Prowltusk z Sen\'jin Village chce, abyś $gzniszczył:zniszczyła; 3 Plany Ataku przetrzymywane w Kolkar Crag.",
    ["T"] = "Zatrzymać agresję Kolkarów",
  },
  [787] = {
    ["D"] = "Throm\'ka, $C. Jestem Eltrigg, powołany przez Thralla, aby nadzorować trening rekrutów.$B$BHorda nie jest już tym, czym była niegdyś. Swego czasu opuściłem Hordę, rozczarowany rosnącym wpływem żądnych mocy sługusów Płonącego Legionu. Podczas wygnania zostałem pojmany przez grupę ludzi, jednak uratował mnie wódz. Słysząc jego wizję Hordy, wolnej od demonicznych wpływów i prowadzonej przez szamanów, powróciłem.$B$BGornek będzie miał dla ciebie dalsze instrukcje.",
    ["O"] = "Zgłoś się do Gorneka w Den.",
    ["T"] = "Nowa Horda",
  },
  [788] = {
    ["D"] = "Pierwsze zadanie ma na celu wzmocnić twoją siłę. Mógłbym od razu wysłać cię do Barrens, żebyś $gpolował:polowała; na kodo, lecz szczerze mówiąc, bardziej przydasz się $gżywy niż martwy:żywa niż martwa;.$B$BSądzę, że odpowiednim wyzwaniem dla ciebie będą cętkowane dziki, które znajdziesz na północ stąd.",
    ["O"] = "Zabij 10 Mottled Boars i wróć do Gorneka z Den.",
    ["T"] = "Ostrzenie zębów",
  },
  [789] = {
    ["D"] = "I potężni wojownicy, i niewprawni nowicjusze, ginęli od jadowitych żądeł skorpionów. Ich ogromne skupisko znajdziesz na północny zachód stąd. Dostarcz mi dziesięć ich ogonów jako dowód twej biegłości w walce.$B$BOdtrutka na ich jad jest wytwarzana właśnie z trucizny pozyskanej z żądeł. Trzymamy pod ręką spore ilości antidotum na jad skorpionów, aby pomagać młodym wilkom, takim jak ty...$B$BJestem jednak przekonany, że nie będziesz go potrzebować, mam rację?",
    ["O"] = "Zdobądź 10 Scorpid Worker Tails dla Gorneka z Den.",
    ["T"] = "Żądło skorpiona",
  },
  [790] = {
    ["D"] = "$N! Myślałem, iż umrę tutaj, a nikt się o tym nie dowie. Gdy polowałem na tutejsze skorpiony, trafiłem na jednego, który wyglądał bardziej krwiożerczo od reszty. Rzucając się na niego, zdołałem zadać potężny cios jego kleszczom, nim zbliżyły się do moich nóg.$B$BNie byłem jednak przygotowany na żądło, które wbiło mi się w pierś, przecinając mięśnie i rozpryskując krew. Proszę, zabij dla mnie tego skorpiona! Muszę zachować mój honor! Walczyłem z nim na płaskowyżu na południu.",
    ["O"] = "Zabij Sarkotha i dostarcz jego kleszcze do Hana\'zui.",
    ["T"] = "Sarkoth",
  },
  [791] = {
    ["D"] = "Wiek uczynił mnie nieprzydatnym do walki. Teraz staram się być przydatnym w innych dziedzinach.$B$BZ tego punktu obserwacyjnego wypatruję najeźdźców. Ponieważ nasza siła tutaj wzrasta, coraz rzadziej muszę dąć w róg.$B$BDla zabicia czasu wytwarzam przedmioty, aby pomóc młodszym, bardziej krzepkim wojownikom, bronić naszych ziem.$B$BMogę ci naszykować torbę na twoje rzeczy. Jeśli przyda ci się taka torba, dostarcz mi skrawki płótna; to materiał często używany przez ludzi i centaury.",
    ["O"] = "Furl Scornbrow z wieży obserwacyjnej w Razor Hill chce 8 Canvas Scraps.",
    ["T"] = "Nieś swe brzemię",
  },
  [792] = {
    ["D"] = "Ufam, że Dolina Prób sporo cię nauczy, $gmłody:młoda; $C.$B$BZostałam wysłana do doliny, aby cię prowadzić, lecz odkryłam tu rosnącą skazę...$B$BGrupa nazywająca siebie Płonącym Ostrzem założyła obóz w Dolinie Prób. Czają się w jaskini na północnym wschodzie, a ich plugawe chowańce wyłażą stamtąd, siejąc wokół spustoszenie.$B$BW ramach pierwszego starcia z Płonącym Ostrzem zlecam ci pokonanie ich chowańców. Zgładź wielu i - jeśli przeżyjesz - wróć do mnie.",
    ["O"] = "Zabij 12 Vile Familiars.$B$BWróć do Zureethy Fargaze na zewnątrz Den.",
    ["T"] = "Plugawe chowańce",
  },
  [793] = {
    ["D"] = "Pieczęć Ziemi jest utrzymywana przez trzy kamienie runiczne, przechowywane w Filarach Diamentu, Opalu i Ametystu w Parowie Lethlor. Używając Znaku Ziemi, będziesz w stanie usunąć kamienie i złamać Pieczęć Ziemi.$B$BUważaj jednak, $N, Blacklash i Hemantus nie są czarnymi smokami, które można lekceważyć. Zabij je i zwróć mi ich kajdany.$B$BAby dotrzeć do parowu, udaj się do położonej najbardziej na wschód części Badlands. Bądź ostrożny, w parowie żyje niezliczona ilość smoków.",
    ["O"] = "Użyj Znaku Ziemi do aktywacji Filaru Diamentu, Opalu i Ametystu, i zdobądź Kamienie Runiczne.$B$BUmieść kamienie runiczne w Pieczęci Ziemi, by uwolnić Blacklasha i Hematusa.$B$BZgładź ich i zwróć Gornowi Blacklash\'s Bindings, Chains of Hematus i Znak Ziemi.",
    ["T"] = "Zerwane sojusze",
  },
  [794] = {
    ["D"] = "Moje zaklęcia wskazują, iż jakiś przedmiot o potężnej mocy znajduje się w głębi sabatu Płonącego Ostrza, chroniony przez bestie i czarną magię.$B$BTo medalion Płonącego Ostrza, a twym następnym zadaniem będzie odnalezienie go i wyniesienie z jaskini.$B$BLecz strzeż się, medalion może być w posiadaniu jednego z członków klanu, a jego moc będzie o wiele większa niż chowańców, z którymi do tej pory $gwalczyłeś:walczyłaś;.$B$BRuszaj, $N. Jaskinię znajdziesz na północnym zachodzie.",
    ["O"] = "Przynieś Burning Blade Medallion do Zureethy Fargaze na zewnątrz Den.",
    ["T"] = "Medalion Płonącego Ostrza",
  },
  [795] = {
    ["D"] = "",
    ["O"] = "Pieczęć Ziemi spoczywa tutaj wraz z trzema zagłębieniami przeznaczonymi na Ametystowy Kamień Runiczny, Opalowy Kamień Runiczny oraz Diamentowy Kamień Runiczny.",
    ["T"] = "Pieczęć Ziemi",
  },
  [796] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [797] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [798] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [799] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [800] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [801] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [802] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [803] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [804] = {
    ["D"] = "Twój uczynek podniósł mnie na duchu. Nie poddam się tak łatwo! Wytrzymam!$B$BNiestety, nie jestem na siłach, aby samodzielnie wrócić do Leża. Proszę, $N, wróć tam i poinformuj Gorneka o mojej sytuacji. Może on będzie w stanie mi pomóc.",
    ["O"] = "Donieś Gornekowi z Den o położeniu Hana\'zui.",
    ["T"] = "Sarkoth",
  },
  [805] = {
    ["D"] = "Twe działania przeciwko Płonącemu Ostrzu zostały zakończone... tutaj, w dolinie. Jednakże chcę, abyś $gdoniósł:doniosła; komuś o swoich odkryciach.$B$BUdaj się do trollowej wioski Sen\'jin i odnajdź mistrza Gadrina. Aby dojść do wioski, wydostań się z doliny na wschód, a następnie skręć w prawo na rozwidleniu.$B$BPowiedz Gadrinowi o Płonącym Ostrzu oraz o tym, że dotarło do Doliny Prób. Dowiedz się od niego, czy jest już i w Sen\'jin.$B$BRuszaj, $N, i spiesz się. Obawiam się, iż zło odnalezione w sabacie Płonącego Ostrza jest zwiastunem poważniejszego zagrożenia...",
    ["O"] = "Porozmawiaj z mistrzem Gadrinem w Sen\'jin Village.",
    ["T"] = "Zgłoś się do Wioski Sen\'jin",
  },
  [806] = {
    ["D"] = "Nie możemy pozwolić, by klan Płonącego Ostrza posiadał przyczółek w Durotarze! Musimy ich zniszczyć, nim rozpanoszą zło!$B$BPrzeprowadziłem własne śledztwo w tej sprawie i dowiedziałem się, że czarnoksiężnik Płonącego Ostrza, goblin Fizzle Darkstorm, rozbił obóz wewnątrz Grani Gromu na północnym zachodzie. Stamtąd wraz ze swymi kultystami rozprzestrzenia chaos.$B$BZnajdź i pokonaj Fizzle\'a, i przynieś mi jego pazur!",
    ["O"] = "Przynieś Fizzle\'s Claw do Orgnila Soulscara w Razor Hill.",
    ["T"] = "Ciemne burze",
  },
  [808] = {
    ["D"] = "Słyszę głos mego brata, Minshiny, wołający mnie w snach.$B$BMinshina został porwany przez Zalazane\'a, czarnoksiężnika z Wysp Echa na wschodzie. I jest martwy.$B$BLecz śmierć nie dała mu wolności. Magia Zalazane\'a uwięziła duszę Minshiny w jego własnej czaszce. W moich snach widziałem ją wśród innych czaszek, w kręgu mocy na największej z Wysp Echa. Jak długo tam pozostaje, dusza mojego brata jest skazana na zgubę.$B$B$N, błagam. Znajdź krąg i odzyskaj czaszkę Minshiny. Przynieś ją do mnie.$B$BUwolnij go!",
    ["O"] = "Odzyskaj Czaszkę Minshiny z kręgu mocy w Echo Isles.$B$BPrzynieś ją mistrzowi Gadrinowi z Sen\'jin Village.",
    ["T"] = "Czaszka Minshiny",
  },
  [809] = {
    ["D"] = "Od czasu ostatniej wielkiej wojny, zakończonej porażką Płonącego Legionu, szukałem źródeł demonicznego skażenia w społeczeństwie orków. Naszyjnik, który mi $gprzyniosłeś:przyniosłaś;, potwierdza moje obawy.$B$BNależy do Płonącego Ostrza, kultu, który gromadzi się wokół przedmiotu o demonicznej mocy. Zwie się go Demonicznym Nasionem, a znajduje się on w Barrens, na szczycie Dreadmist Peak. Musi zostać zniszczony!$B$BIdź na zachód, do Posterunku Obserwacyjnego na granicy Barrens, i porozmawiaj z moim asystentem, Ak\'Zelothem. Pokieruje cię dalej.",
    ["O"] = "Porozmawiaj z Ak\'Zelothem w Barrens.",
    ["T"] = "Ak\'Zeloth",
  },
  [810] = {
    ["D"] = "You would do well to learn how dangerous this land can be, $c.$B$BThe wildlife here can teach us such things... if we are wise and observant.$B$BThe scorpids are a perfect example of survival in Durotar. If you are to survive, it would be wise to take on some of their characteristics as your own. Their hardened carapaces can protect you from the harshness of the sun, or even a deadly weapon.$B$BBring me 6 Small Scorpid Carapaces from the Clattering Scorpids, $N, and I shall see about rewarding you justly.",
    ["O"] = "Bring 6 Small Scorpid Carapaces to Kor\'ghan in Sen\'jin Village.",
    ["T"] = "<UNUSED>",
  },
  [811] = {
    ["D"] = "One of the other traits of the scorpids is their fierce loyalty. They will protect one another if they are in danger--you\'ve probably already seen this behavior in your first scorpid hunt.$B$BYou would do well to heed that lesson and adapt it for yourself: we are stronger as one; we are weak when we are divided into many.$B$BBring me 8 Large Scorpid Carapaces from the Armored Scorpids and I shall reward you for learning this wisdom.",
    ["O"] = "Bring 8 Large Scorpid Carapaces to Kor\'ghan in Sen\'jin Village.",
    ["T"] = "<UNUSED>",
  },
  [812] = {
    ["D"] = "$N... twoje wyczucie czasu jest doskonałe. Mam nadzieję, że będę mógł pochwalić także twój pośpiech.$B$BWalcząc z okolicznymi skorpionami, byłem niedostatecznie ostrożny i jeden z nich głęboko mnie użądlił. Czuję, jak trucizna osłabia mnie, nawet podczas naszej rozmowy. W takim tempie została mi może godzina życia. Aby przeżyć będę potrzebował twojej pomocy...$B$BKor\'ghan z Orgrimmaru wie, jak przyrządzić antidotum. Znajdź go... i pośpiesz się, $N. Nie zdołam wiele dłużej wytrzymać. Kor\'ghan powinien być w Szczelinie Cienia.",
    ["O"] = "Znajdź Kor\'ghana w Orgrimmarze i zdobądź Venomtail Antidote. Następnie przynieś antidotum do Rhinaga niedaleko północno-zachodniej granicy Durotaru.",
    ["T"] = "Zapotrzebowanie na lek",
  },
  [813] = {
    ["D"] = "Jadogony są jednymi z najbardziej śmiercionośnych skorpionów w Durotarze. Rhinag źle uczynił, polując na nie bez antidotum, ale besztanie go teraz jest ostatnią rzeczą, jakiej mu potrzeba.$B$BPrzynieś mi kilka woreczków jadowych z jakichkolwiek skorpionów zamieszkujących niedaleko wejścia do Orgrimmaru, a przyrządzę antidotum.$B$BPośpiesz się, $N. Jeden z naszych potrzebuje twojej pomocy.",
    ["O"] = "Przynieś 4 Venomtail Poison Sacs do Kor\'ghana z Orgrimmaru.",
    ["T"] = "Poszukiwanie antidotum",
  },
  [814] = {
    ["D"] = "Cook and clean--that\'s all I do!$B$BYou want to eat, you get me some more meat! I don\'t have all day to hunt and prepare food for all these louses. You got to learn to pull your own weight around here if you wanna be treated equal.$B$BGet me some Chunks of Boar Meat if you want to make yourself useful... or you don\'t want to starve to death.",
    ["O"] = "Bring 10 Chunks of Boar Meat to Cook Torka in Razor Hill.",
    ["T"] = "<UNUSED>",
  },
  [815] = {
    ["D"] = "Bah! Prawie zapomniałem, że muszę przygotować śniadanie.$B$B$N, rusz się i przynieś mi kilka jaj biczogonów. Potrzebuję co najmniej trzech sztuk, jeśli ma mi starczyć na jutrzejszy posiłek.$B$BBiczogony krwistoszponne są zajadłe i gotowe do ochrony swych jaj za cenę życia. Czasami zagrzebują je zbyt głęboko pod ziemią, by dało się je bezpiecznie odsłonić, ale jeśli dostaniesz się na Wyspy Echa, na południowy wschód od Wioski Sen\'jin, znajdziesz je na każdej z nich.",
    ["O"] = "Przynieś 3 Taillasher Eggs do kucharza Torki z Razor Hill.",
    ["T"] = "Zbij kilka jaj",
  },
  [816] = {
    ["D"] = "$N, proszę, możesz mi pomóc? Mój syn Kron poszedł kilka dni temu na polowanie i jeszcze nie wrócił. Wybrał się na zachód, w stronę Barrens, by zapolować na krokodyle wzdłuż rzeki Północnej Furii. Obawiam się najgorszego.$B$BJego uparta duma, równie silna jak on, zawsze pakowała go w kłopoty. Ostrzegałam go, że krokodyle są potężne i podstępne. Zezłościł się i wybiegł.$B$BJeśli nie będziesz $gmógł:mogła; go znaleźć, przynieś mi choć znak jego losu... nawet jeśli będziesz $gmusiał:musiała; rozedrzeć brzuch każdego krokodyla z brzegów rzeki Północnej Furii.",
    ["O"] = "Przynieś znak losu Krona do Mishy Tor\'kren z farmy na północny zachód od Razor Hill.",
    ["T"] = "Zaginiony, ale nie zapomniany",
  },
  [817] = {
    ["D"] = "Wiele skór, których używamy, $N, pochodzi od tygrysów z Durotaru. Koce, pancerze, namioty: to przyczyny, dla których polujemy na bestie, a jednocześnie pozwalamy im się rozmnażać.$B$BPrzyszedł czas by przetrzebić ich stado, pomówmy więc. Nasza liczba wzrasta, a potrzeby zaczynają przerastać zapasy. Potrzebuję więcej skór, jeśli mam przygotować stosowne towary dla naszych ludzi.$B$BPrzynieś mi cztery futra tygrysów z Durotaru, a wynagrodzę cię. Zwierzęta znajdziesz na wyspach na południe stąd.",
    ["O"] = "Przynieś 4 Durotar Tiger Furs do Vel\'rina Fanga w Sen\'jin Village.",
    ["T"] = "Praktyczna zdobycz",
  },
  [818] = {
    ["D"] = "Choć oczy czasem mnie już zawodzą, wciąż widzę dostatecznie wyraźnie. Częściej muszę tylko polegać na moich umiejętnościach alchemika, by wspomóc się w czarach, które niegdyś łatwo mi przychodziły. Ale odmawiam przyjęcia ucznia - żaden dostatecznie godzien troll lub ork się jeszcze nie znalazł.$B$BTy jesteś $ggodzien:godna;? Tak, oczywiście jesteś... oczywiście myślisz, że jesteś.$B$BPotrzebuję kilku rzeczy. Zdobędziesz je dla mnie?$B$BPotrzebuję nienaruszonych oczu makrur i fiolek śluzu pełzaków. Zapewni ci je każda makrura czy pełzak w Durotarze. Wkrótce pomówimy ponownie.",
    ["O"] = "Przynieś 4 Intact Makrura Eyes i 8 fiolek Crawler Mucus do mistrza Vornala w Sen\'jin Village.",
    ["T"] = "Wypłacalny duch",
  },
  [819] = {
    ["D"] = "Niewielki napis umieszczony na denku beczki mówi:$B$B\"Chen Stormstout-$B$BNiech twój duch wzniesie się i zawsze podnosi cię na duchu.\"",
    ["O"] = "Znajdź kogoś, kto wie cokolwiek o Chen\'s Empty Keg.",
    ["T"] = "Pusta beczka Chena",
  },
  [821] = {
    ["D"] = "$gChciałbyś:Chciałabyś; spróbować imiennika Chena? Achh, grzmocący porter jest mocnym trunkiem. Chen nauczył przepisu mojego mentora, a on przekazał go mnie. Chcę, byś $gprzyniósł:przyniosła; mi kilka rzeczy, ale powiem ci jedno: cel jest wart środków.$B$BPrzynieś mi 5 kłów lwów z sawanny, 5 nerek jakiegokolwiek stepochodźca i 1 róg z dowolnego gatunku jaszczura grzmotów. To powinno załatwić sprawę.$B$BZnajdziesz te składniki na obszarze Barrens.",
    ["O"] = "Przynieś 5 Savannah Lion Tusks, 5 Plainstrider Kidneys i 1 Thunder Lizard Horn do piwowara Drohna z Ratchet.",
    ["T"] = "Pusta beczka Chena",
  },
  [822] = {
    ["D"] = "Dobra rzecz ten grzmocący porter, nie?$B$BMam jeszcze jeden przepis, którego nauczyłem się od Chena. Jesteś $gzainteresowany:zainteresowana;? Jego przygotowanie nie zajmie dużo czasu, a może się przydać, jeśli planujesz dalsze przygody.$B$BPrzynieś mi 5 błyskających gruczołów z dowolnego grzmotoskóra, 1 gruczoł ślinowy z większego jastrzębia grzmotów i 1 wątrobę dowolnego kodo z Barrens.$B$BJak mówiłem, napój ma kopa; to troggowe piwo, o którym ci wcześniej wspomniałem.",
    ["O"] = "Przynieś 5 Lightning Glands, 1 Thunderhawk Saliva Gland i 1 Kodo Liver do piwowara Drohna w Ratchet.",
    ["T"] = "Pusta beczka Chena",
  },
  [823] = {
    ["D"] = "My, mieszkańcy Wioski Sen\'jin, mamy własne problemy i dziękujemy ci za twoją pomoc. Ale wiadomości, które $gzdobyłeś:zdobyłaś;, obserwując Płonące Ostrze, oznaczają kłopoty dla wszystkich.$B$BW Razor Hill stacjonuje ork, Orgnil Soulscar, który chroni Durotar przed złem takim jak Płonące Ostrze! Idź do Orgnila i przedstaw mu nasze położenie oraz wieści, które udało ci się zebrać w Dolinie Prób. Będzie chciał je poznać.$B$BRazor Hill leży na północ stąd.",
    ["O"] = "Porozmawiaj z Orgnilem Soulscarem w Razor Hill.",
    ["T"] = "Raport dla Orgnila",
  },
  [824] = {
    ["D"] = "Krąg Ziemi to szamańska grupa poświęcająca się badaniu i ochronie żywiołaków. Zdążyli zapomnieć więcej rzeczy o szalonych pradawnych bogach, starożytnych legendach i tradycjach niż większość uczonych kiedykolwiek się dowie.$B$BNa szczęście dla ciebie znam kogoś z Kręgu Ziemi tutaj, w Ashenvale. Udaj się do Posterunku Zoram\'gar w Zoram Strand; pokaż Je\'neu Sancrei to, co $gznalazłeś:znalazłaś;. Jeśli ktoś potrafi odgadnąć znaczenie tej kuli, będzie to on.",
    ["O"] = "Zanieś Befouled Water Globe do Je\'neu Sancrei z Zoram\'gar Outpost w zachodnim Ashenvale.",
    ["T"] = "Je\'neu z Kręgu Ziemi",
  },
  [825] = {
    ["D"] = "Jeden z moich zwiadowców doniósł, że wrak z floty Proudmoore\'a wciąż spoczywa na wybrzeżu Durotaru, na wschód od Twierdzy Tiragarde.$B$BNie jest tajemnicą, że ludzie sprzymierzeni z tymi głupimi, małymi stworzeniami zwanymi gnomami, dysponują zaawansowaną wiedzą na temat mechaniki. Musimy w pełni zrozumieć wszystkich naszych potencjalnych wrogów. A nasz lud także będzie czerpać korzyści z tej wiedzy.$B$BPopłyń do wraku, $N, i dostarcz mi narzędzia Przymierza.",
    ["O"] = "Gar\'Thok z Razor Hill chce, byś $gprzyniósł:przyniosła; mu 3 zestawy Gnomish Tools z wraków statków na wybrzeżu.",
    ["T"] = "Z wraku...",
  },
  [826] = {
    ["D"] = "Znachor Zalazane przebywa na Wyspach Echa na wschodzie. Wyspy te niegdyś nazywaliśmy domem.$B$BStamtąd wysyła on swe trolle na suchy ląd, gdzie te rzucają uroki na naszych ludzi, by mógł on przejąć nad nimi kontrolę.$B$BZalazane musi zostać powstrzymany.$B$BPokonaj Zalazane\'a i jego sługusów - dawne trolle z klanu Mrocznych Włóczni, już dla nas stracone. Przynieś mi jego głowę, a będę wiedział, iż nadszedł kres jego rządów zła.",
    ["O"] = "Pokonaj Zalazane\'a.$B$BZabij 8 Voodoo Trolls i 8 Hexed Trolls.$B$BPrzynieś Gadrinowi głowę Zalazane\'a.",
    ["T"] = "Zalazane",
  },
  [827] = {
    ["D"] = "$N. Płonące Ostrze zatruło jaskinię na wschód od Orgrimmaru znaną jako Skała Czaszki. Wewnątrz jaskini jego kultyści odprawiają ohydne obrzędy i palącymi obrożami przypalają własne ciała.$B$BWydaje mi się, że nosząc te obroże, kultyści zestrajają się z demoniczną mocą. Nie mam na to dowodu, dlatego muszę je zbadać.$B$BUdaj się do jaskini i zabierz obroże kultystom, których tam spotkasz. Dostarcz mi je, a odkryję ich tajemnicę.",
    ["O"] = "Zgromadź Searing Collars z kultystów w Skull Rock.$B$BDostarcz je Margozowi w jego obozowisku.",
    ["T"] = "Skała Czaszki",
  },
  [828] = {
    ["D"] = "Jeden z naszych szamanów, Margoz, wie więcej na temat plagi Płonącego Ostrza. Wspominał o Skale Czaszki: jaskini w górach - tuż obok Orgrimmaru! - która daje schronienie sporej grupie kultystów Płonącego Ostrza.$B$BZanim się tam udasz, porozmawiaj z Margozem. Jest mądry, a jego rady są cenne.$B$BObozuje on na północnym wschodzie, między wybrzeżem a wąwozem Wyschniętego Strumienia.$B$BSkorzystaj z jego rady, lecz cokolwiek rzeknie, wciąż pragnę, byś $gzmiażdżył:zmiażdżyła; tych kultystów!",
    ["O"] = "Porozmawiaj z Margozem.",
    ["T"] = "Margoz",
  },
  [829] = {
    ["D"] = "Obroże, które mi $gprzyniosłeś:przyniosłaś;, są potężnym demonicznym narzędziem. Obawiam się, że poznanie ich pochodzenia wykracza poza moje szamańskie umiejętności. Potrzebujemy czarnoksiężnika, aby je głębiej zbadać.$B$BZabierz palącą obrożę do Neeru Fireblade\'a. Chociaż jest on utalentowanym czarnoksiężnikiem, specjalizuje się w zwalczaniu sił demonicznych i twierdzi, że jego badania nad okultyzmem są niegroźne. Prawda to czy nie, potrzebujemy jego pomocy w walce z demonicznym kultem w Durotarze.$B$BNeeru można znaleźć w Orgrimmarze, wewnątrz Szczeliny Cienia.",
    ["O"] = "Przynieś Example Collar do Neeru Fireblade w Orgrimmarze.",
    ["T"] = "Neeru Fireblade",
  },
  [830] = {
    ["D"] = "Otwierasz wiekową, podniszczoną kopertę i odkrywasz oficjalnie wyglądający dokument. Rozpoznajesz pieczęć Admirała Proudmoore\'a.$B$BWygląda to na coś ważnego. Być może Gar\'Thok, dowódca z Razor Hill byłby zainteresowany tymi informacjami.",
    ["O"] = "Zabierz Rozkazy Admirała Proudmoore\'a do Gar\'Thoka w Razor Hill.",
    ["T"] = "Rozkazy Admirała",
  },
  [831] = {
    ["D"] = "Ludziom nie można ufać. Walczyliśmy po jednej stronie z ciężkim sercem, wiedząc, że i tak pewnego dnia zostaniemy zdradzeni.$B$BŚmierć Admirała nie wystarczyła, aby powstrzymać fałsz, który zapoczątkował. Ta szumowina dobrze wszystko zaplanowała, nim spotkała się ze śmiercią.$B$BWygląda na to, że jego panowanie nie skończy się nawet z odejściem Benedicta. Kto wie, ile czasu upłynie, zanim następna fala ludzi Proudmoore\'a zaleje nasze wybrzeża.$B$BMusimy natychmiast dostarczyć te rozkazy do Nazgrela, do Orgrimmaru! Można go spotkać w komnacie Thralla.",
    ["O"] = "Dostarcz Rozkazy Admirała Proudmoore\'a do Nazgrela w komnacie Thralla w Orgrimmarze.",
    ["T"] = "Rozkazy Admirała",
  },
  [832] = {
    ["D"] = "<W swych myślach słyszysz dobywające się z wisiora słowa.>$B$BGazz\'uz?$B$BGazz\'uz... zgłoś się!$B$BMówi się o twych odkryciach w Skale Czaszki. Musisz przygotować się na atak!$B$BGazz\'uz, nakazuję ci mówić! Odpowiadaj albo sprawię, że Neeru Fireblade dowie się o twej obecności i rychło wymierzy ci cios.$B$BNie próbuj przeciwstawiać się potędze Neeru...$B$B...Gazz\'uz, jesteś tam...?",
    ["O"] = "Zabierz to oko do Neeru Fireblade\'a.",
    ["T"] = "Płonące cienie",
  },
  [833] = {
    ["D"] = "Jedynie najmężniejsi taureni spoczywają w Czerwonych Skałach, naszym świętym cmentarzysku. Jest to zaszczyt przyznawany wielkim wojownikom, którzy pomogli zbudować i bronić Thunder Bluff, oraz tym, którzy oddali życie dla dobra swych plemion i wodzów.$B$BLecz plugastwo utorowało sobie drogę do naszych świętych ziem. Wataha kolcozwierzy pustoszy miejsca pochówku, ja zaś swe najlepsze lata mam już za sobą i nie mogę ich przegonić.$B$BMuszą być przepędzeni siłą, $N.",
    ["O"] = "Wiedziciel Raintotem chce, abyś $gzabił:zabiła; 8 Bristleback Interlopers z Red Rocks.",
    ["T"] = "Święty pochówek",
  },
  [834] = {
    ["D"] = "Jestem Rezlak, jeden z chłopaków Gazlowa. Szef wysłał mnie, by pomóc orkom tutaj w Durotarze. Wszystko szłoby jak po maśle, gdyby nie te wozy. Nie daję rady zapewnić im bezpieczeństwa! Znacznie utrudnia mi to pracę, wiesz?$B$BOstatnia dostawa - obiecali, że dojedzie! - została zagrabiona przez harpie z... gdzie to było... Kanionu Tnącego Wiatru?$B$BMuszę mieć te zapasy, inaczej nigdy niczego nie skończę! Udaj się dużym kanionem na południe, a znajdziesz wąwóz wcinający się dokładnie we wschodnią i zachodnią stronę ścian.",
    ["O"] = "Odzyskaj 5 paczek z zapasami i przynieś je Rezlakowi niedaleko Orgrimmaru.",
    ["T"] = "Wiatry pustyni",
  },
  [835] = {
    ["D"] = "Gazlowe powiedział mi kiedyś: \"Rezlak. Jest jedna rzecz, którą musisz wiedzieć o życiu: jeśli chcesz coś zrobić dobrze, zrób to sam.\"$B$BNie mogę ścierpieć straty wszystkich wozów dostawczych, dlatego wezmę sprawy we własne ręce. Wąwóz Wyschniętego Strumienia przecina wschodni Kanion Tnącego Wiatru. Jeśli zabijemy wszystkie tamtejsze harpie, szlaki będą bezpieczne.$B$BOczywiście, była jeszcze jedna rzecz, której nauczył mnie Gazlowe, a brzmiała: \"Wszystko można kupić.\" To jak, $N, pomożesz mi?",
    ["O"] = "Zabij 12 Dustwind Savages i 8 Dustwind Storm Witches na polecenie Rezlaka z okolic Drygulch Ravine.",
    ["T"] = "Zabezpieczając szlaki",
  },
  [836] = {
    ["D"] = "Gnomi głos ponownie wydobywa się z robota:$B$B\"Należy przenieść OOX-09-OS na otwarte, bezpieczne miejsce, aby mógł rozpocząć długą procedurę startową. Ma wbudowany zegar, lecz potrzebuję czasu, by sprawić, by znów działał. Odeskortuj robota z jego obecnego miejsca do, powiedzmy, linii brzegowej pod klifem Overlook! To powinno być idealne miejsce, a trasa zajmie dostatecznie dużo czasu, aby uruchomić procedurę startową!\"$B$B\"Odprowadź robota bezpiecznie do brzegu, a następnie przyjdź porozmawiać ze mną w Booty Bay! Oglethorpe Obnoticus – bez odbioru!\"",
    ["O"] = "Odprowadź OOX-09-OS do linii brzegowej pod klifem Overlook, następnie zgłoś się do Oglethorpe\'a Obnoticusa w Booty Bay.",
    ["T"] = "Ratunek dla OOX-09-OS!",
  },
  [837] = {
    ["D"] = "Gdy przybyliśmy, Brzytwowłose kolcozwierze władały znaczną częścią tych ziem i okazały się ciężkim orzechem do zgryzienia. Dzięki naszemu wysiłkowi udało się znacznie ograniczyć ich liczbę, lecz wciąż pozostają dobrze ufortyfikowane w niektórych miejscach.$B$BTo trwa już jednak zbyt długo. Dla własnego bezpieczeństwa nie możemy pozwolić na żadne umocnienia Brzytwowłosych na naszych ziemiach. Ich obozowiska znajdują się na zachód stąd. Rozejrzyj się za krzewami cierni, a znajdziesz je. Dzisiaj wypędzimy je z Durotaru, jutro być może z całego Kalimdoru.",
    ["O"] = "Zabij 4 Razormane Quilboars, 4 Razormane Scouts, 4 Razormane Dustrunners i 4 Razormane Battleguards dla Gar\'Thoka z Razor Hill.",
    ["T"] = "Wtargnięcie",
  },
  [838] = {
    ["D"] = "Na wyspie Caer Darrow leży Scholomance – szkoła służąca za warownię dla Plagi. Nasz wróg przebywa wewnątrz, bezpiecznie prowadząc badania wzmacniające jego siłę. Drzwi blokują przejście, a ich pokonanie okazuje się niemożliwe bez odpowiedniego klucza.$B$BAptekarz Dithers posiada rozległą wiedzę na temat Scholomance oraz zna sposób na zdobycie klucza. Dowiodłeś swej wartości, jako kogoś, kto potrafi wszystko załatwić; teraz powierzam ci to zadanie. Porozmawiaj z nim o tej sprawie.",
    ["O"] = "Porozmawiaj z Apotekarzem Dithers w Bulwark, Western Plaguelands.",
    ["T"] = "Scholomance",
  },
  [839] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [840] = {
    ["D"] = "Hmm, wyglądasz na całkiem $gsilnego:silną;.$B$BPosłuchaj, mój dobry przyjaciel Kargal potrzebuje nowych rekrutów do służby w Barrens. Wiem, że chcesz robić to, co dobre dla Hordy. Oto nadchodzi szansa.$B$BWeź ten list rekrutacyjny do Kargala i spytaj, czy go podpisze.",
    ["O"] = "Udaj się drogą na zachód od Razor Hill, by przez most dotrzeć na Barrens.$B$BZatrzymaj się za mostem, przy placówce orków.$B$BPrzekaż Kargalowi Bettlescarowi w placówce w Barrens swój list rekrutacyjny.",
    ["T"] = "Poborowy Hordy",
  },
  [841] = {
    ["D"] = "Niech zgadnę – nie zdążyłeś wykonać swych złowieszczych, prowadzących do zagłady świata czynów na czas. Nie, czekaj, lepiej... utopiłeś je w piasku tej pustyni! Tak więc, jakikolwiek był tego powód, mam dodatkowe źródła energii, które mogę ci sprzedać. Jednakże tym razem będzie cię to kosztować dziesięć, TAK, DZIESIĘĆ Bukłaków Włóczęgów!$B$BCzasy są ciężkie, Jah, a źródła energii nie rosną na drzewach! Hmm, a co by było, gdyby rosły. Może dałoby się ZASADZIĆ odpowiednią sadzonkę...",
    ["O"] = "Przynieś 10 Wastewander Water Pouches do Chief Engineera Bilgewhizzle\'a w Gadgetzanie w zamian za następne źródło energii.",
    ["T"] = "Kolejne źródło energii?",
  },
  [842] = {
    ["D"] = "Zabierz ten podpisany list rekrutacyjny do Crossroads.$B$BDowodzi tam Sergra Darkthorn, niech ją szlag. Jest wredną szamanką, która zanudzi cię na śmierć, zanim pozwoli zrobić ci coś użytecznego. Thrall jest przekonany, że ona jest kimś specjalnym, ale ja nie jestem tego taki pewien.$B$B$gSam:Sama; zdecydujesz, co o tym myśleć, szczeniaku...",
    ["O"] = "Udaj się drogą na zachód z Kargal\'s Far Watch Outpost.$B$BNa skrzyżowaniu w kształcie litery \"T\" skręć w lewo i idź drogą na południe.$B$BZnajdź Sergrę Darkthorn na przecięciu traktów w Crossroads.",
    ["T"] = "Rekrutacja do Rozdroży",
  },
  [843] = {
    ["D"] = "Samotnie wędruję po tych drogach.$B$BKrasnoludy z Bael Modan nie znają szacunku dla mych ziem. Straszliwe wybuchy żłobią w ziemi głębokie doły, a hałaśliwe maszyny rozrywają wzgórza na strzępy. Niegdyś będące domem i żywicielem mego plemienia ziemie roją się teraz od niszczycielskich krasnoludów.$B$BPróby rozwiązania problemu drogą dyplomacji zawiodły. Nadszedł czas na rozstrzygające posunięcie.$B$BUżyj siły, by pozbyć się krasnoludów z wykopalisk Bael Modan i przynieś mi dziennik ich przywódcy, poszukiwacza Khazgorma.",
    ["O"] = "Gann Stonespire chce, żebyś $gzabił:zabiła; 15 Bael\'dun Excavators i 5 Bael\'dun Foremen.$B$BPrzynieś Dziennik Khazgorma do Ganna Stonespire\'a.",
    ["T"] = "Odzyskanie ziemi Ganna",
  },
  [844] = {
    ["D"] = "Twoja pierwsza zwierzyna będzie łatwa do zabicia.$B$BStepochodźce ze wschodu atakują nasze dostawy żywności, co zaczyna stanowić problem.$B$BWybij je i wróć do mnie z ich dziobami.",
    ["O"] = "Zbierz 7 Plainstrider Beaks i przekaż je Sergrze Darkthorn z Crossroads.",
    ["T"] = "Groźba stepochodźców",
  },
  [845] = {
    ["D"] = "Choć zebry nie są najwaleczniejszymi zwierzętami w Barrens, są jednak nieco silniejsze niż stepochodźce. Bez obaw - w swoim czasie zapolujesz na poważniejszą zwierzynę, ale teraz twoim zębom przydałoby się małe przypiłowanie.$B$BZapoluj na zebry z północy i południa i zbierz ich kopyta. Przynieś mi je, a może następnym razem wyślę cię przeciw groźniejszej bestii.",
    ["O"] = "Zabijając Zhevra Runners, zbierz 4 Zhevra Hooves dla Sergry Darkthorn z Crossroads.",
    ["T"] = "Zebry",
  },
  [846] = {
    ["D"] = "Jasnym jest, że poszukiwacze używają ładunków wybuchowych i tych głośnych maszyn do rozrywania ziemi. W niedługim czasie możemy się spodziewać przybycia nowego majstra.$B$BChcę, żeby krasnoludy posmakowały własnych środków. Wedle tych planów, mieszając nitroglicerynę z miazgą drzewną i azotanem sodu, uzyskamy ładunek wybuchowy. Ich zapasy posiadają strzelcy, żołnierze i oficerowie z Twierdzy.$B$BZdobądź te przedmioty i przynieś mi je. Stworzę ładunek, którego krasnoludy nigdy nie zapomną!",
    ["O"] = "Gann Stonespire chce, żebyś $gprzyniósł:przyniosła; mu 6 fiolek Nitroglycerin, 6 paczek Wood Pulp i 6 próbek Sodium Nitrate.",
    ["T"] = "Zemsta Ganna",
  },
  [847] = {
    ["D"] = "Ta... ta moc... to jest ta moc szamanów, którą Tor\'gan próbował mi pokazać? Muszę przyznać, że to interesujące. Powiedz Tor\'ganowi, że mnie przekonał... na razie. Wysłucham tego, co ma mi do powiedzenia.",
    ["O"] = "Porozmawiaj z Tor\'ganem w Arathi Highlands.",
    ["T"] = "Chytrość jaszczura",
  },
  [848] = {
    ["D"] = "Oazy Barrens kryją tajemnicę. Ich wody dają życiową energię, wzmacniając czerpiące z nich zwierzęta i rośliny.$B$BWzmacniają i zmieniają.$B$BIstnieje pewien rodzaj grzyba rosnący w oazach. Jego zarodniki mają właściwości, które my, aptekarze z Lordaeronu, uważamy za użyteczne.$B$BPrzynieś mi te zarodniki, a zyskasz naszą wdzięczność.",
    ["O"] = "Przynieś 4 Fungal Spores do aptekarza Helbrima z Crossroads.",
    ["T"] = "Zarodniki grzybów",
  },
  [849] = {
    ["D"] = "Korzystając z planów Khazgorma, nie powinienem mieć problemu ze zrobieniem ładunku wybuchowego.$B$BAch, proszę bardzo.$B$BTeraz, Thumedan, powierzę ci specjalne zadanie. Weź ten ładunek wybuchowy i użyj go do wysadzenia latającej machiny z Bael Modan.$B$BLatająca machina jest nie tylko kluczową częścią infrastruktury wykopaliska, ale służy też jako broń. Co więcej, jest symbolem potęgi i obrazą pamięci mego plemienia.$B$BPrzyspórz mi dumy, dokonując tego heroicznego czynu, a zostaniesz $gnagrodzony:nagrodzona;.",
    ["O"] = "Zniszcz latającą machinę z Bael Modan i wróć do Ganna Stonespire\'a.",
    ["T"] = "Zemsta Ganna",
  },
  [850] = {
    ["D"] = "Centaury dręczyły taurenów przez lata. A niedawno realnym zagrożeniem stały się centaury z plemienia Kolkar z Barrens. Zwykle w ich szeregach w tej krainie panował chaos, ale wyodrębnili się w nich nowi przywódcy, którzy ich zjednoczyli.$B$BBy nasze tutejsze siedziby pozostały bezpieczne, ci przywódcy centaurów muszą umrzeć.$B$BPrzynieś mi głowę Baraka Kodobane\'a. Obozuje on w pobliżu leżących na północ stąd Zapomnianych Sadzawek.$B$BPokonaj go, a potem wróć do mnie.",
    ["O"] = "Przynieś głowę Baraka do Regthara Deathgate\'a, na zachód od Crossroads.",
    ["T"] = "Przywódcy Kolkarów",
  },
  [851] = {
    ["D"] = "Centaur Verog Derwisz wędruje po Barrens i niełatwo będzie go odnaleźć. Ale jego siedziba znajduje się w namiocie dowódcy centaurów przy Oazie Stojących Wód na południowy wschód stąd. Możliwe, że uda ci się go zwabić.$B$BUdaj się do oazy na południowy wschód stąd i zaatakuj centaury w pobliżu namiotu dowodzenia. To będzie niebezpieczne, ale jeśli zabijesz ich wystarczająco dużo, powinny podnieść alarm. I Verog nadejdzie.$B$BPrzynieś mi jego głowę, a ja umieszczę ją obok tej należącej do Baraka Kodobane\'a.",
    ["O"] = "Przynieś Głowę Veroga do Regthara Deathgate\'a, na zachód od Crossroads.",
    ["T"] = "Verog Derwisz",
  },
  [852] = {
    ["D"] = "Hezrul Bloodmark jest przywódcą centaurów Kolkar w Barrens. Jest on okrutny, brutalny i przebiegły. Pokonanie go zakłóciłoby i złamało Kolkarów, znacznie zmniejszając zagrożenie dla nas.$B$BZabij go więc. $gPrzyniosłeś:Przyniosłaś; mi głowę Baraka i Veroga, więc przynieś mi tez głowę Herzula.$B$BHezrul przewodzi swoimi ludźmi z Oazy Bujnych Wód, na południe.",
    ["O"] = "Przynieś głowę Hezrula Bloodmarka do Regthara Deathgate\'a na zachód od Crossroads.",
    ["T"] = "Hezrul Bloodmark",
  },
  [853] = {
    ["D"] = "Przetworzyłem zarodniki, które od ciebie otrzymałem w emulsje. Muszę ją teraz wysłać do mojej wspólniczki, aptekarki Zamahy. Jeżeli $gzaniósłbyś:zaniosłabyś; jej to, z pewnością zaoferowałaby ci coś z naszych zapasów dóbr alchemicznych.$B $BPrzebywa ona w Sadzawkach Wizji, jaskini pod siedzibą szamanów w Thunder Bluff. Ścieżka do tej jaskini jest dobrze ukryta, ale możesz ją odnaleźć na klifie Wzniesienia Ducha.$B $BTylko się pośpiesz. Emulsja zachowa swój potencjał tylko przez krótką chwile i przed upływem czasu musi zostać wylana i przetworzona.",
    ["O"] = "Przynieś Rendered Spores dla aptekarki Zamah w Thunder Bluff, przed upływem czasu.",
    ["T"] = "Apothecary Zamah",
  },
  [854] = {
    ["D"] = "Przewidziałem twoje przybycie, $gmłody:młoda; $C. Chociaż może nie jesteś już $gtaki młody:taka młoda;.$B$BMyślę, że nadszedł twój czas, żebyś $gwyruszył:wyruszyła; w głąb tej krainy. Wyczuwam, że twoim przeznaczeniem jest dokonywanie wielkich czynów.$B$BMusisz odszukać Crossroads, nasz los splótł się z orkami i potrzebują oni teraz naszego wsparcia. Idź dalej w dół tej drogi na wschód i podążaj dalej na północ do Crossroads. Znajdź Thorka, został on pobłogosławiony przez samą Matkę Ziemię.",
    ["O"] = "Porozmawiaj z Thorkiem w Crossroads, w Barrens.",
    ["T"] = "Podróż do Crossroads",
  },
  [855] = {
    ["D"] = "Plemię Kolkarów są zagrożeniem dla planów Hordy dotyczących zawładnięcia tymi ziemiami, a więc musimy zmniejszyć ich liczby. Znów mam zadanie dla ciebie.$B$BGdy będziesz na ich terytorium, zabij ich wojowników i zbierz bransolety. Wróć gdy będzie $gmiał:miała; pokaźną ich ilość, a Horda cię wynagrodzi.",
    ["O"] = "Zbierz 15 Centaur Bracers dla Regthara Deathgate\'a na zachód od Crossroads.",
    ["T"] = "Bransolety centaurów",
  },
  [856] = {
    ["D"] = "Though you have reached the Barrens, your journey is not complete. You must continue on to the Crossroads, where you are needed most.$B$BFollow the road as you were, and turn left where the path gives you the choice. Follow it North until you see the walls of the Crossroads.$B$BJust before you enter, you should see the Ancestral Sage, he will have words of wisdom for you.",
    ["O"] = "Continue down the road from Camp Taurajo.$B$BTurn left at the T intersection and continue North.$B$BFollow the path to the Ancestral Sage outside the Crossroads.",
    ["T"] = "<UNUSED>",
  },
  [857] = {
    ["D"] = "Ta moc była moja! Tylko moja! I chcę ją z powrotem! Z powrotem powiedziałem!$B$BCi brudni kopacze odkryli To... jakież To było piękne. Uznaliśmy, że Łza Księżyców było pierwszym ogromnym odkryciem w Bael Modan.$B$BTo powinno być moje! Moje powiedziałem!$B$BW generale Twinbraidzie urosła zazdrość w związku z mocą jaką To mi dało. Zamknął to z dala w twierdzy. Nazwał to przeklętym, zrobił to! Głupek!$B$BInni Tego pragnęli i zostali powstrzymani! Ten nikczemnik Twinbraid odsunął mnie od Tego.$B$BPragnę Tego z powrotem. Z powrotem powiedziałem!",
    ["O"] = "Feegly the Exiled chce, abyś $godzyskał:odzyskała; dla niego Tear of the Moons.",
    ["T"] = "Łza Księżyców",
  },
  [858] = {
    ["D"] = "Nie sądzę, by to Sputtervalve cię przysłał. Utknąłem tu. Wskoczyłem tu, nie wiedząc, że będę potrzebował klucza, aby odblokować kolumnę ruchu rozdrabniarki. Inny operator spytał mnie, czy wszystko w porządku, i spanikowałem! Zamiast powiedzieć mu, że nie mam klucza, powiedziałem, że są problemy z mechaniką.$B$BMusimy się stąd biegiem wydostać! Idź do sterowni na szczycie dźwigu, nadzorca powinien mieć klucz do tej maszyny.$B$BPomóż mi się stąd wydostać!",
    ["O"] = "Zdobądź Ignition Key i przynieś go Wizzlecrankowi.",
    ["T"] = "Zapłon",
  },
  [860] = {
    ["D"] = "Jeśli chcesz kroczyć ścieżką łowcy, twa droga wiedzie przez Barrens. Tamtejsze zwierzęta są uparte i groźne. Polując tam, wiele się nauczysz, twój duch nabierze mocy.$B$BPorozmawiaj z Sergrą Darkthorn. Będzie ona twym pierwszym przewodnikiem po Barrens.$B$BSpotkasz ją w Crossroads. By do niej dotrzeć, kieruj się na wschód od Wioski Bloodhoof, do Barrens, potem skręć na północ przy rozwidleniu dróg. I uważaj na siebie - dla nieprzygotowanych i nieuważnych Barrens są niebezpieczne.",
    ["O"] = "Porozmawiaj z Sergrą Darkthorn w Crossroads.",
    ["T"] = "Sergra Darkthorn",
  },
  [861] = {
    ["D"] = "Pragniesz podróży i odkryć, widzę to. I ja czułem pokusę do wędrówki, kiedyś...$B$BWędrówki i polowania. Bowiem polowanie to dla taurena największy honor.$B$BJeśli naprawdę chcesz pójść drogą myśliwego, Melor Stonehoof może wskazać ci ścieżkę. Spotkasz go w Thunder Bluff, na Wzniesieniu Łowcy.$B$BBy pokazać zaś swe umiejętności i zdecydowanie, przynieś mu szpony równinnych włóczęgów z Mulgore. Są one twarde i przebiegłe - odpowiednia zdobycz dla $gmłodzieńca:młodej damy; na ścieżce łowcy.",
    ["O"] = "Przynieś Melorowi Stonehoofowi z Thunder Bluff 4 Flatland Prowler Claws.",
    ["T"] = "Droga łowcy",
  },
  [862] = {
    ["D"] = "Tu, w Barrens, myśliwy taki jak ty musi być naprawdę głodny. Ja głoduję cały dzień.$B$BPowiem ci coś, zrobię ci dobrą potrawkę. Potrzebuję tylko kilka ryjących szczurów.$B$BZdaje się, że plugawe krasnoludy z Bael Modan są zalewane przez ten powszechnie wielbiony przysmak. Teraz idź na południe do Bael Modan i przynieś mi kilka dużych szczurów.$B$BNie możesz nazwać się doświadczonym podróżnikiem, póki nie spędzisz trochę czasu, zabijając szczury! Ha!",
    ["O"] = "Przynieś 8 Dig Rats do Gruba, na wschód od Crossroads.",
    ["T"] = "Szczurzy gulasz",
  },
  [863] = {
    ["D"] = "Mam nadzieję, że wszystko wyjdzie w praniu... To nie może być zbyt trudne. Kilka przycisków tu, dźwignia czy dwie... No, $ggotowy:gotowa; do drogi?",
    ["O"] = "Chroń Wizzlecranka i skradzioną rozdrabniarkę w drodze do Sputtervalve\'a do Ratchet.",
    ["T"] = "Ucieczka",
  },
  [864] = {
    ["D"] = "\"Proszę, źródło mocy zostało bezpiecznie usunięte i dane są zabezpieczone. No, to bezpiecznej podróży i tak dalej. Miejmy nadzieję, że nikczemny naukowy eksperyment zadziałał i w ogóle.\"$B$BGoblin odwrócił się od ciebie, by zająć się sprawami Gadgetzańskiej Kompanii Wodnej. Zabezpieczasz zapieczętowany zestaw testowy, przygotowując się do drogi powrotnej do Undercity. Aptekarka Zinge czeka tam na ciebie, jak i na zapieczętowany polowy zestaw testowy.",
    ["O"] = "Zanieś Sealed Field Testing Kit do aptekarki Zinge w Undercity.",
    ["T"] = "Powrót do aptekarki Zinge",
  },
  [865] = {
    ["D"] = "Jaszczury z Barrens są sprytniejsze niż te z innych ziem. I myślę, że cały ten spryt kryje się w ich rogach! Jeśli tak jest, mógłbym zmielić te rogi na proszek i użyć do stworzenia \"sprytnych napojów\". I sprzedawałbym je, zbijając majątek!!!$B$BA ty możesz mi pomóc. Znajdź dla mnie nienaruszone rogi jaszczura z kososzponów słonecznołuskich. Kręcą się po południowych i północnych Barrens, przy granicy z lasem Ashenvale.",
    ["O"] = "Zbierz 5 Intact Raptor Horns z Sunscale Scytheclaws i przynieś je Mebokowi Mizzyrixowi z Ratchet.",
    ["T"] = "Rogi jaszczurów",
  },
  [866] = {
    ["D"] = "Zioła z Barrens nie przypominają tych z innych ziem. Ich właściwości są z grubsza te same, ale woda z oaz odmienia je, są troszkę inne!$B$BChcę zbadać te różnice... sprawdzić, czy da się je wykorzystać!$B$BJeśli znasz się na zielarstwie, zbierz mi próbki korzeni ziół, które znajdziesz w Barrens. Przynieś mi je, bym mógł porównać je z tymi z innych regionów.",
    ["O"] = "Przynieś Mebokowi Mizzyrixowi z Ratchet 8 Root Samples.",
    ["T"] = "Próbki korzeni",
  },
  [867] = {
    ["D"] = "Przeklęte harpie pustoszą nasze karawany z zapasami już zbyt długo. Czas rozpruć im kilka gardeł i uszczuplić ich liczbę.$B$BPodglądałem trochę ich gniazda i sprawdziłem, kto kim rządzi. Największe zniszczenia poczyni atak skierowany w większość dolnych warstw ich łańcucha dowodzenia; potem możemy wypracować sobie drogę na sam szczyt.$B$BRozpoczniemy powoli, najpierw zajmij się wiedźmoskrzydłymi harpiami i łotrzyniami z północnego zachodu i przynieś mi 8 ich szponów. To będzie dobry początek...",
    ["O"] = "Zbierz 8 szponów z Witchwing.$B$BPrzynieś je Darsokowi Swiftdaggerowi.",
    ["T"] = "Harpie łupieżcy",
  },
  [868] = {
    ["D"] = "Hej, $N. Wysłano mnie do Crossroads., bym obserwował te ziemie i relacjonował, co się dzieje, mym panom w Orgrimmarze.$B$BJednym z przedmiotów moich obserwacji są owadopodobne stworzenia, które można znaleźć na południu, na Polu Gigantów. Niewiele o nich wiemy, uważam więc za konieczne dowiedzieć się o nich czegoś więcej. Wydają się być bardziej inteligentne niż jakiekolwiek inne normalne zwierzęta.$B$BWeź szczypce do chwytania i zbierz trochę jaj tych stworzeń z ich kopców, ale bądź $gostrożny:ostrożna;: zaniepokojone, będą atakować.",
    ["O"] = "Przynieś 12 Silithid Eggs i Digging Claw do Korrana w Crossroads.",
    ["T"] = "Polowanie na jaja",
  },
  [869] = {
    ["D"] = "Nie tak dawno z naszej strażnicy skradziono ładunek srebra. Było przeznaczone na żołd dla strażników z Crossroads i chcemy je odzyskać.$B$BCo dziwne... złapaliśmy jednego ze złodziei w noc kradzieży. I... to był jaszczur! Niewiarygodne!$B$BNie mam pojęcia, po co jaszczurom to srebro. Ale nie obchodzi mnie to. Chcę głów jaszczurów, by więcej nas nie okradały!$B$BZapoluj na nie w Barrens. Zbierz dla mnie ich głowy!",
    ["O"] = "Przynieś Gazrogowi z Crossroads 12 Raptor Heads.",
    ["T"] = "Jaszczury złodzieje",
  },
  [870] = {
    ["D"] = "Dawno temu Barrens były miejscem z bujną roślinnością tętniącą życiem. Jednak wojny i kataklizmy, które przeszły przez te ziemie, wypaliły je i wysuszyły do reszty. Takie są koleje losów i smuci to moje serce.$B$BLecz przez ostatnie parę lat w Barrens powstały nowe oazy i życie rozkwita. A tam poniżej, my, druidzi, wyczuwamy moc wyciekającą na powierzchnię.$B$BMusimy znaleźć jej źródło. Udaj się nad Zapomniane Sadzawki, na północny zachód od Crossroads. Poszukaj źródła mocy w tamtejszych wodach, a potem wróć tutaj.",
    ["O"] = "Złóż Tondze Runetotem raport ze swoich odkryć.",
    ["T"] = "Zapomniane sadzawki",
  },
  [871] = {
    ["D"] = "Wszystkie kolcozwierze są naszymi wrogami, $N. Niektóre po prostu udowodniły, że są większym utrapieniem niż inne.$B$BPlemię Brzytwowłosych atakuje nasze szlaki zaopatrzeniowe z Durotaru, zapewniając nam ciągłe utrapienie. Wysłałem zwiadowców na poszukiwania dowódcy tych najazdów, ale do czasu ich powrotu wszelkie straty, jakie możesz zadać tym plugawym świniakom, mają dla nas ogromne znaczenie.$B$BZacznij na północnym wschodzie, w kierunku Durotaru. Zawsze możesz poznać ich obozowiska po olbrzymich kolczastych pnączach wyrastających z ziemi. Znajdź je i zabij.",
    ["O"] = "Zabij 8 Water Seekers, 8 Thornweavers i 3 Hunters z plemienia Razormane, potem wróć do Thorka w Crossroads.",
    ["T"] = "Powstrzymać ataki",
  },
  [872] = {
    ["D"] = "$N, jeden z moich zwiadowców był świadkiem ataku na karawanę z Durotaru. Sprawcami rzeczywiście są kolcozwierze z plemienia Brzytwowłosych. W szczególności jeden z nich dowodzi najazdami: Kreenig Snarlsnout. Widziano go na północny wschód stąd, dokładnie na południe od drogi z Durotaru. Jeśli mamy pozbyć się zagrożenia ze strony kolcozwierzy, Kreenig musi zginąć.$B$BŻeby mieć pewność, że ataki ustaną, musimy dodać zniewagę do ich ran. Zabij Kreeniga oraz większość jego plemienia, następnie przynieś mi jego kieł.",
    ["O"] = "Zabij 8 Razormane Geomancers, 8 Razormane Defenders, i Kreeniga Snarlsnouta.$B$BPotem przynieś Kreenig Snarlsnout\'s Tusk do Thorka w Crossroads.",
    ["T"] = "Koniec zamętu",
  },
  [873] = {
    ["D"] = "Wielki Isha Awak jest władcą tych wód. Potężna jest jego siła i wielka jego duma. Ludzie z wybrzeża boją się go, pożarł bowiem wielu z nich.$B$BLecz ja się go nie lękam. Jestem wdzięczna, że tu jest. Jest godnym wyzwaniem i zaszczytną zdobyczą.$B$BJeśli jesteś $ggotów:gotowa;, wypłyń na poszukiwanie Isha Awaka, Zagłady Głębin.$B$BDuch jego spoczywa w jego sercu; słuchając jego bicia można poznać swoje przeznaczenie.",
    ["O"] = "Przynieś Serce Isha Awaka do Mahren Skyseer.",
    ["T"] = "Isha Awak",
  },
  [874] = {
    ["D"] = "$gPolowałeś:Polowałaś; już na zwierzęta z Barrens. Twój duch jest silny. Ale łowca musi być zawsze czujny. Prawdziwy łowca potrafi polować wszędzie i na wiele sposobów. Góry czy bagna nie stanowią dla niego przeszkody.$B$BMorze również.$B$BZnajdź mą siostrę, Mahren. Poluje na ogromne morskie zwierzęta wzdłuż wybrzeża. Wyszkoli cię w technice ich łowów.$B$BLecz uważaj podczas swych poszukiwań, gdyż wybrzeże Barrens zajęte jest przez ludzi.",
    ["O"] = "Porozmawiaj z Mahren Skyseer.",
    ["T"] = "Mahren Skyseer",
  },
  [875] = {
    ["D"] = "Hahaha, $N. Wracasz po więcej? Dobrze to słyszeć.$B$BTym razem chcę, abyś $gusunął:usunęła; kilku poruczników harpii z Wysuszonych Wzgórz. Jedynie zabójczynie wiedzmoskrzydłe bywają porucznikami, a te odróżnisz od reszty dzięki pierścieniom, które noszą. To paskudna banda, a do tego mają tam jeszcze podwładnych. Zabicie sześciu z nich będzie poważnym ciosem zadanym ich bandzie.$B$BSpraw, by umierały w męczarniach, $N. Chcemy, aby te harpie ścierwa zrozumiały, że walka z Hordą to głupota.",
    ["O"] = "Zbierz 6 Harpy Lieutenant Rings z Witchwing Slayers i zanieś je do Darsoka Swiftdaggera z Crossroads.",
    ["T"] = "Porucznicy harpii",
  },
  [876] = {
    ["D"] = "Poszło ci świetnie z porucznikami i ich podwładnymi, dlatego proszę cię o ostatnią przysługę.$B$BSerena Bloodfeather jest siostrą harpii zwanej Krwawopiórą, którą dawno temu zabił Rexxar. Najwyraźniej te ataki na transporty Hordy są zemstą za jej śmierć.$B$BChcę, abyś $gpoderżnął:poderżnęła; jej gardło i przyniósł mi jej głowę. Umieszczę ją na kolejnej karawanie... To powinno dać harpiom do myślenia.",
    ["O"] = "Zabij Serenę Bloodfeather i przynieś jej głowę Darsokowi Swiftdaggerowi z Crossroads.",
    ["T"] = "Serena Krwawopióra",
  },
  [877] = {
    ["D"] = "Szczeliny, podobne do tych, jakie $gwidziałeś:widziałaś; w Zapomnianych Sadzawkach, mogą znajdować się również w innych oazach Barrens. Jeśli tak, może są one źródłem tamtejszego życia.$B$BMusimy to sprawdzić.$B$BProszę, weź te nasiona. Są martwe i jałowe, ale zabierz je do oazy Stojących Wód na południowym wschodzie. Jeśli jest tam szczelina, umieść w niej nasiona... i obserwuj.",
    ["O"] = "Po zbadaniu Stagnant Oasis wróć do Tongi z Crossroads.",
    ["T"] = "Oaza Stojących Wód",
  },
  [878] = {
    ["D"] = "Musisz uderzyć na moich wrogów. <chrząknięcie> Musisz pomóc Mangletooth i Brzytwowłosym, osłabiając Najeżaków. Oba szczepy są bardzo uduchowione - związane z ziemią i jej mocą. <chrząknięcie> Daje nam to siłę do wszystkiego... zwłaszcza do wojny.$B$BJeżeli chcesz się dowiedzieć, kto tak naprawdę spowodował udrękę Thorka <chrząknięcie> i Hordy, to pomóż Mangletooth! Zaatakuj duchowych przywódców Najeżaków z północy. Osłab ich, aby Brzytwowłosi mogli pokonać ich i przejąć kontrolę nad Barrens.",
    ["O"] = "Zabij 6 Bristleback Water Seekers, 12 Bristleback Thornweavers i 12 Bristleback Geomancers, po czym wróć do Mangletooth z Camp Taurajo w Barrens.",
    ["T"] = "Wojna plemion",
  },
  [879] = {
    ["D"] = "Trzech z mojego plemienia opuściło Zagrodę, aby przewodzić najazdom na Hordę, $R7. <chrząknięcie> Są przebiegli i bezlitośni i jeśli ich pokonasz, wtedy wasze Crossroads i większość terenów Barrens zaznają spokoju... <chrząknięcie> przynajmniej ze strony plemienia Brzytwowłosych. <chrząknięcie>$B$BNak, Kuz i Lok, Zguba Orków są tymi, których szukasz. Przebywają daleko na południu Barrens. Jeden jest magiem, drugi tropicielem, a ich lider, zwany Zgubą Orków <chrząknięcie> wojownikiem. Zabij ich, $R7, tak jak oni zabili mnie.",
    ["O"] = "Zabij Naka, Kuza i Loka Orcbane, i przynieś ich czaszki Mangletooth z Camp Taurajo w Barrens.",
    ["T"] = "Zdrada od wewnątrz",
  },
  [880] = {
    ["D"] = "Twoje odkrycia są niesamowite, $N. Te oazy mają właściwości, które muszą pochodzić z zewnętrznego źródła. Albo może z wewnętrznego.$B$BChciałbym wiedzieć, jak te szczeliny działają na zwierzęta, które piją wodę z oazy.$B$BZapoluj na kłaposzczęki z Oazy Bujnych i Stojących Wód. Przynieś mi ich skorupy, abym mógł je zbadać.",
    ["O"] = "Przynieś 8 Altered Snapjaw Shells do Tongi Runetotem z Crossroads.",
    ["T"] = "Odmienione istoty",
  },
  [881] = {
    ["D"] = "Biała Mgła, Echeyakee w języku taurenów, jest królem wszystkich kotów sawanny. Skrada się tak zręcznie, że mawiają, iż jest jak cienkie pasmo białej mgły na powierzchni ziemi. Zabija tak szybko, że jego ofiara nie ma czasu na strach czy ból.$B$BTaureni mawiają, że jest jednocześnie miłosierdziem i śmiercią.$B$BDowiesz się, czy to prawda, bo wysyłam cię, abyś $gzapolował:zapolowała; na Echeyakee. Jego leże znajduje się na północny wschód od Crossroads, pośród kości olbrzymiego kodo.$B$BRuszaj. Zadmij w róg, gdy dotrzesz na miejsce. Zadmij w róg, a on nadejdzie.",
    ["O"] = "Przynieś Skórę Echeyakee Sergrze Darkthorn z Crossroads.",
    ["T"] = "Echeyakee",
  },
  [882] = {
    ["D"] = "Ishamuhale, Włóczniozęby, jest najokrutniejszym słonecznołuskim jaszczurem w Barrens. Nie poluje dla sportu ani dla jedzenia. Poluje, bo to jego pasja. Zabija, bo leży to w jego naturze.$B$BZresztą, zobaczysz jaki on jest, $N, gdyż twoja ścieżka prowadzi teraz śladami pazurów Ishamuhale.$B$BRozpocznij polowanie. Upoluj jego ulubioną zdobycz, zebrę, i przynieś zewłok pod martwe drzewo na północny zachód od Ratchet. Ishamuhale wywęszy mięso i przybędzie.$B$BBądź $ggotów:gotowa;, kiedy się zjawi.",
    ["O"] = "Przynieś Ishamuhale\'s Fang do Jorna z Camp Taurajo.",
    ["T"] = "Ishamuhale",
  },
  [883] = {
    ["D"] = "Kopyto Lakota\'mani jest symbolem siły wielkich kodo.",
    ["O"] = "Przynieś Kopyto Lakota\'mani do Jorna z Camp Taurajo.",
    ["T"] = "Lakota\'mani",
  },
  [884] = {
    ["D"] = "Przy dotknięciu, z kolca z ogona Owatanki lecą iskry.",
    ["O"] = "Przynieś Owatanka\'s Tailspike do Jorna z Camp Taurajo.",
    ["T"] = "Owatanka",
  },
  [885] = {
    ["D"] = "Dotyk pióra Washte Pawne zadaje ból.",
    ["O"] = "Przynieś Washte Pawne Feather Jornowi Skyseer z Camp Taurajo.",
    ["T"] = "Washte Pawne",
  },
  [886] = {
    ["D"] = "Druidzi z Thunder Bluff wyczuwają dziwną moc przesączającą się na Barrens, na wschód od Mulgore.$B$BTonga Runetotem został wysłany, aby odkryć źródło tej mocy, lecz obawiamy się, że będzie potrzebował pomocy.$B$BWyrusz do Barrens i porozmawiaj z Tongą. Znajdziesz go w Crossroads. Aby tam trafić, podążaj drogą na wschód od Wioski Bloodhoof. Wkrocz na Barrens, a kiedy droga się rozwidli, skręć na północ. Tą drogą trafisz do Crossroads.$B$BTrzymaj się traktu, $N. Barrens to nieprzyjazna okolica.",
    ["O"] = "Porozmawiaj z Tongą Runetotemem w Crossroads.",
    ["T"] = "Oazy Pustkowi",
  },
  [887] = {
    ["D"] = "Bardzo chciałbym, żeby wiceadmirał Grezzlik bardziej przykładał się do zabezpieczenia naszych morskich szlaków handlowych. Przy takich nakładach na Flotę Handlową wkurza mnie widok swobodnie pływającej chmary piratów napadających na statki i kradnących moje towary!$B$BSłyszałem, że Korsarze z Mórz Południowych rozbili obóz na południe stąd. Są prawdziwym wrzodem na tyłku i jeżeli Grezzlik się nimi nie zajmie, cóż, być może ty pomożesz mi się ich pozbyć.",
    ["O"] = "Zabij 12 Southsea Brigands i 6 Southsea Cannoneers dla Gazlowe\'a z Ratchet.",
    ["T"] = "Korsarze z Mórz Południowych",
  },
  [888] = {
    ["D"] = "Chciałbym odzyskać wszystkie moje dobra, jednak wiem, że to niemożliwe. Jednakże, jest kilka rzeczy, które koniecznie muszę mieć!$B$BJak widzisz, moje obserwatorium jest gotowe, ale wciąż potrzeba mniejszej z dwóch soczewek. Pierwszą dostarczyła karawana z Durotaru, ale druga płynęła statkiem i nigdy nie dotarła. Do tego nie dostałem przesyłki butów od Drizzlika z Booty Bay!$B$BUdaj się do obozu piratów i poszukaj moich rzeczy.",
    ["O"] = "Odzyskaj Shipment of Boots i Telescopic Lens dla Gazlowe\'a z Ratchet.",
    ["T"] = "Skradzione łupy",
  },
  [889] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Duch wiatru",
  },
  [890] = {
    ["D"] = "Czekam już całą wieczność na mój ostatni ładunek dóbr z Booty Bay! Jestem niemal pewien, że został skradziony przez Korsarzy, ale tak dla pewności, czy $gmógłbyś:mogłabyś; zejść do doków i zapytać Dizzywiga, czy moje rzeczy nie trafiły przypadkiem do magazynu bez mojej wiedzy?$B$BMasz, weź moją księgę rachunkową do Dizzywiga i niech dwa razy porówna moją listę ze swoimi zapiskami.",
    ["O"] = "Przynieś księgę rachunkową Gazlowe\'a do dokmistrza Dizzywiga.",
    ["T"] = "Zaginiony ładunek",
  },
  [891] = {
    ["D"] = "No i straciłem kolejny statek przez tych fanatyków z Twierdzy Northwatch!$B$BTrzeba się zająć tym draniami. Ich paranoja doprowadziła ich do szaleństwa. Spust się cieszy, a pociski lecą beztrosko w kierunku wszystkiego w zasięgu dział.$B$BUdaj się do Twierdzy, na południe wzdłuż Wybrzeża Kupców i przystąp do jej oblężenia. Przynieś mi odznaczenia ich żołnierzy jako dowód. I, na miłość do mej floty, zabij kapitanową Fairmount i jej fanatycznych kanonierów!",
    ["O"] = "Kapitan Thalo\'thas Brightsun z Ratchet chce, byś $gzebrał:zebrała; 10 Theramore Medals, $gzabił:zabiła; panią kapitan Fairmount, kanoniera Whessana i kanoniera Smythe\'a.",
    ["T"] = "Działa Northwatch",
  },
  [892] = {
    ["D"] = "W moich zapiskach wszystko jest bez zarzutu, $N. Wracaj do Gazlowe\'a i powiedz mu, że ma pecha. Wcale bym się nie zdziwił, gdyby się okazało, że to piraci zwędzili jego rzeczy.$B$BNic więcej nie mogę dla niego zrobić. Aha... ale możesz mu przekazać, że mam dla niego co nieco z Undermine, niech wpadnie, gdy będzie miał trochę czasu.",
    ["O"] = "Oddaj Gazlowe\'owi z Ratchet jego księgę rachunkową.",
    ["T"] = "Zaginiony ładunek",
  },
  [893] = {
    ["D"] = "Z tego, co mi wiadomo, mieszkające na południe stąd, za Polem Gigantów, Brzytwowłose kolcozwierze nie posiadają wyszkolonych kowali, a mimo to najwyraźniej zaczęły wytwarzać wytrzymalszy oręż. Chciałbym dostać kilka jego rodzajów, by - jeśli to możliwe - poznać stosowane przez nich metody.$B$BJeśli pragniesz pomóc przynieść honor Hordzie, dostarcz mi egzemplarze tych broni. Zdobądź dla mnie sztylet ich tropicieli, używaną przez wieszczów różdżkę oraz tarczę wojownika. To powinno wystarczyć!",
    ["O"] = "Przynieś Razormane Backstabber, Charred Razormane Wand oraz Razormane War Shield do Tatternacka Steelforge\'a z Camp Taurajo w Barrens.",
    ["T"] = "Ulubione bronie",
  },
  [894] = {
    ["D"] = "Venture Company wybudowało niewielką stację badawczą daleko na północ stad, na południowy zachód od Sludge Fen. Niewiele wiem o tym, co tam robią, ale udało mi się odkryć, że eksperymentują z czymś, co nazywają \"autokrętem\".$B$BAle czym, na pękniętą miskę olejową, jest autokręt? Cóż, czymkolwiek jest, chcę go obejrzeć, więc potrzebuję kogoś, kto go przyniesie.$B$BUdało mi się zdobyć kopię instrukcji obsługi systemu sterującego; po jej przeczytaniu zapewne domyślisz się, jak odłączyć od niego autokręt.",
    ["O"] = "Uzyskaj dostęp do konsoli sterującej w stacji badawczej Venture Company.",
    ["T"] = "Autokręt",
  },
  [895] = {
    ["D"] = "POSZUKIWANY!$B$BBaron Longshore, kapitan statku Heedless.$B$BKapitan Longshore z Gilneas kierował statkami Korsarzy z Mórz Południowych i jest poszukiwany za piractwo. Zwłoki kapitana mają zostać dostarczone w stanie umożliwiającym na zidentyfikowanie go!$B$B-- Gazlowe",
    ["O"] = "Przynieś głowę Barona Longshore\'a do Gazlowe\'a w Ratchet.",
    ["T"] = "POSZUKIWANY: Baron Longshore",
  },
  [896] = {
    ["D"] = "Jako dokmistrz tak ruchliwego portu jak Ratchet trzymam rękę na pulsie. Wiem wszystko o przepływie dóbr i funduszy między tym miejscem a Booty Bay.$B$BOstatnio dotarły mnie słuchy na temat Kamieniołomu Venture Co. na północny wschód od Sludge Fen. Jeden z górników znalazł tam szmaragd wielkości twej pięści. Znam kilku nabywców, którzy byliby zainteresowani dostaniem czegoś takiego w swoje ręce i z radością podzielę się połową uzyskanej zań ceny.",
    ["O"] = "Odzyskaj Cats Eye Emerald z rąk jednego z nadzorców bądź ochroniarzy Venture Co. dla dokmistrza Dizzywiga z Ratchet.",
    ["T"] = "Szczęście górnika",
  },
  [897] = {
    ["D"] = "Dziwne, owadopodobne stworzenie wydaje się nie pasować do tutejszej okolicy, jak gdyby Barrens nie były jego naturalnym środowiskiem.",
    ["O"] = "Zanieś Harvester\'s Head do Jorna Skyseera.",
    ["T"] = "Żniwiarz",
  },
  [898] = {
    ["D"] = "Nareszcie! Ktoś przybył mi na ratunek!$B$BNie mogę uwierzyć, że $gprzedarłeś:przedarłaś; się przez straże. Ci fanatycy z Theramore są kompletnie szaleni. Zatopili mój statek i uwięzili mnie, jedynego ocalałego. Nazwali mnie wrogiem i zagrożeniem dla Przymierza.$B$BJa! Zagrożeniem dla ich wielkiego tak zwanego Przymierza? Byłem majtkiem na statku wożącym bimber między Ratchet a Booty Bay.$B$BDość gadania. Pomożesz mi dotrzeć do Rachet? Daj znać, gdy będziesz $ggotowy:gotowa;, i znikajmy stąd.",
    ["O"] = "Odprowadź Giltharesa Firebougha do kapitana Brightsuna z Ratchet.",
    ["T"] = "Uwolniony z twierdzy",
  },
  [899] = {
    ["D"] = "Może wiesz, jaki ból niesie niepewność, a może nie, $C. Lecz wiedz jedno: każdego dnia tkwię tu od wschodu do zachodu słońcu, przeczesując horyzont w poszukiwaniu tych potworów. Zabiłem każdego świniaka, jaki dotychczas stanął mi na drodze, lecz daleko jeszcze do ugaszenia trawiącej mnie żądzy krwi. Może zamiast skierować się na północ do Crossroads, powinienem podążyć do Taurajo.$B$BTy, $C - ty możesz mi pomóc.$B$BZabij ich. Zabij tylu, ilu będziesz w stanie. Przynieś mi ich kły, a razem będziemy radować się z ich śmierci.",
    ["O"] = "Przynieś Mankrikowi z Crossroads 60 Bristleback Quilboar Tusks.",
    ["T"] = "Zżerany nienawiścią",
  },
  [900] = {
    ["D"] = "Trzy zawory sterujące są aktualnie otwarte. Różne odczyty na panelu sterującym pozwalają się domyślić, że muszą one zostać zamknięte, aby można było wyłączyć urządzenie.",
    ["O"] = "Zamknij Fuel Control Valve, Regulator Valve i Main Control Valve, a następnie ponownie użyj konsoli sterującej.",
    ["T"] = "Autokręt",
  },
  [901] = {
    ["D"] = "Teraz, gdy urządzenie zostało wyłączone, można otworzyć konsolę sterującą i autokręt może zostać wymontowany. Pozostaje tylko zostawić wszystko na swoim miejscu i znaleźć klucz otwierający konsolę.",
    ["O"] = "Zdobądź klucz do konsoli od majstra Sniggles\'a w celu użycia na konsoli sterującej.",
    ["T"] = "Autokręt",
  },
  [902] = {
    ["D"] = "Po otwarciu płyty czołowej konsoli sterującej twoim oczom ukazuje się gęsta plątanina przewodów, rurek i innych dziwnych mechanicznych obiektów - większość z nich wydaje się nie mieć żadnego praktycznego przeznaczenia. Po odsunięciu ich na bok i sięgnięciu jeszcze głębiej do wnętrza konsoli, znajdujesz autokręt. Szarpnięcie pozwala wyjąć go z obudowy.",
    ["O"] = "Oddaj autokręt Sputtervalve\'owi w Ratchet.",
    ["T"] = "Autokręt",
  },
  [903] = {
    ["D"] = "Nadszedł czas zapolować na coś, co naprawdę gryzie. Łowcy z Barrens to trudna zdobycz. Trudna, pomysłowa, chytra... i zabójcza. Znajdziesz ich pośród wysokich traw. Wiele z nich przebywa na południowy zachód od Crossroads.$B$BZachowaj czujność polując na nie, $N, albo może się okazać, że w miejsce łowcy $gstałeś:stałaś; się ofiarą.",
    ["O"] = "Zbierz 7 Prowler Claws z Savannah Prowlers dla Sergry Darkthorn z Crossroads.",
    ["T"] = "Łowcy z Barrens",
  },
  [904] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [905] = {
    ["D"] = "Teraz, $N, polowanie stanie się trudniejsze. Musisz $gsamemu:samej; znaleźć drogę do legowiska i dopaść ofiarę.$B$BZapoluj na słonecznołuskie jaszczury na południu. Zabij je i zbierz ich pióra, które noszą. Umieść je w legowiskach kososzponów, znajdujących się na południowy zachód od Oazy Stojących Wód. Pokaż ich braciom, że się ich nie lękasz!",
    ["O"] = "Zabij jaszczury Sunscale i zbierz ich pióra. Użyj piór na 3 gniazdach Scytheclaw. Wróc do Sergry Darkthorn z Crossroads.",
    ["T"] = "Rozzłoszczone kososzpony",
  },
  [906] = {
    ["D"] = "Zabierz głowę Loka do Thorka z Crossroads, $R7. <chrząka> Powinien dowiedzieć się, co przydarzyło się memu plemieniu - ha, nie żeby miał uwierzyć, że sam Mangletooth pomógł przy <chrząka> takich rzeczach. Lecz jestem pewien, że wynagrodzi cię za tak wspaniały czyn. <chrząka>$B$BBędę błogosławił cię mocą Agamaggana tak długo, ile pozostanę w tej klatce. Szerokiej drogi.",
    ["O"] = "Przynieś Czaszkę Loka do Thorka z Crossroads w Barrens.",
    ["T"] = "Zdrada od wewnątrz",
  },
  [907] = {
    ["D"] = "Teraz, $N, musisz zmierzyć się z wielkimi jaszczurami grzmotów. To bestie tak olbrzymie, że ziemia drży, gdy kroczą przez równiny. Zachowaj ostrożność podczas walki z nimi, jeden fałszywy ruch i możesz znaleźć się pod ich stopami.$B$BJaszczury grzmotów znajdziesz na południu Barrens. Są znane jako burzopyskie, burzoskóre, i grzmotogłowe. Wróć do mnie, kiedy je pokonasz.",
    ["O"] = "Przynieś 3 fiolki Thunder Lizard Blood do Jorna Skyseera z Camp Taurajo.",
    ["T"] = "Rozwścieczone jaszczury grzmotów",
  },
  [908] = {
    ["D"] = "Młot Zmierzchu skierował się do Ruin Sanktuarium Księżyca w Blackfathom Deeps. Ich obecność może mieć tylko jeden cel - zwrócenie żywiołów przeciw nam. Jeżeli ich nie powstrzymamy, ten region pozostanie pod ich panowaniem na dobre.$B$BRuszaj w Blackfathom i znajdź głębinowy kamień ruin; powinien spoczywać gdzieś blisko wody. W nim znajduje się głębinowy rdzeń - odpowiednio go używając, będziemy mogli odczytać historię aktywności żywiołów. Jeżeli znajdę się w jego posiadaniu, ja i Krąg Ziemi być może będziemy w stanie zrobić coś, by ich powstrzymać!",
    ["O"] = "Przynieś Fathom Core do Je\'neu Sancrei z Zoram\'gar Outpost w Ashenvale.",
    ["T"] = "Pośród ruin",
  },
  [909] = {
    ["D"] = "Pokonany żywiołak wody zostawił po sobie dziwną wodną kulę. Domyślasz się, że ten przedmiot jakoś dodawał bestii energii. Wewnątrz kuli przelewa się zgniła woda. Wydaje się ona odporna na wszelkiego rodzaju siły fizyczne.$B$BJeżeli ktokolwiek mógłby zrobić użytek z tego przedmiotu, będzie to Je\'neu Sancrea z Kręgu Ziemi. Znajduje się on w posterunku Hordy Zoram\'gar w Ashenvale.",
    ["O"] = "Zanieś Strange Water Globe do Je\'neu Sancrea w Zoram\'gar Outpost, Ashenvale.",
    ["T"] = "Baron Aquanis",
  },
  [910] = {
    ["D"] = "Słyszałem opowieści o potężnych statkach, które kursują między Ratchet a Booty Bay! To fantastyczne żeglować po oceanach i walczyć w wielkich bitwach morskich. Może kiedy dorosnę, zostanę potężnym żeglarzem Hordy! Yeah!$B$BZabrałbyś mnie do doków Ratchet, proszę? Obiecuję, że nie będę wchodził do wody i nie będę sprawiał kłopotów - chcę tylko zobaczyć wielkie łodzie i poczuć słoną morską wodę! Yeah!",
    ["O"] = "Zabierz swego podopiecznego do doków Ratchet w Barrens.",
    ["T"] = "Podróż do doków",
  },
  [911] = {
    ["D"] = "Mówią, że Ashenvale to nowe pogranicze, a Mor\'shan Rampart w Barrens to brama do niego. Byłoby wspaniale być osadnikiem, zdobywać wszystko, co potrzebne, od nieposkromionej dziczy! Mówią, że to miejsce, gdzie w przyszłości dojdzie do najsilniejszych starć między Hordą i Przymierzem, i ja chcę tam być, $N!$B$BProszę, czy mógłbyś mnie zabrać do Mor\'shan Rampart, abym mógł zobaczyć jak wygląda pogranicze? Chcę zobaczyć miejsce, skąd Horda wypędza te śmierdzące nocne elfy!",
    ["O"] = "Zabierz swojego podopiecznego do Mor\'shan Rampart w północnej części Barrens, zaraz przy granicy z Ashenvale.",
    ["T"] = "Brama na pogranicze",
  },
  [912] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Stonesplinter Trogg Disguise",
  },
  [913] = {
    ["D"] = "Thunderhawk, $N, jest zaciekłą bestią. Nadszedł czas, abyś się z nim $gzmierzył:zmierzyła;. Musisz znaleźć trasę jego wędrówek i przynieść mi jego skrzydła na dowód udanego polowania.$B$BZrób to, a nie będę miał dla ciebie więcej zadań.",
    ["O"] = "Odszukaj i zgładź Thunderhawk, przynieś jego skrzydła Jornowi Skyseerowi z Camp Taurajo.",
    ["T"] = "Krzyk jastrzębia grzmotów",
  },
  [914] = {
    ["D"] = "Druidzi z Wailing Caverns, Druids of the Fang, stanowią aberrację. Byli niegdyś częścią stowarzyszenia szlachetnych druidów, które zamierzało uzdrowić Barrens, teraz jednak starają się dopasować krainę do własnych, spaczonych wyobrażeń.$B$BDowodzi nimi czwórka druidów, z których każdy posiada klejnot snów. Nawet teraz ich twarze mnie prześladują! Pokonaj przywódców Kła i przynieś mi ich klejnoty, a być może w Barrens znów zaznają spokoju.$B$BIdź, $N. Znajdziesz ich czających w głębi Wailing Caverns (46,36).",
    ["O"] = "Przynieś Narze Wildmane z Thunder Bluff Klejnoty Cobrahna, Anacondry, Pythasa i Serpentisa.",
    ["T"] = "Przywódcy Kła",
  },
  [915] = {
    ["D"] = "LODY! Proszę, proszę, proszę mógłbyś mi przynieść trochę lodów?! Mój ulubiony smak to truskawkowy, a nie ma lepszych lodów truskawkowych na świecie niż Lody Truskawkowe od Tigule\'a i Forora! To moje ulubione lody na całym wielkim świecie!$B$BJadłem je dawno temu, kiedy byłem na torze wyścigowym na Shimmering Flats, ale słyszałem, że teraz mogą być dostępne w mieście! Proszę? Bardzo proszę? O lody? I do tego od Tigule\'a i Forora??!?!",
    ["O"] = "Przynieś Lody Truskawkowe swemu podopiecznemu. Chłopiec uwielbia lody od Tigule\'a i Forora.",
    ["T"] = "Z mleka, wody, dla ochłody...",
  },
  [916] = {
    ["D"] = "Przybyłem do Shadowglen, by obserwować leśne przędzarze zamieszkujące jaskinię Shadowthread. Są kuzynami mniejszych odmian pająków; sądzę, że drzewo świata wywiera na nie intensywny efekt. Chciałbym zdobyć okazy do badań, aby to potwierdzić.$B$BNajpierw chciałbym dostać nieco ich trucizny. Zbierz gruczoły jadowe leśnych przędzarzy od pająków we wnętrzu i okolicach jaskini Shadowthread na północ stąd. Będę mógł zbadać ich podobieństwo z trucizną mniejszych kuzynów.",
    ["O"] = "Przynieś 10 Webwood Venom Sacs do Gilshalana Windwalkera z Aldrassilu.",
    ["T"] = "Trucizna przędzarzy",
  },
  [917] = {
    ["D"] = "Teraz, kiedy mam już jad pająka, chciałbym zdobyć parę żywych okazów do badań. Niestety, pochwycenie żywego olbrzymiego pająka jest ponad twoje siły, $gmłody:młoda; $C. Co więcej, pająk olbrzym to za dużo nawet dla mnie!$B$BGdybyś jednak $gznalazł:znalazła; niewyklute jajo, transport okazów byłby znacznie łatwiejszy; mógłbym wówczas zaaranżować przesyłkę niewyklutych pająków.$B$BGłęboko w jaskini Shadowthread powinno znajdować się gniazdo. Proszę, poszukaj tam jaja i przynieś mi je.",
    ["O"] = "Przynieś Webwood Egg do Gilshalana z Aldrassilu.",
    ["T"] = "Jajo przędzarza",
  },
  [918] = {
    ["D"] = "Drzewiaki Teldrassilu są żywiołakami natury. W pewien sposób stanowią odbicie naturalnego porządku roślin i zwierząt na naszym wspaniałym drzewie.$B$BWięc to, jak gniewne się stały, jest niepokojące.$B$BMyślę, że ma to coś wspólnego z glebą. Pracowałem nad wieloma sposobami nawożenia roślin i chciałbym wypróbować je na nasionach drzewiaków. Proszę, czy $gmógłbyś:mogłabyś; zebrać nasiona z drzewiaków żyjących wokoło jeziora Al\'Ameth i mi je przynieść?",
    ["O"] = "Przynieś 8 Timberling Seeds do Denalana przebywającego niedaleko jeziora Al\'Ameth.",
    ["T"] = "Nasiona drzewiaków",
  },
  [919] = {
    ["D"] = "Małe drzewiaki kiełkują wokół wód jeziora Al\'Ameth. Obawiam się, że jest za późno, by pomóc tym latoroślom - powinniśmy się ich pozbyć, zanim urosną na tyle, że będą sprawiać problem.$B$BWędrując w okolicy jeziora, zerwij proszę każdy kiełek, jaki zobaczysz. Pomóż utrzymać czystość naszej ziemi!",
    ["O"] = "Przynieś 12 Timberling Sprouts do Denalana przebywającego niedaleko jeziora Al\'Ameth.",
    ["T"] = "Kiełki drzewiaków",
  },
  [920] = {
    ["D"] = "$N, tak? Słyszałem, że Tenaron o ciebie pytał. Znajdziesz go w pokoju na szczycie Aldrassilu.$B$BMożemy żyć wieki, ale będzie dla ciebie lepiej, jeśli nie każesz mu czekać...",
    ["O"] = "Pomów z Tenaronem Stormgripem na szczycie Aldrassilu w Shadowglen.",
    ["T"] = "Wezwanie Tenarona",
  },
  [921] = {
    ["D"] = "Nadszedł czas, $N, abyś $gruszył:ruszyła; w świat w poszukiwaniu swego przeznaczenia. Nim jednak opuścisz granice naszego zaczarowanego lasu, musisz się jeszcze wiele nauczyć o naszej najnowszej historii.$B$BOd czasu Bitwy o Górę Hyjal pośród naszego ludu zaszło wiele zmian. Nordrassil jest teraz bladym cieniem tego, czym był niegdyś; jego mocy użyto do pokonania Archimonde\'a i przepędzenia Płonącego Legionu...$B$BMusisz wykonać pewne zadanie. Udaj się do księżycowej studni na północ od Aldrassilu i przynieś mi fiolkę jej wód.",
    ["O"] = "Napełnij Crystal Phial i odnieś ją Tenaronowi Stormgripowi, na szczyt Aldrassilu.",
    ["T"] = "Korona Ziemi",
  },
  [922] = {
    ["D"] = "$N, czy $gmógłbyś:mogłabyś; zanieść jedno z nasion, które mi $gprzyniosłeś:przyniosłaś;, mojemu przyjacielowi, Rellianowi Greenspyre? To druid z Darnassus; kiedy ostatni raz z nim rozmawiałem, podzielał moje zainteresowanie sprawą drzewiaków. Nawet miał parę pomysłów i wierzę, że będzie wdzięczny za okaz nasiona, na którym mógłby pracować.$B$BDziękuję ci, $N, $gbyłeś:byłaś; dla mnie wspaniałym pomocnikiem. Mam nadzieję, że pewnego dnia ujrzysz owoce mych badań.$B$BRelliana można zazwyczaj spotkać, jak przechadza się ścieżkami Enklawy Cenariusa w Darnassus.",
    ["O"] = "Przynieś Timberling Seed do Relliana Greenspyre z Darnassus.",
    ["T"] = "Rellian Greenspyre",
  },
  [923] = {
    ["D"] = "W drzewiakach narasta brutalność. Próbujemy odnaleźć jej źródło, lecz nim się to uda... dla bezpieczeństwa Teldrassilu musimy wyciąć drzewiaki, dla których jest już za późno na pomoc. Najbardziej skażone są te, które włóczą się wokół jeziora Wellspring na północy Teldrassilu. Muszą zostać unicestwione!$B$BWybij tamtejsze drzewiaki i zbierz porastające je mechate narośla. Przynieś je do mnie, bym mógł je spalić.",
    ["O"] = "Przynieś 5 Mossy Tumors do Relliana Greenspyre w Darnassus.",
    ["T"] = "Narośla",
  },
  [924] = {
    ["D"] = "Nasiono Demona to potężne narzędzie w rękach Płonącego Legionu. Spoczywa w jaskini na Dreadmist Peak, ponad demonicznym ołtarzem ognia.$B$BPrzygotowałem kamienie mocy, które, osadzone w pobliżu nasiona, zerwą jego połączenie z Legionem.$B$BZabierz kamień ze stołu i zanieś go na ołtarz ognia na Dreadmist Peak. Kieruj się na zachód, a gdy dojdziesz do rozwidlenia dróg, skręć na północ. Szczyt zobaczysz po swej lewej stronie. Najbezpieczniej wspiąć się po północnej ścianie.$B$BŚpiesz się - moc kamienia gaśnie wraz z czasem.",
    ["O"] = "Weź Flawed Power Stone. Dostarcz go na Altar of Fire, zanim się wyczerpie, następnie wróć do Ak\'Zelotha.",
    ["T"] = "Nasiono demona",
  },
  [925] = {
    ["D"] = "Mówią, że Cairne Bloodhoof to jeden z największych bohaterów Hordy wszystkich czasów. Kiedy dorosnę, tez chciałbym być bohaterem!$B$BZnasz Cairne\'a, $N? Mógłbyś mi wyświadczyć przysługę? Mógłbyś zdobyć dla mnie odcisk jego kopyta? Nie wiem, jak go poprosić, pewnie nie ma czasu dla kogoś takiego jak ja... ale ty! Ty jesteś poszukiwaczem przygód, tak jak on! Jestem pewny, że dałby ci swój odcisk!$B$BProszę...",
    ["O"] = "Udaj się do Thunder Bluff, aby zdobyć odcisk kopyta Cairne\'a Bloodhoofa dla swego podopiecznego.",
    ["T"] = "Odcisk kopyta Cairne\'a",
  },
  [926] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Wadliwy kamień mocy",
  },
  [927] = {
    ["D"] = "Serce Blackmoss the Fetid pokrywa ciemny, oleisty mech. Tak naprawdę na to, że jest to serce, wskazuje tylko powolne, rytmiczne bicie... Bicie, które można wyczuć nawet teraz.$B$BByć może Denalan chciałby je obejrzeć.",
    ["O"] = "Przynieś Moss-twined Heart Denalanowi niedaleko jeziora Al\'Ameth.",
    ["T"] = "Omszałe serce",
  },
  [928] = {
    ["D"] = "Choć mógłbym powiedzieć ci więcej o księżycowych studniach i Teldrassilu, muszę wysłać cię w drogę. Corithras Moonrage będzie cię oczekiwał. Przelałem wodę, którą $gprzyniosłeś:przyniosłaś;, do tego naczynia. Zaniesiesz je do niego.$B$BZnajdź Corithrasa. Spotkasz go przy księżycowej studni Dolanaaru. Opuść Shadowglen obierając drogę wiodącą z Aldrassilu na południe; trzymaj się dalej bruku, gdy skręci na zachód.$B$BUważaj jednak, $N, aby nie schodzić z drogi. Ostatnimi czasy las pełen jest groźnych bestii.",
    ["O"] = "Zabierz Partially Filled Vessel do Corithrasa Moonrage\'a z Dolanaaru.",
    ["T"] = "Korona Ziemi",
  },
  [929] = {
    ["D"] = "Po pierwsze, pozwól że powiem ci więcej o zadaniu, które musisz wykonać. Druidzi z Darnassus korzystają z wód księżycowych studni Teldrassilu i czasami muszą zostać one uzupełnione. Przy pomocy tych specjalnie przygotowanych fiolek możesz nabrać wody z księżycowych studni.$B$BZabierz to naczynie na wschód, do księżycowej studni na obrzeżach wioski Starbreeze, i napełnij je tamtejszą wodą; następnie wróć do mnie. Kiedy skończysz, opowiem ci dalszą część historii, poczynając od momentu, w którym skończył Tenaron.",
    ["O"] = "Napełnij Jade Phial i odnieś ją Corithrasowi Moonrage\'owi z Dolanaaru.",
    ["T"] = "Korona Ziemi",
  },
  [930] = {
    ["D"] = "Pomiędzy liśćmi świecącej rośliny wisi duży, okrągły owoc.$B$BDenalan na pewno chciałby go zbadać.",
    ["O"] = "Zanieś Świecący Owoc Denalanowi, nad jeziorem Al\'Ameth.",
    ["T"] = "Świecący owoc",
  },
  [931] = {
    ["D"] = "Liście rośliny migoczą w leśnym świetle, tworząc wirującą, pulsującą aurę.$B$BSądzisz, że Denalan chciałby otrzymać jeden okaz.",
    ["O"] = "Zanieś Shimmering Frond do Denalana, nad jezioro Al\'Ameth.",
    ["T"] = "Błyskający liść",
  },
  [932] = {
    ["D"] = "Muszę cię ostrzec, $N; ta sprawa musi pozostać między nami. Satyry są już dla nas wystarczająco kłopotliwe, a ten znalazł się zbyt blisko naszego domu.$B$BZwie się Lordem Melenasem. Zamieszkuje pobliską jaskinię w Spaczonej Skale, gdzie panuje nad dużą grupą grellich wojowników. Jego serce jest czarne jak noc i planuje coś ohydnego.$B$BMusisz odnaleźć go w jego jaskini, zaledwie kilka kroków na północ stąd i przynieść mi jego głowę.",
    ["O"] = "Zabij Lorda Melenasa i przynieś jego głowę Tallonkaiemu Swiftrootowi z Dolanaaru.",
    ["T"] = "Wypaczona nienawiść",
  },
  [933] = {
    ["D"] = "Kolejna księżycowa studnia leży na południowy wschód od wejścia do Darnassus, u brzegów Sadzawek Arlithriena. Z powodów narastającej agresji i ataków furbolgów ze szczepu Sękatej Sosny, Wartowniczki mają trudności z patrolowaniem tego obszaru.$B$BSzukając studni zachowaj czujność i trzymaj broń pod ręką.",
    ["O"] = "Napełnij Tourmaline Phial i odnieś ją Corithrasowi Moonrage\'owi z Dolanaaru.",
    ["T"] = "Korona Ziemi",
  },
  [934] = {
    ["D"] = "Jednak nie wszystko poszło dobrze z zasadzeniem Teldrassilu. Staghelm starannie przygotował plany dotyczące wzrostu nowego Drzewa Świata, lecz był jeden mały problem, problem z którym wiele kłopotów w Teldrassilu może być powiązanych.$B$BJednak o tym porozmawiamy później. Musisz pójść do ostatniej księżycowej studni, na północny zachód Polany Wyroczni. Pod konarami Drzewa Wyroczni znajduje się pierwsza i najsilniejsza z naszych studni. Zdobądź fiolkę jej wody i wróć do mnie.",
    ["O"] = "Wypełnij Amethyst Phial i przynieś ją z powrotem do Corithrasa Moonrage\'a w Dolanaar.",
    ["T"] = "Korona ziemi",
  },
  [935] = {
    ["D"] = "Bez błogosławieństwa Alexstraszy, Dawczyni Życia i Nozdormu Bezczasowego, wzrost Teldrassilu nie był prawidłowy. Widziano jak dziwne stworzenia wyłaniały się spod konarów drzewa, zaś oszalałe furbolgi atakowały podróżników.$B$BMogę mieć jedynie nadzieję, że Arcydruid znajdzie szybko rozwiązanie tego problemu. Wleję zawartość fiolek, które mi przyniosłeś, do jednego naczynia i zaniesiesz je do Darnassus.$B$BWręcz je Fandralowi Staghelmowi, znajdziesz go w gaju druidów.",
    ["O"] = "Przynieś Filled Vessel do Arcydruida Fandrala Staghelma w Darnassus.",
    ["T"] = "Korona Ziemi",
  },
  [936] = {
    ["D"] = "Przepraszam $C, ale jeśli to możliwe, chciałbym zająć ci chwilkę twojego czasu.$B$BKrąg Cenarionu w Thunder Bluff poszukuje doświadczonych poszukiwaczy przygód, takich jak ty, do pomocy w ważnym projekcie badawczym. Choć nie znam szczegółów, mogę cię poinformować, że nikt inny jak sam Hamuul Runetotem dowodzi tym przedsięwzięciem. $B$BProszę - jeśli jesteś $gzainteresowany:zainteresowana;, pomów z nim osobiście na Wzniesieniu Starszych w obrębie Thunder Bluff.",
    ["O"] = "Porozmawiaj z Arcydruidem Hamuulem Runetotemem z Thunder Bluff.",
    ["T"] = "Pomoc dla Arcydruida Runetotema",
  },
  [937] = {
    ["D"] = "Wraz z małą grupą wartowniczek zostałam tu skierowana, by chronić Drzewo Wyroczni przed harpiami, które pozakładały gniazda wokół całej polany. Krok po kroku próbowałyśmy je odeprzeć.$B$BKiedy Drzewo Wyroczni usiłowało wysłać do Darnassus gońca z raportem, harpie zaatakowały go i zabiły.$B$BJeżeli czujesz się na siłach, by podołać zadaniu, udaj się do ich gniazd, zabij je i wróć do mnie z ich pasami na dowód swego czynu.",
    ["O"] = "Zdobądź 6 Bloodfeather Belts i przynieś je wartowniczce Arynii Cloudsbreak, w Oracle Glade.",
    ["T"] = "Zaczarowana polana",
  },
  [938] = {
    ["D"] = "Futro nocnej pantery ma charakterystyczny szary kolor, wtapiający się w otaczający las. Dostrzegasz, że leżąca pantera jest poważnie ranna; głębokie skaleczenie ciągnie się przez jej grzbiet i brzuch.$B$BPodnosi głowę i spogląda na ciebie szklistymi, rozumnymi, niebieskimi oczami. Wygląda na to, że chce pójść za tobą.",
    ["O"] = "Odprowadź Mist do wartowniczki Arynii Cloudsbreak przy księżycowej studni niedaleko Drzewa Wyroczni.",
    ["T"] = "Mgła",
  },
  [939] = {
    ["D"] = "Spoglądasz na prosty, drewniany flet, który podniosłeś po pokonaniu Xavarica.$B$BSękate drewno robi solidne wrażenie, ale gdy obracasz je w rękach, wydaje się, że spirale i wzory na powierzchni instrumentu zaczynają ruszać się i wirować. Nagle zaczynasz odczuwać lęk...$B$BPotrząsasz głową, pewna, że umysł płata ci figle.$B$BMożliwe, że inne satyry posiadają wskazówki dotyczące tego, co znalazłeś. Zanieś swe znaleziska druidce Eridan Bluewind mieszkającej na południu Felwood.",
    ["O"] = "Przynieś Flute of Xavaric i 5 próbek Jadefire Felbind do Eridan Bluewind z południowego Felwood.",
    ["T"] = "Flet Xavarica",
  },
  [940] = {
    ["D"] = "Las szepcze o twoim odważnym wyczynie, $N. Gdy tylko harpie zostały usunięte ze swych gniazd, poczułam, jak błogi spokój rozprzestrzenia się po całym lesie, a jego mieszkańcy znów czują się bezpiecznie. Bałam się wysyłać kolejnego posłańca do Arcydruida, ale teraz wiem, że ty bezpiecznie dostarczysz mu moją wiadomość.$B$BZanieś mu to i wiedz, że las będzie nad tobą czuwał na twej drodze do lasu z kamienia.",
    ["O"] = "Dostarcz raport Drzewa Wyroczni do Arcydruida Fandrala Staghelma z Darnassus.",
    ["T"] = "Teldrassil",
  },
  [941] = {
    ["D"] = "Usunąłem ten cuchnący porost z serca, ale ono wciąż jest skażone...$B$BSpróbuj umieścić je w mojej donicy. Jest wypełniona odżywczą glebą, która może oczyścić i uleczyć serce.",
    ["O"] = "Zasadź Tainted Heart w donicy Denalana.",
    ["T"] = "Zasadzenie serca",
  },
  [942] = {
    ["D"] = "Ta skamieniałość jest uderzająco podobna do tej, którą niegdyś widziałem w Ironforge. Archeolog Flagongut przyniósł ją na doroczną konferencję Ligi Odkrywców. Wierzył, że ma ona moc, którą można w jakiś sposób wydobyć.$B$BOstatnie, co słyszałem o Flagongucie, to wzmianka, że zaszył się w Tawernie Deepwater w Porcie Menethilów, oczekując na eskortę do miejsca wykopalisk Whelgara. Spotkaj się z nim i pokaż mu skamiałość Remtravela. Może będzie potrafił objaśnić tajemnicę z przeszłości.$B$BStatek do portu odpływa z Auberdine.",
    ["O"] = "Zanieś tajemniczą skamieniałość archeologowi Flagongutowi z Menethil Harbor.",
    ["T"] = "Roztargniony poszukiwacz",
  },
  [943] = {
    ["D"] = "Poszukiwacz Whelgar posiada teraz oryginalną skamielinę na swych wykopaliskach w Wetlands. Kiedy odnalazłem Kamień Relu, sądziłem, że to jest klucz do rozszyfrowania tajemnicy skamieliny.$B$BGdy podróżowałem drogą, by spotkać się z Whelgarem, zostałem zaatakowany przez jaszczury i relikt przepadł. Nie mam pojęcia, która z tych cętkowanych bestii połknęła kamień, ale jeżeli go odzyskasz, będę mógł wydobyć moc z tych artefaktów.$B$BPrzynieś mi zarówno Kamień Relu, jak i oryginalną skamielinę.",
    ["O"] = "Archeolog Flagongut z Menethil Harbor chce, żebyś $gprzyniósł:przyniosła; mu Stone of Relu i Flagongut\'s Fossil.",
    ["T"] = "Roztargniony poszukiwacz",
  },
  [944] = {
    ["D"] = "Dziwne, że nagi są tutaj, w Darkshore. Ale wciąż dziwniejsza jest... obecność Młota Zmierzchu. Ten kult czci dawnych, starych panów ziemi. Władców pokonanych wieki temu.$B$BMaster\'s Glaive na południu to miejsce, gdzie poległ taki dawny władca.$B$BIdź tam i poszukaj więcej czcicieli Młota Zmierzchu.$B$BWeź ten flakon wróżebny. Po przeszukaniu Master\'s Glaive użyj go do stworzenia czary wróżebnej. Potem porozmawiaj ze mną za jej pośrednictwem.",
    ["O"] = "Zdobądź informacje, następnie użyj Phial of Scrying, by stworzyć Scrying Bowl. Użyj czary do rozmowy z Onu.",
    ["T"] = "Glewia Mistrza",
  },
  [945] = {
    ["D"] = "Ratunku!$B$BSpacerowałam wokół Master\'s Glaive, a ci brudni kultyści mnie otoczyli. Dobrze, że umiem się chować!!$B$BPomożesz mi się stąd wydostać? Muszę też powiadomić moją siostrę Therysil, że wszystko ze mną w porządku. Znajdziesz ją na południu, w Ashenvale, w Świątyni Aessiny.",
    ["O"] = "Pomóż uciec Therylune, potem powiedz Therysil z Shrine of Aessina, że jej siostra jest bezpieczna.",
    ["T"] = "Ucieczka Therylune",
  },
  [946] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [947] = {
    ["D"] = "Obmyśliłem miksturę, która wymaga rzadkich grzybów; grzybów rosnących wyłącznie w określonej jaskini. Leży ona za Wodospadami Cliffspring, idąc na wschód, a potem nieco na północ, wzdłuż gór.$B$BPoszedłbym tam sam, ale Zagajnik Prastarych poradził mi trzymać się z daleka od tego miejsca. Nasi czcigodni sprzymierzeńcy wyczuli, że w jaskini czai się nowe zło zagrażające Darkshore.$B$BProszę, zbierz dla mnie te grzyby, $N. Przy okazji zbadaj jaskinię, by potwierdzić obawy Prastarych.",
    ["O"] = "Przynieś 5 Scaber Stalks i 1 Death Cap do Barithrasa Moonshade\'a z Auberdine.",
    ["T"] = "Jaskiniowe grzyby",
  },
  [948] = {
    ["D"] = "Onu, Prastary Wiedzy z Zagajnika Prastarych, wie o twojej podróży do Wodospadów Cliffwater i życzy sobie z tobą rozmawiać. Zagajnik leży na południe stąd; mieści się niedaleko gór.$B$BPrastarzy są mądrzy i cierpliwi. Ale jeśli Onu chce zasięgnąć twej rady w sprawie tego, co $gwidziałeś:widziałaś; przy wodospadach, obawiam się, że jest to sprawa niecierpiąca zwłoki.",
    ["O"] = "Porozmawiaj z Onu w Grove of the Ancients.",
    ["T"] = "Onu",
  },
  [949] = {
    ["D"] = "Nie znamy przyczyny obecności Młota Zmierzchu przy Master\'s Glaive.. Ale musi ona być mroczna.$B$BPrzeszukaj ich obóz... Poszukaj jakiejś rzeczy, która mogłaby wyjawić nam ich intencje.$B$BBowiem musimy najpierw odgadnąć ich intencje, nim poczynimy plany.",
    ["O"] = "Znajdź wskazówkę w obozie Twilight\'s Hammer przy Master\'s Glaive.",
    ["T"] = "Obóz Zmierzchu",
  },
  [950] = {
    ["D"] = "Zaglądanie w Księgę Zmierzchu prowadzi do szaleństwa. Po ledwie spojrzeniu tekst zaczyna się rozpływać i tańczyć, a niegdyś piękna kaligrafia zmienia się w groteskowe kształty.$B$BWyrwanie karty pełnej szalonych gryzmołów to wszystko, co możesz zrobić, nim popadniesz w omdlenie.",
    ["O"] = "Przynieś Onu zdobyte Insane Scribbles.",
    ["T"] = "Powrót do Onu",
  },
  [951] = {
    ["D"] = "Pergamin, który $gznalazłeś:znalazłaś; w Master\'s Glaive, to strona starożytnego tekstu... napisanego przez elfy! Ciąży na nim potężna klątwa, zbrukała go też skaza Młota Zmierzchu, ale wygląda na to, że kult używa starożytnej elfiej magii, by sprowadzić swych starych władców do naszego świata.$B$BUdaj się na północny wschód, do ruin Mathystry, i poszukaj starożytnych reliktów wśród trawy i zniszczonych skał. Może badając je, odkryjemy, jak Młot Zmierzchu ma zamiar wykorzystać elfią magię.",
    ["O"] = "Przynieś 6 Mathystra Relics do Onu z Grove of the Ancients.",
    ["T"] = "Relikty Mathystry",
  },
  [952] = {
    ["D"] = "Jeśli $gmiałeś:miałaś; dość czasu, by służyć za posłańca u Drzewa Wyroczni, jestem pewien, że mogę powierzyć ci zadanie dostarczenia wiadomości do Zagajnika Prastarych w Darkshore, na południe od Auberdine.$B$BZapewne będziesz $gmusiał:musiała; zapewnić sobie transport na hipogryfie. Ale wierzę, że chociaż na tyle cię stać. Zabierz to do Onu, Prastarego Wiedzy. Oczekiwał wieści ode mnie nawet wówczas, gdy ja czekałem na wieści z Polany Wyroczni.",
    ["O"] = "Dostarcz wiadomość Fandrala do Onu z Grove of the Ancients w Darkshore, na południe od Auberdine.",
    ["T"] = "Zagajnik Prastarych",
  },
  [953] = {
    ["D"] = "Na wschód stąd znajdziesz ruiny Ameth\'Aran. Obecnie spotkasz tam jedynie niespokojne duchy Szlachetnie Urodzonych, którzy niegdyś zamieszkiwali tamte mury; niegdyś był to także dom sług Azshary, w którym mogli oni swobodnie praktykować swą potężną magię.$B$BZostałam wysłana w celu zbadania ruin. Gdy się tam znalazłam, natknęłam się na dwie duże tablice, na których ktoś nabazgrał historię Ameth\'Aran i jego upadku. Gdy czytałam runy, obstąpiły mnie duchy, więc uciekłam.$B$BProszę, jeśli tylko możesz, udaj się do ruin i odczytaj dla mnie te tablice.",
    ["O"] = "Zbadaj tablice opowiadające o Ameth\'Aran i jego upadku; potem wróć do wartowniczki Tyshy Moonblade w Darkshore.",
    ["T"] = "Upadek Ameth\'Aran",
  },
  [954] = {
    ["D"] = "Leżące na wschodzie Ruiny Bashal\'Aran roją się od demonicznych sług. Chochliki i satyry, które osiedliły się w tym rejonie, żywią się magiczną energią tego miejsca; wciąż z niej czerpią, zwiększając swą moc.$B$BMimo to zauważyłem, że jest tam kapliczka, do której się nie zbliżają. W zachodniej części ruin, ze szczytu małego urwiska, emanuje dziwna, niebieska aura... Tam musi znajdować się przyczyna niechęci demonów.$B$BChciałbym, żebyś to $gsprawdził:sprawdziła;.",
    ["O"] = "Znajdź źródło dziwnej niebieskiej aury w ruinach Bashal\'Aran.",
    ["T"] = "Bashal\'Aran",
  },
  [955] = {
    ["D"] = "Gdybym miał opowiedzieć historię mojego życia, bez wątpienia wyczerpałoby to twoją cierpliwość. Powiedzmy, że było ono długie i bolesne, a ta widmowa forma jest chyba najgorszą jego częścią.$B$BWiężą mnie tutaj magiczne kajdany. Moje słowa mogą brzmieć nieszczerze, ale zapewniam cię, że będę wdzięczny ponad wszelkie wyobrażenie, jeśli pomożesz mi odnaleźć to, co mnie tu trzyma. Niewoli mnie pieczęć, lecz badając kolczyki chochlików i grelli, może natrafię na jej ślad.",
    ["O"] = "Zdobądź 8 Grell Earrings dla Asteriona z Bashal\'Aran.",
    ["T"] = "Bashal\'Aran",
  },
  [956] = {
    ["D"] = "Jeśli grelle miały styczność z pieczęcią, która utrzymuje moje odwieczne więzienie, chyba potrafię powiedzieć, co się wydarzyło. Bez wątpienia dostała się ona w ręce przewodzącego nimi satyra.$B$BJestem przekonany, że tak właśnie się stało. Jeden z satyrów musi posiadać pieczęć. Gdyby udało ci się ją odzyskać, byłbym już tak bliski przekroczenia krat tego więzienia, że łzy napływają mi do oczu.",
    ["O"] = "Zdobądź Ancient Moonstone Seal i przynieś ją Asterionowi z Bashal\'Aran.",
    ["T"] = "Bashal\'Aran",
  },
  [957] = {
    ["D"] = "Pieczęć tworząca me więzienie, jest dziełem jednego z najpotężniejszych Szlachetnie Urodzonych. W Ameth\'Aran, ruinach na południe stąd, bliźniaczych tutejszym, do dziś płonie pradawny, błękitny płomień. W nim pieczęć może zostać zniszczona.$B$BUważaj tam jednak na siebie...",
    ["O"] = "Zniszcz Ancient Moonstone Seal w pradawnym płomieniu w Ameth\'Aran, po czym wróć do Asteriona, do Bashal\'Aran.",
    ["T"] = "Bashal\'Aran",
  },
  [958] = {
    ["D"] = "Istnieje zadanie, które chciałbym ci powierzyć. $C.$B$BCzy dane ci już było zobaczyć ruiny Ameth\'Aran? Jeśli nie - znajdziesz je po wschodniej stronie głównego traktu, nieco na południe stąd. Niegdyś były domem wielu potężnych Szlachetnie Urodzonych; teraz są pozostałością po zniszczeniach, do których doprowadzili.$B$BWartowniczki poinformowały mnie, że duchy Szlachetnie Urodzonych przetrwały i nadal władają narzędziami swej starożytnej magii. Musisz zdobyć te relikty, abyśmy mogli je zniszczyć.",
    ["O"] = "Odzyskaj 7 Highborne Relics dla Thundrisa Windweavera z Auberdine.",
    ["T"] = "Narzędzia Szlachetnie Urodzonych",
  },
  [959] = {
    ["D"] = "Uups!$B$BJak widzisz, mieliśmy tu mały wypadek! Poranny ładunek z Booty Bay był ogromny. Oooogromny, mówię ci! Nigdy jeszcze nie widziałem tylu skrzyń. Cóż, próbowałem wszystko przyspieszyć, więc zacząłem wyładowywać troszkę więcej niż sprzęt mógł wytrzymać. I wtedy wszystko zaczęło się walić.$B$BZanim zorientowałem się, co się stało, zobaczyłem jak ta szumowina, Mad Magglish, ucieka z butelką 99-letniego porto pod pachą. Goniłem go aż do Wailing Caverns (46,36). Nie ma mowy, żebym tam wszedł.$B$BMoże tobie starczy odwagi, by go znaleźć (52,55).",
    ["O"] = "Operator Dźwigu z Ratchet, Bigglefuz, chce twojej pomocy w odzyskaniu butelki 99-letniego Porto od Mada Magglisha ukrywającego się w Wailing Caverns.",
    ["T"] = "Kłopoty w dokach",
  },
  [960] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Onu rozmyśla",
  },
  [961] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Onu medytuje",
  },
  [962] = {
    ["D"] = "Królewskie Stowarzyszenie Aptekarzy z siedzibą we wspaniałym Undercity w Lordaeronie przysłało mnie tu ze szczególną misją, $N. Być może zechcesz wspomóc mnie, a zatem i Mroczną Panią, w naszych wysiłkach zmierzających do poprawienia sytuacji Opuszczonych.$B$BOstatnimi czasy badałam rzadki okaz flory zwany żmijokwiatem. Sądzę, że w większych ilościach tego ziela kryje się wielki potencjał.$B$BNiestety żmijokwiat rośnie wyłącznie w najciemniejszych zakamarkach Wailing Caverns - niebezpiecznego systemu podziemnych korytarzy, położonego w Barrens.",
    ["O"] = "Aptekarka Zamah z Thunder Bluff chce, byś $gzebrał:zebrała; 10 okazów Serpentbloom.",
    ["T"] = "Żmijokwiat",
  },
  [963] = {
    ["D"] = "Dowiedziałem się, że na skutek bitew nad Studnią Wieczności Ameth\'Aran zostało zniszczone, a jego ludność zginęła, łącznie z mą ukochaną, Anayą.$B$BNigdy bym nie przypuszczał, że tysiące lat później wspomnienie Anayi wciąż będzie nawiedzać moje sny. Kiedy otępiały wędrowałem po lasach Darkshore, znalazłem się w ruinach Ameth\'Aran... gdzie ujrzałem nawiedzoną duszę mojej ukochanej.$B$BMusi zostać oswobodzona, lecz sam nie mam serca tego zrobić. Jej dusza musi zostać zniszczona.",
    ["O"] = "Uwolnij duszę Anayi Dawnrunner i przynieś jej wisiorek Cerelleanowi Whiteclawowi z Auberdine.",
    ["T"] = "Z miłości odwiecznej",
  },
  [964] = {
    ["D"] = "Klucz do Scholomance zwany jest Kluczem Szkieletowym. Musi zostać wykuty ze szczątków szkieletu - właściwie to kilku - i utwardzony we właściwej formie przy pomocy najmocniejszych metali. Sygnet mocy jakiejś istoty, która potrafi swobodnie otwierać przejście do Scholomance, ostatecznie sprawi, że klucz będzie działał.$B$BJednak zacznijmy od podstaw, $N. By wykuć klucz, potrzebujemy fragmentów szkieletów. Te z obrębu Andorhalu powinny zawierać to, czego potrzebujemy, ale te poza murami też mogą się nadać.",
    ["O"] = "Przynieś 15 Skeletal Fragments do Aptekarza Dithersa z Bulwark, w Western Plaguelands.",
    ["T"] = "Fragmenty szkieletu",
  },
  [965] = {
    ["D"] = "Witaj, $R7. Jestem Elissa Starbreeze, moim obowiązkiem jest zadbanie, by nic nie mogło zaszkodzić Auberdine.$B$BW tym celu wysłałam Balthule\'a Shadowstrike, by przyjrzał się dziwnym zdarzeniom zachodzącym w pobliżu Wieży Althalaxxa na północnym wschodzie.$B$BJuż dawno powinien wrócić. Martwię się, że mógł natknąć się w lesie na jakieś niespodziewane zagrożenie. Byłabym bardzo wdzięczna, gdybyś go $godnalazł i sprawdził:odnalazła i sprawdziła;, czy wszystko z nim w porządku.",
    ["O"] = "Znajdź Balthule\'a Shadowstrike\'a w pobliżu Tower of Althalaxx w Darkshore.",
    ["T"] = "Wieża Althalaxxa",
  },
  [966] = {
    ["D"] = "Grupa czarnoksiężników osiedliła się w okolicy i wnętrzu wieży. Wróciłbym wcześniej do Auberdine, by złożyć raport Elissie, ale bałem się, że jeśli mnie tu nie będzie, mogę coś przegapić.$B$BDelgren podejrzewał, że takie towarzystwo może zbierać się w pobliżu wieży, ale nie znał powodów.$B$BW moje ręce wpadło trochę pozostałości noszonych przez czarnoksiężników pergaminów, ale potrzebuję ich więcej, by rozwiązać tę zagadkę. Ostrzegam cię, nie zapuszczaj się do wnętrza wieży, gdyż tamtejsi czarnoksiężnicy są o wiele potężniejsi!",
    ["O"] = "Zbierz 4 Worn Parchments dla Balthule\'a Shadowstrike\'a z okolic Tower of Althalaxx.",
    ["T"] = "Wieża Althalaxxa",
  },
  [967] = {
    ["D"] = "Mój mistrz, Delgren Odkupiciel, jest paladynem, który miłościwie zaoferował swoją pomoc w obronie naszych lasów przed siłami demonów i nieumarłych. Nauczył mnie wiele o Świętym Blasku i sztuce wojennej.$B$BDelgren musi natychmiast dowiedzieć się o działaniach kultu.$B$BZnajdziesz go daleko na południe stąd, przy Posterunku Maestra w lesie Ashenvale. Nie trać czasu, obawiam się, że zagrożenie ze strony kultu Mrocznego Pasma rośnie z każdą godziną.",
    ["O"] = "Dostarcz list Balthule\'a do Delgrena the Purifiera w Ashenvale Forest.",
    ["T"] = "Wieża Althalaxxa",
  },
  [968] = {
    ["D"] = "Mimo że okropnie zniszczony i porysowany, widoczny na okładce tytuł księgi jest wciąż czytelny:$B$B\"Moce podziemia\"$B$BWnętrze książki zajmuje lista niewymawialnych imion ze źle wróżącymi przydomkami, metodami czczenia i preferowanymi ofiarami... wiele z nich obejmuje żywe, humanoidalne stworzenia.$B$BNa wewnętrznej stronie okładki księgi widnieją słowa: \"Runy i Przesądy Bonegripa, Opuszczona Pieczara, Ironforge. Właściciel: Gerrig Bonegrip.\"$B$BJeśli Bonegrip sprzedaje tego typu książki, być może zechce tę odkupić.",
    ["O"] = "Przynieś Księgę: \"The Powers Below\" do Gerriga Bonegripa z Forlorn Cavern w Ironforge.",
    ["T"] = "\"Moce podziemia\"",
  },
  [969] = {
    ["D"] = "Ach, starczy rzut oka na ciebie - chcesz, by ci zrobić talizman szczęścia. Mau\'ari zawsze wie!$B$BNa południu znajdziesz kanion i olbrzymy stworzone z kryształów lodu. Olbrzymy czasem noszą ich odłamki, ale zawsze możesz je samemu zebrać z kanionu. Mają potężne właściwości odbijające.$B$BPrzynieś mi 4 kryształy lodowych maczug, a mój talizman szczęścia będzie twój.",
    ["O"] = "Zbierz 4 Frostmaul Shards dla Znachorki Mau\'ari z Everlook.",
    ["T"] = "Niech szczęście będzie z tobą",
  },
  [970] = {
    ["D"] = "List Balthule\'a jest ponury. Ten Kult Mrocznego Pasma stanowi cierń w moim boku, który musi być usunięty. Miałem do czynienia z paroma szumowinami z Mrocznego Pasma na północny wschód stąd, w Ordil\'Aran. Jeden z nich posiada klejnot dusz, który jak sądzę ukrywa tajemnicę mocy kultu.$B$BPrzynieś mi go, a będę w stanie rozszyfrować kryjące się w nim sekrety.",
    ["O"] = "Zbierz Glowing Soul Gem i zwróć go do Delgrena the Purifier z Maestra\'s Post.",
    ["T"] = "Wieża Althalaxx",
  },
  [971] = {
    ["D"] = "Jak zapewne wiesz, kolekcjonuję wiedzę. Starą wiedzę. Potężną wiedzę. Wiedzę, która otwiera bramy; wiedzę mogącą obudzić Uśpionych.$B$BKrążą pogłoski o starym fragmencie wiedzy, Manuskrypcie Lorgalis, spoczywającym na dnie Blackfathom Deeps w Ashenvale. To miejsce to stara siedziba od dawna martwych elfów. Elfów, które posiadały wielką wiedzę, zanim ich miasto zamieniło się w ruinę.$B$BPrzeszukaj Blackfathom Deeps w poszukiwaniu manuskryptu. Zrób to, a nigdy ci tego nie zapomnę. Nawet gdy... skończą się dni.",
    ["O"] = "Przynieś Lorgalis Manuscript do Gerriga Bonegripa z Forlorn Cavern w Ironforge.",
    ["T"] = "Wiedza w głębinach",
  },
  [972] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Sapta wody",
  },
  [973] = {
    ["D"] = "Ilkrud Magthrull. Tak, wiem coś o nim. Jest potężnym orczym czarnoksiężnikiem, który osiedlił się przy Kaplicy Ognistej Blizny, miejscu wielkiego zła w południowo-zachodnim Ashenvale.$B$BDotychczas był niewiele więcej niż irytujący, więc nie rozprawiłem się z nim, ale wygląda na to, że przyszedł na niego czas.",
    ["O"] = "Przynieś księgę Ilkruda Magthrulla do Delgrena the Purifier z Maestra\'s Post.",
    ["T"] = "Wieża Althalaxxa",
  },
  [974] = {
    ["D"] = "Tutejsze gorące źródła są dla mnie tajemnicą. Skąd pochodzi to gorąco?$B$BPatrząc na odległość sadzawek od Fire Plume Ridge zastanawiam się, czy wulkan nie ma z tym czegoś wspólnego. Skonstruowałem termometr do robienia odczytów temperatury na wulkanie; chciałbym znaleźć jego najgorętszą część. Przyrząd podaje temperaturę w stopniach Kraklenheita!$B$BProszę, weź go i zmierz temperaturę każdego napotkanego punktu gorąca na wulkanie!",
    ["O"] = "Krakle z Un\'Goro Crater chce, byś znalazł najgorętsze miejsce w Fire Plume Ridge.$B$BZa każdym razem, gdy znajdziesz gorące miejsce, kliknij prawym przyciskiem na termometr, by zmierzyć temperaturę. Kontynuuj poszukiwania, póki nie znajdziesz najgorętszego z nich.",
    ["T"] = "Poszukiwanie źródła",
  },
  [975] = {
    ["D"] = "Teraz, nim dam ci ten amulet, lepiej wyjaśnię jak go używać.$B$BJeśli będziesz go nosić ze sobą, znajdziesz pewne przedmioty, upuszczone przez stworzenia, które pokonasz. Jeśli nie będziesz miał amuletu, nie znajdziesz ich. Zrozumiałeś?$B$BPoznasz te przedmioty po nazwie - zwą się E\'ko. Jeśli znajdziesz jakikolwiek z nich, po prostu przynieś je starej Mau\'ari, ona ci pomoże.$B$BPoczekaj chwilę, a umocuję twój amulet.",
    ["O"] = "Porozmawiaj za moment z Witch Doctor Mau\'ari, by otrzymać amulet szczęścia.",
    ["T"] = "Skrytka Mau\'ari",
  },
  [976] = {
    ["D"] = "Delgren prosił mnie o dostarczenie listów i zapasów do Wartowniczki Starbreeze z Auberdine, ale nie chcę wyruszać samotnie. Groźni nieprzyjaciele kręcą się po lesie, a ja nie chciałbym ryzykować dostania się tych pakunków w złe ręce.$B$BJeśli ty i inni zachcielibyście pełnić rolę strażników, mógłbym wyruszyć od razu. Nie mam wątpliwości, że z twoją ochroną bezpiecznie dostarczylibyśmy te dobra do Auberdine.",
    ["O"] = "Porozmawiaj z Delgren the Purifier w Maestra\'s Post po bezpiecznym przeprowadzeniu Feera przez Ashenvale Forest.",
    ["T"] = "Zapasy dla Auberdine",
  },
  [977] = {
    ["D"] = "Moi przyjaciele zawsze wpadają do mnie ze wspaniałymi pomysłami. Nigdy nie sądziłam, że mogę się z nimi równać... aż do dziś! Właśnie opracowałam projekt czegoś wspaniałego! Jeśli obiecasz, że nikomu nie powiesz, zdradzę ci mój sekret...$B$BZamierzam stworzyć mechanicznego yeti! Moi przyjaciele nie tylko wystraszą się, kiedy go zobaczą, ale kiedy im przejdzie, będą też pod wrażeniem!$B$BNa początek potrzebuję grubych futer lodowokolcych yeti. Pomożesz? Znajdziesz je na południowym wschodzie.",
    ["O"] = "Zdobądź 10 Pristine Yeti Horns dla Umi Rumplesnicker z Everlook.",
    ["T"] = "Jesteśmy tam, yeti?",
  },
  [978] = {
    ["D"] = "Wydaje się, że pióra kniejniaków z Hinterlands zawierają ślady magicznych właściwości. Te moce... nie wygląda na to, by te stworzenia nimi władały; bardziej prawdopodobne, że są wrodzoną cechą tego gatunku - nieodłączną częścią ich istoty.$B$BPodczas moich badań słyszałem, że duża populacja kniejniaków zamieszkuje ośnieżone ziemie Winterspring. Czy te stworzenia mają te same moce? Proszę, pomóż mi znaleźć odpowiedź. Udaj się do Winterspring i zdobądź pióra, potem wróć do mnie.",
    ["O"] = "Zdobądź 10 Opromienionych Piór z Winterspring, następnie wróć do Erelasa Ambersky z Rut\'theran Village.",
    ["T"] = "Opromienione kniejniaki",
  },
  [979] = {
    ["D"] = "Tak, tak, te pióra wydają się zawierać ten sam rodzaj magii, jaki zauważyłem poprzednio... Choć nie jestem pewien, co możemy znaleźć, nalegam, byś kontynuował poszukiwania odpowiedzi.$B$BMoja przyjaciółka wyruszyła ostatnio do Winterspring, by obserwować kniejniaki w ich naturalnym środowisku. Może postaraj się z nią spotkać i sprawdź, co odkryła?",
    ["O"] = "Znajdź Ranshallę we wschodnim Winterspring.",
    ["T"] = "Znajdź Ranshallę",
  },
  [980] = {
    ["D"] = "Więc, słyszałem o innych gorących źródłach w miejscu zwanym Winterspring, daleko na północ stąd. Dziwne jest to, że w tamtej okolicy nie ma żadnych wulkanów. Interesujące, wiem.$B$BCóż, jeśli chcesz dowiedzieć się więcej, musisz dotrzeć do Winterspring i porozmawiać z moją przyjaciółką. Zwie się Donova Snowden; znajdziesz ją właśnie w okolicy tamtejszych gorących źródeł.$B$BDziękuję raz jeszcze za pomoc przy moim termometrze! Do zobaczenia!",
    ["O"] = "Udaj się do Winterspring i porozmawiaj z Donovą Snowden.",
    ["T"] = "Nowe źródła",
  },
  [981] = {
    ["D"] = "Za cały trud włożony w pracę, zasługujesz na dobre wynagrodzenie. Wróc do Delgrena i powiedz mu, że Athrikus Narassin leży martwy i jest to twoja zasługa, i że kult Mrocznego Pasma jest pokonany i rozbity.",
    ["O"] = "Porozmawiaj z Delgren the Purifer w Maestra\'s Post",
    ["T"] = "Wieża Althalaxxa",
  },
  [982] = {
    ["D"] = "U wybrzeża Darkshore, na północ stąd, spoczywają dwa wraki statków - \"Srebrnego Świtu\" i \"Welonu Mgieł\". Jakiś czas temu, kiedy obydwa statki przemierzały rozległe morze podczas żeglugi do Auberdine, zostały zaatakowane przez przeklęte murloki. Leżą teraz na dnie oceanu jako trofea napastników.$B$BObydwóm kapitanom nie poszczęściło się tamtej nocy, a ich dzienniki i dobytek wciąż spoczywają w kapitańskich skrzyniach. Chcę, byś je dla nas $godzyskał:odzyskała;; wiele znaczą dla przebywających wciąż w okolicy członków załogi.",
    ["O"] = "Odnajdź Kasetkę \"Srebrnego Świtu\" i Kasetkę \"Welonu Mgieł\" dla Gorbolda Steelhanda z Auberdine. Obydwa przedmioty można znaleźć na pokładach wraków statków na północ od wioski.",
    ["T"] = "Głęboki ocean, rozległe morze",
  },
  [983] = {
    ["D"] = "Hej! Pomóż mi przy moim najnowszym wynalazku - brzęczydle. Pozwala rozmawiać z innymi na odległość!$B$BMoże już jakieś $gwidziałeś:widziałaś;; wyglądają jak skrzynki z dźwigniami. Niestety, wymagają ciągłej konserwacji.$B$BKażde ma inny problem, ale wpadłem na doskonały pomysł. Ustawiłem je w pobliżu zwierząt, z których można pozyskać potrzebne do naprawy elementy. Ostatnio popsuło się Brzęczydło 827. Znajdziesz je rzut kamieniem na południe od Auberdine. Potrzeba ci będzie 6 nóg pełzaków, by je naprawić. Zapłacę...",
    ["O"] = "Zbierz 6 Crawler Legs i umieść je w Buzzbox 827.",
    ["T"] = "Brzęczydło 827",
  },
  [984] = {
    ["D"] = "Kilku moich braci zostało uratowanych z rąk skażonych furbolgów z Teldrassilu, a ja przyrzekłem powstrzymać takie potworności, nim kolejny z naszego rodzaju odniesie rany... czy też gorzej.$B$BZauważyłem już ślady skażenia w Darkshore, ale muszę znaleźć jeszcze dowody na jego rozprzestrzenianie się. Myślę, że logicznie będzie kontynuować poszukiwania pośród furbolgów. $gMógłbyś:Mogłabyś; sprawdzić, czy w którymś z ich obozów znajdziesz oznaki skażenia?",
    ["O"] = "Znajdź obóz skażonych furbolgów w Darkshore i wróć do Terenthisa z Auberdine.",
    ["T"] = "Jak duże to zagrożenie?",
  },
  [985] = {
    ["D"] = "$gDowiodłeś już, żeś biegły:Dowiodłaś już, żeś biegła; w śledzeniu przeciwnika, $N. Czy równie dobrze sprawdzisz się w walce z nim?$B$BNie każdy poszukiwacz przygód przenosi otwartą walkę nad sztukę skradania się i uników.$B$BJeśli myślisz, że podołasz zadaniu, udaj się do obozu furbolgów na południe od Auberdine, który stanowi obecnie największe zagrożenie dla naszych ludzi. Znajdziesz tam członków plemienia Czarnolasu. Zabij 8 tropicieli i 5 wiatromówców, a potem wróć tutaj, do mnie.",
    ["O"] = "Zabij 8 Blackwood Pathfinders i 5 Windtalkers, a następnie wróć do Terenthisa, do Auberdine.",
    ["T"] = "Jak duże to zagrożenie?",
  },
  [986] = {
    ["D"] = "Twoje umiejętności pomogły mi już w mych działaniach, $N. Czy mogę znów poprosić cię o pomoc? Chodzi o Grimclawa i jego mistrza Volcora. Ponadto mogę sprawić ci magiczny płaszcz, który pozwoli ci kroczyć niepostrzeżenie wśród stworzeń Darkshore, gdy będziesz go szukać.$B$BBy stworzyć ten płaszcz, będę potrzebował świetnych skór księżycowych panter - ich samców lub matriarch; tylko ich skóry są dostatecznie duże. Te koty znajdziesz na północ stąd, niedaleko rzeki Wildbend, lub dużo dalej na południe, bliżej Ashenvale.",
    ["O"] = "Znajdź 5 Fine Moonstalker Pelts i wróć z nimi do Terenthisa z Auberdine.",
    ["T"] = "Zaginiony mistrz",
  },
  [987] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [990] = {
    ["D"] = "Moja pani, Raene Wolfrunner, oczekuje cię w mieście Astranaar, znajdującym się w Ashenvale. Być może z twoją pomocą uda nam się przynajmniej ograniczyć skażenie, które opanowało tamtejsze strony.$B$BSkieruj się na południe i trzymaj się blisko drogi - podążając dokładnie wzdłuż niej, nie będziesz $gmiał:miała; żadnych problemów.",
    ["O"] = "Znajdź Raene Wolfrunner w Ashenvale.",
    ["T"] = "Podróż do Ashenvale",
  },
  [991] = {
    ["D"] = "Przyjaciel, którego znam od dawna, również pomaga Wartowniczkom tutaj w Ashenvale, ale jeszcze nie powrócił.$B$BProwadził poszukiwania przedmiotu, który według niego miał osłabić ataki furbolgów na naszych ludzi - różdżki stworzonej przez martwego już, diabolicznego czarodzieja.$B$BNim stąd wyruszył, wspomniał coś o klejnocie do owej różdżki.$B$BSądził, że klejnot jest prawdopodobnie ukryty w kapliczce nad Jeziorem Falathim u podnóża zachodnich gór. Przedmiot był tam przetrzymywany, zanim kapliczka została opanowana przez murloki.$B$BZnajdź mego przyjaciela, proszę.",
    ["O"] = "Odnajdź Teronisa w Ashenvale.",
    ["T"] = "Oczyszczenie Raene",
  },
  [992] = {
    ["D"] = "Jeśli jesteś zainteresowany, mamy wolne stanowisko czasowego młodszego mierniczego Gadgetzańskiej Kompanii Wodnej!$B$BSkoro nomadzi opanowali nasze studnie, musimy zdobyć nowe wolne źródła wody! Na tej pustyni dość łatwo jest zaopatrzyć się w wodę, ale tylko tym, którzy są wystarczająco sprytni by znaleźć ją jako pierwsi.$B$BWeź ten różdżkownik i zdobądź za jego pomocą próbkę tego życiodajnego płynu ze źródełka niedaleko Sandsorrow Watch. To to miejsce, wokół którego kręcą się trolle. Przynieś użyte urządzenie z powrotem do mnie, gdy już zrobisz co należy!",
    ["O"] = "Użyj nieużywanego różdżkownika w pobliżu zbiornika wodnego przy Sandsorrow Watch. Gdy będziesz już w posiadaniu próbki, wróć z użytym różdżkownikiem do Seniora Surveyora Fizzledowsera z Gadgetzanu.",
    ["T"] = "Poszukiwanie wody dla Gadgetzanu",
  },
  [993] = {
    ["D"] = "Płaszcz jest gotowy, $N. Nadszedł czas na odnalezienie Volcora. Mam tylko nadzieję, że zdążymy.$B$BPłaszcz jest magiczny; raz użyty, nie podziała długo - może pięć minut. Decyzja, kiedy go użyć, należy do ciebie: sugeruję zaczekać, aż znajdziesz Grimclawa.$B$BJeśli to, co mi powiedział jest prawdą, znajdziesz jego mistrza w jaskini na południe stąd. Grimclaw będzie czekał na ciebie przy drodze. Pomachaj do niego, gdy go ujrzysz, a on wskaże ci drogę do swojego mistrza.",
    ["O"] = "Odnajdź Volcora w Darkshore i daj mu Enchanted Moonstalker Cloak.",
    ["T"] = "Zaginiony mistrz",
  },
  [994] = {
    ["D"] = "W porządku,$N, przebijmy się przez nie. Ruszajmy, gdy tylko będziesz $ggotowy:gotowa;. Musimy utorować sobie przejście do drogi - Grimclaw powinien wciąż tam być. Potem możemy się rozdzielić.$B$BTerenthis zechce natychmiast usłyszeć twoją wersję wydarzeń, więc jak tylko się stąd wydostaniemy, ruszaj do Auberdine.",
    ["O"] = "Chroń Volcora, dopóki nie dotrzecie do drogi, potem porozmawiaj z Terenthisem w Auberdine.",
    ["T"] = "Ucieczka dzięki użyciu siły",
  },
  [995] = {
    ["D"] = "W porządku więc... jeśli jesteś tego $gpewny:pewna;, wyślizgniemy się stąd. Ruszajmy, gdy tylko będziesz $ggotowy:gotowa;.$B$BPamiętaj, po tym jak uciekniesz, spotkaj się z Terenthisem w Auberdine. Dotrę tam samodzielnie, jako że prawdopodobnie będę poruszał się szybciej niż ty.",
    ["O"] = "Ucieknij z jaskini furbolgów i spotkaj się z Terenthisem w Auberdine.",
    ["T"] = "Ucieczka dzięki skradaniu się",
  },
  [996] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Chore wiatrokwiecie",
  },
  [997] = {
    ["D"] = "Wybierasz się na południe? Nad jezioro Al\'Ameth? Jeśli tak, miałabym do ciebie prośbę...$B$BMój przyjaciel Denalan rozbił obóz nad wschodnim krańcem jeziora, tam prowadzi badania i eksperymenty nad roślinnością Teldrassilu. Prosił o paczkę rzadkiej ziemi z Darnassus. Ta spóźniła się i dopiero dotarła do Dolanaaru.$B$B$gMógłbyś:Mogłabyś; ją do niego zanieść?",
    ["O"] = "Zanieś paczkę rzadkiej ziemi do Denalana znad jeziora Al\'Ameth.",
    ["T"] = "Ziemia Denalana",
  },
  [998] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Skażone wiatrokwiecie",
  },
  [999] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "When Dreams Turn to Nightmares",
  },
  [1000] = {
    ["D"] = "Uwaga, bohaterowie!$B$BKrąg Cenarionu poszukuje uzdolnionych osób do pomocy w odkrywaniu odległych zakątków Kalimdoru! Daleko na zachód od Gadgetzanu i Tanaris leży zakazane pustkowie pełne niewyobrażalnych niebezpieczeństw, więc Krąg potrzebuje pełnych zapału, honorowych pełnomocników do działania w swym imieniu.$B$BWszyscy zainteresowani winni postarać się o spotkanie z Kręgiem. Pomówcie z Arcydruidem Hamuulem Runetotemem na Wzniesieniu Starszych w Thunder Bluff, aby dowiedzieć się więcej!",
    ["O"] = "Porozmawiaj z Arcydruidem Hamuulem Runetotemem na Elder Rise w Thunder Bluff o wezwaniu Kręgu Cenarionu do odkrywania zakątków Kalimdoru.",
    ["T"] = "Nowe pogranicze",
  },
  [1001] = {
    ["D"] = "Z wnętrza maszyny rozlega się cichy głos.$B$B\"Tu Wizbang! Następne brzęczydło jest na północ od Auberdine, na plaży.$B$BTo tak, to brzęczydło ma numer 411, a do naprawy będziesz $gpotrzebował:potrzebowała; 3 oczu threshodonów. Znajdziesz je w głębi wód, w pobliżu wybrzeża! Threshodony z Darkshore... *hik*... Przepraszam, odbiło mi się...$B$BTak jak ostatnim razem, wrzuć je środka, a otrzymasz nagrodę. *Hik*... Co? Nie, czuję się świetnie!\"",
    ["O"] = "Pozyskaj 3 Thresher Eyes z Darkshore Threshers zamieszkujących głębiny morza w okolicy Buzzbox 411.",
    ["T"] = "Brzęczydło 411",
  },
  [1002] = {
    ["D"] = "Brzęczydło wydaje z siebie serię trzasków, po czym słyszysz ze środka głos Wizbanga.$B$B\"Nasztępne bszęczydło ma numer 323. Na północz od Auberdine ale... polewasz? Szo? Och, jeszt na droze, więs nie powinno byś trudno je snaleść, koło mosztu.\"$B$BWizbang mamrocze coś niezrozumiale, po czym znowu słyszysz odgłos głośnego przełykania.$B$B\"Będzie szeba kłuf ksziężyczowych pszeszladofcóf... 6 sztuk.\"",
    ["O"] = "Zbierz 6 Moonstalker Fangs i umieść je w Buzzbox 323.",
    ["T"] = "Brzęczydło 323",
  },
  [1003] = {
    ["D"] = "Pomiędzy odgłosami wrzenia i kapania przebija się bełkotliwy głos Wizbanga.$B$B\"Nasztępny bęzie drogą na południe. Snajziesz je łatwo... na poboszu... obok płotu. Chyba ukryłem je w jakiź kszakach... Kszszakach. Hahaha... Taa, Bszęczydło 525 wymaha poziwiałych szkalpów z tych ziwych osztowych miziów. Rany, ale trudne szłówko. Oższtowy... Hehehe...\"$B$BSłyszysz kolejne odgłosy przełykania, po czym maszyna milknie. Po chwili jednak ponownie dobiega cię głos:$B$B\"Sztery!\"",
    ["O"] = "Zdobądź 4 Grizzled Scalps z Grizzled Thistle Bears występujących na południe od Auberdine i umieść je w Buzzbox 525.",
    ["T"] = "Brzęczydło 525",
  },
  [1004] = {
    ["D"] = "Uwaga, bohaterowie!$B$BKrąg Cenariona szuka dobrze zbudowanych jednostek, aby pomóc im w przeszukiwaniu nowej, stałej granicy Kalimdoru! Zakazane bezdroże jest pełne niewyobrażalnych niebezpieczeństw, które leżą daleko na zachód w Tanaris i Gadgetzan, a także Krąg potrzebuje honorowych pełnomocników, aby działali w ich imieniu.$B$BWszystkie zainteresowane osoby powinny żądać audiencji z Kręgiem Cenariona. Porozmawiaj z Arcydruidem Hamuulem Runetotemem na Wzniesieniu Starszych w Thunder Bluff po więcej informacji!",
    ["O"] = "Porozmawiaj z Arcydruidem Hamuulem Runetotemem w części Elder Rise w Thunder Bluff o Kręgu Cenariona i wezwij do zbadania granic Kalimdoru.",
    ["T"] = "Nowa Granica",
  },
  [1005] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "What Lurks Beyond",
  },
  [1006] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "What Lies Beyond",
  },
  [1007] = {
    ["D"] = "Powierzę ci pewne zadanie, $N.$B$BGdy na moim małym stateczku sunąłem po falach przelewających się nad zatopionymi ruinami miasta Zoram, z wody wyłoniły się nagi, zaatakowały mnie i poszarpały swoimi szponami! Uciekłem, zabierając ze sobą co tylko mogłem, i rozbiłem ten niewielki obóz.$B$BJednak kiedy dotarłem do brzegu i biegłem... straciłem mą cenną własność.$B$B$N, proszę, odnajdź miejsce zasadzki u wybrzeża na północy i poszukaj starożytnej statuetki. Jest powodem, dla którego zdecydowałem się stawić czoło niebezpieczeństwom Zoram Strand.",
    ["O"] = "Przynieś Talenowi, przebywającemu w obozie nieopodal Zoram Strand, Starożytną Statuetkę.",
    ["T"] = "Starożytna statuetka",
  },
  [1008] = {
    ["D"] = "Zło czai się na naszym północno-zachodnim wybrzeżu, znanym jako Zoram Strand.$B$BSpoczywa tam miasto Zoram, zniszczone podczas Rozdarcia i zatopione na dnie morza. Od wieków pozostaje ono stracone dla elfów. Stracone i niemalże zapomniane...$B$BTeraz powróciły nagi, lecz nie wiemy dlaczego. Ale powód nie jest tak ważny: musimy wybić te potwory i zepchnąć je z powrotem w głąb morza!$B$BWróć do mnie, gdy wykonasz swe zadanie.",
    ["O"] = "Przynieś 20 Wrathtail Heads do Shindrell Swiftfire z Astranaaru.",
    ["T"] = "Mielizna Zoram",
  },
  [1009] = {
    ["D"] = "Obawiam się, że sekrety antycznej statuetki pozostaną ukryte, chyba że znajdziemy klucz do jej zamka.$B$BKluczem jest Pierścień Zoram. Należał do władców miasta, zanim pochłonęły je fale wzbudzone Rozdarciem Świata.$B$BPierścień zaginął na wiele lat, jednakże w ostatnim czasie odnalazły go nagi.$B$BIch przywódczyni, Ruuzel, osiedliła się na wyspie na północnym skraju Zoram. Proszę, $N, odzyskaj dla mnie ten pierścień!",
    ["O"] = "Przynieś Ring of Zoram do Talena nieopodal Zoram Strand.",
    ["T"] = "Ruuzel",
  },
  [1010] = {
    ["D"] = "Istnieje pewien rodzaj rośliny, która niegdyś rosła w starych ruinach Bathran\'s Haunt, na północ stąd. Roślinę tę zwano Bathran\'s Hair, znana była z leczenia chorób duszy.$B$BW wiosce jest chore dziecko i wydaje mi się, że chodzi o coś więcej niż tylko chorobę ciała. Udasz się do Bathran\'s Haunt i poszukasz tej rośliny? Może być mi potrzebna, by właściwie leczyć to dziecko.$B$BBathran\'s Haunt leży na północ od Maestra\'s Post i na południe od granicy z Darkshore.",
    ["O"] = "Przynieś 5 Bathran\'s Hair do Orendila Broadleafa z Ashenvale.",
    ["T"] = "Włosy Bathrana",
  },
  [1011] = {
    ["D"] = "Opuszczeni, nieumarłe ramię Hordy, wśliznęli się do Ashenvale i przyczaili w naszych ruinach i kurhanach. Sądzimy, że ich celem jest rozprzestrzenić zarazę na ziemiach nocnych elfów. Musimy zdobyć pewność!$B$BOpuszczeni mają obóz na południe stąd, niedaleko Kurhanów Dor\'Danil, gdzie tworzą trucizny, które następnie przelewają do butelek. Wywalcz sobie drogę do obozu i ukradnij butelkę takiej trucizny. Zbadam ją i odkryję jej zastosowanie.",
    ["O"] = "Przynieś Butlę Trucizny Kaynethowi Stillwindowi z Forest Song.",
    ["T"] = "Choroby Opuszczonych",
  },
  [1012] = {
    ["D"] = "Kiedy trudziłem się nad truciznami Opuszczonych, miałem wizję. Wizję druidów z Kurhanów Dor\'Danil, otrutych... zamordowanych przez nieumarłych! Teraz są błądzącymi zjawami, oddzielonymi od ciał i doprowadzonymi do szaleństwa...$B$BAby dusze druidów mogły któregoś dnia znaleźć ukojenie, musisz udać się do Kurhanów Dor\'Danil i zniszczyć ich niegdyś wielkich przywódców: Taneela Darkwooda, Uthila Mooncalla i Mavorisa Cloudsbreaka.$B$BZrób to, po czym wróć do mnie.",
    ["O"] = "Zabij druidów: Taneela Darkwooda, Uthila Mooncalla, Mavorisa Cloudsbreaka i wróć do Kaynetha Stillwinda z Forest Song.",
    ["T"] = "Szaleni druidzi",
  },
  [1013] = {
    ["D"] = "$N, w Shadowfang Keep znajduje się księga, Book of Ur, która byłaby cennym nabytkiem do mojej kolekcji. Przed nadejściem Plagi Ur był wielkim magiem z Dalaranu, zaś jego badania na temat innych światów stanowią wielką wartość dla... pewnych ugrupowań spośród Opuszczonych.$B$BUdaj się do Shadowfang Keep i znajdź tę księgę. Przynieś mi ją, a poinformuję o twych zasługach naszą Mroczną Panią...",
    ["O"] = "Przynieś Book of Ur do Keeper Bel\'dugur z Aptekarium Undercity.",
    ["T"] = "Księga Ura",
  },
  [1014] = {
    ["D"] = "Arugal wciąż zasiada w Shadowfang Keep. Nie możemy ogłosić Lasu strategiczną fortecą Mrocznej Pani, póki Arugal nie zostanie zgładzony.$B$BDopilnuję, by jego magia została unicestwiona, $N. Ale twoim rękom pozostawiam zapewnienie, ażeby Arugal poznał chłodne oblicze śmierci, na którą zasługuje.$B$BUdaj się do Shadowfang Keep i raz na zawsze przynieś kres odrażającym zaklęciom Arugala! Przynieś mi głowę tego plugawca!",
    ["O"] = "Zabij Arugala i przynieś jego głowę Dalarowi Dawnweaverowi z Sepulcher.",
    ["T"] = "Arugal musi umrzeć",
  },
  [1015] = {
    ["D"] = "Uwaga, bohaterowie!$B$BKrąg Cenarionu poszukuje uzdolnionych osób do pomocy w odkrywaniu odległych zakątków Kalimdoru! Daleko na zachód od Gadgetzanu i Tanaris leży zakazane pustkowie pełne niewyobrażalnych niebezpieczeństw, więc Krąg potrzebuje pełnych zapału, honorowych pełnomocników do działania w swym imieniu.$B$BWszyscy zainteresowani winni postarać się o spotkanie z Kręgiem. Pomówcie z Arcydruidem Darnassus, Fandralem Staghelmem, aby dowiedzieć się więcej!",
    ["O"] = "Porozmawiaj z Arcydruidem Fandralem Staghelmem z Cenarion Enclave w Darnassus o wezwaniu Kręgu Cenarionu do odkrywania zakątków Kalimdoru.",
    ["T"] = "Nowe pogranicze",
  },
  [1016] = {
    ["D"] = "Weź ten zwój wróżebny - wskaże twórcę tych żywiołaków. Ale będziesz $gpotrzebował:potrzebowała; czegoś z nich jako składnika do rzucenia zaklęcia - ich obręcze świetnie się do tego nadadzą.$B$BParę nietkniętych obręczy tych istot powinno wystarczyć. Inne nie mają dla naszych celów żadnego zastosowania, ale mogą być coś warte dla kupców, gdybyś $gchciał:chciała; je sprzedać. Gdy już zdobędziesz obręcze, uwolnij moc zwoju. Wróć do mnie z wynikami, a będziemy kontynuować.",
    ["O"] = "Zbierz 5 Intact Elemental Bracers i użyj na nich Divining Scroll. Następnie przynieś Divining Scroll do wartowniczki Velene Starstrike z Silverwind Refuge.",
    ["T"] = "Obręcze żywiołaków",
  },
  [1017] = {
    ["D"] = "Tylko jeden nieumarły mag w Barrens zdolny jest skazić tak wiele żywiołaków. To także jedyny mag dość głupi, żeby tego spróbować. Sarilus Foulborne rezyduje najprawdopodobniej na Szczycie Dreadmist, śmiejąc się ze mnie.$B$B$N, musisz udać się na ziemie wroga i pokonać tego niegodziwca. Mam już dosyć tego durnia; musimy pokazać mu, co spotyka tych, którzy igrają z Wartowniczkami.$B$BZabij go i przynieś mi jego głowę. Bądź jednak $gostrożny:ostrożna;, Horda może na ciebie czekać.",
    ["O"] = "Zabij Sarilusa Foulborne\'a i przynieś jego głowę wartowniczce Velene Strarstrike z Silverwind Refuge.",
    ["T"] = "Mag przywoływacz",
  },
  [1018] = {
    ["D"] = "Poświęćcie chwilę uwagi, bohaterowie!$B$BKrąg Cenarionu poszukuje śmiałków gotowych do pomocy w eksploracji nowych rozległych pograniczy Kalimdoru! Na zachód od Tanaris i Gadgetzan leżą zakazane ziemie pełne nieznanych niebezpieczeństw, więc Krąg potrzebuje emanujących zapałem i honorem osób gotowych do działania w jego sprawie.$B$BWszyscy zainteresowani niechaj skontaktują się z Kręgiem Cenarionu. Po więcej informacji zgłaszajcie się do Arcydruida Hamuula Runetotema na Wzniesieniu Starszych w Thunder Bluff .",
    ["O"] = "Porozmawiaj z Arcydruidem Hamuulem Runetotemem na Wzniesieniu Starszych w Thunder Bluff o wezwaniu Kręgu Cenarionu do eksploracji pograniczy Kalimdoru.",
    ["T"] = "Nowe Pogranicze",
  },
  [1019] = {
    ["D"] = "Poświęćcie chwilę uwagi, bohaterowie!$B$BKrąg Cenarionu poszukuje śmiałków gotowych do pomocy w eksploracji nowych rozległych pograniczy Kalimdoru! Daleko na zachód od Tanaris i Gadgetzan leżą zakazane ziemie pełne niewyobrażalnych niebezpieczeństw, więc Krąg potrzebuje emanujących zapałem i honorem pełnomocników, którzy będą działać w jego sprawie.$B$BWszyscy zainteresowani niechaj skontaktują się z Kręgiem Cenarionu. Po więcej informacji zgłoście się do Arcydruida z Darnassus, Fandrala Staghelma!",
    ["O"] = "Porozmawiaj z Arcydruidem Fandralem Staghelmem w Cenarion Enclave w Darnassus o wezwaniu Kręgu Cenarionu do eksploracji pograniczy Kalimdoru.",
    ["T"] = "Nowe Pogranicza",
  },
  [1020] = {
    ["D"] = "$N, sporządziłem lek, który, jak sądzę, może uleczyć chore dziecko. Zabierz go do Astranaaru i daj ojcu dziecka, Pelturasowi Whitemoonowi.$B$BAby dotrzeć do Astranaaru, podążaj drogą na południe, potem na wschód.",
    ["O"] = "Przynieś Orendil\'s Cure do Pelturasa Whitemoona z Astranaaru.",
    ["T"] = "Lek Orendila",
  },
  [1021] = {
    ["D"] = "Słuchaj, nie wiem, kim jesteś, ale potrzebuję twej pomocy. Moje siostry udały się odzyskać od satyrów Gałąź Cenariusa. Powiedziały, że niedługo wrócą, ale nie ma ich już od dwóch dni!$B$BMusisz je odnaleźć! Szukały ruin świątyni nocnych elfów w Xavian, na północny zachód stąd. Nie wiem, co myśleć. Szukaj Anilii, ona przewodziła poszukiwaniom.",
    ["O"] = "Znajdź Anilię w Xavian.",
    ["T"] = "Plugawe satyry! Driady w niebezpieczeństwie!",
  },
  [1022] = {
    ["D"] = "Choć włożyłyśmy wiele trudu w wygnanie demonów z leżącego na północy Felwood, nie odniosłyśmy większych sukcesów. Udało nam się utrzymać większość demonicznych bytów z dala od Ashenvale.$B$BNa północ, nieopodal granicy z Felwood, tajemniczy wilko-ludzie opanowali kaplicę Mel\'Thandris. Ich mrożące krew w żyłach wycie sprawiło, że tamtejszy obszar zyskał nazwę Doliny Skowytu. Przechowywany w kaplicy Tom Mel\'Thandris może rzucić nieco światła na sprawę tych wilko-ludzi.",
    ["O"] = "Udaj się do Howling Vale i przeczytaj Tome of Mel\'Thandris, następnie wróć do wartowniczki Melyrii Frostshadow z Forest Song.",
    ["T"] = "Dolina Skowytu",
  },
  [1023] = {
    ["D"] = "Przetrząsając dobytek Teronisa, znajdujesz dobrze zachowany dziennik.$B$BZabierasz dziennik i pozostawiasz ciało Teronisa.$B$BOstatnią rzeczą do wykonania jest znalezienie klejnotu, którego szukał Teronis. Raene wspomniała, że jest gdzieś w okolicy. Może posiada go któryś z murloków...",
    ["O"] = "Znajdź Glowing Gem i wróć do Raene Wolfrunner z Astranaaru z Dziennikiem Teronisa.",
    ["T"] = "Porządki Raene",
  },
  [1024] = {
    ["D"] = "Będziesz $gmusiał:musiała; przeprowadzić badania na własną rękę, ale z tego, co mówią notatki Teronisa, wygląda na to, że kolejną rzeczą, jaką musisz zrobić, jest odnalezienie pozostałych części wykonanej przez Dartola różdżki. Zaczęłabym od odwiedzenia księżycowej studni na wschód od Jeziora Iris. Gdy będziesz $ggotów:gotowa;, udaj się drogą, a kiedy dotrzesz do małego postoju z ławeczką po lewej stronie drogi, skręć na północ.$B$BDriada imieniem Shael\'dryn będzie odpowiedniejszym przewodnikiem w twej misji. Odszukaj ją.$B$BWeź klejnot ze sobą - Shael\'dryn będzie go potrzebować, by pomóc ci odtworzyć różdżkę.",
    ["O"] = "Odnajdź Shael\'dryn przy księżycowej studni na północnym wschodzie.",
    ["T"] = "Porządki Raene",
  },
  [1025] = {
    ["D"] = "Zanim udasz się do księżycowej studni, mam dla ciebie inne zadanie, którym wspomożesz mieszkańców Ashenvale, jeżeli chcesz sprawdzić swe umiejętności.$B$BNieopodal drogi, na wschód przed rzeką Falfarren, furlbogi atakują wędrowców. Ich udręczone umysły karmią się strachem i krwią niewinnych podróżnych.$B$BWspomóż Wartowniczki w ochronie ziem, okazując tym bestiom tyleż miłosierdzia, ile one mają dla naszej rasy.$B$BWydaje mi się, że ich obóz znajduje się na południe od drogi... bądź $gostrożny:ostrożna;.",
    ["O"] = "Zabij 1 Den Watcher, 2 Ursas, 10 Totemics, i 12 Warriors plemienia Foulweald i wróć do Raene Wolfrunner z Astranaaru.",
    ["T"] = "Agresywna obrona",
  },
  [1026] = {
    ["D"] = "Chciałabym, by twoje wieści były lepsze.$B$BRaene ma rację, wiem wiele o tworze Dartola i drzewcach na tych ziemiach - a przynajmniej niegdyś wiedziałam. Są teraz skażone, ich natura została spaczona.$B$BJeśli pragniesz zdobyć kolejną część różdżki, będziesz $gmusiał:musiała; odnaleźć klucz, aby otworzyć skrzynię, w której spoczywa.$B$BDrewniany klucz nosi przy sobie jeden z drzewców na północny wschód stąd, nieopodal Felwood. Gdy już go zdobędziesz, poszukaj małej polanki na zachód od drogi w pobliżu granicy z Felwood... Skrzynia powinna gdzieś tam być.",
    ["O"] = "Znajdź Wooden Key i część Dartol\'s Rod, zanim powrócisz do Shael\'dryn przy księżycowej studni.",
    ["T"] = "Porządki Raene",
  },
  [1027] = {
    ["D"] = "Ostatnia część różdżki została oddana na przechowanie druidom z Dor\'danil. Nie mam pojęcia, gdzie ją ukryli. Wybacz, że nie mogę bardziej ci pomóc.$B$BMogę ci jedynie powiedzieć, żebyś $gpodążył:podążyła; drogą prowadzącą w Barrens. Druidzi mieli schronienie na wschód od tamtego traktu, ale nie posłużą ci pomocą: niedawno zostali zabici... to coś, o czym nie mam zbytniej ochoty myśleć.$B$BGdy znajdziesz ostatnią część, przynieś mi ją, a pomogę ci odtworzyć różdżkę.",
    ["O"] = "Znajdź ostatnią część Dartol\'s Rod i wróć do Shael\'dryn przy księżycowej studni.",
    ["T"] = "Porządki Raene",
  },
  [1028] = {
    ["D"] = "Oto kompletna różdżka, $N. Jej rekonstrukcja była prosta... dopiero znalezienie kapliczki o mocy zdolnej ją naładować będzie wyzwaniem.$B$BPrzy odrobinie chęci i skupienia, nie powinno być to zbyt trudne dla kogoś, kto zaszedł już tak daleko.$B$BPójdź na południowy wschód stąd - mało tam dróg, więc bądź $gostrożny:ostrożna; - i nie spuszczaj oka z północy. Kapliczka ukryta jest w górach otaczających tę polanę.$B$BNa miejscu umieść różdżkę w kapliczce... magia zajmie się resztą. Hehe.",
    ["O"] = "Znajdź ukrytą kapliczkę i naładuj mocą Dartol\'s Rod.",
    ["T"] = "Porządki Raene",
  },
  [1029] = {
    ["D"] = "Proponuję ci znaleźć Raene i dać jej znać, że różdżka jest gotowa. Jestem pewna, że będzie wiedzieć jaki ma być twój następny krok.$B$BPowodzenia, $N.",
    ["O"] = "Dostarcz Dartol\'s Rod do Raene Wolfrunner znajdującej się w Astranaar.",
    ["T"] = "Oczyszczenie Raene",
  },
  [1030] = {
    ["D"] = "Niestety, nie wiem co miał dokładnie na myśli.$B$BJeśli to co mówił o różdżce jest prawdą, to pozwoli ci przyjąć zupełnie inną formę. Ale nie mam pojęcia jaką.$B$BByć może, myślał użyć jej mocy by zbliżyć się do skażonych furbolgów, ale nawet te nieskażone mogłyby go zabić, jeśli nie zachowałby dostatecznej ostrożności. Przemieniony przez różdżkę, Dartol, mógłby porozmawiać z furbolgiem, nietkniętym magią spaczonego mchu.$B$BNa twoim miejscu, zacząłbym swe poszukiwania nad Jeziorem Mystral.",
    ["O"] = "Znajdź nieskażonego furbolga, i porozmawiaj z nim używając mocy Dartol\'s Rod of Transformation.",
    ["T"] = "Oczyszczenie Raene",
  },
  [1031] = {
    ["D"] = "Anilia kładzie ręce na twoich ramionach i przyciąga cię do siebie. Dysząc, nim zamyka oczu, a gdy ostatni, charczący oddech opuszcza jej ciało, wskazuje położony na północ łuk. \"On ją zabrał... Geltharis...\" W głębi serca wiesz, że ostatnim życzeniem Anilii jest ujrzeć Gałąź Cenariusa ponownie w rękach driad.",
    ["O"] = "Zabij Geltharisa i zwróć Gałąź Cenariusa Illiyanie z Forest Song.",
    ["T"] = "Gałąź Cenariusa",
  },
  [1032] = {
    ["D"] = "Nie mogę uwierzyć, że Anilia nie żyje... Bawiłyśmy się w lasach całymi dniami. Czuję się niemal... smutna.$B$BWiem, co może poprawić mi nastrój. Proszę, zabij satyry, które odebrały mi Anilię! Przynieś mi ich rogi jako dowód twych czynów, a zdobędziesz moją dozgonną wdzięczność.",
    ["O"] = "Przynieś 16 Rogów Satyrów do Illiyany z Forest Song.",
    ["T"] = "Wyrżnij satyry!",
  },
  [1033] = {
    ["D"] = "Miałem nadzieję, że lek Orendila uratuje Relarę, ale obawiam się, że tylko spowolnił chorobę toczącą me dziecko. Musimy znaleźć silniejsze lekarstwo! Na szczęście Orendil rozmawiał ze mną o innych środkach, gdyby pierwszy nie zadziałał.$B$BŁza Elune to specyficzny kamień występujący tylko w jednym miejscu: na wyspie na Jeziorze Iris, na wschód od Astranaaru. Orendil powiedział, że ten kamień zmyje zakażenie... proszę, $N, przynieś mi Łzę Elune i módl się, by zakończyła cierpienie mojego dziecka!",
    ["O"] = "Przynieś Łzę Elune Pelturasowi z Astranaaru.",
    ["T"] = "Łza Elune",
  },
  [1034] = {
    ["D"] = "Łza Elune obmyła me dziecko z części choroby. Jej koszmary osłabły, a ja dziękuję bogini za jej błogosławieństwo. Ale... wciąż pali ją gorączka.$B$BOrendil powiedział mi o zamarzniętym pyle występującym w Ruinach Gwiezdnego Pyłu. Możliwe, że zmniejszy on gorączkę Relary. Zbierz trochę pyłu i wróć proszę do mnie.$B$BRuiny leżą na południe, $N. Niech Elune przyspieszy twą podróż.",
    ["O"] = "Przynieś 5 Handfuls of Stardust Pelturasowi z Astranaaru.",
    ["T"] = "Ruiny Gwiezdnego Pyłu",
  },
  [1035] = {
    ["D"] = "Gorączka Relary minęła, ale wciąż jest bardzo słaba. Nie wierzę, by sam czas zwrócił jej siły, które straciła. Sądzę, że niezbędna tu będzie moc kamienia księżycowego.$B$BZbieraliśmy niegdyś kamienie księżycowe nad Jeziorem Upadłego Nieba na południowy wschód stąd... dopóki nie nadeszły bagienne stwory.$B$BIch przywódca, Wieszcz Cienistej Kniei, zgromadził wszystkie spadłe z nieba kamienie księżycowe. Musisz zabrać wieszczowi jeden z nich.$B$BBy tego dokonać, obawiam się, że będziesz $gmusiał:musiała; go zabić.",
    ["O"] = "Zabierz Fallen Moonstone z Shadethicket Oracle i przynieś go Pelturasowi z Astranaaru.",
    ["T"] = "Upadłe Niebo",
  },
  [1036] = {
    ["D"] = "$N... ta, słyszałem o tobie. Powiadają, że nie jesteś $gprzyjacielem:przyjaciółką; Booty Bay - tak jak my, Piraci Krwawych Żagli. Mistrz floty Firallon szuka takich krzepkich i dziarskich $gchłopaków:dziewczyn; jak ty do specjalnego zadania.$B$BJeśli jesteś $gzainteresowany:zainteresowana;, skieruj się na \"Crimson Veil\" i porozmawiaj z nim pod pokładem. Jest zacumowana na Dzikim Wybrzeżu na wschód stąd, obok \"Ścinacza Fal\" i \"Szczęścia Panienki\".",
    ["O"] = "Porozmawiaj z mistrzem floty Firallonem na pokładzie \"Crimson Vale\" u wybrzeży Stranglethorn Vale.",
    ["T"] = "Zatrzymaj się, rozbójniku",
  },
  [1037] = {
    ["D"] = "Velinde Starsong była moją poprzedniczką, tutaj, w lesie Ashenvale. Wpierw zdawało się, że miała sytuację w Felwood pod kontrolą, ale krok po kroku jej wysiłki zawodziły. Pewnego dnia po prostu znikła.$B$BZostałam tu przysłana, aby kontynuować jej pracę. Obawiam się jednak, że nic nie wiem o tej kapłance. Może Thyn\'tel Bladeweaver, jedna z poruczników Wartowniczek, zna szczegóły odnośnie jej zniknięcia; mnie w nie nie wtajemniczono.$B$BZ pewnością zrozumie ona wagę tych informacji.",
    ["O"] = "Pomów z Thyn\'tel Bladeweaver na Warrior\'s Terrace w Darnassus.",
    ["T"] = "Velinde Starsong",
  },
  [1038] = {
    ["D"] = "Tom Mel\'Thandris ci to pokazał? Sądzę, że pozwolenie ci na obejrzenie jej rzeczy nie wyrządzi większej szkody. Ten klucz pozwoli ci otworzyć kufer w baraku Wartowniczek, gdzie trzymamy jej rzeczy. Prowadziła dziennik, w którym spisywała swe czynności. To jedyne źródło, które może zawierać jakieś informacje.$B$BPowinnam ci powiedzieć, że Wartowniczki wierzą, że miała ona swój własny powód, by odejść, i że w każdej chwili może wrócić. W przeszłości ta kapłanka dużo zrobiła, by zyskać nasze zaufanie.",
    ["O"] = "Przeszukaj kufer Velinde w poszukiwaniu jej dziennika, następnie zwróć go wraz z kluczem do Thyn\'tel Bladeweaver z Darnassus.",
    ["T"] = "Działania Velinde",
  },
  [1039] = {
    ["D"] = "Ratchet jest jedynym portem w Barrens. Wielce prawdopodobne, że Velinde znalazła tam okręt handlowy, który zabrał ją do Jaskini Blackwater w Azeroth. Prowadziliśmy ograniczone kontakty z zawiadującymi portem goblinami, ale dokmistrz powinien mieć informacje o przybywających i odpływających na statkach pasażerach.$B$BPrzemierz Ashenvale drogą na południowy wschód, a znajdziesz się w Barrens. Uważaj gdzie stąpasz, wojownicy Hordy patrolują krainę. W porcie jednak będziesz $gbezpieczny:bezpieczna;.",
    ["O"] = "Pomów w Ratchet z dokmistrzem Dizzywigiem.",
    ["T"] = "Port na Pustkowiach",
  },
  [1040] = {
    ["D"] = "A tak, w końcu to znalazłem. Trzeba było mi powiedzieć, że przejeżdżała tędy tak dawno temu. Zobaczmy.$B$BVelinde. Wykupiła przeprawę do Booty Bay na Black Osprey. Nie mam tu nic więcej dopisane, więc zakładam, że bezpiecznie dotarła do portu.$B$BNie potrafię ci bardziej pomóc, ale ona pytała o podróż lądem po tamtej części świata, wspomniałem więc Ruzzgota, dowódcę karawan wyruszających z Booty Bay. Możliwe, że ta Velinde z nim pojechała.$B$BTeraz ruszaj dalej, nie mam dla ciebie całego dnia.",
    ["O"] = "Udaj się statkiem do Booty Bay i pomów z Caravaneerem Ruzzgotem.",
    ["T"] = "Przeprawa do Booty Bay",
  },
  [1041] = {
    ["D"] = "Okazuje się, że myliłem się co do ciebie, a to nie jest coś co dzieje się codziennie.$B$BTak się składa, że pamiętam tą Velinde, której szukasz. Nie każdego dnia kapłanka nocnych elfów chce podróżować z brudną, starą - ale jakże wspaniałą, jeśli potrzebujesz transportu - karawaną jak moja.$B$BRozdzieliliśmy się na drodze na północ, ona skierowała się w stronę Darkshire. Tamtejszy pisarz przechowuje wszelkiego rodzaju zapisy. Może wie coś pożytecznego.$B$BUważaj w dżungli, to zawsze było śmiercionośne miejsce, nawet za najlepszych czasów.",
    ["O"] = "Pomów z Clerkiem Daltrym z Darkshire.",
    ["T"] = "Szlak karawan",
  },
  [1042] = {
    ["D"] = "Nie mam żadnych zapisków dotyczących pobytu Velinde Starsong w Darkshire... choć, jeśli wolno mi coś powiedzieć, z trudem mogę wyobrazić sobie kapłankę nocnych elfów wynajmującą pokój w gospodzie, jeśli wiesz co mam na myśli.$B$BLecz worgeny, o których $gwspomniałeś:wspomniałaś;, to coś, o czym słyszałem. Ledwie wczoraj Calor przybył do miasta ze sznurem ich głów. Calor pracuje dla rodziny Carevinów. Łowców demonów, nieumarłych i innych monstrów. Pomów z Jonathanem, jest głową gospodarstwa.",
    ["O"] = "Pomów z Jonathanem Carevinem z Darkshire.",
    ["T"] = "Rodzina Carevinów",
  },
  [1043] = {
    ["D"] = "Twoja historia brzmi wiarygodnie... Nie rozumiem do końca twoich pobudek, ale jeśli twoje sprawy tutaj, w Duskwood, obejmują oczyszczenie lasu z jakiejkolwiek ilości worgenów, obędzie się bez rozumienia, w imię rezultatów.$B$BNa południe stąd jest kopalnia, którą opanowały worgeny... Pojawiły się znikąd, ale z tego, co wiemy, tam właśnie pokazały się po raz pierwszy.$B$BIdź zająć się swoją sprawą, ale chciałbym prosić cię, byś - jeśli odkryjesz coś ważnego - $gpodzielił:podzieliła; się tym ze mną. Przyjmiemy każdą pomoc w naszej wojnie przeciwko złu.",
    ["O"] = "Poszukaj śladów po Scythe of Elune, a następnie wróć do Jonathana Carevina, do Darkshire.",
    ["T"] = "Kosa Elune",
  },
  [1044] = {
    ["D"] = "Opanujemy kwestię worgenów, nie martw się o to. Zło, które twoja przyjaciółka sprowadziła do naszego lasu, zostanie powstrzymane. Nie winię jej za jej czyny. Dziwne wydarzenia dzieją się w tych czasach, a ciemność nie daje nam chwili wytchnienia.$B$BNie zamierzam zatrzymywać cię dłużej. Podejrzewam, że są inni, którzy powinni usłyszeć, co $godkryłeś:odkryłaś; w kopalniach Duskwood.",
    ["O"] = "Powróć do Thyn\'tel Bladeweaver z Darnassus.",
    ["T"] = "Odpowiedzi na pytania",
  },
  [1045] = {
    ["D"] = "Nocne elfy są stare jak świat, ale ich ignorancja niszczy ich świat. A teraz niszczy również nasz. Ale tego już nie jesteśmy w stanie więcej kontrolować...$B$BWinię elfy za wiele rzeczy, ale nadal sądzę, że powinniśmy być odpowiedzialni za nasze czyny. Nawet nieskażeni, jesteśmy w stanie dokonywać bardzo złych uczynków.$B$BRan Bloodtooth jest jednym z tych złych furbolgów. Pożąda mocy... a skażenie sprawiło tylko, że stał się silniejszy. Pałam nienawiścią do elfów, jednak nie pragnę złego dla ich potomstwa. Musimy więc zaprowadzić porządek w moim rodzaju.",
    ["O"] = "Zabij Rana Bloodtooth i 4 Bloodtooth Guards,kolejno wróć do Krolga niedaleko Lake Mystral.",
    ["T"] = "Oczyszczenie Raene",
  },
  [1046] = {
    ["D"] = "Wróć do swego plemienia i daj mu znać o swym zwycięstwie.$B$BPokaż swe trofeum i pław się w chwale...",
    ["O"] = "Przynieś Ran Bloodtooth\'s Skull i Dartol\'s Rod of Transformation do Raene Wolfrunner w Astranaar.",
    ["T"] = "Porządki Raene",
  },
  [1047] = {
    ["D"] = "Uwaga, bohaterowie!$B$BKrąg Cenariona poszukuje osób zdolnych do służby w pomocy przy odkrywaniu nowych, rozległych granic Kalimdoru! Zakazane bezdroża, pełne niewyobrażalnych niebezpieczeństw leżą na dalekim zachodzie od Tanaris i Gadgetzanu, dlatego Krąg potrzebuje chętnych i śmiałych ochotników do działań w ich imieniu.$B$BWszystkie zainteresowane osoby powinny szukać kontaktu z Kręgiem Cenariona. Po więcej informacji zgłoś się do Arcydruida w Darnassus, Fandrala Staghelma!",
    ["O"] = "Pomów z Arcydruidem Fandralem Staghelmem w Cenarion Enclave w Darnassus o wezwaniu Cenarion Circle do odkrywania granic Kalimdoru.",
    ["T"] = "Nowa Granica",
  },
  [1048] = {
    ["D"] = "Podczas, gdy Mroczna Pani dogląda uciskającego problemu ekspansji Króla Lisza na północy, ja robię wszystko, by kwestie leżące bliżej domu były odpowiednio rozwiązywane. $B$BNie mam wątpliwości, że ludzkie szkodniki nazywające siebie Szkarłatną Krucjatą starają się być największym cierniem w naszym domowym boku. Polana Tirisfal dosłownie roi się od tych czerwonych mrówek.$B$BRuszaj do ich Klasztoru, $C, przynieś zgubę Wysokiej Inkwizytor Whitemane oraz jego pachołkom.",
    ["O"] = "Zabij High Inquisitor Whitemane, Scarlet Commander Mograine, Heroda, Szkarłatnego Czempiona oraz Houndmaster Loksey, po czym raportuj z powrotem Varimathrasowi w Undercity.",
    ["T"] = "Do Szkarłatnego Klasztoru",
  },
  [1049] = {
    ["D"] = "Krąg Ziemi ma czyste intencje w stosunku do naszych zarażonych braci. Któż jednak zna motywy tych, którzy szeptają du uszu Rady Starszych?$B$BHistoria Opuszczonych, z którymi się sprzymierzyliśmy, pełna jest wyrachowania i zdrady. Zbyt szybko zawarliśmy ten pakt. Może Cairne dobrze by zrobił, gdyby posłuchał ostrzeżeń z Ogrimmaru.$B$BW zakamarkach Scarlet Monastery spoczywa \"Kompendium Upadłych\" strzeżone przez szalonych ludzkich fanatyków. Ich metody biorą się z szaleństwa, jednakże ich odkrycia mogą okazać się przydatne.",
    ["O"] = "Odzyskaj \"Kompendium Upadłych\" z Klasztoru położonego w Tirisfal Glades. Powróć z nim do Mędrca Truthseekera z Thunder Bluff.",
    ["T"] = "Kompendium Upadłych",
  },
  [1050] = {
    ["D"] = "Przyszłość jest nieunikniona! Wpadamy w nią, niczym krople deszczu w Wielkie Morze.$B$BMoże jednak dzięki poznaniu przeszłości, dowiemy się czego oczekiwać i lepiej przygotujemy się na nieznane.$B$BZanim wszystkie te straszne nieszczęścia spadły na Lordaeron, istniał pewien bastion wiedzy ukryty na Tirisfal Glades. Krążą pogłoski o księdze zwanej \"Mitologią Tytanów\", którą przechowywano w bibliotece starego Klasztoru.$B$BPrzynieś ją do mnie, a może razem uda nam się rozszyfrować sekrety przeszłości!",
    ["O"] = "Odzyskaj z Klasztoru \"Mitologię Tytanów\" i przynieś ją Bibliotekarce Mae Paledust z Ironforge.",
    ["T"] = "Mitologia Tytanów",
  },
  [1051] = {
    ["D"] = "Choć moja wola jest wolna, nie mogę już więcej służyć Mrocznej Pani. Czuję, że mój czas na Azeroth dobiega końca. Moja siła życiowa jest rozbita.$B$BInterrogator Vishas mi to zrobił! Torturował mnie tygodniami! Zabrał mój pierścionek zaręczynowy i dał go swojej żonie. Drań!$B$BZemsta... pragnę zemsty!$B$BNapuszony głupiec przechwalał się swoją szlachetną żoną Nancy, która żyje przy jeziorze Lordamere. Wytrop dziewkę, zgładź ją i przynieś mój pierścionek zaręczynowy do mojej żony, Moniki w Tarren Mill.$B$BWypełnij moje ostatnie życzenie....",
    ["O"] = "Zwróć Vorrel Sengutz\'s pierścionek zaręczynowy do Moniki Sengutz w Tarren Mill.",
    ["T"] = "Zemsta Vorrela",
  },
  [1052] = {
    ["D"] = "My Scarlet Crusade rościmy prawa do twierdz od Hearthglen po Tirisfal Glades. Jesteśmy dumni z naszych bastionów oczyszczenia w Lordaeron.$B$BSprawdziłeś się w walce przeciw nieumarłym w Desolace. Ale prawdziwe zagrożenie plagi leży w Lordaeron.$B$BPrzemieść się do miasta Southshore, w Eastern Kingdoms. Znajdź krzyżowca imieniem Raleigh the Devout. Oddaj mu ten list polecający noszący moją pieczęć, a będzie Ciebie eskortował do honorowego miejsca w Scarlet Monastery.",
    ["O"] = "Zabierz Brother Anton\'s Letter of Commendation do Raleigh the Devout w Southshore.",
    ["T"] = "W Dół Szarłatną Drogą",
  },
  [1053] = {
    ["D"] = "Niegdyś służyłem Scarlet Crusade z honorem, lojalnością oraz dumą. Wierzyłem w szlachetność ich sprawy: pozbyć się z Azeroth nieumarłych.$B$BLecz gdy spędzałem czas w Klasztorze w Tirisfal Glades zrozumiałem, że ich kontakt z rzeczywistością zanika. Teraz myślą, że wszyscy, którzy nie noszą kolorów Krucjaty są zarażeni. Niewinni mężczyźni i kobiety byli torturowani z powodu domniemanego zarażenia plagą.$B$BScarlet Crusade musi zostać zniszczona w imię Światłości. Ty, $N, musisz zniszczyć obłąkany reżim.",
    ["O"] = "Zabij High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion oraz Houndmaster Loksey później złóż raport do Raleigh the Devout w Southshore.",
    ["T"] = "W Imię Światłości",
  },
  [1054] = {
    ["D"] = "Dokładnie na północ od Astranaaru znajdują się furbolgi Kolcogrzbiete. Moi zwiadowcy donieśli, że ich liczba znacznie zwiększyła się w ostatnich kilku miesiącach. Jeśli urosną w siłę, mogą znaleźć odwagę na bezpośredni atak na Astranaar.$B$BZabij tylu z nich, ilu tylko potrafisz i przynieś mi czaszkę ich wodza jako dowód, że ich starania zostały stłumione... przynajmniej na razie.$B$BJa pozostanę tutaj w Astranaar i będę oczekiwała na wieści od ciebie. Niech Elune będzie z tobą.",
    ["O"] = "Przynieś Dal Bloodclaw\'s Skull do Raene Wolfrunner w Astranaar.",
    ["T"] = "Likwidacja zagrożenia",
  },
  [1055] = {
    ["D"] = "Kostur, który jest w twojej dłoni jest gotowy. Shael\'dryn chce usłyszeć o twoim sukcesie.",
    ["O"] = "Wróć do Shael\'dryn przy studni księżyca.",
    ["T"] = "Porządki Raene",
  },
  [1056] = {
    ["D"] = "Duchy lasu powiedziały mi o twej odwadze i woli podróżowania.$B$BNa południe, niedaleko od Jeziora Mystral, znajduje się tunel zwany Ścieżką Talondeep. Idąc tym tunelem znajdziesz się na obszarze znanym jako Grań Windshear w Stonetalon Mountains. Jak już tam będziesz, kieruj się na Jezioro Cragpool, potem na północ, w górę stromym zboczem, aż dojdziesz do Szczytu Stonetalon.$B$BTam znajdziesz opiekuna Albagorma. Uważaj na jego zadania, $R7.$B$BPodróż będzie niebezpieczna.",
    ["O"] = "Pojedź do opiekuna Albagorma w Stonetalon Peak.",
    ["T"] = "Wyprawa do Stonetalon Peak",
  },
  [1057] = {
    ["D"] = "Jako obrońca leśnych duchów możesz domyślać się dlaczego jestem zaniepokojony.$B$B$gPodróżowałeś:Podróżowałaś; przez te góry, aby dotrzeć do tego szczytu. Na pewno $gwidziałeś:widziałaś; to, co spotkało tę ziemię. Chciwość doprowadziła do zniszczenia tych świętych wzgórz.$B$BOsmalona Dolina na południu została podpalona przez chciwą armię zmechanizowanych przemysłowców. Co gorsze, pragniemy zainicjować proces odrostu; jednak Krwawe Furie, które wdarły się na tą ziemię odmawiają nam przejścia.$B$BPozbądź się nędznych harpii, $N!",
    ["O"] = "Obrońca Albagorm z Stonetalon Peak chce, abyś $gzabił:zabiła; 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers oraz 7 Bloodfury Roguefeathers.",
    ["T"] = "Odzyskanie Osmalonej Doliny",
  },
  [1058] = {
    ["D"] = "Jestem bardzo podekscytowany!$B$BTrzy małe klatki dla trzech małych elfów! Lecz co powinniśmy zrobić z naszymi kochanymi, drzewolubnymi przyjaciółmi? Może dajmy im smak tego... jak to oni nazywają... leśną magią!$B$BBędę potrzebował dużej ilości śluzu ze szlamowców Stonetalon. Od tych paskudnych kotów, przynieś mi wąsiki zmierzchu. Będę również potrzebował oczu jeleni, oczywiście - oczu nigdy za wiele. Ach, i nie zapomnijmy o cennej łusce z baśniowego smoka.$B$BŚpiesz się na Szczyt Stonetalon, $N, abym mógł przyrządzić trochę leśnej magii!",
    ["O"] = "Szarlatan Jin\'Zil w Malaka\'jin chce 5 porcji Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes oraz Fey Dragon Scale.",
    ["T"] = "Leśna Magia Jin\'Zil\'a",
  },
  [1059] = {
    ["D"] = "Krwawe Furie zostały stłumione. Jednak wkrótce się przegrupują, jeśli nie podjęte zostaną żadne działania.$B$BDaleko na południu od Barrens, leży kraina zwana Thousand Needles. Jeśli pojedziesz na zachód w głąb Thousand Needles i dotrzesz do krawędzi bujnego lasu Feralas, odnajdziesz druida zwanego Falfindel Waywarder.$B$BTen wspaniały i mądry druid jest zdolny przywołać wielkie duchy lasu, które mogą pomóc w odzyskaniu Osmalonej Doliny.$B$BPrzekaż mu, że jesteśmy w potrzebie. Odszukaj go niezwłocznie!",
    ["O"] = "Przybądź do Falfindela Waywarder\'a na granicy Thousand Needles i Feralas.",
    ["T"] = "Odzyskanie Osmalonej Doliny",
  },
  [1060] = {
    ["D"] = "Dobrze się $gsprawiłeś:sprawiłaś;, $N. Jesteś w czepku $gurodzony:urodzona;, jest coś co chciałbym ci pokazać.$B$BTe harpie nie pochodzą z okolic Barrens. Pochodzą z krainy zwanej Stonetalon, która znajduje się daleko, na północny-zachód stąd. Choć to chyba dla ciebie niebezpieczne miejsce, ten list musi zostać doręczony do mojego starego przyjaciela, który tam mieszka, szamana imieniem Jin\'Zil.$B$BUcieszy się z wieści, że Serena Krwawopióra nie żyje i myślę, że spodoba ci się w Stonetalon.",
    ["O"] = "Dostarcz Darsok\'s letter do Jin\'Zil wewnątrz jego jaskini w Malaka\'Jin, w Stonetalon.",
    ["T"] = "List do Jin\'Zil",
  },
  [1061] = {
    ["D"] = "Duchy Stonetalon Mountains są rozwścieczone za sprawą goblinów i ich sługusów, którzy grabią i palą ziemię. A ona rozbrzmiewa krzykiem, natomiast ci, którzy jej nasłuchują... usłyszeli zew.$B$BSeereth Stonebreak, obiecująca szamanka z Hordy, została wysłana do Stonetalon. Melduje ona o rozległym wylesianiu przez gobliny i prosi o pomoc.$B$BSpotkaj się z Seereth w Stonetalon. Aby do niej dotrzeć, podążaj drogą na zachód od Crossroads w Barrens. Założyła obóz niedaleko Doliny Greatwood.",
    ["O"] = "Porozmawiaj z Seereth Stonebreak w Stonetalon Mountains.",
    ["T"] = "Duchy Stonetalon",
  },
  [1062] = {
    ["D"] = "Prowadzone przez gobliny Venture Company przemieściło się do Stonetalon Mountains, wycinając drzewa i paląc wielkie obszary lasu. Duchy tego miejsca szaleją ze wściekłości i bólu. Musimy powstrzymać Venture Company!$B$BSkieruj się na północny zachód, za Dolinę Greatwood, na Grań Windshear. Znajdziesz gobliny i ich pachołków podczas pracy - pokaż im, że Horda nie pozwala na eksploatacje Stonetalon. Pokaż im to w języku, który najlepiej rozumieją...$B$BPrzemoc.",
    ["O"] = "Zabij 15 Venture Co. Loggers, a następnie powróć do Seereth Stonebreak na granicy Stonetalon i Barrens.",
    ["T"] = "Goblini najeźdźcy",
  },
  [1063] = {
    ["D"] = "By naprawdę zająć się duchami Stonetalon musimy skonsultować się ze starszyzną Taurenów.$B$BNie znam wiele ich imion, ale znam jedno: Magatha. Słyszałam, że jest bardzo stara i ma wielką wiedzę. Jeśli ktokolwiek może korzystać z duchowej pomocy Taurenów, to ona.$B$BMagatha mieszka w stolicy taurenów Thunder Bluff, na Wzniesieniu Starszych - w północno wschodniej części miasta. Porozmawiaj z Magathą i powiedz jej o niebezpieczeństwie w Stonetalon Mountains.",
    ["O"] = "Porozmawiaj z Magatha w Thunder Bluff.",
    ["T"] = "Starowinka",
  },
  [1064] = {
    ["D"] = "Taureni są przywiązani do tej ziemi i boli mnie, kiedy słyszę o losie Stonetalon. Obawiam się jednak, że aby uzdrowić tę ziemię, musimy najpierw usunąć z niej chorobę.$B$BCzy to nie szczęście, że Opuszczeni są naszymi sojusznikami? Mają wiedzę na temat wielu chorób. Wierzę, że mogą nam pomóc i dzięki temu wzrośnie zaufanie między naszymi ludami.$B$BPorozmawiaj z aptekarką Zamah. Jest ona uczoną i wysłanniczką Opuszczonych. Znajdziesz ją w Sadzawkach Wizji poniżej Wzniesienia Ducha.",
    ["O"] = "Porozmawiaj z aptekarką Zamah w Pools of Vision w Thunder Bluff.",
    ["T"] = "Pomoc Opuszczonych",
  },
  [1065] = {
    ["D"] = "By pozbyć się Venture Company ze Stonetalon, musimy podjąć ekstremalne środki. Ekstremalne, ale bez rozlewu krwi.$B$BA, mój kolega może posiadać narzędzia, których potrzebujemy. Nazywa się Lydon; mieszka w mieście Tarren Mill w Hillsbrad Foothills, w dalekiej krainie Lordaeron.$B$BBy dotrzeć do Hillsbrad, udaj się zeppelinem do naszego głównego miasta, Undercity. Potem idź na północ do Tirisfal Glades, południowy-zachód do Silverpine i na południe do Hillsbrad.$B$BTam poszukaj Lydona i przynieś mu jego notatki. Zawierają szczegóły tego, co od niego potrzebujemy.",
    ["O"] = "Przynieś list Zamaha do aptekarza Lydona w Tarren Mill.",
    ["T"] = "Podróż do Tarren Mill",
  },
  [1066] = {
    ["D"] = "Stworzę toksynę, aby zmniejszyć zagrożenie ze strony Venture Company, sprawiając, że staną się słabi i posłuszni. To powinno rozwiązać problemy Hordy w Stonetalon, racja?$B$BAle żeby stworzyć toksynę, potrzebuję krwi niewinnych, bardzo trudny do pozyskania składnik. Na szczęście Syndykat, grupa ludzkich bandytów w tym regionie najmuje magów cienia... a ci magowie zbierają krew niewinnych dla ich własnych, podejrzanych celów.$B$BMożesz znaleźć magów w Twierdzy Durnholde na południu.",
    ["O"] = "Przynieś 5 fiolek Innocent Blood do aptekarza Lydona w Tarren Mill.",
    ["T"] = "Krew niewinnych",
  },
  [1067] = {
    ["D"] = "Proszę, oto toksyna. Jeżeli użyjesz jej przeciwko Venture Company, powinna przynieść korzystne, czasami nawet zaraźliwe efekty. Muszę powiedzieć, że to całkiem ekscytujące, gdy korzystają z moich produktów na polu walki!$B$BLecz przed użyciem, zanieś ją do aptekarki Zamah. Ona musi stworzyć metodę podawania, aby zmaksymalizować jej efekt.",
    ["O"] = "Przynieś Lydon\'s Toxin do aptekarki Zamah w Thunder Bluff.",
    ["T"] = "Powrót do Thunder Bluff",
  },
  [1068] = {
    ["D"] = "Jest powiązanie pomiędzy magią duchową szamanów, a magią natury druidów. To dlatego shaman może słyszeć nawoływania duchów Stonetalon. Wiele z ich szeptów przepadło, ale jedna wiadomość, jedna wizja, jest jasna....$B$BW tej wizji widziałam dwie maszyny na kształt ludzi na Grani Windshear, na północny-zachód z Doliny Greatwood, przewracające drzewa z niesamowitą prędkością. Te metalowe bestie muszą być powstrzymane!$B$BMaszyny te były oznaczone dziwnymi znakami:$B$BXT:4 i XT:9.",
    ["O"] = "Zniszcz maszyny niszczące XT:4 i XT:9, a następnie powróć do Seereth Stonebreak na granicy pomiędzy Stonetalon Mountains, a Barrens.",
    ["T"] = "Mechaniczni Drwale",
  },
  [1069] = {
    ["D"] = "Omlety z pajęczych jaj to nowy trend w Booty Bay! Problem w tym że... w Booty Bay\'s nie mają jaj.$B$BWywęszyłem okazję!$B$BNa Grani Windshear i w Kanionie Sishir, w Stonetalon Mountains na północnym zachodzie, żyją pająki Deepmoss. Przynieś mi ich jaja, a ja zlecę wysyłkę!$B$BNa Grani Windshear, jaja będą zlepione pod resztkami drzew.$B$BW Kanionie Sishir... no cóż, jeśli masz słaby żołądek, to $gpowinieneś:powinieneś; po prostu zebrać jaja na Grani Windshear...",
    ["O"] = "Przynieś 15 Deepmoss Eggs do Meboka Mizzyrixa w Ratchet.",
    ["T"] = "Jaja pająków Deepmoss",
  },
  [1070] = {
    ["D"] = "Witaj, $N.$B$BWydajesz się $gpełny:pełna; zapału do wędrówek. $gByłeś:Byłaś; już może w Stonetalon Mountains? To kraina skażona przez Venture Company i innych wrogów nocnych elfów.$B$BOstatnimi czasy, wartowniczka Wolfrunner wysłała tam moją przyjaciółkę Kaelę Shadowspear by sprawdziła co dzieje się z tą krainą, ale nie mamy jeszcze od niej żadnych wieści. Jestem jeszcze bardziej zaniepokojona, ponieważ razem z nią Przymierze wysłało gnomiego maga... to niewątpliwa oznaka problemów.$B$B$gMógłbyś:Mogłabyś; jej poszukać i wrócić do mnie z wieściami?",
    ["O"] = "Znajdź Kaela Shadowspear patrolującą wejście do doliny Windshear Crag w Stonetalon Mountains.",
    ["T"] = "Na straży Stonetalon",
  },
  [1071] = {
    ["D"] = "Widzisz, $N, jestem członkiem Światłego Zgromadzenia Nauk Archeologicznych, Alchemicznych oraz Inżynieryjnych i moim celem... - nie, OBOWIĄZKIEM! - jest pokazać nocnym elfom, że połączenie magii, mikstur i mechanizmów może pomóc w ocaleniu ich lasów.$B$BAle to ciężki orzech do zgryzienia, dodatkowo gobliny wydają się tu mnożyć jak króliki. Nie mam nawet czasu na budowanie moich najnowszych wynalazków!$B$BPotrzebuję trochę czasu na planowanie i organizację. Żeby to zrobić, potrzebuję twojej pomocy w zatrzymaniu goblinów na Grani Windshear na wschodzie...",
    ["O"] = "Zabij 10 Venture Co. Loggers oraz 10 Venture Co. Deforesters, następnie wróć do Gaxima Rustfizzle\'a w Stonetalon.",
    ["T"] = "Wytchnienie dla gnoma",
  },
  [1072] = {
    ["D"] = "Urządzenie, o którym mówię jest najbardziej zaawansowaną wersją ze wszystkich moich wynalazków. Jednak potrzebujemy specjalnej mikstury, jeżeli to ma zadziałać. Myślę, że moglibyśmy połasić się na najlepszy towar, ponieważ ta misja może być twoją ostatnią.$B$BI dlatego będziemy potrzebować trochę silnych materiałów wybuchowych: nitromirglyceronium.$B$BJedyną osobą która może zrobić NG-5 jest mój stary przyjaciel: Lomac Gearstrip. Poszukaj go w Mieście Majstrów.$B$BPorozmawiaj z nim, aby wytworzył nam trochę NG-5, a ja biorę się do pracy nad swoimi urządzeniami.",
    ["O"] = "Pomów z Lomac Gearstrip w Ironforge.",
    ["T"] = "Stary kolega",
  },
  [1073] = {
    ["D"] = "Hahaha... potrzebujesz nitromirglyceronium, aby zatrzymać gobliny od zniszczenia lasu?!$B$BNie dbam o to czy znasz Gaxima czy nie... dam tobie manele tylko po to, aby zobaczyć jak ty, bądź oni wysadzacie wszystko na drobniuteńkie kawałeczki.$B$BJest jednak mały problem: nic mi już nie zostało.$B$BJednak coś ci powiem, przynieś mi odpowiednie mikstury, a przyrządzę trochę w mgnieniu oka.$B$BPrzynajmniej możesz udowodnić, że masz trochę umiejętności jako alchemik przed tym, jak wręczę tobie próbkę mojego największego dzieła.",
    ["O"] = "Przynieś 4 Minor Mana Potions i 2 Elixirs of Minor Fortitude do Lomaca Gearstripa w Ironforge.",
    ["T"] = "Niekompetencja + Chemikalia = Zabawa",
  },
  [1074] = {
    ["D"] = "Bardzo proszę, $gnieznajomy:nieznajoma;. Uważaj z tym... to niestabilna substancja.$B$BJeśli naprawdę jesteś $gprzyjacielem:przyjaciółką; Gaxima, to pozdrów go ode mnie. Jeśli nie, baw się dobrze wysadzając się w powietrze.",
    ["O"] = "Oddaj Nitromirglyceronium Gaximowi Rustfizzle\'owi w Stonetalon.",
    ["T"] = "Niekompetencja + Chemikalia = Zabawa",
  },
  [1075] = {
    ["D"] = "Dobrze, a teraz czas na część planu, w której dokonuję zdalnej detonacji... Och, nie wyjaśniłem tego jeszcze?$B$BWięc w skrócie: z małą pomocą magii mogę sprawić, że materiał wybuchowy eksploduje wtedy, gdy nie ma cię w pobliżu. Składam urządzenie, które pozwoli ci wywołać eksplozję NG-5 po wciśnięciu przycisku, kiedy tylko będziesz $ggotowy:gotowa;.$B$BAle do tego potrzebuję zaklęcia od mojego przyjaciela w Stormwind - Collin Mauren tak ma na imię. Znajdziesz go w kwaterach magów. Nie przeoczysz go, ponieważ jest człowiekiem.",
    ["O"] = "Znajdź Collina Maurena w Stormwind.",
    ["T"] = "Zwój Maurena",
  },
  [1076] = {
    ["D"] = "O, chyba mam. Zaklęcie wysyłające... Myślę, że to jest efekt, którego on szuka.$B$BBędę musiał wytworzyć zwój, w którym zawrę zaklęcie. Żeby to zrobić będę potrzebował kawałków gruzu z piaszczystych diabłów.$B$BGdy będę pozyskiwać resztę komponentów, może $gmógłbyś:mogłabyś; udać się do Westfall i znaleźć jedno z tych wstrętnych stworzeń? One są niebezpieczne, ale jestem pewien, że dla ciebie to nic trudnego, jeśli chcesz poddać się jednemu z eksperymentów Gaxima.$B$BBędę tu czekać na twój powrót.",
    ["O"] = "Przynieś Dust Devil Debris do Collina Maurena w Stormwind.",
    ["T"] = "Diabły w Westfall",
  },
  [1077] = {
    ["D"] = "Proszę bardzo, $N. Powinno się nadać.$B$BProszę, przekaż moje pozdrowienia dla Gaxima kiedy go spotkasz. Czekam na wieści o tym, jak zakończy się ta przygoda.$B$BŻegnaj.",
    ["O"] = "Przynieś Zwój Wiadomości do Gaxima Rustfizzle\'a w Stonetalon.",
    ["T"] = "Specjalna przesyłka dla Gaxima",
  },
  [1078] = {
    ["D"] = "Podróżnicy ciągle pytają mnie o Stonetalon Mountains. Wygląda na to, że to doskonałe miejsce na przygodę - nie ma znaczenia czy chcesz zobaczyć wiwernę, żywiołaka czy masz interes do Venture Company.$B$BWewnątrz Osmalonej Doliny, głęboko w Stonetalon, żyje pewien gatunek bazyliszków. Ich łuski zmielone na pył są doskonałym odczynnikiem do kilku zaklęć, które stworzyłem.$B$BJeżeli kilka z tych bazyliszków jeszcze żyje, chciałbym mieć kilka ich łusek.$B$BPoświęć trochę czasu, nie musisz się spieszyć, ale dobrze zapłacę.",
    ["O"] = "Przynieś 8 Crystalized Scales Collinowi Maurenowi do Stormwind.",
    ["T"] = "Poszukiwania dla Maurena",
  },
  [1079] = {
    ["D"] = "To jest to, $N. Słuchaj uważnie. Urządzenia są skończone i gotowe do użycia.$B$BWeź te strony - dzięki nim dowiesz się więcej o detonatorach, materiałach wybuchowych i jak je umieszczać.$B$BPamiętaj, że sukces twojej misji nie zależy od wielkości zniszczeń jakie spowodujesz. Sukces projektu Alpha\'s zależy od tego czy przyniesiesz plany inżynierskie Venture Co. z tartaku na południe od Cragpool Lake.",
    ["O"] = "Odzyskaj Venture Co.\'s Engineering Plans z tartaku w Windshear Crag.",
    ["T"] = "Ukryty Ops - Alpha",
  },
  [1080] = {
    ["D"] = "Plan Beta jest jak Plan Alpha, $N.$B$BOdwrócimy ich uwagę, a potem ukradniemy ich cenne listy.$B$BZdobycie tych listów jest kluczowe... pamiętaj.$B$BStrony, które ci dałem, powiedzą ci gdzie podłożyć ładunki wybuchowe. Tylko wróć tu w jednym kawałku i nie zapomnij o listach....",
    ["O"] = "Odzyskaj listy Venture Co. z Windshear Mine na wschodnim końcu Windshear Crag.",
    ["T"] = "Tajne Operacje - Beta",
  },
  [1081] = {
    ["D"] = "$N, jestem pewien, że Tyrande Whisperwind chciałaby ci sama podziękować za branie udziału w tej misji.$B$BMoże na to nie wygląda, ale to co $gpomogłeś:pomogłaś; rozpocząć może bardzo wzmocnić naszą pozycję w Stonetalon Mountains.$B$BJeżeli uważasz siebie za naszego sojusznika wobec tych okrucieństw, idź zobacz się z Tyrande w Świątyni Księżyca w Darnassus.",
    ["O"] = "Znajdź Tyrande Whisperwind w Darnassus.",
    ["T"] = "Powitanie przez Tyrande",
  },
  [1082] = {
    ["D"] = "$N, wielce się nam $gprzysłużyłeś:przysłużyłaś;, udzielając się tutaj.$B$BWartowniczki Ashenvale wynagrodzą cię jeśli poinformujesz je, że Gaxim i ja żyjemy. Przekaż im, że dobrze sobie radzimy w sprawie zatrzymania Venture Company i uzdrowienia krainy.$B$BZnajdź Tarę Thenysil w Astranaar; będzie zadowolona widząc, że $gwróciłeś:wróciłaś; z dobrymi wieściami.",
    ["O"] = "Wróć do wartowniczki Thenysili w Ashenvale.",
    ["T"] = "Wieści dla wartowniczki Thenysili",
  },
  [1083] = {
    ["D"] = "Nie mam pewności co Venture Company zrobiło z doliną, ale to oczywiste, że zostali pokonani przez tamtejsze stworzenia.$B$BPodpalili las i użyli narzędzi zniszczenia, aby przetrzebić tyle doliny, ile było możliwe.$B$BAle w swojej ignorancji przebudzili coś jeszcze: płonące duchy, żywiołaki ognia, kamienia i szału.$B$BTe ziemie nie mają szansy uświadczyć błogosławieństwa Elune, kiedy te kreatury wędrują wolne.$B$BPrzynieś mi ich tlące rdzenie, aby udowodnić mi, że YOUR)GENDER(zredukowałeś;zredukowałaś) ich liczbę.",
    ["O"] = "Przynieś 8 Smoldering Embers z żywiołaków ognia w Charred Vale do Kaeli Shadowspear w Stonetalon.",
    ["T"] = "Rozwścieczone duchy",
  },
  [1084] = {
    ["D"] = "Dla mnie to oczywiste, że obrońcy doliny - drzewce - miały coś do czynienia z odparciem Venture Company. Niestety, nawet ci wspaniali niegdyś obrońcy stali się zepsuci.$B$BGaxim myśli, że ich zepsucie jest jakoś połączone z broniami używanymi przez gobliny podczas odwrotu.$B$BPowiedziałem mu, że zbiorę próbkę z rannego drzewca i pozwolę mu ją zbadać, żeby dowiedzieć się czy to prawda.$B$BPrzynieś mi ten metal, żeby gnom mógł powiedzieć więcej.",
    ["O"] = "Przynieś kawałek Corroded Shrapnel do Kaela Shadowspear w Stonetalon.",
    ["T"] = "Zranieni Starożytni",
  },
  [1085] = {
    ["D"] = "Sytuacja w Stonetalon jest śmiertelnie poważna skoro nocne elfy współpracują z gnomami.$B$BVenture Company zniszczyło te ziemie, a ja spędziłam większość mojego czasu ratując je.$B$BNie oceniaj Gaxima pochopnie. Rozumie on, że musimy współpracować razem.$B$BJeśli chcesz nas wspierać, zacznij od rozmowy z Gaximem.$B$BPrzepraszam. Jeszcze nie mogę cię wysłać do Tary z dobrymi wiadomościami. Może wkrótce...",
    ["O"] = "Porozmawiaj z Gaximem.",
    ["T"] = "Na straży w Stonetalon",
  },
  [1086] = {
    ["D"] = "Toksyna jest przygotowana. Pozostało tylko jej dostarczenie, ty się tym zajmiesz, $N.$B$BVenture Company musi mieć jakiś cel skoro wysyła wiadomości oraz lekkie ładunki pomiędzy ich główną bazą, a obszarem działań w Stonetalon. Podejrzewam, że jest to małe lotnisko - zbyt małe na sterowiec, ale wystarczające na żyrokopter. Musisz przeszukać obszary w Stonetalon, które są pod kontrolą Venture Company i znaleźć to lotnisko, jeśli istnieje. Jeśli je znajdziesz, umieść tam toksynę.$B$BZostaw to tam i uciekaj.",
    ["O"] = "Przynieś Toxic Fogger do lotniska Venture Co. i wróć do aptekarza Zamaha.",
    ["T"] = "Lotnisko żyrokopterów",
  },
  [1087] = {
    ["D"] = "Nie możesz sobie wyobrazić nienawiści, którą czuję dla tej nędznej krainy. Ci, podobni Cenariusowi oraz druidzi Kaldorei, używają na szczycie góry ich żałosnych mocy, aby zdusić przepływ magii, nawet daleko na południe od ich żałosnych gospodarstw... ich ukochanych lasów.$B$BGdybym tylko mogła wrócić do Jeadenaru i cieszyć się przepływem magii... jednak mój mistrz nie pozwoli mi wrócić, dopóki nie skończę swojej pracy.$B$BNie wątpię, że kochasz nocne elfy i ich sojuszników tak mało jak ja. Pomóż mi, a $goboje możemy będziemy usatysfakcjonowani:obie może będziemy usatysfakcjonowane;.",
    ["O"] = "Zabij 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists dla Braelyn Firehand w pobliżu Sun Rock Retreat.",
    ["T"] = "Dziedzictwo Cenariusa",
  },
  [1088] = {
    ["D"] = "Myśleli, że mogą powstrzymać przepływ magii. Pomylili się. Myśleli, że mogli ukryć Ordanusa, ale ja zdobędę jego głowę!$B$BMagia obdarzyła mnie prawdziwym wzrokiem. Tak... Tutaj jest. Skrzyżowanie... Na czubku wielkiego drzewa w lesie Ashenvale. Imię... Raynewood. Jeden z najstarszych synów leśnego boga. Porwali go ze szczytu zanim go znalazłam, jednak jego czas się kurczy.$B$BPrzynieś mi głowę, a ja podzielę się z tobą wspaniałym darem.",
    ["O"] = "Przynieś głowę Ordanusa do Braelyn Firehand w pobliżu Sun Rock Retreat.",
    ["T"] = "Ordanus",
  },
  [1089] = {
    ["D"] = "Druidzi zbudowali Szponiaste Leże na Szczycie Stonetalon, gdzie posiadają wiele potężnych przedmiotów.$B$BOpracowali kompleksowy plan, aby nie wpadły one w niepowołane ręce.$B$BNa szczęście, udało mi się... uzyskać pewne informacje on jednego z nich.$B$BW ukrytej małej latarni znajdującej się u wejścia do leża, znajdziesz klucz strażnika bramy, który pozwoli ci otworzyć ukryte kryjówki wokół tego terenu. Przedmioty z tych skrytek pozwolą otworzyć ci skarb, znajdujący się w jednym z obszarów centralnych.",
    ["O"] = "Wybierz się do legowiska w Stonetalon Peak. Używając Gatekeeper\'s Key, uzyskaj ukryte przedmioty druidów. Za pomocą tych przedmiotów otwórz Talon Den Hoard.",
    ["T"] = "Legowisko",
  },
  [1090] = {
    ["D"] = "Wiesz, kiedyś byłem drugą najważniejszą osobą w tym miejscu. Zmieniło się to, kiedy Gerenzo przejął stery. Zwolnił mojego szefa, Ziz Fizziksa, i wysłał mnie do pracy w kopalniach. Ziz jednak powiedział mi bym tu został i dowiedział się co jest grane. Jego nowy szef obficie nam zapłaci jeśli poznamy plany Gerenzo.$B$BW każdym razie, jedyne co wiem to, że Gerenzo rozkazał wydobyć ogromną ilość tej złoto-zielonej rudy. Mogę załatwić ci próbkę, byś $gzaniósł:zaniosła; ją do Ziza, tylko zajmij się patrolami.",
    ["O"] = "Weź tajemnicze złoże rudy od Piznika jak tylko skończy je wydobywać.",
    ["T"] = "Rozkazy Gerenzo",
  },
  [1091] = {
    ["D"] = "$N, weź te listy do Kaeli. Jestem pewien, że zechce się o tym dowiedzieć. A na pewno wszystkie Wartowniczki.$B$BUpewnij się, że powiesz jej jak skuteczni byliśmy i, że nie mogło się obyć bez odrobiny magii.",
    ["O"] = "Zanieś Venture Co. Letters do Kaeli Shadowspear w Stonetalon Mountains.",
    ["T"] = "Wiadomości dla Kaeli",
  },
  [1092] = {
    ["D"] = "Myślę, że lepiej zacząć myśleć o wydostaniu się stąd. To nie potrwa długo na zwrot tego, co się tutaj rozprzestrzeniło na wyższe grunty i jestem pewien, że nie będą zbyt uprzejmi spotykając mnie jeszcze raz. Wymknę się i spotkam z Zizem. Przy odrobinie szczęścia będzie w stanie znaleźć mi nową pracę! Spróbuję posprzątać trochę ten bałagan, a Ty powinieneś natychmiast wziąć próbki rudy do Ziza. Powiedział mi, że rozbił obóz gdzieś na zachodniej części Windshear Crag Powodzenia.",
    ["O"] = "Dostarcz Unidentified Ore do Ziza Fizziksa w Stonetalon Mountains.",
    ["T"] = "Rozkaz Gerenzo",
  },
  [1093] = {
    ["D"] = "Okropne, co też Venture Company chce tu zrobić, nie? Co oni sobie myślą? Kompania goblińska wynajęła gnoma!$B$B$N, szczęśliwie dla mnie, Sputtervalve poznał mój geniusz, gdy tylko mnie ujrzał. Zatrudnił mnie tuż po tym, jak zostałem wykopany!$B$BPowiedział mi, że kompania chce zbudować kilka olbrzymich maszyn do obróbki drewna, i Sput chciałby, żebym ukradł plany maszyny dla niego. Niestety, Gerenzo - ten cholerny gnom - pragnie, bym kopnął w kalendarz... może ty $gmógłbyś:mogłabyś; ukraść te plany dla mnie? Najpewniej znajdziesz je przy jednym z operatorów tych maszyn.",
    ["O"] = "Zdobądź Super Reaper 6000 Blueprints dla Ziz Fizziks w Stonetalon Mountains.",
    ["T"] = "Super Żniwiarz 6000",
  },
  [1094] = {
    ["D"] = "Ta koperta zawiera wszystkie informacje, które udało mi się zwinąć, zanim wykopali mnie za drzwi... wewnętrzne dokumenty Venture Company, jakieś instrukcje, sprawy techniczne... Och, i oczywiście schematy Super Rozpruwacza 6000.$B$BSputtervalve zamieszkał w Ratchet w Barrens. Nie $gpowinieneś:powinnaś; mieć problemu ze znalezieniem go, to taki mały, zielony koleżka.",
    ["O"] = "Dostarcz Sealed Envelope do Sputtervalve\'a z Ratchet w Barrens.",
    ["T"] = "Dalsze instrukcje",
  },
  [1095] = {
    ["D"] = "Sprawa tego gnoma, który został zatrudniony przez Venture Company, wywołała pewne zamieszanie w Undermine. Książęta handlu nie pochwalają bratania się Razdunka z tym Gerenzo.$B$BRiddlevox poprosił mnie, bym zajął się tym problemem i jestem pewien, że kazał mu to zrobić któryś, lub którzyś, z książąt handlu. Oczywiście tego Dyrektor mi nie powiedział. Powiedzmy, że mam przeczucie.$B$BGerenzo musi zostać usunięty za wszelką cenę; zajęcie się tym będzie odpowiednim sprawdzianem dla Fizziksa.",
    ["O"] = "Zanieś nowe rozkazy do Ziza Fizziksa, w Stonetalon Mountains.",
    ["T"] = "Dalsze instrukcje",
  },
  [1096] = {
    ["D"] = "Kiedyś spotkałem Gerenzo, ale powiem ci, jego widok nie cieszy oczu. Jego ciało wygląda jakby się rozpadało; powszczepiał w siebie metal i mechanizmy, zastępując niektóre członki mechanicznymi odpowiednikami.$B$BNa północny wschód stąd, wysoko ponad jeziorem Cragpool, w pobliżu koła wodnego, leży miejsce, z którego Gerenzo zarządza całą strefą. Nie ma możliwości bym się tam przebił, nie wspominając o zabiciu Gerenzo... Ale ty wyglądasz na kogoś, komu by się to udało.$B$BJeśli go dla mnie zabijesz, sowicie wynagrodzę twój czas!",
    ["O"] = "Przynieś Mechaniczne Ramię Gerenza Wrenchwhistle\'a do Ziza Fizziksa w Stonetalon Mountains.",
    ["T"] = "Gerenzo Wrenchwhistle",
  },
  [1097] = {
    ["D"] = "W Stormwind znajduje się krasnoludzki kowal kujący bronie, Grimand Elmore. Przysłał on list, że potrzebuje pomocy w dostawie. Przypuszczam, że chce wysłać paczkę na północ, w swoje rodzinne strony.$B$BMasz na sobie solidną parę butów! Więc jeśli jesteś $gzainteresowany:zainteresowana; pracą wymagającą chodzenia, porozmawiaj z Grimandem. $gMógłbyś:Mogłabyś; się tu przydać, ale musimy też utrzymać silne więzi z krasnoludami.$B$BGrimanda Elmore\'a można znaleźć w sklepie z bronią w Dystrykcie Krasnoludów, w północno-wschodniej części miasta Stormwind.",
    ["O"] = "Porozmawiaj z Grimand Elmore w Stormwind.",
    ["T"] = "Zadanie Elmore\'a",
  },
  [1098] = {
    ["D"] = "W ramach przygotowań do napaści na Shadowfang wysłano tam dwóch umarłych tropicieli celem zebrania informacji. Minęło wiele dni, a oni nie wrócili, ale musimy uzyskać ich raport, jeśli chcemy mieć jakąś nadzieję na udany atak!$B$BWięc oto twoje zadanie, $N. Udaj się na południe, do Shadowfang Keep i znajdź Umarłych Tropicieli Adamanta i Vincenta. Znajdź ich, a jeśli będą potrzebowali pomocy, udziel im jej.$B$BTa misja jest równie niebezpieczna co znacząca, $N. Nie zawiedź.",
    ["O"] = "Znajdź Deathstalkera Adamanta i Deathstalkera Vincenta.",
    ["T"] = "Umarli Tropiciele w Shadowfang",
  },
  [1099] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Goblins Win!",
  },
  [1100] = {
    ["D"] = "Powoli otwierasz nadniszczony dziennik Henriga Lonebrowa...",
    ["O"] = "Przeczytaj Dziennik Henriga Lonebrowa.",
    ["T"] = "Dziennik Lonebrowa",
  },
  [1101] = {
    ["D"] = "Biedny Heralath! I ten krasnolud... Lonebrow. Ależ to była dzielna dusza.$B$BNie możemy pozwolić, by ich męstwo poszło na marne. Ta starucha... Charlga Razorflank... musi zostać powstrzymana.$B$BInfiltracja zagrody z całą pewnością będzie niebezpieczna. Nie ma czasu, by skontaktować się z Darnassus. $N, zbierz grupę, by zgładzić staruchę.$B$BPrzynieś mi medalion Razorflank na dowód jej zgonu.",
    ["O"] = "Przynieś Razorflank\'s Medallion do Falfindela Waywardera z Thalanaaru.",
    ["T"] = "Starucha z Zagrody",
  },
  [1102] = {
    ["D"] = "Cairne jest szlachetnym przywódcą, który zjednoczył nasz lud tu, w Thunder Bluff.$B$BLecz nie potrafię tak łatwo jak niektórzy przebaczyć tym, którzy wypędzili nas z ziem naszych przodków. Mój lud od dziesięcioleci zamieszkiwał południowe Barrens. Ta kraina była dla nas świętością. Lecz zostaliśmy stamtąd przegnani przez liczniejszego wroga.$B$BMarny koniec czeka tę staruchę, Charlgę Razorflank, która zbiera ohydne armie z wnętrza Zagrody Razorfen.$B$B$N, przynieś mi serce Charlgi, a będę mógł odejść w spokoju.",
    ["O"] = "Przynieś Razorflank\'s Heart do Aulda Stonespire\'a z Thunder Bluff.",
    ["T"] = "Mściwy los",
  },
  [1103] = {
    ["D"] = "Czołem, $gbratku:siostro;! Ty też $gprzylazłeś:przylazłaś; tutaj, żeby oczyścić wody i udowodnić Islen to, że rozumiesz nauki wody?$B$BWłaśnie pokonałem sam skorumpowanego ducha wody i miałem właśnie zamiar umieścić bransolety i pozostałe krople wody w koksowniku.$B$BA cóż to? Achhh. Tiev rozumie to, aż za dobrze, kiedy coś idzie nie tak. No cóż, Tiev mógłby ci nawet pomóc, gdybyś $gpotrzebował:potrzebowała; zobaczyć oczyszczonego ducha wody jeszcze raz.$B$BPrzynieś mi saptę wody od Islen jako dowód, że jesteś $ggotowy:gotowa;, a ja poczekam przed oddaniem swojej.",
    ["O"] = "Przynieś Water Sapta do Tieva Mordune\'a w Silverpine Forest, jeśli nie udało ci się porozmawiać z Minor Manifestation of Water.",
    ["T"] = "Zew wody",
  },
  [1104] = {
    ["D"] = "Mam tyle pomysłów dla naszego pojazdu rakietowego! Tak dużo! I muszę je wszystkie wypróbować!!$B$BPracuję nad nowym rodzajem paliwa. Takim, które daje naprawdę naprawdę dużo ognia!! Mieszanka nie jest jeszcze doskonała, ale chyba wiem, czego tu trzeba...$B$BSkorpiony, które włóczą się po Shimmering Flats, mają jad, w którym jest dużo dużo soli. Jest wyjątkowy! I to właśnie to, czego potrzebuję!$B$BPrzynieś mi jad, a wierz mi - nasz pojazd poleci!!",
    ["O"] = "Przynieś 6 Salty Scorpid Venoms do Fizzle\'a Brassboltsa z Shimmering Flats.",
    ["T"] = "Słonawy jad",
  },
  [1105] = {
    ["D"] = "Mój brat pracuje nad nowym paliwem do swojego pojazdu rakietowego. Jest genialny, masz na to moje słowo. Taki genialny, że... myślę, że to nowe paliwo, nad którym pracuje, jest tak silne, że może przeżreć się przez podwozie pojazdu!$B$BChcę wzmocnić jego bak, nim to nastąpi.$B$BŻółwie z tych równin mają bardzo twarde skorupy. Chcę ich użyć do skonstruowania nowych zbiorników dla naszego pojazdu rakietowego. Takich, które dadzą radę utrzymać nowe paliwo mojego brata.$B$BWyglądasz na odpowiedzialną osobę. Zdobędziesz dla mnie te skorupy?",
    ["O"] = "Dostarcz 9 Hardened Tortoise Shells do Wizzle\'a Brassboltsa z Shimmering Flats.",
    ["T"] = "Twarde skorupy",
  },
  [1106] = {
    ["D"] = "Pracuję nad nowym silnikiem, który szybko rozpędzi mój pojazd! Na tyle szybko, by wzniósł się w powietrze, wiem o tym! Potrzebuję tylko tłoków, które wytrzymają bardzo bardzo bardzo duże naprężenia. Póki co wszystkie próby kończyły się niepowodzeniem, gdyż nie jestem w stanie zrobić wystarczająco wytrzymałych tłoków!$B$BAle jest ktoś, kto może mi pomóc.$B$BNazywa się Martek Wygnaniec. Jest wybitnym kowalem i wie o metalach więcej niż ktokolwiek inny. Zanieś mu ten list, wiem, że pomoże!$B$BLecz mieszka daleko stąd - w Azeroth, w Badlands, w obozie, z goblinem!$B$BZnajdź go!",
    ["O"] = "Zanieś List Fizzle\'a do Marteka Wygnańca z Badlands.",
    ["T"] = "Martek Wygnaniec",
  },
  [1107] = {
    ["D"] = "Nasz ścigacz to najszybsza rzecz na tych równinach! Tak szybka, że... boję się, że tarcie rozedrze go na strzępy!$B$BBy temu zapobiec, muszę stworzyć kompozyt, którym pokryję ruchome części pojazdu. Musi być twardy, ale nie kruchy, a zarazem odporny na wpływ soli, albo czas spędzony wShimmering Flats go zetrze.$B$BSłyszałaś kiedyś o Vile Reef, $N? To u wybrzeży Stranglethorn Valen. Żyją tam Saltscale murloki, a ich płetwy ogonowe to kluczowy składnik mojej mieszanki.",
    ["O"] = "Przynieś 10 Encrusted Tail Fins do Wizzle\'a Brassboltsa z Shimmering Flats.",
    ["T"] = "Zeskorupiałe płetwy ogonowe",
  },
  [1108] = {
    ["D"] = "Nie siedzę tu tylko dlatego, żeby trzymać się z dala od ludzi. W Badlands występuje mnóstwo metali, $N, jeśli tylko masz odwagę je zdobyć.$B$BSzczęśliwym zbiegiem okoliczności metal zwany indurium posiada ponoć wysoką odporność na ciepło i naprężenia. Może się sprawdzić w pojeździe Fizzle\'a.$B$BAle się upewnijmy. Zdobądź dla mnie próbki indurium, a ja sprawdzę jego właściwości.$B$BWłaściwa ruda indurium spoczywa w głębi Uldamanu, ale troggi Stonevault z Badlands mają czasem przy sobie jej odpryski. Przynieś mi je.",
    ["O"] = "Przynieś 10 Indurium Flakes do Marteka the Exiled w Badlands.",
    ["T"] = "Indurium",
  },
  [1109] = {
    ["D"] = "$N, jak widzisz, Królewskie Stowarzyszenie Aptekarskie jest w trakcie... bardzo interesującego eksperymentu.$B$BMoim zadaniem, jako tutejszego Mistrza, jest nadzorować najbardziej ambitne eksperymenty alchemiczne. Tak wiele pracy, a tak mało czasu!$B$BWydaje się, że jak na $C zwiedziłeś spory kawałek świata. Może jesteś w stanie mi pomóc.$B$BPotrzebuję rzadkiej substancji. To wstrętna maź; pochodzi od rzadkiego gatunku nietoperzy zamieszkującego wyłącznie gnojowisko znane jako Zagroda Razorfen. Przynieś mi guano nietoperzy, byśmy mogli rozpocząć naszą pracę...",
    ["O"] = "Przynieś Mistrzowi Aptekarzy Faranellowi z Undercity kupkę Kraul Guano.",
    ["T"] = "Dalej, dalej, guano!",
  },
  [1110] = {
    ["D"] = "Heh heh, przy tylu wyścigach, ile ich się tu odbywa, nie należy się dziwić kilku nieszczęśliwym wypadkom na trasie. Jeśli rozejrzysz się po Shimmering Flats, znajdziesz dowody dawnych kraks - wszędzie roi się od kawałków pojazdów rakietowych!$B$BA za te kawałki zarówno gnomy, jak i gobliny są skłonne płacić. Ciągle szukają nowych gadżetów, by wcisnąć je w swe pojazdy. $B$BIdź więc i zdobądź mi trochę części. Zbierz stertę, a dobrze ci zapłacę.",
    ["O"] = "Przynieś Kravelowi Koalberadowi z Shimmering Flats 30 Części Pojazdu Rakietowego.",
    ["T"] = "Części pojazdu rakietowego",
  },
  [1111] = {
    ["D"] = "Zajmuję się dostarczaniem innym tego, czego potrzebują, a tamte gnomy potrzebują swoich zamówionych części. Tydzień temu zostały dostarczone do Ratchet, ale nie miałem możliwości się tam udać.$B$BZatem gotowy trochę połazić? Udaj się do Ratchet i daj to zamówienie na części Dokmistrzowi Dizzywigowi - powinien być w dokach.$B$BZrób to dla mnie, a będę miał dla ciebie więcej pracy.$B$BPracy, drogi przyjacielu, z widokiem na niezły zarobek...",
    ["O"] = "Zanieś Zamówienie na Części Kravela do Wharfmastera Dizzywiga w Ratchet.",
    ["T"] = "Dokmistrz Dizzywig",
  },
  [1112] = {
    ["D"] = "Oto paczka dla Kravela, $N. Kiedy ją doręczysz, powiedz mu... że jeśli chce złożyć jeszcze jakieś specjalne zamówienie, musi najpierw uregulować rachunek!",
    ["O"] = "Zanieś Kravelowi Koalbeardowi z Shimmering Flats jego części.",
    ["T"] = "Części dla Kravela",
  },
  [1113] = {
    ["D"] = "Możesz się zastanawiać, po co mi rzadka odmiana guana. Cóż - ten eksperyment ma mi pokazać, jaki efekt wywrą na sobie dwie diametralnie różne substancje chemiczne. Zwłaszcza wtedy, gdy połączymy je z silnie toksycznym czynnikiem, by zagwarantować najbardziej... upiorne efekty.$B$BNa północno-wschodnich wzgórzach Tirisfal Glades wznosi się Scarlet Monastery. Wewnątrz i na zewnątrz jego murów mieszkają szaleni uczniowie kongregacji Scarlet Crusade. Nie ma znaczenia, których będziesz zabijać - każdy z nich może mieć takie serce, jakich potrzebuję.",
    ["O"] = "Mistrz Aptekarzy Faranell z Undercity chce 20 Hearts of Zeal.",
    ["T"] = "Gorliwe serca",
  },
  [1114] = {
    ["D"] = "Skoro już mam, czego potrzebuję, daj te części Fizzle\'owi Brassboltsowi. Czeka na nie już od dłuższego czasu - jestem pewien, że nie będzie tęsknił za drobiazgiem, który usunąłem z jego zamówienia...$B$BNie zawracałbym mu tym głowy. To była drobnostka bez znaczenia.$B$BWierz mi.",
    ["O"] = "Zanieś Delikatne Części Pojazdu do Fizzle\'a Brassboltsa z Shimmering Flats.",
    ["T"] = "Przesyłka dla gnomów",
  },
  [1115] = {
    ["D"] = "Pomogliśmy gnomom, teraz czas na przysługę dla goblinów! $B$BSłyszałem, że pilot wyścigowy goblinów, Nazz Steamboil, nie zawsze używa tego imienia. Zastanawiam się dlaczego go zmienił. Ciekawe czy to sekret... ciekawe jak cenny jest to sekret.$B$BJeśli ktokolwiek zna prawdę, to jest to Krazek z Booty Bay, w południowej części Stranglethorn. Porozmawiaj z Krazekiem i zapytaj go o naszego pilota goblina.$B$BJeśli dowiesz się od niego czegoś użytecznego, może zamienimy to w zysk.",
    ["O"] = "Porozmawaj z Krazekiem w Booty Bay w Booty Bay.",
    ["T"] = "Rozsiewacz plotek",
  },
  [1116] = {
    ["D"] = "Informacje na temat Nazz to spora prośba, $N. Tak, spora prośba... Ale przybywasz tutaj ze Shimmering Flats po to.... Czy jesteś gotów podróżować jeszcze trochę?$B$BPodczas, gdy ja skontaktuję się z pewnymi osobami, może coś dla mnie zbierzesz, co?$B$BHm... co to może być? Może Pył Snu ze smocząt na Bagnach Smutków? Tak, przydałoby się go trochę do mojej sakwy...$B$BZdobądź go dla mnie, $N, a dam Ci informacje, których szukasz.",
    ["O"] = "Przynieś 10 Specks of Dream Dust do Krazek\'a w Booty Bay. Pył Snu można zebrać ze smocząt zlokalizowanych na Bagnach Smutków.",
    ["T"] = "Pył Snu w Bagnie",
  },
  [1117] = {
    ["D"] = "Musiałem wykorzystać sporo przysług i oddać butelkę rzadkiego elfiego wina, a także sporo samemu pokombinować! Jednak znalazłem informację, której szukasz.$B$BNapisałem list z paroma bardzo interesującymi haczykami na naszego przyjaciela, Nazz\'a Steamboil. Zrób z tym co chcesz - dla mnie to zbyt niebezpieczne.$B$BTylko nie mów nikomu skąd to masz!",
    ["O"] = "Przynieś Goblin Rumors do Kravel\'a Koalbeard na Shimmering Flats.",
    ["T"] = "Wieści dla Kravel\'a",
  },
  [1118] = {
    ["D"] = "$N, jesteś $C, $gktóremu:której; mogę zaufać w sprawie wykonania roboty, jak i trzymania gęby na kłódkę.$B$BMyślałem nad nowym planem. Jest ryzyko, ale jak nam się uda, to napchamy sobie kieszenie szmalem! Myślę, że jesteś osobą do tego idealną.$B$BNa początek musisz wrócić do Booty Bay. Sorki, $N. Wiem, że już cię tam wysyłałem. Tym razem pogadasz z Crankiem Fizzlebubem.$B$BDaj mu ten list. Pomóż mu, jeśli będzie tego potrzebował. Nagroda będzie warta wysiłku.",
    ["O"] = "Przynieś Kravel\'s Scheme do Cranka Fizzlebuba w Booty Bay.",
    ["T"] = "Spowrotem do Booty Bay",
  },
  [1119] = {
    ["D"] = "Wymyśliłem jak użyć Zanzil\'s Mixture z piwem, by stworzyć potężną libację. Fool\'s Stout. Wydaję mi się, że to będzie to, czego potrzebuje Kravel, ale wypróbuj to i daj mi znać jak działa.$B$BI $N, nie trzymaj tego zbyt długo. Zanzil\'s Mixture ma dziwny efekt na drożdże piwne, przyśpieszają ich działanie. Nie pozostaną świeże na zawsze.",
    ["O"] = "Przynieś Fool\'s Stout z powrotem do Kravel\'a na Shimmering Flats.",
    ["T"] = "Mikstura Zanzil i piwo głupców",
  },
  [1120] = {
    ["D"] = "Musimy wypróbować Fool\'s Stout na jednej z załóg wyścigowych. Jeśli chcesz wypróbować je na gnomach,to proszę - weź to piwo i zanieś je Gnome Pit Boss.$B$BI nie czekaj zbyt długo. To piwo w końcu się popsuje.",
    ["O"] = "Przynieś Fool\'s Stout do Gnome Pit Boss.",
    ["T"] = "Upij Gnomy",
  },
  [1121] = {
    ["D"] = "Musimy wypróbować Fool\'s Stout na jednym z Pit Crews. Jeżeli chcesz ją wypróbować na goblinach, to proszę - weź to piwo i daj je Goblin Pit Boss.$B$BI nie zwlekaj zbyt długo. To piwo może się szybko popsuć.",
    ["O"] = "Przynieś Fool\'s Stout do Goblin Pit Boss.",
    ["T"] = "Upij Gobliny",
  },
  [1122] = {
    ["D"] = "Ten Fool\'s Stout działa świetnie! Obstawię zakład na następny wyścig i... mam nadzieję, że ekipa, którą upiłeś, wykonała numer na ich samochodzie!$B$BJest jeszcze jedno zadanie dla Ciebie - zabierz te notatki z powrotem do Crank Fizzlebub w Booty Bay. Będzie chciał wiedzieć o udanym teście.$B$BI ufnie możemy otrzymać więcej tego Fool\'s Stout na przyszłe wyścigi!",
    ["O"] = "Zanieś Fool\'s Stout Report do Crank Fizzlebub w Booty Bay.",
    ["T"] = "Wróć z Raportem do Fizzlebuba",
  },
  [1123] = {
    ["D"] = "W tej misji majordomus strażnika Remulosa w Moonglade - Rabine Saturna - poszukuje pomocy w eksploracji rozległych ziem daleko na zachód od Tanaris i Un\'Goro. Przesiaduje w Nighthaven, głównej wiosce Moonglade.$B$BChcę, byś dobrze zrozumiał istotę swojej obecności tutaj. W Moonglade między nocnymi elfami z Darnassus i Kręgiem Cenariona jest wciąż rosnące napięcie. Spójrz ponad rasowe ograniczenia, wsłuchaj się w mądrość swoich przodków, gdy będziesz się tu parać z Kręgiem, $N. Powodzenia.",
    ["O"] = "Porozmawiaj z Rabine Saturna w wiosce Nighthaven, w Moonglade. Moonglade leży pomiędzy Felwood, a Winterspring, dotrzesz tam drogą z Timbermaw Hold.",
    ["T"] = "Rabine Saturna",
  },
  [1124] = {
    ["D"] = "Na zachód od Krateru Un\'Goro, idąc przez północno-zachodni grzbiet wzgórza, znajdziesz nieprzyjazne pustkowie - Silithus. Niewielu wie, że rozegrała się tam starożytna wojna pomiędzy nocnymi elfami, a złą, obcą siłą. Zło zostało zapieczętowane, lecz podejrzewamy, że pewne siły próbują prowokować ten... nieopisany horror.$B$BPoszukaj Layo Starstrike, jednego z naszych agentów w Silithus; szukaj go w Spoczynku Walecznych, ostatnim miejscu spoczynku zmarłych na pustkowiach. Daj mu ten list, by zyskać jego zaufanie.",
    ["O"] = "Porozmawiaj z Layo Starstrike obok Valor\'s Rest cmentarza w Silithus i pokaż mu Rabine\'s Letter.",
    ["T"] = "Pustkowie",
  },
  [1125] = {
    ["D"] = "Na południowy zachód od nas leży tragiczne miejsce - ruiny Southwind Village. Tam powinna zacząć się nasza praca, $N.$B$BZ tego, co się dowiedziałem wynika, że ta wioska była kiedyś bazą operacji dla Nocnych Elfów w Silithus. Już dawno temu została zniszczona przez roje Silithid, które przeżerają się przez pustkowia. Mogę sobie tylko wyobrażać horror, przez który mieszkańcy wówczas przeszli...$B$BTorturowane duchy poległych druidów i strażników błądzą bezcelowo po ruinach. Wybierz się tam i uwolnij dusze tych nędznych bytów tak jak trzeba.",
    ["O"] = "Uwolnij dusze ośmiu Tortured Druidów oraz ośmiu Tortured Sentinelów w Southwind Village, po czym wróć do Layo Starstrike\'a na cmentarzu Valor\'s Rest w Silithus.",
    ["T"] = "Duchy Southwind",
  },
  [1126] = {
    ["D"] = "Rój na pewno kieruje się do Southwind Village, a ja myślę, że znam sposób, by się do nich dobrać. Z mojego doświadczenia wynika, że roje Silithid są wrażliwe na ich obecne otoczenie - to odkrywa ich ataki, gdyż słychać zawodzenia śmierci od dusz.$B$BRoje Silithid są najsilniejsze w wieży - w tej z masą os krążącą wokół. Przeskaluj wieżę i popchnij rój do stanu aktywnego. Zamelduj mi o tym, czego się dowiesz, ale bądź ostrożny! Jeśli odkryjesz cokolwiek, co może się okazać pomocne, przynieś to do mnie.",
    ["O"] = "Przeszukaj wieżę w Southwind Village i zlokalizuj środki do poruszenia roju Silithid w aktywność. Przynieś z powrotem coś niezwykłego, co możesz odkryć w międzyczasie, do Layo Starstrike na cmentarzu Valor\'s Rest w Silithus.",
    ["T"] = "Rój w Wieży",
  },
  [1127] = {
    ["D"] = "Więc chcesz trochę Fool\'s Stout, eh? Myślisz nad powrotem do wyścigów...?$B$BW porządku, przynieś mi więcej Zanzil\'s mixture i zrobię trochę więcej sztuczek dla ciebie.",
    ["O"] = "Przynieś 12 Zanzil\'s Mixture do Crank Fizzlebub w Booty Bay.",
    ["T"] = "Fool\'s Stout",
  },
  [1130] = {
    ["D"] = "$N, Melor Stonehoof słyszał o twoich czynach i wyznaczył drogę przed tobą.$B$BJeśli chcesz przez nią przejść, to idź do Thunder Bluff i porozmawiaj z Melorem. Znajdziesz go na Wzniesieniu Łowcy.",
    ["O"] = "Porozmawiaj z Melorem Stonehoof\'em w Thunder Bluff.",
    ["T"] = "Merol wysyła wiadomość",
  },
  [1131] = {
    ["D"] = "Czasami polujemy dla pożywienia. Czasami polujemy dla honoru. Czasami polujemy by zrozumieć nauki Matki Ziemi.$B$BLecz żadna z tych rzeczy nie jest powodem polowania, które przygotowałem dla ciebie. Chodzi o zabicie stworzenia, którego nie pobłogosławiła Matka Ziemia.$B$BHiena Steelsnap wędruje po Thousand Needles, na południe od Barrens. Jest tyranem, przyciągającym inne hieny, i szerzącym strach i rozlew krwi pomiędzy bardziej spokojnymi bestiami.$B$BZnajdź Steelsnap, $N. Znajdź ją i pokonaj.",
    ["O"] = "Przynieś Steelsnap\'s Rib do Melora Stonehoofa w Thunder Bluff.",
    ["T"] = "Steelsnap",
  },
  [1132] = {
    ["D"] = "Och, znów być nad morzem! By poczuć muskanie wiatru oraz fale kołyszące mnie jak moja ukochana matka, dawno temu!$B$BOch, jakże chciałbym mieć takie szczęście jak ty, mości $C, ponieważ morze widzę w twojej przyszłości!$B$BTo moja powinność rozmawiać z mężnymi duszami, które garną się do Kalimdoru, ziemi wielkich możliwości! Jeśliś $gskory:skora; do sprawdzenia swego szczęścia na morzu, wypłyń statkiem stąd do jakże uroczego portu w Auberdine. Jak zejdziesz na ląd, porozmawiaj z moją współpracowniczką, elfką Fiorą Longears.$B$BOna powinna ci pomóc w poszukiwaniu przygody na Kalimdorze!",
    ["O"] = "Porozmawiaj z Fiorą Longears w porcie Auberdine w Darkshore.",
    ["T"] = "Fiora Longears",
  },
  [1133] = {
    ["D"] = "Jeśli właśnie $gprzybyłeś:przybyłaś; łodzią z Menethil, to pierwszą rzeczą jaką $gpowinieneś:powinnaś; zrobić jest... udanie się do Astranaar. Jestem pewny, że tak gorliwy członek Alliance jak Ty może uczynić tam trochę dobra. Porozmawiaj z Shindrell Swiftfire i zaoferuj jej swe usługi.$B$BNie musisz wspominać kto Cię przysyła. Shindrell i tak mnie nie zna...",
    ["O"] = "Porozmawiaj z Shindrell Swiftfire w Astranaar.",
    ["T"] = "Wyprawa do Astranaar",
  },
  [1134] = {
    ["D"] = "Nie jesteśmy z Hordą w otwartej wojnie, ale nasz pokój jest kruchy. Często natrafiamy na ich agentów ruszających przeciwko nam, jednak działających w ukryciu.$B$BZrobiliśmy postępy, bo informatorzy z Theramore przekazali nam, że orki pozyskują jad od Pridewingów niedaleko Jeziora Mirkfallon, w Stonetalon Mountains na południu. Orkowie-zabójcy potem używają tego jadu w swoich sekretnych rajdach śmierci skierowanych w Przymierze!$B$BJeśli to prawda, musimy ich powstrzymać, $N. Trzeba pozbawić ich źródła tego jadu.",
    ["O"] = "Przynieś 12 Pridewing Venom Sac do Shindrell Swiftfire w Astranaarze.",
    ["T"] = "Pridewingi ze Stonetalon",
  },
  [1135] = {
    ["D"] = "Jak możesz już wiedzieć, wywerny są często oswajane przez orków i używane jako wierzchowce. Ale o czym mniej wiadomo to to, że jad wywerny w pewnych kręgach jest wart więcej niż sama bestia. Więc jeśli nie boisz się urządzenia małego polowania na nie, to... Będę miała dla ciebie robotę.$B$BJest jedno takie miejsce, nazywa się Highperch - to na ziemiach Thousand Needles, na zachód stąd. Wywerny z Highperch mają mocny jad. Mocny i wartościowy.",
    ["O"] = "Przynieś 10 Highperch Venom Saców do Fiory Longears w Theramore.",
    ["T"] = "Jad Highperch",
  },
  [1136] = {
    ["D"] = "$N, nadszedł już najwyższy czas, byś $gwyruszył:wyruszyła; ku dalekim ziemiom. Jesteś $ggotowy:gotowa;.$B$BTeraz zapolujesz na Frostmawa, yeti z Gór Alteraku. Jest nieuchwytny, jego biały kożuch zlewa się ze śniegami jego górskiego domu. Rzadko się pokazuje.$B$BJednak ja pokażę ci, jak wywabiać kreatury takie jak on. Proszę, weź ten zwój. Napisałem na nim, jak przygotować przynętę na Frostmawa.$B$BA teraz ruszaj, $N. Twoja podróż będzie długa, a podczas niej czeka cię mnóstwo wyzwań. Twoje zadanie jest wykonane tylko wtedy, gdy wrócisz z grzywą Frostmawa.",
    ["O"] = "Przynieś Frostmaw\'s Mane do Melora Stonehoofa w Thunder Bluff.",
    ["T"] = "Frostmaw",
  },
  [1137] = {
    ["D"] = "Indurium wykazuje niezwykłą odporność na ciepło! Z pewnością dobrze się sprawdzi w silniku Fizzle\'a. Ale będzie potrzebował zasadniczej rudy, a nie tylko odprysków.$B$BBy się do niej dobrać, trzeba zapuścić się z kilofem w czeluście Uldamanu na północnej granicy Badlands. To prawdziwe źródło indurium.$B$BPozdrów ode mnie Fizzle\'a Brassboltsa i przekaż mu, co ci powiedziałem.$B$BBezpiecznej drogi, $N. I wcale się nie zdziwię, jeśli znów się spotkamy - jak tylko Fizzle dowie się o indurium, zapewne wyśle cię po nie do Uldamanu!",
    ["O"] = "Porozmawiaj z Fizzle\'em Brassboltsem w Shimmering Flats.",
    ["T"] = "Wiadomość dla Fizzle\'a",
  },
  [1138] = {
    ["D"] = "Ubóstwiam kraby. To prawdziwe owoce morza! Można je upiec, zgrillować, ugotować i przyrządzić na parze. Usmażyć na patelni, w głębokim tłuszczu, czy na wolnym ogniu. Jest sałatka z krabów, zupa z krabów, gulasz z krabów, krab z pieprzem, krab w cytrynach, krab w korzeniach biczownika, i krab-niespodzianka z Ironforge. To... to chyba wszystko.$B$BObecnie łowię ryby, a z tego nie będzie żadnych ładnych kawałków kraba. Możesz je uzyskać z pełzaczy rafowych i opancerzonych pełzaczy pływowych. Można je przyrządzić na wiele sposobów. Upiec, zgrillować, ugotować...",
    ["O"] = "Zdobądź 6 Fine Crab Chunks dla Gubbera Blumpa z Auberdine.",
    ["T"] = "Owoce morza",
  },
  [1139] = {
    ["D"] = "Spowolniliśmy klan Shadowforge, odcinając ich od Blackrock Spire, lecz misja Hammertoe\'a wciąż nie została wypełniona. Jego śmierć nie może pójść na marne. Marzył o odnalezieniu Tablic Woli: kamiennych odłamków, na których Tytani zapisali zaklęcia mające pomóc im tchnąć życie w ich nieożywione dzieła - dać im wolną wolę. Tak przynajmniej mówią legendy.$B$BMusimy odnaleźć te Tablice, zanim dokona tego klan Shadowforge.$B$BWróć do Uldamanu, odnajdź tablice i natychmiast przynieś je tutaj.",
    ["O"] = "Odnajdź Tablicę Woli i zwróć ją Doradcy Belgrumowi z Ironforge.",
    ["T"] = "Zaginione Tablice Woli",
  },
  [1140] = {
    ["D"] = "Pismo orków jest tylko troszeczkę lepsze niż bazgroły dzieciaka. Wielu z mego cechu szydziło sobie, gdy zdecydowałem się uczyć ich języka, ale znalazłem go pożytecznym w głębszym zrozumieniu moich wrogów.$B$BZ bazgrołów Ilkruda wynika, że Athrikus cały czas posiada dwa kamienie dusz, które są trzymane w Night Run i w Satyrnaarze, obszarach Ashenvale zajętych przez satyrów.$B$BUważaj tam na siebie, $N, ociekające krwią skronie satyrów mogą okazać się zgubą nawet dla zaprawionego $C takiego jak ty.",
    ["O"] = "Uwolnij uwięzione dusze Highborne z Night Run i Satyrnaaru, a potem wróć do Delgrena the Purifiera w Maestra\'s Post.",
    ["T"] = "Wieża Althalaxxa",
  },
  [1141] = {
    ["D"] = "Kocham łowienie. Rodzina Blumpów jest z tego znana. Nazywam się Gubber Blump; jestem wędkarzem.$B$BJest taka ryba, którą lubię łowić w tych rejonach, zwana ciemnobrzeżnym grańcem. Kiedyś wybierałem się na nie łódką, lecz żadna łódka nie wypływa na morze od czasu, gdy te złośliwe murloki się tu wprowadziły. Założę się, że to one zjadły wszystkie grańce.$B$BSłuchaj, chcesz mi pomóc w łowieniu ciemnobrzeżnych grańców? Jeśli to zrobisz, dostaniesz prawdziwą rodzinną wędkę Blumpów! To naprawdę dobry kij do łapania ryb.",
    ["O"] = "Złów 6 Darkshore Grouper dla Gubbera Blumpa z Auberdine.",
    ["T"] = "Rodzina i wędka",
  },
  [1142] = {
    ["D"] = "Nie pozostało mi wiele życia... jestem... taki... słaby.$B$B...o-o-odważny krasnolud - Lonebrow - wyruszył, by o-o-ostrzec Falfindela...$B$BLecz zanim... u-u-umrę...$B$B...moja żona, Treshala... jej wisiorek, symbol przywiązania do mnie... skradziony... przez jednego z tych p-p-plugawców...$B$BOdnajdź go p-p-proszę... i zanieś do Treshali, do Darnassus...$B$B...razem z w-w-wieścią o mej samotnej... śmierci.",
    ["O"] = "Odnajdź Wisiorek Treshali i zwróć go Treshali Fallowbrook z Darnassus.",
    ["T"] = "Gasnące życie",
  },
  [1143] = {
    ["D"] = "Rozumiem. Jeśli to, co mówisz, jest prawdą, nadszedł czas, by zaatakować. Jestem przekonany, że Athrikus przebywa na szczycie wieży. Bądź jednak $gostrożny:ostrożna;; chroni go wielu potężnych czarnoksiężników, znacznie groźniejszych niż ci, z którymi się dotąd $gspotkałeś:spotkałaś;.",
    ["O"] = "Zabij Athrikusa Narassina i przynieś jego głowę Balthule\'owi Shadowstrike\'owi, przebywającemu nieopodal Tower of Althalaxx.",
    ["T"] = "Wieża Althalaxxa",
  },
  [1144] = {
    ["D"] = "Nareszcie przybyła pomoc!$B$BNie masz pojęcia, jak długo byłem tutaj więziony. Nie pamiętam, kiedy ostatnim razem widziałem świat za tymi cierniami.$B$BWidzisz, jestem przedsiębiorcą. Jak to mawiają, nie pogardzę żadnym miedziakiem. Zwietrzyłem okazję - Mebok Mizzyrix sporo płacił za Redleaf Tuber z tej tu obory. Uznałem, że to będzie bułka z masłem. Jak widzisz, trochę się pomyliłem!$B$BTak czy owak, jeśli będziesz tak miły i pomożesz mi się stąd wydostać, na pewno tego nie pożałujesz.",
    ["O"] = "Wyprowadź Importera Willixa z Razorfen Kraul.",
    ["T"] = "Importer Willix",
  },
  [1145] = {
    ["D"] = "Wielu podróżników, którzy przewinęli się przez Crossroads, pomagało mi gromadzić jaja z Pola Gigantów. Wielu z nich podzieliło się też opowieściami o tamtejszych śmiertelnie groźnych stworzeniach. Usłyszałem wystarczająco dużo, aby uznać te owady za znacznie większe zagrożenie, niż początkowo uważał mój mistrz.$B$BPotrzebuję kuriera, który uda się do Orgrimmaru, do Belgroma Rockmaula. Ta sprawa to nie przelewki i powinien się jej podjąć tylko ten, kto potraktuje ją poważnie.$B$BBelgrom przebywa zazwyczaj u wejścia do gildii wojowników.",
    ["O"] = "Dostarcz zapieczętowany list Korrana do Belgroma Rockmaula z Orgrimmaru.",
    ["T"] = "Rosnący rój",
  },
  [1146] = {
    ["D"] = "A więc Korran doszedł do podobnego wniosku odnośnie tych owadów - wygląda na to, że są większym zagrożeniem, niż przypuszczaliśmy.$B$BKilka dni temu przybył do mnie ledwo żywy łowca z Thousand Needles. Jego oddział szturmowy miał przegnać krasnoludzką ekipę wykopaliskową z Shimmering Flats. Podczas ataku z jaskini na wykopaliskach wyłoniły się liczne owady i nieomal zgładziły całą grupę.$B$BOddziałem dowodził Moktar Krin. Schronili się na granicy Shimmering Flats. Zanieś mu tę wiadomość.",
    ["O"] = "Dostarcz Zapieczętowany List Belgroma do Moktara Krina w Thousand Needles.",
    ["T"] = "Rosnący rój",
  },
  [1147] = {
    ["D"] = "Hmm. Wygląda na to, że Belgrom widzi w tych potworach zagrożenie. Chce zepchnąć je do tych samych nor, z których wylazły.$B$BWygląda na to, że zabicie wysłanych przez Ligę Odkrywców krasnoludów to nie wszystko - muszę teraz posłać w połowie martwy oddział do następnej bitwy. Nie damy rady sami tego dokonać; nie w tym stanie. Strefa wykopaliskowa leży na południe stąd. Żadne krasnoludy nie powinny już stanowić problemu. Masz chęć wznieść swój miecz czy też kostur i w ramach pomocy odwalić część roboty?",
    ["O"] = "Zabij 5 Silithid Searchers, 5 Silithid Hive Drones, i 5 Silithid Invaders, po czym wróć do Moktara Krina z Thousand Needles.",
    ["T"] = "Rosnący rój",
  },
  [1148] = {
    ["D"] = "Uważnie oglądasz pancerz. Obróciwszy go w rękach zdajesz sobie sprawę, że sposób, w jaki nachodzą na siebie chitynowe płytki, czyni pancerz niesamowicie twardym. Nie przypomina niczego, co do tej pory widziałaś. Oglądasz pozostałą część ciała i zdajesz sobie sprawę, że te stworzenia są bardzo silne i wysoko rozwinięte.$B$BSpoglądając ponownie na pancerz dochodzisz do wniosku, że Korran chętnie zbadałby więcej tych stworzeń. Mogłoby mu to pomóc określić czym są i skąd się biorą.",
    ["O"] = "Zanieś 1 Silithid Heart, 5 Silithid Talons i 3 Intact Silithid Carapaces do Korrana z Crossroads.",
    ["T"] = "Fragmenty roju",
  },
  [1149] = {
    ["D"] = "Odnalazłeś mnie zatem, a może sprowadziło cię do mnie przeznaczenie? To nieistotne. Stoisz tu przede mną i tak oto twoja podróż rozpoczyna się na nowo.$B$BByt składa się wielu aspektów: ducha, ciała, umysłu. Niektóre z nich można oszacować tradycyjnymi, zakorzenionymi w kulturze metodami. Co do innych, możemy tylko mieć nadzieję, że są częścią nas. Jeśli się zgodzisz, poddam próbie niektóre z aspektów będących częścią twojej istoty.$B$BJeśli ci się powiedzie, staniesz się silniejszy. Jeśli nie podołasz zadaniu, doświadczysz ogromu Otchłani.$B$BPierwszy sprawdzian to Próba Wiary.",
    ["O"] = "Jeśli masz w sobie wiarę, skocz z pomostu górującego nad Thousand Needles.",
    ["T"] = "Próba Wiary",
  },
  [1150] = {
    ["D"] = "Cieszę się, że w świetle dotychczasowych wydarzeń twoja odwaga pozostała niezachwiana. Skoro twa wiara jest niewzruszona, nadszedł czas, by poddać próbie twe ciało.$B$BRozpoczniemy od próby wytrzymałości. Udaj się do Roguefeather Den, położonej na zachód od Freewind Post. Przedrzyj się w głąb leża i zniszcz zapasy pożywienia harpii. To wzbudzi ich gniew. Jeśli uda ci się wytrzymać dostatecznie długo, pojawi się sama Grenka Bloodscreech, by osobiście z tobą skończyć. Wówczas zabij ją i przynieś mi jej szpon, by ukończyć próbę.",
    ["O"] = "Przynieś Szpon Grenki Dornowi Plainstalkerowi z Thousand Needles.",
    ["T"] = "Próba Wytrwałości",
  },
  [1151] = {
    ["D"] = "Za czasów Starych Bogów znaczną część tego świata zamieszkiwały żywiołaki. Oddawały im cześć, zaś ci dzięki swej mocy umożliwiali im pobyt na tym świecie. Gdy Starzy Bogowie zostali wygnani, żywiołaki zniknęły z naszego świata i teraz powracają wyłącznie na żądanie potężnych magów.$B$BSą jednak wyjątki. Niektóre żywiołaki miały dość mocy, by pozostać tu na własną rękę. Jednym z nich jest Rok\'Alim.$B$BBy poddać próbie swą siłę, odnajdź Rok\'Alima w Thousand Needles i zabij go.",
    ["O"] = "Przynieś Fragmenty Rok\'Alima Dornowi Plainstalkerowi z Thousand Needles.",
    ["T"] = "Próba Siły",
  },
  [1152] = {
    ["D"] = "Nasz wspólny czas dobiega końca. Choć jestem człowiekiem oświeconym, Próba Wiedzy nie leży w mej gestii. Są nauki do zdobycia i miejsca do odwiedzenia, nad którymi inni sprawują władzę.$B$BJeśli jesteś gotowy, odszukaj Brauga Dimspirita - jest szamanem o wielkiej wiedzy. Podda cię dalszym sprawdzianom, dlatego zważaj na jego słowa, $N.$B$BGdy będziesz gotowy, odnajdź tunel łączący Stonetalon Mountains z Ashenvale - Braug przebywa nieopodal tego miejsca. I bądź ostrożny, nocne elfy mogą zechcieć utrudnić ci zadanie.",
    ["O"] = "Znajdź Brauga Dimspirita nieopodal wejścia na Talondeep Path w Stonetalon Mountains.",
    ["T"] = "Próba Wiedzy",
  },
  [1153] = {
    ["D"] = "W przeszłości $guczyniłeś:uczyniłaś; wiele, by mi pomóc, $C. Wódz jest zadowolony z moich dotychczasowych osiągnięć i prosi, bym z nową determinacją rzucił się w wir pracy. Honor nakazuje powiadomić go o wszystkim, czego tu $gdokonałeś:dokonałaś;, lecz najpierw chciałbym cię ponownie prosić o pomoc.$B$BOstatnio przybyli tu podróżnicy z południa, z miejsca zwanego Thousand Needles. Zabili tam kobolda, przy którym znaleźli próbkę niezwykłej rudy. Nie chcieli jednak jej sprzedać. Chciałbym dostać w ręce próbkę tej rudy do zbadania.",
    ["O"] = "Zdobądź Unrefined Ore Sample od kopacza lub geodety Gravelsnouta i przynieś ją Tatternackowi Steelforge\'owi z Camp Taurajo w Barrens.",
    ["T"] = "Próbka nowej rudy",
  },
  [1154] = {
    ["D"] = "Przeszłeś próby Dorna i teraz pragniesz przebyć kolejne. Bardzo dobrze. Ale stawiane przed tobą do tej pory wyzwania były dziecinne łatwe. Nietrudno jest sprawdzić ciało - umysł to zupełnie inna sprawa.$B$BUjmę to prosto: znajdź książkę, której tytuł ci podam, przeczytaj ją i odpowiedz na moje pytania, dotyczące jej treści.$B$BMusisz być ciekawy, o jaką książkę chodzi. To \"Dziedzictwo Aspektów\". Można ją znaleźć w czeluściach Dor\'Danil w południowym Ashenvale. Strzegą jej tam druidzi i ich poplecznicy.",
    ["O"] = "Znajdź \"Dziedzictwo Aspektów\" i zanieś je do Brauga Dimspirita, przebywającego nieopodal wejścia na Talondeep Path w Stonetalon Mountains.",
    ["T"] = "Próba Wiedzy",
  },
  [1155] = {
    ["D"] = "x",
    ["O"] = "x",
    ["T"] = "<NYI> <TXT> bug crystal side quest",
  },
  [1156] = {
    ["D"] = "x",
    ["O"] = "x",
    ["T"] = "<NYI> <TXT> speak to alchemist pestlezugg",
  },
  [1157] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<NYI> <TXT> pestlezugg needs items",
  },
  [1158] = {
    ["D"] = "x",
    ["O"] = "x",
    ["T"] = "<NYI> <TXT> speak to rabine saturna",
  },
  [1159] = {
    ["D"] = "$N, dobrze się spisałeś. Zaliczyłeś pierwszą część Próby Wiedzy, lecz pozostało jeszcze jedno pytanie, na które trzeba udzielić odpowiedzi. Jednak zadanie go nie należy do mnie.$B$BOdnajdź Parquala Fintallasa w Mieście Lordaeron. Zanim dopadła go plaga, był wielkim znawcą historii. Obecnie wciąż poszukuje oświecenia, ale nieco innej natury.$B$BNim o cokolwiek cię zapyta, będzie chciał coś od ciebie otrzymać, ale do tej pory radziłeś sobie po mistrzowsku, więc jestem pewien, że i z tą przeszkodą sobie poradzisz.",
    ["O"] = "Odnajdź w Undercity Parquala Fintallasa.",
    ["T"] = "Próba Wiedzy",
  },
  [1160] = {
    ["D"] = "Powiem Ci czego musisz szukać, a nawet pozwolę zadać mi pytanie, ale nie dlatego, że chcesz pokazać, na co Cię stać. Wiedza jest znacznie więcej warta niż siła. Choć zdaje się, że inni prześcignęli Cię w tej dziedzinie, to twoja wiedza o świecie okaże się cenniejsza.$B$BUdaj się do Monastery na północ od rejonu Tirisfal Glades. W tamtejszej bibliotece spoczywa księga zwana \"Beginnings of the Undead Threat\". Była używana przez obecnie spaczonych paladynów, aby trenowali do walki z moim rodzajem.$B$BDostarcz tę księgę do mnie.",
    ["O"] = "Znajdź księgę Beginnings of the Undead Threat i zwróć ją do Parqual Fintallas w mieście Undercity.",
    ["T"] = "Test Wiedzy",
  },
  [1161] = {
    ["D"] = "x",
    ["O"] = "x",
    ["T"] = "<NYI> <TXT> gossip shade of ambermoon",
  },
  [1162] = {
    ["D"] = "x",
    ["O"] = "x",
    ["T"] = "<NYI> <TXT> speak to hamuul runetotem",
  },
  [1163] = {
    ["D"] = "x",
    ["O"] = "x",
    ["T"] = "<NYI> <TXT> speak to tyrande whisperwind",
  },
  [1164] = {
    ["D"] = "Dziwka! Świnia! Kenata wciąż żyje; jej rodzina opływa w zdrowie i dostatek, podczas gdy ja cierpię. Zaiste, Opuszczona!$B$BMoja rodzina odeszła, zabrana przez plagę. Nasza posiadłość również przepadła; została ograbiona i spalona podczas wojny. I po tym wszystkim ona i jej wstrętne bachory mieli czelność ukraść jedyne cenne rzeczy, jakie mi zostały.$B$BPrzedmioty, które ukradli, już mnie nie obchodzą. Teraz chcę ich głów!$B$BZabij ich dla mnie! Idź do gospodarstwa Dabyrie na Wyżynach Arathiańskich, na północny wschód od Punktu Uchodźców.",
    ["O"] = "Przynieś Genavie Callow z Undercity głowy Kenaty, Fardela i Marcela Dabyrie.",
    ["T"] = "Okraść złodziei",
  },
  [1166] = {
    ["D"] = "Na kolana przed Naczelnik Mok\'Morokk!$B$BRexxar uczynić mnie potężny przywódca klanu Stonemaul!$B$BJa być dobry przywódca. Trzymać klan bezpieczny.$B$BPrzylecieć duże smoki i spalić nasz stary dom. Ja sprytny ogr. Tutaj znaleźć nowy dom dla klan.$B$BOpuścić stary dom tak szybko, że ja zapomnieć tabaki. Mała trollica, odzyskać me rzeczy. Iść na południe i znaleźć mój pyszniutki grog, moja tabaka i moja kasetka. Jak ty to zrobić, ja cię polubić. Poszukaj w Den of Flame i Stonemaul Ruins... one tam być, ja pewny!",
    ["O"] = "Naczelnik Mok\'Morokk z Brackenwall Village chce, byś odnalazł jego grog, tabakę i kasetkę w Dustwallow Swamp.",
    ["T"] = "Troski Naczelnika Mok\'Morokka",
  },
  [1167] = {
    ["D"] = "Przed zmierzeniem się z Athrikusem, być może korzystne będzie dla ciebie skonsultowanie się z Balthule. Nie mam żadnych wątpliwości, że on był czujny na swojej warcie w wieży. Może mieć jakieś informacje na temat ostatnich zmian.",
    ["O"] = "Porozmawiaj z Balthule Shadowstrike w pobliżu Tower of Althalaxx.",
    ["T"] = "Wieża Althalaxxa",
  },
  [1168] = {
    ["D"] = "Rexxar mianować Mok\'Morokka Naczelnikiem. Bardziej zależeć mu na władzy niż na ograch.$B$BCzarne smoki zabić wiele ogrów. Zabić żonę Tharga. Mok\'Morokk rozkazać nam uciekać. Kazać nam przyjść tutaj.$B$BOgr mieć walczyć. Ogr nie być dobry w bieganiu. Mok\'Morokka interesować jedynie Mok\'Morokk.$B$BJa nazywać domem Ruiny Kamiennych Maczug. Mi się podobać na południu. To miejsce to nie dom.$B$BPomóż ogrom walczyć z armią czarnych smoków. Ja chcieć zemsty. Ja chcieć wrócić do domu.",
    ["O"] = "Tharg z Brackenwall Village chce, byś $gzabił:zabiła; 15 Firemane Scouts, 10 Firemane Ash Tails i 5 Firemane Scalebanes.",
    ["T"] = "Armia czarnego smoka",
  },
  [1169] = {
    ["D"] = "Podczas gdy ten tchórzliwy głupiec Mok\'Morokk pławi się we władzy, zaś Tharg boryka się z demonami smutku i zemsty, oraz rywalizuje o przywództwo w klanie, tylko ja staram się określić, kto stoi za atakiem na nasz stary dom.$B$BSkąd to zakłopotanie w oczach, $N? Spodziewałeś się, że będę mówił niczym nieokrzesany opryszek, tylko dlatego, że jestem ogrem?$B$BWracając do sedna sprawy, przynieś mi serca i języki piskląt oraz młodych. Wytropię korzenie tego zła...",
    ["O"] = "Draz\'Zilb z Wioski Brackenwall chciałby, byś przyniósł mu 7 Searing Tongues i 7 Searing Hearts.",
    ["T"] = "Rozpoznanie lęgu",
  },
  [1170] = {
    ["D"] = "Stonemaul Village została zaatakowana przez potomstwo Onyxii. Ale dlaczegóż córka pana czarnych smoków, Śmiercioskrzydłego, miałaby zaatakować nasze ziemie?$B$BTo niezwykle niepokojące. Zapewne Onyxia miała swoje własne powody, by tu przybyć, daleko wykraczające poza atak na małą grupę ogrów.$B$BNatychmiast poinformuj Mok\'Morokka! Trzeba podjąć działania.",
    ["O"] = "Porozmawiaj z Naczelnikiem Mok\'Morokkiem z Wioski Brackenwall.",
    ["T"] = "Potomstwo Onyxii",
  },
  [1171] = {
    ["D"] = "Ty zostawić mnie teraz sam. Ty iść powiedzieć Draz\'Zilb, że my zostać tutaj. Tutaj nie być czarne smoki.",
    ["O"] = "Porozmawiaj z Draz\'Zilbem z Wioski Brackenwall.",
    ["T"] = "Potomstwo Onyxii",
  },
  [1172] = {
    ["D"] = "Lęg Onyxii został rozsiany po całym Smoczym Mroku. Nie wolno dopuścić, aby chociaż jedno nowe pisklę się wykluło.$B$BRuszaj do Wyrmbog na południu Dustwallow Marsh. Z pewnością wymościła tam sobie leże. Odszukaj przeklęte smocze jaja i zniszcz je.$B$BNigdy nie odzyskamy Stonemaul Village, jeśli okoliczne tereny pozostaną wylęgarnią.$B$BA co do Mok\'Morokka... mam inne plany odnośnie tego drania.",
    ["O"] = "Draz\'Zilb z Wioski Brackenwall chce, byś zniszczył 5 Eggs of Onyxia.",
    ["T"] = "Potomstwo Onyxii",
  },
  [1173] = {
    ["D"] = "Ty ośmielać się mierzyć z Naczelnik Mok\'Morokk?$B$BHa!$B$BJa zmiażdżyć mały $R!$B$BTy powiedzieć, gdy gotowy na solidne lanie.",
    ["O"] = "Pokonaj Mok\'Morokka i poinformuj o tym Draz\'Zilba z Wioski Brackenwall.",
    ["T"] = "Rzuć wyzwanie Naczelnikowi Mok\'Morokkowi",
  },
  [1174] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Gnomes Win!",
  },
  [1175] = {
    ["D"] = "Po wielkim zderzeniu goblińskiego \"Czerwonego Grzmotu\" z bazyliszkiem, Kronkrider zatrudnił mnie, bym zajął się torem. Nie wiem, co jedzą zwierzęta z tych równin, że dorastają do takich rozmiarów, ale musimy zachować ostrożność i przetrzebić je, by nie włóczyły się po torze podczas wyścigu.$B$BCoś ci powiem. Jeśli chcesz się stąd ruszyć i trochę zarobić, idź usunąć bazyliszki z okolicy.",
    ["O"] = "Zabij 10 Saltstone Basilisks, 10 Saltstone Crystalhides i 6 Saltstone Gazers dla Trackmastera Zherina z Shimmering Flats.",
    ["T"] = "Stłuczka na trasie",
  },
  [1176] = {
    ["D"] = "Gdy chodzi o wyścigi, liczy się każdy gram! Czy chodzi o lekkie podkręcenie wylotu mocy, drobne poluzowanie na cewce napinającej, czy obniżenie wagi ramy - trzeba brać wszystko pod uwagę.$B$BUżywamy kości sępów do usprawniania naszych ścigaczy, ponieważ umożliwiają idealne zrównoważenie wagi i wytrzymałości. Co więcej, łatwo zdobyć ich większą ilość, gdyż słone równiny roją się od sępów.$B$BPrzynieś mi trochę kości, a dobrze ci za nie zapłacę.",
    ["O"] = "Zdobądź 10 Hollow Vulture Bones dla Pozzika z Shimmering Flats.",
    ["T"] = "Superlekka konstrukcja",
  },
  [1177] = {
    ["D"] = "Mud duży ogr.$B$BByć głodny.$B$BIść zatłuc rybów. Przynieść Mudowi jeść.$B$BNakarmić Muda, albo Mud nakarmić się tobą.",
    ["O"] = "Mudcrush Durtfeet z północnych Dustwallow chce 8 Mirefin Heads.",
    ["T"] = "Głodny!",
  },
  [1178] = {
    ["D"] = "Nasz zespół wyścigowy stanowi źródło dumy wszystkich goblinów. Byłbyś zaskoczony, jakie osoby w ten czy inny sposób wnoszą swój wkład w jego działanie.$B$BZnasz Gazlowe\'a? Ściąga dla nas części z całego świata. Raz nawet zjawił się pogrzebać przy jednej z naszych instalacji!$B$BKilka tygodni temu powiedział, że przyśle nam nowy prototyp sprężarki paliwa, ale ta ciągle nie dotarła. Zwykle jest bardzo punktualny... Może zechciałbyś udać się do Ratchet i spytać go o nią? Nie byłbym tak natrętny, ale gnomy depczą nam po piętach!",
    ["O"] = "Porozmawiaj z Gazlowem w Ratchet.",
    ["T"] = "Gobliński sponsoring",
  },
  [1179] = {
    ["D"] = "Czy kiedykolwiek słyszałeś o Shimmering Flats? Jest to słona równina w Kalimdorze, na południe od kanionu Thousand Needles. Jest to doskonałe miejsce na wyścigi, bo jest bardzo płaskie!$B$BJest tam kilku braci gnomów, moich przyjaciół, wypróbowują swoje nowe rakietowe auto i z tego co słyszałem jest szybkie! Hah, tak szybkie, że piloci cały czas się rozbijają ulegając kontuzjom.$B$BPoprosili mnie więc o kilka kasków ochronnych, ale mam tutaj obowiązki. Nie mogę się do nich wybrać.$B$BCzy Ty mógłbyś?",
    ["O"] = "Zanieś skrzynkę kasków ochronnych do Wizzle Brassbolts w Shimmering Flats.",
    ["T"] = "Bracia Brassbolts",
  },
  [1180] = {
    ["D"] = "Wróćmy do tego, po co tu przyszedłeś. Wiem, że obiecałem Pozzik\'owi, że dostarczę nowy regulator paliwa dla niego, ale do tej pory mi go nie dostarczono. Revilgaz w Booty Bay powiedział, że go wyśle, lecz być może po prostu zapomniał.$B$BJeśli to prawda, to niewiele możemy zrobić. Co najwyżej możemy sprawdzić czy ładunek wyszedł z Booty Bay.$B$BZgłoś się do Wharfmaster\'a Lozgil\'a obok, on powinien sprawdzić rejestr załadunku.",
    ["O"] = "Porozmawiaj z Wharfmasterem Lozgil\'em w Booty Bay.",
    ["T"] = "Rejestr Goblina",
  },
  [1181] = {
    ["D"] = "Obawiam się, że nie mogę ci bardziej pomóc, $N. Jeżeli nadal Cię to interesuje, to sugeruję, byś sam porozmawiał z Baronem. Jeśli jest ktoś, kto zna biznesy Revilgaz\'a, to jest to właśnie Revilgaz.$B$BZnajdziesz go na najwyższym piętrze tawerny nad morzem.",
    ["O"] = "Porozmawiaj z Baron Revilgaz w Booty Bay.",
    ["T"] = "Gobliński Sponsoring",
  },
  [1182] = {
    ["D"] = "Widzisz, Shreddery Venture Company znajdujące się na jeziorze Nazferiti (w północnym Stranglethorn) zostały wyposażone w nowy model regulatora paliwa. Myślałem, że Pozzik będzie w stanie na tym skorzystać, jeśli zdobędzie szczegóły konstrukcji. Niestety, Cozzle, brygadzista tamtego rejonu, okazuje się być bardziej sprytny niż myślałem.$B$BWyglądasz na osobę, która może mieć więcej szczęścia w znajdywaniu owych planów. Wiem, że Cozzle trzyma je w swoim domu, ale na pewno są gdzieś pod kluczem.",
    ["O"] = "Przynieś plany regulatora paliwa do Barona Revilgaz\'a w Booty Bay.",
    ["T"] = "Goblin Sponsorship",
  },
  [1183] = {
    ["D"] = "Gotowy na powrót? Pozdrów ode mnie Pozzik\'a i powiedz mu, że jeśli kiedykolwiek by czegoś potrzebował, niech pyta śmiało. Będę czekał na wieści o nowym rekordzie toru, ustanowionym przez niego!",
    ["O"] = "Dostarcz plany regulatora paliwa do Pozzik\'a znajdującego się w Shimmering Flats.",
    ["T"] = "Goblin Sponsorship",
  },
  [1184] = {
    ["D"] = "Wróć do Belgrom w mieście Orgrimmar i przekaż mu, że Moktar czynił dobrze to co mu przykazano w Thousand Needles. Przekaż mu jeszcze, że me badania postępują i mam nadzieje się czegoś dowiedzieć już niedługo. To go powinno wielce zadowolić.",
    ["O"] = "Powróć do Belgrom Rockmaul w mieście Orgrimmar.",
    ["T"] = "Części Roju",
  },
  [1185] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "A pod pokrywą było...",
  },
  [1186] = {
    ["D"] = "Będę zajęty pracą przy zintegrowaniu tego nowego regulatorara paliwa z naszymi modelami wyścigowymi, ale jeśli chciałbyś wspomóc nasz zespół jeszcze trochę, to pogadaj z Razzeric. On jest naszym pilotem - naszym osiemnastym pilotem, tak w ramach ścisłości - i lubi co nieco modyfikować swój ścigacz.$B$BWięc nie zdziw się więc jak jego ścigacz będzie... no tego, tak trochę się wyróżniał...",
    ["O"] = "Porozmawiaj z Razzeric na Shimmering Flats.",
    ["T"] = "Osiemnasty Pilot",
  },
  [1187] = {
    ["D"] = "Pozzik jest świetnym mechanikiem, to oczywiste, ale on się po prostu boi porządnie dozbroić i wziąć się za ten wyścig. Ale nie ja.$B$BKiedy Pozzik skończy ze ścigaczem, poświęcę nieco czasu na swoje własne modyfikacje - no wiesz, tu poluzować sterownicę, wyrzucić kilka części ramy i dodać nieco mocy!$B$BZamówiłem Seaforium Booster u Shreev z Gizmorium w Gadgetzan, ale najwyraźniej sterowiec, którym go wysłano rozbił się w Dustwallow Marsh! Muszę to mieć, $N!",
    ["O"] = "Odzyskaj Seaforium Booster dla Razzeric w Shimmering Flats.",
    ["T"] = "Modyfikacje Razzerica",
  },
  [1188] = {
    ["D"] = "Ale zaczekaj, co to jest? Shreev zostawił zabezpieczenie włączone. To ciągle będzie ograniczać zasób mocy, który zaczerpnąć mogę ze wzmacniacza. No mówiłem mu, że ma go wyłączyć! To nie dobrze.$B$BMusisz zabrać ten wzmacniacz do Gadgetzan Gizmorium znajdującego się w rejonie Tanaris Desert i niech Shreev ściągnie to zabezpieczenie.",
    ["O"] = "Przynieś Seaforium Booster do Shreev z Gadgetzan.",
    ["T"] = "Po pierwsze Bezpieczeństwo",
  },
  [1189] = {
    ["D"] = "Proszę, zrobiłem co chciał Razzeric. Tylko powiedz mu, żeby był ostrożny, gdy to wyłączy. Jeśli popełni choćby najmniejszy błąd, zamiast ruszyć do przodu, zostanie z niego tylko wypalona plama na trasie.$B$BA byłoby szkoda, gdyby tak się stało. Kto wie, czy nasz dziewiętnasty kierowca będzie na tyle dobry?",
    ["O"] = "Zwróć Modified Seaforium Booster do Razzerica w Shimmering Flats.",
    ["T"] = "Bezpieczeństwo Przede Wszystkim",
  },
  [1190] = {
    ["D"] = "Bracia Brassboltowie odkryli nowy materiał budowlany, jest to jedyne wytłumaczenie, które ma sens. Ich wozy zaczęły funkcjonować szybciej niż pierwotnie, lecz ich plany oraz wszystkie dane, które zgromadziliśmy z ich ruin są identyczne.$B$BWiemy jedynie, że Rizzle Brassbolt skupił się na planach jego nowego odkrycia niemalże całkowicie.$B$BZamek jest w stanie wytworzyć dla Ciebie dywersję, abyś był w stanie ukraść od nich schematy.",
    ["O"] = "Niechaj Zamek wytworzy dywersje, a następnie wykradnie plany Rizzle\'a dla Pozzik\'a z Shimmering Flats.",
    ["T"] = "Trzymając tempo",
  },
  [1191] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Dystrakcja Zamek\'a",
  },
  [1192] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Ruda Indurium",
  },
  [1193] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Uszkodzona Pułapka",
  },
  [1194] = {
    ["D"] = "Schematy Rizzlea opisują proces udoskonalenia rudy Indurium. Wedle jego bazgrołów ruda Indurium pozyskiwana jest z krasnoludzkiej strefy wykopaliskowej Uldamanu na Badlands.$B$BDuża część notatek odnosi się do właściwości żaroodpornych.$B$BPapiery są przyciśnięte czymś co wygląda na kawałek nierafinowanej rudy Indurium.",
    ["O"] = "Przynieś Sample of Indurium Ore do Pozzika w Shimmering Flats.",
    ["T"] = "Schematy Rizzlea",
  },
  [1195] = {
    ["D"] = "Centaury Galaka w Thousand Needles chronią pewien artefakt od czasów stworzenia centaurów.$B$BChcielibyśmy go odzyskać, lecz potrzebujemy do tego fiolki wody z jednej ze studni księżycowych nocnych elfów.$B$BAby pozyskać wodę, będziesz $gmusiał:musiała; nabyć jedną z fiolek noszonych przez driady blisko Raynewood Retreat w sercu lasu Ashenvale. Jest tam studnia księżycowa blisko zachodniego brzegu rzeki Falfarren, na południe od głównej drogi, gdzie będziesz $gmógł:mógł; napełnić fiolkę.",
    ["O"] = "Zwróć Filled Etched Phial do Zangena Stonehoofa w Thunder Bluff.",
    ["T"] = "Święty Płomień",
  },
  [1196] = {
    ["D"] = "Dostarcz napełnioną fiolkę do Raua Cliffrunnera w Posterunku Freewind w południowo-wschodnim Thousand Needles. Możesz dotrzeć do Thousand Needles poprzez skorzystanie z wielkiej windy w południowym krańcu Barrens.$B$BNie zdziwi mnie jak pomożesz nam w dalszych krokach.",
    ["O"] = "Dostarcz Filled Etched Phial do Raua Cliffrunnera w Freewind Post.",
    ["T"] = "Święty Płomień",
  },
  [1197] = {
    ["D"] = "Używając wody, którą $gprzyniosłeś:przyniosłaś;, będziesz w stanie chwilowo zgasić płomień, który chroni relikt centarów. Efekt ten nie będzie utrzymywał się na stałe, dlatego musisz być $gszybki:szybka;.$B$BSplithoof Crag, twierdzę centaurów znajdziesz na północ stąd. Płomień znajduje się w dobrze strzeżonej części twierdzy, dlatego bądź $gostrożny:ostrożna;.$B$BCentaury Galaka mają przewagę liczebną i będą raczej niechętni do poddania czegoś tak im drogiego.",
    ["O"] = "Zdobądź Cloven Hoof dla Rau Cliffrunner w Freewing Post.",
    ["T"] = "Święty Płomień",
  },
  [1198] = {
    ["D"] = "Wiele plotek krąży na temat rzekomej unii kultu Twilight\'s Hammer i Nagów wewnątrz Blackfathom Deeps na wybrzeżach Ashenvale.$B$BMoja rola jako strażnika Argent Dawn to zebrać jak najwięcej informacji, żebyśmy mogli wiedzieć, gdzie potrzebna jest pomoc.$B$BMinęło już kilka dni od kiedy wysłałem zwiadowcę, żeby sprawdził aktywność w Blackfathom Deeps. Argent Guard Thaelrid do tej pory nie wrócił.$B$BMoi inni zwiadowcy są zajęci innymi ważnymi sprawami.$B$BZnajdź Thaelrid\'a dla mnie, $N.",
    ["O"] = "Znajdź Argent Guard Thaelrid w Blackfathom Deeps.",
    ["T"] = "W poszukiwaniu Thaelrida",
  },
  [1199] = {
    ["D"] = "Wzmocnieni przez starożytne rytuały chaotycznych Old Gods, członkowie Twilight Hammer starają się przywrócić swych mrocznych panów, i zasiać śmierć i terror na całym świecie.$B$BWierzymy, że Twilight Hammer zjednoczyło się z Naga i gromadzą się w Blackfathom Deeps na wybrzeżach Ashenvale.$B$BCzegokolwiek nie planują w otchłaniach starej światyni - muszą zostać powstrzymani.$B$BWalcz z nimi i przynieś dowody swoich zasług, a twoje starania będą szczodrze nagrodzone.",
    ["O"] = "Przynieś 10 Twilight Pendants do Argent Guard Manadaos w Darnassus.",
    ["T"] = "Zapada Zmierzch",
  },
  [1200] = {
    ["D"] = "Siły mnie opuściły. Potrzebuję Twojej pomocy!$B$BDawno temu to miejsce było Wielką Świątynią Elune. Ale nieszczęście przerodziło to miejsce w ruinę, kiedy zepsucie Starego Boga wypełzło z głębin ziemi i skaziło Księżycową Studnię.$B$BAku\'Mai, sługa Starego Boga, wyszedł z wód.$B$BKultyści Twilight Hammer zjednoczyli się z Nagami w okupacji tych ziem. Kultyści dowodzeni przez Kelris\'a, poświęcili niewinnych Aku\'Mai\'owi by zyskać moc.$B$BZabij Kelris\'a i przynieś jego głowę do Selgorma w Darnassus, $N, proszę.",
    ["O"] = "Przynieś głowę Twilight Lord Kelris\'a do Dawnwatchera Selgorma w Darnassus.",
    ["T"] = "Podłość Blackfathom",
  },
  [1201] = {
    ["D"] = "Horda oraz Przymierze utrzymują niepewny pokój. Pomniejsze potyczki oraz tajne działania podejmowane są jedną stroną przeciwko drugiej, i naszym obowiązkiem jest upewnienie się, że Horda jest na szczycie.$B$BTeraz jest okazja, aby to zrobić.$B$BInfiltratorzy z Sojuszu zajęli pozycję na wschód od wioski Brackenwall. Szpiegują wieś oraz meldują nasze ruchy do Theramore, na co nie możemy pozwolić.$B$BWytrop dywersantów i zgładź ich. Przekaż wyraźną wiadomość do ich przełożonych, że nie będziemy tolerować obecności ich szpiegów!",
    ["O"] = "Zabij 9 Theramore Infiltrators, następnie wróć do Nazeera Bloodpike\'a w Brackenwall Village.",
    ["T"] = "Szpiedzy Theramore",
  },
  [1202] = {
    ["D"] = "$N, wysłaliśmy dwóch naszych szpiegów, by ukradli dokumenty ze statku w dokach Theramore. Udało się im, lecz zostali złapani i musieli wyrzucić dokumenty do morza.$B$BJednemu z nich później udało się uciec, lecz nie był w stanie odzyskać papierów. Zameldował mi o swojej porażce, a ja teraz przydzielam to zadanie tobie.$B$BDokumenty są w skrzynce, gdzieś w wodach pod dokami Theramore. Znajdź je i mi przynieś, $N.",
    ["O"] = "Przynieś Captain\'s Documents do Nazeera Bloodpike\'a w Brackenwall Village.",
    ["T"] = "Doki Theramore",
  },
  [1203] = {
    ["D"] = "Muszę coś pociąć. Nie mogę Ci powiedzieć co zamierzam ciąć, ale... potrzebuję dla siebie ostrze. Nie byle jakie ostrze...$B$BNiektórzy mówią na to pałasz księżycowej stali. Ja nazywam to machające ostrze.$B$BTy pomóc mi? Może znajdziesz je w mieście, może porozmawiasz z kowalem i on zrobi ją dla ciebie.$B$BAle nie zwlekaj z tym. To co tnę nie trwa wiecznie...",
    ["O"] = "Dostarcz Moonsteel Broadsword do Jarla w Dustwallow Marsh.",
    ["T"] = "Jarl Potrzebuje Ostrza",
  },
  [1204] = {
    ["D"] = "Pracuję nad daniem, które nazywam \"Mudrock Soup and Bugs.\" Wciąż potrzebuję głównych składników i... więc, nie sądzę, że przetrwam długo na zewnątrz miasta w Dustwallow Marsh!$B$BWięc, $N, możesz coś dla mnie upolować? Na początek potrzebne mi są języki żółwi murdock. Możesz je znaleźć przy brzegu, najczęściej w okolicy zatoki.$B$BNie szukam jednak byle jakich języków! Słyszałem, że języki niektórych murdocków są rozwidlone...$B$BPowiadają, że rozwidlone języki mają wyrazisty smak i ja chce uzyskać taki w moim daniu...",
    ["O"] = "Przynieś 8 Forked Mudrock Tongues do Morgana Sterna w Theramore.",
    ["T"] = "Mudrock Soup and Bugs",
  },
  [1205] = {
    ["D"] = "Deadmire jest pradawnym krokodylem z Dustwallow Marsh. Czas by zginął.$B$BStare kości miażdżą się, gdy ciągnie swe wielkie ciało przez bagna, pomimo tego nadal porusza się z siłą i szybkością młodego osobnika. Jego wiekowe ciało torturuje wspaniałego ducha, który jest w nim, ducha, którego ogień nie zgaśnie.$B$BTeraz żyje w stałym szaleńczym bólu. Musisz zakończyć życie tego szlachetnego stworzenia, $N. Musisz zgładzić Deadmire.",
    ["O"] = "Przynieś Deadmire\'s Tooth do Melora z Thunder Bluff.",
    ["T"] = "Deadmire",
  },
  [1206] = {
    ["D"] = "Nie ma to jak sok z oczu. Szkoda tylko, że zwierzyna ma tylko jedną parę oczu.$B$BLecz pająki, te to maja ich od groma. Oko na oku można by rzec. Sok z oczu Darkmist, ten to dopiero jest smaczny. Orzeźwiające i akuratnie słony! Nie wyłuskane oczy pająków... Już czuje ich smak.$B$BPająki Darkmist znajdują się na zachód z ta, a dokładnie w Darkmist Cavern. Domyśliłeś się już, że jaskinia zawdzięcza swą nazwę pająkom... A może jest na odwrót? Hmmm...",
    ["O"] = "Przynieś 20 Unpopped Darkmist Eyes do \"Swamp Eye\" Jarl w Swamplight Manor.",
    ["T"] = "Jarl potrzebuje oczu",
  },
  [1218] = {
    ["D"] = "Lubię gotowanie. Dobrą bagienną kuchnię. Smażone zielone żabie udka i tym podobne.$B$BAle do gotowanie potrzebuję przyprawy. Łagodnej przyprawy. Uduszę z tego gulasz, wyssę go do cna i Tobie też trochę dam.$B$BLubisz gulasz?",
    ["O"] = "Przynieś 3 Soothing Spices do \"Swamp Eye\" Jarla w Dustwallow Marsh.",
    ["T"] = "Łagodne Przyprawy",
  },
  [1219] = {
    ["D"] = "Przeczesanie terenu poskutkowało znalezieniem oderwanej ręki Orka. Ręka zaciśnięta była na wyrzeźbionej z kości tubie. W tubie znaleźliśmy kawałek brudnego dokumentu.$B$BDokument był napisany w języku orków... i wygląda na ważny dokument.",
    ["O"] = "Przynieś Spy\'s Report do Porucznika Aden\'a w Theramore.",
    ["T"] = "Report Orka",
  },
  [1220] = {
    ["D"] = "Captain Vimes powinien zobaczyć raport orka, który znalazłeś, $N. On zna język orków lepiej niż wszyscy. Powinien również wiedzieć, że są tam szpiedzy Hordy w okolicy Theramore!$B$BThe captain jest w barakach, na północno-wschodniej stronie Theramore Isle.",
    ["O"] = "Przynieś the Spy\'s Report do Captain Garran Vimes.",
    ["T"] = "Kapitan Vimes",
  },
  [1221] = {
    ["D"] = "Bulwy Blueleafów są przysmakiem na całym świecie! Ale są bardzo, ale to bardzo rzadkie. Jedyne miejsce, gdzie można je znaleźć tutaj w Barrens znajduje się głęboko pod ziemią, w Zagrodzie Razorfen.$B$BLecz nawet tam ich znalezienie jest niemożliwe, jeżeli nie wiesz gdzie szukać! To dlatego wytresowałem te susły Snufflenose, żeby szukały za mnie. One mają wspaniałe nosy i mogą wywęszyć bulwy z pięćdziesięciu kroków.$B$BTo nie będzie łatwe, ale jeśli dasz mi trochę bulw, sowicie zapłacę.",
    ["O"] = "Weź Crate with Holes.$BWeź Snufflenose Command Stick.$BWeź i przeczytaj Snufflenose Owner\'s Manual.$B$BW Razorfen Kraul, użyj Crate with Holes, aby przywołać Snufflenose Gopher i użyj Command Stick na suśle, aby ten zaczął szukać Tubers.$B$BPrzynieś 6 Blueleaf Tubers, Snufflenose Command Stick i Crate with Holes do Meboka Mizzyrixa w Ratchet.",
    ["T"] = "Bulwy Blueleafów",
  },
  [1222] = {
    ["D"] = "Świetnie, nareszcie ktoś kto nie chce mnie pożreć!$B$BPotrzebuję pomocy w zajmowaniu się miejscowymi zwierzakami, a ty pasujesz do tej roboty idealnie.$B$BKucharz Morgan Stern tworzy nowy przepis i wysłał mnie po liście boberka. Chyba myśli, że są smaczne.$B$BSzukając tych roślin... dałem się otoczyć! Możesz mi pomóc, w czasie kiedy ja poszukam roślin?",
    ["O"] = "Eskortuj \"Stinky\" Ignatza, następnie porozmawiaj z Morganem Sternem w Theramore.",
    ["T"] = "Ucieczka Śmierdziucha",
  },
  [1238] = {
    ["D"] = "Przeczesanie terenu poskutkowało znalezieniem urwanej ręki Orka. Zaciśnięta jego dłoń trzymała wyrzeźbioną tubę w kości. W tubie znaleziono brudny dokument.$B$BTen dokument to raport zrobiony przez Orka szpiegującego przez tygodnie miasto Theramore.$B$BPo sprawdzeniu raportu, wiemy, że musi być dostarczony do orkowego mistrza szpiegów w Brackenwall Village.",
    ["O"] = "Dostarcz Spy\'s Report do Nazeer\'a Bloodpike\'a w Brackenwall Village.",
    ["T"] = "Zagubiony Report",
  },
  [1239] = {
    ["D"] = "Energiczne wykopy odsłoniły głowę Orka, brutalnie oderwaną przy szyi. Jego usta zamarły w grymasie, a jego martwe oczy patrzą stanowczym tonem.",
    ["O"] = "Przynieś Defiant Orc Head do Nazeer Bloodpike w Brackenwall Village.",
    ["T"] = "Odcięta głowa",
  },
  [1240] = {
    ["D"] = "Musimy poznać zdarzenia dotyczące śmierć Marg\'a! I jedyną drogą, aby to zrobić, $N, jest użycie magii szamana trolli.$B$BPrzynieś głowę Marga Kin\'weelay znajdującego się w Stranglethorn Vale, w Grom\'gol Base Camp. $B$BKin\'weelay jest najpotężniejszym szamanem Plemienia Darkspear. Jeśli ktokolwiek może porozmawiać z duszą Marga Nighteye, to jest nim ten troll.",
    ["O"] = "Zanieś głowę Defian Orc do Kin\'weelaya znajdującemu się w Grom\'gol Base Camp w Stranglethorn Vale.",
    ["T"] = "Szaman Trollów",
  },
  [1241] = {
    ["D"] = "Niedawno dyplomata został wysłany do Theramore, żeby spotkać się z Jainą Proudmoore. Ten dyplomata nigdy nie przybył.$B$BI wierzę, że Bractwo Defias ma w tym udział, ale nie jestem pewny jaki. Zniknięcie dyplomaty na razie umknęło uwadze ludzi, jednak nie na długo.$B$BAgenci króla już oczyszczają miasto ze wskazówek, ale mam własne kontakty, które chciałbym zaangażować.$B$BW Alei Bohaterów jest mój stary przyjaciel Jorgen. Znajdź go, daj mu tę notatkę i podążaj za jego instrukcjami.",
    ["O"] = "Znajdź Jorgen\'a w mieście Stormwind.",
    ["T"] = "Zaginiony Dyplomata",
  },
  [1242] = {
    ["D"] = "Weź ten oto list do Ellinga Triasa. O niczym innym z nim nie rozmawiaj. Wystarczy być uprzejmym i poczekać na odpowiedź od niego. I nie martw się, odpowie.$B$BPowiem ci jeszcze jedno, $N: traktuj tę sprawę poważnie i trzymaj gębę na kłódkę.$B$BZnajdziesz Triasa w jego sklepie z serami, \"Sklep z serami u Tirasa\" w Dzielnicy Handlowej. Powodzenia.",
    ["O"] = "Dostarcz Jorgen\'s Sealed Note do Ellinga Triasa w Stormwind.",
    ["T"] = "Zaginiony Dyplomata",
  },
  [1243] = {
    ["D"] = "Jorgen, ty skurczy.... Więc tak to będzie, huh?$B$BW porządku, poradzę sobie. Mam nadzieje, że dopadnie go Wirująca Otchłań!$B$BSytuacja wygląda następująco, $N. Popytam moich miejscowych informatorów, ale ty wykonasz brudną robotę za parę miedziaków.$B$BKieruj się do Darkshire w Duskwood i znajdź strażnika Backusa - zwykle patroluje północną drogę, tuż przy mieście. Powiedz mu, że badasz dla mnie aktywność Bractwa Defias, a on pomoże ci od strony informacyjnej.",
    ["O"] = "Daj Sealed Note strażnikowi Backusowi w Duskwood.",
    ["T"] = "Zaginiony Dyplomata",
  },
  [1244] = {
    ["D"] = "Działalność Bractwa Defias? Cóż, stale można się na nią natknąć; nawet jeśli działają samotnie, uważamy ich za zagrożenie.$B$BGdyby głębiej się nad tym zastanowić, miało tu w sumie miejsce pewne dziwne zjawisko. Co prawda kilka tygodni temu, kilku ich agentów zebrało się w pobliżu Addle\'s Stead. Z raportu wnioskuję, że chodziło o coś ważnego.$B$BMoże udasz się tam na zwiad i przyniesiesz mi cokolwiek tam znajdziesz?$B$BZagroda znajduje się na południe od drogi przecinającej granicę Westfall i Duskwood.",
    ["O"] = "Znajdź Defias Docket i zwróć strażnikowi Backusowi w Duskwood.",
    ["T"] = "Zaginiony Dyplomata",
  },
  [1245] = {
    ["D"] = "Łoł, to wygląda na bardzo złożone jak na coś, co miało po prostu wyprowadzić cię w pole. Nie powinienem w ogóle tego oglądać. Zabierz to do Triasa - on będzie w stanie cokolwiek z tego zrozumieć. I nie pozwól NIKOMU stanąć ci na drodze. To mnie przerasta. Może też przerasta jego, ale to się zobaczy.$B$BI jeśli $gmógłbyś:mogłabyś;, $N, nie wspominaj nikomu, że ci pomogłem. Jeśli moi przełożeni dowiedzą się, że wiedziałem o czymkolwiek związanym z tym, a nie podzieliłem się z nimi, to prawdopodobnie mnie powieszą.",
    ["O"] = "Zanieś Defias Docke do Ellinga Trias w Stormwind.",
    ["T"] = "Zaginiony Dyplomata",
  },
  [1246] = {
    ["D"] = "Tak, kiedy teraz o tym myślę... Dashel... Dashel coś tam ... Jak on się nazywał? FIST! Dashel Stonefist. W pewnych kręgach mówią na niego Piącha - prawdopodobnie ze względu na to, że lubi wdawać się w burdy.$B$BMożesz znaleźć go na starym mieście, przeważnie w samym jego centrum. Idź i pogadaj z nim. Jeśli będziesz $gmusiał:musiała;, użyj miecza albo czegoś ciężkiego i tępego, aby go przekonać, żeby się trochę otworzył. I nie wahaj się. Jeśli jest taki jak papiery sugerują, to nie przekaże ci żadnych informacji ochoczo.",
    ["O"] = "Porozmawiaj z Dashelem Stonefistem w Stormwind.",
    ["T"] = "Zaginiony Dyplomata",
  },
  [1247] = {
    ["D"] = "Więc... um... Być może coś wiem o tym spotkaniu w Addle\'s Stead. To działo się parę tygodni temu, o ile mnie pamięć nie myli. Naprawdę, nie miałem w tym swojego udziału. Moja rola została wykonana, gdy plan A zawiódł... przeklęci poszukiwacze przygód.$B$BGość, którego mieliśmy przygotowanego na wdrożenie planu B opuścił Port Menethil; nazywa się Slim. To wszystko co wiem odnośnie ich zapasowego planu.",
    ["O"] = "Porozmawiaj z Ellingiem Trias w Stormwind.",
    ["T"] = "Zaginiony dyplomata",
  },
  [1248] = {
    ["D"] = "Mój kontakt osiadł w Wetlands, w portowym mieście Menethil. Powinien być chętny pomóc jedynie usłyszawszy twoje słowa, jeżeli powiesz mu, że pracujesz dla mnie. Ma na imię Mikhail. Przed opuszczeniem Stormwind kilka lat temu, wspominał coś o podjęciu zawodu barmana.$B$BPorozmawiaj z nim, znajdź tego Slima i dowiedz się czy jest coś jeszcze co powinniśmy wiedzieć o tym porwanym dyplomacie. Musimy się dowiedzieć gdzie go zabrali, albo chociaż kim jest. W liście nie ma słowa o ich planach, kiedy już zostanie złapany.",
    ["O"] = "Porozmawiaj z Mikhail\'em w Wetlands.",
    ["T"] = "Zaginiony Dyplomata",
  },
  [1249] = {
    ["D"] = "Mówisz, że Elling cię tu wysłał? W takim razie moja gościnność powiększyła się dziesięciokrotnie. Będziesz czegoś $gpotrzebował:potrzebowała;, po prostu zapytaj. Zrobię wszystko co w mojej mocy by cię wesprzeć.$B$BHmm, Slim, mówisz? Nie jestem pewien czy to imię brzmi znajomo, ale będę trzymał na niego oko.$B$BNie oglądaj się, $N, dżentelmen przy wyjściu patrzy w naszą stronę. Przysłuchuje się naszej konwersacji nieco zbyt uważnie, jeśli wiesz co mam na myśli. Na twoim miejscu zrobiłbym co możesz, by go obezwładnić zanim rzuci się w stronę drzwi.",
    ["O"] = "Obezwładnij Tapoke Jahn zanim ucieknie, a natępnie wróć do Mikhail w Menethil.",
    ["T"] = "Zaginiony Dyplomata",
  },
  [1250] = {
    ["D"] = "Defias nie zapłacili mi wystarczająco, bym umarł walcząc w ich sprawie. Porwano króla. Tak, króla Stormwind, a nie jakiegoś podrzędnego dyplomatę. Był właśnie w drodze na spotkanie z Jainą Proudmore - najwyraźniej było to ważne spotkanie i wielka tajemnica. Ale nie tylko Bractwo Defias jest w to zamieszane. Ktoś z nimi współpracuje. Myślę, że wiedzieli, iż ta sprawa ich przerasta.$B$BJa miałem tylko dostarczyć ich ludzi na pokład królewskiego statku, dopóki ten był w porcie. Gość, który mi to zlecił nazywał się Hendel. To wszystko co wiem. Przysięgam!",
    ["O"] = "Porozmawiaj z Mikhail w Wetlands.",
    ["T"] = "Zagubiony Dyplomata",
  },
  [1251] = {
    ["D"] = "Żelazna tarcza, poczerniona ogniem, który zapłonął w gospodzie, jest związana z rozpadającym się kominem, czyli jedną z niewielu rzeczy jakie zostały po gospodzie Shady Rest.$B$BTarczę można wydobyć z cegieł komina.",
    ["O"] = "Przynieś Blackened Iron Shield do Krog\'a w Brackenwall Village.",
    ["T"] = "Czarna Tarcza",
  },
  [1252] = {
    ["D"] = "Delikatny błysk światła rzuca Ci się w oko z pod gruzu. Oczyszczenie miejsca ukazuje insygnię ze złotą kotwicą: znak Theramore.$B$BPod kotwicą widnieje napis \"Porucznik Paval Reethe\".",
    ["O"] = "Przynieś odznakę Reethe\'a do Kapitana Garran Vimes w Theramore.",
    ["T"] = "Porucznik Paval Reethe",
  },
  [1253] = {
    ["D"] = "Żelazna tarcza, poczerniona przez ogień, który spalił gospodę, jest wśród gruzów komina, jednej z niewielu rzeczy jakie zostały po gospodzie Shady Rest.$B$BTarczę można wydostać z cegieł komina.",
    ["O"] = "Przynieś Blackened Iron Shield do Captain Garran Vimes w Theramore.",
    ["T"] = "Czarna Tarcza",
  },
  [1258] = {
    ["D"] = "Innym składnikiem mojego nowego przepisu są opancerzone nogi gigantycznego kraba. Te, które znajdują się w Dustwallow - nazywają je Muckshellami - się nie nadają!$B$BObawiam się, że jedyne odpowiednie kraby żyją dalako stąd, w Swamps of Sorrows. Skorupa z nogi kraba jest kluczowym elementem prezencji potrawy, więc potrzebuję nietkniętych, gładkich nóg. Dorosły krab może mieć jedną lub dwie takie nogi, a ja potrzebuję ich dużo, aby ukończyć moje danie.$B$BWięc $N, jesteś chętny na wyprawę?",
    ["O"] = "Przynieś 12 Pristine Crawler Legs do Morgana Sterna w Theramore.",
    ["T"] = "...oraz robaki",
  },
  [1259] = {
    ["D"] = "Nie rozpoznaje imienia Lieutenant Paval Reethe. Największą szansę miałbyś, pytając Adjutant\'a Tesoran\'a. Prowadzi archiwa strażników Theramore, od ludzi do ich ekwipunku.$B$BPowinien Ci powiedzieć, kim jest Reethe poprzez zajrzenie do archiwów.",
    ["O"] = "Dowiedz się więcej na temat Reethe od Adjutant\'a Tesoran\'a w Theramore.",
    ["T"] = "Porucznik Paval Reethe",
  },
  [1260] = {
    ["D"] = "Projektuję nowy jadłospis dla restauracji. Będzie wypełniony wiejskimi potrawami z \"zalewowym\" motywem. Myślę, że moi klienci na Blue Recluse je pokochają!$B$BWysłałem mojego bratanka Morgan do Theramore, miasta na skraju Dustwallow Marsh, żeby zbierał przepisy od lokalnych mieszkańców i muszę wiedzieć co udało mu się do tej pory znaleźć.$B$BPodróż do Theramore jest długa. Za długa dla mnie. Ale założę się, że taki młody $C jak ty będzie uradowany na myśl o takiej wyprawie, prawda ?",
    ["O"] = "Porozmawiaj z Morgan Stern w Theramore.",
    ["T"] = "Morgan Stern",
  },
  [1261] = {
    ["D"] = "Przeklęty skorupiak! Nie zabijesz Marga! Ah, ale jestem martwy. Więc musiałeś mnie ubić,...$B$Bale moja misja! Moja misja! $N, musisz ją ukończyć.$B$BTymczasem niedaleko Theramore, odkryłem grupę żołnierzy Alliance na plaży. Jeden z nich miał naszyjnik. Naszyjnik z taką większą ilością klejnotów, na którą nie stać zwykłego żołnierza!$B$BTej nocy, zakradłem się do ich obozu i ukradłem naszyjnik, lecz po powrocie, skorupiak mnie znalazł i zabił!$B$B$N, musisz znaleźć skorupiaka i odzyskać naszyjnik!",
    ["O"] = "Przynieś naszyjnik z klejnotami do Nazeer\'a w Brackenwall Village.",
    ["T"] = "Marg Mówi",
  },
  [1262] = {
    ["D"] = "To dziwne, że naszyjnik, który Marg ukradł, był w rękach zwykłych żołnierzy. Być może właściciel był przebrany lub sami żołnierze go ukradli!$B$BNieistotne. Musimy znaleźć szlachcica, który jest właścicielem naszyjnika, jeśli mamy rozwikłać tę zagadkę.$B$BZanieś naszyjnik do Zor Lonetree w Orgrimmar. Jest dobrze wyszkolony w polityce Alliance i będzie wiedział czy owy naszyjnik prowadzi do szlachciców Stormwind.",
    ["O"] = "Przynieś Jeweled Pendant do Zor\'a Lonetree w Orgrimmar.",
    ["T"] = "Zamelduj się u Zor\'a",
  },
  [1263] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "The Burning Inn <CHANGE TO GOSSIP>",
  },
  [1264] = {
    ["D"] = "Na początku każdego miesiąca, wszyscy marynarze z Kul Tiras dostają wypłatę i zazwyczaj opuszczają Theramore dla innego miejsca. Duża część z nich przychodzi tu hulać, uganiać się za kobietami, czy po prostu spędzić miło czas. Jedna z takich grup, była stałym bywalcem w tawernie i wierzę, że Hendel jest wśród nich.$B$BDowódca Samaul przebywający w Theramore, może pomóc ci w odnalezieniu go, jeżeli tylko Handel cały czas tu stacjonuje. Jest całkowicie lojalny Proudmoore, a jeśli wypowiesz imię Elling, powinien ci pomóc... dyskretnie.",
    ["O"] = "Znajdź dowódcę Samaula w Dustwallow Marsh.",
    ["T"] = "Zgubiony Dyplomata",
  },
  [1265] = {
    ["D"] = "Hendel? Kojarzę gościa. Jednak dlaczego szukasz jednego z moich żołnierzy??$B$BElling wysłał cię byś go $gznalazł:znalazła;? Hmm, nie podoba mi się to. Elling nie wysłałby ciebie do mnie, jeśli sprawa nie byłaby problematyczna. Zrozumiem jeśli powiedz mi, że nie możesz mi zdradzić szczegółów, jednak wiedz, że mam za zadanie chronić te ziemie. Jeśli chcesz wywołać zamieszanie, wtedy ja proponuję, byś $ginformował:informowała; mnie o tym, o czym możesz.$B$BWierzę, że Hendel stacjonował na pierwszej wieży za Theramore. Bądź $gostrożny:ostrożna;.",
    ["O"] = "Przeszukaj Sentry Point by znaleźć szeregowego Hendela.",
    ["T"] = "Zagubiony Dyplomata",
  },
  [1266] = {
    ["D"] = "Szeregowy Hendel jest na zachód stąd. Obecnie jest na służbie, czuwając nad szpiegami Theramoru podczas ich odpoczynku. Przyglądali się oni bazie Hordy, Brackenwall i szukali czegokolwiek co mogłoby zagrozić naszym granicom.$B$BNie $gpowinieneś:powinnaś; mieć problemu w znalezieniu go; rozglądaj się za namiotami wzdłuż drogi.$B$BMam jeszcze jedną sprawę, ale złapię cię później. Jeśli będziesz $gmiał:MIAŁA; jakieś problemy, możesz mnie zawsze znaleźć w wieży Lady Proudmoore.",
    ["O"] = "Znajdź szeregowego Hendela w Dustwallow Marsh.",
    ["T"] = "Zaginiony Dyplomata",
  },
  [1267] = {
    ["D"] = "",
    ["O"] = "Porozmawiaj z Jainą Proudmore w Dustwallow Swamp.",
    ["T"] = "Zaginiony Dyplomata",
  },
  [1268] = {
    ["D"] = "Ślady kopyt rozciągają się od nadal tlącego się szkieletu rusztowań karczmy Shady Rest. Znajduje się tam przynajmniej kilka wyraźnych tropów jak i większa ich ilość prawie nieuchwytnych w wilgotnym mule moczar.",
    ["O"] = "Złóż raport Krog\'owi dotyczący niepokojących śladów kopyt przy karczmie Shady Rest w Brackenwall Village.",
    ["T"] = "Podejrzane odciski kopyt",
  },
  [1269] = {
    ["D"] = "Błysk światła spod rumowiska przykuł Twój wzrok. Oczyszczenie gruzu i piachu zakrzepniętego na przedmiocie ujawniło dystynkcje przedstawiającą złotą kotwicę na białym tle - symbol Theramore.$B$BPod kotwicą widać wytłoczony napis - imię: \"Lieutenant Paval Reethe\".",
    ["O"] = "Przynieś Reethe\'s Badge do Krog\'a w Brackenwall Village.",
    ["T"] = "Porucznik Paval Reethe",
  },
  [1270] = {
    ["D"] = "Świetnie, wreszcie coś, co nie chce mnie zjeść!!$B$BPotrzebuję pomocy w zajęciu się tymi zwierzętami, a ty wydajesz się do tej roboty pasować, $gkoleżko:panienko;.$B$BGoblin z Ratchet o imieniu Mebok Mizzyrix potrzebuje liści bobreka na miksturę, czy coś... Szczerze to nie wiem na co - płaci dobrze, a ja znam te bagna, więc tu jestem.$B$BNa nieszczęście dla mnie zanim znalazłem bobreka zostałem otoczony! Możesz mi tu pomóc i ochraniać mnie, gdy będę szukał rośliny dla Meboka?",
    ["O"] = "Eskortuj \"Stinky\" Ignatza i pomów z Mebokiem Mizzyrix w Ratchet.",
    ["T"] = "Ucieczka Śmierdziucha",
  },
  [1271] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Uczta w Błękitnej Samotni",
  },
  [1273] = {
    ["D"] = "Trochę mi to zajęło, ale znalazłem Reethe. Dobrze się schował jak na człowieka.$B$BOgron bał się, że mógł oszaleć po tak długim pobycie na bagnach. Chodź ze mną zdobyć od niego informacje.",
    ["O"] = "Idź z Ogronem, aby porozmawiać z Reethe, później wróc do Kroga w Brackenwall Village.",
    ["T"] = "Przepytywanie Reethe\'go",
  },
  [1274] = {
    ["D"] = "Przepraszam, $gpanie:pani;. Biskup DeLavey poprosił mnie, abym znalazł poszukiwacza przygód, który mógłby pomóc w jego delikatnej sprawie.$B$BJeśli $gmógłbyś:mogłabyś; po cichu dostać się do Twierdzy Stormwind i porozmawiać z nim jak najszybciej, jestem pewien, że doceni twoją pomoc. Proszę, abyś $gbył dyskretny:była dyskretna;. To jest bardzo ważne.",
    ["O"] = "Odnajdź biskupa DeLavey\'a w Stormwind Keep.",
    ["T"] = "Zaginiony Dyplomata",
  },
  [1275] = {
    ["D"] = "Głupie krwawe elfy bawią się demoniczną magią. Czy oni wiedzą co stało się z nagami i satyrami z Kalimdoru? Lękam się, że krwawe elfy spotka podobne zniekształcenie. Azeroth nie może pozwolić na stworzenie kolejnej rasy potworów. Chciałbym zbadać pnie mózgowe satyrów i nag, także może będę w stanie wywnioskować ku jakiemu losowi zmierza rasa elfów. W Blackfathom Deeps, na wybrzeżu Ashenvale, znajdziesz zarówno satyry jak i nagi.$B$BTo długa wyprawa, $N.",
    ["O"] = "Gershala Nightwhisper w Auberdine chce 8 Corrupt Brain Stems.",
    ["T"] = "Badanie nad korupcją",
  },
  [1276] = {
    ["D"] = "Ah, Teraz pamiętam! Mosarn jest dobrym kowalem Thunder Bluff. Wcześniej słyszałem gdzieś jego imię.$B$BW podziękowaniu Earthen Ring nagrodził mnie zbroją stworzoną przez Mosarna. Bardzo dobre wykonanie.$B$BMożliwe, że może powiedzieć Ci więcej na temat tarczy, którą sam zrobił.$B$BTo nie za duża wskazówka, ale od czasu, gdy nie dostajemy niczego użytecznego z poza Reethe, to wszystko co wiemy.",
    ["O"] = "Pokaż Blackened Iron Shield Mosarnowi w Thunder Bluff.",
    ["T"] = "Czarna Tarcza",
  },
  [1277] = {
    ["D"] = "Kagoro has revealed that the centaur hoofprints belong to some chumps in Mauradon.",
    ["O"] = "Beat down.",
    ["T"] = "<nyi> <TXT> The Centaur Hoofprints",
  },
  [1278] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<nyi> <TXT> The Grim Totem Clan",
  },
  [1279] = {
    ["D"] = "Finish one of the three.",
    ["O"] = "",
    ["T"] = "<nyi> <TXT>The Centaur Hoofprints",
  },
  [1280] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<nyi> <TXT>The Centaur Hoofprints",
  },
  [1281] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Jim\'s Song <CHANGE TO GOSSIP>",
  },
  [1282] = {
    ["D"] = "Nie mogę pomóc, jeśli tylko współczuję Jim\'owi. Nigdy taki nie był. Na chwilę wybiegł z karczmy, prosto na bagno. Wspaniałe miejsce. $B$BSłuchaj, naprawdę nie chcę rozmawiać na ten temat. Idź z tym do Kapitana Vimesa, jeśli musisz. Stacjonuje na najwyższym piętrze Foothold Citadel, czyli w dużych koszarach na wschód od Wieży Pani Jainy.",
    ["O"] = "Porozmawiaj z Kapitanem Garranem Vimsem na najwyższym piętrze Foothold Citadel.",
    ["T"] = "Wołają go uśmiechający się Jim.",
  },
  [1283] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Fire at the Shady Rest <CHANGE TO GOSSIP>",
  },
  [1284] = {
    ["D"] = "Rzędy śladów kopyt prowadzą od wciąż dymiącego szkieletu gospody Shady Rest. Istnieje co najmniej kilka widocznych odcisków, z większą ilością rzędów śladów, prawie niewidocznych w miękkim błocie bagna.",
    ["O"] = "Zamelduj podejrzane ślady w gospodzie Shady Rest do Captaina Garran\'a Vimes\'a w Theramore.",
    ["T"] = "Podejrzane ślady kopyt",
  },
  [1285] = {
    ["D"] = "Reddon... Redpath... Ah, tutaj jest! Porucznik Paval Reethe.$B$BDołączył do straży Theramore wraz z większością rekrutów, którzy przybyli z za morza wraz z Lady Proudmoore. Zaciągnął się z marines Kul Tiras w wieku szesnastu lat. Wybitna służba, awanse...$B$BNa liście zaginionych.",
    ["O"] = "Powróć z informacjami na temat Reethe do Kapitana Garran Vimes w Theramore.",
    ["T"] = "Człowiek Daelin\'a",
  },
  [1286] = {
    ["D"] = "To była walka o utrzymanie terenu na bagnach, ale dzięki wielkiej determinacji, byliśmy w stanie utrzymać kilka strażnic obronnych w całej strefie.$B$BOstatnie informacje i raporty zwiadowcze, które otrzymałem, wskazują na to, że grupa dezerterów zajęła naszą opuszczoną wieżę w Lost Point, na południowy wschód od karczmy.$B$BWydaje się, że Balos Jacken to miejscowy Porucznik. Sprawdź czy możesz uzyskać z niego jakieś informacje.$B$BOstrzegam Cię, $N. To może być ciężki orzech do zgryzienia.",
    ["O"] = "Zdobądź informację na temat Reethe od Balos Jacken oraz dezerterów w Dustwallow Marsh.",
    ["T"] = "Dezerterzy",
  },
  [1287] = {
    ["D"] = "Reethe? Ten tchórz?$B$BWyrzuciliśmy go z obozu, bo upierał się, żeby zaatakować zapasy ogrów z Brackenwall Village. Jest nas za mało, aby stanąć na przeciwko tym bezmózgim brutalom.$B$Przekroczył granice zbyt wiele razy, więc zostawiliśmy go samemu sobie.$B$BPomogłem ci, więc czemu nie mógłbyś zapomnieć, że na nas wpadłeś?",
    ["O"] = "Porozmawiaj z Kaptainem Garranem Vimesem w Theramore na temat Reethe.",
    ["T"] = "Dezerterzy",
  },
  [1288] = {
    ["D"] = "Wykonałeś sporo dobrej doboty, $N, jak na amatora.$B$BLady Proudmoore prosiła, żeby ją informować na temat tej delikatnej sytuacji, a dawno z nią nie rozmawiałem.$B$BMiałem dostarczyć mój raport do niej później, ale wydaje mi się, że to Ty powinieneś z nią porozmawiać. Myślę, że lepiej odpowiesz na jej pytania niż ja.",
    ["O"] = "Dostarcz Raport Vimes\'a do Lady Jainy Proudmoore w Theramore.",
    ["T"] = "Raport Vimes\'a",
  },
  [1289] = {
    ["D"] = "Well. judging from Captain Vimes\'s report. you\'ve been a huge help to his investigation. and for that I thank you.$B$BI can put my mind more at ease knowing that the matter is in such capable hands. If you would. I would request that you return to Captain Vimes and help him in getting to the bottom of this mystery.",
    ["O"] = "Return to Captain Garran Vimes in Theramore.",
    ["T"] = "Vimes\'s Report",
  },
  [1293] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<nyi> <TXT> Centaur Hoofprints",
  },
  [1294] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<nyi> <TXT>Centaur Sympathies",
  },
  [1295] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<nyi> <TXT> Course of Action",
  },
  [1296] = {
