    ["T"] = "<UNUSED>",
  },
  [3425] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [3441] = {
    ["D"] = "Wysłuchaj mojej opowieści, podróżniku.",
    ["O"] = "Wysłuchaj historii Kalarana Windblade\'a.",
    ["T"] = "Kara boska",
  },
  [3442] = {
    ["D"] = "Podjąłeś słuszną decyzję, $N.$B$BMusimy uderzyć tam, gdzie zadamy najwięcej strat: cztery wieże strażnicze.$B$BKiedy cztery wieże staną w ogniu, będziemy wstanie przystąpić do ofensywy zanim oni zdążą zareagować.$B$BBędziesz potrzebował odpowiedniego narzędzia, aby podpalić wieże. Żeby je zrobić musisz zebrać trochę materiałów.$B$BPrzynieś mi 4 Hearts of Flame i 4 Golem Oil, a będę mógł zrobić Torch of Flawless Flame.$B$BTwoim pierwszym celem powinny być golemy i żywiołaki znajdujące się na tych ziemiach.",
    ["O"] = "Zbierz 4 Hearts of Flame i 4 Globes of Golem Oil, i zwróć je do Kalaran Windblade.",
    ["T"] = "The Flawless Flame",
  },
  [3443] = {
    ["D"] = "Aby utrzymać nieskazitelny płomień, będziemy potrzebować ostrza i osłony. Najpierw musisz znaleźć odpowiednie ostrze.$B$BThe Dark Iron Taskmasters i Slavers of the Cauldron używają broni ze wzmocnionego Thorium, niezwykle wytrzymałego stopu. Jeśli przyniesiesz mi osiem Thorium Plated Daggers, mogę przerobić je na stop i przekuć w ostrze.",
    ["O"] = "Przynieś 8 Thorium Plated Daggers do Kalaran Windblade.",
    ["T"] = "Forging the Shaft",
  },
  [3444] = {
    ["D"] = "Odwiedziłem niegdyś budzące grozę komnaty Sunken Temple. Tamtejsze zło przenika wszystko, co się tam tylko pojawi; ledwie zdołałem odnaleźć drogę powrotną, brodząc w szlamie, który pokrywa teraz posadzki. Jedyne, co pamiętam, to duża, okrągła komnata, pełna posągów węży...$B$BOdkryłem ostatnio okrągły kamień, na którym odciśnięto symbol tego samego węża. Spakowałem go i wysłałem do mojej pracowni w Ratchet. Odzyskaj go, a może będę mógł powiedzieć ci więcej.",
    ["O"] = "Zdobądź Kamienny Krąg z pracowni Marvona Rivetseekera w Ratchet.",
    ["T"] = "Kamienny krąg",
  },
  [3445] = {
    ["D"] = "Są na tym świecie niespokojne duchy, $N. Są i takie, które skażone przez wieki odosobnienia związały się ze starożytnym złem...$B$BSłyszałem o miejscu, które leży głęboko pod powierzchnią ziemi - zepchnięte tam przez moce potężniejsze niż kiedykolwiek widziały me oczy.$B$BJeśli chciałbyś dowiedzieć się czegoś więcej o tym miejscu - Sunken Temple - znajdź goblina imieniem Marvon Rivetseeker. Badał wiele starożytnych miejsc tego świata. Ostatnie co o nim wiadomo, to że opuścił swój dom w Ratchet, by badać trollowe ruiny w Tanaris.",
    ["O"] = "Znajdź Marvona Rivetseekera w Tanaris.",
    ["T"] = "Zatopiona Świątynia",
  },
  [3446] = {
    ["D"] = "W środku świątyni znalazłem okrągły pokój z sześcioma balkonami. Na każdym z nich znajdowała się wężowata statua. Zaciekawiony popchnąłem jedną z nich, by zobaczyć co się stanie, a to była pułapka! Niemal postradałem życie w tej eksplozji. Leżąc tam, na krawędzi i patrząc w dół zorientowałem się, że na dnie komnaty jest jeszcze jedna statua; ołtarz jakiegoś... Hakkara, tak chyba nazywało się to bóstwo. $B$BMyślę, że sekret tkwi w ołtarzu - musisz zabrać ten znak do ołtarza w Sunken Temple.",
    ["O"] = "Odszukaj Ołtarz Hakkara w Sunken Temple, w Swamp of Sorrows.",
    ["T"] = "W głębiny",
  },
  [3447] = {
    ["D"] = "Moje wspomnienia są zamazane, ale powiem ci wszystko co wiem. Wierzę, że krąg posągów w Sunken Temple., choć niebezpieczny, kryje sekret, za którym stać może ogromny skarb.$B$BZ głównego ołtarza udało mi się uaktywnić szereg snopów światła. Myślę, że jeśli tylko uda ci się odkryć co oznaczają, będziesz mógł znaleźć to, co schowane jest w tej komnacie.$B$BLecz ostrzegam cię, $N. Wielkie zło czai się w tej świątyni. Każdy przedmiot przedstawiający sobą wartość najprawdopodobniej będzie gorliwie strzeżony...",
    ["O"] = "Udaj się do Sunken Temple. i odkryj sekret kryjący się za kręgiem posągów.",
    ["T"] = "Sekret kręgu",
  },
  [3448] = {
    ["D"] = "Niedawno mej pieczy powierzono zbadanie Azshary - niegdyś pięknej krainy, którą elfy nazywały domem. Tak było w czasach, kiedy wciąż jeszcze praktykowały magię. Teraz jest to bardziej niebezpieczne niż piękne miejsce, ale nie powstrzyma nas to przed zajrzeniem pod każdy kamień w poszukiwaniu odpowiedzi na nasze pytania dotyczące przeszłości. $B$BMój kompan imieniem Tymor zaoferował się, iż pomoże mi zbadać te ziemie, jako że interesują go tego typu sprawy. $B$BMieszka w niewielkim mieszkaniu na prawo od Sali Tajemnic, tutaj w mieście.",
    ["O"] = "Porozmawiaj z Tymorem w Ironforge.",
    ["T"] = "Przekazanie brzemienia",
  },
  [3449] = {
    ["D"] = "Magia była niegdyś tak bliska elfom jak Elune. Niektórzy z najpotężniejszych elfickich magów tworzyli runy i tablice głoszące zasady wiedzy tajemnej i ich własne rozważania na ten temat. Rozstawiali je w miejscach dostępnych dla wszystkich, by każdy mógł nad nimi podumać. $B$BBardzo chciałbym dostać kopie tych run z Ruin Eldarath. Mam dla ciebie zestaw, który pomoże ci wykonać kopie, lecz do ciebie będzie należeć ich odnalezienie. Bądź $gostrożny:ostrożna; - Liga Odkrywców nie jest jedyną organizacją zainteresowaną Eldarath.",
    ["O"] = "Używając Drawing Kit stwórz kopie Runy Beth\'Amary, Runy Jin\'yael, Runy Markri i Runy Sael\'hai. Następnie udaj się na małą wyspę w pobliżu południowego półwyspu Azshary i oddaj rysunki przywołanemu uprzednio pilotowi Xiggsowi Fuselighterowi.",
    ["T"] = "Magiczne runy",
  },
  [3450] = {
    ["D"] = "Chcę dostać te kopie do mojej wieży, ale nie ma potrzeby abyś $gpokonywał:pokonywała; taki szmat drogi. Po prostu załatwię im transport drogą powietrzną z Azshary. $B$BXiggs Fuselighter wisi mi jedną czy dwie przysługi i niedługo będzie w tamtej okolicy - przydzielono mu patrolowanie wybrzeża. Porozmawiaj z nim zanim wyruszysz. Przekaże ci pistolet sygnałowy, byś $gmógł:mogła; dać mu znać. Kiedy już zdobędziesz kopie udaj się tam gdzie ci każe i daj mu je, on przetransportuje je bezpiecznie do wieży. Powinien być w hangarze w Sali Wojskowej.",
    ["O"] = "Porozmawiaj z Xiggsem Fuselighterem w Ironforge.",
    ["T"] = "Prosty odbiór",
  },
  [3451] = {
    ["D"] = "Ach, więc Tymor cię przysłał, hę? Ta, wiszę mu przysługę czy dwie. Że co? Co... a to mały diabeł. Ta, mogę mu w tym pomóc. Więc będziesz $gpotrzebował:potrzebowała; pistoletu sygnałowego i lokacji... to powinno być proste.$B$BU południowego półwyspu Azshary leży mała wysepka, na której zrobiliśmy lądowisko. Weź ten pistolet sygnałowy i użyj go tam. Zobaczę twoją flarę i przylecę żeby zabrać to... to coś, czego on chce.",
    ["O"] = "Porozmawiaj z Xiggsem Fuselighterem w Ironforge i zdobądź od niego Standardowy Model Pistoletu Sygnałowego.",
    ["T"] = "Sygnał do odbioru",
  },
  [3452] = {
    ["D"] = "Potrzebujemy ostatniej części potrzebnej do utworzenia pochodni. $B$BW górach na północny zachód stąd znajdziesz wielkie obozowisko Twilight\'s Hammer. Mówi się, że posiadają symbole i figurki stanowiące hołd dla ich boga. Te symbole i figurki mogą nosić zaklęcie, odpowiednie, by stworzyć magiczną osłonę. Przynieś mi pojedynczy symbol Ragnarosa, a ja spróbuje wydobyć z niego magię, by móc stworzyć oprawę.",
    ["O"] = "Znajdź Symbol Ragnarosa i przynieś go do Kalarana Windblade\'a.",
    ["T"] = "Oprawa dla płomienia",
  },
  [3453] = {
    ["D"] = "Daj mi chwilę, abym mógł złączyć części i nałożyć odpowiednie zaklęcia.",
    ["O"] = "Poczekaj, aż Kalaran Windblade ukończy Pochodnię Zemsty.",
    ["T"] = "Pochodnia Zemsty",
  },
  [3454] = {
    ["D"] = "Pochodnia musi teraz zostać powiązana z jej właścicielem. Podnieś pochodnię, $N.",
    ["O"] = "Podnieś Pochodnię Zemsty.",
    ["T"] = "Pochodnia Zemsty",
  },
  [3461] = {
    ["D"] = "Tymor nie dał mi nic, czym mógłbym ci zapłacić, więc proponuję ci, byś $gzwrócił:zwróciła; się z tym do niego, kiedy już wrócisz do Ironforge. Jestem pewien, że wciąż będzie w swoim mieszkaniu w Sali Magii. Po prostu zapukaj tam i upewnij się, że dobrze ci zapłaci. Wyprawa do tego miejsca nie była spacerem po parku - to wiem na pewno. $B$BJeszcze raz dzięki za to, że mu $gpomogłeś:pomogłaś;. I powodzenia.$B$BOh, nie będę potrzebował tego zestawu do rysowania. Może zabierzesz go ze sobą do Tymora i oddasz mu, kiedy będziesz się z nim widzieć?",
    ["O"] = "Przynieś Tymorowi jego Drawing Kit do Ironforge.",
    ["T"] = "Powrót do Tymora",
  },
  [3462] = {
    ["D"] = "Porozmawiaj z moim wysłannikiem, Squire Maltrake. On poinstruuje Cię, co dalej zrobić z Torch of Retribution.",
    ["O"] = "Porozmawiaj z Squire Maltrake.",
    ["T"] = "Squire Maltrake",
  },
  [3463] = {
    ["D"] = "Słuchaj, $N. Od kiedy cztery wieże nie mogą zostać zniszczone, możesz użyć Torch of Retribution, aby zająć je ogniem na bardzo długi okres czasu: Ogniem, którego żadna siła, ani żywioł nie jest wstanie zwalczyć.$B$BKiedy będą płonąć, żaden obrońca ani strażnik nie będzie mógł pełnić warty, a tym samym ich pierwsza linia obrony stanie się bezużyteczna.$B$BMusisz dostać się do środka i użyć Torch of Retribution w każdej z ich fortyfikacji. Uważaj na strażników Dark Irons, $N.",
    ["O"] = "Podłóż ogień pod Północną, Południową, Wschodnią, i Zachodnią Wieżę Strażniczą używając Torch of Retribution w środku każdego z budynków.",
    ["T"] = "Set Them Ablaze!",
  },
  [3481] = {
    ["D"] = "Skrzynia wydaje się być zamknięta.",
    ["O"] = "Otwórz skrzynię.",
    ["T"] = "Błyskotki...",
  },
  [3482] = {
    ["D"] = "To jest wersja zadania czarnej skrzynki dla Hordy.",
    ["O"] = "Zabierz to pudło do Kravel.",
    ["T"] = "The Pocked Black Box",
  },
  [3483] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Sygnał do odbioru",
  },
  [3501] = {
    ["D"] = "Mimo, że nigdy nie znajdziesz nieskazitelnej Sphere of Draenethyst, niewątpliwie znajdziesz różne Fragments of the Draenethyst podczas swojej wędrówki przez te ziemie.$B$BPodczas kiedy wątpliwym jest, że Kum\'isha będzie w stanie użyć Flawed Fragments, aby powrócić do domu, te odłamki mogą się przysłużyć dla Draenei w inny sposób.$B$BZwróć każdy Flawed Draenethyst Fragments, który znajdziesz, a wynagrodzę cię.",
    ["O"] = "Przynieś Kum\'isha Imperfect Draenethyst Fragments i odbierz nagrodę za każdy fragment, który przyniesiesz.",
    ["T"] = "Everything Counts In Large Amounts",
  },
  [3502] = {
    ["D"] = "Po tym pokazie nienasyconej chciwości, czuje się znudzony.$B$BJednak nie zamierzam rozwodzić się, zbyt długo, nad twoim zbieractwem.$B$BZa każdy Imperfect Draenethyst Fragment, który przyniesiesz, nagrodzę cię większą ilością rupieci. Moja kupka śmieci maleje, gdy twoja rośnie. W Draenor mówimy w takiej sytuacji, że \"każdy wygrywa\".",
    ["O"] = "Przynieś Kum\'isha Imperfect Draenethyst Fragments. Każdy stwór w Blasted Lands może posiadać fragment.",
    ["T"] = "One Draenei\'s Junk...",
  },
  [3503] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Spotkanie z Mistrzem",
  },
  [3504] = {
    ["D"] = "Zdradliwa, złodziejska kobieta! Tak ją nazywam i taka zawsze będzie!$B$BChyba popełniłem wielką pomyłkę, $N. Zaufałem krwawej elfce. Co gorsza, zaufałem kobiecie!$B$BTwierdziła, że w Azsharze będą wielkie bogactwa... potężne przedmioty. Po prostu wysłałem kilku wojowników razem z nią, by ją chronili i miałem zostać nagrodzony. Cóż, zobacz kto wyszedł na głupca, zabiła ich wszystkich.$B$BChcę zemsty, $N, ale nie mogę sobie pozwolić, żeby wysłać tam kogoś jeszcze. Znajdź Ag\'thora w Valormok, na północ od Obozowiska Haldarr. On powie ci więcej.",
    ["O"] = "Dostarcz Sealed Letter do Ag\'tora z Ag\'tor Bloodfist w Azsharze.",
    ["T"] = "Zdradzony",
  },
  [3505] = {
    ["D"] = "Myślałem dużo.$B$BMusimy zacząć naszą krucjatę przeciw jej pracownikom wzdłuż południowego urwiska na północy półwyspu Azshary. Zabij ich z okrucieństwem - niech wiedzą, że wybrali złą stronę.$B$BNie przejmuj się nią za bardzo -większość czasu spędza ze swoimi ochroniarzami przeszukując tereny Azshary. Mądrym posunięciem po wybiciu jej pracowników, będzie znalezienie jej osobistego obozu. Wyszukaj miejsca, z którego można by ją było zaatakować. Prawdopodobnie znajdzie się tam coś, co mogło by ją sprowokować.",
    ["O"] = "Zabij 10 Blood Elf Reclaimers, i 10 Blood Elf Surveyors zanim przeszukasz obóz Magini Rimtori. Po zrobieniu tego, poszukaj czegoś co może być dla niej ważne i będzie można dzięki temu ją sprowokować.",
    ["T"] = "Zdradzony",
  },
  [3506] = {
    ["D"] = "Chwila zastanowienia podsuwa nowe pomysły; jeden przywodzi na twą twarz uśmiech: może zniszczenie kryształów zdenerwuje krwawą elfkę odpowiedzialną za zabicie tak wielu orków i zdradzenie Belgroma?$B$BKontynuując rozszyfrowywanie znaków oraz rysunków zauważasz, że jeden z kryształów jest powiązany z twórcą kręgu - inne są powiązane z czymś o wiele bardziej ponurym.$B$BZamykasz księgę i zaczynasz zastanawiać się, który kryształ zniszczyć.",
    ["O"] = "Zniszcz magiczny kryształ skupiający związany z Maginią Rimtori, a potem ją zabij. Następnie zabierz Głowę Magini Rimtori do Ag\'tora Bloodfista z Azshary.",
    ["T"] = "Zdradzony",
  },
  [3507] = {
    ["D"] = "Wróć do Belgroma, do Orgrimmaru. Będzie chciał osobiście zobaczyć jej głowę! My wkrótce też tam wrócimy.$B$BAch, to rzeczywiście piękny dzień. Dziękuję ci za pomoc, $N.",
    ["O"] = "Porozmawiaj z Belgromem Rockmaulem z Orgrimmaru.",
    ["T"] = "Zdradzony",
  },
  [3508] = {
    ["D"] = "Jest w tobie wielka skłonność do ryzyka. To godna pochwały cecha twojego ludu - rzucacie się do walki, nawet bez większych szans na zwycięstwo. Pomogę ci, choćby po to, by ujrzeć śmierć kolejnego ze sługusów Razelikha.$B$BPrzebicie osłony chroniącej podwładnych Razelikha będzie wymagało nieco czasu i pewnych rzadkich artefaktów.$B$BNie odchodź; na początek muszę odprawić rytuał oświecenia. Pozyskane informacje posłużą mi do stworzenia broni o wielkiej mocy.",
    ["O"] = "Poczekaj, aż Loramus ukończy czar oświecenia.",
    ["T"] = "Przebicie osłony",
  },
  [3509] = {
    ["D"] = "Jest tylko jeden sposób, by zranić demona i jego podwładnych. Należy wykuć potężną broń, na której zostanie wyryte jego prawdziwe imię.$B$BTylko taką bronią da się zabić demona i jego sługi.$B$BW Azsharze mieszka pewne pomniejsze bóstwo - Lord Arkkoroc. Musisz go odnaleźć, lecz strzeż się - jeśli jego słudzy odkryją twoją obecność, będą starali się zniszczyć cię za wszelką cenę.$B$BMożesz też mieć absolutną pewność, że sama informacja również będzie kosztować.",
    ["O"] = "Porozmawiaj z Lordem Arkkorokiem z Azshary. Poszukiwania Świątyni Arkkorana rozpocznij u brzegu morza.",
    ["T"] = "Imię bestii",
  },
  [3510] = {
    ["D"] = "Ona zabija moje dzieci, śmiertelniku. Ona, która zwie się władczynią oceanów. Fałszywy bożek, nic ponad to. Zabij ją i przynieś mi wszystkie jej głowy.$B$BW zamian za to zdradzę ci imię, którego tak pragniesz, oraz ofiaruję coś równie wartościowego.$B$BSnuje się wokół swego lęgowiska... Hetera jej imię.$B$B<Lord Arkkoroc wskazuje na południowy wschód.>$B$BIdź!",
    ["O"] = "Zabij Heterę i przynieś Zakrwawioną Głowę Hetery, Obitą Głowę Hetery i Poranioną Głowę Hetery do Lorda Arkkoroca.",
    ["T"] = "Imię bestii",
  },
  [3511] = {
    ["D"] = "Jak obiecałem, wyjawię ci prawdziwe imię demonicznego władcy, Razelikh the Defiler. Jednakże najpierw muszę przygotować coś niezwykle ważnego dla powodzenia twojej misji.$B$BBroń, którą próbujesz stworzyć, potrzebować będzie zahartowania. Daj mi chwilkę na wyciśnięcie krwi z tych głów.$B$B<Lord Arkkoroc ściska głowy w swych gigantycznych pięściach, wyciskając z nich krew aż do ostatniej jej kropli.>$B$BZabierz ten topnik do Loramusa, wraz z prawdziwym imieniem bestii, które brzmi: Rakh\'likh.",
    ["O"] = "Zanieś topnik do Loramusa Thalipedesa.",
    ["T"] = "Imię bestii",
  },
  [3512] = {
    ["D"] = "Naszym pierwszym krokiem będzie opracowanie metody porozumiewania się z Eranikusem za pośrednictwem klejnotu. Smok ten tkwi w zawieszeniu pomiędzy snem i śmiercią, zaplątany w sieci koszmarów. Mimo, że esencja, którą udało ci się zdobyć, jest silnie skażona, myślę, że uda nam się nawiązać z nim kontakt.$B$BUdaj się do skutej lodem wschodniej części Winterspring i odszukaj jednego z naszych śmiertelnych sojuszników, Umbranse\'a the Spiritspeakera. Jest ludzkim medium, za pośrednictwem którego przemawiają umarli. Choć Eranikus nie jest do końca martwy, medium może okazać się pomocne.",
    ["O"] = "Udaj się do wschodniej części Winterspring i porozmawiaj z Umbranse\'em the Spiritspeakerem.",
    ["T"] = "Własnymi słowami Eranikusa",
  },
  [3513] = {
    ["D"] = "Noszący oficjalny wygląd zwój przewiązano ciasno srebrną wstążką. Masz pewność, że kogoś zainteresuje, tylko kogo?$B$BNa północy, w pobliżu granicy z Ashenvale, znajduje się posterunek, a jeśli zawarte w zwoju informacje dotyczą nocnych elfów, to właśnie tam należałoby go dostarczyć.",
    ["O"] = "Zabierz Runed Scroll do północnej wieży strażniczej w Barrens.",
    ["T"] = "Runiczny zwój",
  },
  [3514] = {
    ["D"] = "Ten zwój pochodzi od tej intrygantki, driady Rynthariel, Klucznicy ze Szponiastego Leża położonego na szczycie szczycie Stonetalon. $B$BNie skontaktuje się już z posłańcem, który przewoził ten zwój. Niemniej musimy przedsięwziąć pewne środki. Horda nie będzie tolerować tutaj jej gońców. $B$BUdaj się do Szponiastego Leża, zabij Rynthariel, a potem zostaw tam znak, aby wszyscy mogli go zobaczyć. Weź ten sztandar Hordy. Zatknij go w ziemię leża, a założę się, że nie będą już tacy chętni do wysyłania posłańców przez nasze ziemie.",
    ["O"] = "Zabij przywódczynię Talon Den, Klucznicę Rynthariel.",
    ["T"] = "Obecność Hordy",
  },
  [3515] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [3516] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [3517] = {
    ["D"] = "Przyznaję, maksymalnie wykorzystuję mój pobyt w Azsharze. Kara Belgroma ma w tym swój udział.$B$BZanim wyjechałam, zebrałam trochę informacji. Nigdy byś nie uwierzył, na ile wartościowych przedmiotów można tu trafić.$B$BPowiem ci więcej o moich interesach i nawet odpalę część zysków, jeśli pomożesz mi zdobyć kilka z nich.$B$BPotrzebuję pewnych tablic, rozproszonych po Ruinach Eldarath, na wschód stąd. Wszystkie cztery noszą imiona Szlachetnie Urodzonych czarodziejów. Zdobądź je dla mnie, a jeszcze porozmawiamy.",
    ["O"] = "Znajdź tablice Beth\'Amary, Jin\'yael, Markri i Sael\'hai, po czym wróć z nimi do Jedigi z Azshary.",
    ["T"] = "Kradzież wiedzy",
  },
  [3518] = {
    ["D"] = "Pierwsza tablica przeznaczona jest dla taureńskiej kobiety... tej, którą zwą Magatha. Należy ona do starszyzny Thunder Bluff i jest orędowniczką sojuszu z taurenów z Opuszczonymi. Żywi ona najgłębsze z całej starszyzny przekonanie, że taureni i ich tradycja mogą pomóc Opuszczonym stać się na powrót ludźmi.$B$BZanieś jej Tablicę Beth\'Amary. Może ona być kluczem, który pozwoli pomóc Opuszczonym... a przynajmniej tak twierdzi Magatha.",
    ["O"] = "Zanieś Tablicę Beth\'Amary do Magathy z Thunder Bluff.",
    ["T"] = "Przesyłka dla Magathy",
  },
  [3519] = {
    ["D"] = "Ughhh... Ugryzła mnie pajęczyca, Ohydna Githyiss. Stało się to, gdy badałem pobliską jaskinię pająków. Jestem pewien, że jej ugryzienie było jadowite. Musisz mi pomóc!$B$BProszę, powiedz o wszystkim Diranii Silvershine. Będzie wiedziała co robić.$B$BPospiesz się... Słabo mi...",
    ["O"] = "Porozmawiaj z Diranią Silvershine w Shadowglen.",
    ["T"] = "Przyjaciel w potrzebie",
  },
  [3520] = {
    ["D"] = "Poszukuję dusz skrzekaczy z dolin Feralas. Są one krewnymi starego, bardzo starego boga. Ich dusze są z nim powiązane.$B$BWeź tą cierniową różdżkę i udaj się do Feralas. Odnajdź skrzekacze z dolin w południowej i centralnej części krainy, po czym pokonaj je i nakreśl moją różdżką znak w powietrzu nad ich truchłami. To nakłoni ich dusze do objawienia się; wystarczy, że ich dotkniesz, by zdobyć ich esencję.$B$BWróć do mnie z różdżką i zebraną esencją dusz, a opowiem ci więcej o starym bogu, o którym wspomniałem.",
    ["O"] = "Schwytaj dusze trzech skrzekaczy z Feralas, po czym wróć do Yeh\'kinyi, do Steamwheedle Port.",
    ["T"] = "Dusze skrzekaczy",
  },
  [3521] = {
    ["D"] = "Możemy pomóc Iverronowi, gdyż znam antidotum na tę pajęczą truciznę. Jego sporządzenie będzie jednak wymagało kilku składników.$B$BBędę potrzebowała hiacyntowych grzybów. Rosną one pod drzewami, lub można znaleźć je przy grellach, bytujących na południe stąd - wygląda na to, że są ich przysmakiem. Potrzebne będą także księżycowe lilie, rosnące tylko przy wodzie.$B$BOstatni składnik może okazać się najtrudniejszy do zdobycia. Jest nim posoka leśnych przędzarzy, tych samych pająków, które zatruły Iverrona.",
    ["O"] = "Zbierz 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, i 1 Webwood Ichor dla Diranii Silvershine z Shadowglen.",
    ["T"] = "Antidotum dla Iverrona",
  },
  [3522] = {
    ["D"] = "Antidotum jest gotowe. Proszę, dopilnuj, by Iverron je wypił.$B$BJest coś, o czym musisz wiedzieć. Antidotum zachowa swą moc jedynie przez 5 minut - musisz dostarczyć je Iverronowi przed upływem tego czasu.$B$BNiech wiatr będzie z tobą, $N.",
    ["O"] = "Zanieś Antidotum Iverronowi zanim skończy się czas. Znajdziesz go obok jaskini na północy.",
    ["T"] = "Antidotum dla Iverrona",
  },
  [3523] = {
    ["D"] = "Znakomicie! Nazywam się Belnistrasz i dziękuję ci za ratunek. Już myślałem, że nie uniknę śmierci... a nawet czegoś gorszego - losu posiłku tych zarażonych Plagą szkodników. Tak, dokładnie, Plagą - nieumarli zawarli coś na kształt umowy z knurokolcami, a ten koszmar jest jej skutkiem.$B$BPosłuchaj... zamiast po prostu uciec, wolałbym coś tutaj zmienić, dla dobra nas wszystkich. Czujesz się na siłach, by mi pomóc? To prawdopodobnie niebezpieczne, ale nie wyglądasz mi na kogoś, kto przejmuje się takimi kwestiami.",
    ["O"] = "Jeśli zgodzisz się pomóc Belnistraszowi, porozmawiaj z nim ponownie i oddaj mu Kamień Przysięgi, który ci wręczył.",
    ["T"] = "Plaga z Podnóża",
  },
  [3524] = {
    ["D"] = "Wiadomo, że majestatyczne morskie zwierzęta u kresu swych dni docierają do wybrzeży Darkshore i osiadają na plażach w oczekiwaniu na śmierć. Ostatnimi czasy liczba zalegających na brzegu stworzeń nieustannie rośnie. Świątynia Księżyca przysłała mnie tu, bym zbadała tę sprawę, ale obecność murloków wzdłuż linii brzegowej znacznie utrudnia mi pracę.$B$BNa południe od Auberdine morze wyrzuciło na plażę ogromne stworzenie, które zostało otoczone przez ohydne szaromgielne murloki. Czy $gmógłbyś:mogłabyś; tam pójść i przynieść mi jego kości do zbadania?",
    ["O"] = "Pozyskaj Sea Creature Bones, leżącego na plaży na południe od Auberdine i wróć z nimi do Gwennyth Bly\'Leggonde z Auberdine.",
    ["T"] = "Konające na brzegu",
  },
  [3525] = {
    ["D"] = "W pobliżu wejścia znajduje się bożek, służący knurokolcom za makabryczny piec. Te bestie... dosłownie pożerają tych, których porwały na Barrens. Mogę ugasić posąg i uniemożliwić jego ponowne wykorzystanie, ale potrzebuję do tego twojej pomocy. Mój plan jest taki: będziesz eskortować mnie do posągu, a gdy tam dotrzemy, odprawię rytuał. Nie będę miał większych możliwości, by z tobą rozmawiać, a co dopiero się bronić. Chroń mnie, gdy będę wygaszał posąg. Jeśli mnie załatwią - wszystko przepadnie.$B$BJesteś ze mną?!",
    ["O"] = "Eskortuj Belnistrasza do bożka knurokolców w Razorfen Downs.$B$BChroń go, gdy będzie odprawiał rytuał ugaszenia posągu.",
    ["T"] = "Ugaszenie posągu",
  },
  [3526] = {
    ["D"] = "Ekspercka inżynieria dzieli się na dwie odrębne szkoły: inżynierię gnomów i inżynierię goblinów. Ta druga to oczywisty wybór wszystkich geniuszy tej dziedziny. Uczy, jak ujarzmić świat przy pomocy racjonalnego wykorzystania ładunków wybuchowych i fantastycznego sprzętu!$B$BPrzeczytaj ten podręcznik, $N. Jeśli chcesz poznać inżynierię goblinów, zanieś go Nixxowi Sprocketspringowi z Gadgetzanu. Pamiętaj - członkostwo jest permanentne i decydując się na jedną ze stron tracisz dostęp do drugiej, więc zanim dokonasz wyboru, upewnij się, że tego właśnie chcesz.",
    ["O"] = "Jeżeli chcesz dowiedzieć się więcej na temat Inżynierii Goblinów, zanieś \"Podręcznik dziedzin inżynierii\" do Nixxa Sprocketspringa z Gadgetzanu.",
    ["T"] = "Inżynieria goblinów",
  },
  [3527] = {
    ["D"] = "Starożytne proroctwo Mosh\'aru opisuje sposób uwięzienia esencji boga Hakkara. Zostało zapisane na dwóch tablicach i ukryte w trollowym mieście Zul\'Farrak na zachód od Gadgetzanu.$B$BPrzynieś mi tablice Mosh\'aru!$B$BPierwsza z nich jest w posiadaniu od dawna martwego trolla Theka the Martyr. Powiadają, że jego dręczyciele zostali zamienieni w skarabeusze i teraz krążą wokół jego relikwiarza.$B$BDrugą tablicę przechowuje hydromantka Velratha, przebywająca w pobliżu świętej sadzawki Gahz\'rilli.$B$BGdy zdobędziesz obie tablice, przynieś je do mnie.",
    ["O"] = "Przynieś Yeh\'kinyi z Tanaris Pierwszą i Drugą Tablicę Mosh\'aru.",
    ["T"] = "Proroctwo Mosh\'aru",
  },
  [3528] = {
    ["D"] = "Nadszedł czas, by schwytać esencję awatara Hakkara.$B$BZabierz Jajo Hakkara do Sanctum of the Fallen God w Sunken Temple w Azeroth. Wezwij moc jaja, by przebudzić martwego boga.$B$BWyśle przeciw tobie swoje sługi. Pokonaj krwiopijców i zabierz im krew Hakkari, potem użyj jej, by ugasić wieczne płomienie więżące duszę Hakkara. Gdy ogień zgaśnie, awatar Hakkara wkroczy do naszego świata.$B$BPokonaj go i umieść jego esencję w Jaju Hakkara.",
    ["O"] = "Przynieś Filled Egg of Hakkar do Yeh\'kinyi z Tanaris.",
    ["T"] = "Bóg Hakkar",
  },
  [3529] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [3541] = {
    ["D"] = "Znam pasera w Orgrimmarze. Mieszka w The Drag. Trudno go przydybać, jeśli się nie wie, gdzie szukać, ale jeśli rozejrzysz się po najwyższym budynku, powinieneś bez problemu go znaleźć.$B$BWyświadcz mi jednak przysługę i nie rozpowiadaj po całym Kalimdorze, że tam jest i czym się zajmuje - to byłoby bardzo nieprzyjemne dla nas obojga.$B$BDa nam więcej niż uczciwą cenę za Tablicę Jin\'yael. Nie do końca wiem czemu, ale trzeba było widzieć, jak bardzo się podekscytował, gdy usłyszał, gdzie jej szukać.",
    ["O"] = "Zanieś Jes\'rimonowi z Orgrimmaru Tablicę Jin\'yael.",
    ["T"] = "Przesyłka dla Jes\'rimona",
  },
  [3542] = {
    ["D"] = "Moim następnym kontaktem jest Andron Gant. Zwykle trzyma się Undercity... konkretnie sąsiedztwa Aptekarni.$B$BGdy przyszło do tematu, do czego mu potrzebna Tablica, puścił nieco więcej pary z gęby. Wygląda na to, że kilku magów z Undercity chce przestudiować magiczne zaklęcia szlachetnie urodzonych. Myślą, że ta tablica im pomoże. Markri była mistrzynią w przyzywaniu stworzeń; szczególnie żywiołaków.$B$BZanieś mu Tablicę Markri i wróć do mnie po swoją część nagrody.",
    ["O"] = "Zanieś Andronowi Gantowi z Undercity Tablicę Markri.",
    ["T"] = "Przesyłka dla Androna Ganta",
  },
  [3561] = {
    ["D"] = "Ostatnia tablica jest przeznaczona dla kogoś bardzo niebezpiecznego, Gilraen. Uważaj co mówię; ufam tej osobie daleko mniej niż którejkolwiek z tych, do których cię wysłałam. $B$BArcymag Xylem ma swoją wieżę na wzgórzach górujących nad Azsharą. Jest człowiekiem, ale nie zachowuje się jak żaden z ludzi, których spotkałam... albo zabiłam. Emanuje mocą i nie śmiałam pytać go, co zamierza zrobić z tablicą.$B$BPrzyszedł do mnie i powiedział, że jego strażnik Sanath pomoże mi dostać się do wieży, kiedy będę gotowa się na spotkanie. Szukaj Sanatha na północy.",
    ["O"] = "Przynieś Tablicę Sael\'hai do Arcymaga Xylema z Azshary.",
    ["T"] = "Przesyłka dla Arcymaga Xylema",
  },
  [3562] = {
    ["D"] = "Weź to pismo do Jedigi. Powiedz jej, że zapłata będzie tutaj czekać na jej powrót. I dodaj, że jestem zadowolona z jej usług. $B$BRuszaj żwawo, $N. Powiedz swojej pani, że będę tu na nią czekać.",
    ["O"] = "Dostarcz Pismo Magathy do Jedigi z Azshary.",
    ["T"] = "Zapłata Magathy dla Jedigi",
  },
  [3563] = {
    ["D"] = "Zanieś ten list do Jedigi. Poinformuj ją, że nasza transakcja była owocna i jestem zadowolony z jej pracy.$B$BPowiedz jej, żeby szybko wróciła do Orgrimmaru. Jes\'rimon zadba, żeby jej nic nie brakowało.$B$BPowiedz jej to; może w przyszłości będę znowu potrzebował twoich usług, $N.",
    ["O"] = "Dostarcz Wiadomość Jes\'rimona do Jedigi z Azshary.",
    ["T"] = "Zapłata dla Jedigi od Jes\'rimona",
  },
  [3564] = {
    ["D"] = "Proszę... Weź... <czka> to do Jedigi. Powodzenia!",
    ["O"] = "Dostarcz Wiadomość Androna do Jedigi z Azshary.",
    ["T"] = "Zapłata dla Jedigi od Androna",
  },
  [3565] = {
    ["D"] = "O co chodzi? A tak, oczywiście. Twoja zapłata.$B$BWeź to i znikaj. Myślę, że Jediga oczekuje twojego powrotu z niewyczerpanymi pokładami cierpliwości.",
    ["O"] = "Dostarcz Wiadomość Xylema do Jedigi z Azshary.",
    ["T"] = "Zapłata dla Jedigi od Xylema",
  },
  [3566] = {
    ["D"] = "To... to... to była pułapka.$B$BWybacz... mi.$B$BZabij drania... Za nas wszystkich... Za Thoriusa.",
    ["O"] = "Zabij Lathorica Czarnego i Obsidiona, następnie wróć do Thoriusa z Ironforge z Głową Lathorica i Sercem Obsidiona.",
    ["T"] = "Powstań, Obsidionie!",
  },
  [3567] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Na szczyt",
  },
  [3568] = {
    ["D"] = "Widzisz tę taurenkę za moimi plecami - tę, która wygląda, jakby zaraz miała zwymiotować? Odwiedziła ostatnio Azsharę. Twierdzi, że została zraniona przez jakieś nagi, gdy przedzierała się przez Ruiny Eldarath.$B$BPo walce z kilkoma z nich postanowiła odpocząć na plaży i napiła się wody z pozostałej po przypływie sadzawki. Teraz ma mdłości... między innymi.$B$BChciałbym dowiedzieć się, co wypiła. Weź to pudełko; w środku są puste fiolki, które oznaczyłem. Napełnij każdą z nich w innej sadzawce i wróć do mnie.",
    ["O"] = "Przed powrotem do Chemista Cuely\'a napełnij 4 Puste Fiolki w sadzawkach pozostałych po przypływie wzdłuż wybrzeża Ruins of Eldarath w Azsharze.",
    ["T"] = "Postępujące zatrucie",
  },
  [3569] = {
    ["D"] = "Daj to Thersie. Może jej to pomoże... Może nie. Nie dowiemy się, póki nie wypije.",
    ["O"] = "Daj Eliksir Cuely\'ego Thersie Windsong w Undercity.",
    ["T"] = "Postępujące zatrucie",
  },
  [3570] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Postępujące zatrucie",
  },
  [3581] = {
    ["D"] = "Imagine yourself racing across the plains, through forests and over mountains, the wind in your face... Traveling over unseen territory",
    ["O"] = "Speak to Saern Priderunner again to learn the Plainsrunning skill.",
    ["T"] = "Plainsrunning",
  },
  [3601] = {
    ["D"] = "Kim\'jael, doprawdy!! Czy wiesz, co Kim\'jael znaczy u krwawych elfów, $N? Mały szczur... lub coś podobnego. Wielkie bydlaki!$B$BWynajęli mnie, bym pomógł im zbadać teren w poszukiwaniu jakichś zaginionych skarbów. Oczywiście, gdy tylko usłyszałem słowo \"skarb\" i sumę, jaką mieli mi zapłacić, przyjąłem ofertę z otwartymi ramionami. Rzecz jasna, oszukali mnie i próbowali mnie zabić... MNIE!$B$BOkazuje się, że nie można ufać krwawym elfom.$B$BProblem w tym, że ciągle mają mój sprzęt i nie mogę go odzyskać. Pomożesz mi?",
    ["O"] = "Przeszukaj Thalassiańską Bazę w poszukiwaniu Kompasu Kim\'jaela, jego Lunety, Wypchanego Kurczaka oraz Wizzlegoobera, następnie wróć do niego w Azsharze.",
    ["T"] = "Kim\'jael, doprawdy!",
  },
  [3602] = {
    ["D"] = "Pradawne klifowe olbrzymy z południowego rejonu Azshary traktują skały i budynki jako swoje pożywienie. Pozostałością ich trawienia są wysoce kowalne i niezwykle silne kryształy zwane azszarytami.$B$BIch formacje walają się po południowym półwyspie, lecz niewiele z nich jest pozyskiwanych ze względu na niezwykle agresywną naturę olbrzymów.$B$BTwoim zadaniem jest udać się tam i zdobyć niezbędną do stworzenia ostrza broni ilość azszarytów. Moje felogary pomogą ci w pozyskaniu kryształów.",
    ["O"] = "Zdobądź 20 Skrystalizowanych Azszarytów z terenów południowej Azshary. Możesz skorzystać z pomocy Felogara, który \"wywącha\" dla ciebie położenie ukrytych złóż.$B$BGdy zakończysz zadanie, wróć do Loramusa.",
    ["T"] = "Azszaryt",
  },
  [3621] = {
    ["D"] = "Broń jest gotowa do wykucia. Musisz zanieść hartowany azszaryt do kogoś potrafiącego okiełznać energię felu.$B$BTaki kowal przebywa w Stranglethorn Vale. Galvan the Ancient, przywódca Mithril Order, wykuje broń zgodnie z twoim życzeniem. Jego obóz odnajdziesz pomiędzy Zul\'Gurub, a kopcem ogrów Mosh\'Ogg.$B$BNiech twoja wiara i nieustępliwość przeprowadzą cię przez tę próbę. Jeśli ci się nie uda, wiedz, że Bóg uśmiecha się do ciebie z wysokości, śmiertelniku.",
    ["O"] = "Dostarcz przesyłkę do Galvana Starożytnego, do Stranglethorn Vale.",
    ["T"] = "Kształtowanie zguby z felu",
  },
  [3622] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [3625] = {
    ["D"] = "$N, stworzenie broni zajmie mi trochę czasu.$B$BWiedz, że będziesz mógł użyć mocy klątwy felu raz na trzy minuty. W użyciu przeciwko Razelikh the Defiler i jego sługom jej osłabienie może trwać jednak dłużej, dlatego też winieneś użyć tej klątwy wyłącznie we właściwej chwili!$B$BDaj mi teraz trochę czasu na wykucie twojej broni, $N.",
    ["O"] = "Poczekaj, aż Galvan zakończy swą pracę.",
    ["T"] = "Zaczarowana felowa broń z azszarytu",
  },
  [3626] = {
    ["D"] = "Godzina odkupienia jest bliska, $N. Musisz wrócić do Blasted Lands ze swoją nową bronią i porozmawiać z Fallen Hero of the Horde, aby wskazał ci twoje ostateczne zadanie.",
    ["O"] = "Wróć do Poległego Bohatera Hordy.",
    ["T"] = "Powrót do Strzaskanej Krainy",
  },
  [3627] = {
    ["D"] = "Aby dostać się do Plugawiciela, najpierw musisz zabić trójcę mocy i połączyć rozbity amulet. Kiedy odzyskasz wszystkie trzy części, wróć do mnie, a powiem ci, co robić dalej.$B$BRuszaj, $N! Do Blasted Lands! Sevine, Allistarj oraz Grol muszą umrzeć!",
    ["O"] = "Zabij Grola Niszczyciela, Lady Sevine oraz Arcymaga Allistarj. Z ich ciał zabierz Amulet Grola, Amulet Sevine oraz Amulet Allistarj.$B$BPamiętaj, by UŻYĆ swej Zaczarowanej Felowej Broni z Azszarytu, by osłabić tę trójcę. Inaczej nie mogą zostać zabici...",
    ["T"] = "Złączenie rozbitego amuletu",
  },
  [3628] = {
    ["D"] = "Leże Razelikha znajduje się na szczycie najwyższej góry w Blasted Lands. Jedyną drogą na szczyt są teleportujące runy, umieszczone wokół góry. Tak długo, jak posiadasz amulet, możesz użyć jednej z nich. Kiedy wkroczysz do leża, musisz przywabić bestię. Amulet to twój klucz, $N. Użyj go w Altar of the Defiler.$B$BJeśli pokonasz Plugawiciela, przynieś mi jego róg. Stanie się znakiem nadziei dla wszystkich, którzy go ujrzą - dowodem na to, że bohaterowie naprawdę istnieją w tym rozdartym wojną świecie.",
    ["O"] = "Zniszcz Razelikha Plugawiciela i zanieś Odłamany Róg Plugawiciela Poległemu Bohaterowi Hordy. Musisz także zwrócić Amulet Razelikha Poległemu Bohaterowi Hordy, by został zniszczony, aby nigdy nie wpadł w niepowołane ręce.",
    ["T"] = "Tyś jest Rakh\'likh, demonie",
  },
  [3629] = {
    ["D"] = "Ekspercka inżynieria dzieli się na dwie odrębne szkoły: inżynierię gnomów i inżynierię goblinów. Wspominam o tej drugiej tylko dlatego, że jestem uczciwym nauczycielem. Gobliny lubią robić rzeczy, które wybuchają, nieważne, co stanie im na drodze - wliczając w to nie same.$B$BPrzeczytaj ten podręcznik, $N. Jeśli chcesz się nauczyć, jak wysadzić się w powietrze, zanieś go Nixxowi Sprocketspringowi z Gadgetzanu. Pamiętaj - członkostwo jest permanentne i decydując się na jedną ze stron tracisz dostęp do drugiej, więc zanim dokonasz wyboru, upewnij się, że tego właśnie chcesz.",
    ["O"] = "Jeśli życzysz sobie nauczyć się czegoś więcej o Goblińskiej inżynierii, weź tą instrukcję dla Nixxa Sprocketspringa w Gadgetzanie.",
    ["T"] = "Goblińska inżynieria",
  },
  [3630] = {
    ["D"] = "Inżynieria na poziomie eksperckim dzieli się na dwie dyscypliny: gnomów i goblinów. Inżynieria gnomów jest zdecydowanie najlepsza z tych dwóch! Polega na budowie urządzeń i gadżetów, które sprawiają, że życie jest lepsze! $B$B$N, przeczytaj podręcznik. Jeśli chcesz dowiedzieć się więcej o inżynierii gnomów - weź ten podręcznik do Majstermistrza Oversparka w Ironforge. Pamiętaj - członkostwo jest stałe i zabrania dołączania do innej dyscypliny, więc upewnij się czy jesteś $gzdecydowany:zdecydowana; zanim ukończysz to zadanie!",
    ["O"] = "Jeśli chcesz dowiedzieć się więcej o inżynierii gnomów, weź Manual of Engineering Disciplines do Majstermistrza Oversparka w Ironforge",
    ["T"] = "Inżynieria gnomów",
  },
  [3631] = {
    ["D"] = "Hmph. Mówię Ci, że nie jesteś jeszcze gotowy, ale to nie jest moja decyzja. Strahad uważa inaczej i to jest jego decyzja, aby... wysłać właśnie Ciebie.$B$BOn chce mówić z Tobą i to szybko. Znajdziesz go powyżej Ratchet w Barrens, na jego małej wieży ze swoimi Acolytami.$B$BNie zwlekaj za długo.",
    ["O"] = "Porozmawiaj ze Strahad Farsanem w Barrens.",
    ["T"] = "Przywołanie Felsteeda",
  },
  [3632] = {
    ["D"] = "Inżynieria na poziomie eksperta dzieli się na dwie odrębne szkoły: inżynierię gnomów i inżynierię goblinów. Z nich dwóch zdecydowanie wyróżnia się ta pierwsza! Polega na tworzeniu cudownych gadżetów i urządzeń, które ułatwiają życie!$B$BPrzeczytaj ten podręcznik, $N. Jeśli chcesz dowiedzieć się więcej na temat inżynierii gnomów, zanieś go Majstermistrzowi Oversparkowi tu, w Ironforge. Pamiętaj - członkostwo jest permanentne i decydując się na jedną ze stron tracisz dostęp do drugiej, więc zanim dokonasz wyboru, upewnij się, że tego właśnie chcesz.",
    ["O"] = "Jeżeli chcesz dowiedzieć się więcej na temat Inżynierii Gnomów, zanieś \"Podręcznik dziedzin inżynierii\" do Tinkmastera Oversparka z Ironforge.",
    ["T"] = "Inżynieria gnomów",
  },
  [3633] = {
    ["D"] = "Ekspercka inżynieria dzieli się na dwie dyscypliny: gnomów i goblinów. Oczywiście wszyscy genialni inżynierowie wybrali inżynierie goblinów. Naucz się, jak opanować świat dzięki rozsądnemu korzystaniu z materiałów wybuchowych i wspaniałej aparatury!$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz nauczyć się inżynierii goblinów zgłoś się do Nixxa Sprocketspringa w Gangetzanie. Pamiętaj - wybór jest stały i zabrania dołączenia do innej dyscypliny, więc upewnij się że to jest to, co chcesz robić zanim wykonasz zadanie.",
    ["O"] = "Jeśli chcesz dowiedzieć się więcej o inżynierii goblinów, weź Manual of Engineering Disciplines do Nixxa Sprocketspringa w Gadżetonie w Tanaris.",
    ["T"] = "Inżynieria goblinów",
  },
  [3634] = {
    ["D"] = "Inżynieria na poziomie eksperta dzieli się na odrębne szkoły: inżynierię gnomów i inżynierię goblinów. Choć uważam to za stratę czasu, $gpowinieneś:powinnaś; mieć świadomość istnienia tej pierwszej. Gnomy konstruują różne gadżety, które mają ponoć zmieniać świat, ale rzadko kiedy działają.$B$BPrzeczytaj ten podręcznik, $N. Jeśli chcesz się dowiedzieć, jak sprawić, by metal ważył tyle co papier, zanieś go do Oglethorpe Obnoticusa z Booty Bay. Pamiętaj - członkostwo jest permanentne i decydując się na jedną ze stron tracisz dostęp do drugiej, więc zanim dokonasz wyboru, upewnij się, że tego właśnie chcesz.",
    ["O"] = "Jeżeli chcesz dowiedzieć się więcej na temat Inżynierii Gnomów, zanieś \"Podręcznik dziedzin inżynierii\" do Majstermistrza Oversparka z Ironforge.",
    ["T"] = "Inżynieria gnomów",
  },
  [3635] = {
    ["D"] = "Inżynieria na poziomie eksperta dzieli się na odrębne szkoły: inżynierię gnomów i inżynierię goblinów. Choć uważam to za stratę czasu, $gpowinieneś:powinnaś; mieć świadomość istnienia tej pierwszej. Gnomy konstruują różne gadżety, które mają ponoć zmieniać świat, ale rzadko kiedy działają.$B$BPrzeczytaj ten podręcznik, $N. Jeśli chcesz się dowiedzieć, jak sprawić, by metal ważył tyle co papier, zanieś go Oglethorpe\'owi Obnoticusowi z Booty Bay. Pamiętaj - członkostwo jest permanentne i decydując się na jedną ze stron tracisz dostęp do drugiej, więc zanim dokonasz wyboru, upewnij się, że tego właśnie chcesz.",
    ["O"] = "Jeżeli chcesz dowiedzieć się więcej na temat Inżynierii Gnomów, zanieś \"Podręcznik dziedzin inżynierii\" do Oglethorpe\'a Obnoticusa z Booty Bay.",
    ["T"] = "Inżynieria gnomów",
  },
  [3636] = {
    ["D"] = "Plaga stanowi dla Przymierza nieustające zagrożenie - jestem pewien, że dobrze o tym wiesz. Ostatnio natrafiliśmy na pewne osobliwe znaleziska, $N. $B$BW Barrens znajduje się obrzydliwa plątanina cierni zwana Razorfen Downs. Niegdyś był to dom prostych knurokolców; obecnie wyszedł na jaw pakt zawarty Plagą, który uczynił z nich o wiele potworniejsze monstra... Są teraz podwładnymi lisza, Amnennar the Coldbringer. $B$BZjednocz się ze Światłością, $N; połóż kres tej ohydnej unii.",
    ["O"] = "Arcybiskup Benedictus chce, abyś zabił Amnennar the Coldbringer w Razorfen Downs.",
    ["T"] = "Sprowadź Światłość",
  },
  [3637] = {
    ["D"] = "Inżynieria na poziomie eksperta dzieli się na odrębne szkoły: inżynierię gnomów i inżynierię goblinów. Choć uważam to za stratę czasu, $gpowinieneś:powinnaś; mieć świadomość istnienia tej pierwszej. Gnomy konstruują różne gadżety, które mają ponoć zmieniać świat, ale rzadko kiedy działają.$B$BPrzeczytaj ten podręcznik, $N. Jeśli chcesz się dowiedzieć, jak sprawić, by metal ważył tyle co papier, zanieś go do Oglethorpe Obnoticusa z Booty Bay. Pamiętaj - członkostwo jest permanentne i decydując się na jedną ze stron tracisz dostęp do drugiej, więc zanim dokonasz wyboru, upewnij się, że tego właśnie chcesz.",
    ["O"] = "Jeżeli chcesz dowiedzieć się więcej na temat Inżynierii Gnomów, zanieś \"Podręcznik dziedzin inżynierii\" do Oglethorpe Obnoticusa z Booty Bay.",
    ["T"] = "Inżynieria gnomów",
  },
  [3638] = {
    ["D"] = "Inżynieria goblinów polega na praktycznym wykorzystaniu wysoce dochodowych i wysoce wybuchowych materiałów! Nasze schematy pozwalają nam tworzyć potężne bronie i ładunki wybuchowe; mówił o tym podręcznik, który $gczytałeś:czytałaś;.$B$BPodręcznik wspomniał też zapewne o naszej przysiędze zachowania dyskrecji. Gdy zostaniesz goblińskim inżynierem nie będzie odwrotu. Nie będziesz $gmiał:miała; żadnego dostępu do inżynierii gnomów.$B$BJeśli ciągle chcesz zostać goblińskim inżynierem, podpisz ten dokument gwarantujący zachowanie dyskrecji na całe życie i odezwij się do mnie ponownie. Dobrze to sobie przemyśl, $N.",
    ["O"] = "Jeśli zgodzisz się zostać goblińskim inżynierem, kliknij prawym klawiszem na Deklaracji Dyskrecji i jeszcze raz porozmawiaj z Nixxem Sprocketspringem z Gadgetzanu.",
    ["T"] = "Ślubowanie dyskrecji",
  },
  [3639] = {
    ["D"] = "Jako twój mentor, chcę próbek twojej pracy. Nie ma wątpliwości, że jesteś uzdolnionym inżynierem, $N. Chciałbym je obejrzeć, aby przeanalizować twoje rzemiosło pod kątem podkreślenia technik charakterystycznych dla goblińskiej myśli inżynieryjnej w twoich przyszłych konstrukcjach.$B$BPrzynieś mi proszę dwadzieścia dużych żelaznych bomb, dwadzieścia trwałych lasek dynamitu oraz pięć owiec wybuchowych - nie zapomnij ich uprzednio zabezpieczyć!$B$BPokaż mi te przedmioty, a wydam ci Kartę Członkowską Goblińskich Inżynierów z dostępem do wszystkich nauczycieli goblińskiej inżynierii!",
    ["O"] = "Przynieś Nixxowi Sprocketspringowi z Gadgetzanu 20 Big Iron Bombs, 20 Solid Dynamite i 5 Explosive Sheep.",
    ["T"] = "Pokaż wyniki swej pracy",
  },
  [3640] = {
    ["D"] = "Inżynieria gnomów polega na przekształcaniu teorii inżynierii w praktykę służącą naszym potrzebom! Nasze schematy pozwalają nam tworzyć rzeczy, które kontrolują otaczające nas środowisko; mówił o tym podręcznik, który $gczytałeś:czytałaś;.$B$BPodręcznik wspomniał też zapewne o naszej przysiędze zachowania dyskrecji. Gdy zostaniesz gnomim inżynierem, nie będzie odwrotu. Nie będziesz $gmiał:miała; żadnego dostępu do inżynierii goblinów.$B$BJeśli wciąż chcesz zostać gnomim inżynierem, podpisz ten dokument gwarantujący zachowanie dyskrecji na całe życie i odezwij się do mnie ponownie. Dobrze to sobie przemyśl, $N.",
    ["O"] = "Jeśli zgodzisz się zostać gnomim inżynierem, kliknij prawym klawiszem na Deklaracji Dyskrecji i jeszcze raz porozmawiaj z Majstermistrzem Oversparkiem z Ironforge.",
    ["T"] = "Ślubowanie dyskrecji",
  },
  [3641] = {
    ["D"] = "Widzę, że jesteś zdolnym inżynierem, nie ma co do tego wątpliwości, $N. Jako twój mentor, chciałbym zobaczyć kilka owoców twojej pracy. Chciałbym je obejrzeć, aby przeanalizować twoje rzemiosło pod kątem podkreślenia technik charakterystycznych dla gnomiej myśli inżynieryjnej w twoich przyszłych konstrukcjach. Przynieś mi proszę sześć mithrilowych rurek, dokładną lunetę oraz dwie zaawansowane kukły strzelnicze.$B$BPokaż mi te przedmioty, a oficjalnie staniesz się gnomim inżynierem z dostępem do wszystkich schematów!",
    ["O"] = "Przynieś Majstrowi Oversparkowi z Ironforge 6 Mithril Tubes, 1 Accurate Scope i 2 Advanced Target Dummies.",
    ["T"] = "Pokaż wyniki swej pracy",
  },
  [3642] = {
    ["D"] = "Inżynieria gnomów polega na przekształcaniu teorii inżynierii w praktykę służącą naszym potrzebom! Nasze schematy pozwalają nam tworzyć rzeczy, które kontrolują otaczające nas środowisko; mówił o tym podręcznik, który $gczytałeś:czytałaś;.$B$BPodręcznik wspomniał też zapewne o naszej przysiędze zachowania dyskrecji. Gdy zostaniesz gnomim inżynierem, nie będzie odwrotu. Nie będziesz $gmiał:miała; żadnego dostępu do inżynierii goblinów.$B$BJeśli wciąż chcesz zostać gnomim inżynierem, podpisz ten dokument gwarantujący zachowanie dyskrecji na całe życie i odezwij się do mnie ponownie. Dobrze to sobie przemyśl, $N.",
    ["O"] = "Jeśli zgodzisz się zostać gnomim inżynierem, kliknij prawym klawiszem na Deklaracji Dyskrecji i jeszcze raz porozmawiaj z Oglethorpe\'em Obnoticusem z Booty Bay.",
    ["T"] = "Ślubowanie dyskrecji",
  },
  [3643] = {
    ["D"] = "Widzę, że jesteś zdolnym inżynierem, nie ma co do tego wątpliwości, $N. Jako twój mentor, chciałbym zobaczyć kilka owoców twojej pracy. Chciałbym je obejrzeć, aby przeanalizować twoje rzemiosło pod kątem podkreślenia technik charakterystycznych dla gnomiej myśli inżynieryjnej w twoich przyszłych konstrukcjach. Przynieś mi proszę sześć mithrilowych rurek, dokładną lunetę oraz dwie zaawansowane kukły strzelnicze.$B$BPokaż mi te przedmioty, a oficjalnie staniesz się gnomim inżynierem z dostępem do wszystkich schematów!",
    ["O"] = "Przynieś Oglethorpe\'owi Obnoticusowi z Booty Bay 6 Mithril Tubes, 1 Accurate Scope i 2 Advanced Target Dummies.",
    ["T"] = "Pokaż wyniki swej pracy",
  },
  [3644] = {
