  [4119] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Chory nocny smok",
  },
  [4120] = {
    ["D"] = "Jako łowca staram się naśladować moich przeciwników. Znając ich dobrze łatwo jest przechylić szalę zwycięstwa na swoją stronę, $N.$B$BW miejscu noszącym nazwę Felwood, na północ od Ashenvale, zwierzęta zostały skażone przez substancję zwaną felem. Doprowadziła ona niedźwiedzie i wilki do szaleństwa, ale jestem pewien, że dodała im też sił.$B$BUdaj się do Felwood, $N, i zmierz się z tymi bestiami. Przekonaj się samemu, czy są tak silne, jak myślę.",
    ["O"] = "Talo Thornhoof z Camp Mojache w Feralas chce, abyś zabił w Felwood 12 Angerclaw Grizzlies oraz 12 Felpaw Ravagers in Felwood.",
    ["T"] = "Siła zepsucia",
  },
  [4121] = {
    ["D"] = "Naprawdę myślisz, że zdołasz dotrzeć do umówionego miejsca spotkania ze mną jako więźniem? Na serio spodziewałeś się, że włamiesz się do pilnie strzeżonej fortecy Blackrock i zabierzesz z niej tak cenny nabytek, nie ściągając przy tym niczyjej uwagi?$B$BZostaniesz zniszczony!",
    ["O"] = "Przeprowadź swojego więźnia, Grarka Lorkruba, przez Burning Steppes oraz Blackrock Mountain, aż do Searing Gorge.$B$BPamiętasz, jak Lexlort wspomniał, że jego ludzie będą czekać po drugiej stronie, aby przejąć więźnia.$B$BBędziesz musiał przekazać mu także swoje Thorium Shackles.",
    ["T"] = "Kłopotliwe położenie",
  },
  [4122] = {
    ["D"] = "Śledziłem go przez Searing Gorge i Blackrock Mountain, aż do Burning Steppes. Przyłapałem zdrajcę na gorącym uczynku, gdy przekazywał orkom z Blackrock zapiski dotyczące naszych codziennych działań. Mówię o Grarku Lorkrubie.$B$BZnajduje się teraz w Burning Steppes, bezpieczny pod ich opieką - a przynajmniej tak mu się wydaje.$B$BWeź te kajdany, $N. Znajdź Grarka, zakuj go w nie i przeprowadź przez Blackrock Mountain. Zrób to, a nagroda będzie twoja.",
    ["O"] = "Udaj się do Burning Steppes i znajdź Grarka Lorkruba. Pamiętasz, że Lexlort wspominał, że ostatnio widziano go w potężnej fortecy Blackrock.$B$BGdy znajdziesz Grarka Lorkruba, skuj go Kajdanami z Thorium i przeprowadź go przez Blackrock Mountain do Searing Gorge. Ludzie Lexlorta będą czekać tam na ciebie, by przejąć więźnia.",
    ["T"] = "Grark Lorkrub",
  },
  [4123] = {
    ["D"] = "Od lat poszukuję pewnego klejnotu. Nazwano go Heart of the Mountain i jest rozmiaru twojej pięści! Krasnoludy Dark Iron trzymają go w swym skarbcu i choćbym nie wiem co zrobił, nie zechcą mi go sprzedać.$B$BMuszę więc posunąć się do użycia siły.$B$BPrzebij się do Lower Vault czeluści Blackrock Depths, włam się do skrytki krasnoludów i zabierz stamtąd Serce. Aby tego dokonać, musisz pokonać Wartownika Doomgripa, a on nie pojawi się, póki nie otworzysz każdego schowka w skarbcu!$B$BPowodzenia.",
    ["O"] = "Przynieś Heart of the Mountain do Maxworta Uberglinta z Burning Steppes.",
    ["T"] = "Serce Góry",
  },
  [4124] = {
    ["D"] = "Współpracownik Ginro Hearthkindle szuka pomocy w kwestii zlokalizowania położenia kuriera i przesyłek, które nosił. Minęło około tygodnia odkąd kurier zniknął. Poszukiwania go na własną rękę okazały się bezowocne i jesteśmy w impasie. Niestety musiałem poinformować, że kurier zaginął w akcji.$B$BJeżeli masz czas oraz zasoby na zbyciu, proszę porozmawiaj z Ginro. Powinien znajdować się w twierdzy Stronghold, w swojej kwaterze.",
    ["O"] = "Porozmawiaj z Ginro Hearthkindle w Feathermoon Stronghold.",
    ["T"] = "Zaginiony kurier",
  },
  [4125] = {
    ["D"] = "Minęło około tygodnia, odkąd Raschal, kurier, wyruszył do Thalanaar. Zna dobrze Feralas. Był z nami odkąd generał Feathermoon poprowadził tutaj siły ekspedycyjne. Wiem, że jego plan polegał na przepłynięciu łodzią przy brzegu i spróbowaniu przejścia przez południowe Feralas, aby uniknąć obozu Hordy.$B$BNie mogłem znaleźć jego łodzi, ale może ty możesz. Może jest ukryta, czy może nawet zatopiona. Niezależnie od tego, może być gdzieś wskazówka, gdzie ona jest. Jeśli odkryjesz coś, daj mi znać.",
    ["O"] = "Zlokalizuj łódź kurierską gdzieś wzdłuż wybrzeża Feralas.",
    ["T"] = "Zaginiony kurier",
  },
  [4126] = {
    ["D"] = "Krasnoludy Czarnorytne, prowadzone przez złoczyńcę Hurleya Blackbreatha, ukradli jeden z najlepszych przepisów na piwo klanu Thunderbrew. Bandyci! Nie zasługują na taki dobry przepis!$B$B$N, mam dla ciebie trudne zadanie. Pójdź do Głębin Blackrock w Burning Steppes, zniszcz wszystkie beczki Thunderbrew Lager, które znajdziesz, i odzyskaj przepis na gorzałkę!$B$BProszę, odzyskaj przepis, nawet jeśli musisz wywrócić Głębiny Blackrock do góry nogami, aby to zrobić!",
    ["O"] = "Przynieś Lost Thunderbrew Recipe do Ragnara Thunderbrewa w Kharanos.",
    ["T"] = "Hurley Blackbreath",
  },
  [4127] = {
    ["D"] = "Grzebiąc w błocie twoje palce natrafiają na rękojeść noża. Wygląda na zadbnany i można śmiało stwierdzić, że ktokolwiek, kto był na łodzi mógł go zgubić. Być może duża część zagubionej łodzi może mieć coś wspólnego ze zgubą.$B$BŁapiesz nóz, pamiętając, że Ginro Hearthkindle z Feathermoon Stronghold poinstruował Cię, aby pokazać mu wszelkie znalezione rzeczy. Masz jednak wrażenie, że nie jesteś całkiem sam w wodzie...",
    ["O"] = "Wróć do Feathermoon Stronghold i pokaż Ginro Heartkindlowi Discarded Knife, który znalazłeś.",
    ["T"] = "Wrak Statku",
  },
  [4128] = {
    ["D"] = "Ho, $N. Słyszałem, że Ragnar Thunderbrew jest wściekły na kogoś, kto kradnie mu piwo. Poszukuje on dzielnych poszukiwaczy przygód i jest gotów mnóstwo zapłacić.$B$BPorozmawiaj z Ragnar jeśli jesteś zainteresowany. Jest w Thunderbrew Distillery w Kharanos, w Dun Morogh.",
    ["O"] = "Porozmawiaj z Ragnar Thunderbrew.",
    ["T"] = "Ragnar Thunderbrew",
  },
  [4129] = {
    ["D"] = "Zamieszkały w Stronghold druid, Quintis Jonespyre, ma pewne... unikalne moce. Jedna z nich obejmuje psychometrię - zdolność do dotykowego ujawnienia historii przedmiotu. Nie pytaj mnie jak to robi; ja przypisuję to magii, której nie rozumiem i nie chcę zrozumieć. Wiem jednak dwie rzeczy: pierwsza - widziałem, że to działa i druga - jest mi winny przysługę.$B$BZanieś ten nóż do Quint\'a, do jego małego drzewnego domu i przekaż mu ode mnie, że jego karciany dług zostanie spłacony, jeśli zastosuje na tym nożu swoje czary.",
    ["O"] = "Zabierz ze sobą Discarded Knife do samotni Quintisa w Feathermoon Stronghold",
    ["T"] = "Sekrety noża",
  },
  [4130] = {
    ["D"] = "Jestem trochę chwiejny, niestety. W każdym razie otrzymałem kilka użytecznych wizji.$B$BRaschal zabiera ze swojej łodzi dwa duże skórzane plecaki i wchodzi do środka; wraca jednak do łodzi. Widzę głowy gnolli... wpadł na jakieś gnolle - Woodpaw myślę, że tak są nazywani. Jest bardzo zmartwiony - niemal przerażony - o czymś. Tak bardzo, że nie zwraca uwagi na tworzące się za sobą żywioły wody. Obrazy... zatrzymaj się.$B$BPotrzebuje odpoczynku przepraszam $N. Powiedz Ginie, co widziałem. Musi wiedzieć.",
    ["O"] = "Porozmawiaj z Ginro Hearthkindle w Feathermoon Stronghold.",
    ["T"] = "Czytanie psychometryczne",
  },
  [4131] = {
    ["D"] = "Nasi \"przyjaciele\", Leśnołape gnolle, mogli dorwać w końcu Raschala, ale coś mi mówi, że tak się nie stało. Nadal, ich obóz to najlepsze miejsce, gdzie można zacząć poszukiwania.$B$BChciałbym posiadać jaśniejsze instrukcje dotyczące tego, co trzeba zrobić, ale wszystko, co wiem na tę chwilę, to: \"Znajdź obóz gnolli - ruszaj.\" Wiem, że gnolle zatrzymują sobie rzeczy, które znajdą, i walczą o nie; może natknęły się na plecaki, o których wspomniał Quint. W przeszłości nie zaryzykowałbym bezpośredniej walki, ale biorąc pod uwagę wizję Quinta, nie wahajcie się użyć przemocy.",
    ["O"] = "Poszukaj w obozie Leśnołapych gnolli w południowym Feralas rzeczy należących do kuriera lub jego samego.",
    ["T"] = "Leśnołape gnolle",
  },
  [4132] = {
    ["D"] = "Wykonałeś świetną robotę, $N. Teraz nadszedł czas, aby wysłać cię na ostatnią misję.$B$BGenerała Angerforge z Dark Iron odpowiedzialny za koordynacje ataków na 109 dywizję K.E.F. i masowe wycinanie naszych sił, musi spotkać sprawiedliwość.$B$BTo niewątpliwie będzie Twoja najtrudniejsza misja, ale jeśli ci się uda, zostaniesz sowicie wynagrodzony.",
    ["O"] = "Udaj się do Blackrock Depths i zabij Generała Angerforge! Wróć do Warlord Goretooth, gdy zadanie zostanie zakończone.",
    ["T"] = "Operacja: Śmierć Angerforge",
  },
  [4133] = {
    ["D"] = "Shadowmaster Vivian Lagrave potrzebuje twojej pomocy. Ona jest w Badlands, w orkowej placówce zwanej Kargath, chodzą pogłoski o pewnym naparze zrobionym przez krasnoludów z klanu Dark Iron z Blackrock Depths.$BNEW_LinePorozmawiaj z Vivian. Ona czeka na Ciebie.",
    ["O"] = "Porozmawiaj z Shadowmaster Vivian Lagrave w Kargath.",
    ["T"] = "Vivian Lagrave",
  },
  [4134] = {
    ["D"] = "Mówi się, że Hurley Blackbreath z klanu Dark Iron, ukradł przepis na piwo. To piwo, Thunderbrew Lager, napełnia pijącego dużą siłą i odwagą. Chcemy przestudiować ten napitek. Być może znajdziemy inne zastosowania z jego zaletami... aplikacje bardziej zgodne z celami Opuszczonymi.$B$BPójdź do Blackrock Depths i znajdź Hurleya, weź od niego przepis na Thunderbolt Lager i przynieś go do mnie.$B$BAby go odnaleźć, może będziesz musiał go zwabić i zagrozić jego cennemu piwu.",
    ["O"] = "Przynieś Lost Thunderbrew Recipe do Viviana Lagrava w Kargath.",
    ["T"] = "Zaginiona recepta Thunderbrew",
  },
  [4135] = {
    ["D"] = "W plecaku są dwa przedmioty: pierwszy to paczka przedmiotów powiązanych z Thalanaar, drugi to notatka napisana w pośpiechu do nieznanego odbiorcy.$B$BNotatka mówi o odkryciu podstępnych, robako-podobnych stworzeń na południe od obozu gnolli, w miejscu zwanym Wijąca Otchłań. Autor czuł potrzebę zbadania tego osobiście, jakby było to prawdziwe zagrożenie dla wszystkich w Feralas. Zapiski są podpisane \"Raschal z Feathermoon\".$B$BWydaje się, że znalazłeś miejsce, w którym ostatecznie wylądował Raschal.",
    ["O"] = "Odkryto ostatnie znane miejsce pobytu Raschala, kontynuuj poszukiwania jego lub jego szczątków w Wijącej Otchłani. Zgodnie z notatką, znajduje się ona na południu od obozowiska Gnolli Woodpaw.",
    ["T"] = "Wijąca Otchłań",
  },
  [4136] = {
    ["D"] = "Mój brat Ribbly zawsze pasożytował na swej rodzinie, brał nasze pieniądze i marnował je na schemat za schematem.$B$BOstatni schemat musiał być jego najgorszym dziełem, ponieważ Baron Revilgaz z Booty Bay właśnie ogłosił cenę za głowę biednego Ribbly\'ego. Nawet nie wiesz, jak cieszy to Screwspigotów! Nasz mały Ribbly wreszcie jest coś wart!$B$BTeraz chowa się głęboko w Blackrock Depths. Proszę, znajdź i przyprowadź go do mnie!$B$BAle, jeśli nie będzie chciał iść, to się nie martw... po prostu przynieś mi jego głowę.",
    ["O"] = "Przynieś głowę Ribbly\'ego do Yuki Screwspigot w Burning Steppes.",
    ["T"] = "Ribbly Screwspigot",
  },
  [4141] = {
    ["D"] = "Widzisz tam Lariona? To JEGO wina, że jesteśmy tutaj!$B$BMówiłem mu, że idziemy w złym kierunku, ale czy posłuchał? Czy mógłbyś uwierzyć, że to on jest tym, który się do mnie nie odezwie? Cóż, dopóki nie zmieni swojego zdania, poróbmy sobie z niego trochę żartów.$B$BCzy dostrzegłeś dziwne roślinopodobne stworzenia w okolicy? są jedynie problemem, naprawdę, ale myślę że odpowiednio wytrenowane, mogę zmusić je do wykonywania poleceń.$B$BPo pierwsze jednak, będę potrzebował trochę próbek do analizy. Myślisz, że mógłbyś zdobyć ich trochę?",
    ["O"] = "Zdobądź 15 Bloodpetals i powróć do Muigin.",
    ["T"] = "Muigin i Larion",
  },
  [4142] = {
    ["D"] = "Nie jestem pewien, co z tym zrobić, $N. Rośliny... wydają się mieć minimalną inteligencję.$B$BNie jestem żadnym specjalistą. Ale znam kogoś, kto nim jest!$B$BPójdź na północne Feralas i poszukaj mojego przyjaciela Gregana Brewspewera. Jest ekspertem w tych sprawach.$B$BJestem pewny, że Gregan może nam pomóc. Znajdziesz go na pustyni; nie jest typem, który żyje w dużym mieście.",
    ["O"] = "Weź Bloodpetal do Gregana Brewspewera w Feralas.",
    ["T"] = "Wizyta u Gregana",
  },
  [4143] = {
    ["D"] = "Prawdę mówiąc, $N, nigdy nie widziałem podobnych roślin w swoich podróżach. Być może powinienem wyruszyć do tego krateru...$B$BMyślę, że wiem czego Muigin szuka - Atal\'ai Haze. To straszne rzeczy, trudne do zebrania, ale tego potrzebuję, by kontrolować małe potwory.$B$BMusisz odwiedzić świątynię Atal\'Hakkar na Swamp of Sorrows. Atal\'ai Haze można zbierać z głębinowych lurkerów, mrocznych robaków lub szlamów. Powodzenia, $N!",
    ["O"] = "Zbierz 5 próbek Atal\'ai Haze, a następnie wróć do Muigina w Un\'Goro Crater.",
    ["T"] = "Mgła zła",
  },
  [4144] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Kiełki Krwawopłatka",
  },
  [4145] = {
    ["D"] = "Widzisz tam Muigina? To JEGO wina, że się zgubiliśmy!$B$BTo ja byłem tym, który znał drogę, ale on uparł się, że zna skrót, no i skończyliśmy tutaj!$B$BNa domiar złego, ciągle przysyła mi swoje szalone szkodniki roślinne żeby mnie irytować. Jestem tak zły, że nie planuję się do niego odzywać w najbliższym czasie, ale te szkodniki to już za wiele.$B$BCzemu nie spróbujemy uszczuplić jego zapasów, to pierwsza rzecz. Idź i upoluj trochę Bloodpetals, potem wróć do mnie.",
    ["O"] = "Upoluj 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers oraz 5 Bloodpetal Trappers dla Lariona w Marshal\'s Refuge.",
    ["T"] = "Larion i Muigin",
  },
  [4146] = {
    ["D"] = "Masz szczęście, $N! Pracowałem nad niektórymi własnymi eksperymentami, kiedy Marvon zniknął i jeden z nich miał krótkotrwałą usterkę. Wystarczy kilka poprawek, to powinno być świetne, aby pozbyć się szkodników Bloodpetal.$B$BMogę pozwolić ci mieć jeden zapper z moich prototypów, ale będziesz musiał uzupełnić paliwo. Możesz dostać potrzebną mgłę Atal\'ai, którą zapper potrzebuje w świątyni Atal\'Hakkar. Deep Lurkers, Murk Worms lub Oozes są tymi, których potrzebujesz.",
    ["O"] = "Dostarcz Unloaded Zapper i 5 próbek Atal\'ai Haze do Larion w Marshal\'s Refuge.",
    ["T"] = "Paliwo Zapper",
  },
  [4147] = {
    ["D"] = "Udało mi się wyszpiegować co robi Muigin, a on rzeczywiście coś tam rozwija!$B$BMyślę, że jedynym rozwiązaniem jest... nie, nie porozmawiać z nim... co sobie myślisz? Rozwiązaniem jest walka!$B$BPotrzebujemy pomocy mojego przyjaciela Marvona, która ma pracownie w Ratchet. Jestem pewien, że będzie w stanie stworzyć jakiś gadżet, który nam pomoże.",
    ["O"] = "Udaj się do pracowni Marvon Rivetseeker w Ratchet.",
    ["T"] = "Pracownia Marvona",
  },
  [4148] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Krwistopłatkowy porażacz",
  },
  [4161] = {
    ["D"] = "Dawno temu nocne elfy nosiły miano kaldorei, co oznacza \"dzieci gwiazd\". Znajomość historii jest dla ciebie równie ważna jak trening bojowy, $N, słuchaj zatem uważnie.$B$BKaldorei zawsze czerpali dumę z harmonii zachowywanej w kontaktach z naturą. Oznacza to, że bierzemy z natury jedynie to, co nam niezbędne, i dajemy w zamian coś o równej wartości. Utrzymywanie tej równowagi, $N, jest dla nas korzystne.$B$BIdź w las i zbierz dla mnie siedem małych odnóży pająków - nie więcej.",
    ["O"] = "Zbierz 7 Small Spider Legs dla Zerrina w Dolanaarze.",
    ["T"] = "Kaldorejski przepis",
  },
  [4181] = {
    ["D"] = "Ekspercka inżynieria dzieli się na dwie odrębne szkoły: inżynierię gnomów i inżynierię goblinów. Wspominam o tej drugiej tylko dlatego, że jestem uczciwym nauczycielem. Gobliny lubią robić rzeczy, które wybuchają, nieważne, co stanie im na drodze - wliczając w to nie same.$B$BPrzeczytaj ten podręcznik, $N. Jeśli chcesz się nauczyć, jak wysadzić się w powietrze, zanieś go Nixxowi Sprocketspringowi z Gadgetzanu. Pamiętaj - członkostwo jest permanentne i decydując się na jedną ze stron tracisz dostęp do drugiej, więc zanim dokonasz wyboru, upewnij się, że tego właśnie chcesz.",
    ["O"] = "Jeżeli chcesz dowiedzieć się więcej na temat Inżynierii Goblinów, zanieś \"Podręcznik dziedzin inżynierii\" do Nixxa Sprocketspringa z Gadgetzanu.",
    ["T"] = "Inżynieria goblinów",
  },
  [4182] = {
    ["D"] = "Życie na Burning Steppes obfituje w konflikty.$B$BSpójrz tylko na to miejsce! Wiemy bardzo niewiele o tym, co tu się wydarzyło, ale kiedyś, przed wielkim wybuchem, wszystko to było częścią gór Redridge.$B$BDość płaczów! Mamy problem, $N. Może już zauważyłeś smokowców pod tą granią. Potrzebujemy pomocy w wyparciu ich stąd. Zabij, ilu dasz radę, i wróć do mnie. Jeśli ci się uda, może porozmawiamy o innych kwestiach.",
    ["O"] = "Zabij 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin i 1 Black Drake.",
    ["T"] = "Zagrożenie ze strony smokowców",
  },
  [4183] = {
    ["D"] = "Zawsze sądziliśmy, że orki z klanu Czarnej Skały są produktami bestialskiego wychowania, jednak to, co znaleźliśmy na ich ojczystej ziemi, rzuca inne światło na tę kwestię.$B$BTo prawda, że tym, co napędza orków, jest żądza krwi i walki, ale istotami, które ich kontrolują, są czarne smoki. Podejrzewamy, że to właśnie te gady napełniają ich gniewem i wrogością.$B$BZanieś ten list do sędziego Solomona. Będzie wiedział, co robić.$B$B<Helendis wręcza ci zapieczętowany list.>",
    ["O"] = "Udaj się do Lakeshire w Redridge Mountains i dostarcz Helendis Riverhorn\'s Letter do Magistrate\'a Solomona.",
    ["T"] = "Prawdziwi władcy",
  },
  [4184] = {
    ["D"] = "To ponure wieści, $N. Świadomość, że nasi śmiertelni wrogowie są zaledwie sługami znacznie potężniejszych istot, jest przygnębiająca. Nie ma szans, żeby Lakeshire przetrwało połączony atak orków i czarnych smoków. A jeśli Lakeshire padnie, Darkshire wkrótce pójdzie jego śladem. Co będzie następne? Goldshire? Samo Stormwind?$B$BMusisz natychmiast dostarczyć te informacje do króla Stormwind, Variana Wrynna! Jeśli one nie nakłonią go do przysłania posiłków, to nic go nie przekona, a wówczas wszystko stracone.",
    ["O"] = "Udaj się do Stormwind i dostarcz Solomon\'s Plea do Króla Variana Wrynna.$B$BZnajdziesz go w Stormwind Keep.",
    ["T"] = "Prawdziwi władcy",
  },
  [4185] = {
    ["D"] = "Solomon maluje sytuację w czarnych barwach. Jednakże nie możemy pozwolić sobie na skierowanie naszych rozproszonych po kraju sił do Lakeshire na podstawie czystych spekulacji. Nim będę mógł działać, potrzebuję dowodów na potwierdzenie tego, o czym napisał Solomon.$B$BPorozmawiaj z Lady Prestor, $N. To uczona kobieta; wie dużo o smokach i smokowcach. Może ona rzuci nieco światła na tę sytuację.",
    ["O"] = "Porozmawiaj z Highlordem Bolvarem Fordragonem, po tym jak pomówisz z Lady Katraną Prestor.",
    ["T"] = "Prawdziwi władcy",
  },
  [4186] = {
    ["D"] = "Upoważnię cię do działania w imieniu Stormwind, $N.$B$BWróć do Lakeshire, do sędziego Solomona, i dostarcz mu to zarządzenie.",
    ["O"] = "Zanieś Wrynn\'s Decree do Magistrate\'a Solomona z Lakeshire.",
    ["T"] = "Prawdziwi władcy",
  },
  [4201] = {
    ["D"] = "Och, udręki miłości! Mój ukochany szeregowiec Rocknot jest nieczuły na me wdzięki. Zostałam odtrącona! To mnie doprowadza do szaleństwa!$B$BMusisz mi pomóc! My, sukuby, wiemy wiele o miłości, a ja potrafię sporządzić napar, który skruszy żelazne mury, otaczające serce mego miłego. W tym celu będę potrzebowała następujących przedmiotów: ziela o nazwie krew Groma, olbrzymią żyłę srebra z jednego z klifowych olbrzymów z Azshary i nieco wody z Golakka Springs Crater w Un\'Goro. Możesz nabrać wody do tej fiolki.$B$BProszę, $N, pomóż nieszczęsnej duszy w próbie zdobycia szczęścia!",
    ["O"] = "Przynieś Mistress Nagmarze z Blackrock Depths 4 Gromsblood, 10 Giant Silver Veins i Nagmara\'s Filled Vial.",
    ["T"] = "Napój miłosny",
  },
  [4221] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Chore wiatrokwiecie",
  },
  [4222] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Chore wiatrokwiecie",
  },
  [4223] = {
    ["D"] = "<Sędzia Solomon wzdycha.>$B$BMusisz wrócić na Burning Steppes, $N. Jako przedstawiciel Stormwind, będziesz podlegać Komendantowi Maxwellowi. Powodzenia.",
    ["O"] = "Porozmawiaj z Marshalem Maxwellem na Burning Steppes.",
    ["T"] = "Prawdziwi władcy",
  },
  [4224] = {
    ["D"] = "Co? Myślałeś, że byłeś pierwszy? Ilu jeszcze żołnierzy musimy stracić, zanim Stormwind zacznie działać?$B$BZebraliśmy ogromną ilość informacji dotyczących zagrożenia ze strony Czarnej Skały, po czym straciliśmy oficera dowodzącego, Komendanta Windsora. Wraz z nim przepadły wszystkie zgromadzone dane.$B$BPotrzebujemy właśnie tych dokumentów. Porozmawiaj z Johnem Obdartusem, $N. Towarzyszył Windsorowi, kiedy zaatakowały ich orki. Po raz ostatni widziano go w jaskini na północ stąd.",
    ["O"] = "Porozmawiaj z Ragged Johnem.",
    ["T"] = "Prawdziwi władcy",
  },
  [4241] = {
    ["D"] = "Więc ten bezwartościowy tchórz powiedział ci, że Windsor nadal żyje, tak?$B$BNo to wskakuj w zbroję, żołnierzu - musisz go odnaleźć. Jeśli nadal żyje, masz sprowadzić go tu z powrotem. A jeśli jest martwy, chcę na to dowodu.$B$B<Maxwell śmieje się.>$B$BZałożę się, że masz już powyżej uszu tego tekstu, co?",
    ["O"] = "Udaj się na północny zachód, do Blackrock Mountain, i wejdź do Blackrock Depths. Potem dowiedz się, co się stało z Marshalem Windsorem.$B$BPrzypominasz sobie, że Ragged John mówił coś o Windsorze wleczonym do więzienia.",
    ["T"] = "Komendant Windsor",
  },
  [4242] = {
    ["D"] = "Bolvar to głupiec. Zbierałem te jego cenne \"dowody\", żeby się nimi udławił.$B$BJest ślepym pajacem. Ma dowody tuż przed nosem, a ich nie widzi.$B$BJeśli chodzi o moje dokumenty, to przepadły. Na amen. Są nie do odzyskania.$B$BSJeśli kiedykolwiek uda mi się znaleźć Ironfoe\'a i wydostać się z tego labiryntu, to pierwszym miejscem, do jakiego się udam, będzie Stormwind, a pierwsze, co tam zrobię, to przywalę tej gadzinie młotem prosto między oczy.$B$BZostaw mnie w spokoju, $N.",
    ["O"] = "Przekaż Marshal Maxwell z Morgan\'s Vigil na Burning Steppes złą wiadomość.",
    ["T"] = "Utracona nadzieja",
  },
  [4243] = {
    ["D"] = "Niestety, coś się stało z jednym z moich największych wynalazków. Widziałeś mechaniczne wiewiórki? Cóż, żeby poznać bliżej małpy z krateru Un\'Goro, skonstruowałam ich mechaniczny odpowiednik. Nazwałam ją To-Ja 01.$B$BMiała dalekowidzące klejnoty zamiast oczu, więc widziałam wszystko to, co ona. Udało jej się dotrzeć do Fungal Rock, gdzie mieści się leże małp, i wtedy straciłam z nią kontakt. Ostatnią rzeczą, jaką widziałam, był jeden z tamtejszych samców alfa, który pędził w stronę To-Ji, by się z nią przywitać!$B$BPomożesz mi ją znaleźć?",
    ["O"] = "Znajdź A-Me 01 w Un\'Goro Crater.",
    ["T"] = "W pogoni za To-Ją 01",
  },
  [4244] = {
    ["D"] = "Po bliższych oględzinach znajdujesz wysuwany panel. Nad okablowaniem dostrzegasz wyraźnie napisane zdanie: \"Wymień mithrilową obudowę, a potem wyłącz i włącz zasilanie.\"$B$BUmieszczając panel na miejscu, zastanawiasz się, czy naprawienie To-Ji i przyprowadzenie jej do Marshall\'s Refuge, do Karny Remtravel będzie naprawdę takie proste.$B$BDowiesz się, jak spróbujesz.",
    ["O"] = "Znajdź Mithril Casing i wróć do A-Me 01, do Un\'Goro Crater.",
    ["T"] = "W pogoni za To-Ją 01",
  },
  [4245] = {
    ["D"] = "Po tym, jak upewniłeś się, że jesteś gotowy odprowadzić To-Ję 01 do Karny Remtravel, ustawiasz przełącznik na pozycji \"Wyłącz\". Rozglądasz się przez chwilę, aby sprawdzić, czy wokół nie ma żadnych goryli, i zastanawiasz się, co się stanie, gdy włączysz maszynę.$B$BTo twoja ostatnia szansa... Na pewno chcesz to zrobić?",
    ["O"] = "Odprowadź A-Me 01 do Karny Remtravel z Un\'Goro Crater.",
    ["T"] = "W pogoni za To-Ją 01",
  },
  [4261] = {
    ["D"] = "Felwood był tak spokojnym i pogodnym miejscem... dopóki nie opanował go Legion. Infernale, zniszczenie, chaos...$B$BCzaszka Gul\'dana dopilnowała, by nikt nie został oszczędzony. Wszystko uległo skażeniu.$B$BNawet teraz, jako duch, wciąż czuję się jak w pułapce, dźwigając cierpienie tej ziemi. Pomóż mi wrócić do domu. Proszę, $N, powiedz mi, że odprowadzisz prastarego ducha do miejsca, w którym będzie mógł wreszcie odpocząć.$B$BKiedy już będę wolny, odnajdź proszę Kaynetha Stillwinda, druida, który przebywa w Pieśni Puszczy, na wschodzie.",
    ["O"] = "Odprowadź Areia w bezpieczne miejsce, następnie porozmawiaj z Kaynethem Stillwindem z Forest Song we wschodnim Ashenvale.",
    ["T"] = "Prastary duch",
  },
  [4262] = {
    ["D"] = "Ostatnich pięciu magów, którzy poszli powęszyć wokół Góry Czarnej Skały, wróciło spalonych na skwarki z fantazyjną pomarańczową fryzurą – jeśli nie gorzej.$B$B<Jalinda podnosi z ziemi garść popiołu i rozsiewa ją w powietrzu.>$B$BKłopoty sprawia szczególnie jeden paskudny stwór - Zwierzchnik Pyron. Trzeba pozbyć się tego żywiołaka, żeby nasza ekipa badawcza mogła dostać się do Głębin Czarnej Skały!$B$BPyron pilnuje wejścia do kamieniołomu Czarnej Skały.",
    ["O"] = "Zabij zwierzchnika Pyrona.$B$BPamiętasz, że Jalinda mówiła, iż Pyron strzeże kamieniołomu. Może $gpowinieneś:powinnaś; go tam poszukać?",
    ["T"] = "Zwierzchnik Pyron",
  },
  [4263] = {
    ["D"] = "Jesteś pewien, że w swoich ostatnich słowach Pyron wspomniał Incendiusa?$B$B<Jalinda z trudem przełyka ślinę.>$B$BLord Incendius jest jakoby sługą Ragnarosa! O rany, o rany... co my zrobimy?$B$BJak myślisz, podołasz kolejnej misji? Nie mam nikogo innego, $N!$B$BDopóki Incendius nie przestanie przywoływać Pyrona z popiołów, nigdy nie uda nam się dostać do środka.$B$BMusisz go znaleźć i zniszczyć!",
    ["O"] = "Odnajdź Lorda Incendiusa w Blackrock Depths i zniszcz go!",
    ["T"] = "Incendius!",
  },
  [4264] = {
    ["D"] = "Kartka jest pokryta plamami. Tekst ledwie daje się odczytać, ale zauważasz następujące zwroty:$B$B...słodka ironia...$B$B...upadek rozbitego Przymierza...$B$B...gdyby nie staranność Generała Angerforge\'a, moglibyśmy nigdy nie odkryć klucza do szyfru...$B$B...Argelmach prawie skończył odszyfrowywanie notatek Windsora.$B$BNasz pan powstanie z otchłani i zniszczy wszystko, co pozostanie...$B$B- Imperator Dagran Thaurissan.",
    ["O"] = "Właśnie natknąłeś się na coś, co może wzbudzić zainteresowanie Marshala Windsora. Być może jest jeszcze jakaś nadzieja.",
    ["T"] = "Zgnieciona kartka",
  },
  [4265] = {
    ["D"] = "Pod wpływem twojego dotyku kokon otwiera się, uwalniając nocnego elfa płci męskiej, który o dziwo wciąż żyje. Najwyraźniej jest w dobrym stanie, choć jest mocno oszołomiony. Kiedy pomagasz mu wydostać się z kokonu, nieco się ożywia.$B$B\'Dzięki Elune - uratowałeś mnie, przyjacielu! Jestem... Raschal. Obudziłem się sparaliżowany w środku tego kokonu, po tym jak obezwładniły mnie te stworzenia. Przysłano cię z Fortecy?\'$B$BWygląda na to, że znalazłeś zaginionego kuriera!",
    ["O"] = "Uwolnij Raschala z kopca Zukk\'ashów.$B$BWróć do Feathermoon Stronghold, do Ginra Hearthkindle\'a i przekaż mu, że Raschal żyje i ma się dobrze.",
    ["T"] = "Uwolniony z kopca",
  },
  [4266] = {
    ["D"] = "$N, Generał Shandris Feathermoon chce pomówić z tobą osobiście. Nie mam wątpliwości, że pragnie podziękować ci za przysługi wyświadczone Fortecy, ale wiem też, że chce porozmawiać o robalach, które ty i Raschal napotkaliście w południowym Feralas. Wieści o tych owadach Zukk\'ash są... co najmniej niepokojące.$B$BGenerał Feathermoon czeka na ciebie w głównym budynku.",
    ["O"] = "Porozmawiaj z Shandris Feathermoon w Feathermoon Stronghold.",
    ["T"] = "Powitanie bohatera",
  },
  [4267] = {
    ["D"] = "Powierzam ci kopię raportu Raschala na temat plagi robactwa w południowo-wschodnim Feralas. Oryginał zostanie umieszczony w Darnassus, natomiast chciałabym, żebyś zaniósł tę kopię do przedstawicielki Protektoratu. Nazywa się Gracina Spiritmight; jest kapłanką przebywającą w Temple of the Moon w Darnassus. Dysponuje rozległą wiedzą na temat tych stworzeń i jeśli dostarczysz jej ten raport, wszyscy na tym skorzystamy.$B$BOdmaszerować. Powodzenia, $N; niech Elune ma nas wszystkich w opiece.",
    ["O"] = "Dostarcz Raschal\'s Report do Graciny Spiritmight z Darnassus.",
    ["T"] = "Odrodzenie silithidów",
  },
  [4281] = {
    ["D"] = "Paczka, którą znalazłeś w obozie Leśnołapych, prawdopodobnie miała trafić do Thalanaaru, małego posterunku w południowo-wschodnim Feralas. Bez względu na los zaginionego kuriera, paczka wciąż pozostaje niedostarczona.$B$BDokładne oględziny paczki ujawniają wypisane ręcznie na opakowaniu imię \"Falfindel Waywarder\". Może to do niego miała trafić.",
    ["O"] = "Zanieś Undelivered Parcel do Falfindela Waywardera z Thalanaaru.",
    ["T"] = "Przesyłka do Thalanaaru",
  },
  [4282] = {
    ["D"] = "<Komendant Windsor macha z podekscytowaniem kartką.>$B$BCzy wiesz, co to oznacza, $N?$B$BMoże nie wszystko stracone! Z tego, co zdołałem ustalić, notatki są w posiadaniu dwóch krasnoludów Ciemnego Żelaza: Generała Angerforge\'a i lorda golemów, Argelmacha. Mam przeczucie, że nie oddadzą ci ich tak po prostu, nawet jeśli ładnie poprosisz.$B$BMam nadzieję, że jesteś gotów do walki.$B$BIdź i znajdź tych dwóch nikczemników! Zniszcz ich i przynieś mi moje zaginione notatki.",
    ["O"] = "Odzyskaj Marshal Windsor\'s Lost Information.$B$BMarshal Windsor uważa, że są one w posiadaniu Golem Lorda Argelmacha i Generała Angerforge\'a.",
    ["T"] = "Okruch nadziei",
  },
  [4283] = {
    ["D"] = "Chcę ci zdradzić pewien sekret, żołnierzu. Podejdź no tu bliżej.$B$BTYLKO JA TU JESTEM NORMALNY!$B$BPopatrz na tych ludzi! Uwierzysz, że wszyscy są niepoczytalni!? No więc są! ŚWIRY! SZALEŃCY!$B$B<Oralius ścisza głos.>$B$BNiech to zostanie pomiędzy mną, tobą i moim kumplem Kapitanem Winkym.$B$B<Oralius grabs at the air and squeezes.>$B$BTak czy siaaak... zbieram odznaki, bo ładnie pasują do mojej kolekcji ogrzych uszu. Orkowe to ostatni krzyk mody. Pięćdziesiąt. RUSZAJ!$B$B<Oralius dmie w róg.>$B$BDAJESZ!",
    ["O"] = "Zbierz 50 Blackrock Medallions.",
    ["T"] = "PIĘĆDZIESIĄT! YEP!",
  },
  [4284] = {
    ["D"] = "Jestem pewna, że je zauważyłeś, $N. Są wszędzie!$B$BCo mam na myśli? Cóż, oczywiście, że kryształy!$B$BKryształy... Są wszechobecne w kraterze. Większość ludzi nie zwraca na nie uwagi, ale mam dziwne przeczucie, że kryją w sobie wielką moc. Od pewnego czasu prowadzę na nich eksperymenty, ale póki co niczego się jeszcze nie dowiedziałam. Cóż, przynajmniej na razie.$B$BSłuchaj, kończą mi się kryształy - może mógłbyś mi ich trochę przynieść?",
    ["O"] = "Zbierz po 7 Power Crystals z każdego koloru: czerwonych, niebieskich, żółtych i zielonych. Przynieś je do J.D. Collie z Marshal\'s Refuge.",
    ["T"] = "Kryształy mocy",
  },
  [4285] = {
    ["D"] = "Do czego mogły służyć? Nie mogę pozbyć się tej myśli z głowy!$B$BDoprowadza mnie to do szału - że te plotki o kryształach są prawdziwe. Może i jestem naiwna, ale zwykle wierzę w to, co mówią mi ludzie.$B$BTak czy inaczej, słyszałam, że jeden z kryształowych pylonów jest dość blisko. Gdzieś na północy... Proszę, $N, znajdź go. Po prostu wiem, że istnieją.",
    ["O"] = "Znajdź Northern Crystal Pylon w Un\'Goro Crater.",
    ["T"] = "Północny pylon",
  },
  [4286] = {
    ["D"] = "Kapitan Winky mówi, że krasnoludy Ciemnego Żelaza z Depths mają najlepszy towar. Co nie, Winky?$B$B<Oralius udaje pirata, najlepiej jak umie.>$B$BARRR, KOLEŚ! ŚWIĘTA PRAWDA!$B$BWidzisz, o co mi chodzi? Musisz się tam dostać i przynieść mi kilka porcji tego towaru.$B$BGIdź tam i daj czadu!",
    ["O"] = "Zbierz 20 Dark Iron Fanny Packs.",
    ["T"] = "Dobry towar",
  },
  [4287] = {
    ["D"] = "Podczas mojego pobytu w tej krainie słyszałam dziwne historie o tajemniczych pylonach, wznoszących się w kniei w kraterze, $N. Przypuszczam, że są dość duże, z widocznymi w środku kryształami.$B$Bhociaż nigdy żadnego nie widziałam, nie mogę oprzeć się myśli, że plotki są prawdziwe - i że pylony muszą mieć coś wspólnego z tymi wszystkimi kryształami, które znajdujemy.$B$BA zatem, może mógłbyś mi pomóc zaspokoić moją ciekawość? Jeden z tych pylonów rzekomo znajduje się we wschodniej części krateru. Jak myślisz - znajdziesz go?",
    ["O"] = "Odszukaj Eastern Crystal Pylon w Un\'Goro Crater.",
    ["T"] = "Wschodni pylon",
  },
  [4288] = {
    ["D"] = "Moje eksperymenty nie dały do tej pory żadnych pozytywnych wyników, $N. Mogę tylko mieć nadzieję, że znajdziesz rozwiązanie, odnajdując jeden z pylonów, o których istnieniu słyszałam.$B$BMoże jeśli umieścimy w nich kombinację kryształów w różnych kolorach... ale za bardzo wybiegam w przyszłość. Wpierw je znajdźmy!$B$B$N, przeszukaj zachodnią część krateru; podobno znajduje się tam pylon.",
    ["O"] = "Odszukaj Western Crystal Pylon.",
    ["T"] = "Zachodni pylon",
  },
  [4289] = {
    ["D"] = "W tym kraterze żyje wiele dziwnych stworzeń — wydają się być szlachetniejszymi odmianami bestii zamieszkujących moje rodzime okolice i inne miejsca. Nie potrafię tego wyjaśnić, ale to miejsce emanuje mocą Matki Ziemi. Oddaję jej hołd za każdym razem, gdy tropię jedno z jej pięknych stworzeń po niecce krateru.$B$BJeżeli ty też pragniesz poczuć oświecenie towarzyszące temu działaniu, udaj się na północ. Tam znajdziesz wielkie małpy, stanowiące sprawdzian dla siły każdego śmiertelnika. Przynieś mi ich skóry... okaż swoją siłę.",
    ["O"] = "Przynieś 2 Un\'Goro Gorilla Pelts, 2 Un\'Goro Stomper Pelts i 2 Un\'Goro Thunderer Pelts do Torwy Pathfindera przy wejściu do Un\'Goro Crater.",
    ["T"] = "Małpy z Un\'Goro",
  },
  [4290] = {
    ["D"] = "Kiedyś, dość dawno temu, mój brat wyciął kawałek mięsa z ofiary Lar\'korwiego. Nie wiedział, że bestia obserwuje go z lasu. Podążała za moim bratem całymi dniami, zabijając wszystko, czego ten dotknął. W końcu przerażony brat postanowił opuścić krater i o niej zapomnieć.$B$BLar\'korwi zabił go niedaleko stąd.$B$BJeżeli chcesz sprowokować Lar\'korwiego, znajdź jego ostatnią ofiarę i wytnij z niej trochę mięsa.$B$BPotem wróć do mnie.",
    ["O"] = "Znajdź truchło najnowszej ofiary Lar\'korwiego i zabierz z niego Piece of Threshadon Carcass, po czym wróć do Torwy Pathfindera w Un\'Goro Crater.",
    ["T"] = "Pożywienie Lar\'korwiego",
  },
  [4291] = {
    ["D"] = "Jestem zaskoczony, że jeszcze się za ciebie nie zabrał, $N. Ale wszystko w porządku, gdyż mam plan, jak zwabić go do nas.$B$BJako dominujący samiec Lar\'korwi ma prawo spółkować z każdą samicą, jaką wybierze — a wybiera ich wiele. Na zachód stąd znajdziesz liczne jaja rawazaurów. Zbliżając się do nich, spowodujesz atak którejś z matek. Samice wydzielają ohydny zapach z gruczołów zapachowych na głowach, informujący samców, że są płodne. Przynieś mi jeden z tych gruczołów.",
    ["O"] = "Przynieś 2 Ravasaur Pheromone Glands do Torwy Pathfindera nieopodal wejścia do Un\'Goro Crater.",
    ["T"] = "Zapach Lar\'korwiego",
  },
  [4292] = {
    ["D"] = "To będzie najtrudniejsza część, ponieważ plan jest skomplikowany. Na północ stąd znajdziesz mały szlak wiodący w góry. Właśnie tam widziałem Lar\'korwiego po raz ostatni. Kiedy ujrzysz kości wielkich stworów, które niegdyś przemierzały ten teren, będziesz wiedział, że dotarłeś na miejsce. Zabierz znalezione mięso i złóż je tam. Następnie natrzyj je miksturą, którą przygotowałem. Jeśli ich połączone zapachy nie sprowadzą do ciebie Lar\'korwiego, to nie wiem, co mogłoby pomóc.",
    ["O"] = "Używając zawartości Torwa\'s Pouch, przywołaj Lar\'korwiego i pokonaj go. Następnie zanieś Lar\'korwi\'s Head Torwie Pathfinderowi nieopodal wejścia do Un\'Goro Crater.",
    ["T"] = "Przynęta na Lar\'korwiego",
  },
  [4293] = {
    ["D"] = "Felwood to las daleko na północ od Barrens, dalej nawet niż Ashenvale. Tam, wokół stawów pobłogosławionych dotykiem skażenia, znajdziesz szlamy. Plaga zdziesiątkowała ten obszar atakami infernali i magią demonów — prawdopodobnie wtedy szlamy wyłoniły się z ziemi.$B$BPobierz próbki ze szlamów z Felwood, a potem użyjemy stojącego obok sprzętu badawczego do stworzenia grupy kontrolnej do naszych testów na innych próbkach, które pozyskasz.",
    ["O"] = "Zbierz Felwood Slime Samples z różnych szlamów z Felwood. Następnie, używając Testing Equipment obok chemika Fuely\'ego w Undercity, oceń, która z próbek jest najbardziej skażona. Przynieś chemikowi Fuely\'emu 5 Corrupted Felwood Samples.",
    ["T"] = "Próbka szlamu...",
  },
  [4294] = {
    ["D"] = "$gSłyszałeś:Słyszałaś; o Kraterze Un\'Goro, $N? Leży nieopodal pustyni Tanaris. To zdumiewające miejsce: porośnięte bujną roślinnością i tętniące zwierzęcym życiem.$B$BMusisz się tam udać. Doszły mnie słuchy, że to miejsce nietknięte przez wpływy z zewnątrz. Odkrywcy dopiero zaczynają poznawać jego sekrety.$B$BChciałbym poddać testom tamtejsze szlamy. Jeśli to prawda i rzeczywiście nie są skażone, chciałbym dowiedzieć się, jak takie stworzenia wyewoluowały.",
    ["O"] = "Zbierz Un\'Goro Slime Samples z różnych szlamów z Un\'Goro Crater. Następnie, używając Testing Equipment obok chemika Fuely\'ego w Undercity, oceń, która z próbek jest najczystsza. Przynieś chemikowi Fuely\'emu 5 Pure Un\'Goro Samples.",
    ["T"] = "... i porcja śluzu",
  },
  [4295] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Ciemne piwo Rocknota",
  },
  [4296] = {
    ["D"] = "Przybyłem do Burning Steppes, śladem legendy o Siedmiu. Byli oni krasnoludami o wielkiej mądrości i sile, a jeśli posiadasz te dwie cechy, to z pewnością w ślad za nimi pojawi się bogactwo.$B$BTego właśnie pragnę. Bogactwa!$B$BJeśli dowiemy się czegoś więcej o Siedmiu, może razem się wzbogacimy. Podobno gdzieś ruinach Thaurissanu znajduje się Tablica Siedmiu. Zawiera ona wiedzę starożytnych krasnoludów. Znajdź tę tablicę, przepisz jej zawartość i przynieś mi ten zapis. Razem zagłębimy się w jej sekrety!",
    ["O"] = "Zdobądź Tablet Transcript.",
    ["T"] = "Tablica Siedmiu",
  },
  [4297] = {
    ["D"] = "Skrzty śmigacze są wszystkożerne — co oznacza, że jedzą mięso i rośliny. Jeżeli z tego twojego jaja coś się wykluje, lepiej jeśli będziemy na to przygotowani. Wierz mi lub nie, dobrym pokarmem dla tych małych są grube i soczyste kawałki schabu. Nigdy nie dowiedziałem się dlaczego tak jest, lecz ma to coś wspólnego z planami Elune odnośnie elfów... może skrzatosmoki miały być ich obrońcami, nie wiem.$B$BZaopiekuję się jajkiem, a Ty może przynieś mi kilka porcji schabu ze Srebrnogrzywego Tropiciela, żeby młode miało co jeść, gdy się wykluje.",
    ["O"] = "Przynieś Angarowi Beastamerowi z Hinterlands 5 Silvermane Stalker Flanks.",
    ["T"] = "Pokarm dla dziecka",
  },
  [4298] = {
    ["D"] = "Oj, wygląda na bliższe wyklucia się, niż myślałem...",
    ["O"] = "Porozmawiaj z Agnarem Beastamerem z Hinterlands.",
    ["T"] = "Zostajesz rodzicem",
  },
  [4299] = {
    ["D"] = "Find the Tomb of the Seven, and place this PX83-Enigmatron there.  ",
    ["O"] = "Place the PX83-Enigmatron in the Tomb of the Seven, then return to Maxwort Uberglint.",
    ["T"] = "<NYI> <TXT>The Tomb of the Seven",
  },
  [4300] = {
    ["D"] = "Hmm, jak tak sobie o tym myślę, może jest coś, co $gmógłbyś:mogłabyś; zrobić dla Dłoni. Tak, Jes\'rimon z pewnością mógłby skorzystać z twojej pomocy.$B$BW Kraterze Un\'Goro mieszkają jaszczury z zabójczymi szponami. Czasem niektóre z nich mają białe szpony, zamiast czarnych niczym śmierć. Dłoń ma... klientów... którym podoba się wykonana z nich broń. Przynieś mi dużo białych szponów, a sporo ci za nie zapłacę. Uwiń się z tym szybko, a może pomogę ci w inny sposób.",
    ["O"] = "Przynieś 8 White Ravasaur Claws do Jes\'rimona z Orgrimmaru.",
    ["T"] = "Kościana broń",
  },
  [4301] = {
    ["D"] = "Kiedy zwiedzałeś Un\'Goro, widziałem kilka rzeczy, które mogłyby zainteresować tak potężnego łowcę, jak ty. Jedną z nich była ogromna małpa, żyjąca na północy, pośród innych goryli. Byłeś już w tej jaskini, lecz nie mam pewności, czy tym razem uda ci się wyjść stamtąd o własnych siłach, o ile oczywiście przyjmiesz moje zadanie.$B$BNazywam go U\'cha i jest on - tego możesz być pewien - jednym z najsilniejszych synów Matki Ziemi. Pokonaj U\'chę i przynieś mi jego skórę. Dokonaj tego, a będę bronić twego prawa do miana wielkiego łowcy.",
    ["O"] = "Przynieś Skórę U\'chy do Torwy Pathfindera u wejścia do Un\'Goro Crater.",
    ["T"] = "Potężny U\'cha",
  },
  [4321] = {
    ["D"] = "Informacje, które dałeś mi o pylonach, są bardzo interesujące...$B$BDaj mi chwilkę, abym wykonał pewne obliczenia, $N. Pogadaj ze mną za moment, a będę w stanie udzielić Ci odpowiedzi, której szukaliśmy.",
    ["O"] = "Porozmawiaj za moment z J.D. Collie.",
    ["T"] = "Making Sense of It",
  },
  [4322] = {
    ["D"] = "Musimy się stąd wydostać, $N. Pomóż mi odzyskać mój ekwipunek ze składu i uwolnić moich przyjaciół. Jeśli uda nam się opuścić to miejsce, musisz dotrzeć do Morgan\'s Vigil i porozmawiać z Marshalem Maxwellem. Wyda ci dalsze instrukcje.",
    ["O"] = "Pomóż Komendantowi Windsorowi odzyskać ekwipunek i uwolnić jego przyjaciół. Jeśli ci się to uda, wróć do Komendanta Maxwella.",
    ["T"] = "Wyrwij murom zęby krat!",
  },
  [4323] = {
    ["D"] = "I want some Hyena Pelts, and only the best will do!  Get me spotted Hyena pelts and I\'ll give you phat lewtz, yo.",
    ["O"] = "Bring 7 Spotted Hyena Pelts to TESTTAUREN at Freewind Post.",
    ["T"] = "<NYI> <TXT> Get those Hyenas!!!",
  },
  [4324] = {
    ["D"] = "Choć z mojego młodszego brata Ribbly\'ego przez całe życie nie było żadnego pożytku, chyba wreszcie okazało się, że jednak jest coś wart! Lecz... aby wykorzystać jego nowoodkrytą wartość, potrzebujemy twojej pomocy.$B$BMoja siostra Yuka szuka go od tygodni i trafiła za nim aż do Burning Steppes. Wysłała do mnie prośbę o najęcie jakiejś pomocy.$B$BWięc co ty na to? Chcesz pomóc? Jeśli tak, porozmawiaj z moją siostrą. Znajdziesz ją w głębi Flame Crest - jaskini na północny zachód od Dreadmaul Rock.",
    ["O"] = "Porozmawiaj z Yuką Screwspigot z Burning Steppes.",
    ["T"] = "Yuka Screwspigot",
  },
  [4341] = {
    ["D"] = "Odwiedziłeś dymiące ruiny Thaurissanu? Spotkałeś tam może żałosnego drania zwącego się Kharanem Mighthammerem? Krasnoluda, który miał się niby opiekować moją małą dziewczynką!$B$B<Król szlocha.>$B$BA teraz jej nie ma, $N!$B$BMoi ludzie przewrócili Stepy do góry nogami. Jedyne, co odkryli odnośnie miejsca pobytu mojej córki, jest to, że może przebywać w Czeluściach. Z tego co wiem, może być już martwa!$B$BPonoć Kharan jest tam uwięziony... znajdź go! Żądam odpowiedzi!",
    ["O"] = "Udaj się do Blackrock Depths i odszukaj Kharana Mighthammera.$B$BKról wspominał, że Kharan jest tam przetrzymywany jako więzień - może powinieneś poszukać więzienia?",
    ["T"] = "Kharan Mighthammer",
  },
  [4342] = {
    ["D"] = "Proszę, wysłuchaj mnie, zanim wydasz wyrok!",
    ["O"] = "Wysłuchaj historii Kharana Mighthammera.",
    ["T"] = "Opowieść Kharana",
  },
  [4343] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Chore wiatrokwiecie",
  },
  [4361] = {
    ["D"] = "Musisz dostarczyć te informacje Królowi Magniemu, $N. On będzie wiedział, co robić!",
    ["O"] = "Wróć do Ironforge i przekaż złe wieści Królowi Magniemu Bronzebeardowi.",
    ["T"] = "Doręczyciel złych wieści",
  },
  [4362] = {
    ["D"] = "Wygląda na to, że mój stary nieprzyjaciel, Dagran Thaurissan, ma na swej łasce mnie i królestwo Ironforge.$B$BMożesz być moją ostatnią nadzieją, $N. Musisz uratować moją ukochaną córkę, Moirę!$B$BJest tylko jeden sposób dający pewność złamania czaru, który Thaurissan rzucił na Moirę: zabić go.$B$BI $N, nie rób jej krzywdy! Pamiętaj, że jest pod całkowitą kontrolą Thaurissana! Jej czyny lub słowa będą skutkiem jego złego czaru!",
    ["O"] = "Wróć do Blackrock Depths i ocal Księżniczkę Moirę Bronzebeard ze szponów złego Imperatora Dagrana Thaurissana.",
    ["T"] = "Los królestwa",
  },
  [4363] = {
    ["D"] = "Thaurissan był wspaniałym i zacnym krasnoludem. Zrujnowałeś moje życie i życie mojego nienarodzonego dziecka!$B$B<Przypuszczasz, że Księżniczka Bronzebeard może jeszcze odczuwać resztki wpływu zaklęcia Imperatora.>$B$BWróć do Ironforge i powiedz mojemu ojcu, że następcą tronu Królestwa Ironforge będzie krasnolud Dark Iron.$B$BTak będzie, czy się z tym zgadza, czy nie.",
    ["O"] = "Wróć do Ironforge i porozmawiaj z Królem Magnim Bronzebeardem.",
    ["T"] = "Niespodzianka księżniczki",
  },
  [4381] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Kryształ odnowy",
  },
  [4382] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Kryształ mocy",
  },
  [4383] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Kryształ osłony",
  },
  [4384] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Kryształ podatności",
  },
  [4385] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Kryształowy ładunek",
  },
  [4386] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Kryształowy ładunek",
  },
  [4401] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Chory śpiewokwiat",
  },
  [4402] = {
    ["D"] = "Na pewno zgrzejesz się tutaj w Dolinie Prób.$B$B<Galgar ociera brew.>$B$BJeśli tylko miałbym trochę owoców kaktusa, mógłbym zrobić moją sławną kaktusowa niespodziankę! Nic nie schłodzi cię bardziej niż odrobina pysznego owocu.$B$BPowiem ci coś, $N. Jeśli przyniesiesz mi dziesięć owoców kaktusa, zrobię dla ciebie kilka porcji kaktusowej niespodzianki, abyś $gmógł:mogła; zabrać je na swoje przygody. Jeśli jesteś $gzainteresowany:zainteresowana;, znajdziesz owoce kaktusa rosnące w okolicy nieopodal kaktusów.",
    ["O"] = "Przynieś Galgarowi 10 owoców kaktusa. Pamiętaj, że $gpowinieneś:powinnaś; znaleźć je nieopodal kaktusów.",
    ["T"] = "Kaktusowa niespodzianka Galgara",
  },
  [4403] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Chore wiatrokwiecie",
  },
  [4421] = {
    ["D"] = "Niewielu szuka tutaj przygód... Zaraza w Felwood jest powszechna.$B$BJako członek Emerald Circle pragnę wyleczyć tę krainę z plugastwa, ale są również tacy, którzy pragną, by kraina była coraz większą zgnilizną.$B$BMówię o Jadefire Satyrs, którzy zamieszkują na północny zachód stąd, w Ruins of Constellas. Prowadzeni przez okrutnego satyra Xavathrasa, zarażają wszystkie napotkane stworzenia.$B$BMusimy obronić tę ziemię, ona była kiedyś nasza. Pokonaj Xavathrasa i zniszcz jego sługi.",
    ["O"] = "Zabij 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues i Xavathrasa. Wróć do Eridan Bluewind w Felwood, gdy wykonasz zadanie.",
    ["T"] = "Zaraza w Jadefire",
  },
  [4441] = {
    ["D"] = "Flet, który znalazłeś był wyrzeźbiony ze starożytnych obrońców, Entów, którzy wiernie chronili swych sojuszników nocne elfy.$B$BSatyrowie zdołali spaczyć wszystko czego tknęli, nie pomijając starożytnych, którzy z Felwood uczynili swój dom. Przy użyciu Fel, duchy starożytnych zostały związane i torturowane, i nigdy nie zostały uwolnione. Ten artefakt, który znalazłeś, jest bez wątpienia zaklęty.$B$BMusimy spróbować oczyścić flet, $N. Zdobądź błogosławioną wodę ze Świątyni Księżyca w Darnassus.",
    ["O"] = "Wyrusz do Darnassus i użyj Eridan\'s Vial, by zebrać Vial of Blessed Water z Temple of the Moon. Wróć do Eridan\'a z pełną fiolką.",
    ["T"] = "Felbound Ancients",
  },
  [4442] = {
    ["D"] = "Z pomocą wody Elune spróbuję oczyścić flet. Trzeba zakończyć te cierpienia...$B$BNiech Elune prowadzi mą rękę i serce.$B$BZagadaj do mnie ponownie za chwilę.",
    ["O"] = "Porozmawiaj za moment z Eridanem.",
    ["T"] = "Oczyszczony!",
  },
  [4443] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Chory korzeń biczownika",
  },
  [4444] = {
    ["D"] = "",
