  [5891] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Balsam poprzez odzysk",
  },
  [5892] = {
    ["D"] = "Zanim zaczęły się walki, przechowywaliśmy zaopatrzenie dla Dun Baldar w kopalni Irondeep. Dopóki mieliśmy wolnych żołnierzy do jej pilnowania, troggi, które wyszły tam na powierzchnię, nie stanowiły problemu, ale teraz, gdy walczymy z Hordą, nie możemy utrzymać kontroli nad Irondeep.$B$BPotrzebujemy tych zapasów z Irondeep, $N. Wejdź do kopalni i przynieś mi ich jak najwięcej.",
    ["O"] = "Dostarcz 10 skrzynek Irondeep Supplies do Alliance Quartermastera w Dun Baldar.",
    ["T"] = "Dostawy z Irondeep",
  },
  [5893] = {
    ["D"] = "Kopalnia Coldtooth na północ stąd była idealnym miejscem do składowania zaopatrzenia, ale teraz, gdy walki z Stormpikes nabierają tempa, nie zawsze mamy wojowników na zbyciu, by siedzieli w kopalni i jej pilnowali. Dlatego kontrola nad kopalnią często przechodzi w ręce Przymierza albo mieszkańców podziemi...$B$BAle wciąż potrzebujemy naszych zapasów, Azhin! Idź do Coldtooth i przynieś mi ich jak najwięcej. I uważaj na wrogów po drodze; w tym miejscu szale zwycięstwa szybko przechylają się z jednej strony na drugą...",
    ["O"] = "Dostarcz 10 skrzynek Coldtooth Supplies do Horde Quatermastera z Frostwolf Keep.",
    ["T"] = "Dostawy z &quot;Zimnego Zęba&quot;",
  },
  [5901] = {
    ["D"] = "A więc by wywołać nieco cierpienia i niesnasek w Szkarłatnej Krucjacie, chcę odebrać im ich cenny tartak. Jestem pewna, że strata tego źródła zasobów przysporzy im wiele kłopotów w budowaniu umocnień i odbudowie miasta na ich własne potrzeby. Pomożesz mi, $N?$B$BZacznij od zabrania tego słoika do Wschodnich Ziem Plagi. Napełnij go termitami, które znajdziesz w kopcach na terenie lasu. Wróć, gdy będziesz $gmiał:miała; ich dość.",
    ["O"] = "Użyj Empty Termite Jar przy Termite Mounds w Eastern Plaguelands. Gdy zbierzesz 100 Plagueland Termites, wróć do Mickey Levine, w Bulwark, Tirisfal Glades.",
    ["T"] = "A niech was plaga...",
  },
  [5902] = {
    ["D"] = "Teraz, gdy mamy termity, zanieś tę wzmocnioną beczułkę do Tartaku Northridge, na południe od Hearthglen - znajdziesz go na zachód od drogi wiodącej do miasta.$B$BGdy już tam dotrzesz, postaw beczułkę w środku tartaku. Znajdź odpowiednie miejsce; gdzieś wysoko, na przykład na jakiejś skrzyni i otwórz ją. $B$BGdy to uczynisz, reszta zrobi się sama. Po prostu wróć do mnie, a otrzymasz nagrodę za pomoc.",
    ["O"] = "Znajdź w środku Northridge Lumber Mill w Western Plaguelands odpowiednie miejsce do podłożenia Barrel of Plagueland Termites.",
    ["T"] = "A niech was plaga...",
  },
  [5903] = {
    ["D"] = "Wiele razy NPC_GENDER(próbowałem;próbowałam) przepędzić Szkarłatną Krucjatę przy użyciu siły, ale bezskutecznie. Więc, dla odmiany, NPC_GENDER(postanowiłem;postanowiłam) nieco utrudnić im życie.$B$BJeśli jesteś $gzainteresowany:zainteresowana;, chcę zaatakować tartak przy pomocy najokropniejszego gatunku termitów, na jaki kiedykolwiek natrafiono.$B$BW Plaguewood, obok niegdyś wspaniałego Stratholme, znajdziesz gatunek, który przetrwał obie plagi naraz. Odnajdź ich kopce i napełnij nimi ten słoik, byśmy mogli je przygotować do szturmu na Krucjatę.",
    ["O"] = "Użyj Empty Termite Jar przy Termite Mounds w Eastern Plaguelands. Gdy zbierzesz x 100 Plagueland Termites, wróć do Nathaniela Dumaha, w Chillwind Camp, Western Plaguelands.",
    ["T"] = "A niech was plaga...",
  },
  [5904] = {
    ["D"] = "Teraz, gdy mamy termity, zanieś tę wzmocnioną beczułkę do Northridge Lumber Mill, na południe od Hearthglen - znajdziesz go na zachód od prowadzącej do miasta drogi.$B$BGdy już tam dotrzesz, postaw beczułkę w centrum tartaku. Znajdź odpowiednie miejsce, na przykład na jakiejś skrzyni i otwórz ją. Termity zrobią swoje i tartak nie zda się Krucjacie już na nic.",
    ["O"] = "Znajdź miejsce w centrum Northridge Lumber Mill w Western Plaguelands, odpowiednie do podłożenia Barrel of Plagueland Termites.",
    ["T"] = "A niech was plaga...",
  },
  [5921] = {
    ["D"] = "Wszyscy druidzi są mile widziani na świętych ziemiach Moonglade, bez względu na napięcia w Kręgu Cenariusa, panujące obecnie pomiędzy Arcydruidem Straghelmem a Opiekunem Remulosem - strażnikiem Moonglade. Teraz, gdy uczysz się ścieżek Pazura, nauczę cię zaklęcia, które cię tam przetransportuje. Używaj go, gdy tylko będziesz $gpotrzebował:potrzebowała; mądrości Moonglade lub pocieszenia.$B$BTwoją pierwszą lekcją będzie podróż do Moonglade i rozmowa z Dendrite\'em Starblaze z Nighthaven o ścieżce, po której teraz kroczysz. Powodzenia, $gmłody druidzie:młoda druidko;.",
    ["O"] = "Użyj zaklęcia \"Teleport do Moonglade\", by dostać się do tej krainy. Gdy tam przybędziesz, porozmawiaj z Dendrite\'em Starblaze\'em w Nighthaven.",
    ["T"] = "Moonglade",
  },
  [5922] = {
    ["D"] = "Wszyscy druidzi są mile widziani na świętych ziemiach Moonglade, zarówno taureni jak i nocne elfy. Opiekun Remulos - strażnik Moonglade - trzyma pieczę nad wszystkimi druidami, którzy spoczywają tam w letargu. Teraz, gdy uczysz się ścieżek Pazura, nauczę cię zaklęcia, które cię tam przetransportuje. Używaj go, gdy tylko będziesz $gpotrzebował:potrzebowała; mądrości Moonglade lub pocieszenia.$B$BTwoją pierwszą lekcją będzie podróż do Moonglade i rozmowa z Dendrite\'em Starblaze z Nighthaven o ścieżce, którą teraz kroczysz. Powodzenia, $gmłody druidzie:młoda druidko;.",
    ["O"] = "Użyj zaklęcia \"Teleport do Moonglade\", by dostać się do tej krainy. Gdy tam przybędziesz, porozmawiaj z Dendrite\'em Starblaze\'em w Nighthaven.",
    ["T"] = "Moonglade",
  },
  [5923] = {
    ["D"] = "Wybacz, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Mathrengyl Bearwalker chce z tobą pomówić. Wygląda na to, że twoje szkolenie na druida przejdzie teraz w kolejną fazę, pod zwierzchnictwo Mathengryla. Jest on osobistym pomocnikiem samego Arcydruida, a zarazem najmędrszym i najdostojniejszym druidem na Teldrassilu.$B$BZnajdziesz go w Enklawie Cenariusa w Darnassus, na drugim piętrze drzewa Fandrala Staghelma.",
    ["O"] = "Porozmawiaj z Mathrengylem Bearwalkerem w Cenarion Enclave, w Darnassus.",
    ["T"] = "W odpowiedzi na zew",
  },
  [5924] = {
    ["D"] = "Wybacz, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Mathrengyl Bearwalker chce z tobą pomówić. Wygląda na to, że twoje szkolenie na druida przejdzie teraz w kolejną fazę, pod zwierzchnictwo Mathengryla. Jest on osobistym pomocnikiem samego Arcydruida, a zarazem najmędrszym i najdostojniejszym druidem na Teldrassilu.$B$BZnajdziesz go w Enklawie Cenariusa w Darnassus, na drugim piętrze drzewa Fandrala Staghelma.",
    ["O"] = "Porozmawiaj z Mathrengylem Bearwalkerem w Cenarion Enclave, w Darnassus.",
    ["T"] = "W odpowiedzi na zew",
  },
  [5925] = {
    ["D"] = "Wybacz, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Mathrengyl Bearwalker chce z tobą pomówić. Wygląda na to, że twoje szkolenie na druida przejdzie teraz w kolejną fazę, pod zwierzchnictwo Mathengryla. Jest on osobistym pomocnikiem samego Arcydruida, a zarazem najmędrszym i najdostojniejszym druidem na Teldrassilu.$B$BZnajdziesz go w Enklawie Cenariusa w Darnassus, na drugim piętrze drzewa Fandrala Staghelma.",
    ["O"] = "Porozmawiaj z Mathrengylem Bearwalkerem w Cenarion Enclave, w Darnassus.",
    ["T"] = "W odpowiedzi na zew",
  },
  [5926] = {
    ["D"] = "Wybacz, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Turan Runetotem chce z tobą pomówić. Wygląda na to, że twoje szkolenie na druida przejdzie teraz w kolejną fazę, pod jego zwierzchnictwo. Turak jest jednym z pomocników samego Arcydruida; jest znany z mądrości i cierpliwości i na pewno dobrze cię wyszkoli.$B$BZnajdziesz go w Thunder Bluff, wewnątrz głównego namiotu Kręgu Cenarionu na Wzniesieniu Starszych.",
    ["O"] = "Porozmawiaj z Turakiem Runetotemem w Elder Rise miasta Thunder Bluff.",
    ["T"] = "W odpowiedzi na zew",
  },
  [5927] = {
    ["D"] = "Wybacz, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Turan Runetotem chce z tobą pomówić. Wygląda na to, że twoje szkolenie na druida przejdzie teraz w kolejną fazę, pod jego zwierzchnictwo. Turak jest jednym z pomocników samego Arcydruida; jest znany z mądrości i cierpliwości i na pewno dobrze cię wyszkoli.$B$BZnajdziesz go w Thunder Bluff, wewnątrz głównego namiotu Kręgu Cenarionu, na Wzniesieniu Starszych.",
    ["O"] = "Porozmawiaj z Turakiem Runetotemem w Elder Rise miasta Thunder Bluff.",
    ["T"] = "W odpowiedzi na zew",
  },
  [5928] = {
    ["D"] = "Wybacz, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Turan Runetotem chce z tobą pomówić. Wygląda na to, że twoje szkolenie na druida przejdzie teraz w kolejną fazę, pod jego zwierzchnictwo. Turak jest jednym z pomocników samego Arcydruida; jest znany z mądrości i cierpliwości i na pewno dobrze cię wyszkoli.$B$BZnajdziesz go w Thunder Bluff, wewnątrz głównego namiotu Kręgu Cenariona na Wzniesieniu Starszych.",
    ["O"] = "Porozmawiaj z Turakiem Runetotemem w Elder Rise miasta Thunder Bluff.",
    ["T"] = "W odpowiedzi na zew",
  },
  [5929] = {
    ["D"] = "Północno-zachodnią część Moonglade zamieszkuje mądra i szlachetna istota, którą zwiemy Wielki Duch Niedźwiedzia. Służył on wszystkim druidom jako nauczyciel i mentor w pierwszym prawdziwym zrozumieniu natury niedźwiedzia. Dla każdego z druidów nadchodzi chwila, w której poszukuje on jego mądrości, a i ty nie jesteś wyjątkiem.$B$BUdaj się teraz do Wielkiego Ducha Niedźwiedzia i naucz się tego, co ma ci do przekazania. Kiedy już przekaże ci swoją wiedzę, wróć tu do mnie, do Nighthaven. Przekonamy się, co naprawdę $gwyniosłeś:wyniosłaś; z lekcji, której ci udzielił.",
    ["O"] = "Odnajdź Great Bear Spirit w północno-zachodniej części Moonglade i dowiedz się, co ma ci do powiedzenia o naturze niedźwiedzia. Kiedy skończysz, wróć do Dendrite\'a Starblaze\'a z Nighthaven w Moonglade.",
    ["T"] = "Wielki Duch Niedźwiedź",
  },
  [5930] = {
    ["D"] = "Północno-zachodnią część Moonglade zamieszkuje mądra i szlachetna istota, którą zwiemy Wielkim Duchem Niedźwiedziem. Służył on wszystkim druidom jako nauczyciel i mentor w pierwszym prawdziwym zrozumieniu natury niedźwiedzia. Dla każdego z druidów nadchodzi chwila, w której poszukuje on jego mądrości, a i ty nie jesteś wyjątkiem.$B$BUdaj się teraz do Wielkiego Ducha Niedźwiedzia i naucz się tego, co ma ci do przekazania. Kiedy już przekaże ci swoją wiedzę, wróć tu do mnie, do Nighthaven. Przekonamy się, co naprawdę $gwyniosłeś:wyniosłaś; z lekcji, której ci udzielił.",
    ["O"] = "Odnajdź Great Bear Spirit w północno-zachodniej części Moonglade Moonglade i dowiedz się, co ma ci do powiedzenia o naturze niedźwiedzia. Kiedy skończysz, wróć do Dendrite’a Starblaze z Nighthaven w Moonglade.",
    ["T"] = "Wielki Duch Niedźwiedź",
  },
  [5931] = {
    ["D"] = "Nadszedł czas, by nasze drogi się rozeszły, $gmłody:młoda; $R7, gdyż postępy w twojej nauce prowadzą cię z powrotem do tego, który cię do mnie przysłał. Mathrengyl Bearwalker zaiste kroczy w równowadze z naturą, nawet zamieszkując niebezpiecznie blisko miejsca, gdzie została ona zachwiana. Wysłuchaj jego wskazówek, a wkrótce ukończysz swe pierwsze szkolenie w roli obrońcy równowagi.$B$BIdź już, $gmłody:młoda; $R7. Wkrótce znów się spotkamy.",
    ["O"] = "Wróć do Darnassus i pomów z Mathrengylem Bearwalkerem z Cenarion Enclave.",
    ["T"] = "Powrót do Darnassus",
  },
  [5932] = {
    ["D"] = "Nadszedł czas, by nasze drogi się rozeszły, $gmłody:młoda; $R7, gdyż postępy w twojej nauce prowadzą cię z powrotem do tego, który cię do mnie przysłał. Choć taurenów uważa się za nowicjuszy w naukach Cenariusa, Turak Runetotem niesie równowagę ścieżkom natury. Wysłuchaj jego wskazówek, a wkrótce ukończysz swe pierwsze szkolenie w roli obrońcy równowagi.$B$BIdź już, $gmłody:młoda; $R7. Wkrótce znów się spotkamy.",
    ["O"] = "Wróć do Thunder Bluff i porozmawiaj z Turakiem Runetotemem w Elder Rise.",
    ["T"] = "Powrót do Thunder Bluff",
  },
  [5941] = {
    ["D"] = "Zebrałeś wiele pamiątek z bitwy o Darrowshire. Za każdym razem, gdy przynosiłeś kolejną, w mym sercu na nowo budziła się tęsknota za moją wioską... pragnąłem uchronić ją od losu, który przypadł jej w udziale.$B$BSądziłem, że już wszystko stracone, ale Chromie, ta dziwna gnomka z Andorhalu, mówi, że jest szansa. Mówi, że możesz uratować Darrowshire!$B$BKazała mi zebrać te pozostałości i powiedzieć ci, byś przyniósł je do niej. Mówiła też, że czeka na ciebie w zrujnowanej karczmie w Andorhalu.",
    ["O"] = "Zanieś Bundle of Relics do Chromie w Andorhal.",
    ["T"] = "Powrót do Chromie",
  },
  [5942] = {
    ["D"] = "Tata kazał mi dać ci ten klucz. Powiedział, że otwiera skrzynię za domem.$B$BChciał jeszcze, żebym ci podziękowała. Zrobiłeś coś dla niego? Mówiłeś mu, że znalazłeś moją lalkę?$B$BDobrze, tu jest klucz. I dziękuję, $N. Bardzo dziękuję! Jesteś bardzo miły!",
    ["O"] = "Zanieś Klucz Josepha do Skrzyni Josepha.",
    ["T"] = "Ukryte skarby",
  },
  [5943] = {
    ["D"] = "Wyglądasz na $gzdolnego:zdolną; $R. Może szukasz okazji, żeby trochę zarobić? Cork i ja zorganizowaliśmy tę karawanę, żeby zarobić krocie, ale nie mieliśmy pojęcia, przez co trzeba przejść, żeby wyjść na swoje!$B$BTam dalej leży Sabat Mannoroca... zazwyczaj demony nas ignorują, ale tym razem coś śmiertelnie przeraziło kodo. Zapłacę ci za przeprowadzenie karawany przez teren Sabatu. Jak już bezpiecznie przezeń przebrniemy, odbierzesz nagrodę od naszego wspólnika, Smeeda z obozu Scrabblescrewa.",
    ["O"] = "Przeprowadź Gizelton Caravan przez Mannoroc Coven. By otrzymać zapłatę, porozmawiaj ze Smeedem w Scrabblescrew\'s Camp.",
    ["T"] = "Karawana Gizeltonów",
  },
  [5944] = {
    ["D"] = "Przez tyle czasu byłem marionetką w rękach Wielkiego Krzyżowca. Jaki sens było walczyć przeciwko temu, czym stała się sama Scarlet Crusade? Minęły dekady, lecz wspomnienia mojego ojca - te drogocenne wspomnienia, to one zachowały mnie przy życiu.$B$BŚnię sny, nieznajomy. W tych snach mój ojciec jest ze mną. Z dumą stoi u mego boku, gdy staję się członkiem Zakonu. Walczymy z legionami Plagi, ramię przy ramieniu. Jesteśmy dumą Przymierza i Lordaeronu.$B$BChcę czegoś więcej, niż snów.$B$BZabierz mnie do niego.",
    ["O"] = "Pomóż Taelanowi Fordringowi wydostać się z Hearthglen.",
    ["T"] = "W snach",
  },
  [5961] = {
    ["D"] = "Cieszy mnie wielce, że zahartowani w bitwie wojownicy przyłączają się do naszej sprawy. Z każdym dniem nasze szeregi rosną w siłę. Może jesteś $ggotowy:gotowa;, by się wykazać?$B$BJednym z pierwszych moich czempionów był Nathanos, znany obecnie jako Blightcaller - Herold Plagi. Niewielu w naszych szeregach wykazuje większe oddanie i entuzjazm.$B$BOdszukaj go na Wschodnich Ziemiach Plagi. Zamieszkuje Marris Stead; od czasu do czasu zapuszcza się na wymarłe pustkowia, mordując wszelkie plugastwo, czy to z Plagi, czy z Przymierza, które stanie mu na drodze.",
    ["O"] = "Porozmawiaj z Nathanosem Blightcallerem w Eastern Plaguelands. Podobno osiedlił się w Marris Stead.",
    ["T"] = "Czempion Królowej Banshee",
  },
  [5981] = {
    ["D"] = "Około czterech tysięcy lat temu Tyrande Whisperwind uratowała królową mroźnych panter przed rozszalałymi olbrzymami. Od tamtej pory mroźne pantery są sojusznikami nocnych elfów.$B$BTe same giganty, które były niegdyś zagrożeniem dla mroźnych panter, można wciąż znaleźć niedaleko stąd. Zwą ich Frostmaul, a zamieszkują one wielką dolinę na południu. $B$BDowiedź swej lojalności względem mroźnych panter; zgładź te olbrzymy w imię królowej mroźnych panter, Shy-Rotam!",
    ["O"] = "Rivern Frostwind chce, byś $gzabił:zabiła; 4 Frostmaul Giants i 4 Frostmaul Preservers.",
    ["T"] = "Rozszalałe olbrzymy",
  },
  [6000] = {
    ["D"] = "$N! I would not have expected to see you in the area were however instructed to hold after you look out.$B$BHighest one time of your training is continued. With the next attendance in Stormwind should you with Gakin clean-look. $B$BIt will expect you.",
    ["O"] = "Announces you to Gakin the Darkbinder in the Magic quarter of Stormwind.",
    ["T"] = "Swearing to Gakin",
  },
  [6001] = {
    ["D"] = "Dokładnie na wschód od Auberdine znajduje się kilka jaskiń księżyczaków. W jednej z nich, najbliższej Auberdine, znajduje się kamień księzyczaków. Strażnik kamienia, Lunaclaw, ujawni się tylko wtedy, jeśli na kamieniu znajdzie się księżycowy pył Cenarionu. Lunaclaw dysponuje siłą, jaką musisz posiąść jako Druid Pazura.$B$B$gZyskałeś:Zyskałaś; prawo do używania księżycowego pyłu Cenarionu, $N... teraz pokaż mi, że $gzasłużyłeś:zasłużyłaś; też na siłę ciała i siłę ducha, których potrzebuje każdy druid!",
    ["O"] = "Użyj Cenarion Moondust na Moonkin Stone w okolicach Auberdine, aby przywołać Lunaclaw. Następnie musisz stawić mu czoła oraz posiąść siłę ducha i ciała, którą dysponuje.$B$BKiedy skończysz, porozmawiaj w Darnassus z Mathrengylem Bearwalkerem.",
    ["T"] = "Ciało i duch",
  },
  [6002] = {
    ["D"] = "Na zachód od Taurajo, w Barrens - na moment nim kraina ta przechodzi w Mulgore - stoi kamień księżyczaków. Księżyczaki to wyjątkowe stworzenia, nie spotykane w tej części kontynentu. Strażnik kamienia, Lunaclaw, ujawni się tylko wtedy, jeśli na kamieniu znajdzie się księżycowy pył Cenarionu. Lunaclaw dysponuje siłą, jaką musisz posiąść jako Druid Pazura.$B$B$gZyskałeś:Zyskałaś; prawo do używania księżycowego pyłu, $N... teraz pokaż mi, że $gzasłużyłeś:zasłużyłaś; też na siłę ciała i siłę ducha, których potrzebuje każdy druid!",
    ["O"] = "Użyj Cenarion Lunardust na Moonkin Stone znajdującym się pomiędzy Mulgore a Barrens, aby przywołać Lunaclaw. Następnie musisz stawić mu czoła oraz posiąść siłę ducha i ciała, którą dysponuje.$B$BKiedy skończysz, porozmawiaj w Thunder Bluff z Turakiem Runetotemem.",
    ["T"] = "Ciało i duch",
  },
  [6004] = {
    ["D"] = "Zostałam wysłana jako zwiadowca, by oszacować i nieco uszczuplić siły obronne Hearthglen. Niektórzy członkowie Przymierza uważają, że to małe miasto ma większe niż tylko historyczne znaczenie. Zastanawianie się co to za znaczenie nie należy do moich obowiązków; tak czy inaczej nie dam rady kontynuować mojej misji, dopóki trochę nie odpocznę.$B$BJeśli zgodzisz się pomóc, szczodrze ci zapłacę. Zacznij na południe stąd, w obozie nieopodal ich małego szańca. Jeśli okażesz się dość silny, może nadasz się do pomocy przy moim głównym zadaniu.",
    ["O"] = "Zabij 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi i 2 Scarlet Knights, po czym wróć do Kirsty Deepshadow w Western Plaguelands.",
    ["T"] = "Niedokończone sprawy",
  },
  [6021] = {
    ["D"] = "Wyobraź sobie, nie dość tych wszystkich problemów na ziemiach Plagi... mamy na głowie jeszcze złodziei! I to nie zwyczajnych złodziei, tylko trolli złodziei.$B$BI to nie zwykłych trolli złodziei, tylko martwych trolli złodziei!$B$BPrzewodzi im wielki, nieżywy troll, zwany Zaeldarr the Outcast; przychodzą tu w nocy i kradną ciała z tego dołu; potem zanoszą je do swej strasznej kryjówki - Undercroft na zachód stąd.$B$BIdź tam i pozbądź się Zaeldarra, $N. Niedobrze mi się robi od jego rozbojów!",
    ["O"] = "Przynieś Zaeldarr\'s Head do Caretakera Alena z Light\'s Hope Chapel.",
    ["T"] = "Zaeldarr Wygnaniec",
  },
  [6022] = {
    ["D"] = "Póki przebywasz na moim podwórku, zabijasz w sposób planowy.$B$BW ramach pierwszego zadania nakarmisz moje psy.$B$BWeź ten moździerz i tłuczek i udaj się do Corin\'s Crossing. Na miejscu znajdziesz spory wybór stworów Plagi. Potrzebuję żywej zgnilizny z ich trucheł. Po zmiażdżeniu w moździerzu pozwól jej osiąść, a stężeje. Tę stężałą zgniliznę masz przynieść tutaj.$B$BI przyjmij do wiadomości, imbecylu, że żywa zgnilizna nieumarłych nie pozostaje \"żywa\" zbyt długo. Musisz zabijać szybko!",
    ["O"] = "Wybierz się do Corin\'s Crossing i wymorduj przedstawicieli Plagi, którzy je teraz zamieszkują. Zbierz 7 porcji Living Rot w mniej niż 10 minut. Użyj Moździerza i Tłuczka, by zmiażdżyć Living Rot i przygotować Coagulated Rot.",
    ["T"] = "Zabijać w sposób planowy",
  },
  [6023] = {
    ["D"] = "Tak naprawdę moim zadaniem było osłabić wysunięte siły Scarlet Crusade, a potem przedostać się do Hearthglen, by ocenić ich liczebność. Wciąż nie jestem w stanie zrobić tego sama, mogłabym więc prosić cię jeszcze raz o pomoc, $N? Z tego, co udało mi się dowiedzieć, zanim mnie odkryli, kręgosłup sił Scarlet Crusade poza miastem stanowią jej dwaj ważni członkowie: Huntsman Radley i Cavalier Durgen. Zabij ich; to nam pozwoli poczynić postępy. Powinni być gdzieś w Hearthglen Pass, przed właściwym miastem.",
    ["O"] = "Zabij Huntsmana Radleya i Cavaliera Durgena, po czym wróć do Kirsty Deepshadow w Western Plaguelands.",
    ["T"] = "Niedokończone sprawy",
  },
  [6024] = {
    ["D"] = "Zabij mnie. Nim będzie za późno.$B$BJestem Hameya. Podczas podróży do Zul\'Mashar wraz z moimi braćmi zjedliśmy jakieś niedobre mięso... i zmieniliśmy się. Jesteśmy zarażeni.$B$BSłyszę słowa lisza, pchające mnie do Zul\'Mashar, bym zaraził więcej moich współplemieńców. Nie mogę się oprzeć, więc piszę ten zwój, zanim moja wola mnie opuści.$B$BZakopałem skrzynię w piachu obok wozu za tą kryptą, ale tylko moim kluczem można ją otworzyć. Mam go przy sobie. Jeśli chcesz moje skarby, znajdź mnie.$B$BZabij mnie. Nim będzie za późno.",
    ["O"] = "Zabij Infiltrator Hameya. Użyj jego klucza na Mound of Dirt za Undercroft.",
    ["T"] = "Prośba Hameyi",
  },
  [6025] = {
    ["D"] = "Co? Naprawdę? Chcesz wiedzieć więcej? Ale przecież już tak wiele dla mnie zrobiłeś, Azerutelialu. Nie mogłabym cię prosić, abyś udał się w moim imieniu do samego Hearthglen.$B$BJesteś pewien Azerutelialu? Hearthglen jest o wiele bardziej niebezpieczny niż przełęcz. Nie mogę zapewnić ci żadnej ochrony, ani nawet informacji dotyczących tego, co możesz spotkać. $B$BCóż, jeśli naprawdę chcesz pomóc, wejdź do miasta i znajdź wysoko położone miejsce, z którego będziesz miał dobry widok na okolicę. Stamtąd będziesz mógł ocenić liczebność wroga. Gdy to zrobisz, wróć tu i opowiedz mi o wszystkim. Bądź ostrożny....",
    ["O"] = "Udaj się do Hearthglen i znajdź wysoki punkt obserwacyjny, z którego będziesz mógł dostrzec miasto i określić siły Scarlet Crusade. Następnie wróć do Kirsty Deepshadow w Western Plaguelands.",
    ["T"] = "Niedokończone sprawy",
  },
  [6026] = {
    ["D"] = "Członkowie Argent Dawn zlecili Smokeyowi, by dokonał dla nich małej demolki. Ale mamusia Smokeya nie wychowała go na głupka. Kiedy złoto uderza o stół, wtedy usługi Smokeya stają się dostępne. To moje motto! $B$BChciałbym odpalić ci część zlecenia, jeśli jesteś gotów trochę pobiegać. Oto układ: ruszam do Plaguewood i oznaczam budynki, które mamy zniszczyć. Ty zbierasz składniki do bomb. Spotykamy się tutaj, gdy ukończysz swoje zadanie. Umowa stoi?",
    ["O"] = "Smokey LaRue chce, abyś zdobył 2 Sztabki Thorium, 1 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs i 8 Unstable Triggers. $B$BAby zdobyć te rzeczy, będziesz musiał znaleźć kowala i inżyniera.",
    ["T"] = "To ogromna prośba",
  },
  [6027] = {
    ["D"] = "$N, powierzam ci Gem of the Serpent. Umieść go w dłoni Serpent Statue, która znajduje się na Ranazjar Isle, małej wysepce na północny zachód stąd. Czyniąc to sprawisz, że pojawi się ten, kto chroni Book of the Ancients. Ta księga zawiera sekrety Nag; sekrety ukrywane od wieków. Przynieś mi tą książkę, a dowiemy się wiele o naszych pokrytych łuską wrogach!",
    ["O"] = "Zdobądź Book of the Ancients, po czym wróć do Azore\'a Aldamorta, do wieży w Ethel Rethor.",
    ["T"] = "Księga Prastarych",
  },
  [6028] = {
    ["D"] = "Poszukuję odpowiedzialnej osoby do pomocy w małej, jednakże ważnej sprawie. Jestem miejscowym reprezentantem interesów Argent Dawn przed lokalnym zarządem Everlook. Muszę dostarczyć raport o postępach Argent Officer Pureheart z Chillwind Camp; miejsce to znajduje się daleko stąd, na południowym skraju Western Plaguelands. $B$BMogę śmiało powiedzieć, że to doskonała okazja do przedstawienia się mojej przełożonej i - być może - otrzymania od niej jakiegoś zlecenia.",
    ["O"] = "Dostarcz Everlook Report do Argent Officer Pureheart z Chillwind Camp, Western Plaguelands.",
    ["T"] = "Raport z Everlook",
  },
  [6029] = {
    ["D"] = "Poszukuję odpowiedzialnej osoby do pomocy w małej, jednakże ważnej sprawie. Jestem miejscowym reprezentantem interesów Argent Dawn przed lokalnym zarządem Everlook. Muszę dostarczyć raport o postępach Argent Officer Garush z Bulwark; miejsce to znajduje się daleko stąd, u zachodniego skraju Western Plaguelands, na wschód od Tirisfal Glades. $B$BMogę śmiało powiedzieć, że to doskonała okazja do przedstawienia się memu przełożonemu i - być może - otrzymania od niego jakiegoś zlecenia.",
    ["O"] = "Dostarcz Everlook Report do Argent Officer Garush z Bulwark, w Western Plaguelands.",
    ["T"] = "Raport z Everlook",
  },
  [6030] = {
    ["D"] = "Pustelnik, znany w tych stronach jako Umbranse, dostarczył Argent Dawn prawdziwe literackie arcydzieło... zapełnione prawdopodobnie największym stężeniem nonsensu, jaki widziałem zapisany na papierze. $B$BJeden z najbardziej szanowanych przywódców Argent Dawn, Książę Nicholas Zverenhoff, jest wspaniałym językoznawcą. Możesz mu to dostarczyć? oczywiście za odpowiednią cenę... Light\'s Hope Chapel - to miejsce, w którym obecnie przebywa; daleko we wschodniej części Eastern Plaguelands.",
    ["O"] = "Dostarcz księgę \"Badania nad mową duszy\" Księciu Nicholasowi Zverenhoffowi z Light\'s Hope Chapel w Eastern Plaguelands",
    ["T"] = "Książę Nicholas Zverenhoff",
  },
  [6031] = {
    ["D"] = "Żyjemy szczęśliwie w naszej ostoi. Nie lubimy nieznajomych. To dobre dla nas, ale nie dla handlu.$B$BNie tak dawno temu jedna z naszych nielicznych przyjaciółek, nocna elfka, przybyła do nas odziana w pelerynę z runicznego materiału. Runiczny materiał to tutaj rzadkość, ale ta peleryna była tak doskonała, że moi ludzie poprosili mnie o uszycie z niego większej ilości ubrań. $B$BCzy przyniesiesz mi runiczny materiał? Jeśli dostarczysz mi go wystarczająco dużo, dam ci coś w zamian.",
    ["O"] = "Przynieś 30 sztuk Runecloth do Meilosha z Timbermaw Hold.",
    ["T"] = "Runiczny materiał",
  },
  [6032] = {
    ["D"] = "Choć lud Drewnopyskich uwielbia dotyk runicznego materiału, nie jest on dla nas święty. Jednak księżycowy materiał - tak. $B$BPrzynieś mi małą porcję tego świętego materiału, a ja nauczę cię sekretnej techniki krawieckiej.",
    ["O"] = "Przynieś 2 sztuki Mooncloth do Meilosha z Timbermaw Hold.",
    ["T"] = "Święty materiał",
  },
  [6041] = {
    ["D"] = "Kiedy gromadziłeś składniki, kilku moich ludzi oznaczyło budynki Plagi, które mają zostać zniszczone. $B$BOto plan: dam ci dziesięć lasek mojej specjalnej mieszanki. Zabierzesz je do Lasu Plagi i podłożysz w oznaczonych budynkach. $B$B<Smokey pstryka palcami.>$B$BBing! To takie proste.",
    ["O"] = "Udaj się do Lasu Plagi, na północny zachód od Kaplicy Blasku Nadziei. Zniszcz 8 Struktur Plagi używając Smokey\'s Special Compound na Znakach Detonacji, umieszczonych w każdym budynku. Smokey oznaczył Zigguraty oraz Rzeźnie. $B$BGdy podłożysz bombę, opuść budynek i podziwiaj swoją robotę. $B$BTak na marginesie, Smokey\'s Special Compound jest raczej... niestabilny.",
    ["T"] = "Gdy Smokey śpiewa, staję się brutalny",
  },
  [6042] = {
    ["D"] = "Nie można odejść na dwa kroki od tego gospodarstwa, nie wpadając na któregoś z tych obrzydliwych nietoperzy. Chcę móc zabierać moje ogary na polowanie na Plagę nie będąc zaczepianym przez żadne cholerne śmierdzące gacki. Z całą pewnością mam ciekawsze rzeczy do roboty, niż bezmyślne wyżynanie tych kreatur od świtu do nocy. W przeciwieństwie do ciebie.$B$BCo? Twoje szkolenie? To jest twoje szkolenie! A teraz zejdź mi z oczu i nie wracaj, dopóki nie zabijesz sporej ilości tych skrzydlatych demonów. Nie zawiedź mnie.",
    ["O"] = "Zabij 20 Noxious Plaguebats oraz 10 Monstrous Plaguebats. Gdy wykonasz zadanie, wróć do Nathanosa Blightcallera.",
    ["T"] = "Drobne zgryzoty nieżycia",
  },
  [6061] = {
    ["D"] = "Dla nas, taurenów, ważne jest, by podążać za tradycją naszych przodków i walczyć z potężnymi stworzeniami. Poskramiając te bestie łączymy ich dusze z naszymi, zbliżając się tym samym do Matki Ziemi.$B$BW ten sam sposób oswajanie zwierząt, by walczyły po naszej stronie, pomaga nam stać się jednością z otaczającą nas naturą. Ostatecznie nauczysz się oswajać dowolne zwierzęta, w zależności od twego uznania. Ale wszystko wymaga ćwiczeń, a ty musisz się jeszcze wiele nauczyć. Zacznij przy pomocy tej różdżki oswajania; oswój dorosłego stepochodźca.",
    ["O"] = "Użyj Taming Rod by oswoić Adult Plainstrider. Popracuj nad swymi umiejętnościami, a potem zwróć Taming Rod Yawowi Sharpmane\'owi z Bloodhoof Village.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6062] = {
    ["D"] = "Władza nad naturą to umiejętność godna podziwu. Jako $głowca:łowczyni;, musisz dążyć do opanowania wrodzonej siły i mocy każdego ze zwierząt, które wybierzesz.$B$BZdobycie nad nim kontroli nie jest prostym wyczynem; musisz do niego przystąpić z mocnym postanowieniem.$B$BW ramach swego pierwszego zadania weź tę różdżkę oswajania i użyj jej, by oswoić straszliwego cętkowanego dzika. Można je znaleźć w pobliżu Razor Hill. Popracuj nad swymi umiejętnościami walcząc z dzikiem u boku, następnie wróć do mnie.",
    ["O"] = "Użyj Taming Rod by oswoić Dire Mottled Boar. Popracuj nad swymi umiejętnościami, a potem zwróć Taming Rod Thotarowi z Razor Hill.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6063] = {
    ["D"] = "Ważne jest, byś jako $głowca pamiętał:łowczyni pamiętała; o odpowiedzialności, jaka leży w twych dłoniach. Natury nie można naginać do zaspokajania własnych zachcianek; jest czymś, co należy szanować i postrzegać jako potęgę o wiele przerastającą nasz marny byt.$B$BMusisz udowodnić, że to rozumiesz, $N, zanim zdobędziesz umiejętność oswajania zwierzęcia na swego towarzysza.$B$BTwoim pierwszym zadaniem będzie wziąć tę różdżkę oswajania. Z jej pomocą będziesz $gmógł:mogła; oswoić leśnego przyczajca. Uczyń to i przećwicz swe umiejętności, $głowco:łowczyni;.",
    ["O"] = "Użyj Taming Rod by poskromić Webwood Lurker. Poćwicz, po czym zwróć Taming Rod Dazalarowi z Dolanaar.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6064] = {
    ["D"] = "Witaj, $gchłopcze:młoda damo;! Więc, $gchciałbyś:chciałabyś; wiedzieć jak oswoić sobie własnego pupila?$B$BCóż, zacznijmy. Gdy nadchodzi czas polowania, nie ma nic ważniejszego, niż twój ekwipunek, ale o mojej nowej pukawce możemy pogadać kiedy indziej. A teraz, skupmy się na czymś, czym na pewno jesteś $gzainteresowany:zainteresowana;: na własnym zwierzęciu!$B$BNajlepszym sposobem na naukę jest przetestowanie kilku zwierząt jako towarzyszy i sprawdzenie, które najbardziej ci się spodoba. Odnajdź wielkiego turniowego dzika, a następnie użyj na nim różdżki oswajania, by go oswoić.",
    ["O"] = "Użyj Taming Rod by oswoić Large Crag Boar. Popracuj nad swymi umiejętnościami, a potem zwróć Taming Rod Grifowi Wildheartowi z Kharanos.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6065] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dostatecznie $gzdolnego:zdolną;, by oswoić zwierzę i przysposobić je na swojego towarzysza.$B$BMusisz porozmawiać z Yawem Sharpmanem z Wioski Bloodhoof. On wprowadzi cię na ścieżkę, na której dowiesz się, jak oswoić własne zwierzę.",
    ["O"] = "Porozmawiaj z Yawem Sharpmane\'em z Bloodhoof Village.",
    ["T"] = "Ścieżka łowcy",
  },
  [6066] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dostatecznie $gzdolnego:zdolną;, by oswoić zwierzę i przysposobić je na swojego towarzysza. $B$BMusisz porozmawiać z Yawem Sharpmane\'em z Wioski Bloodhoof. On wprowadzi cię na ścieżkę, na której dowiesz się, jak oswoić własne zwierzę.",
    ["O"] = "Porozmawiaj z Yawem Sharpmane\'em z Bloodhoof Village.",
    ["T"] = "Ścieżka łowcy",
  },
  [6067] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dostatecznie $gzdolnego:zdolną;, by oswoić zwierzę i przysposobić je na swojego towarzysza.$B$BMusisz porozmawiać z Yawem Sharpmane\'em z Wioski Bloodhoof. On wprowadzi cię na ścieżkę, na której dowiesz się, jak oswoić własne zwierzę.",
    ["O"] = "Porozmawiaj z Yawem Sharpmane\'em z Bloodhoof Village.",
    ["T"] = "Ścieżka łowcy",
  },
  [6068] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dostatecznie $gzdolnego:zdolną;, by oswoić zwierzę i przysposobić je na swojego towarzysza.$B$BMusisz porozmawiać z Thotarem z Razor Hill. Wskaże ci on drogę do samodzielnego oswojenia zwierzyny.",
    ["O"] = "Porozmawiaj z Thotarem z Razor Hill.",
    ["T"] = "Ścieżka łowcy",
  },
  [6069] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dostatecznie $gzdolnego:zdolną;, by oswoić zwierzę i przysposobić je na swojego towarzysza.$B$BMusisz porozmawiać z Thotarem z Razor Hill. Wskaże ci on drogę do samodzielnego oswojenia zwierzyny.",
    ["O"] = "Porozmawiaj z Thotarem z Razor Hill.",
    ["T"] = "Ścieżka łowcy",
  },
  [6070] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dostatecznie $gzdolnego:zdolną;, by oswoić zwierzę i przysposobić je na swojego towarzysza.$B$BMusisz porozmawiać z Thotarem z Razor Hill. Wskaże ci on drogę do samodzielnego oswojenia zwierzyny.",
    ["O"] = "Porozmawiaj z Thotarem z Razor Hill.",
    ["T"] = "Ścieżka łowcy",
  },
  [6071] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dość $gdoświadczonego:doświadczoną;, by poradzić sobie z oswojeniem zwierzęcia i wytrenowaniem go na swojego towarzysza. $B$BMusisz porozmawiać z Dazalarem z Dolanaaru. On wprowadzi cię na ścieżkę, która nauczy cię jak zdobyć własne zwierzę.",
    ["O"] = "Porozmawiaj z Dazalarem z Dolanaaru.",
    ["T"] = "Ścieżka łowcy",
  },
  [6072] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dość $gdoświadczonego:doświadczoną;, by poradzić sobie z oswojeniem zwierzęcia i wytrenowaniem go na swojego towarzysza.$B$BMusisz porozmawiać z Dazalarem z Dolanaaru. On wprowadzi cię na ścieżkę, która nauczy cię, jak zdobyć własne zwierzę.",
    ["O"] = "Porozmawiaj z Dazalarem z Dolanaaru.",
    ["T"] = "Ścieżka łowcy",
  },
  [6073] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dość $gdoświadczonego:doświadczoną;, by poradzić sobie z oswojeniem zwierzęcia i wytrenowaniem go na swojego towarzysza.$B$BMusisz porozmawiać z Dazalarem z Dolanaaru. On wprowadzi cię na ścieżkę, która nauczy cię, jak zdobyć własne zwierzę.",
    ["O"] = "Porozmawiaj z Dazalarem z Dolanaaru.",
    ["T"] = "Ścieżka łowcy",
  },
  [6074] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dostatecznie $gzdolnego:zdolną;, by oswoić zwierzę i przysposobić je na swojego towarzysza.$B$BMusisz zobaczyć się z Grifem Wildheartem z Kharanos. Wskaże ci on drogę do samodzielnego oswojenia zwierzyny.",
    ["O"] = "Porozmawiaj z Grifem Wildheartem z Kharanos.",
    ["T"] = "Ścieżka łowcy",
  },
  [6075] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dostatecznie $gzdolnego:zdolną;, by oswoić zwierzę i przysposobić je na swojego towarzysza.$B$BMusisz zobaczyć się z Grifem Wildheartem z Kharanos. Wskaże ci on drogę do samodzielnego oswojenia zwierzyny.",
    ["O"] = "Porozmawiaj z Grifem Wildheartem z Kharanos.",
    ["T"] = "Ścieżka łowcy",
  },
  [6076] = {
    ["D"] = "Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na dostatecznie $gzdolnego:zdolną;, by oswoić zwierzę i przysposobić je na swojego towarzysza.$B$BMusisz zobaczyć się z Grifem Wildheartem z Kharanos. Wskaże ci on drogę do samodzielnego oswojenia zwierzyny.",
    ["O"] = "Porozmawiaj z Grifem Wildheartem z Kharanos.",
    ["T"] = "Ścieżka łowcy",
  },
  [6081] = {
    ["D"] = "Posiadasz teraz moc oswajania zwierzęcia, ale musisz także nauczyć się, jak je szkolić.$B$BWybierz się do Orgrimmaru. Tam porozmawiaj z jednym z naszych najbardziej szanowanych łowców, Ormakiem Grimshotem. Pokaże ci, jak szkolić twojego nowego pupila. Znajdziesz go niedaleko Doliny Honoru.$B$BPowodzenia, $N.",
    ["O"] = "Porozmawiaj z Ormakiem Grimshotem z Orgrimmaru.",
    ["T"] = "Szkolenie zwierzęcia",
  },
  [6082] = {
    ["D"] = "Ostatnim stworzeniem jakie musisz oswoić jest to, które $gwinieneś:winnaś; nauczyć się naśladować: opancerzony skorpion. Uderza szybko i pewnie; opanowanie takiej siły jest twoim, jako $głowcy:łowczyni;, przeznaczeniem.$B$BGdy wrócisz, obdarzę cię umiejętnościami, jakich będziesz $gpotrzebował:potrzebowała;, by oswoić zwierzę, które wybierzesz; będzie ono na twoje rozkazy. Pod twoją kontrolą twój pupil będzie razem z tobą zdobywał doświadczenie. Pokażę ci także jak go przywoływać i odprawiać, gdy będziesz sobie tego życzyć.",
    ["O"] = "Użyj Taming Rod by oswoić Armored Scorpid. Popracuj nad swymi umiejętnościami, a potem zwróć Taming Rod Thotarowi z Razor Hill.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6083] = {
    ["D"] = "Łatwo zauważyć przewagę, jaką zwierzę zapewnia w walce z przeciwnikiem. Gdy zyskujesz kontrolę nad innym zwierzęciem, $gsam:sama; rośniesz w siłę. Twój pupil musi stać się przedłużeniem ciebie.$B$BNastępne zadanie wymaga, byś $gopuścił:opuściła; stały ląd; kolejne stworzenie do oswojenia znajdziesz w wodach u wybrzeża, za Wioską Sen\'jin, nieopodal Wysp Echa. Szukaj żwawego kraba zwanego przybrzeżnym pełzaczem. Użyj różdżki oswajania by go oswoić, potem popracuj nad swymi umiejętnościami.",
    ["O"] = "Użyj Taming Rod by oswoić Surf Crawler. Popracuj nad swymi umiejętnościami, a potem zwróć Taming Rod Thotarowi z Razor Hill.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6084] = {
    ["D"] = "Turniowe dziki są dość zwaliste; może $gwolałbyś:wolałabyś; coś z nieco większą finezją? Zatem dobrze, mam coś takiego. Na południe i wschód stąd znajdziesz wielkie białe koty, zwane śnieżnymi lampartami. Podobnie jak w przypadku elegancko rzeźbionej strzelby, ich zewnętrzne piękno skrywa potężnego wojownika, zdolnego do zadawania ogromnych obrażeń. Są daleko bardziej zwinne i szybkie niż dzik, którego $goswoiłeś:oswoiłaś;.$B$BWeź różdżkę oswajania i oceń, jak podoba ci się śnieżny lampart.",
    ["O"] = "Użyj Taming Rod, by oswoić Snow Leopard. Popracuj nad swymi umiejętnościami, a potem zwróć Taming Rod Grifowi Wildheartowi z Kharanos.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6085] = {
    ["D"] = "Może spodoba ci się zwierzę, które dysponuje czymś więcej niż tylko brutalną siłą. Lodowy pazurzasty niedźwiedź jest świetnym kompanem dla świeżo $gupieczonego łowcy, takiego:upieczonej łowczyni, takiej; jak ty; można go znaleźć na wschód od Kharanos. Oto różdżka oswajania; wypróbuj to zwierzę jako swojego pupila!$B$BGdy wrócisz, obdarzę cię umiejętnością oswojenia dowolnego zwierzęcia; będzie ono stawiało czoła przeciwnościom, których doświadczysz i wraz z tobą zdobywało doświadczenie. Pokażę ci także jak je przywoływać i odprawiać, gdy będziesz sobie tego życzyć.",
    ["O"] = "Użyj Taming Rod, by oswoić Ice Claw Bear. Popracuj nad swymi umiejętnościami, a potem zwróć Taming Rod Grifowi Wildheartowi z Kharanos.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6086] = {
    ["D"] = "Posiadasz teraz moc oswajania zwierzęcia, ale musisz także nauczyć się, jak je szkolić.$B$BWybierz się do Ironforge i znajdź Salę Zbrojeń. Tam porozmawiaj z jedną z naszych najbardziej szanowanych treserów zwierząt, Belią Thundergranite. Nauczy cię jak szkolić twoje zwierzę, więc w drogę!$B$BBelia jest przyjazną kobietą; nie $gpowinieneś:powinnaś; mieć kłopotów ze zdobyciem jej aprobaty. Powodzenia, $N.",
    ["O"] = "Porozmawiaj z Belią Thundergranite z Ironforge.",
    ["T"] = "Szkolenie zwierzęcia",
  },
  [6087] = {
    ["D"] = "Masz zapalczywego ducha, $głowco:łowczyni;; ochoczo oczekujesz następnego wyzwania. $B$BTwoim kolejnym zadaniem będzie pozyskanie towarzystwa wilka, zwanego tropicielem preriowym. To stworzenie jest szybkie i nie zna strachu; aby uczynić zeń swego towarzysza, musisz wykazać się tymi samymi umiejętnościami.$B$BPodczas walki nauczysz się tworzyć ze swoim pupilem drużynę. Na koniec musicie działać jak jedność, ramię w ramię.$B$BOto różdżka oswajania, $N. Oswój tropiciela preriowego i popracuj nad swymi umiejętnościami.",
    ["O"] = "Użyj Taming Rod by oswoić Prairie Stalker. Popracuj nad swymi umiejętnościami, a potem zwróć Taming Rod Yawowi Sharpmane\'owi z Bloodhoof Village.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6088] = {
    ["D"] = "Finałowym zadaniem, które dla ciebie mam, będzie poskromienie stworzenia, które zamieszkuje przestworza. Sęponur jest trudnym przeciwnikiem, ale dzięki jego towarzystwu posiądziesz wiedzę o gwałtownym ataku i groźnym wyglądzie.$B$BZ woli Matki Ziemi, kiedy wrócisz obdarzę cię umiejętnościami, których będziesz potrzebować, by uczynić swym towarzyszem dowolne zwierzę, zgodnie z własnym wyborem; będzie ono stawiało czoła przeciwnościom, których doświadczysz i wraz z tobą zdobywało doświadczenie. Pokażę ci także jak je przywoływać i odprawiać, gdy będziesz sobie tego życzyć.",
    ["O"] = "Użyj Taming Rod by oswoić Swoop. Popracuj nad swymi umiejętnościami, a potem zwróć Taming Rod Yawowi Sharpmane\'owi z Bloodhoof Village.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6089] = {
    ["D"] = "Posiadasz teraz moc oswajania zwierzęcia, ale musisz także nauczyć się, jak je szkolić.$B$BUdaj się do Thunder Bluff. Tam porozmawiaj z jednym z naszych najbardziej szanowanych łowców, Holtem Thundehornem. Jeśli uzna, żeś tego $ggodny:godna;, obdarzy cię umiejętnością szkolenia swego zwierzęcia. $B$BHolt poskromił najbardziej mocarne i przerażające bestie Azeroth i ma pod swoją komendą wiele silnych zwierząt. Jego więzy z Matką Ziemią są silne i możesz wiele się od niego nauczyć. Powodzenia, $N.",
    ["O"] = "Porozmawiaj z Holtem Thunderhornem w Hunter Rise miasta Thunder Bluff.",
    ["T"] = "Szkolenie zwierzęcia",
  },
  [6101] = {
    ["D"] = "Różnorodność natury jest czymś, czego można być pewnym, $N. Jedyne, co możemy o niej powiedzieć to to, że nigdy nie jest taka sama; ciągle się zmienia.$B$BZadania, które ci zlecę, pomogą ci docenić wartość ogromnego zróżnicowania stworzeń, spośród których możesz wybrać swojego towarzysza.$B$BWeź tę różdżkę oswajania i użyj jej by poskromić nocną panterę. Znajdziesz je na południe stąd. Przećwicz swoje umiejętności łowieckie. Wówczas zaczniesz dostrzegać podobieństwa i różnice natury.",
    ["O"] = "Użyj Taming Rod, by poskromić Nightsaber Stalker. Poćwicz, po czym zwróć Taming Rod Dazalarowi z Dolanaaru.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6102] = {
    ["D"] = "$gPoskromiłeś:Poskromiłaś; dwa stworzenia kroczące po ziemi, teraz czas na takie, które przemierza przestworza. Użyj różdżki oswajania, by poskromić wielką sowę. Zamieszkują one tereny na zachód stąd. Przećwicz swoje umiejętności z tą potężną sową u swego boku.$B$BKiedy wrócisz, obdarzę cię umiejętnościami, których będziesz potrzebować, by uczynić swym towarzyszem dowolne zwierzę, zgodnie z własnym wyborem; będzie ono stawiało czoła przeciwnościom, których doświadczysz i wraz z tobą zdobywało doświadczenie. Pokażę ci także jak je przywoływać i odprawiać, gdy będziesz sobie tego życzyć.",
    ["O"] = "Użyj Taming Rod, by poskromić Strigid Screecher. Poćwicz, po czym zwróć Taming Rod Dazalarowi z Dolanaaru.",
    ["T"] = "Oswajanie zwierzęcia",
  },
  [6103] = {
    ["D"] = "Posiadasz teraz moc oswajania zwierzęcia, ale musisz także nauczyć się, jak je szkolić.$B$BUdaj się do Darnassus. Tam porozmawiaj z jedną z naszych najbardziej szanowanych łowczyń, Jocastą. Obdarzy cię umiejętnością szkolenia twego zwierzęcia, więc nie trać czasu. $B$BChoć Jocasta może wydawać się nieco surowa, jednak zawsze cieszy się mogąc ujrzeć nowego łowcę zasilającego szeregi. Traktuj ją z szacunkiem, a odwdzięczy ci się tym samym. Powodzenia, $N.",
    ["O"] = "Porozmawiaj z Jocastą z Enklawy Cenariusa w Darnassus.",
    ["T"] = "Szkolenie zwierzęcia",
  },
  [6121] = {
    ["D"] = "Jesteś już $ggotowy:gotowa;, by nauczyć się o truciznach i mocy jaką my, druidzi, nad nimi posiadamy, $N. Cenarius pobłogosławił nas umiejętnością, pozwalającą uleczyć nawet najpaskudniejszą truciznę za pomocą zwykłej inkantacji. Ten dar niełatwo jest zdobyć... i aby upewnić się, że pojmiesz tę lekcję, będziesz $gmusiał:musiała; zająć się tą sprawą tak, jak zrobiłaby to przeciętna osoba.$B$BUdaj się do Moonglade i porozmawiaj z Dendrite\'em Starblaze; oczekuje on twego przybycia, by rozpocząć lekcję.",
    ["O"] = "Udaj się do Moonglade i porozmawiaj z Dendrite\'em Starblaze\'em z osady Nighthaven.",
    ["T"] = "Nowa lekcja",
  },
  [6122] = {
    ["D"] = "Wodospady Cliffspring w Darkshore są głównym źródłem wody pitnej dla całego regionu. Podejrzewam, że są również głównym źródłem trucizny, która zaatakowała tamtejszą faunę - szczególnie jelenie. Użyj tej probówki, aby pobrać próbkę wody u wejścia do jaskini znajdującej się za wodospadem. Musisz być $gostrożny:ostrożna;, bowiem zasiedliły ją nagi.$B$BKiedy to uczynisz, dostarcz probówkę Alanndarian Nightsong z Auberdine. To ona prosiła nas o pomoc, będziesz z nią współpracować, by rozwiązać ten problem.",
    ["O"] = "Użyj Pustej Probówki do wody z Wodospadów Cliffspring, by pobrać próbkę wody u wejścia do jaskini znajdującej się przy wodospadach.$B$BDostarcz Alanndarian Nightsong z Auberdine w Darkshore Napełnioną Probówkę wody z Wodospadu Cliffspring.",
    ["T"] = "Pierwotne źródło",
  },
  [6123] = {
    ["D"] = "Przyniesiona przez ciebie woda posłuży nam za bazę dla naszego lekarstwa dla jeleni. By nadać jej leczniczych właściwości potrzebuję ziemiokorzeni. Zielarze potrafią je odnaleźć, więc jeśli mamy pecha i nie znasz się na zielarstwie, będziesz $gmusiał:musiała; znaleźć kogoś, kto nam pomoże.$B$BBy nadać lekarstwu mocy potrzebuję księżycowych grzybów. Znalezienie okazów księżycowych grzybów jest dość łatwe; rosną we wszystkich jaskiniach na wchód stąd. Jaskinie zamieszkują księżyczaki. Ostatnimi czasy bywają rozdrażnione, więc bądź $gostrożny:ostrożna;.",
    ["O"] = "Przynieś Alanndarian Nightsong z Auberdine 5 Earthroot oraz 12 Lunar Funguses. Będzie ona mogła wówczas sporządzić miksturę leczącą.",
    ["T"] = "Przygotowanie antidotum",
  },
  [6124] = {
    ["D"] = "Składniki, które $gprzyniosłeś:przyniosłaś;, wystarczą na przygotowanie dziesięciu dawek balsamu, $N. Kiedy będę pracować w wiosce, starając się przygotować go więcej, chciałbym, abyś $gułatwił:ułatwiła; nam początek. Chore jelenie spotkać można na terenie całego Darkshore. Pomóż nam je wyleczyć, aplikując im ten balsam.$B$BJestem pewna, że gdy ukończysz zadanie, Dendrite Starblaze z Moonglade będzie chciał z tobą porozmawiać. Proszę, przekaż Kręgowi Cenarionu podziękowania od Auberdine... i $gsam:sama; przyjmij wyrazy wdzięczności za pomoc, którą nam $gofiarowałeś:ofiarowałaś;!",
    ["O"] = "Zaaplikuj Curative Animal Salve 10 chorym Sickly Deer , które zamieszkują tereny całego Darkshore. To powinno je wyleczyć. Chore sztuki widywano na południe od Cliffspring River na północ od Auberdine, aż po południe Darkshore, przy granicy z lasami Ashenvale.",
    ["T"] = "Uleczenie chorych",
  },
  [6125] = {
    ["D"] = "$gNauczyłeś:Nauczyłaś; się, co to znaczy oczyścić z trucizny nie korzystając z duchowego wsparcia. Kiedy opanujesz swą nowo pozyskaną władzę nad trucizną pamiętaj, co inni muszą znosić walcząc z nią.$B$B$gPowinieneś:Powinnaś; teraz udać się do Mathrengyla Bearwalkera, do Darnassus, $N. Nie ma wątpliwości iż teraz, gdy $gpojąłeś:pojęłaś; udzieloną ci lekcję, czeka on, by nauczyć cię nowego zaklęcia.$B$BSzerokiej drogi, $gmłody druidzie:młoda druidko;. Jeszcze się spotkamy.",
    ["O"] = "Wróć do Mathrengyla Bearwalkera, do Cenarion Enclave w Darnassus.",
    ["T"] = "Władza nad trucizną",
  },
  [6126] = {
    ["D"] = "Jesteś już $ggotowy:gotowa;, by nauczyć się o truciznach i mocy jaką my, druidzi, nad nimi posiadamy, $N. Cenarius pobłogosławił nas umiejętnością, pozwalającą uleczyć nawet najpaskudniejszą truciznę za pomocą zwykłej inkantacji. Ten dar niełatwo jest zdobyć... i aby upewnić się, że pojmiesz tę lekcję, będziesz $gmusiał:musiała; zająć się tą sprawą tak, jak zrobiłaby to przeciętna osoba.$B$BUdaj się do Moonglade i porozmawiaj z Dendrite\'em Starblaze\'em; oczekuje on twego przybycia, by rozpocząć lekcję.",
    ["O"] = "Udaj się do Moonglade i porozmawiaj z Dendrite\'em Starblaze\'em z osady Nighthaven.",
    ["T"] = "Nowa lekcja",
  },
  [6127] = {
    ["D"] = "Leżący na północny zachód od Crossroads szczyt Dreadmist jest najbardziej prawdopodobnym kandydatem na źródło rozprzestrzeniającej się trucizny. Na jego wietrznych wierzchołkach leżą sadzawki wody, wpływające na cykle pogodowe. Podejrzewam, że woda ta została skażona przez czczących demony członków klanu Płonącego Ostrza.$B$BUżyj tej probówki, aby pobrać próbkę wody z sadzawki na najwyższym wierzchołku góry. Kiedy to uczynisz, dostarcz probówkę Tondze Runetotemowi z Crossroads. To on prosił nas o pomoc, będziesz z nim współpracować, by rozwiązać ten problem.",
    ["O"] = "Użyj Pustej Probówki do wody z Dreadmist Peak, by pobrać próbkę wody z sadzawki na szczycie.$B$BDostarcz Tondze Runetotemowi z Crossroads w Barrens Napełnioną Probówkę wody z Dreadmist Peak.",
    ["T"] = "Pierwotne źródło",
  },
  [6128] = {
    ["D"] = "Przyniesiona przez ciebie woda posłuży nam za bazę dla naszego lekarstwa dla gazeli. By nadać jej leczniczych właściwości potrzebuję ziemiokorzeni. Zielarze potrafią je odnaleźć, więc jeśli nie jesteś $gobeznany:obeznana; z zielarstwem, będziesz $gmusiał:musiała; znaleźć kogoś, kto nam pomoże.$B$BBy nadać lekarstwu mocy potrzebuję rogów kodo - ich odpryski czy nawet fragmenty nie wystarczą. Kodo, z którymi prawdopodobnie sobie poradzisz, włóczą się po północnych częściach Barrens. Dla większego dobra upoluj kilka z nich w imię równowagi, $N, i przynieś mi ich rogi.",
    ["O"] = "Przynieś Tondze Runetotemowi z Crossroads 5 Earthroot i 5 Kodo Horns. Będzie on mógł wówczas sporządzić miksturę leczącą.",
    ["T"] = "Przygotowanie antidotum",
  },
  [6129] = {
    ["D"] = "Składniki, które $gprzyniosłeś:przyniosłeś;, wystarczą na przygotowanie dziesięciu dawek balsamu, $N. Kiedy będę pracować z miejscowymi starszymi, starając się przygotować więcej balsamu, chciałbym, abyś $gułatwił:ułatwiła; nam początek. W północnej części Barrens można spotkać chore gazele. Pomóż nam je wyleczyć, aplikując im ten balsam.$B$BJestem pewien, że gdy ukończysz zadanie, Dendrite Starblaze z Moonglade będzie chciał z tobą porozmawiać. Proszę, przekaż Kręgowi Cenarionu nasze podziękowania... i $gsam:sama; przyjmij wyrazy wdzięczności za pomoc, którą nam $gofiarowałeś:ofiarowałaś;!",
    ["O"] = "Zaaplikuj Curative Animal Salve 10 chorym Sickly Gazelles, które zamieszkują północne części Barrens. To powinno je wyleczyć. Chore sztuki zostały zauważone na północ od drogi przecinającej Crossroads z zachodu na wschód.",
    ["T"] = "Uleczenie chorych",
  },
  [6130] = {
    ["D"] = "$gNauczyłeś:Nauczyłaś; się, co to znaczy oczyścić z trucizny nie korzystając z duchowego wsparcia. Kiedy opanujesz swą nowo pozyskaną władzę nad trucizną pamiętaj, co inni muszą znosić walcząc z nią.$B$B$gPowinieneś:Powinnaś; teraz udać się do Turaka Runetotema z Thunder Bluff, $N. Nie ma wątpliwości iż teraz, gdy $gpojąłeś:pojęłaś; udzieloną ci lekcję, czeka on, by nauczyć cię nowego zaklęcia.$B$BSzerokiej drogi, $gmłody druidzie:młoda druidko;. Jeszcze się spotkamy.",
    ["O"] = "Wróć do Turaka Runetotema w Elder Rise miasta Thunder Bluff.",
    ["T"] = "Władza nad trucizną",
  },
  [6131] = {
    ["D"] = "Drewniane Paszcze są jedynym plemieniem furbolgów, które uchroniło się od skażenia. Jednak obecnie wiele innych ras zabija furbolgi na ślepo, nie zwracając uwagi, czy to przyjaciele czy wrogowie. Z tego powodu Drewniane Paszcze ufają niewielu.$B$BCzy chcesz dowieść swoich intencji? Udaj się do skażonego plemienia Martwego Lasu, a być może jednego dnia uznamy cię za sojusznika. Pierwszych przedstawicieli Martwego Lasu – wojowników, tropicieli i ogrodników - znajdziesz na zachód stąd.",
    ["O"] = "Grazle chce, abyś wykazał się, zabijając 5 Deadwood Warriors, 5 Deadwood Pathfinders oraz 5 Deadwood Gardeners.",
    ["T"] = "Sojusznik Drewnianych Paszcz",
  },
  [6132] = {
    ["D"] = "Zabierz mnie stąd!$B$BPrzybyłam do Doliny Włóczni, aby porozmawiać z Maraudinami. Myślałam, że mogę z nimi zrobić mały interes... ale oni nie chcą rozmawiać! Myślę, że chcą mnie zjeść!$B$BZabierz mnie stąd, a mój brat Hornizz sporo ci zapłaci! Jest w naszym obozie obok cmentarza kodo, na wschodzie.$B$BPośpieszmy się, $N. Dwie minuty temu słyszałam jakieś centaury jak rozmawiają o zbieraniu drewna pod ich garnek...",
    ["O"] = "Eskortuj Melizzę Brimbuzzle.",
    ["T"] = "Zabierz mnie stąd!",
  },
  [6133] = {
    ["D"] = "Wysokie elfy z Quel\'Lithien mają w swoim posiadaniu coś, co należy do mnie: dokumenty, które opisują historię mojego życia w postaci śmiertelnika.$B$BZanim spytasz - nie, nie życzę sobie, abyś je czytał. Zrób tylko to, co mówię, robaku: znajdź je i zwróć mi.$B$BI jeszcze jedno, imbecylu, postaraj się, aby twoje odwiedziny jeszcze długo przyprawiały ich o koszmary...",
    ["O"] = "Udaj się na północne rubieże Eastern Plaguelands i odnajdź Quel\'Thalas Registry. Znajdziesz je gdzieś w środku leśniczówki Quel\'Lithien.$B$BMusisz również zabić 8 Rangers, 8 Pathstriders i 8 Woodsmen.",
    ["T"] = "Żądanie Dowódcy Zwiadowców",
  },
  [6134] = {
    ["D"] = "Na południowym wschodzie jest Dolina Kości, nawiedzona przez duchy Magram. Brzmi strasznie, prawda? Pomyśl, jak straszne jest to dla Magram! Jeśli zdobędziemy energię ducha z tego miejsca, założę się, że będzie wiele warta dla tych centaurów.$B$BWeź to pudełko z magnesami na duchy. Jeśli umieścisz jeden między dwoma wielkimi szkieletami w dolinie Gigantów Śmierci, wtedy duchy się do niego zbliżą. Oddal się, wyjmij duchy i dostań swoją duch-o-plazmę - to jest tym co sprzedamy Magram.",
    ["O"] = "Zbierz 8 Ghost-o-plasms.",
    ["T"] = "Obława na duch-o-plazmę",
  },
  [6135] = {
    ["D"] = "Jak na razie udawało ci się wykonywać moje rozkazy poprawnie, choć dość powolnie. $B$BZapewne uważasz, że jesteś już gotów na jakieś wyzwanie. Tak... tak, imbecylu, może nawet zlecę ci jakiś bardziej skomplikowany zestaw zadań. $B$BNietoperz-albinos, Duskwing, przemierza ziemie na północ stąd. Wytrop go i zniszcz. Przynieś mi kawałek jego białej sierści, a zostaniesz wynagrodzony.",
    ["O"] = "Znajdź Duskwinga i zabij go. Zabierz ze zwłok Patch of Duskwing\'s Fur i zanieś go Nathanosowi Blightcallerowi. $B$BDuskwinga można ponoć spotkać na północ od Marris Stead.",
    ["T"] = "Ponuroskrzydły, jak ja cię nienawidzę...",
  },
  [6136] = {
    ["D"] = "Za obozowiskiem Argent Dawn w Light\'s Hope, na zachód od Northdale, znajdziesz opasłego czerwia zwanego Borelgore. $B$BTen potwór pożarł cały mój oddział. Jest niesamowitej wielkości; im więcej zje, tym większy się staje...$B$BChoć nie będą za tobą płakał, jeśli staniesz się jego obiadem, wolałbym, żebyś to ty go pokonał. Jak dotąd Borelgore pożarł wszystkich, którzy próbowali go upolować.",
    ["O"] = "Odnajdź Borelgore\'a na północnych rubieżach Eastern Plaguelands i zniszcz go. Kiedy wypełnisz misję, wróć do Nathanosa Blightcallera.",
    ["T"] = "Spaślak",
  },
  [6141] = {
    ["D"] = "Mój brat broni, Brat Anton, usłyszał plotki o inwazji nieumarłych w dalekim Kalimdorze, w krainie znanej jako Desolace. Anton natychmiast zarezerwował sobie transport do tego miejsca, aby znaleźć i zniszczyć zagrożenie ze strony nieumarłych!$B$BSzuka kogoś odważnego, kto zechce mu pomóc. Jeśli twoje serce jest prawe, porozmawiaj z Antonem. Jest w Desolace, w mieście Przymierza w Nijel\'s Point.",
    ["O"] = "Porozmawiaj z Bratem Antonem w Desolace.",
    ["T"] = "Brat Anton",
  },
  [6142] = {
    ["D"] = "Wyglądasz mi na rybaka, $C! Kocham łowić - łowię przez całe moje życie. Najlepszą przynętą jest delikatne mięso małż; ryby po prostu nie mogą się oprzeć, wiesz co mam na myśli?$B$BNa północ, na wybrzeżu znajdziesz wrak statku. Małże pełne mięsa są porozrzucane po tym miejscu. Przynieś mi dziesięć ich, a ja dam ci coś w zamian.",
    ["O"] = "Znajdź 10 Soft-shelled Clam Meat i przynieś je do Mai\'Lahii przy wiosce Shadowprey.",
    ["T"] = "Przynęta z małż",
  },
  [6143] = {
    ["D"] = "Może $gsłyszałeś:słyszałaś;, a może nie... moja ekipa i ja łowiliśmy ryby nieopodal wyspy Ranazjar, tuż przy wraku w północnej części wybrzeża. Zawsze tam wędkowaliśmy, a teraz szukam sposobu, by pomścić moich zgładzonych towarzyszy.$B$BNagi zaatakowały nas z samego rana i zabiły wszystkich oprócz mnie.$B$BMęczą mnie wyrzuty sumienia, $C; Potrzebuję, byś $gwyruszył:wyruszyła; zgładzić te nagi. Postaram się odpowiednio ci to wynagrodzić. Myślisz, że $gmógłbyś:mogłabyś; mi pomóc?",
    ["O"] = "Zabij 7 Slitherblade Myrmidon, 7 Slitherblade Naga i 5 Slitherblade Sorceresses, a potem porozmawiaj z Drulzegarem z wioski Shadowprey, w Desolace.",
    ["T"] = "Kolejna ryba do ubicia",
  },
  [6144] = {
    ["D"] = "Nadeszły rozkazy. Sam Bragor Bloodfist zażądał, bym wysłał swoich najbardziej \"uzdolnionych\" podwładnych do Undercity, aby wzięli udział w bardzo delikatnej misji.$B$BNiestety moi najbardziej uzdolnieni podwładni zginęli ponad trzy lata temu, a na ich miejsce zostały mi tylko kmiotki z martwicą mózgu. $B$B<Nathanos przeszywa cię zimnym spojrzeniem.> $B$BNatychmiast udaj się do Undercity i zgłoś się do Bragora Bloodfista. Nie przynieś mi wstydu!",
    ["O"] = "Udaj się do Undercity i porozmawiaj z Bragor Bloodfist.",
    ["T"] = "Wezwanie do dowództwa",
  },
  [6145] = {
    ["D"] = "Tak jak ciało nie może żyć bez głowy, tak samo głowa nie przetrwa bez ciała. Przez umocnienia Scarlet Crusade w Stratholme niemal nie sposób się przebić. Zamiast tego musimy odciąć ciało od głowy.$B$BMoi Umarli Tropiciele obserwują działania Krucjaty poza Stratholme. Główne dowództwo każdego dnia wysyła raport do Tyr\'s Hand. Ten raport jest kluczem! Znajdź Crimson Courier, odzyskaj raport i zanieś go Nathanosowi.",
    ["O"] = "Wróć do Eastern Plaguelands i wytrop Crimson Courier. Zabij go i odzyskaj Grand Crusader\'s Command.$B$BZabierz je do Nathanosa Blightcallera, by otrzymać dalsze instrukcje.",
    ["T"] = "Karmazynowy kurier",
  },
  [6146] = {
    ["D"] = "Wprowadziłem do tego rozkazu małe poprawki. Jeśli nasz podstęp się powiedzie, Scarlet Oracle wyjdzie z ukrycia, a wtedy uderzymy! $B$BSłuchaj uważnie. Musisz oddać ten rozkaz Crusader Lord Valdelmarowi. $B$BJak? Wręczysz mu go, imbecylu. $B$BWeź ten rozkaz i zgniłe jabłko do Tyr\'s Hand. Kiedy wejdziesz do miasta, zjedz jabłko. Zmienisz się w coś... znośniejszego dla ludzkiego oka. Wręcz rozkaz Crusader Lord Valdelmarowi.",
    ["O"] = "Udaj się do Tyr\'s Hand, na południowy wschód od Marris Stead. Kiedy już tam będziesz, zjedz Rotten Apple. W przebraniu członka Scarlet Crusade dostarcz Grand Crusader\'s Command do Crusader Lord Valdelmar.",
    ["T"] = "Podstęp Nathanosa",
  },
  [6147] = {
    ["D"] = "Dziwna ta prośba ze strony Wielkiego Krzyżowca... niemniej stanie się, jak tego żąda. Wróć do Scarlet Bastion i powiedz mu, że Oracle wkrótce wyruszy w drogę. $B$BPodejmiemy wszelkie środki, by nawet włos nie spadł jej z głowy podczas drogi do Stratholme.",
    ["O"] = "Wróć do Nathanosa Blightcallera z nowymi informacjami.",
    ["T"] = "Powrót do Nathanosa",
  },
  [6148] = {
    ["D"] = "Demetria jest głównym doradcą Wielkiego Krzyżowca. Zwą ją Oracle z powodu jej \"nadprzyrodzonych\" mocy. To z jej pomocą Krucjata odniosła swoje zwycięstwa nad Plagą. $B$BChoć udało nam się podstępem wywabić ją z ukrycia, to jeśli naprawdę posiada moce, o jakie się ją posądza, bez wątpienia będzie się spodziewać kłopotów. Ty będziesz tymi \"kłopotami\". $B$BOdnajdź Oracle i zgładź ją. Powinni właśnie wyruszać z Tyr\'s Hand. Przynieś mi dumę, robaku.",
    ["O"] = "Scarlet Crusade wykonał swój ruch. Gdzieś na drodze z Tyr\'s Hand do Stratholme znajdziesz Oracle, Demetrię, i jej orszak. Odnajdź ją i zgładź. Wróć do Nathanosa Blightcallera z wieściami o zwycięstwie.",
    ["T"] = "Szkarłatna Wyrocznia, Demetria",
  },
  [6161] = {
    ["D"] = "Dziennik Rackmore\'a głosi o tym, jak jego statek płynął do Feathermoon Stronghold, gdy został zaatakowany przez morskie stworzenia. By zapobiec wpadnięciu jego skarbu w ręce wroga, ukrył swoją skrzynię na Ranazjar Isle.$B$BOtwarcie skrzyni wymaga dwóch kluczy, srebrnego i złotego. Te klucze zostały zgubione, ale jeżeli one i skrzynia zostaną znalezione, skarb czeka!",
    ["O"] = "Znajdź Rackmore\'s Silver Key. Znajdź Rackmore\'s Golden Key. Znajdź i otwórz Rackmore\'s Chest.",
    ["T"] = "Zdobądź skarb Rackmore\'a!",
  },
  [6162] = {
    ["D"] = "Mój mąż przebył Felwood w imię honoru naszego rodu, walcząc przeciw Shadow Council i innym zdeprawowanym ohydztwom!$B$BGdy wymknął się śmierci kolejny raz, otrzymałam od niego list, w którym pisał, że druid prosi go o pomoc w zlikwidowaniu przesiąkniętego do cna złem Furbolga, zwanego Overlordem Rorem, później o moim mężu i tym druidzie słuch zaginął.$B$BChcę szponiastą łapę tego Rora, $N. W ten sposób zapłaci za uczynienie mnie wdową! Myślę, że ten potwór jest na południu... obok granicy z Ashenvale.",
    ["O"] = "Zabij Overlorda Rora i zanieś jego pazur do Dreka\'Sur z Bloodvenom Post w Felwood.",
    ["T"] = "Ostatnia bitwa męża",
  },
  [6163] = {
    ["D"] = "Było ich zbyt wielu. Właśnie tutaj, na tym gospodarstwie... oddałem swoje ostatnie tchnienie w obronie Lordaeronu. Ta farma i wszystko wokół zostało zalane przez ogromną falę Plagi. $B$BTen śmieć. To plugastwo. Stanął nade mną, a z jego rozprutego brzucha zwisała plątanina flaków. $B$BObudziłem się jako nieumarły. Przez długi czas byłem bezradny, Król Lisz pochłonął mój umysł. $B$BPrzyszła po mnie... jakoś w głębi zawsze wiedziałem, że przyjdzie. Wolna. $B$BA teraz nadszedł czas zemsty - zemsty na tym, co odebrało mi życie. Zniszcz to.",
    ["O"] = "Udaj się do Stratholme i zgładź Ramsteina the Gorger. Zabierz jego głowę na pamiątkę dla Nathanosa.",
    ["T"] = "Ramstein",
  },
  [6164] = {
    ["D"] = "Jestem gotów na otwarcie firmy! Co potrzebujesz?$B$BOj czekaj... Nie mogę otworzyć sklepu bez mojej księgi z recepturami. Jak będę pilnował składników bez tej księgi?$B$BMusiałem zostawić ją gdzieś w mieście. Miałem pokój w tawernie.$B$BPrzynieś moja książkę. Proszę przynieś ją do mnie! Przyniesiesz ją a zobaczysz! Otworzę sklep i zobaczysz, że moje ceny będą SZALONE!",
    ["O"] = "Przynieś Augustus\' Receipt Book z karczmy Terrordale.",
    ["T"] = "Księga receptur Augustusa",
  },
  [6165] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<NYI> <TXT> Archmage Timolain\'s Remains",
  },
  [6181] = {
    ["D"] = "Chociaż nie otrzymaliśmy bezpośrednio zbyt dużo pomocy od Stormwind, to mam kontakt w mieście, który pomaga nam dostarczać zbroje. Nazywa się Osric Strang. Jego sklep, Ograniczona Odporność, mieści się w starym mieście w Stormwind.$B$BNasze zasoby zbroi maleją, więc muszę się skontaktować z Osrickiem, aby było ich więcej. Możesz przekazać mu tą wiadomość?$B$BNajszybsza droga do Stormwind jest przez Thora, naszego mistrza gryfonów. Znajdziesz go na dole wzgórza; przynieś mu moją wiadomość, a potem weź gryfa do Stormwind.",
    ["O"] = "Przynieś liścik Lewisa do mistrza gryfów Thora.",
    ["T"] = "Prędka wiadomość",
  },
  [6182] = {
    ["D"] = "Nathanos Marris był pierwszym i ostatnim dowódcą ludzkich strażników. Uczeń Sylvanas Windrunner, teraz Królowej Banshee Opuszczonych.$B$BMyśleliśmy, że Nathanos zginął w walce broniąc Lordaeron pięć lat temu, jednak jego ciało nie zostało nigdy odnalezione. Przewidywano, że nigdy nie wydostał się z Wschodnich Ziem Plagi.$B$BMathias Shaw prowadził dochodzenie w tej sprawie i może mieć jakieś informacje. Natychmiast zgłoś się do niego. Przesiaduje na starym mieście, w barakach.",
    ["O"] = "Porozmawiaj z Mathiasem Shawem w Old Town Stormwind. Przybywa w barakach.",
    ["T"] = "Pierwszy i ostatni",
  },
  [6183] = {
    ["D"] = "Pięciu moich najlepszych agentów było przydzielonych do sprawy Marrisa. Jeden powrócił, tylko po to, by umrzeć we śnie trzy dni później.$B$BJedyne co udało się z niego wyciągnąć, to niewyraźny bełkot. Udało nam się zrozumieć dwa słowa: \"Nathanos\" i \"Blightcaller\".$B$BNie mam wolnych ludzi do kontynuowania tego dochodzenia i Ravenholdt nam nie pomoże. Musimy dojść do sedna tej sprawy; nawet jeśli miałoby to służyć tylko rodzinom zmarłych. Pomożesz?",
    ["O"] = "Porozmawiaj ponownie z Mathiasem Shawem, jeśli chcesz przyjąć jego zadanie.",
    ["T"] = "Uhonorowanie zmarłych",
  },
  [6184] = {
    ["D"] = "Jak dotąd wiemy jedynie, iż Nathanos Marris prawdopodobnie zginął z ręki tego Blightcallera. Przypuszczamy, że Blightcaller ponosi również odpowiedzialność za śmierć moich agentów. $B$BKolejny agent SI:7, Flint Shadowmore, stacjonuje w obozie Przymierza w Chillwind Point w Western Plaguelands. Odszukaj go; wprowadzi cię w aktualną sytuację na Ziemiach Plagi i zleci ci twój przydział. $B$BPowodzenia, $N.",
    ["O"] = "Udaj się do Chillwind Camp w Western Plaguelands i spotkaj się z Flintem Shadowmore\'em.",
    ["T"] = "Flint Shadowmore",
  },
  [6185] = {
    ["D"] = "Jak mówiłem, twoja pierwsza misja to rozpoznanie. Nic specjalnego, $N. Udaj się do Eastern Plaguelands i dowiedz się czegoś na temat Blightcallera. $B$BWypatruj również śladów naszych zaginionych współpracowników. Musimy założyć, że są martwi, a jeśli są martwi, to gdzieś muszą leżeć... ich zwłoki.$B$B<Flint z trudem przełyka ślinę.>$B$BWszyscy agenci SI:7 noszą te insygnia. $B$B<Flint pokazuje ci własne insygnia SI:7.>$B$BJeśli jakieś znajdziesz, przynieś mi je.",
    ["O"] = "Przeszukaj Eastern Plaguelands w poszukiwaniu śladów związanych z \"Blightcallerem\" i zaginionymi agentami SI:7. Jeśli znajdziesz jakieś Insygnia SI:7, zwróć je Flintowi Shadowmore\'owi z Chillwind Camp.",
    ["T"] = "Wschodnie plagi",
  },
  [6186] = {
    ["D"] = "<Z twarzy Flinta odpływa cała krew.>$B$BNa... Nathanos to zrobił? Nathanos jest Heroldem Plagi? $B$BAle dlaczego? Był taki... szlachetny - dowódca zwiadowców cieszący się powszechnym szacunkiem. Jedyny człowiek na przestrzeni dziejów, którego zgodziły się szkolić wysokie elfy. A teraz bezwzględny agent Opuszczonych? $B$BJa... przepraszam, że cię o to proszę, $N, lecz wysoki lord Bolvar musi natychmiast się o tym dowiedzieć. Proszę, wróć do Stormwind i przekaż mu wieści.",
    ["O"] = "Wróć do Stormwind i poinformuj wysokiego lorda Bolvara o losie Nathanosa Marrisa.",
    ["T"] = "Nadchodzi Blightcaller",
  },
  [6187] = {
    ["D"] = "Czy wiesz, ilu dowódców zwiadowców żyje na tym świecie? Ilu ludzi w historii wstąpiło w ich szeregi? $B$BOsiągnięcia Nathanosa były bezprecedensowe. Był taktycznym geniuszem, odpowiedzialnym za zwycięstwa Przymierza na przestrzeni całej dekady konfliktu. $B$BA teraz... czempion Opuszczonych. $B$BNie. Tak być nie może. Trzeba przywrócić porządek. $B$BZbierz armię, $N. Poprowadź ją na Ziemie Plagi i zniszcz Blightcallera. $B$BŻyczę szczęścia, $N. Zaiste, będziesz go potrzebował podczas tej bitwy.",
    ["O"] = "Zbierz armię i udaj się do Eastern Plaguelands. Wszystkimi siłami przypuść atak na Nathanosa Blightcallera oraz wszelkie plugastwo z Hordy, które spróbuje go bronić. $B$BZachowaj przytomność umysłu, $N. Horda będzie broniła dowódcy zwiadowców do ostatniej kropli krwi.",
    ["T"] = "Trzeba przywrócić porządek",
  },
  [6201] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED> The Legacy of the Ashbringer",
  },
  [6221] = {
    ["D"] = "Dokładnie na południowym zachodzie znajduje się obóz furbolgów Umarłego Pnia. Spaczenie przesiąknęło ten obóz i chciałbym zakończyć to, zanim stanie się problemem.$B$BPlemię Umarłego Pnia jest złe, ale jest to efekt zatrucia ich umysłów magią spaczenia. Ich wrogość nie jest cechą wrodzoną, jednak nie można im już pomóc. Smuci mnie wielce, że muszę walczyć ze swoim ludem.$B$BProszę, $N, zrób co trzeba i nie wdawaj się w szczegóły; to zbyt dużo dla mnie.",
    ["O"] = "Nafien chce, byś $gzabił:zabiła; 5 Deadwood Den Watchers, 5 Deadwood Avengers oraz 5 Deadwood Shamans.",
    ["T"] = "Umarły Pień na północy",
  },
  [6241] = {
    ["D"] = "Plemię Drewnopyskich zwykło trzymać się swoich, $N. Podczas gdy pozwalamy na przejście tym, którzy udowodnili, że są godni zaufania, staramy się unikać innych plemion furbolgów, kiedy tylko się da.$B$BOstatnio zauważyłam, że plemię Nastającej Zimy jest do nas coraz bardziej wrogo nastawione. Wydaje się być w szale, podsycanym przez własny strach oraz nienawiść do wszystkiego czego nie rozumieją.$B$BOgraniczenie ich liczebności było by dla nas znaczącą pomocą, $N.",
    ["O"] = "Salfa pragnie, byś $gzabił:zabiła; 6 Winterfall Totemics, 6 Winterfall Den Watchers i 6 Winterfall Pathfinders.",
    ["T"] = "Aktywność w Winterfall",
  },
  [6261] = {
    ["D"] = "$N, w tej skrzynce jest wszystko, o co prosił Lewis. Możesz zabrać ją do niego? $B$BJeśli $grozmawiałeś:rozmawiałaś; już z Thorem w Westfall, będziesz $gmógł:mogła; polecieć tam na gryfie. Naszym mistrzem gryfów jest Dungar Longdrink, przebywający ponad dzielnicą handlową.$B$BPorozmawiaj z nim, następnie dostarcz tę skrzynię do Lewisa tak szybko, jak to możliwe. Nie chcemy, by nasi ludzie w Westfall walczyli bez zaopatrzenia!",
    ["O"] = "Zanieś Osric\'s Crate do Dungara Longdrinka, mistrza gryfów.",
    ["T"] = "Dungar Longdrink",
  },
  [6281] = {
    ["D"] = "Za niewielką opłatą możesz wykupić lot gryfem do Stormwind, co pozwoli ci dostarczyć list Lewisa do Osrica. To najszybszy możliwy sposób, by się tam dostać. $B$BJeśli jesteś $gzainteresowany:zainteresowana;, odezwij się do mnie ponownie, gdy będziesz $ggotowy:gotowa; do drogi. Pobiorę niewielką opłatę, ale wierz mi, warto!",
    ["O"] = "Wykup przelot gryfem od mistrza gryfów Thora i dostarcz Lewis\' Note do Osrica Stranga, do sklepu Limited Immunity w Old Town miasta Stormwind.",
    ["T"] = "Dalsza podróż do Stormwind",
  },
  [6282] = {
    ["D"] = "Taureni dzierżą zaszczyt opieki nad tą krainą. Z pewnością łatwo się domyślić, dlaczego martwię się liczbą harpii, zamieszkujących Stonetalon.$B$BTo przez Krwawe Furie zwiększa się liczba harpii w Kalimdorze; rzucają się na wszystko, co się rusza, sprawiając, że strach wychodzić poza próg domu.$B$BPotrzebuję cię, byś je $gwyrżnął:wyrżnęła;, $N!",
    ["O"] = "Maggran Earthbinder z Sun Rock Retreat chce, byś $gzabił:zabiła; 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers i 7 Bloodfury Roguefeathers.",
    ["T"] = "Zagrażające harpie",
  },
  [6283] = {
    ["D"] = "Ograniczenie liczby harpii Krwawych Furii nie wystarczy. Jedynym skutecznym środkiem na tę plagę jest śmierć ich przywódczyni, Krwawej Furii Rozpruwaczki! $B$BTo prawdziwa władczyni tych cuchnących kreatur. Zabij ją, a ich liczba na pewno się zmniejszy.$B$BWróć do Osmalonej Doliny i poszukaj jej przy zachodnich wzgórzach. Nie będzie łatwo ją pokonać, ale nagroda będzie tego warta.",
    ["O"] = "Maggran z Sun Rock Retreat chce, byś $gzabił:zabiła; Bloodfury Ripper i przyniósł jej pozostałości na dowód swojego czynu.",
    ["T"] = "Ród Krwawych Furii",
  },
  [6284] = {
    ["D"] = "Ostrzeżenie: wstęp do Kanionu Sishir na zachód stąd wyłącznie na własne ryzyko.$B$BBesseleth i jej ośmionożne dzieci lasu objęły ten kanion w posiadanie.$B$BMaggran Earthbinder z Sun Rock Retreat wyznaczył nagrodę za Besseleth. Zabij ją i przynieś mu dowód swego czynu; wówczas otrzymasz zapłatę za uśmiercenie tego ośmionożnego potwora.",
    ["O"] = "Zabij Besseleth i przynieś jej kieł do Maggrana z Sun Rock Retreat.",
    ["T"] = "Arachnofobia",
  },
  [6285] = {
    ["D"] = "Mistrzem gryfów w Westfall jest Thor. Jeśli już z nim $grozmawiałeś:rozmawiałaś;, możesz polecieć do niego na jednym z moich gryfów.$B$BCo warto pamiętać: gryfy zawsze uczy się, jak dolecieć do stolicy, ale jeśli chcesz lecieć do konkretnego mistrza gryfów, zabiorą cię doń tylko wtedy, gdy już u niego $gbyłeś:byłaś;.$B$B$gOdwiedziłeś:Odwiedziłaś; już Thora, więc odezwij się do mnie jeszcze raz, gdy będziesz $ggotów:gotowa; na przelot gryfem do Westfall. Gdy będziesz na miejscu, dostarczysz skrzynię Osrica kwatermistrzowi Lewisowi.",
    ["O"] = "Wykup przelot gryfem do Sentinel Hill od mistrza gryfów Dungara Longdrinka, następnie dostarcz Osric\'s Crate do Lewisa w Sentinel Hill.",
    ["T"] = "Powrót do Lewisa",
  },
  [6301] = {
    ["D"] = "Chciwość przemysłu i niekończąca się wojna zniszczyły ziemie Stonetalon. Tylko błogosławieństwo Matki Ziemi może uleczyć takie rany. $B$B$N, potrzebuję, byś $gposzukał:poszukała; specjalnych nasion - nasion Gai. Rosną wyłącznie w Stonetalon Mountain, na północ od Sun Rock Retreat, nad Jeziorem Mirkfallon, przy lustrze wody. $B$BGdy przyniesiesz mi nasiona, za pomocą mych szamańskich mocy przyspieszę ich rozwój.",
    ["O"] = "Tammra Windfield z Sun Rock Retreat chce, byś $gzebrał:zebrała; 10 Gaea Seeds.",
    ["T"] = "Cykl odrodzenia",
  },
  [6321] = {
    ["D"] = "Egzekutor Hadrec poprosił mnie o inwentaryzację wyposażenia Sepulcher. Przy Pladze i innych czyhających w lesie atrakcjach, nie chce, by Strażnikom Śmierci brakowało niezbędnego ekwipunku. $B$BOkazało się, że generalnie jesteśmy dobrze wyposażeni, ale potrzebujemy więcej broni, by zastąpić te stracone w polu.$B$BOto zamówienie na potrzebne przedmioty dla handlarza broni Gordona Wendhama z Undercity.$B$BZabierz je do naszego mistrza nietoperzy, Karosa Razoka, i porozmawiaj z nim o transporcie do Undercity.",
    ["O"] = "Przynieś Podrig\'s Order do Karosa Razoka.",
    ["T"] = "Zaopatrzenie Sepulcher",
  },
  [6322] = {
    ["D"] = "Umieściłem zaopatrzenie dla Sepulcher w tej skrzyni. Jeśli już je $godwiedziłeś:odwiedziłaś; i $grozmawiałeś:rozmawiałaś; z tamtejszym mistrzem nietoperzy, możesz wrócić do niego na grzbiecie jednego z nich.$B$BPorozmawiaj z mistrzem nietoperzy Undercity, Michaelem Garrettem. Zapewni ci transport do Sepulcher.",
    ["O"] = "Przynieś skrzynię Gordona do Michaela Garretta.",
    ["T"] = "Michael Garrett",
  },
  [6323] = {
    ["D"] = "Jeden z moich nietoperzy zabierze cię do Undercity za drobną opłatą. Kiedy będziesz $ggotów:gotowa;, odezwij się do mnie, a zorganizujemy ci transport.$B$BGordona Wendhama znajdziesz w Dzielnicy Handlowej Undercity. To ta sama dzielnica, w której wyląduje nietoperz.",
    ["O"] = "Zapłać właścicielowi nietoperzy, Karosowi Razokowi, za lot nietoperzem do Undercity, po czym zanieś rozkazy Podriga do Gordona Wendhama w Undercity.",
    ["T"] = "Lot do Undercity",
  },
  [6324] = {
    ["D"] = "Właścicielem nietoperzy z Sepulcher jest treser nietoperzy Karos Razok. Jeśli już go $gpoznałeś:poznałaś;, mogę dać ci nietoperza, który cię do niego zaniesie.$B$BNasze nietoperze zawsze znajdą drogę do Undercity, ale żeby polecieć do bardziej odległych okolic, jeździec musi najpierw odwiedzić dane miejsce i porozmawiać z tamtejszym właścicielem nietoperzy.$B$B$gPoznałeś:Poznałaś; już Karosa z Sepulcher, więc możesz teraz latać tam na nietoperzach. Gdy będziesz $ggotowy:gotowa;, odezwij się do mnie.",
    ["O"] = "Zapłać właścicielowi nietoperzy, Michaelowi Garretowi, za lot nietoperzem do Sepulcher, po czym zanieś skrzynię Gordona do Umarłego Strażnika Podriga w Sepulcher.",
    ["T"] = "Powrót do Podriga",
  },
  [6341] = {
    ["D"] = "Rybacy z wioski Rut\'theran radzą sobie nieźle, gdyż tutejsze wody są niezwykle obfite w wielkie ryby. Chciałabym porównać je z tymi, które można złowić na kontynencie.$B$BMam tu zbiór kości i łusek, które chciałabym przekazać mojemu koledze w Darkshore. Ma na imię Laird i zajmuje się handlem rybami w wiosce Auberdine.$B$BZanieś mój zbiór do mistrza hippogryfów, Vesprystusa, i poproś go o lot do Auberdine.",
    ["O"] = "Przynieś Nessa\'s Collection do Vesprystusa.",
    ["T"] = "Zbiory z Teldrassilu",
  },
  [6342] = {
    ["D"] = "Są dwie metody, by dostać się do Auberdine z wioski Rut\'theran - promem lub na grzbiecie hippogryfa. Obie są dość szybkie i niezawodne, ale jeśli jeszcze nie $gleciałeś:leciałaś; do Auberdine, to zalecam ci to zrobić.$B$BRadzę ci za każdym razem porozmawiać z mistrzem hippogryfów gdy odwiedzisz nowe miasto. Kiedy porozmawiasz z mistrzem, wtedy będziesz $gmógł:mogła; się tam dostać drogą powietrzną z innych miast.$B$BOto zbiór Nessy. Porozmawiaj ze mną znów, gdy będziesz $ggotów:gotowa; polecieć do Auberdine i doręczyć zbiór Nessy do Lairda.",
    ["O"] = "Poproś mistrza hipogryfów Vesprystusa o lot do Auberdine, następnie zanieś Nessa\'s Collection do Lairda.",
    ["T"] = "Lot do Auberdine",
  },
  [6343] = {
    ["D"] = "Muszę wysłać odpowiedz Nessie. Musi się dowiedzieć jak różnią się ryby z Teldrasillu od tych wyłowionych nad brzegiem Kalimdoru. Możemy tylko zgadywać co jest tego przyczyną, ale sam uważam, że Teldrassil wywołuje wielki wpływ na żyjącą na nim florę i faunę!$B$BProszę, zanieś Nessie odpowiedź. Jeśli pragniesz przelecieć się na grzbiecie hippogryfa, by dostać się do wioski Rut\'theran, to porozmawiaj z tutejszym mistrzem hippogryfów, Caylaisem Moonfeather. Jeśli chcesz przepłynąć się promem, to regularnie odpływa on z doku na północnym zachodzie.",
    ["O"] = "Przynieś Laird\'s Response do Nessy Shadowsong.",
    ["T"] = "Powrót do Nessy",
  },
  [6344] = {
    ["D"] = "Moja znajoma, Nessa Shadowsong, jest handlarką ryb w Wiosce Rut\'theran. Potrzebuje przesłać paczkę do Darkshore i szuka gońca, który pomógłby jej w tym.$B$BJeśli jesteś $gzainteresowany:zainteresowana;, udaj się do Nessy w wiosce Rut\'theran poprzez portal w Darnassus. Portal znajdziesz na zachód od ogrodów świątyni.",
    ["O"] = "Porozmawiaj z Nessą Shadowsong",
    ["T"] = "Nessa Shadowsong",
  },
  [6361] = {
    ["D"] = "Mam trochę skór zwierząt z Barrens i muszę je dostarczyć do Thunder Bluff. Mój kolega, Ahanu, zrobi z nich skórzane przedmioty.$B$BZaniesiesz mu je w moim imieniu?$B$BNajszybsza droga do Thunder Bluff prowadzi na grzbiecie wiwerny. Zanieś skóry do Taka, naszego trenera wiwern Devraka w Crossroads i pomów z nim o przetransportowaniu cię do Thunder Bluff.",
    ["O"] = "Przynieś Bundle of Hides do mistrza wiwern Devraka w Crossroads.",
    ["T"] = "Pakiet skór",
  },
  [6362] = {
    ["D"] = "Za niewielką opłatą, podaruje ci podróż wiwerną do Thunder Bluff. Nie ma szybszego sposobu, by dostać się do miasta!$B$BJeśli cię to zadowala, porozmawiaj ze mną ponownie, gdy będziesz $ggotów:gotowa; do podróży.$B$BJeśli masz zamiar zanieść te skóry do Ahanu, to sądzę, że znajdziesz go w zbrojowni Hewy, w wieży mistrzów lotów podniebnych w Thunder Bluff. Jest to dokładnie tam gdzie wylądujesz!",
    ["O"] = "Wykup podróż wiwerną do Thunder Bluff u mistrza wiwern Devraka, następnie przynieś skóry do Ahanu w Thunder Bluff.",
    ["T"] = "Podróż do Thunder Bluff",
  },
  [6363] = {
    ["D"] = "Przygotowałem skórzane dobra dla Jahana na sprzedaż w Crossroads. Możesz mu to dostarczyć?$B$BJeśli $gbyłeś:byłaś; już wcześniej w Crossroads i $grozmawiałeś:rozmawiałaś; z tamtejszym trenerem wiwern, to śmiało możesz skorzystać z jednego z naszych zwierząt i powrócić tam.$B$BWeź ze sobą skórzane dobra do Tala, naszego trenera wiwern w Thunder Bluff i porozmawiaj z nim o transporcie do Crossroads.",
    ["O"] = "Zanieś skórzane przedmioty Ahanu do Tal w Thunder Bluff.",
    ["T"] = "Tal, mistrz lotów podniebnych",
  },
  [6364] = {
    ["D"] = "By polecieć do miasteczka, $gmusiałeś:musiałaś; je poprzednio odwiedzić i porozmawiać tam z mistrzem wiwern owego miasteczka. Jeśli $gbyłeś:byłaś; w Crossroads i $grozmawiałeś:rozmawiałaś; z mistrzem Devrakiem, możesz za niską opłatą skorzystać z przelotu do tego miasteczka.$B$BPorozmawiaj ze mną ponownie kiedy będziesz $ggotów:gotowa;. Kiedy będziesz w Crossroads, będziesz $gmógł:mogła; dostarczyć skórzane dobra do Jahana Hawkwinga.",
    ["O"] = "Kup przelot do Crossroads od mistrza lotów Tala, później zanieś skórzane dobra Ahanu do Jahana Hawkwinga.",
    ["T"] = "Powrót do Jahana",
  },
  [6365] = {
    ["D"] = "Mam trochę kawałków mięsa, które chcę wysłać do przyjaciółki. Jej imię to Gryshka, karczmarka w Orgrimmarze. Czy doniesiesz jej mięso ode mnie?$B$BNajszybciej do Orgrimmaru dotrzesz lecąc na wiwernie. Zabierz mięso do mistrza wiwern w Crossroads, Devraka i porozmawiaj z nim o transporcie do Orgrimmaru.",
    ["O"] = "Przynieś Zargh\'s Meats do Devraka w Crossroads.",
    ["T"] = "Mięso do Orgrimmaru",
  },
  [6381] = {
    ["D"] = "Tak jak $gwidziałeś:widziałaś;, $C, choć ziemia pogrążona jest w bólu, cykl życia wciąż stanowi potęgę. Teraz nastał czas, byśmy my pomogli mu trwać. Musisz zasiać te nasiona w centrum zniszczenia, w Osmalonej Dolinie na zachód stąd. Uważaj na siebie - harpie i rozwścieczone żywiołaki ognia wciąż nękają tę pobliźnioną ziemię.$B$B$N, weź te zaklęte nasiona Gai i zasadź je w kopczykach żyznej gleby. Cykl życia musi trwać!",
    ["O"] = "Zasadź 10 Gaea Seeds w Gaea Dirt Mounds i zwróć pozostałe Enchanted Gaea Seeds Tammrze z Sun Rock Retreat.",
    ["T"] = "Nowe życie",
  },
  [6382] = {
    ["D"] = "Twoja siła robi wrażenie, $C. To, jak palisz się do polowania, upewnia mnie, że sprostasz grubszemu zwierzowi... i większemu wyzwaniu.$B$BKnieje Ashenvale to rozległa, dziewicza puszcza, którą Horda chce sobie podporządkować, zarówno pod względem politycznym jak i duchowym. Jeśli chcesz dowieść swojej wartości na niezbadanych ziemiach, poszukaj wskazówek u Senani Thunderheart z Posterunku Splintertree. Placówka ta znajduje się na północ od ścieżki prowadzącej z Barrens.",
    ["O"] = "Porozmawiaj z Senani Thunderheart z Splintertree Post w Ashenvale.",
    ["T"] = "Polowanie w Ashenvale",
  },
  [6383] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Polowanie w Ashenvale",
  },
  [6384] = {
    ["D"] = "Mam tu wiwernę i za kilka monet mogę przewieźć cię nią do Orgrimmaru. Kiedy się tam dostaniesz, możesz zabrać mięso do Gryshki. Jej tawerna znajduje się w Dolinie Siły, niedaleko Wieży Lotów, gdzie wyląduje mój wierzchowiec.$B$BPorozmawiaj ze mną ponownie, kiedy będziesz $ggotowy:gotowa; na podróż.",
    ["O"] = "Wynajmij wiwernę do Orgrimmaru od mistrza wiwern Devraka, później przynieś Zargh\'s Meats do Gryshki w Orgrimmarze.",
    ["T"] = "Przejażdżka do Orgrimmaru",
  },
  [6385] = {
    ["D"] = "Napisałam list z podziękowaniami do Zargha. Czy dostarczysz go dla mnie? Jeśli $gbyłeś:byłaś; już w Crossroads i $grozmawiałeś:rozmawiałaś; z ich mistrzem wiwern, to możesz tam polecieć.$B$BWeź mój list do Dorasa, mistrza wiwern Orgrimmaru i porozmawiaj z nim o transporcie do Crossroads.",
    ["O"] = "Przynieś list Gryshki do Dorasa w Orgrimmarze.",
    ["T"] = "Doras, mistrz wiwern",
  },
  [6386] = {
    ["D"] = "Moje wiwerny są szkolone, by latać w wiele różnych miejsc, jeśli tylko $gbyłeś:byłaś; w tym miejscu i $grozmawiałeś:rozmawiałaś; z mistrzem wiwern, który tam pracuje.$B$B$gByłeś:Byłaś; już w Crossroads i $grozmawiałeś:rozmawiałaś; z ich mistrzem wiwern Devrakiem, więc możesz polecieć do niego. Kiedy będziesz w Crossroads, możesz dostarczyć list Gryshki do Zargha.$B$BPorozmawiaj ze mną, kiedy będziesz $ggotowy:gotowa;.",
    ["O"] = "Kup od mistrza wiwern Dorasa lot wiwerną do Crossroads, następnie zanieś Gryshka\'s Letter do Zargha w Crossroads.",
    ["T"] = "Powrót do Crossroads",
  },
  [6387] = {
    ["D"] = "Widzę wielu młodych krasnoludów u moich drzwi, chcą się uczyć handlu minerałami górniczymi. A jeśli jest coś, czego górnik potrzebuje bardziej niż czegokolwiek, to wybieraj!$B$BMam listę studentów górnictwa, którzy uzyskali wysokie zdolności w lekcjach i zdobyli wielkie honory. Weź moją listę do Golnira Bouldertoe w Ironforge. On już na nią czeka.$B$BNajszybszym sposobem dotarcia do Ironforge jest użycie gryfa, więc dostarcz ten list do naszego mistrza gryfów, Thorgruma Borrelsona i porozmawiaj z nim o transporcie do Ironforge.",
    ["O"] = "Przynieś List Brocka do Thorgruma Borrelsona w Thelsamar.",
    ["T"] = "Stypendyści",
  },
  [6388] = {
    ["D"] = "Oto kilofy dla studentów Brocka. Jeśli już $gbyłeś:byłaś; w Thelsamarze, to wskakuj na gryfa i leć z powrotem!$B$BWeź te narzędzia, udaj się do naszego mistrza gryfów, Grytha Thurdena, i porozmawiaj z nim o powrocie do Thelsamaru.",
    ["O"] = "Zanieś Honorary Picks do Grytha Thurdena z Ironforge.",
    ["T"] = "Gryth Thurden",
  },
  [6389] = {
    ["D"] = "Przetrząsasz Tartak za czymś odpowiednim do otwarcia Beczki. Znajdujesz łom, który spisze się idealnie.$B$BZapierasz się na nogach i modlisz, abyś zdążył uciec z Tartaku zanim dopadną ciebie Termity.",
    ["O"] = "Uwolnij Termity ze skażonych ziem w Tartaku Północnej Grani, po czym powróć z Beczką Termitów do Nathaniela Dumah w Halnym Obozie w zachodnich Ziemiach Zarazy.",
    ["T"] = "Zaraza ponad Tobą",
  },
  [6390] = {
    ["D"] = "Rozglądasz się po tartaku, szukając czegoś odpowiedniego do otwarcia beczki. Znajdujesz łom, który wygląda na odpowiednie narzędzie. Stajesz i modlisz się, abyś $gzdołał:zdołała; wydostać się z tartaku, zanim dotrą do ciebie termity.",
    ["O"] = "Uwolnij Plagueland Termites w Northridge Lumber Mill, później wróć z Barrel of Plagueland Termites do Mickey\'a Levine\'a przy Bulwark, w Tirisfal Glades.",
    ["T"] = "A niech was plaga...",
  },
  [6391] = {
    ["D"] = "Za kilka monet, jeden z moich gryfów przeniesie ciebie do Ironforge. A tam dostarczysz listę Brocka do Golnira Bouldertoe. Znajdziesz go w Gildii Górników. To jest w dzielnicy Wielkiej Kuźni miasta Ironforge, która jest dokładnie tam, gdzie moje gryfy lądują!$B$BMów do mnie ponownie, gdy będziesz $ggotowy:gotowa; do drogi.",
    ["O"] = "Opłać podróż na gryfie do Ironforge u Mistrza Gryfów - Thorgruma Borrelsona, następnie dostarcz Listę Brocka do Golnira Bouldertoe w Ironforge.",
    ["T"] = "Podróż do Ironforge",
  },
  [6392] = {
    ["D"] = "Za niewielką opłatą możesz wybrać się w podróż gryfem do Thelsamaru... pod warunkiem, że kiedyś już tam $gbyłeś:byłaś;. Gryfy latają tylko w miejsca, które już $godwiedziłeś:odwiedziłaś;, więc upewnij się, że porozmawiasz z każdym napotkanym mistrzem gryfów.$B$B$gPoznałeś:Poznałaś; już Thorgruma, mistrza gryfów z Thelsamaru, tak więc możesz teraz do niego wrócić. Kiedy już dotrzesz do Thelsamaru, dostarcz kilofy krasnoludowi o imieniu Brock Stoneseeker.$B$BZgłoś się do mnie, gdy będziesz $ggotów:gotowa; do drogi.",
    ["O"] = "Opłać podróż gryfem do Thelsamar u mistrza gryfów Grytha Thurdena, a następnie zanieś Honorary Picks Brockowi Stoneseeker w Thelsamarze.",
    ["T"] = "Powrót do Brocka",
  },
  [6393] = {
    ["D"] = "Trybunał Fal wysłał mnie, abym wypowiedział wojnę żywiołakom ognia, tutaj w Stonetalon Mountain. Neptulon Łowca Fal, Pan wszystkich żywiołaków wody, pragnie ujrzeć, jak nasi płomienni kuzyni gasną.$B$B$N, możesz pomóc mi zyskać przychylność w Trybunale poprzez zniszczenie ognistych żywiołaków w Osmalonej Dolinie. Kiedy już zostaną zniszczone, żywiołaki ognia zostawią po sobie szczątki Incendrites. Powróć z nimi do mnie, a zostaniesz $gnagrodzony:nagrodzona;.",
    ["O"] = "Przynieś 10 Incendrites Tsunamanowi w Sun Rock Retreat.",
    ["T"] = "Wojna żywiołaków",
  },
  [6394] = {
    ["D"] = "$N, jesteś $ggodnym zaufania:godną zaufania; $R5. Czy mogę liczyć na ciebie przy następnym zadaniu?$B$BJakiś czas temu badałem jaskinie na północy dla minerałów i zostawiłem mój ulubiony kilof. Kiedy później wróciłem tam, by odzyskać go, znalazłem jaskinie zapełnione złośliwymi bestiami! Czy pójdziesz do jaskini sabatu Płonącego Ostrza i odzyskasz mój kilof?$B$BZostawiłem go w komnacie z wodospadami. Mój kilof ma w sobie magiczną umiejętność - możesz go zobaczyć w ciemności. Nie martw się więc odnalezieniem go... a tego co go pilnuje!",
    ["O"] = "Przynieś Thazz\'ril\'s Pick do brygadzisty Thazz\'rila.",
    ["T"] = "Kilof Thazz\'rila",
  },
  [6395] = {
    ["D"] = "Moja przyjaciółka Marla Fipps żyła ze swoim mężem Samuelem przed nadejściem plagi, lecz po jej nadejściu Samuel zginął i dołączył do armii Plagi.$B$BMarla nie została zabita, tylko po to żeby zginąć z rąk jej bezmózgiego męża. Jej miłość była tak silna, że jej ostatnim życzeniem było to, aby została pochowana wraz ze swoim ukochanym Samuelem.$B$BSamuel Fipps wędruje w ruinach obozu przy drodze na północ od Deathknell. Pokonaj go i spełnij życzenie Marli: pochowaj go w jej grobie, w pierwszym rzędzie naszego cmentarza.",
    ["O"] = "Przynieś szczątki Samuela Fipps\'a do grobu Marli, następnie wróć do nowicjusza Elretha.",
    ["T"] = "Ostatnie życzenie Marli.",
  },
  [6401] = {
    ["D"] = "Przekaż dobre wieści Tammrze Windfield, cioci Kayi, która przebywa w Sun Rock Retreat. Kaya żyje! Myśleliśmy, że została stracona po brutalnym ataku na naszą wioskę. Podążaj ścieżką na zachód, aby dostać się do Sun Rock Retreat.",
    ["O"] = "Przekaż dobre wieści Tammrze Windfield w Sun Rock Retreat.",
    ["T"] = "Kaya żyje",
  },
  [6402] = {
    ["D"] = "Spotkasz się z Windsorem w bramie Stormwind.$B$BTo, co Windsor zaraz odkryje, wstrząśnie podstawą królestwa!$B$B$N, nie próbuj ryzykować tam $gsam:sama;. Musisz zgromadzić armię! Zbierz swoich rodaków. Do broni!",
    ["O"] = "Udaj się do miasta Stormwind i zapuść się pod bramy miasta. Porozmawiaj z giermkiem Rowe, aby mógł poinformować marszałka Windsora, że $gprzybyłeś:przybyłaś;.",
    ["T"] = "Miejsce spotkania Stormwind",
  },
  [6403] = {
    ["D"] = "To była nie lada podróż, $gprzyjacielu:przyjaciółko;. Mam u ciebie dług wdzięczności. Być może, kiedy to wszystko się zakończy...$B$BJak już bez wątpienia się $gprzekonałeś:przekonałaś;, Lady Prestor to Onyxia: Potomek Deathwinga, bliźniak tyrana w Iglicy Czarnej Skały, Nefariana.$B$BZbyt długo trzymała nasze królestwo w jej zniewalającym spojrzeniu. Nawet wysoki lord jest kontrolowany przez jej sztuczki - jak kukiełka. Kres tego nadejdzie dzisiaj. Czar zostanie zerwany.$B$BNie martw się, bo razem odniesiemy zwycięstwo!$B$BJesteś $ggotowy:gotowa;?",
    ["O"] = "Podążaj za Reginaldem Windsorem przez Stormwind. Chroń go od wszelkiej krzywdy!",
    ["T"] = "Wielka Maskarada",
  },
  [6421] = {
    ["D"] = "Coś jest tu nie tak, w Stonetalon. Czujesz to napięcie w powietrzu, $N?$B$BNa południowy wschód stąd leży głęboka jaskinia w Jarze Boulderslide. Tamtejsze koboldy szaleńczo wykopują rzadki kryształ zwany rezonitem. Potrzebuję twojej pomocy w zdobycia próbek rudy, bym mógł zrozumieć, co się dzieje w tej jaskini. Będę również potrzebował, byś $gzbadał:zbadała; dno tej jaskini.$B$BIdź, $gmłody:młoda; $R7, muszę koniecznie wiedzieć, jakie zło czai się pod tymi górami.",
    ["O"] = "Zagłąb się do jaskini w Boulderslide Ravine i przynieś z tamtąd 10 Resonite Crystals do zbadania dla Mor\'rogala na Sun Rock Retreat.",
    ["T"] = "Jar Boulderslide",
  },
  [6441] = {
    ["D"] = "Hej! W drodze do Ratchet przemierzałam Ashenvale i postanowiłam zrobić przystanek w Splintertree. Zawsze wypatruję wszelkich okazji, a wygląda na to, że rogi satyrów cieszą się ostatnio powodzeniem w Ratchet.$B$BPopytałam trochę wśród miejscowych i wychodzi na to, że tutejsze satyry - te z Night Run, Satyrnaaru i Xavian - wszystkie co do jednego mają dokładnie takie rogi, jakich szukam. Ja nie mam z nimi szans... ale ty wyglądasz na $gtakiego, co dałaby:taką, co dałaby; radę!$B$BWiesz co, zdobądź dla mnie te rogi, a nie pożałujesz.",
    ["O"] = "Zbierz 16 Satyr Horns dla Pixel z Splintertree Post.",
    ["T"] = "Rogi satyrów",
  },
  [6442] = {
    ["D"] = "Zło czai się u wybrzeża, $R7.$B$BTo miejsce spoczynku potępionego miasta Zoram, które od dawna spoczywa w ruinach i w otchłani morza. Zagubione i niemal zapomniane.$B$BNiedawno, z nieznanych powodów, powróciły tu nagi. Jednak ich motywy są mało ważne; musimy bronić ziem, których zdobycie tak wiele nas kosztowało.$B$BWróć do mnie z głowami nag! Przepędź je z powrotem w głębiny!",
    ["O"] = "Przynieś 20 Wrathtail Heads do Marukai z okolic Zoram Strand.",
    ["T"] = "Nagi na wybrzeżu Zoram",
  },
  [6461] = {
    ["D"] = "My, trolle z Malaka\'Jin, żyjemy z darów ziemi; Stonetalon Mountain zapewniają nam wspaniałe łowy, które pozwalają nam przetrwać.$B$BOstatnio przyciągnęliśmy uwagę niemile widzianych gości... miejscowe pająki napadają nocami nasze obozy i kradną naszą zdobycz.$B$BJeśli zechcesz pomóc nam wybić te straszliwe bestie, my z Malaka\'Jin będziemy twoimi dłużnikami. Pająki są wszędzie w Stonetalon Mountain - po prostu skieruj się na północ, a zobaczysz, o czym mówię.",
    ["O"] = "Xen\'zilla z Malaka\'Jin chce, byś $gzabił:zabiła; 10 Deepmoss Creepers i 7 Deepmoss Venomspitters.",
    ["T"] = "Krwiożercy",
  },
  [6462] = {
    ["D"] = "Moi ziomkowie jechali tu wioząc święte trollowe amulety, lecz nim dotarli do Zoram\'gar, furbolgi Kolcogrzbiete zaatakowały ich i zabiły! Plugawce!$B$BBrak mi moich zabitych braci i sióstr, ale spotkam się z nimi znów w przyszłym życiu. Natomiast na tym świecie ich amulety stanowią wielką wartość. To hańba, że znalazły się w posiadaniu furbolgów!$B$B$N, musisz odzyskać amulety! Leżą w skrzyniach w Ostoi Kolcogrzbietów, jaskini na krańcu ich wioski, na północ od Astranaaru.",
    ["O"] = "Przynieś 8 Troll Charms do Mitsuwy z Zoram\'gar Outpost.",
    ["T"] = "Trollowe amulety",
  },
  [6481] = {
    ["D"] = "$gOdkryłeś:Odkryłaś; śmiertelne zagrożenie dla tych krain, $C. Rezonitowy pojemnik, który $gznalazłeś:znalazłaś; w tej jaskini, mieści pogrążonego w śnie Ziemca o imieniu Goggeroc.$B$BUżywając moich szamańskich mocy zmieniłam strukturę zebranych przez ciebie rezonitowych kryształów. Weź ten zaklęty kryształ rezonitu i rozbij rezonitową pokrywę, która skrywa Ziemca.$B$BGdy Goggeroc się obudzi, będzie osłabiony... Zabij go, $N!",
    ["O"] = "Otwórz rezonitowy pojemnik za pomocą Enchanted Resonite Crystal, po czym zabij Goggeroca. Wróć do Mor\'rogala z wieściami i Enchanted Resonite Crystal.",
    ["T"] = "Przebudzenie Ziemca",
  },
  [6482] = {
    ["D"] = "Hę? Kim jesteś? $B$B$N? Nie jesteś furbolgiem. Niech ich demony! Myśleli, że jestem niedźwiedziem i schwytali mnie, a teraz głodzą! Opadam z sił...$B$BPomóż mi uciec, potem porozmawiaj z moją siostrą Yamą w posterunku Splintertree, na wschód stąd.$B$B$N! Muszę stąd uciec!",
    ["O"] = "Ochroń Ruula, potem porozmawiaj z Yamą Snowhoof w Splintertree Post.",
    ["T"] = "Wolność dla Ruula",
  },
  [6501] = {
    ["D"] = "Wszystko co mogę ci dać to część pękniętego medalionu.$B$BMusisz znaleźć innego przedstawiciela smoczej krwi, który zechce pomóc ci wykuć nowy klucz. Gdy będziesz już $gmiał:miała; klucz, udasz się do Wyrmbog w Dustwallow Marsh. Tam znajdziesz jej leże, $N.$B$BGdzie $gmógłbyś:mogłabyś; znaleźć inne smoki chętne do pomocy? Przykro mi, ale nie wiem... Mówi się, że istnieją. Niektórzy może nawet działają i żyją między nami, przebrani za przedstawicieli człekokształtnych ras. Życzę ci szczęścia.",
    ["O"] = "Musisz znaleźć istotę zdolną przywrócić moc Fragmentowi Smoczego Oka. Jedyna informacja, jaką posiadasz o takiej istocie, to to, że istnieje.",
    ["T"] = "Smocze Oko",
  },
  [6502] = {
    ["D"] = "To fragment smoka, łuska - zaklęta i przemieniona. W całości - zapewniłaby ci dostęp do leża bestii. Pęknięta jest bezużyteczna.$B$BMożna naprawić ten przedmiot, ale będzie to wymagało krwi czempiona czarnych smoków. Jest taki jeden... nosi miano Generała Drakkisatha; włada armią pomiotów Nefariana. Może o nim słyszałeś?$B$BWróć z jego krwią, $R, a zaczaruję ten fragment tak, by umożliwił ci wstęp do leża Onyxii.",
    ["O"] = "Musisz zdobyć Blood of the Black Dragon Champion - Generała Drakkisatha. Drakkisatha można znaleźć w jego sali tronowej za Halls of Ascension w Blackrock Spire.",
    ["T"] = "Amulet Smoczego Ognia",
  },
  [6503] = {
    ["D"] = "Otrzymaliśmy wieści, że dywersanci z Ashenvale niedawno opuścili placówkę Silverwing i teraz krążą po lesie na obrzeżu naszych terenów. Nie chcemy, żeby zbierali informacje o naszej obronie!$B$BPrzemierz lasy na południe od naszej placówki i na wschód od należącej do Przymierza placówki Silverwing. Znajdź i zabij dywersantów, potem wróć do mnie.",
    ["O"] = "Zabij 9 Ashenvale Outrunners, po czym wróć do Kuray\'bina z Splintertree Outpost.",
    ["T"] = "Dywersanci z Ashenvale",
  },
  [6504] = {
    ["D"] = "Właśnie odebrałam tego szatkownika z Ratchet i wracałam do tartaku Wojennej Pieśni, gdzie wyznaczono mi służbę. Dostałam instrukcję, jak obsługiwać tego szatkownika, ale podczas drogi podmuch wiatru wyrwał mi ją z rąk. Kartki poleciały wszędzie wokół, a mi została tylko okładka.$B$BPrzypuszczam, że teraz kartki mogą już być po prostu wszędzie... ale bez nich nie wiem, jak obsługiwać szatkownika! Poszukasz ich dla mnie?",
    ["O"] = "Znajdź 12 zagubionych kartek Shredder Operating Manual, złóż je w Rozdziały 1, 2 i 3. Oddaj kartki Gurdzie Ragescar z okolic Splintertree Post.",
    ["T"] = "Zgubione kartki",
  },
  [6521] = {
    ["D"] = "Malcin twierdzi, że przebywa na obrzeżach Razorfen Downs. Ten ambasador musi zostać zgładzony - a jego misja stać się porażką w oczach Króla Lisza.$B$BJego obecność tłumaczy wiele z tego, co odkryliśmy w tamtej okolicy - niektóre z quilboar stały się przerażająco potężne, a jednocześnie wykazują specyficzne oznaki infekcji Plagą. Zaiste, musi to oznaczać, że zawarto jakiś układ.$B$BZnajdź Malcina i zgładź go. Wróć do mnie, kiedy to polecenie stanie się faktem.",
    ["O"] = "Przynieś Ambassador Malcin\'s Head do Bragora Bloodfista z Undercity.",
    ["T"] = "Przeklęte przymierze",
  },
  [6522] = {
    ["D"] = "Mój Panie, $B$BDobrze wiesz, co Tobie oferujemy. Ogromną szansę na przejęcie Barrens i okolicznych ziem. W zamian chcemy tylko Twojej pomocy. Przez pomoc nie mamy na myśli nic więcej niż tylko to, abyś dał nam wolną rękę w prowadzeniu działań w okolicy. $B$BProszę, pozwól, że omówimy tę sprawę. Mamy wielką moc i pragniemy podzielić się nią z tymi, którzy będą na tyle mądrzy, aby się do nas przyłączyć. Przez jakiś czas pozostanę na obrzeżach Razorfen Downs.$B$BZ wyrazami szacunku $B$BAmbasador Malcin",
    ["O"] = "Zanieś Small Scroll do Bragora Bloodfista z Undercity.",
    ["T"] = "Przeklęte przymierze",
  },
  [6523] = {
    ["D"] = "Dziękuję za ratunek! Musimy szybko uciekać, zanim odkryją, że jestem wolna. Proszę, odprowadź mnie do Obozu Aparaje. Stamtąd znam już drogę.$B$BMojego ojca - Makabę Flathoofa - bardzo ucieszy wiadomość, że jestem bezpieczna.",
    ["O"] = "Odprowadź Kayę Flathoof do Camp Aparaje, po czym wróć do Makaby Flathoofa, w rejon południowo-wschodniego skraju Stonetalon.",
    ["T"] = "Ochroń Kayę",
  },
  [6541] = {
    ["D"] = "$gByłeś:Byłaś; kiedyś w Ashenvale na północy? Horda niedawno założyła tam placówkę na Wybrzeżu Zoram. Zawsze przyda nam się pomoc nowych rekrutów w obronie naszych nowych frontów.$B$BJeśli sądzisz, że dasz radę, spotkaj się z Kadrakiem w północnym Barrens, w strażnicy. Kieruje kampanią w Ashenvale i może wydać ci dalsze rozkazy.",
    ["O"] = "Zgłoś się do Kadraka, do strażnicy na północnym Barrens.",
    ["T"] = "Zgłoś się do Kadraka",
  },
  [6542] = {
    ["D"] = "$gByłeś:Byłaś; kiedyś w Ashenvale na północy? Horda niedawno założyła tam placówkę w Zoram Strand. Zawsze przyda nam się pomoc nowych rekrutów w obronie naszych nowych frontów.$B$BJeśli sądzisz, że dasz radę, spotkaj się z Kadrakiem w północnych Barrens, w strażnicy. Kieruje kampanią w Ashenvale i może wydać ci dalsze rozkazy.",
    ["O"] = "Zgłoś się do Kadraka, do strażnicy w północnych Barrens.",
    ["T"] = "Zgłoś się do Kadraka",
  },
  [6543] = {
    ["D"] = "Niedawno wysłałem kilku zwiadowców do Ashenvale i potrzebuję kuriera, który mógłby dostarczyć im ich rozkazy, a mnie przekazać raporty z tego, co zaobserwowali.$B$BTwoim pierwszym przystankiem powinna być Placówka Zoram\'gar, położona na zachodnim wybrzeżu, na Wybrzeżu Zoram. Tam znajdziesz pierwszego gońca. Będziesz $gmusiał:musiała; się też zatrzymać w Posterunku Splintertree, na północ stąd oraz przy drodze na wschód, w pobliżu Azshary. Tam z kolei znajdziesz zwiadowcę i jeźdźca.$B$BPrzekaż każdemu raport i odbierz ich sprawozdanie z obserwacji.",
    ["O"] = "Otwórz Bundle of Reports. Zanieś Warsong Reports Zwiadowcy, Gońcowi i Jeźdźcowi klanu Warsong. Przynieś meldunki, które ci przekażą, Kadrakowi ze strażnicy na północnym Barrens.",
    ["T"] = "Raporty Wojennej Pieśni",
  },
  [6544] = {
    ["D"] = "Hej! Chodź tutaj!$B$BJa i moi chłopcy zaraz zaatakujemy posterunek Silverwing na zachód stąd. Naszym celem jest ich przywódczyni, Duriel Moonfire. Ze sprawozdań zwiadowców wynika, że placówka jest silnie chroniona przez wartowniczki i wojowników. To będzie wspaniała bitwa!$B$BChcesz mieć udział w chwale i wspomóc nas? Jeśli tak, to kiedy skończymy, będziesz $gmógł:mogła; zameldować o naszym sukcesie mojemu przełożonemu, Ertogowi Ragetuskowi z posterunku Splintertree.$B$BCo ty na to? Jesteś z nami?",
    ["O"] = "Wspieraj Torka w jego napaści na Silverwing Outpost i Duriel Moonfire. Następnie zdaj raport Ertogowi Ragetuskowi ze Splintertree Post.",
    ["T"] = "Napaść Torka",
  },
  [6545] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Raport Gońca Wojennej Pieśni",
  },
  [6546] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Raport jeźdźca Wojennej Pieśni",
  },
  [6547] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Raport Zwiadowcy Wojennej Pieśni",
  },
  [6548] = {
    ["D"] = "Klan Ponurego Totemu napadł na moją wioskę i prawie wszystkich zabili. Zabiłem ich tyle ile mogłem, ale ledwo uszedłem z życiem.$B$B$N, jedyne czego teraz chce, to to aby więcej ich zginęło. Znajdziesz ich na zachód stąd.",
    ["O"] = "Zabij 8 Grimtotem Ruffians i 6 Grimtotem Mercenaries, po czym wróć do Makaby Flathoof przy południowo-wschodnim krańcu Stonetalon.",
    ["T"] = "Pomścij moją Wioskę",
  },
  [6561] = {
    ["D"] = "Siły mnie opuściły. Potrzebuję twojej pomocy!$B$BDawno temu to miejsce było wspaniałą świątynią Elune. Niestety, popadło w ruinę, gdy trucizna Starych Bogów przesączyła się z głębi ziemi i skaziła świętą księżycową studnię.$B$BZ wód wyłoniła się Aku\'Mai, służebnica Starego Boga.$B$BKultyści Młota Zmierzchu zawarli sojusz z nagami, by opanować tę okolicę. Pod wodzą Kelrisa składają niewinnych w ofierze Aku\'Mai, by zyskać moc.$B$BProszę cię, $N, zabij Kelrisa i zanieś jego głowę do Bashany z Thunder Bluff.",
    ["O"] = "Przynieś Bashanie Runetotem z Thunder Bluff głowę Twilight Lorda Kelrisa.",
    ["T"] = "Nikczemnik z Czarnych Głębin",
  },
  [6562] = {
    ["D"] = "Je\'neu Sancrea potrzebuje pomocy. Czeka u wejścia do Blackfathom Deeps w Ashenvale. Puszcza nocnych elfów znajduje się na północ od Stonetalon Mountains. Możesz tam dotrzeć podróżując przez Windshear Crag, lub kierując się przez Barrens na północ. Zoram Strand leży na zachodnich krańcach lasu. Uważaj, $N. Nie wszyscy przyjmą cię tam z otwartymi ramionami.",
    ["O"] = "Porozmawiaj z Je\'neu Sancreą w Ashenvale.",
    ["T"] = "Kłopoty w Głębinach",
  },
  [6563] = {
    ["D"] = "W początkowych odcinkach korytarzy Blackfathom Deeps wzdłuż ścian znajdują się spore skupiska szafirów. Doniesiono mi ostatnio, że nagi zaczęły zbierać te klejnoty. Dopóki nie dowiemy się, po co to robią, mam przeczucie, że powinniśmy im to uniemożliwić. Kryształy mieszczą w sobie wielką moc żywiołów i niewłaściwie użyte mogą stać się potężnym komponentem magicznym.$B$BPomożesz mi, $N? Blackfathom Deeps znajdują się przy Zoram Strand na północ od naszej placówki.",
    ["O"] = "Przynieś Je\'neu Sancrei z Ashenvale 20 Sapphires of Aku\'Mai.",
    ["T"] = "Esencja Aku\'Mai",
  },
  [6564] = {
    ["D"] = "Pomięta kartka zabazgrana jest brzydkim charakterem pisma.$B$B\'Tak, powiedz wszystkim kapłankom, żeby przynosiły kryształy do mnie. Są w nich dusze silnych żywiołaków wody, które z pewnością wspomogą naszych akwamantów w ich zaklęciach przyzwania.$B$BDzięki zawartej w kryształach mocy udobruchamy Aku\'Mai. Pewno dnia zdobędziemy dość mocy, by sprowadzić ją do nas, zaś świat powróci do swej najwspanialszej ery. Ery rządów Starych Bogów!\'",
    ["O"] = "Zanieś Damp Note do Je\'neu Sancrei z Ashenvale.",
    ["T"] = "Wierność Starym Bogom",
  },
  [6565] = {
    ["D"] = "Nie możemy pozwolić, by kultyści Młota Zmierzchu wprowadzili swój plan w życie. Młot nie rozumie duchów natury. Wierzy w Przedwiecznych Bogów - istoty chaosu i zniszczenia, które zostały pokonane wieki temu. Musisz powstrzymać tego całego Lorgusa. Nie może mu się udać. NPC_GENDER(Sam;Sama) nie dam sobie z tym rady - jestem za NPC_GENDER(słaby;słaba).$B$BUdaj się do Blackfathom Deeps, znajdź go i zabij. Potem wróć do mnie.",
    ["O"] = "Zabij Lorgusa Jetta.",
    ["T"] = "Wierność Przedwiecznym Bogom",
  },
  [6566] = {
    ["D"] = "Dobrze cię znowu widzieć, $N. Wiatr niesie ze sobą wiadomości z Wschodnich Królestw.$B$BUsiądź, posłuchaj.",
    ["O"] = "Posłuchaj co ma do powiedzenia Thrall.",
    ["T"] = "Co Wiatr Niesie",
  },
  [6567] = {
    ["D"] = "Rexxar, jeden z mych najwierniejszych czempionów, odkrył, jak dostać się do smoczego leża. Niestety, opuścił Azeroth i dołączył do ekspedycji badającej Draenor.$B$BJednakże tę informację zna Rokaro, towarzysz Rexxara, przebywający w Wiosce Shadowprey. Odszukaj go.",
    ["O"] = "Odszukaj Rokara w Shadowprey Village w Desolace.",
    ["T"] = "Czempion Hordy",
  },
  [6568] = {
    ["D"] = "Iluzja i przebranie. Oto jak oszukasz czarne smoki i zdobędziesz to, czego szukasz.$B$BChoć mógłbym nauczyć cię co nieco o podstępie, potrzebujesz pomocy mistrza.$B$BZnam pewną osobę, która mogłaby się tym zająć. W Western Plaguelands znajdziesz Wiedźmę Myrandę, niegdysiejszą mistrzynię iluzjonistów z Lordaeronu. Kiedyś już nam pomogła i jeśli uzna, że sprawa jest tego warta, zrobi to ponownie.$B$BZanieś jej tę wiadomość.",
    ["O"] = "Zanieś Rokaro\'s Letter do Myrandy the Hag z Western Plaguelands.",
    ["T"] = "Mistrzyni podstępu",
  },
  [6569] = {
    ["D"] = "Ach, więc $R chce zostać członkiem rodu czarnych smoków, co?$B$BStworzenie samej iluzji jest banalne, ale składniki potrzebne do rzucenia czaru są trudne do zdobycia. Wódz powierzył ci tę misję, więc Myranda musi wierzyć w twoje kompetencje.$B$BUdaj się do górnej cytadeli Blackrock Spire i zabijaj czarnych smoczniaków, aż ich oczy wypełnią ci sakwę.$B$BWróć do Myrandy, gdy będziesz miał dość tego składnika.",
    ["O"] = "Udaj się do Blackrock Spire i zbierz 20 Black Dragonspawn Eyes. Gdy ukończysz to zadanie, wróć do Myrandy the Hag.",
    ["T"] = "Okulusowe iluzje",
  },
  [6570] = {
    ["D"] = "Nasączyłam ten amulet magią niezbędną do stworzenia i utrzymania iluzji w obrębie leża Emberstrife\'a.$B$BEmberstrife to prastary Drakon, stary odźwierny Nefariana. Powierzono mu obowiązek poddawania próbie tych smoczniaków, którzy chcieliby wstąpić w szeregi elitarnych strażników Onyxii.$B$BUdaj się do Wyrmbog, na Dustwallow Marsh, i wejdź do leża Emberstrife\'a. Gdy się tam znajdziesz, załóż amulet i pozwól przeznaczeniu zrobić resztę!",
    ["O"] = "Udaj się do Wyrmbog na Dustwallow Marsh i odszukaj Emberstrife\'s Den. Gdy znajdziesz się w środku, załóż Amulet of Draconic Subversion i porozmawiaj z Emberstrife\'em.",
    ["T"] = "Emberstrife",
  },
  [6571] = {
    ["D"] = "Brakuje nam zaopatrzenia dla obozu drwali Wojennej Pieśni!$B$BPixel ze Posterunku Splintertree ma nasz ładunek pił tarczowych. Zabranie skrzynki toporów będzie wymagało podróży do Booty Bay, do dokmistrza Lozgila.$B$BTrudniej będzie z paliwem i linami. Liny zwędziły nam furbolgi Kolcogrzbiety i te ze szczepu Zgniłej Kniei, natomiast dostawa paliwa została przechwycona przez satyry, które teraz używają go do swoich plugawych obrzędów w Night Run, Satyrnaarze i Xavian!$B$BMożesz mi pomóc?",
    ["O"] = "Zgromadź Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil i Warsong Axe Shipment dla Locke\'a Okarra ze Splintertree Post.",
    ["T"] = "Zaopatrzenie Wojennej Pieśni",
  },
  [6581] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Piły tarczowe Wojennej Pieśni",
  },
  [6582] = {
    ["D"] = "Jesteśmy dziećmi Śmiercioskrzydłego, smoczku. Musimy narzucić słabszym Aspektom naszą dominację.$B$BJeśliś godzien wywyższenia, słabsze rody wypadną przy tobie blado.$B$BZnajdź ich czempionów i zniszcz ich w imię naszego Ojca!$B$BUdaj się do Winterspring i wytrop potężnego niebieskiego drakona, Scryera. Zmiażdż go i każdego z jego sługusów, którzy wejdą ci w drogę. Wyrwij mu czerep i wróć z nim do mnie.",
    ["O"] = "Musisz znaleźć Scryera, czempiona rodu niebieskich smoków, i zabić go. Odrąb mu czerep i przynieś go Emberstrife\'owi.$B$BScryera można znaleźć w Winterspring.",
    ["T"] = "Próba Czaszek - Scryer",
  },
  [6583] = {
    ["D"] = "Musimy brać przykład z naszego Ojca, który zmiażdżył inne Aspekty, i siać chaos i zniszczenie wśród ich potomstwa.$B$BMusisz dowieść swej waleczności w walce z tymi, którzy nie śpią, a śnią: potomstwem rodu zielonych smoków.$B$BUdaj się na Swamp of Sorrows i odnajdź drakona Somnusa, czempiona zielonego rodu. Uwolnij swą nienawiść, zgnieć tego robaka... I wróć do mnie z jego czaszką...",
    ["O"] = "Zniszcz czempiona zielonego rodu, drakona Somnusa. Zabierz jego czaszkę do Emberstrife\'a.",
    ["T"] = "Próba Czaszek - Somnus",
  },
  [6584] = {
    ["D"] = "Strażnicy czasu, dzieci Nozdormu - Władca wieków...$B$BJest ich trzech, co strzegą Grot Czasu, lecz tylko jeden, który utrzymuje zainteresowanie Czarnego Lotu: Time Shifter, Chronalis, faworyzowane smocze dziecię Nozdormu.$B$BUderz w to tak bohaterze, ciosem, który sprawi, że nawet stoickie piaski czasu będą płakać. Powróć do mnie wraz z jego czaszką.",
    ["O"] = "Strażnikiem Grot Czasu na Pustyni Tanaris jest Chronalis, syn Nozdormu. Pokonaj go i przynieś jego czaszkę z powrotem do Emberstrife.",
    ["T"] = "Próba czaszek, Chronalis",
  },
  [6585] = {
    ["D"] = "To było nad górami Grim Batol, gdzie nasz Ojciec wściekł się przeciwko połączonej potędze Aspektów. Tchórzliwy czyn zdrajcy, Alexstraszy, kupił innym Aspektom wystarczająco czasu, by uciekły od Gniewu Ojca.$B$BTaki haniebny czyn...$B$BCzerwony Lot teraz strzeże Grim Batol, ich porucznik, Axtroz, musi zostać zgładzony. Powróć z czaszką Axtroza do mnie. Dla Ojca, szczeniaku!",
    ["O"] = "Wyrusz do Grim Batol i wytrop Axtroza, smoczy czempion Czerwonego Lotu. Pokonaj go i weź jego czaszkę. Powróć z nią do Emberstrife.",
    ["T"] = "Próba czaszek, Axtrox",
  },
  [6601] = {
    ["D"] = "Z czaszek naszych wrogów został ukształtowany medalion. Znasz ten medalion, taaak? Niewątpliwie widziałeś go noszonego przez twoich starszych.$B$BWeź to, szczeniaku. Wróć do Iglicy i pokaż go Generałowi Drakkisath. Generał umieści ostatni czar na medalionie, dostrajając błyskotkę do twojego ducha.$B$BBędziesz nosić ukończony medalion jako odznakę honoru, symbolizującą twoje podniesienie do jednej z naszych najbardziej elitarnych rang: Strażnika Matki lęgu.$B$BRuszaj!",
    ["O"] = "Wygląda na to, że żarty się skończyły. Wiesz, że Amulet of Draconic Subversion, który stworzyła dla Ciebie wiedźma Myranda, nie będzie działał w Iglicy Czarnej Skały. Być może powinieneś znaleźć Rokaro i przedstawić mu swój problem. Pokaż mu amulet Dull Drakefire. Miejmy nadzieję, że będzie wiedział, co dalej.",
    ["T"] = "Podniesienie...",
  },
  [6602] = {
    ["D"] = "Co sądzisz o złożeniu wizyty Generałowi? Tym razem już bez iluzji.$B$BCeremonia? Miłe słowo do opisania krwawej łaźni, która cieszy Czarne Smoki.$B$BWszystkie amulety potrzebują krwi Generała Drakkisathana. Naprawdę prymitywne zabezpieczenia, jest wiele sposobów, by ją zdobyć.$B$BUdaj się do Wież Czarnej Góry i zabij Generała Drakkisathana. Wróć z jego krwią, a ja aktywuję portal do leża Onyxii.",
    ["O"] = "Udaj się w podróż do Wież Czarnej Góry i zabij generała Drakkisathana. Zbierz jego krew i wróć do Rokaro.",
    ["T"] = "Krew Czempiona Czarnego Smoka",
  },
  [6603] = {
    ["D"] = "Kłopoty w Winterspring!$B$BWiesz, spędziłem dość czasu w dziczy i wiem o tych rzeczach... Zawsze mogę z dumą to powiedzieć. Uważam godziny spędzone na wzgórzach za spędzone dobrze. Pomagają w utrzymaniu szybkiego refleksu, chłodnej głowy i uważnego oka...$B$BZrozumienie dziczy w takim stopniu, jak ja to robię, wymaga osądu, rozumu i dorosłości.$B$BWięc, o czym to ja mówiłem?$B$BAch tak, kłopoty. Poszukaj Donovy Snowden przy gorących źródłach, ona powie ci więcej.",
    ["O"] = "Znajdź Donovę Snowden obok gorących źródeł w Winterspring.",
    ["T"] = "Kłopoty w Winterspring!",
  },
  [6604] = {
    ["D"] = "Zauważyłeś opuszczony obóz na południe stąd? Wygląda na to, że Wildkiny oszalały i zniszczyły prawie wszystko, co wpadło im w łapska!$B$BSłyszałem plotkę, że jeden z ocalałych z ataku odpoczywa w Starfall Village, na zachód stąd. Jestem bardzo ciekawy, co się tam wydarzyło... a Ty?",
    ["O"] = "Porozmawiaj z Jaronem Stoneshaperem w Starfall Village.",
    ["T"] = "Rozjuszony Wildkin",
  },
  [6605] = {
    ["D"] = "Właśnie wróciłem z Felwood, $N. Będąc w drodze, zatrzymałem się w Bloodvenom Post i spotkałem kogoś dziwnego... Wyglądała na skupioną na czymś, i przypuszczam że mógłbym ci powiedzieć, co to było, ale myślę, że chciałaby sama ci wyjaśnić.$B$BJeśli jesteś ciekaw, zdążaj do Bloodvenom Post w wschodnim Felwood i szukaj Winny Hazzard.$B$BKto wie, może potrzebować twojej pomocy...",
    ["O"] = "Porozmawiaj z Winna Hazzard w Felwood.",
    ["T"] = "Dziwak",
  },
  [6606] = {
    ["D"] = "Zawsze się przyda trochę szczęścia, co? Mała przewaga to wszystko czego trzeba, żeby obrócić bieg zdarzeń na Twoją korzyść...$B$BJakiś czas temu poznałem dość ekscentryczną znachorkę. Dała mi amulet szczęścia... oczywiście nie za darmo. Ale uwierz mi, było warto!$B$BMoże byłbyś zainteresowany jednym dla siebie? Znajdź znachorkę Mau\'ari w Everlook. Nie oddam ci przecież swojego!",
    ["O"] = "Porozmawiaj ze znachorem Mau\'ari w Everlook.",
    ["T"] = "Trochę szczęścia",
  },
  [6607] = {
    ["D"] = "Nie powiem, żebym czerpał wiele przyjemności z wędkarstwa. Chyba zajmuję się tym już od dobrych 20-30 lat.$B$BMPrzypuszczam, że nie z takich przyczyn ludzie zmotywowani są do swoich zajęć.$B$BNie twierdzę, że musisz wędkować przez 30 lat albo złowić każdą rybę w morzu i aby stać się mistrzem wędkarstwa. Potrzeba raczej zwykłej determinacji - wystarczającej determinacji, żeby godzinami siedzieć na zadku, nie robiąc nic.$B$BWiesz co, złów mi kilka rzadkich ryb, a nauczę cię sztuczki albo dwóch. Oto lista:",
    ["O"] = "Nat Pagle chce, żebyś $gzłowił:złowiła; następujące ryby:$B$BMisty Reed Mahi Mahi z Misty Reed Strand w Swamp of Sorrows.$B$BSar\'theris Striker z Sar\'theris Strand w Desolace.$B$BFeralas Ahi z Verdantis River w Feralas.$B$BSavage Coast Blue Sailfin z Savage Coast w Stranglethorn Vale.$B$BWróć do Nata Pagle\'a, kiedy już wszystkie wyłowisz!",
    ["T"] = "Nat Pagle, Wędkarz Ekstremalny",
  },
  [6608] = {
    ["D"] = "Lumak nie może uczyć $N dalej. Ty za $gdobry:dobra;! Znajdź kolegę Lumaka, Nata Pagle. Człowiek, ale ja go nie je! Lumaka to kolega! Nat nauczy łowić lepiej.$B$BTy znajdziesz Nat w Dustwallow Marsh, na południe od wioski ludziów, Termosczy-jakoś-tak. Nat pewnie łowi. Idź już!",
    ["O"] = "Wydaje ci się, że Lumak próbuje ci powiedzieć, iż nie może dłużej pomagać ci poprawiać twoją umiejętność łowienia ryb. Możesz spróbować znaleźć jego przyjaciela, Nata Pagle, człowieka łowiącego na jednej z wysepek na południe od Theramore (przynajmniej tak powiedział Lumak)",
    ["T"] = "Ty za dobry!",
  },
  [6609] = {
    ["D"] = "Jo żym jest beczący krasnolud, $gchłopcze:dziewuszko;! Nie był żem zaprojektowany do łowienia! Popacz na mnie! Całym z kamienia.$B$BNic więcej nie umiem - $gprzebiłeś:przebiłaś; mnie. Nauczył żem cię wszystkiego, co umie!$B$BNie czaisz? Ach, dobra. Mam starego towarzysza w Kalimdorze, który pewnikiem ci pomoże. Zowie się Nat Pagle, zuch chłop. Znajdziesz go na wyspie, na południe od Theramore. Zawijaj!",
    ["O"] = "Udaj się do Kalimdoru, do przybrzeżnego miasta Theramore. Po dotarciu będziesz $gmusiał:musiała; odnaleźć wyspę leżącą na południe od portu. Nat Pagle oczekuje twojego przybycia!",
    ["T"] = "Nic mnie nie zostało!",
  },
  [6610] = {
    ["D"] = "$gSłyszałeś:Słyszałaś; kiedyś o małżmletach? Oczywiście, że nie! To jest moje ostatnie i najlepsze kulinarne dzieło. Och, $N, sama myśl o małżmletach powoduje, że cieknie mi ślinka.$B$BNiestety nie mam zapasów żeby je zrobić. Co ty na to, abyśmy zawarli umowę? Ty zbierasz produkty, a ja zrobię małżmlety i nauczę cię niuansów kuchni egzotycznej oraz dam ci parę na drogę! Zgoda??$B$BTo czego potrzebuje to:",
    ["O"] = "Dirge Quikcleave chce, abyś $gzdobył:zdobyła; dla niego:$B$B12 dużych jaj.$BZnajdziesz je przy myszołowach wędrujących po Tanaris albo przy innych gatunkach dużych ptaków.$B$B10 kawałków Zesty Clam Meat.$BZnajdziesz je naturalnie w małżach!$B$B20 kawałków Alterac Swiss.$BWstąp do sklepu z serami!$B$BZbierz wszystkie te rzeczy i wróć do Dirge.",
    ["T"] = "Niespodzianka młażmletowa",
  },
  [6611] = {
    ["D"] = "Jak możesz oczekiwać od Zemja, że nauczy cie wszystkiego? Rozumiesz jak robić wszystkie mojo Zemja i nadal pragniesz więcej!$B$BZamja już tu nie pomoże. Tłusty $R musi iść do Gadgetzan. Znajdziesz tam małego goblina o imieniu Dirge - on ci pomoże, tłuściochu.$B$BKiedy staniesz się szefem kuchni, przyjdziesz pouczyć Zemja, dobra? A teraz idź!",
    ["O"] = "Idź do Gadgetzan na pustyni Tanaris i porozmawiaj z Dirge Quikcleave o polepszeniu twoich zdolności kucharskich.",
    ["T"] = "Idź do Gatgetzan!",
  },
  [6612] = {
    ["D"] = "Patrząc na twój warsztat widzę, że się znasz na rzeczy i wiesz, co robisz. Nie jestem w stanie nauczyć cię wiele więcej.$B$BPoszczęściło ci się, bo znam faceta, który może ci pomóc. Jest goblinem, prawdopodobnie najlepszym kucharzem na całym Kalimdorze.$B$BTa, to ta zła wiadomość, $gchłopcze:dziewczyno; musisz się udać aż na Kalimdor. Udaj się do miasta Gadgetzan i odnajdź Dirge\'a Quickcleave\'a. On już cię dalej wyuczy.",
    ["O"] = "Udaj się do Gadgetzanu na pustyni Tanaris i porozmawiaj Dirgem Quikcleaverem o przyszłości twojej kariery kucharskiej.",
    ["T"] = "Znam jednego faceta...",
  },
  [6621] = {
    ["D"] = "$B, na południowy wschód od Astranaaru żyje jeszcze inne plemię furbolgów - plemię Plugawej Kniei. Nie są tak liczne jak Kolcogrzbiety, ale ich dzikie zachowania mogą nam zagrozić w najbliższej przyszłości. Przy użyciu odrobiny siły, jesteśmy w stanie zażegnać to zagrożenie. Weź ten baner do wioski furbolgów Plugawej Kniei i umieść go na ich kopcu totemów. Będą próbować go zniszczyć, ale stawiaj im opór dopóki ich wódz, Murgut, pojawi się, by zachować godność plemienia. Przynieś mi totem, który nosi.$B$BZbierz swych sojuszników, $N. To nie jest zadanie dla $gzwykłego:zwykłej; $C.",
    ["O"] = "Umieść Karang\'s Banner na Foulweald Totem Mound. Nie pozwól furbolgom zniszczyć banera. Pokonaj herszta Murguta i przynieś Murgut\'s Totem do Amakkara w Silverwind Refuge.",
    ["T"] = "Król Zgniłej Kniei",
  },
  [6622] = {
    ["D"] = "Dzień dobry, doktorze. Tego popołudnia poddamy ocenie twoją zdolność do właściwej oceny stanu zdrowia pacjentów. Jeśli zdasz ten egzamin, dołączysz do prestiżowego Oddziału Urazowego Hordy.$B$BTeraz uważaj! Najpierw należy zająć się krytycznie rannymi. Po nich przyjdzie czas na poważnie rannych. Rannych należy zostawić na koniec. Aby zdać egzamin, musisz ocalić 15 pacjentów. Jeśli 6 pacjentów umrze w trakcie egzaminu, oblejesz.$B$BBandaże selekcyjne zostaną ci zapewnione.$B$BPowodzenia, doktorze.",
    ["O"] = "Uratuj pacjentów, używając Bandaży Selekcyjnych, by opatrzyć ich rany. Musisz ocalić 15 pacjentów, nim 6 z nich umrze z powodu ran.$B$BPamiętaj o właściwej kolejności niesienia pomocy! Pierwsi umrą Krytycznie Ranni Żołnierze, zaraz po nich Poważnie Ranni Żołnierze. Ranni Żołnierze przeżyją najdłużej, więc należy zająć się nimi już PO opatrzeniu Krytycznie Rannych i Poważnie Rannych Żołnierzy.",
    ["T"] = "Selekcja rannych",
  },
  [6623] = {
    ["D"] = "Doktor $N, jak sądzę. Miło cię znowu widzieć.$B$BMam dla ciebie wspaniałe wieści! Doktor Gregory Victor, ordynator Oddziału Urazowego Hordy, osobiście wyraził życzenie, abyś $gdołączył:dołączyła; do niego w Hammerfall. To może być twoja życiowa szansa! Oddałbym wszystko, by móc studiować pod okiem wielkiego doktora Gregory\'ego Victora! Nie zmarnuj jej!",
    ["O"] = "Udaj się do Hammerfallu w Arathi Highlands i porozmawiaj z doktorem Gregorym Victorem o wstąpieniu w szeregi Horde Trauma.",
    ["T"] = "Oddział Urazowy Hordy",
  },
  [6624] = {
    ["D"] = "Dzień dobry, doktorze. Tego popołudnia poddamy ocenie twoją zdolność do właściwej oceny stanu zdrowia pacjentów. Jeśli zdasz ten egzamin, dołączysz do prestiżowego grona członków Oddziału Urazowego Przymierza.$B$BTeraz uważaj! Najpierw należy zająć się krytycznie rannymi. Po nich przyjdzie czas na poważnie rannych. Rannych należy zostawić na koniec. Aby zdać egzamin, musisz ocalić 15 pacjentów. Jeśli 6 pacjentów umrze w trakcie egzaminu, oblejesz.$B$BBandaże selekcyjne zostaną ci zapewnione.$B$BPowodzenia, doktorze.",
    ["O"] = "Uratuj pacjentów, używając Bandaży Selekcyjnych, by opatrzyć ich rany. Musisz ocalić 15 pacjentów, nim 6 z nich umrze z powodu ran.$B$BPamiętaj o właściwej kolejności niesienia pomocy! Pierwsi umrą Krytycznie Ranni Żołnierze, zaraz po nich Poważnie Ranni Żołnierze. Ranni Żołnierze przeżyją najdłużej, więc należy zająć się nimi już PO opatrzeniu Krytycznie Rannych i Poważnie Rannych Żołnierzy.",
    ["T"] = "Selekcja rannych",
  },
  [6625] = {
    ["D"] = "Doktor $N, jak sądzę. Miło cię znowu widzieć.$B$BMam dla ciebie wspaniałe wieści! Doktor Gustaf VanHowzen, ordynator Oddziału Urazowego Przymierza, osobiście wyraził życzenie, abyś $gdołączył:dołączyła; do niego w Theramore. To może być twoja życiowa szansa! Oddałbym wszystko, by móc studiować pod okiem wielkiego Doktora Gustafa VanHowzena! Nie zmarnuj jej!",
    ["O"] = "Udaj się w podróż do Theramore w Dustwallow Marsh i porozmawiaj z doktorem Gustafem VanHowzenem o wstąpieniu w szeregi Alliance Trauma.",
    ["T"] = "Oddział Urazowy Przymierza",
  },
  [6626] = {
    ["D"] = "Z tego co widziałam, Opuszczeni nie przekazują dalej swojej... choroby... Ten dyplomata wydawał się obiecywać życie poza życiem potencjalnym poplecznikom. Zaczynam sądzić, że należy do Plagi.$B$BJednak póki co, nie on stanowi główny problem, a rosnące wokół niego szeregi. Codziennie wypełzają z cieni, niemalże błagając go o więcej mocy.$B$BNie jestem dość potężna, by walczyć z nimi pojedynkę, $N. Co powiesz? Masz chęć zapolować?",
    ["O"] = "Zabij 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death\'s Head Cultists, po czym wróć do Myriam Moonsinger, przebywającej w pobliżu wejścia do Razorfen Downs.",
    ["T"] = "Siewca zła",
  },
  [6627] = {
    ["D"] = "Przyniosłeś mi książkę, a teraz nadszedł czas na twoje pytanie. Jesteś gotowy?$B$BCzas nie gra roli, $C, więc się nie stresuj. Na odpowiedź masz tyle czasu, ile zechcesz.",
    ["O"] = "Odpowiedz poprawnie na pytanie Brauga Dimspirita, a później ponownie z nim porozmawiaj. Pozostanie w Stonetalon Mountains, aż będziesz gotowy.",
    ["T"] = "Próba Wiedzy",
  },
  [6628] = {
    ["D"] = "Zatem nadszedł czas na naszą kolejną rozmowę. Jako student, wykazałeś wielką wytrwałość, podejmując się mojego zadania.$B$BI tak oto zadam ci teraz twoje pytanie. Kiedy będziesz gotowy, odezwij się do mnie ponownie. Nie musisz się spieszyć $N, odpowiedź nie musi paść szybko.",
    ["O"] = "Odpowiedz poprawnie na pytanie Parquala Fintallasa, a później ponownie z nim porozmawiaj. Pozostanie w Undercity, aż będziesz gotowy.",
    ["T"] = "Próba Wiedzy",
  },
  [6629] = {
    ["D"] = "$N, $gwykonałeś:wykonałaś; świetną robotę zabijając członków klanu Ponurego Totenu. Jeśli się odważysz, to Grundig Darkcloud i jego prywatna banda osiłków są znacznie gorsi od reszty. To on przewodził bestialskiemu atakowi na moją wioskę.$B$BZnajdziesz go w Posterunku Ponurych Totemów, trochę dalej pod górę ścieżką na zachód. Zabij go, a będę ci dozgonnie wdzięczny.",
    ["O"] = "Zabij Grundiga Darkclouda i 6 Grimtotem Brutes, po czym wróć do Makaby Flathoofa, przebywającego w pobliżu południowo-wschodniego krańca Stonetalon.",
    ["T"] = "Zabij Grundiga Darkclouda",
  },
  [6641] = {
    ["D"] = "Vorsha the Lasher... diabelska hydra przemierzająca morza...$B$BAtakowała nasz posterunek, za każdym razem bez powodu, niszcząc wszystko, co stanęło jej na drodze.$B$BLecz ja jestem gotów, $N. Przygotowałem się, by pokonać hydrę i zakończyć jej ataki na Zoram\'gar.$B$BNagi oddają cześć tej dzikiej bestii podtrzymując ogień w żarniku na wyspie nieopodal brzegu. Sądzę, że jeśli go ugasimy, pojawi się rozgniewana Vorsha.$B$BBędziemy potrzebować pomocy, więc koniecznie przyprowadź potężnych przyjaciół.",
    ["O"] = "Chroń Muglasha podczas podróży do koksownika. Pomóż mu go zgasić, a później ochraniaj go walcząc z nagami.$B$BJeśli się wam uda, wróć do Zoram\'gar Outpost i przekaż do Warsong Runner nowinę o śmierci Vorsha the Lasher.",
    ["T"] = "Vorsha the Lasher",
  },
  [6642] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Przychylność Bractwa, ruda Czarnego Żelaza",
  },
  [6643] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Przychylność Bractwa, Ognisty Rdzeń",
  },
  [6644] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Przychylność Bractwa, Rdzeń Lawy",
  },
  [6645] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Przychylność Bractwa, rdzenne skóry",
  },
  [6646] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Przychylność Bractwa, Krew Góry",
  },
  [6661] = {
    ["D"] = "Stój łobuzie. Arrrr... Arrrr, szukasz roboty? Mamy tu poważny problem ze szczurami i za mało rąk do pracy na tylnym pokładzie.$B$BCo rzekniesz? Wszystko, co trza zrobić, to wziąć ten flet szczurołapa i zagrać szkodnikom. Pójdą za tobą na koniec świata!$B$BWystarczy, że złapiesz pięć tych małych gnojków i je tu sprowadzisz. Potrzebujemy ich żywych.$B$BArrrrr...",
    ["O"] = "Za pomocą Rat Catcher\'s Flute schwytaj 5 Deeprun Rats. Przyprowadź szczury do Monty\'ego. Nie zapomnij oddać mu fletu, gdy skończysz.",
    ["T"] = "Obława na szczury kolejkowe",
  },
  [6662] = {
    ["D"] = "Mój brat Nipsy, prowadzi kebaba na drugim końcu Deeprun. Chcę, żebyś $gzabrał:zabrała; do niego tę skrzynkę szczurów zanim zemrą. Ruszajże!$B$B$gJechałeś:Jechałaś; kiedy kolejką? To proste. Siadaj na nią jak przybędzie i ciesz się z jazdy. Tylko trzymaj giczoły w środku, bo ci pourywa.",
    ["O"] = "Dostarcz Carton of Mystery Meat Nipsy\'emu w Stormwind Deeprun Tram Depot.",
    ["T"] = "Mój braciszek, Nipsy",
  },
  [6681] = {
    ["D"] = "$N,$B$BRavenholdt zainteresował się twoją osobą, młody łotrze. Obserwowaliśmy cię przez jakiś czas. Jesteś trochę $gniezdarny:niezdarna;, ale myślę, że jakoś sobie z tym poradzimy.$B$BJeśli jesteś $ggotowy:gotowa; na rozpoczęcie kariery $gucznia:uczennicy; Mistrza Ravenholdta oraz $gczłonka:członkini; Ligi Zabójców jedyne, co musisz zrobić, to dostarczyć dołączoną do tego listu Pieczęć Ravenholdt do Dworu Ravenholdt.$B$BTwoim pierwszym zadaniem jest odnaleźć dwór ukryty pośród wzgórz Hillsbrad i dowieść swego sprytu.$B$BPozdrawiam,$B$BFahrad",
    ["O"] = "Zabierz Seal of Ravenholdt do Fahrada, urzędującego w Ravenholdt Manor ukrytym gdzieś pośród wzgórz Hillsbrad.$B$BTa wyprawa podda sprawdzianowi twój spryt. Bądź na to $ggotowy:gotowa;.",
    ["T"] = "Dwór Ravenholdt",
  },
  [6701] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Odznaki Syndykatu",
  },
  [6721] = {
    ["D"] = "Witaj, $gmłody:młoda; $C. Wyglądasz mi na dość $gdoświadczonego:doświadczoną;, by poradzić sobie z oswojeniem zwierzęcia i wytrenowaniem go na swojego towarzysza.$B$BMusisz porozmawiać z Dazalarem z Dolanaaru. On wprowadzi cię na ścieżkę, która nauczy cię, jak zdobyć własne zwierzę.",
    ["O"] = "Porozmawiaj z Dazalarem z Dolanaaru.",
    ["T"] = "Ścieżka łowcy",
  },
  [6722] = {
    ["D"] = "Witaj, młody łowco. Wyglądasz mi na dość $gdoświadczonego:doświadczoną;, by poradzić sobie z oswojeniem zwierzęcia i wytrenowaniem go na swojego towarzysza.$B$BMusisz porozmawiać z Dazalarem z Dolanaaru. On wprowadzi cię na ścieżkę, która nauczy cię jak zdobyć własne zwierzę.",
    ["O"] = "Porozmawiaj z Dazalarem z Dolanaaru na Teldrassilu.",
    ["T"] = "Ścieżka łowcy",
  },
  [6741] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Więcej łupu!",
  },
  [6761] = {
    ["D"] = "Oddelegowałem mojego sekundanta, Mathrengyla Bearwalkera, żeby zorganizował pomoc dla oddziałów w Moonglade. Pomów z nim o tej sprawie - NIE ze mną.$B$BPozwól, że udzielę ci... przyjacielskiej... porady. To ja wyciągnąłem nas ze szponów ciemności - nie Krąg Cenariusa w Moonglade - kiedy wszystko było stracone dla naszego ludu. Drzewo Teldrassil dało nam wszystkim nowe życie! Oni chcą, żebyś $gmyślał:myślała; inaczej; a wierząc w ich propagandę, $gokazałbyś się głupcem:okazałabyś się głupia;.$B$BPozostawię w twojej gestii zdecydowanie czy jesteś $ggłupcem:głupia;, czy też nim nie jesteś.",
    ["O"] = "Pomów z Mathrengylem Bearwalkerem w Enklawie Cenarion na terenie Darnassusu.",
    ["T"] = "Nowe Pogranicze",
  },
  [6762] = {
    ["D"] = "Do tego zadania, majordomus Opiekuna Remulosa w Moonglade - Rabine Saturna - potrzebuje pomocy w eksploracji rozległych pustkowi na daleki zachód od Tanaris... aż za Kraterem Un\'Goro. $gPowinieneś:Powinnaś; odnaleźć go w Nighthaven, głównej osadzie Moonglade.$B$BTwoje działania bez wątpienia przyniosą nam wszystkim ogromne korzyści, tymczasem krocz z rozwagą. Sytuacja pomiędzy Darnassusem, a Moonglade jest napięta... z czasem może się jeszcze bardziej zaostrzyć.",
    ["O"] = "Pomów z Rabinem Saturną we wiosce Nighthaven, na terenie Moonglade. Moonglade leży pomiędzy Felwood i Winterspring, najlepiej dostać się tam przez Timbermaw Hold.",
    ["T"] = "Rabine Saturna",
  },
  [6781] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Więcej Fragmentów Pancerzy",
  },
  [6801] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Lokholar Lord Lodu",
  },
  [6804] = {
    ["D"] = "Oddział żywiołaków-zwiadowców został wysłany do Eastern Plaguelands Lordaeronu, schorzenie tamtej krainy przeinaczyło i zatruło ich. Lordowie Żywiołu Wody nie mogą puścić tego afrontu płazem!$B$BWeź tę fiolkę. Zawiera ona dozę aspektu Neptulona. Jeżeli zaaplikujesz jej zawartość splugawionym żywiołakowom, zwalczy ona truciznę w ich ciałach i wyleczy ich! Ale ich wewnętrzny konflikt doprowadzi ich do wzbierającego szaleństwa.$B$BPokonaj oszalałe żywiołaki i przynieś mi wiążące je naramienniki.",
    ["O"] = "Użyj Aspect of Neptulon na zatrutych żywiołakach w Eastern Plaguelands. Przynieś 12 Discordant Bracers i Aspect of Neptulon do Duke Hydraxis w Azshara.",
    ["T"] = "Zatruta Woda",
  },
  [6805] = {
    ["D"] = "My, żywiołaki wody, prowadzimy wojnę z tymi związanymi z pomniejszymi żywiołami. Jeśli rzeczywiście jesteś po naszej stronie w tym konflikcie, pokaż mi swoje zaangażowanie w naszą sprawę!$B$BDaleko na południe, w pustynnej krainie Silithus, słudzy powietrza i ziemi gnieżdżą się na skrawku skały, zwanej Crystal Vale. Chronią potężne przedmioty przed słabszymi istnieniami - śmiertelnymi i pomimo tego, że nie znam ich intencji, to zamierzam zapobiec ich działaniom.$B$BUdaj się do Crystal Vale w Silithus i pokonaj naszych wrogów, potem powróć do mnie.",
    ["O"] = "Zabij 15 Dust Stormers i 15 Desert Rumblers, a potem powróć do Diuka Hydraxisa w Azsharze.",
    ["T"] = "Słudzy Powietrza i Ziemi",
  },
  [6821] = {
    ["D"] = "Pokaż mi, jak pokonujesz naszych wrogów i jak wykonujesz dalsze misje, by przyczynić się do powstania Waterlords. Ale jak na razie miałeś słabych przeciwników... jeśli zmierzysz się z potężnym wrogiem, czy dasz mu radę??$B$BTo jest twoje nowe zadanie.$B$BNa szczycie Blackrock Spire orki złapały sługę ognia Pyroguarda Emberseer. Znajdź miejsce, gdzie został uwięziony, zabij tych, którzy go złapali, a następnie zabij Emberseera. Przynieś mi jego oko, w ten sposób pokażesz mi swoją wartość.",
    ["O"] = "Weź Eye of the Emberseer do Duke Hydraxis w Azshara.",
    ["T"] = "Oko Emberseera",
  },
  [6822] = {
    ["D"] = "$N, być może nadszedł czas, aby poddać Cię prawdziwej próbie. Czy jesteś gotowy?$B$BNa dnie Blackrock Depths znajduje się przejście do Molten Core. Jest to bastion naszego przeciwnika, opanowana przez najpotężniejsze sługi ognia znane na tym świecie.$B$BIdź do Molten Core, $N. Pokaż mi swoją siłę, pokaż mi, że jesteś zdolny pokonać to, co znajdziesz w czeluściach tej fortecy.$B$BI jeżeli masz sprzymierzeńców wśród swego ludu, zwołaj ich. Nic mniejszego, niż armia, nie może liczyć na to, że wchodząc do Molten Core powróci żywa.",
    ["O"] = "Zabij 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound i 1 Lava Surger, po czym wróć do Dukea Hydraxisa w Azshara.",
    ["T"] = "Molten Core",
  },
  [6823] = {
    ["D"] = "Jeśli naprawdę chcesz być z nami przywiązany, wtedy zaproszę ciebie do wojny z naszymi nieprzyjaciółmi, sługami wiatru, ziemi i ognia. Każda ich porażka osłabi ich grunt, na którym tutaj stoją i w dalszym ciągu udowodnisz, że jesteś przychylny naszej sprawie.$B$BKampania będzie długa, ale jeśli wytrwasz, wtedy twoja chwała i honor będą wspaniałe.",
    ["O"] = "Zdobądź honorową reputację z frakcją Hydraxian Waterlords, następnie porozmawiaj z Duke Hydraxis w Azshara.",
    ["T"] = "Agent Hydraxis",
  },
  [6824] = {
    ["D"] = "$N, twoje usługi są bardzo cenne dla nas, więc niechętnie wysyłamy cię do tej ostatniej misji, bo nie chcemy stracić tak użytecznego agenta.$B$BAle jego sukces znacznie wzmocniłby nasze wysiłki wojenne i... uznaliśmy, że warto ciebie zaryzykować.$B$BChcemy, by kapitanowie w Molten Core zostali zniszczeni: Lucifron, Sulfuron, Gehennas i Shazzrah. Zabij ich i przynieś mi ich ręce!$B$BTo zadanie zabierze wszystkie zasoby, które posiadasz, $N, ale jeśli to zrobisz, wtedy Firelords otrzymają straszliwy cios.",
    ["O"] = "Weź rękę Lucifron, Sulfuron, Gehennas i Shazzrah do Duke Hydraxis w Azshara.",
    ["T"] = "Ręce wrogów",
  },
  [6825] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Wezwanie powietrza - flota Guse",
  },
  [6826] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Zew Powietrza - Oddział Jeztor",
  },
  [6827] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Zew Powietrza - Oddział Mulverick",
  },
  [6841] = {
    ["D"] = "x",
    ["O"] = "x",
    ["T"] = "<UNUSED>",
  },
  [6842] = {
    ["D"] = "x",
    ["O"] = "x",
    ["T"] = "<UNUSED>",
  },
  [6844] = {
    ["D"] = "Wciąż mamy tutaj ręce pełne roboty, jednak myślę, że poddanie tego analizie w Kręgu jest kluczowe. Uwierz mi - pracy nie zabraknie nawet, kiedy wszystko będzie już załatwione. Jeśli w tej lepkiej chitynie ukryty jest dziennik, Krąg w końcu miałby wgląd w przeszłość!$B$BZabierz to do archiwisty Kręgu w Nighthaven. Nazywa się Umber i jest prawdziwym geniuszem. Lekko stukniętym, ale wciąż geniuszem! Tomy, które ocalił Umber, były w dużo gorszym stanie, niż to. Jeśli da się to jakoś uratować, on potrafi to zrobić.",
    ["O"] = "Zanieś ten Encrusted Silithid Object do Umbera - archiwisty Kręgu Cenarion - w wiosce Nighthaven, Moonglade.",
    ["T"] = "Umber, Archiwista",
  },
  [6845] = {
    ["D"] = "Tak czy inaczej, $gpowinieneś:powinnaś; skontaktować się ze mną szybko... To znaczy, jak chcesz się dowiedzieć, jak tu było wcześniej. Tak szybko, jak dowiem się, co to jest, i jeśli to naprawdę jest książka, z radością podzielę się z tobą tą informacją.$B$BW międzyczasie, zamelduję się u Matki Legowiska z tego małego niedźwiedziego obozu, Rabine. Bez wątpienia będzie chciał wiedzieć na jakie zwariowane antyki natrafisz. Nigdy nie każ Matce Legowiska czekać, $N... To znaczy, chyba że chcesz być $goblany:oblana; miodem.$B$BTo się zdarza, wierz mi.",
    ["O"] = "Porozmawiaj z Rabine Saturna w wiosce Nighthaven, Moonglade.",
    ["T"] = "Odkrywanie sekretów przeszłości",
  },
  [6846] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Zacznijmy Atak!",
  },
  [6847] = {
    ["D"] = "Wasza wojna w sercu Alterac nie ma znaczenia dla Syndykatu, $C. Będziemy postępować tak samo, jak do tej pory: zaczekamy, aż z gruzów i popiołów podniesie się zwycięzca i wtedy uderzymy.$B$BObecnie jednak nie jest to powodem, dla którego jesteśmy teraz tutaj. Straciliśmy The All Seeing Eyy - zostało zabrane przez trole Winterax tego regionu.$B$BOdzyskaj the Eye, a udostępnimy Ci nasze usługi - przynajmniej dopóki twoja frakcja nie upadnie.$B$BWróć do mnie, kiedy zdobędziesz oko, abym mógł Cię zweryfikować.$B$B<Na twarzy Master Rysona pojawia się szeroki uśmiech.>",
    ["O"] = "Odzyskaj Master Ryson\'s All Seeing Eye z jaskini Winterax i zwróć je do Master Ryson.$B$BStrzeż się, gdyż mówi się, że na Master Ryson\'s All Seeing Eye spoczywa okropna klątwa!",
    ["T"] = "Oczy wszystkich widzących Mistrza",
  },
  [6848] = {
    ["D"] = "Twoja wojna w sercu Alterac nic nie znaczy dla Syndykatu, $C. Zrobimy tak jak zawsze robiliśmy: zaczekaj, aż z tego popiołu i kurzu wyjdzie czysty zwycięzca, a następnie ich uderz.$B$BTo jednak nie dlatego tu jesteśmy. Wszystko widzące oko zostało stracone - wzięte przez trolle regionu Winterax.$B$BOdzyskaj oko i nasze usługi bedą twoje - tak długo jak pozostanie pod twojej stronie.$B$BWróć do mnie raz jeszcze, gdy zdobędziesz oko, wtedy będę mógł sprawdzić.$B$B<Master Ryson uśmiecha się.>",
    ["O"] = "Odzyskaj Master Ryson\'s All Seeing Eye z Winterax caves i wróć z nim do Master Ryson.$B$BUważaj, mówi się, że Master Ryson\'s All Seeing Eye niesie ze sobą jakieś straszliwe przekleństwo!",
    ["T"] = "Master Ryson Wszystko widzące oko",
  },
  [6861] = {
    ["D"] = "Tak jak i ty nie mogę się doczekać tego, by wypróbować mój przenośny szatkownik, $R7, ale zanim go złożymy, będę potrzebować materiałów - i to dużo!$B$BA dokładnie mówiąc, góry toru, mithrilu i żelaza. Będę potrzebować też piły parowej. Będziesz $gmusiał:musiała; zdobyć je w tartaku.$B$BKiedy węszyłem w obozie drwali Burzowych Pik (zanim mnie pojmali), zauważyłem stertę pił.",
    ["O"] = "Mistrz inżynierii Zinfizzlex chce, byś $gprzyniósł:przyniosła; mu następujące rzeczy:$B$B*30 Thorium Bars.$B$B*50 Mithril Bars.$B$B*75 Iron bars.$B$B*1 Steamsaw.",
    ["T"] = "Przenośny szatkownik Zinfizzlexa",
  },
  [6862] = {
    ["D"] = "Tak jak i ty nie mogę się doczekać tego, by wypróbować mój przenośny szatkownik, $R7, ale zanim go złożymy, będę potrzebować materiałów - i to dużo!$B$BA dokładnie mówiąc, góry toru, mithrilu i żelaza. Będę potrzebować też piły parowej. Będziesz $gmusiał:musiała; zdobyć je w tartaku.$B$BKiedy węszyłem w obozie drwali Mroźnych Wilków (zanim mnie pojmali), zauważyłem stertę pił.",
    ["O"] = "Mistrz inżynierii Zinfizzlex chce, byś $gprzyniósł:przyniosła; mu następujące rzeczy:$B$B*30 Thorium Bars.$B$B*50 Mithril Bars.$B$B*75 Iron bars.$B$B*1 Steamsaw.",
    ["T"] = "Przenośny szatkownik Zinfizzlexa",
  },
  [6881] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Ivus Władca Lasu",
  },
  [6901] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Rozpocząć Atak!",
  },
  [6921] = {
    ["D"] = "Młot Zmierzchu skierował się do Ruin Sanktuarium Księżyca w Blackfathom Deeps. Ich obecność może mieć tylko jeden cel - zwrócenie żywiołów przeciw nam. Jeżeli ich nie powstrzymamy, ten region pozostanie pod ich panowaniem na dobre.$B$BRuszaj w Blackfathom i znajdź głębinowy kamień ruin; powinien spoczywać gdzieś blisko wody. W nim znajduje się Fathom Core - odpowiednio go używając, będziemy mogli odczytać historię aktywności żywiołów. Jeżeli znajdę się w jego posiadaniu, ja i Krąg Ziemi być może będziemy w stanie zrobić coś, by ich powstrzymać!",
    ["O"] = "Przynieś Fathom Core do Je\'neu Sancrei z Zoram\'gar Outpost w Ashenvale.",
    ["T"] = "Pośród ruin",
  },
  [6922] = {
    ["D"] = "Pokonany żywiołak wody pozostawił po sobie dziwną kulę wody. Przypuszczasz, że ten przedmiot wchłonął w jakiś sposób energię bestii. Wewnątrz kuli chlupocze paskudnie wyglądająca breja. Kula sama w sobie wydaje się niewrażliwa na żaden rodzaj siły fizycznej.$B$BJeżeli ktokolwiek może zrozumieć coś z tego przedmiotu, jest nim Je\'neu Sancrea z Kręgu Ziemi. Obecnie przebywa w Posterunku Zoram\'gar w Ashenvale.",
    ["O"] = "Przynieś Strange Water Globe do Je\'neu Sancrei z Zoram\'gar Outpost w Ashenvale.",
    ["T"] = "Baron Aquanis",
  },
  [6941] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Zew Powietrza - Oddział Vipore",
  },
  [6942] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Zew Powietrza - Oddział Slidore",
  },
  [6943] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Zew wiatru - Flota Ichmana",
  },
  [6961] = {
    ["D"] = "Życzę ci cudownego Święta Zimy, $gprzyjacielu:przyjaciółko;! Upewnij się, że $gprzywitałeś:przywitałaś; się z Zimowym Dziadkiem! Jeśli $gbyłeś:byłaś; $ggrzeczny:grzeczna; w tym roku, otrzymasz wspaniałe prezenty z okazji świąt. Nie zapomnij powiedzieć mu, co chcesz dostać w tym roku!$B$BUpewnij się także, że $gzebrałeś:zebrałaś; dostatecznie dużo smakołyków, aby podzielić się z tymi, którzy byli grzeczni w tym roku. Mamy wspaniały wybór wśród smakołyków. Świeżo z naszej farmy, prosto na twój talerz - to smakowita dobroć od Smokywood Pastures!",
    ["O"] = "Porozmawiaj z Great-father Winter; znajduje się on nieopodal Smokywood Pastures w strefie kupieckiej w Orgrimmarze.",
    ["T"] = "Zimowy Dziadek już tu jest!",
  },
  [6962] = {
    ["D"] = "Hej, możesz zrobić Zimowemu Dziadkowi przysługę?$B$BNie chcę niepotrzebnie mówić o sobie w trzeciej osobie, ale Zimowy Dziadek spędza tu całe dnie i sam chętnie by coś przekąsił. Kilka korzennych ciasteczek i zmrożone mleko do popicia będą w sam raz. Będziesz tak $gdobry:dobra; i przyniesiesz mi je?",
    ["O"] = "Przynieś 5 Gingerbread Cookies i Ice Cold Milk dla Great-father Winter w Orgrimmarze.",
    ["T"] = "Smakołyki dla Zimowego Dziadka",
  },
  [6963] = {
    ["D"] = "Posłuchaj... Nie chce zepsuć magii świąt, ale Smokywood Pastures mogą potrzebować pomocy - takiej, jakiej podróżnicy Twojego typu mogą udzielić.$B$BZgubiliśmy ważny transport słodyczy, które były zapasem na ten rok, a na dodatek zaginął pracownik ze Smokywood Pastures, którego wysłaliśmy, żeby je znalazł! Proszę - transport był ostatnio widziany w okolicy Alterac Mountains w Hillsbrad Foothills. To właśnie tam udał się nasz człowiek.$B$BSprawdź, czy zarówno ładunek, jak i nasz agent tam są, cali i zdrowi!",
    ["O"] = "Znajdź detektywa ze Smokywood Pastures, który zaginął w zimowych rejonach Hillsbrad Foothills.",
    ["T"] = "Skradzione świąteczne smakołyki",
  },
  [6964] = {
    ["D"] = "Podarunki, słodycze, prezenty... dla mnie to bzdura!$B$BTe gobliny nie znają prawdziwego znaczenia tego okresu - okresu Święta Zimy. To czas odrodzenia; ziemia odpoczywa pod puchem śnieżnym sprowadzonym przez Zimowego Dziadka, który NIE JEST głupcem w czerwonym wdzianku, jak tamten tam!$B$BJeśli jesteś $gzainteresowany:zainteresowana;, czym tak naprawdę jest Uczta, to spytaj Sagorna Creststridera. Z całą pewnością będzie zaskoczony, że kogoś bardziej interesuje historią niż wręczaniem sobie prezentów.",
    ["O"] = "Porozmawiaj z Sagornem Creststriderem w Valley of Wisdom w Orgrimmarze na temat Feast of Winter Veil.",
    ["T"] = "Powód do świętowania",
  },
  [6981] = {
    ["D"] = "Odłamek jest idealnie zielony i choć stanowi jednolity fragment, pod jego powierzchnią wiruje coś przypominającego dym. Nie możesz oderwać wzroku od wnętrza kryształu; jednocześnie czujesz, że jest w tym coś niepokojącego.$B$BMoże należałoby sprawdzić, czy ktoś w Ratchet nie mógłby powiedzieć ci czegoś więcej na temat dziwnego znaleziska.",
    ["O"] = "Udaj się do Ratchet, aby dowiedzieć się czegoś więcej na temat świecącego odłamka.$B$BNastępnie zanieś go we wskazane ci miejsce.",
    ["T"] = "Świecący odłamek",
  },
  [6982] = {
    ["D"] = "Kopalnia Coldtooth jest to miejsce składu dla Hordy. Nie trawię ich jedzenia, które dają swoim oddziałom i stan ich uzbrojenia jest okropny! Ale... w takich czasach, kiedy dostawy są dość istotne, możemy wykorzystać to, co mają.$B$BWejdź do kopalni Coldtooth i przynieś mi ich zapasy. To powinno pomóc Przymierzu w walecznym kształtowaniu i usunie potrzebny sprzęt od wojowników Hordy.$B$BPowodzenia, $N. Kopalnia jest na południu, głęboko na terytorium Hordy.",
    ["O"] = "Przynieś 10 Coldtooth Supplies do Alliance Quartermaster w Dun Baldar.",
    ["T"] = "Zapasy Coldtooth",
  },
  [6983] = {
    ["D"] = "Potwór zwany Obrzydliwym Greenchem ukradł nasz zapas słodyczy, $N. Uważaj więc! Jest złośliwy, a grupa tych małych zielonych gnomów wypełnia jego rozkazy!$B$BBędziesz $gpotrzebował:potrzebowała; pomocy, żeby się z nim zmierzyć. Pogłoska głosi, że przetrzymuje nasze słodycze i naszego ukochanego renifera, Metzena, w Growless Cave, w Hillsbrad Foothills! Znajdź nasze słodycze, $N i dostarcz je zanim całe święto zostanie zrujnowane, a dzieci z Ogrimmaru zostaną zawiedzione!",
    ["O"] = "Odzyskaj Stolen Treats i uwolnij Metzen the Reindeer po pokonaniu Abominable Greench, który skrywa się w Growless Cave, w Hillsbrad Foothills.",
    ["T"] = "Jesteś podły...",
  },
  [6984] = {
    ["D"] = "My, ze Smokywood Pastures, doceniamy odzyskanie przez ciebie skradzionych słodyczy, $N. W zamian chcemy ci podarować specjalny prezent... sponsorowany przez nikogo innego, jak Zimowego Dziadka we własnej osobie!$B$BProszę, porozmawiaj z Zimowym Dziadkiem, a on przekaże ci twój prezent z okazji Święta Zimy od ekipy ze Smokywood Pastures. Z naszych upraw, prosto na twój talerz! Zdrowe pyszności od Smokywood Pastures... oczywiście, dzięki tobie!",
    ["O"] = "Porozmawiaj z Great-father Winter w Orgrimmarze.",
    ["T"] = "Podziękowania od Smokywood Pastures",
  },
  [6985] = {
    ["D"] = "Krasnoludy ze Stormpike używają kopalni Irondeep jako składowisko. Chcę, żebyś napadł na tę kopalnię i przyniósł mi ich zapasy. To ukróci starania Stormpikes\' w Alterac Valley, a nam zapewni potrzebne wyposażenie!$B$BBądź ostrożny, $N. Kopalnia Irondeep jest w głębi terytorium Przymierza, a kontrola kopalni zmienia się tak szybko, jak śnieg w Alterac.",
    ["O"] = "Przynieś 10 Irondeep Supplies do Horde Quartermaster we Frostwolf Keep.",
    ["T"] = "Zapasy z Irondeep",
  },
  [7001] = {
    ["D"] = "Wojna w dolinie zebrała swoje żniwo wśród naszych żołnierzy. Musimy odnowić nasze siły!$B$BJeśli uda nam się znów zapełnić stajnie, jeźdźcy wilków będą mogli jeszcze raz ruszyć na pole walki.$B$BWeź ten poganiacz i wytrop wilki, które żyją w pobliskim lesie. Kiedy znajdziesz jakiegoś, użyj poganiacza, żeby go oswoić. Przyprowadź do mnie oswojoną bestię, żebym mógł ją umieścić w stajni.$B$BKiedy stajnia będzie odpowiednio pełna, to jeźdźcy znów będą mogli patrolować okolice na liniach frontu.",
    ["O"] = "Znajdź Frostwolf w Alterac Valley. Użyj Frostwolf Muzzle kiedy jesteś blisko niego, żeby ujarzmić bestię. Kiedy ją oswoisz, Frostwolf podąży za Tobą do stajennego. Porozmawiaj ze stajennym, żeby otrzymać nagrodę za swoją zdobycz.",
    ["T"] = "Puste Stajnie",
  },
  [7002] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Szelki ze skóry",
  },
  [7003] = {
    ["D"] = "Mam zamiar zrobić coś z tymi olbrzymami, jeśli mam tu zostać! Oni zdecydowanie nie wpływają dobrze na interes, prawda?$B$BPracowałem ostatnio nad gnomskim promieniem zmniejszającym, ale używam GOBLIŃSKICH zdobyczy technologicznych w jego budowie! W celu uniknięcia takich niedogodności jak moja śmierć, chciałbym żebyś przetestował urządzenie na olbrzymach w Feralas. Powinieneś znaleźć jakieś pozostałości po ich miniaturyzacji - przynieś mi je!",
    ["O"] = "Użyj Zorbin\'s Ultra-Shrinker, żeby przekształcić każdego giganta, jakiego spotkasz w Feralas w bardziej możliwą do opanowania formę. Przynieś 15 Miniaturization Residues znalezionych z tych gigantów do Zorbina Fandazzleja w porcie Forgotten Coast, Feralas.",
    ["T"] = "Porażeni Giganci",
  },
  [7021] = {
    ["D"] = "Cudownego Święta Zimy, $gprzyjacielu:przyjaciółko;! Nie zapomnij przywitać się z Zimowym Dziadkiem, który przebywa obecnie w Orgrimmarze! Jeśli w tym roku $gbyłeś grzeczny:byłaś grzeczna;, otrzymasz cudowne smakołyki z okazji świąt. Nie zapomnij wspomnieć mu, co masz nadzieję dostać w tym roku!$B$BPonadto, nie zapomnij zgromadzić smakołyków, aby dać je tym, którzy byli w tym roku grzeczni. Mamy bardzo duży wybór. Świeżo z naszej farmy, prosto na twój talerz - to zdrowe dobroci Smokywood Pastures!",
    ["O"] = "Porozmawiaj z Great-father Winter; znajduje się on nieopodal Smokywood Pastures w strefie kupieckiej w Orgrimmarze.",
    ["T"] = "Zimowy Dziadek już tu jest!",
  },
  [7022] = {
    ["D"] = "Życzę ci cudownego Święta Zimy, $gprzyjacielu:przyjaciółko;! Upewnij się, że przywitasz się z Zimowym Dziadkiem! Jeśli $gbyłeś grzeczny:byłaś grzeczna; w tym roku, otrzymasz wspaniałe prezenty z okazji świąt. Nie zapomnij powiedzieć mu, co chcesz dostać w tym roku!$B$BUpewnij się także, że zbierzesz dostatecznie dużo smakołyków, aby podzielić się z tymi, którzy byli grzeczni w tym roku. Mamy wspaniały wybór wśród smakołyków. Świeżo z naszej farmy, prosto na twój talerz - oto smakowita dobroć od Smokywood Pastures!",
    ["O"] = "Porozmawiaj z Greatfather Winter; jest przy kupcu Smokywood Pastures w Ironforge.",
    ["T"] = "Zimowy Dziadek już tu jest!",
  },
  [7023] = {
    ["D"] = "Cudownego Święta Zimy, $gprzyjacielu:przyjaciółko;! Nie zapomnij przywitać się z Zimowym Dziadkiem, który przebywa obecnie w Ironforge! Jeśli w tym roku $gbyłeś grzeczny:byłaś grzeczna;, otrzymasz cudowne smakołyki z okazji świąt. Nie zapomnij wspomnieć mu, co masz nadzieję dostać w tym roku!$B$BPonadto, nie zapomnij zgromadzić smakołyków, aby dać je tym, którzy byli w tym roku grzeczni. Mamy bardzo duży wybór. Świeżo z naszej farmy, prosto na twój talerz - oto zdrowe dobroci Smokywood Pastures!",
    ["O"] = "Porozmawiaj z Greatfather Winter, który znajduje się blisko sprzedawcy Smokywood Pastures w Ironforge.",
    ["T"] = "Zimowy Dziadek już tu jest!",
  },
  [7024] = {
    ["D"] = "Cudownego Święta Zimy, $gprzyjacielu:przyjaciółko;! Nie zapomnij przywitać się z Zimowym Dziadkiem, który przebywa obecnie w Orgrimmarze! Jeśli w tym roku $gbyłeś grzeczny:byłaś grzeczna;, otrzymasz cudowne smakołyki z okazji świąt. Nie zapomnij wspomnieć mu, co masz nadzieję dostać w tym roku!$B$BPonadto, nie zapomnij zgromadzić smakołyków, aby dać je tym, którzy byli w tym roku grzeczni. Mamy bardzo duży wybór. Świeżo z naszej farmy, prosto na twój talerz - to zdrowe dobroci Smokywood Pastures!",
    ["O"] = "Porozmawiaj z Great-father Winter; znajduje się blisko sprzedawcy Smokywood Pastures w Orgrimmarze.",
    ["T"] = "Zimowy Dziadek już tu jest!",
  },
  [7025] = {
    ["D"] = "Hej, możesz zrobić Zimowemu Dziadkowi przysługę?$B$BNie chcę niepotrzebnie mówić o sobie w trzeciej osobie, ale Zimowy Dziadek spędza tu całe dnie i sam chętnie by coś przekąsił. Kilka korzennych ciasteczek i zmrożone mleko do popicia będą w sam raz. Będziesz tak $gdobry:dobra; i przyniesiesz mi je?",
    ["O"] = "Przynieś 5 Gingerbread Cookies i Ice Cold Milk dla Greatfather Winter w Ironforge.",
    ["T"] = "Smakołyki dla Zimowego Dziadka",
  },
  [7026] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Uprząż jeździecka",
  },
  [7027] = {
    ["D"] = "Tylko spójrz na stajnie, $N!Puste!$B$BYBrygada Stormpike nie ma baranów do jazdy - kawaleria nie istnienie. Musisz nam pomóc żołnierzu. Weź ten kołnierz treningowy i znajdź barany wędrujące po okolicy. Użyj kołnierza aby je oswoić, a następnie dostarcz mi je.$B$BGdy będziemy mieć ich wystarczająco dużo, powiadomimy naczelnego dowódcę. Z Twoją pomocą kawaleria się odrodzi!",
    ["O"] = "Znajdź Alterac Ram w Alterac Valley. Gdy będziesz w pobliżu barana użyj kołnierza treningowego do jego schwytania. Następnie zaprowadź go do stajni. Porozmawiaj z właścicielem o nagrodzie za sprowadzenie zwierzyny.",
    ["T"] = "Puste Stajnie",
  },
  [7028] = {
    ["D"] = "Kryształowe jaskinie Terramok leżą na zachodzie, w czeluściach Maraudonu... To prastare miejsce o długiej historii. A ja zamierzam dostać jej część w swoje ręce, wojowniczko. Relikwie starych bogów spoczywają ukryte za wielkimi wrotami.$B$BJeśli pragniesz stawić czoło spaczonemu złu zalegającemu w Maraudonie, sądzę, że mogę sprawić, by ci się to opłaciło. Zbierz theradraskie kryształowe posążki, które tam znajdziesz, i przynieś mi je.$B$BGdy je otrzymam będę mogła... je zbadać. Te moce zbyt długo spoczywają w uśpieniu...",
    ["O"] = "Zbierz 15 Theradric Crystal Carvings dla Willow z Desolace.",
    ["T"] = "Spaczone zło",
  },
  [7029] = {
    ["D"] = "Satyr imieniem Vyletongue zatruł jaskinie Maraudonu, hamując rozwój wielu tamtejszych roślin.$B$BWeź tę fiolkę, $N. Napełnij ją w sadzawce pomarańczowych kryształów we wnętrzu jaskiń; powlekająca jej wnętrze warstwa zneutralizuje toksyny, zmieniając je w leczniczą substancję.$B$BZnajdź splugawione pnącza w głębi pomarańczowych jaskiń i zaaplikuj im oczyszczoną ciecz. Rośliny zostaną oczyszczone ze skażenia, wiedz jednak, że Vyletongue wciąż będzie miał nad nim władzę. Może użyć go przeciwko tobie...",
    ["O"] = "Napełnij Coated Cerulean Vial w sadzawce pomarańczowych kryształów w Maraudonie.$B$BUżyj Filled Cerulean Vial na Vylestem Vines, by zmusić do ujawnienia się trującą Noxxious Scion. $B$BUlecz 8 roślin zabijając Noxxious Scion, następnie wróć do Varka Battlescara z Shadowprey Village.",
    ["T"] = "Skażenie Vyletongue\'a",
  },
  [7041] = {
    ["D"] = "Satyr imieniem Vyletongue zatruł jaskinie Maraudonu, hamując rozwój wielu tamtejszych roślin.$B$BWeź tę fiolkę, $N. Napełnij ją w sadzawce pomarańczowych kryształów we wnętrzu jaskiń; powlekająca jej wnętrze warstwa zneutralizuje toksyny, zmieniając je w leczniczą substancję.$B$BZnajdź splugawione pnącza w głębi pomarańczowych jaskiń i zaaplikuj im oczyszczoną ciecz. Rośliny zostaną oczyszczone ze skażenia, wiedz jednak, że Vyletongue wciąż będzie miał nad nim władzę. Może użyć go przeciwko tobie...",
    ["O"] = "Napełnij Coated Cerulean Vial w sadzawce pomarańczowych kryształów w Maraudonie.$B$BUżyj Filled Cerulean Vial na Vylestem Vines, by zmusić do ujawnienia się trującą Noxxious Scion. $B$BUlecz 8 roślin zabijając Noxxious Scion, następnie wróć do Talendrii z Nijel\'s Point.",
    ["T"] = "Skażenie Vyletongue\'a",
  },
  [7042] = {
    ["D"] = "Słuchaj... niepotrzebne są tu nam żadne magie, ale pastwiska Smokywood mogą skorzystać z twojej pomocy - takiej, na jakiej znasz się najlepiej.$B$BBrakuje nam tu ważnej przesyłki smakołyków, które zaopatrywały nas w sezonie, a teraz brakuje nam agenta pastwisk Smokywood, którego wysłaliśmy na pole, żeby go znalazł! Proszę - ostatnia przesyłka została utracona w rejonie Gór Alterac na Hillsbrad Foothills i tam też trafił nasz człowiek.$B$BSprawdź, czy są one całe i zdrowe!",
    ["O"] = "Znajdź poszukiwacza Smokywood Pastures, który zaginął w śnieżnych regionach Hillsbrad Foothills.",
    ["T"] = "Skradzione świateczne smakołyki",
  },
  [7043] = {
    ["D"] = "Kreatura zwana Obrzydliwym Greenchem ukradła naszą przesyłkę z przysmakami, $N. Bądź $gostrożny:ostrożna;! Jest okrutna oraz ma pod swoją komendą grupę małych gnomów!$B$BBędziesz $gpotrzebował:potrzebowała; czyjejś pomocy, żeby ją pokonać. Plotka głosi, że nasze przysmaki oraz Renifer Metzen znajdują się w Growless Cave, w Hillsbrad Foothills! Odnajdź nasze przysmaki, $N i przynieś je, zanim święto dobiegnie końca, w innym przypadku święta będą zrujnowane, a wszystkie dzieci Stormwind zawiedzione!",
    ["O"] = "Odzyskaj skradzione przysmaki i uwolnij Metzena the Reindeer po pokonaniu Abominable Greench, która ukrywa się w pobliżu Growless Cave, w Hillsbrad Foothills.",
    ["T"] = "Jesteś okropny...",
  },
  [7044] = {
    ["D"] = "Mroczny satyr zwany Lordem Vyletongue rozsiewa swe zło po zakamarkach tych krętych jaskiń, zatruwając umysły ich mieszkańców. Przebywa za fioletowymi kryształami.$B$BVyletongue stworzył też żywy symbol swej zarazy, Noxxiona, który osiedlił się za pomarańczowymi kryształami. Razem skradli dwie części berła mego brata. Mój brat, Celebras... snuje się bezmyślnie po jaskiniach, toczony przez skażenie.$B$BMusisz mu pomóc! Odnajdź elementy berła i porozmawiaj z nim... jakoś.",
    ["O"] = "Odzyskaj dwie części Berła Celebrasa: Celebrian Rod i Celebrian Diamond.$B$BZnajdź sposób, by porozmawiać z Celebrasem.",
    ["T"] = "Legendy Maraudonu",
  },
  [7045] = {
    ["D"] = "Musisz wiedzieć, $N, że u nas, w Smokywood Pastures, dużym szacunkiem darzy się osoby, które odzyskują skradzione smakołyki. Dlatego też chcielibyśmy wręczyć ci coś specjalnego... i to z rąk samego Zimowego Dziadka!$B$BUdaj się do Zimowego Dziadka i odbierz od niego swój świąteczny podarunek od Smokywood Pastures w ramach prezentu. Z naszych upraw, prosto na twój talerz! Zdrowe pyszności od Smokywood Pastures... oczywiście, dzięki tobie!",
    ["O"] = "Porozmawiaj z Greatfather Winter w Ironforge.",
    ["T"] = "Podziękowania od Smokywood Pastures!",
  },
  [7046] = {
    ["D"] = "Moje berło stanowiło niegdyś dla mnie źródło nadziei. Jego moc dawała mi władzę nad tutejszymi jaskiniami. Liczyłem na to, że uda mi się przynieść ukojenie duszy mego stryja... Jest to zadanie, które teraz przekazuję tobie.$B$BBy z dwóch części ponownie uczynić jedność, potrzebuję twej pomocy do odprawienia obrzędu. Pójdź za mną i wysłuchaj instrukcji, podczas gdy będę gromadził energię niezbędną do połączenia rękojeści z diamentem.$B$BRazem ponownie stworzymy Berło Celebrasa!",
    ["O"] = "Towarzysz Celebras the Redeemed podczas tworzenia Berła Celebrasa.$B$BPorozmawiaj z nim po ukończeniu rytuału.",
    ["T"] = "Berło Celebrasa",
  },
  [7061] = {
    ["D"] = "Trzymaj. Jeśli interesuje cię historia Święta Zimy, przeczytaj tę księgę. Jestem zdania, że oddajemy legendzie należny szacunek, a wystarczająco długo studiowałem wszelkie klechdy i podania, by docenić wysiłek, jakim jest zebranie wszystkich informacji w jednym miejscu. Kiedy skończysz, przekaż ją Baine\'owi Bloodhoof w Thunder Bluff. Powinien się ucieszyć, że tradycje naszego ludu cieszą się zainteresowaniem.",
    ["O"] = "Jeśli chcesz dowiedzieć się czegoś więcej o świętach, nie krępuj sięgnąć po księgę \"The Feast of Winter Veil\". Gdy skończysz ją czytać, dostarcz ją do Baine\'a Bloodhoofa w Thunder Bluff.",
    ["T"] = "Święto Zimy",
  },
  [7062] = {
    ["D"] = "Podarunki, przysmaki, prezenty... bah, mówię ci!$B$BTe gobliny naprawdę niszczą prawdziwe znacznie Święta Zimy. To jest czas odnowy; Ziemia drzemie pod pierzyną śniegu przyniesionym przez Zimowego Dziadka, który NIE jest durniem w czerwonym kostiumie!!$B$BJeśli chcesz się dowiedzieć, czym jest to święto, zapytaj historyka Karnika w siedzibie Ligi Odkrywców. Jestem pewien, że będzie zaskoczony, że ktoś interesuje się historią, a nie prezentami.",
    ["O"] = "Porozmawiaj z historykiem Karnikiem w siedzibie Ligi Odkrywców w Ironforge o Feast of Winter Veil.",
    ["T"] = "Powód do świętowania",
  },
  [7063] = {
    ["D"] = "Trzymaj - jeśli chcesz dowiedzieć się więcej na temat Święta Zimy, przeczytaj tę książkę. Chociaż uważam, że nasze uznanie legendy jest właściwe, to i tak doceniam, że wszystkie informacje są zgromadzone w jednym miejscu.$B$BKiedy skończysz, weź książkę do Muradina Bronzebearda. Wiem na pewno, że będzie ucieszony wieściami, że ktoś zainteresował się startymi legendami.",
    ["O"] = "Przeczytaj \"The Feast of Winter Veil\", jeśli chcesz się dowiedzieć czegoś więcej na temat tego święta. Jak już to zrobisz, zanieś ją do Muradina Bronzebearda w Ironforge.",
    ["T"] = "Święto Zimy",
  },
  [7064] = {
    ["D"] = "W głębi Maraudonu mieszka zła istota chaosu - Princess Theradras, uosobienie żywiołu ziemi, krewniaczka Old Gods. Przed wiekami związał się z nią Zaetar, pierworodny syn Cenariusa. Potomstwo tego związku znane jest mieszkańcom Kalimdoru jako centaury. W podzięce za swe narodziny centaury zabiły Zaetara i zagarnęły jego ciało. Moim zadaniem jest odszukać tych, którzy dysponują potęgą wystarczającą do zabicia Theradras, byśmy mogli odzyskać szczątki Zaetara przed powrotem w Stonetalon.",
    ["O"] = "Zabij Princess Theradras i wróć do Selendry, przebywającej w pobliżu Shadowprey Village w Desolace.",
    ["T"] = "Skażenie ziemi i nasiona",
  },
  [7065] = {
    ["D"] = "W głębi Maraudonu mieszka zła, chaotyczna istota, $N. Princess Theradras jest potęgą żywiołu ziemi, spokrewnioną ze Old Gods. Wieki temu odnalazł ją Zaetar, pierworodny syn Cenariusa. Potomstwo ich... związku to istoty zwane centaurami. W podzięce za swe narodziny centaury zabiły Zaetara, zaś Theradras zabrała jego ciało. Moim zadaniem jest odszukać tych, którzy dysponują potęgą wystarczającą do zabicia Theradras, byśmy mogli odzyskać szczątki Zaetara przed powrotem w Stonetalon.",
    ["O"] = "Zabij Princess Theradras i wróć do Keepera Marandisa, z Nijel\'s Point w Desolace.",
    ["T"] = "Skażenie ziemi i nasiona",
  },
  [7066] = {
    ["D"] = "Te niewydarzone centaury - moi synowie i córki - potrzebują swego ojca.$B$BRozejrzyj się - to miejsce rozbrzmiewa nadzieją i wszystkim, co głosił mój ojciec Cenarius.$B$BRozejrzyj się – to miejsce rozbrzmiewa nadzieją i wszystkim, co głosił mój ojciec Cenarius. To tryska ze mnie! I nie mogę im tego odebrać... nawet za zbrodnię przeciw mnie, której się dopuścili.$B$BJest jednak pewna rzecz, o którą chciałbym cię prosić, by ukoić duszę mego brata. Weź to... to pierwsze nasiono, jakie wydało życie wykarmione moim ciałem. Powiedz mu, że mój duch tu przebywa, a ja wciąż żyję. Jestem pewien, że zrozumie.",
    ["O"] = "Odnajdź Remulosa w Moonglade i daj mu Seed of Life.",
    ["T"] = "Nasiono życia",
  },
  [7067] = {
    ["D"] = "Mimo, że zostałem wygnany i ogłoszony heretykiem, moje przekonania wciąż są właściwe - już tylko to pcha mnie do przodu. Ale bym mógł dopełnić swego przeznaczenia, potrzebuję pomocy kogoś z zewnątrz... kogoś, kto nie należy do żadnego z plemion centaurów.$B$BZadanie wymaga wkroczenia do świętych sal Maraudonu - grobowca, którego strzeże mój lud i do którego mogą wejść tylko najbardziej oddani.$B$BJeżeli zgodzisz się mi pomóc, starczy, że skiniesz głową. Przekażę ci pergamin z moimi instrukcjami. Przeczytaj go i rozważ moje słowa.",
    ["O"] = "Przeczytaj Pariah\'s Instructions. Następnie zdobądź Amulet of Union z Maraudonu i zwróć go Centaurowi Pariahowi w południowym Desolace.",
    ["T"] = "Instrukcje Pariasa",
  },
  [7068] = {
    ["D"] = "Potężną moc znaleźć w świętym centaurów miejscu... w świętym Maraudonie. Szczepy centaurów z Desolace chronić go za życia cenę, lecz nie być w stanie powstrzymać nas przed zabraniem tego, co nam potrzebne.$B$BTy iść do Maraudonu. Ty znaleźć stwory ze skałocienia. Ty przynieść fioletowe kryształy, a Uthel\'nay wynagrodzić twój czas.$B$BNiebezpieczne to miejsce, więc może ty zabrać przyjaciół?",
    ["O"] = "Zbierz w Maraudonie 10 Shadowshard Fragments i przynieś je Uthel\'nayowi z Orgrimmaru.",
    ["T"] = "Fragmenty skałocienia",
  },
  [7069] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>",
  },
  [7070] = {
    ["D"] = "Ostatnio rozpocząłem badania rozmaitych kryształów i ich magicznych właściwości. Za zezwoleniem Lady Proudmoore zwracam się z prośbą do podróżników zmierzających do Desolace o odnalezienie miejsca zwanego Maraudonem. Wewnątrz zrujnowanej świątyni mieszkają ogromne żywiołaki złożone z fioletowych kryształów, które nazwałem skałocieniami.$B$BGdybyś postanowił udać się w tym kierunku i znalazł jakieś kryształy, byłbym ci bardzo wdzięczny. Mógłbym nawet wykonać z nich dla ciebie jakąś błyskotkę, gdybyś był zainteresowany.",
    ["O"] = "Zbierz w Maraudonie 10 Shadowshard Fragments i przynieś je Arcymagowi Tervoshowi z Theramore na wybrzeżu Dustwallow Marsh.",
    ["T"] = "Fragmenty skałocienia",
  },
  [7081] = {
    ["D"] = "Cmentarze w Dolinie Alterac to cenne terytorium. O wpływy na tych świętych ziemiach nieustępliwie walczy zarówno Horda, jak i Przymierze. $N, jesteś gotowy włączyć się do walki?$B$BChcę, żebyś zaatakował wrogi cmentarz. Odszukaj jeden, na środku którego stoi chorągiew Hordy i wyrwij ją z ziemi! Zrób to, a zadanie będzie ukończone....$B$BJeśli jednak utrzymasz cmentarz przez kilka minut, nasze posiłki niezwłocznie przybędą Ci z pomocą.",
    ["O"] = "Zaatakuj cmentarz, a następnie wróć do sierżanta Durgena Stormpike\'a w Alterac Mountains.",
    ["T"] = "Cmentarze w Alterac Valley",
  },
  [7082] = {
    ["D"] = "Linie bitewne Doliny Alterac ciągle się przesuwają. Terytoria przechodzą z rąk do rąk gdy stawiamy czoła naszym wrogom w śmiercionośnych bitwach. A cmentarzyska, $N, są miejscem najbardziej zaciekłych walk.$B$BChcę, żebyś zaatakował cmentarz kontrolowany przez Sojusz! Znajdź cmentarzysko z chorągwią Przymierza w środku i wyciągnij ją z ziemi.$B$BUczyń to, a zadanie dla mnie zostanie wykonane, ale...jeśli utrzymasz cmentarz przez kilka minut, stanie się on nasz i żołnierze przybędą by Cię odciążyć.",
    ["O"] = "Zaatakuj cmentarzysko, po wszystkim wróć do kaprala Teeka Bloodnsarl w Alterac Mountains.",
    ["T"] = "Cmentarzyska Alterac",
  },
  [7101] = {
    ["D"] = "Wieże i bunkry są ważnymi punktami, a my musimy je wszystkie zdobyć i okupować! W tym celu chcę, abyś zaatakował bunkier kontrolowany przez wroga.$B$BAby to zrobić, wejdź do jednego ze sztandarem Przymierza. W środku zobaczysz kolejny sztandar. Wyciągnij go, a w jego miejsce pojawi się biały sztandar Hordy. Dobra robota!$B$BW tym momencie Twoje zadanie dla mnie będzie skończone, jednak jeśli przytrzymasz to miejsce wystarczająco długo, a Przymierze nie weźmie go z powrotem, wtedy zostanie zniszczone!",
    ["O"] = "Zdobądź wieżę przeciwnika, następnie wróć do Corporal Teeka Bloodsnarl w Alterac Mountains.",
    ["T"] = "Wieże i bunkry.",
  },
  [7102] = {
    ["D"] = "Wieże i bunkry to kluczowe obiekty obronne, musimy zająć ich jak najwięcej! Chcę, abyś zaatakował wieżę lub bunkier w Dolinie Alterac.$B$BAby to zrobić, wejdź do wieży, na której szczycie znajduje się sztandar Hordy. W środku znajdziesz wrogą chorągiew. Wyciągnij ją, a na jej miejscu pojawi się biała chorągiew Przymierza. Dobra robota!$B$BW tym momencie Twoja misja będzie ukończona. Jeśli jednak nie będziesz bronił obiektu przez pewien czas i Horda go odbije, zostanie on zniszczony!",
    ["O"] = "Zniszcz chorągiew we wrogiej wieży lub bunkrze, a następnie wróć do sierżanta Durgena Stormpike\'a w Alterac Mountains.",
    ["T"] = "Wieże i bunkry",
  },
  [7121] = {
    ["D"] = "$N, dostałem rozkaz od kwatermistrza, by kierować do niego nowych rekrutów. Kwatermistrz potrzebuje surowców, przechowywanych w skrzyniach w kopalniach Alterac i to prawdopodobnie Ty będziesz wyznaczony, aby je dostarczyć.$B$BIdź dalej drogą. Kwatermistrza znajdziesz na zachód stąd.",
    ["O"] = "Zgłoś się do kwatermistrza Stormpike.",
    ["T"] = "Kwatermistrz",
  },
  [7122] = {
    ["D"] = "Kopalnie w Dolinie Alterac skrywają więcej niż tylko minerały. Zarówno Mroźne Wilki jak i Burzowe Piki schowały nadmiar zapasów w kopalniach Irondeep i Coldtooth... zdobycie nad nimi kontroli to niezły pomysł!$B$BZdobądź kopalnie i wróć do mnie. By zdobyć kopalnie, zejdź do tej niekontrolowanej przez nas i zabij jej przywódcę. Kiedy to uczynisz, kopalnia będzie nasza i wyślemy wojsko by ją chronić!",
    ["O"] = "Zdobądź kopalnię, której nie kontrolują Stormpike, po czym wróć do sierżanta Durgen Stormpike w Alterac Mountains.",
    ["T"] = "Zdobądź kopalnię.",
  },
  [7123] = {
    ["D"] = "$N, kwatermistrz Mroźnych Wilków szuka rekrutów do zadań prowadzących do kopalń w Alterac Valley. Pomów z nim; powie Ci więcej.$B$BPodążaj drogą na zachód, do bunkra, potem wyjdź zachodnim wyjściem a znajdziesz naszego kwatermistrza.",
    ["O"] = "Porozmawiaj z Kwatermistrzem Mroźnych Wilków.",
    ["T"] = "Porozmawiaj z naszym Kwatermistrzem",
  },
  [7124] = {
    ["D"] = "Tak jak bitwa rozciąga się po horyzonty Doliny Alterac, tak samo kipi wewnątrz kopalń Coldtooth i Irondeep. Obie z nich skrywają bogate złoża minerałów i służą jako magazyny surowców. Nic dziwnego, że są tak bardzo cenione!$B$BWspomóż nasze działania wojenne, $N! Zajmij jedną z kopalń dla Hordy! Aby ją zająć, wejdź do takiej, która nie znajduje się pod naszą kontrolą i zabij jej przywódcę. Gdy to się stanie, kopalnia będzie należeć do nas. Niezwłocznie wyślemy wojsko, aby jej broniło!",
    ["O"] = "Zajmij kopalnię, a następnie wróć do kaprala Teeki Bloodsnarl w Alterac Mountains.",
    ["T"] = "Zajmij Kopalnię",
  },
  [7141] = {
    ["D"] = "Liga Odkrywców wierzy, że w Dolinie Alterac znajdują się artefakty, ale orki Mroźnych Wilków nie pozwolą nam na eksplorację. Nie możemy pozwolić Hordzie powstrzymać naszych naukowych celów! Pokonaj generała Mroźnych Wilków, Drek\'Thara. Gdy on zginie, orki stracą przewagę.$B$BDrek\'Thar jest w Strażnicy Mroźnych Wilków na południe od Doliny Alterac. Pokonaj go, następnie wróć do mnie.",
    ["O"] = "Wejdź do Alterac Valley, pokonaj generała Hordy Drek\'thara, po czym wróć do badacza Stonehewer w Alterac Mountains.",
    ["T"] = "Bitwa o Alterac",
  },
  [7142] = {
    ["D"] = "Krasnoludy Burzowych Pik i ich sprzymierzeńcy najechali Dolinę Alterac i musimy ich odeprzeć! By zwyciężyć w bitwie o Alterac, musimy pokonać ich generała, Vanndara Stormpike!$B$BZnajdziesz Vanndara w Dun Baldar, na północ od Doliny Alterac.$B$BZniszcz go, $N, po czym wróć do mnie.",
    ["O"] = "Wejdź do Alterac Valley i pokonaj krasnoludzkiego generała, Vanndara Stormpike. Po wszystkim wróć do Voggaha Deathgrip w Alterac Mountains.",
    ["T"] = "Bitwa o Alterac",
  },
  [7161] = {
    ["D"] = "Witaj, $C. Sporo wody upłynęło, od kiedy mieliśmy możliwość odpowiedzieć na wezwanie do boju. Uczucia sprzed lat budzą się powoli, lecz raz obudzona krew wrze.$B$BWszyscy nowo przybyli do doliny muszą przejść chrzest bojowy.$B$BGłęboko w jaskini gnolli Wildpaw znajduje się baner klanu Mroźnego Wilka. Idź i odzyskaj go. Przynieś go do mnie, a otrzymasz insygnium inicjacji klanu Mroźnego Wilka.",
    ["O"] = "Udaj się do jaskini gnolli Wildpaw na południowy wschód od bazy w Alterac Valley i odnajdź tam Frostwolf Banner. Następnie zwróć go Warmasterowi Laggrondowi.",
    ["T"] = "Na poligonie",
  },
  [7162] = {
    ["D"] = "$gPrzybyłeś:Przybyłaś; w samą porę, $C. Te dzikusy, Mroźne Wilki, w ogóle nie odpuszczają! Musimy im pokazać potęgę Burzowych Pik. Muszą się przed nami ugiąć.$B$BZanim udasz się na pole bitwy, zechcesz wstąpić w szeregi Burzowych Pik.$B$BNa południe od Dun Baldar znajdziesz Jaskinie Icewing. Głęboko w ich trzewiach spoczywa sztandar Burzowych Pik. Wyrusz tam i odzyskaj go. Przynieś mi ten proporzec, a zdobędziesz insygnia $gnowicjusza:nowicjuszki; Burzowych Pik.",
    ["O"] = "Udaj się do Icewing Caverns, na południowy zachód od Dun Baldar w Alterac Valley i odzyskaj Stormpike Banner. Oddaj Stormpike Banner Porucznikowi Haggerdinowi w Alterac Mountains.",
    ["T"] = "Test",
  },
  [7163] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Powstań i bądź rozpoznawalny",
  },
  [7164] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Uhonorwany wśród the Clan",
  },
  [7165] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Zasłużona cześć",
  },
  [7166] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Legendarni bohaterowie",
  },
  [7167] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Oko dowodzenia",
  },
  [7168] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Powstań i stań się znanym",
  },
  [7169] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Czczony wśród gwardii",
  },
  [7170] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Zasłużony szacunek",
  },
  [7171] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Legendarni Bohaterowie",
  },
  [7172] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Oko dowodzenia",
  },
  [7181] = {
    ["D"] = "Najazd Stormpike nie jest jedynym zagrożeniem w tym regionie, żołnierzu. Wojna w dolinie jest prowadzona na dwa fronty. Kanibalistyczne trolle Winterax również walczą o władzę.$B$BPrzewodzi nimi Korrak Wściekły - okrutna i przebiegła bestia.$B$BUderzenie przeciw Korrakowi może okazać sie miażdżącym ciosem dla klanu Winterax. Zgładź bestię i zostań nagrodzony!",
    ["O"] = "Według legend, przywódca potężnych trolli Winterax pojawia się, by siać spustoszenie wśród mieszkańców doliny Alterac.$B$BGdy Korrak się ujawni, zniszcz go i powróć do Laggronda, Mistrza Wojennego.",
    ["T"] = "Legenda Korraka",
  },
  [7201] = {
    ["D"] = "Czekają na Ciebie te wyruszające w głębiny, $N.$B$BKlan Ciemnego Żelaza opanował tworzenie niezwykle potężnych golemów. $B$BWstępne raporty od naszych szpiegów wskazują, że krasnoludy używają unikalnego źródła energii, aby nadać swoim twórcom nieporównywalną moc zabijania.$B$BWyobraź sobie, co moglibyśmy zrobić z naszymi obrzydliwościami, gdybyśmy mogli zdobyć naszą esencję elementów! Odwróć to miasto do góry nogami, jeśli musisz, ale nie wracaj, dopóki nie znajdziesz esencji! Płatność będzie warta ryzyka.",
    ["O"] = "Udaj się do Blackrock Depths i odzyskaj 10 Esencji z Elementalów. Twoja pierwsza chęć to przeszukanie golemów i twórców golemów. Pamiętasz, Vivian Lagrave również mamroczącą coś o żywiołach.",
    ["T"] = "Ostatni element",
  },
  [7202] = {
    ["D"] = "Lokalne trolle Winterax w tym regionie są bezlitosnymi dzikusami, które pragną jedynie dodać nasze ciała do ich plugawych kotłów.$B$BMusimy pokazać im naszą moc!$B$BOdzyskaliśmy tomy z ich jaskiń, które szczegółowo opisują ich hierarchię przywództwa. Artefakty wskazują, że ich przywódca, Korrak Bloodrager, pozostaje w ukryciu do czasu gdy nie pojawi się powód by wyszedł.$B$BŚmierć Korraka oznaczałaby śmierć klanu Winterax! Zabij go i wróć.",
    ["O"] = "Według legendy, przywódca potężnych trolli Winterax pojawia się w celu siania spustoszenia w mieszkańcach Doliny Alterak.$B$BJeśli Korrak się pojawi, zniszcz go i wróć do porucznika Haggerdina w Górach Alterak.",
    ["T"] = "Korrak the Bloodrager",
  },
  [7221] = {
    ["D"] = "Ach, $N, zgłaszasz się na służbę, prawda? Wspaniale, Stormpikes może wykorzystać każdego, kogo możemy zebrać!$B$BPorozmawiaj z Poszukiwaczem Stonehewer w Dun Baldar. Rekrutuje ona na ważną misję na terytorium wroga. Znajdziesz Stonehewera na dnie garnizonu Dun Baldar.$B$BI miej oko, kiedy przechodzisz przez Dun Baldar. Jest mnóstwo pracy dla ciężko pracującego $ghis:her;, który nie boi się uściskać jego brudne ręce.",
    ["O"] = "Porozmawiaj z Poszukiwaczem Stonehewerem w garnizonie Dun Baldar.",
    ["T"] = "Porozmawiaj z Poszukiwaczem Stonehewer",
  },
  [7222] = {
    ["D"] = "$c? Dobrze! Cieszymy się, że możemy zobaczyć Cię w Alterac, $N. Wędrowne krasnoludy i ich sprzymierzeńcy wtargnęli do naszej doliny i witamy wszystkich w Hordzie, aby przyłączyli się do nas w sprawiedliwej rzezi!$B$BPorozmawiaj z Voggah Deathgrip. Szuka on agentów do ważnej misji w twierdzy Przymierza w Dolinie Alterac!$B$BZnajdziesz Voggah w Frostwolf Keep.",
    ["O"] = "Porozmawiaj z Voggah w Frostwolf Keep.",
    ["T"] = "Porozmawiaj z Voggah Deathgrip",
  },
  [7223] = {
    ["D"] = "W Dolinie Alterac nieustannie szaleją bitwy, a zapasy, które otrzymujemy od Ironforge, nie wystarczą, by wyposażyć naszych doświadczonych żołnierzy.$B$BJeśli znajdziesz zbroję na polu bitwy, pomóż wysiłkowi wojennemu i przynieś mi te kawałki!",
    ["O"] = "Przynieś 20 Skrawków Pancerza Murgotowi Deepforge w Dun Baldar.",
    ["T"] = "Skrawki zbroi",
  },
  [7224] = {
    ["D"] = "Kiedy walczysz z wrogiem, zbieraj strzępki ich zbroi i przynieś je do mnie. Użyję tych odpadków, żeby zrobić zbroję dla naszych własnych żołnierzy!",
    ["O"] = "Przynieś 20 Skrawek Pancerza Smithowi Regzarowi z Frostwolf Village.",
    ["T"] = "Wrogie łupy",
  },
  [7241] = {
    ["D"] = "W odległej krainie rozbrzmiewają bębny wojenne, $C. Ulubiony klan twojego Wodza jest atakowany przez nikczemny Stormpike Guard z Ironforge.$B$BPatrząc na ciebie, dostrzegam, że walka ci niestraszna i jesteś gotów stanąć do niej w imieniu Frostwolf.$B$BTeraz to ty musisz podjąć kolejny krok w swojej ewolucji.$B$BNa północ od Tarren Mill, w Alterac, odnajdziesz wejście do Alterac Valley. Tam spotkasz Warmastera Laggronda. Pośpiesz się, $C, bitwa nadciąga!",
    ["O"] = "Udaj się do Alterac Valley, położonej w Alterac Mountains. Znajdź i porozmawiaj z Warmasterem Laggrondem - stojącym przed wejściem do tunelu - aby rozpocząć swoją karierę jako żołnierz klanu Frostwolf. Alterac Valley odnajdziesz na północ od Tarren Mill u podnóża Alterac Mountains.",
    ["T"] = "W Obronie klanu Frostwolf",
  },
  [7261] = {
    ["D"] = "Walczymy z brutalną bitwą w dolinach Alterac. Dziki klan Lodowego Wilka rzuca wyzwanie potędze Stormpike! Muszą zostać wytępieni w imię Króla Magni Bronzebearda! Przejęcie, odstrzał i zwrot tej ziemi jest imperatywem suwerennym i terytorialnym dla królestwa Ironforge.$B$BNiestety, żołnierze nie rosną na drzewach! Zgłoś się do porucznika Haggerdina przed Doliną Alterac, aby rozpocząć podróż służbową i honorową wśród Stormpike.",
    ["O"] = "Udaj się do Doliny Alterac na Pogórzu Hillsbradzkim. Przed tunelem wejściowym znajdź i porozmawiaj z Porucznikiem Haggerdinem.$B$BNa chwałę Bronzebearda!",
    ["T"] = "Suwerenny imperatyw",
  },
  [7281] = {
    ["D"] = "Tragicznie... Mój brat zmierzy się ze mną na polu bitwy: Dowódca Stormpike.$B$BZ czterech dowódców Stormpike jest bez wątpienia najbardziej niebezpieczny. Być może, jeśli zostanie zabity, Królowa Banshee może go obrócić tak, jak mnie zrobiła - pokazać mu błąd jego postępowania...$B$BW głębi terytorium wroga znajdziesz mojego brata. Zabij go i wróć do mnie. Ufam, że jesteś w stanie ukończyć tę misję, żołnierzu.$B$BI żołnierzu, nie idź sam.",
    ["O"] = "Udaj się na terytorium Stormpike i zabij komandora Karla Philipsa. Wróć do Commander Louis Philips, gdy zadanie zostanie zakończone.",
    ["T"] = "Miłość braterska",
  },
  [7282] = {
    ["D"] = "Musi zostać wyrzucony z nędzy, żołnierzu! Nie wie, co robi. Stał się bezmyślnym sługą przerażającej Królowej Banshee.$B$BPrzedrzyj się przez Pole Walki w głąb terytorium Lodowego Wilka. Znajdź mojego brata i zniszcz go. Jego udręka musi się skończyć.",
    ["O"] = "Udaj się na terytorium Lodowego Wilka i zabij komendanta Louisa Philipsa. Wróć do Komandora Karla Philipsa, gdy zadanie zostanie zakończone.",
    ["T"] = "Miłość braterska",
  },
  [7301] = {
    ["D"] = "Mamy je uwięzione, $R7. Mówię o ich komandorach skrzydłowych. To była wściekła bitwa na niebie, ale w końcu spadła! Niestety, nasi najlepsi piloci zostali zestrzeleni w kontrataku przeciwko Twierdzy Lodowego Wilka. Musisz dowiedzieć się, co się z nimi stało.$B$BWyszukaj Tower Point West i Frostwolf Keep. To były ich ostatnie znane lokalizacje. Przeszukuj dokładnie te obszary.",
    ["O"] = "Udaj się na terytorium Frostwolf i poszukaj Wing Commandera Slidore\'a, Wing Commandera Vipore i Wing Commandera Ichmana. Wróć do dowódcy Duffy\'ego, jeśli ukończysz misję.",
    ["T"] = "Upadli władcy nieba",
  },
  [7302] = {
    ["D"] = "Nasze wsparcie lotnicze jest w rozsypce, $N. Dowódcy Skrzydła zostali zestrzeleni na terytorium wroga. Musisz dowiedzieć się, co się z nimi stało, abyśmy mogli podjąć próbę ratunku!$B$BOstatni raz widziano lecące ich nad Icewing Bunkierem. Jeźdźca Wojny Jeztor spostrzegł ich w pobliżu tartaku Stormpike. Mulverick... ten lekkomyślny głupiec był widziany w pobliżu Dun\'Baldar North Bunker.$B$BTo wszystko, co mam. Ruszaj się! Przeszukuj dokładnie obszary.",
    ["O"] = "Dowiedz się, co stało się z Wing Commander Guse, Wing Commander Jeztor i Wing Commander Mulverick. Wróć do dowódcy Mulforta, jeśli ukończysz misję.",
    ["T"] = "Upadli władcy nieba",
  },
  [7321] = {
    ["D"] = "Kto powiedział, że nieumarli nie wiedzą nic o gotowaniu? Na przykład, weź mój tajny przepis na zupę z żółwia. Znam ludzi, którzy wróciliby z martwych, by wychłeptać chociaż jedną miskę! Heh, heh...$B$BMówiąc o tym, nie udało mi się ostatnio przyrządzić żadnej. Kiedyś jeździłem do Jeziora Lordamere osobiście, aby polować na te paskudne żółwie, ale obecnie mam ręce pełne roboty i nie mam na to czasu.$B$BJeśli przyniesiesz mi trochę mięsa z żółwia oraz przyprawy, pokażę ci, jak przyrządzać taką zupę!",
    ["O"] = "Przynieś 10 kawałków mięsa z żółwi i przyprawy dla Christopha Jeffcoata w Tarren Mill.",
    ["T"] = "Uśmierzająca zupa z żółwia",
  },
  [7341] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Sprawiedliwy handel",
  },
  [7342] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Strzały aą dla maminsynków",
  },
  [7361] = {
    ["D"] = "<Najak warczy.>$B$BZanim istniały nocne elfy, był troll. To od trolla przyszły nocne elfy.$B$BIch zbuntowane ataki przeciwko mojemu ludowi nie będą tolerowane. Staghelm stara się nas zniszczyć - nie zostawiając śladu po tych, którzy go nudzą. To się nie stanie!$B$BDla każdego nocnego elfa, którego zabijasz i ścinasz, Najak da ci łaskę wśród Mrocznej Włóczni. Słowo waszych czynów rozprzestrzeni się po Kalimdorze i Wschodnich Królestwach. Idź i służ dalej Mrocznej Włóczni!",
    ["O"] = "Otrzymałeś zadanie zabicia wrogich nocnych elfów w Dolinie Alterac.$BNEW_LINIA Zabij nocnego elfa i wróć do Najak Hexxen w Twierdzy Mroźnego Wilka z odcietymi głowami Nocnych Elfów.",
    ["T"] = "Pośród Ciemnej Włóczni",
  },
  [7362] = {
    ["D"] = "Starsza Wiedźma wysłała mnie do tej strefy działań wojennych, aby zbadać inne rasy. Dokładniej, mam zebrać próbki gnomów. Magatha jest przede wszystkim zainteresowana ich przetrwaniem. Tak, gnomy - choć żałośnie słabe i maleńkie - wydzielają ogromną odporność zarówno w walce, jak i poza nią.$B$BNa szczęście dla ciebie, szukam łotrów, by wykonać rozkaz Magatha. Powróć do mnie z kępkami włosów gnomów, a ty będziesz znany jako taureński sojusznik.",
    ["O"] = "Otrzymałeś zadanie zabicia gnomich przeciwników w Dolinie Alterac.$BNEW_LINIA Zabij gnoma i wróć do Ravaka Grimtotema w Lodowym Wilku z Kępką Gnomowych Włosów.",
    ["T"] = "Sojusznik taurenów",
  },
  [7363] = {
    ["D"] = "Ludzie są tak obrzydliwi.$B$B<Komandora Philipsa grymasi.>$B$BChociaż prawdą jest, że jestem żołnierzem Lodowego Wilka, pozostaję sługą Sylvanas.$B$BPodczas mojej służby, wykonuję dodatkową pracę po stronie Mrocznych Aptekarzy z Undercity.$B$BZostałem poproszony o zbieranie ludzkich kości, które mają zostać wykorzystane do leczenia chorób ludzkich.$B$BMam uprawnienia do przekazania tego zadania moim podwładnym.$B$BZnajdź je. Zabij ich. Zwróć mi swoje kościane żetony.",
    ["O"] = "Otrzymałeś zadanie zabicia przeciwników w Dolinie Alterac.$BNEW_LINIA Zabij człowieka i wróć do komandora Louisa Philipsa (który błąka się między liniami frontu a Lodowym Wilkiem) z Kością Ludzką.$B$BLekarstwo na ludzką chorobę jest na wyciągniecie ręki!",
    ["T"] = "Ludzki stan",
  },
  [7364] = {
    ["D"] = "Wielki Tinkerer wysłał mnie na to pole bitwy, aby bronić moich gnomich braci i sióstr. Otrzymaliśmy wiadomość, że taureni wyróżniają się i zabijają gnomy. Co najgorsze, usuwają kępki chwalebnych kosmyków z trupów poległych. Te okrucieństwa muszą zostać zatrzymane. Musimy odwzajemnić się!$B$BChcę, żeby zostały one pozbawione kopyt, $c. Przynieś mi ich kopyta! Pokaż się jako sprzymierzeniec gnomów.",
    ["O"] = "Otrzymałeś zadanie zabicia przeciwników Taurenów w Dolinie Alterac.$B$BZabij taurena i wróć do Dirka Swindle\'a w Dun Baldar z Taurenskim Kopytem.",
    ["T"] = "Nagroda Gnomereganowska",
  },
  [7365] = {
    ["D"] = "Staghelm wydał rozkaz. Wszystkie trolle na polu bitwy muszą zostać wytępione. Ich niedorzeczne roszczenia o narodzinach nocnych elfów muszą być spełnione siłą i należytym uprzedzeniem.$B$BZabij ich i wróć do mnie z ich Mojo. Powtarzam: chcę, żebyś ukradł ich Mojo.",
    ["O"] = "Otrzymałeś zadanie zabicia przeciwnych trolli w Dolinie Alterac.$B$BZabij trolla i wróć do Athramanisa w Dun\'Baldar z Darkspear Troll Mojo.",
    ["T"] = "Requiem Staghelma",
  },
  [7366] = {
    ["D"] = "Arcybiskup jest tak dobry, jak jest mądry. Dla mężczyzny, który miłosiernie patrzy na tak nieszczęsny los...$B$B<Dowódca Philips kręci głową z niedowierzaniem.>$B$BZa miły... Po prostu zbyt miły.$B$BArcybiskup prosi, abyśmy ulitowali się nad nieumarłymi i udzielili im szybkiej i trwałej śmierci. Do tego wielkiego pokazu miłosierdzia potrzebujemy jedynie swoich czarnych, chorych serc.$B$BPrzynieś mi serca Opuszczonych, aby mogli być ceremonialnie spaleni w Katedrze Światła. Pośpiesz się, $N!",
    ["O"] = "Otrzymałeś zadanie zabicia przeciwników Opuszczonych w dolinie Alterac.$B$BZabij Opuszczonych i wróć do Komandora Karla Philipsa (który wędruje między tartakiem, a kopalnią) z Opuszczonych Sercem.",
    ["T"] = "Miłosierdzie Arcybiskupa",
  },
  [7367] = {
    ["D"] = "Klan Mroźnych Wilków ma swoje linie frontu i bazy zaminowane pułapkami, $C. Podczas wkraczania na terytorium wroga musisz uważać gdzie stąpasz.$B$BJeśli im porządnie dowalić, to musisz zniszczyć ich źródło min przeciwpiechotnych - mówię o ich ekspercie od materiałów wybuchowych. Jeśli go zabijesz, możesz bezpiecznie rozbroić miny. Tak długo, jak ekspert będzie martwy, rozbrajanie min będzie bezpieczne.$B$BPrawdopodobnie znajdziesz go w wieży niedaleko Garnizonu Iceblood. Powodzenia!",
    ["O"] = "Znajdź Frostwolf Explosives Expert i zabij go. Wróć do Stormpike Explosives Expert, gdy zadanie zostanie ukończone.",
    ["T"] = "Rozbrajając zagrożenie",
  },
  [7368] = {
    ["D"] = "Wiem wszystko o minach lądowych. W końcu, to ja tutaj kładę wszystkie miny na liniach frontu.$B$BJeśli chcesz rozbroić pola minowe Stormpike, musisz tylko zabić eksperta od materiałów wybuchowych. Ten krasnoludzki tchórz bez wątpienia ukrywa się w pierwszej wieży na Field of Strife. Zdejmijcie go, wtedy te miny lądowe nie wrócą po rozbrojeniu.$B$BJeśli go zabijesz, wróć tu i daj mi znać. Żaden dobry uczynek nie powinien pozostać niewynagrodzony.",
    ["O"] = "Znajdź Stormpike Explosives Expert i zabij go. Po zakończeniu zadania wróć do Frostwolf Explosives Expert.",
    ["T"] = "Rozbrajając zagrożenie",
  },
  [7381] = {
    ["D"] = "Choć prawdą jest, że Korrak został zabity, nasuwa się jedno pytanie: czy pozostanie martwy? Trolle są znane z ich pozagrobowej magii plemiennej. Nie zdziwiłbym się, gdyby upadły przywódca został wskrzeszony, by raz jeszcze rządzić swoim klanem.$B$BWiesz, co zrobić, jeśli kiedykolwiek to nastąpi.$B$B<Warmaster Laggrond wykonuje ruch cięcia wzdłuż swojej szyi palcem wskazującym.>$B$BI tym razem chcę jego czaszkę. Po prostu miej oczy szeroko otwarte, żołnierzu.$B$BOdmaszerować!",
    ["O"] = "Gdyby Korrak the Bloodrager powrócił na Field of Strife, odszukaj go i zniszcz.$B$BZwróć Skull of Korrak do Warmaster Laggrond w Hillsbrad Foothills.",
    ["T"] = "Powrót Korraka",
  },
  [7382] = {
    ["D"] = "Jest w tym coś nie tak... Czy ktoś pomyślał, żeby spalić zwłoki Korraka? Trolle nie cofną się przed niczym, by ożywić swego upadłego przywódcę - jak to mają już w zwyczaju, te niebieskoskóre pogańskie bestie w ludzkim wcieleniu.$B$BTylko miej oczy otwarte, $N. Nie przejmuj się, jeśli Korrak niespodziewanie powróci; jeśli tak się stanie, to chcę, żeby został stracony, a jego zwłoki spalcie na popiół.$B$BŻeby mieć pewność, przynieś mi jego czaszkę, zanim podpalisz jego truchło.",
    ["O"] = "Gdyby Korrak the Bloodrager powrócił na Field of Strife, odszukaj go i zniszcz.$B$BWróć z Skull of Korrak do Lieutenant Haggerdin w Hillsbrad Foothills.",
    ["T"] = "Wiecznie żywy Korrak",
  },
  [7383] = {
    ["D"] = "Jednak nie wszystko poszło dobrze z zasadzeniem Teldrassilu. Staghelm starannie przygotował plany dotyczące wzrostu nowego Drzewa Świata, lecz był jeden mały problem, problem z którym wiele kłopotów w Teldrassilu może być powiązanych.$B$BJednak o tym porozmawiamy później. Musisz pójść do ostatniej księżycowej studni, na północny zachód Polany Wyroczni. Pod konarami Drzewa Wyroczni znajduje się pierwsza i najsilniejsza z naszych studni. Zdobądź fiolkę jej wody i wróć do mnie.",
    ["O"] = "Napełnij Amethyst Phial i zanieś ją do Corithrasa Moonrage w Dolanaarze.",
    ["T"] = "Korona Ziemi",
  },
  [7385] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Hektolitry krwi",
  },
  [7386] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Gromada Kryształów",
  },
  [7401] = {
    ["D"] = "Z rozkazu sierżanta Yazry Bloodsnarl wszystkie krasnoludy na polu bitwy mają zostać zabite w zasięgu wzroku.$B$BJeśli zabijesz krasnoluda w walce, wyrwij mu kręgosłup, pozostawiając bezkształtną kupę smrodu i zgnilizny; ma to służyć jako ostrzeżenie dla dowolnych i wszystkich, którzy ośmielą się przeciwstawić potędze Lodowego Wilka.$B$BWróć do sierżanta Yazry Bloodsnarl z dowodami swoich heroicznych czynów.",
    ["O"] = "Otrzymałeś zadanie zabicia przeciwnych krasnoludów w Dolinie Alterac.$B$BZabij krasnoluda i wyrwij mu kręgosłup. Zanieś Krasnoludowy Kręgosłup sierżantowi Yazrze Bloodsnarlowi w Frostwolf Keep.",
    ["T"] = "Poszukiwani: KRASNOLUDY!",
  },
  [7402] = {
    ["D"] = "Zgodnie z rozkazem kaprala Norega Stormpike wszyscy sprawni fizycznie żołnierze Stormpike są zobowiązani do zabicia wrogich orków, których spotykają na polu bitwy.$B$BŻołnierze są zobowiązani do usunięcia kłów lub zębów z paszczy wroga i przedstawienia zęba, jako dowodu realizacji zadania.$B$BNoś rękawice ochronne.",
    ["O"] = "Otrzymałeś zadanie zabicia przeciwnych orków w Dolinie Alterac.$B$BZabij orka i weź jego orkowy ząb do kaprala Norega Stormpike w Dun Baldar.",
    ["T"] = "Poszukiwani: ORKOWIE!",
  },
  [7421] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Darkspear Defense",
  },
  [7422] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Tuft it Out",
  },
  [7423] = {
