    ["T"] = "I\'ve Got A Fever For More Bone Chips",
  },
  [7424] = {
    ["D"] = "",
    ["O"] = "Spraw im lanie, $N. Niech nauczą się, że gnomy nie dadzą sobą pomiatać!",
    ["T"] = "Co do kopyta?",
  },
  [7425] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Staghelm\'s Mojo Jamboree",
  },
  [7426] = {
    ["D"] = "",
