  [7681] = {
    ["D"] = "Cast feed pet on your pet.",
    ["O"] = "Feed your pet, then talk to your questgiver.",
    ["T"] = "Hunter test quest",
  },
  [7682] = {
    ["D"] = "Cast feed pet on your pet.",
    ["O"] = "Feed your pet, then talk to your questgiver.",
    ["T"] = "Hunter test quest2",
  },
  [7701] = {
    ["D"] = "Z rozkazu Jego Wysokości: Zdrajca Overseer Oilfist agent Thorium Brotherhood, jako nowy dowódca Dark Iron Slag Pit bandy Cauldron powinien zostać zabity. Jego głowę, jako dowód, należy pokazać Lookout Captan Lolo Longstriker, który wynagrodzi wysiłek za ten czyn.",
    ["O"] = "Głęboko w Slag Pit of the Cauldron, w Searing Gorge, znajdziesz zdradzieckiego krasnoluda o imieniu Overseer Maltoriu.$B$BZabij Overseer Maltoriu, a jako dowód weź jego głowę. Wróć z nią do kapitana Lookout Lolo Longstrikera w Searing Gorge, aby otrzymać nagrodę.",
    ["T"] = "POSZUKIWANY: Overseer Maltorius",
  },
  [7703] = {
    ["D"] = "Teraz ty jesteś król, to może odzyskasz cenny artefakt Gordoków od strasznego elfa, który nazywa siebie księciem! Król przed tobą nie dał rady, tak samo jak inni królowie, od kiedy Tortheldrin – ten straszny elf – ukradł go od starożytnego króla Gordoków!$B$BArtefakt nazywa się Rękawica Siły Gordoków. Opowieści z dawnych czasów mówią, że tylko prawdziwy król Gordoków może ją odzyskać. Opowieści z dawnych czasów mówią też, że straszny elf ciągle się tu kręci. Znajdź ją, a stanie się potężną rękawicą, którą będziesz nosić na zawsze! Tak, pokażę ci!",
    ["O"] = "Znajdź Gauntlet of Gordok Might i zwróć ją Captainowi Kromcrushowi z Dire Maul.$B$BWedług Kromcrusha \"opowieść z dawnych czasów\" mówi, że Tortheldrin - \"straszny\" elf, nazywający siebie księciem – ukradł ją pewnemu królowi Gordoków.",
    ["T"] = "Niedokończone sprawy Gordoków",
  },
  [7704] = {
    ["D"] = "Proszę, proszę, proszę... Nie jest to niespodzianka. Chambermaid miała gigantyczną ozdobną poduszkę, a teraz należy ona do ciebie. Evonice Sootsmoker na pewno będzie chciała położyć na niej swoje małe, grube łapska. Zabierz ją do niej i sprawdź, czy zaoferuje ci jakieś drobiazgi za twoją fatygę.",
    ["O"] = "Zanieś Chambermaid Pillaclencher\'s Pillow do Evonice Sootsmoker w Searing Gorge.",
    ["T"] = "Spójrz na rozmiar tego!",
  },
  [7721] = {
    ["D"] = "Jeśli chcę postawić wszystko na jedną kartę i zostać, aby prowadzić sklep inżynieryjny wzdłuż Forgotten Coast, będę musiał poradzić sobie z tymi cholernymi żywiołakami. Przeklinam niezbadane moce elementalizmu!$B$BNa szczęście pojawiłeś się i dałeś mi nadzieję, żywiołaki stanowią idealne źródło pierwotnej mocy dla mojego wyrafinowanego Ultra-Shrinker - daj im to, na co zasłużyły! Kiedy będziesz to robił pamiętaj aby ratować rdzenie żywiołów dla mnie!",
    ["O"] = "Zdobądź 10 Water Elemental Cores zabijając Sea Elementals oraz Sea Sprays, znajdziesz je na Forgotten Coast w Feralas. Zanieś je Zorbin Fandazzle, który znajduje się w pobliżu doków.",
    ["T"] = "Paliwo do zmniejszania",
  },
  [7722] = {
    ["D"] = "Gdy tylko zdrajca, Maltorius, opuścił nasz klan, zostawił coś cenniejszego, niż nieskazitelny tajemniczy kryształ: nasz przepis na ognisty strumień! Mogę się założyć o wszystko, że właśnie ta receptura była warunkiem umowy do jego awansu wśród Czarnorytnich.$B$BChcę, abyś odzyskał z powrotem nasz przepis, $N. Jestem pewien, że jest gdzieś niedaleko Maltoriusa, głęboko w Slag Pit.",
    ["O"] = "Gdzieś w Slag Pit of the Cauldron znajdziesz Secret Plans: Fiery Flux, które Overseer Maltorius ukradł. Znajdź te plany i zwróć je do Master Smith Burninate w Searing Gorge.",
    ["T"] = "Co do strumienia?",
  },
  [7723] = {
    ["D"] = "Niestety nie jestem w stanie mierzyć się z bestiami, jak kiedyś, wszystko przez mój problem z grubymi palcami. Widzisz, tutejszy klimat w połączeniu z brakiem powietrza powoduje, że moje palce się powiększają. Są jak ogromne Thelsamar Blood Sausages, są...$B$BBędziesz musiał wcielić w życie moje rozporządzenie.$B$BPierwsza część programu: Utłuc Heavy War Golems z Gorge na kwaśne jabłko. Bierz się do roboty.",
    ["O"] = "Hansel Heavyhands chce, abyś zabił 20 Heavy War Golem.$B$BHeavy War Golem włóczą się wokół The Cauldron w Searing Gorge. Kiedy już zabijesz ich wystarczająco dużo, wróć do Hansela w Searing Gorge.",
    ["T"] = "Przeklęte, grube palce",
  },
  [7724] = {
    ["D"] = "Nigdy byś się nie domyślił, że za każdym razem, kiedy stary Hansel chce zaczerpnąć oddechu, aby przez chwile odpocząć i zastanowić się nad swoim życiem, wzywa go następna robota.$B$BMyślę sobie, serio?! Wiesz o czym mówię? SER-IO.$B$BNo więc, te Greater Lava Spiders powodują nie lada zamieszanie. Oilfist mówi, że strzelają ogniem z... erm, no wiesz, w każdym razie takie wydarzenia niepokoją dzieci.$B$BI Chyba będziemy musieli je utłuc. A raczej... Ty będziesz musiał je utłuc.",
    ["O"] = "Hansel Heavyhands chce, abyś zabił 20 Greater Lava Spiders w Searing Gorge. Greater Lava Spiders można znaleźć na płaskowyżach i w zbiornikach z lawą, w rejonie Searing Gorge.$B$BWróć do Hansel Heavyhands w Searing Gorge, kiedy zabijesz odpowiednią ilość Greater Lava Spiders.",
    ["T"] = "Ogniste niebezpieczeństwo!",
  },
  [7725] = {
    ["D"] = "Wiem, że już zebrałeś resztki dla mnie..., ale może chcesz na bis w wolnej chwili pozbierać, mogę zawsze użyć więcej tych resztek.$B$BNie mogę zaoferować podobnego wynagrodzenia, będę zachwycony szepnąć słówko o twych usługach do moich wszystkich goblińskich przyjaciół.$B$BUwierz mi chłopcze, kiedy mówię o całkiem długich uszach.",
    ["O"] = "Użyj Zorbin\'s Ultra-Shrinker, by przemienić każdy rodzaj giganta znalezionego w Feralas w bardziej posłuszne formy. Przynieś 10 Miniaturization Residues znalezionych w porażonych wersjach tych gigantów do Zorbina Fandazzle znajdującego się w docks of the Forgotten Coast w Feralas",
    ["T"] = "Znowu z Porażonymi Gigantami",
  },
  [7726] = {
    ["D"] = "Chcesz więcej pracy, hmm? Czyżby heroiczna misja zbierania kawałków Goo z Elemental Beings nie zaspokoiła twojej żądzy przygód? Być może takie misje nie są dla ciebie wystarczającym wyzwaniem....NEWLINE$BOK, tak czy inaczej, potrzebuję więcej Water Elemental Cores. Próbuję zbudować tutaj sklep, więc nagroda nie będzie za wysoka... ale hej! Znam tutaj wielu ciekawych ludzi. Szepnę im o tobie dobre słowo.",
    ["O"] = "Zbierz 6 Water Elemental Cores z Sea Elementals i Sea Sprays wzdłuż Forgotten Coast of Ferals i przynieś je do Zorbin Fandazzle, który jest niedaleko doków.",
    ["T"] = "Więcej paliwa dla Zapping",
  },
  [7727] = {
    ["D"] = "Halluksy, chłopcze. Ja mam halluksy, dostałem halluksy. Jak mam dokonywać jakiegokolwiek rodzaju mordobicia z moją stopą w takim stanie? Dlatego TY mi pomożesz.$B$BScrange i Burninate nakazał mi zabić te stworzenia, aby oni mogli wysłać kilka drużyn ekspedycyjnych do basenów lawy w Płonącym Wąwozie, by zrobić trochę eksploracji. Podobno niektóre Incendozaury lub jakieś takie bzdury tu na dole powodują różnego rodzaju problemy. Ruszaj w końcu i nie wracaj dopóki populacji Incendozaurów nie będzie zagrażało wyginięcie.",
    ["O"] = "Hansel Heavyhands chce, abyś zabił 20 Incendozaurów.$B$BZnajdziesz Incedozaury okupujące baseny lawy wewnątrz Popielnych Sideł. Popielne sidła znajdują się w Cauldron of the Searing Gorge.$B$BWróć do Hansela Heavyhandsa w Searing Gorge kiedy zabijesz wystarczająco Incendozaurów.",
    ["T"] = "Incedozaury? Co kolwiekozauro jest bardziej podobne.",
  },
  [7728] = {
    ["D"] = "Skradzione zostały następujące przedmioty:$B$B* Jedna dysza powietrzna Czarnego Żelaza.$B$B* Jedna Luneta straży.$B$BOferowana jest nagroda dla tych, którzy znajdą i zwrócą skradzione przedmioty.$B$BBractwo Toru ma pewność, że przedmioty te zostały skradzione przez pozbawionych skrupułów i zazdrosnych krasnoludów Czarnprytnych, którzy zamieszkują Płonący Wąwóz.$B$BLuneta, o której mowa, była doskonałym przyrządem dla strażników, a dysza powietrzna niezastąpionym narzędziem kowali.$B$BJeśli znajdziesz zaginione przedmioty, zwróć je Scrange\'owi.",
    ["O"] = "Znajdź i zwróć Smithing Tuyere i Lookout\'s Spyglass do Nadzorcy Scrange\'a w Searing Gorge.$B$BJedyne informacje, jakie posiadasz na temat tych przedmiotów to kolejno: zdecydowanie zostały skradzione przez krasnoludy z klanu Czarnorytnych. Smithing Tuyere to narzędzie kowalskie używane przez kowali, natomiast Lookout\'s Spyglass jest nieocenionym narzędziem monitorującym dla obserwatorów.",
    ["T"] = "SKRADZIONE: Kowalska dysza powietrzna i Luneta straży",
  },
  [7729] = {
    ["D"] = "Taskmaster Scrange szuka kilku dobrych mężczyzn i kobiet do pomocy przy Odstrzale Konkurencji w Searing Gorge.$B$BJeżeli jesteś zainteresowany tą ofertą, wypraw się do Searing Gorge i zamorduj każdego Dark Iron Taskmastera i Dark Iron Slavera, którego zobaczysz.$B$BWróć do Taskmastera Scrangea, gdy twoje ubrania będą wystarczająco nasączone krwią.$B$BSam będziesz wiedział, kiedy będą wystarczająco nasączone krwią, więc nie pytaj.",
    ["O"] = "Zabij 15 Dark Iron Taskmasterów i 15 Dark Iron Slaverów. Wróć do Taskmastera Scrangea w Searing Gorge, gdy ukończysz swoje zadanie.",
    ["T"] = "OFERTA PRACY: Odstrzał Konkurencji",
  },
  [7730] = {
    ["D"] = "Ze zwiadów, które udało nam się przeprowadzić, wnioskujemy, że wróg na południe od gnolli, to rasa owado-podobna. Szczerze mówiąc, to bez znaczenia czy są istotami czującymi, czy nie. Jeżeli doprowadzają gnolle do szału przeciwko nam, to są dla nas dużym zagrożeniem, o ile nie większym, niż same gnolle.$B$BWejdź wgłąb miejsca, w którym te robaki Zukk\'ash żyją. Miejsce to jest znane jako Writhing Deep. Zmniejsz ich liczebność i zgłoś się do mnie z powrotem z tym, co uda ci się ustalić. Przynieś ich pancerzyki, jako dowód wykonanej roboty.",
    ["O"] = "Przynieś 20 Zukk\'ash Carapaces Hadokenowi Swiftstriderowi w Camp Mojache w Feralas.",
    ["T"] = "Pomór Zukk\'ash",
  },
  [7731] = {
    ["D"] = "Analizując teren Writhing Deep, jeden z tropicieli zauważył olbrzymiego owada - znacznie większego od innych w rejonie - szwendającego się po zawiłym terenie. Owad ten, nie tylko większy od innych, ale emanował także aurą, której pozostałe owady nie posiadały. Nadaliśmy mu imię - Stinglasher. Wnętrzności tej bestii byłyby jednak bezwartościowe dla naszych badań, gdyż mamy już sposób na te nowe zagrożenie. Odetnij jego gruczoły i przynieś do mnie jak najszybciej!",
    ["O"] = "Pokonaj Stinglashera w Writhing Deep i zanieś jego gruczoły do Hadoken Swiftstrider w Mojache Camp w Feralas.",
    ["T"] = "Stinglasher",
  },
  [7732] = {
    ["D"] = "Świetnie sobie poradziłeś przy rozpoznaniu zagrożenia jaimi są insekty Zukk\'ash nieopodal obozu Mojache. Jednakże nie jest to jeszcze koniec niebezpieczeństwa, dlatego chciałem cię prosić o jeszcze jedną przysługę.$BTen dokument zawiera wszystkie informacje jakie mamy o tych owadach. Chciałbym żebyś dostarczył go Zilzibinowi Drumlore, znajdziesz go Drag w Orgrimmar. Jest ekspertem od dziwnych stworzeń takich ja te. Mam nadzieje, że przyda mu się wiedza, która zdobyłeś.",
    ["O"] = "Doręcz Camp Mojache Zukk\'ash Report do Zilzibin Drumlore. Znajdziesz go w Drag w Orgrimmar.",
    ["T"] = "Raport Zukk\'ash",
  },
  [7733] = {
    ["D"] = "Mam trop na jeszcze LEPSZE źródło skór, jeżeli jesteś w ogóle w stanie w to uwierzyć! W północnych częściach Feralas - głęboko pośród Rage Scar Hold - jest kolejna grupa Yeti. Są znacznie silniejsze niż te, z którymi już sobie poradziliście. Jeżeli jesteś gotów na kolejne wyzwanie, lepiej się przygotuj! Wynagrodzę cię sowicie za stos dziesięciu futer; przynieś mi je tutaj, a dokończymy interes.",
    ["O"] = "Przynieść 10 Skór Rage Scar Yetich do Pratta McGrubben\'a w Feathermoon Stronghold znajdującej się w Feralas.",
    ["T"] = "Zwiększona jakość",
  },
  [7734] = {
    ["D"] = "Jestem na tropie jeszcze lepszego źródła skór, jeżeli w ogóle można w to uwierzyć! W północnej części Feralas - w głębi Rage Scar Hold - znajdziesz kolejną sforę Yetich. Są one jednak o wiele silniejsze, niż te, z którymi walczyłeś do tej pory, więc jeśli pragniesz większego wyzwania, musisz mieć się na baczności!$B$BSzczodrze cię wynagrodzę za 10 skór tych bestii; przynieś je do mnie, a dobijemy targu.",
    ["O"] = "Przynieś 10 skór Rage Scar Yeti do Jangdora Swiftstridera w Camp Mojache, Feralas.",
    ["T"] = "Lepsza jakość",
  },
  [7735] = {
    ["D"] = "Znalazłeś nieskazitelną skórę yeti, która jest niezwykle gruba i solidna - nawet bardziej od tych z Rage Scar Yetich.$B$BZważając na to, że Pratt McGrubben z Feathermoon Stronghold jest mocno zainteresowany skórami yeti, te mogą okazać się być wręcz idealne dla niego.",
    ["O"] = "Przynieś Pristine Yeti Hide do Pratta McGrubben\'a w Feathermoon Stronghold, w Feralas.",
    ["T"] = "Nieskazitelne skóry Yeti",
  },
  [7736] = {
    ["D"] = "",
    ["O"] = "Przywrócenie Fiery Flux Supplues przez Kingsblood",
    ["T"] = "Restoring Fiery Flux Supplies via Kingsblood",
  },
  [7737] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Uzyskanie jeszcze większej akceptacji",
  },
  [7738] = {
    ["D"] = "$gZnalazłeś:Znalazłaś; coś, co może być idealną skórą z yeti. Z łatwością spostrzegasz, że jest ona wyjątkowo wytrzymała i gruba - o wiele bardziej niż te, które $gwidziałeś:widziałaś; u yeti we Wściekłej Bliźnie.$B$BBiorąc pod uwagę to, że Jangdor Swiftstrider z Obozu Mojache chce kupić skóry z yeti, ta konkretna może go w szczególności zainteresować.",
    ["O"] = "Zanieś Perfect Yeti Hide do Jangdora Swiftstridera w Camp Mojache, w Feralas.",
    ["T"] = "Idealna skóra yeti",
  },
  [7761] = {
    ["D"] = "Debilu.$B$BNie wierzę w to, że będziesz w stanie powstrzymać obcych przed dostaniem się do kryjówki mistrza. W razie twojej bardzo-prawdopodobnej śmierci, ta kula m wbudowany system, który powstrzyma obcych przed przedostaniem się bezpośrednio do Blackwinga. Tylko ci napiętnowani Znakiem Drakkisath\'a mogą użyć tej kuli. Szczęśliwie, Drakkisath nie jest aż tak niekompetentny, jak ty, kwatermistrzu. Broni tego piętna sam!$B$B-Wódz Rend Blackhand$B$BP.S. Zniszcz ten list, idioto.",
    ["O"] = "Ten głupi ork. Wygląda na to, że potrzebujesz znaleźć te piętno i zdobyć Znak Drakkisath\'a, żeby dostać się do Kuli Dowodzenia. Listy wskazują na to, że Generał Drakkisath chroni tego piętna. Być może powinieneś się rozejrzeć?",
    ["T"] = "Rozkaz Blackhand\'a",
  },
  [7781] = {
    ["D"] = "Stare uczucia powracają. To zwycięstwo odbije się echem. Przed tobą leży monolityczna, poorana od walk głowa Nefariana. Zwróć ją do Stormwind, $gbohaterze:bohaterko;.",
    ["O"] = "Zwróć głowę Nefariana do wysokiego lorda Bolvara Fordragona w Stormwind.",
    ["T"] = "Lord Czarnej Skały",
  },
  [7782] = {
    ["D"] = "Udaj się do Doliny Bohaterów i porozmawiaj z marszałkiem polowym Afrasiabi.",
    ["O"] = "Udaj się do Doliny Bohaterów w mieście Stormwind i porozmawiaj z marszałkiem polowym Afrasiabi.",
    ["T"] = "Lord Czarnej Skały",
  },
  [7783] = {
    ["D"] = "Stare uczucie powraca. Powitalne ukłucie zwycięstwa rozbrzmiewa w całym twoim ciele. Przed tobą leży monolityczny, zadrapany w bitwie łeb Nefariana. Zwróć go do swojego wodza wojennego, $gbohaterze:bohaterko;.",
    ["O"] = "Zwróć Head of Nefarian do Thralla w Orgrimmarze.",
    ["T"] = "Pan Czarnej Góry",
  },
  [7784] = {
    ["D"] = "Odnajdź naczelnika Runthaka w Dolinie Siły.",
    ["O"] = "Porozmawiaj z naczelnikiem Runthakiem w Orgrimmarze. Oczekuje ciebie w Valley of Strength.",
    ["T"] = "Pan Czarnej Góry",
  },
  [7785] = {
    ["D"] = "Zbadaj naczynie jego odrodzenia, śmiertelniku. To właśnie z niego odrodzi się Windseeker!",
    ["O"] = "Zbadaj Vessel of Rebirth i zwróć je Highlordowi Demitrianowi.",
    ["T"] = "Zbadaj naczynie",
  },
  [7786] = {
    ["D"] = "Powiedziałem ci już to, co wiem, $N. To ty musisz znaleźć elementium. To ty musisz zniszczyć fizyczną formę Firelorda.$B$BZrób to, a otrzymasz błogosławieństwo Thunderaana.",
    ["O"] = "By uwolnić Thunderaana Windseekera z jego więzienia, musisz zanieść prawą i lewą połowę Bindings of the Windseeker, 10 sztabek Enchanged Elementium oraz Essence of the Firelord do Highlorda Demitriana w Silithus.",
    ["T"] = "Thunderaan the Windseeker",
  },
  [7787] = {
    ["D"] = "Pokonałeś Poszukiwacza Wiatru. Zabierz uśpione ostrze i zmuś tego kłamliwego łajdaka, Demitriana, aby wykorzystał przedmioty, którymi opłaciłeś jego zdradę, do obudzenia Furii Gromu.",
    ["O"] = "Pokaż Dormant Wind Kissed Blade Highlordowi Demitrianowi.",
    ["T"] = "Powstań, Furio Gromu!",
  },
  [7788] = {
    ["D"] = "Za tym tunelem znajdziesz pole walki i zgiełku, młody $C. Horda cały czas niszczy nasz święty las, wycinając wiecznie zieloną roślinność, aby nakarmić swoje machiny wojenne.$B$BWejdź do Warsong Gulch i obroń Silverwing Hold. Uczyń to i zdobądź talizman zasługi. Przynieś mi go, a cię nagrodzę, $N.",
    ["O"] = "Wejdź do Warsong Gulch i pokonaj Hordę, zdobądź Warsong Gulch Mark of Honor i powróć do Sentinel Farsong z Silverwing Grove.",
    ["T"] = "Pokonaj najeźdźców!",
  },
  [7789] = {
    ["D"] = "Dziki las Ashenvale ulegnie potędze Hordy, $R7. Nic co robią nie może pozostać bez odzewu. Kalimdor należy do Hordy. Jak śmieją powstrzymać nas przed odebraniem tego co nasze!$B$BNiech duma rośnie w twoim sercu, gdy zniweczysz ich próbę spowolnienia naszego postępu. Zniszcz wartowniczki Silverwing, i zdobądź znak honoru Pieśni Wojennej. Wróć do mnie z nim, $N a zostaniesz nagrodzony.",
    ["O"] = "Wejdź do Warsong Gulch i pokonaj Przymierze, zdobądź Warsong Gulch Mark of Honor i zanieś go kapitanowi Shatterskull w Mor\'shan Base Camp.",
    ["T"] = "Stłumić Silverwing Usurpers",
  },
  [7790] = {
    ["D"] = "Defeat the Warsong Mill, then return to me.",
    ["O"] = "",
    ["T"] = "REUSE",
  },
  [7791] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Donacja wełny",
  },
  [7792] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Darowizna wełny",
  },
  [7793] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Darowizna Jedwabiu",
  },
  [7794] = {
