  [7836] = {
	["D"] = "$N, wielce przysłużyłeś się naszej zbiórce tkanin. Gdy niestrudzenie pracujemy nad uzupełnieniem zapasów, muszę oznajmić ci, który z naszych braków jest najdotkliwszy - runiczne sukno. Potrzeba nam go rozpaczliwie i mamy nadzieję, że wesprzesz nas tak, jak czyniłeś to już wcześniej.$BJeśli masz ku temu wolę, przynieś mi tyle runicznego sukna, ile zdołasz odstąpić. Na początek przyjmiemy jednorazową darowiznę sześćdziesięciu sztuk, a potem zobaczymy, co dalej.",
	["O"] = "Dostarcz 60 sztuk runicznego sukna Rashonie Straglash.",
	["T"] = "Darowizna runicznego sukna",
  },
  [7837] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Dodatkowe runiczne sukno",
  },
  [7838] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Wielki mistrz areny",
  },
  [7839] = {
    ["D"] = "Męty z Plugawej Gałęzi napadły na naszą wioskę i ukradły moje narzędzia! Mam zapasowy zestaw, lecz te, które mi ukradziono, dostałem od pewnego miłego gnoma, który uratował mi życie, kiedy byłem jeszcze małym orkiem.$B$BChcę moje narzędzia z powrotem, $N - są dla mnie wszystkim.$B$BMarkhor doniósł, że widziano je w pobliżu świątyń Agol\'watha i Shaol\'watha.$B$BTe świątynie znajdują się w północno-wschodnim rejonie Hinterlands.$B$BOdzyskaj je!",
    ["O"] = "Smith Slagtree z Revantusk Village w Hinterlands chce, abyś znalazł Slagtree\'s Lost Tools. Wróć do niego, gdy wykonasz zadanie.$B$BPrzypominasz sobie, że Smith Slagtree wspominał, że narzędzia mogą być w jednej ze świątyń trolli Vilebranch w północno-wschodnim rejonie Hinterlands. Powinieneś także sprawdzić Skulk Rock.",
    ["T"] = "Zbiry Plugawej Gałęzi",
  },
  [7840] = {
    ["D"] = "Lard był w super tajna miejsce na pikniku, gdy wstrętny nędznik z Plugawej Gałęzi walnął Larda wielkim kijem. Lard uciekł do Revantusk, ale zapomniał obiadu Larda. Lard głodny. Może ty pójść do super tajna miejsce i przynieść Lardowi obiad? Lard się boi. Idź na północ! Tam wyspa na północ i super tajna miejsce.",
    ["O"] = "Lard z Revantusk Village w Hinterlands chce, abyś znalazł Lard\'s Lunch. Wróć do niego, kiedy wykonasz zadanie.$B$BLard wspomniał, że zostawił obiad na wyspie na północy. Uważaj na trolle Vilebranch.",
    ["T"] = "Lard zgubił obiad",
  },
  [7841] = {
    ["D"] = "Dzikie Młoty zawierają ugody z naszymi wrogami i zawiązują nowe sojusze. Tym razem, kolego, będą współpracować z wysokimi elfami.$B$B<Otho spluwa.>$B$BMusimy wysłać wiadomość krasnoludom Dzikiego Młota - wiadomość pisaną krwią naszych wrogów. Zaszlachtuj każdego wysokiego elfa z Wysokiej Doliny, jakiego napotkasz; ciała pozostaw jako ostrzeżenie.$B$BNigdy nie zadzieraj z trollami!",
    ["O"] = "Otho Moji\'ko z Revantusk Village w Hinterlands chce, abyś zamordował 8 Highvale Scouts, 5 Highvale Outrunners, 5 Highvale Rangers i 2 Highvale Marksman. Wróć do niego, kiedy wykonasz zadanie.$B$BWysokie elfy z Highvale znajdziesz w Quel\'Danil Lodge w północno-zachodnim rejonie Hinterlands.",
    ["T"] = "Wiadomość dla Dzikich Młotów",
  },
  [7842] = {
    ["D"] = "Mówi się, że Dzikie Młoty i gryfy są sobie równie bliskie, co para trolli. To obrzydliwe, jednak wykorzystamy to na naszą korzyść, kolego. Wyślemy krasnoludom kolejną wiadomość.$B$BZabij każdego gryfa, jakiego spotkasz w Ostępach, i zbierz ich pióra. Zrobimy z nich finalną wiadomość.",
    ["O"] = "Otho Moji\'ko z Revantusk Village w Hinterlands chce, abyś przyniósł mu 1 Long Elegant Feather z gryfów zamieszkujących tę krainę. Wróć do niego, gdy wykonasz zadanie.$B$BGryfy zamieszkują wszystkie rejony Hinterlands.",
    ["T"] = "Kolejna wiadomość dla Dzikich Młotów",
  },
  [7843] = {
    ["D"] = "<Otho wręcza ci długą, usmarowaną krwią dzidę, przystrojoną piórami gryfów.>$B$BWeź to, kolego. Zanieś do Aerie Peak, pod studnię w samym środku miasta. Wbij to prosto w ziemię! Pokaż tym krasnoludom, że zadzieranie z trollami to kiepski pomysł! Wróć, gdy tego dokonasz. Mam nadzieję, że w jednym kawałku.",
    ["O"] = "Otho Moji\'ko z Revantusk Village w Hinterlands chce, abyś udał się do Aerie Peak w zachodnim rejonie Hinterlands i umieścił Final Message to the Wildhammer przy studni w centrum miasta. Wróć do niego, gdy wykonasz zadanie.$B$BUważaj na rozgniewanych krasnoludów Wildhammer i krnąbrnych członków Przymierza.",
    ["T"] = "Finalna wiadomość dla Dzikich Młotów",
  },
  [7844] = {
    ["D"] = "W Hinterlands mieszkają trzy różne plemiona trolli, $N. Jedyne, co je łączy, to to, że są trollami i zamieszkują Hinterlands.$B$BPlugawe Gałęzie - trafna nazwa - są zdeprawowaną bandą; żywią się innymi trollami i humanoidami.$B$BGdyby Zul\'jin tu był, zniszczyłby całe ich plemię jednym ruchem ręki – niestety Zul\'jin dotychczas nie wrócił i jesteśmy zdani na siebie.$B$BTeraz do ciebie należy oczyszczenie tego regionu z plugastwa!",
    ["O"] = "Mystic Yayo\'jin z Revantusk Village w Hinterlands chce, abyś zabił 6 Vilebranch Scalpers and 2 Vilebranch Soothsayers. Wróć do niej, gdy ukończysz zadanie.$B$BYayo\'jin zaznaczyła, że trolle te znajdziesz w okolicach świątyń Shaol\'watha i Agol\'watha w północno-wschodnim rejonie Hinterlands.",
    ["T"] = "Kuzyni kanibale",
  },
  [7845] = {
    ["D"] = "Mój małżonek został uprowadzony przez dzikusów Plugawej Gałęzi podczas napadu na naszą wioskę w środku nocy. Szpiedzy donieśli mi, że ciągle żyje i jest więziony na szczycie Jintha\'alor. Ponoć Nikczemna Kapłanka Hexx przygotowuje go do złożenia w ofierze bezobliczowemu bogu krwi, Hakkarowi.$B$BMusisz go uratować, $N! Naszej wioski nie stać na tak wielką stratę.",
    ["O"] = "Primal Torntusk z Revantusk Village w Hinterlands chce, abyś uratował z Jintha\'alor jej małżonka, Elder Torntuska.$B$BPowiedziała ci, że jest on więziony na szczycie Jintha\'alor, stolicy Vilebranch położonej w południowym rejonie Hinterlands.",
    ["T"] = "Porwano Starszego Torntuska!",
  },
  [7846] = {
    ["D"] = "Klucz do moich kajdan ma Opiekunka Hitah\'ya. Przebywa w pobliskiej jaskini. Uważaj $C, jest dobrze strzeżona.$B$BZabij ją, przynieś klucz i uwolnij mnie z więzów. Tylko wtedy będę mógł wrócić do domu.",
    ["O"] = "Elder Torntusk w Jintha\'alor chce, abyś zabił Hitah\'yę the Keeper i zdobył Shackle Key do jego kajdan. Wróć do niego, gdy tego dokonasz.",
    ["T"] = "Zdobądź klucz!",
  },
  [7847] = {
    ["D"] = "Wróć do mojej koleżanki Primal Torntusk w Osadzie Revantusk. Przekaż jej, że wracam do domu! Ona oczywiście cię wynagrodzi.",
    ["O"] = "Elder Torntusk z Jintha\'alor chce, byś wrócił do Primal Torntusk w Revantusk Village z wieściami o jego uratowaniu.",
    ["T"] = "Wróć do Primal Torntusk",
  },
  [7848] = {
    ["D"] = "Szczeliny się wzbudzają, pękają i rozpadają wokół nas, $R7. Dwa kroki od miejsca, w którym stoję, znajduje się wyłom prowadzący do głębin Góry Blackrock - paszczy lorda ognia.$B$B$gZaskoczony:Zaskoczona;? Żal mi ciebie... Śmiertelne rasy nie mogą pojąć tego, czego nie mogą zobaczyć, dotknąć lub odczuć.$B$BZapewniam cię, portal jest niedaleko, a dostęp do niego jest możliwy.$B$BWzbudziłem twoją ciekawość? Warunek jest prosty. Idź do Blackrock Depths i zdobądź fragment rdzenia. Oddaj mi go, a ja zestroję twoją esencję z portalem.",
    ["O"] = "Podąż do portalu prowadzącego do Molten Core w Blackrock Depths i zdobądź Core Fragment. Wróć do Lothosa Riftwaker w Górze Blackrock, gdy zdobędziesz Core Fragment.",
    ["T"] = "Dostrojenie do rdzenia",
  },
  [7849] = {
    ["D"] = "Jak wielu w naszej wiosce, ja również straciłem drogą mi osobę w puszczy. Niestety, był to mój brat bliźniak Malkhor - zabrany w tym samym najeździe Vilebranch, jak partnerka Torntuska..$B$BNiestety, nie przyszło mu przeżyć - został obdarowany szybką, lecz brutalną egzekucją, szlamy i wilki Vilebranch zostały nakarmione jego zwłokami.$B$BJest zbyt późno na uratowanie jego życia ale nie duszy. Odzyskaj jego szczątki, $N.",
    ["O"] = "Łowca Markhor w wiosce Revantusk w Hinterlands chce, byś odzyskał zwłoki jego brata bliźniaka. Znajdź i przynieś Huntsman Malkhor\'s Skull oraz Huntsman Malkhor\'s Bones Łowcemu Markhorowi.$B$BMarkhor wspomniał, że szlamy i wilki z Vilebranch zostały nakarmione zwłokami jego brata. Wspomniał również, że w Jintha\'alor można znaleźć dół z odpadami, jak również legowisko wilków. Oba te miejsca są blisko szczytu świątyni.",
    ["T"] = "Tęsknota",
  },
  [7850] = {
    ["D"] = "Vilebranchowie walczą z nadnaturalną dzikością. To wszystko przez odrażająco magię Vile Priestess Hexx.$B$BW całym Jintha\'alor znajdziesz Mroczne Naczynua spaczonej krwi. Naczynia te emanują okropną magią bez-twarzowego boga krwi, wzmacniającego Vilebranche, jednocześnie doprowadzając je do szaleństwa.$B$BUkradnij te naczynia i powróć z nimi do mnie, abym usunął z nich spaczenie, uwalniając je z pod władzy boga krwi.",
    ["O"] = "Primal Torntusk z Revantusk Village w Hinterlands chce, abyś odzyskał 5 Vessel of Tainted Blood w Jintha\'alor. Wróc do Primal Torntuska, gdy zadanie będzie skończone.",
    ["T"] = "Mroczne Naczynia",
  },
  [7861] = {
    ["D"] = "Z rozkazu Primal Torntuska, Vile Priestess Hexx i jej przyboczni muszą spotkać się ze sprawiedliwością!$B$BWielka nagroda dla tych, którzy zgładzą ją i jej elitarną gwardię Aman\'zasi.",
    ["O"] = "Dostałeś rozkaz zgładzenia Vile Priestess Hexx oraz 5 Vilebranch Aman\'zasi Guards. Odszukaj Primal Torntuska w Revantusk Village, w Hinterlands, jeżeli ci się powiedzie.$B$BZarówno Vile Priestess Hexx, jak i jej sługi odnajdziesz na szczycie Jintha\'alor w Hinterlands.",
    ["T"] = "Poszukiwana: Vile Priestess Hexx i jej sługusy",
  },
  [7862] = {
    ["D"] = "Po stracie kapitana straży Malkhora, mamy otwarty etat w zastępstwie na jego miejsce. Jeśli chciałbyś zostać kapitanem straży Revantusk, wykonaj to zadanie i prześlij swoją aplikacje do Primal Torntuska:$B$BWyeliminuj berserkerów Vilebranch.$B$BWyeliminuj Łowców CieniVilebranch.$B$BWyeliminuj krwiopijców Vilebranch.$B$BWyeliminuj zjadaczy dusz Vilebranch.",
    ["O"] = "Masz za zadanie zabić: 5 Vilebranch Berserkers, 3 Vilebranch Shadow Hunters, 3 Vilebranch Blood Drinkers oraz 2 Vilebranch Soul Eaters.$B$BPozakończeniu zadania wróć do Primal Torntusk w wiosce Revantusk w Hinterlands.",
    ["T"] = "Oferta pracy: Kapitan straży w Revantusk Village",
  },
  [7863] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Podstawowe wyposażenie strażnika",
  },
  [7864] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Podstawowe wyposażenie strażnika",
  },
  [7865] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Wartowniczy pakiet zaawansowanej opieki",
  },
  [7866] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Pakiet podstawowej pielęgnacji Outrider",
  },
  [7867] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Standardowy pakiet opieki Outridera",
  },
  [7868] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Zaawansowany pakiet pielęgnacyjny Outrider\'ów",
  },
  [7871] = {
    ["D"] = "Za tym tunelem znajdziesz pole walki i zgiełku, młody $C. Horda cały czas niszczy nasz święty las, wycinając wiecznie zieloną roślinność, aby nakarmić swoje machiny wojenne.$B$BWejdź do Warsong Gulch i obroń Silverwing Hold. Odepchnij nacierające oddziały Hordy!$B$BUczyń to i zdobądź talizman zasługi. Przynieś mi go, a cię nagrodzę, $N.",
    ["O"] = "Wejdź do Warsong Gulch i pokonaj Hordę, zdobądź Warsong Gulch Mark of Honor i powróć do Sentinel Farsong z Silverwing Grove.",
    ["T"] = "Pokonaj najeźdźców!",
  },
  [7872] = {
    ["D"] = "Za tym tunelem znajdziesz pole walki i zgiełku, młody $C. Horda cały czas niszczy nasz święty las, wycinając wiecznie zieloną roślinność, aby nakarmić swoje machiny wojenne.$B$BWejdź do Warsong Gulch i obroń Silverwing Hold. Odepchnij nacierające oddziały Hordy!$B$BUczyń to i zdobądź talizman zasługi. Przynieś mi go, a cię nagrodzę, $N.",
    ["O"] = "Wejdź do Warsong Gulch i pokonaj Hordę, zdobądź Warsong Gulch Mark of Honor i powróć do Sentinel Farsong z Silverwing Grove.",
    ["T"] = "Pokonaj najeźdźców!",
  },
  [7873] = {
    ["D"] = "Za tym tunelem znajdziesz pole walki i zgiełku, młody $C. Horda cały czas niszczy nasz święty las, wycinając wiecznie zieloną roślinność, aby nakarmić swoje machiny wojenne.$B$BWejdź do Warsong Gulch i obroń Silverwing Hold. Odepchnij nacierające oddziały Hordy!$B$BUczyń to i zdobądź talizman zasługi. Przynieś mi go, a cię nagrodzę, $N.",
    ["O"] = "Wejdź do Warsong Gulch i pokonaj Hordę, zdobądź Warsong Gulch Mark of Honor i powróć do Sentinel Farsong z Silverwing Grove.",
    ["T"] = "Pokonaj najeźdźców!",
  },
  [7874] = {
    ["D"] = "Dzikie lasy Ashenvale ulegną potędze Hordy, $R7. Nic, co mówią lub czynią Silverwing nie może powstrzymać naszych planów. Kalimdor należy do Hordy. Jak oni śmieją próbować nas powstrzymać przed zabraniem tego, co jest nasze!$B$BNiech duma rozpiera twoje serce, gdy będziesz skracać ich mierne próby spowolnienia nas. Zniszcz Silverwing Sentinels i zdobądź Warsong Mark of Honor. Wróć z nią do mnie, $N, a zostaniesz wynagrodzony.",
    ["O"] = "Weź udział w bitwie Warsong Gulch i pokonaj Przymierze, zdobądź Warsong Gulch Mark of Honor i przynieś ją do Captaina Shatterskulla w Mor\'shan Base Camp.",
    ["T"] = "Stłamszenie uzurpatorów Silverwing",
  },
  [7875] = {
    ["D"] = "Ostępy lasu Ashenvale nie oprą się potędze Hordy, $R7. Nic, co Silverwing rzekną czy zrobią, nie będzie w stanie powstrzymać naszej głównej idei. Kalimdor należy do Hordy. Jak oni śmią próbować zabronić nam zebranie tego, co jest pełnoprawnie nasze!$B$BNiech duma wzbiera w waszych piersiach, kiedy zetniecie ich mizerne próby spowolnienia naszego postępu. Zniszczcie Silverwing Sentinels i zdobądźcie znaki honoru Warsong. Wróć z nimi do mnie, $N, a będziesz nagrodzony.",
    ["O"] = "Wejdź do Warsong Gulch i pokonaj Przymierze, następnie zdobądź Warsong Gulch Mark of Honor i dostarcz je do Captain Shatterskull w Mor\'shan Base Camp.",
    ["T"] = "Stłum samozwańczych Silverwing",
  },
  [7876] = {
    ["D"] = "Puszcze lasu Ashenvale poddadzą się potędze Hordy, $R7. Nic co Srebrnoskrzydli zrobią albo powiedzą, nie jest w stanie zatrzymać naszej suwerennej imperatywy. Kalimdor należy do Hordy. Jak śmieją próbować zatrzymać nas od zabierania tego jest słusznie nasze!$B$BNiech duma puchnie w twej klatce piersiowej, jak będziesz niszczył ich żałosne próby w spowalnianiu nas. Pokonaj Srebrnoskrzydłych Strażników i zdobądź znak honoru Warsong. Przynieś mi taki znak, $N, a zostaniesz nagrodzony.",
    ["O"] = "Dołącz do Warsong Gulch i pokonaj Przymierze, zdobądź Warsong Gulch Mark of Honor i przynieś go Captain Shatterskull w Mor\'shan Base Camp.",
    ["T"] = "Stłum Srebrnoskrzydłych Uzurpatorów",
  },
  [7877] = {
    ["D"] = "W bibliotece Athenaeum, znajduje się stara klatka piersiowa ukryta pod schodami. Weź z niej to, czego tylko pragniesz.",
    ["O"] = "Wróć do Athenaeum i znajdź skarb Shen\'dralara. Zażądaj nagrody!",
    ["T"] = "Skarb Szen\'dradu",
  },
