  [7905] = {
    ["D"] = "Nadchodzi Festyn Darkmoon! Doświadcz naszych ekscytujących gier, wygrywaj wspaniałe nagrody kiedy festyn dotrze do miasta!$B$BJeżeli zamierzasz działać, to możesz wymienić ten voucher na pięć darmowych kuponów na nagrody! Po prostu oddaj ten voucher Gelvasowi Grimegate znajdującemu się na festynie Darkmoon.$B$BAktualnie, wejście do festynu znajduje się w Goldshire, w Elwynn Forest. Nie przegap go! Ruszaj czym prędzej!",
    ["O"] = "Dostarcz Free Ticket Voucher do Gelvasa Grimegate, znajdującego się wewnątrz Darkmoon Faire.",
    ["T"] = "Festyn Darkmoon",
  },
  [7907] = {
    ["D"] = "Teraz kiedy $gzebrałeś:zebrałaś; wszystkie karty Bestii razem do talii, dziewiąta karta pojawia się w tajemniczy sposób z takim samym oznaczeniem co pozostałe osiem. Na karcie znajduje się napis, \"Zwróć te karty na Festyn Lunomroku, a zostaniesz $gwynagrodzony:wynagrodzona;.\" $gSłyszałeś:Słyszałaś;, że wejście na festyn pojawia się blisko Mulgore i Goldshire każdego miesiąca.",
    ["O"] = "Zwróć Beast Deck do Darkmoon Faire, kiedy się pojawi w mieście.",
    ["T"] = "Talia Bestii Darkmoon",
  },
  [7908] = {
    ["D"] = "	Musisz być czymś więcej niż bycie mistrzem areny! Może Pirat, który prowadzi imprezę w Gurubashi, będzie wiedział!",
    ["O"] = "Porozmawiaj z Short John Mithril w Stranglethorn Arena.",
    ["T"] = "Mistrz Areny",
  },
  [7921] = {
	["D"] = "Dowiodłeś swej wartości w naszych zmaganiach w Warsong Gulch. Nie ustawaj we wspieraniu sprawy i przynoś mi kolejne talizmany zasługi. Czyń tak dalej, a zyskasz jeszcze większe zaufanie z naszej strony.",
	["O"] = "Za swe ostatnie zadanie otrzymałeś Srebrnoskrzydły Talizman Zasługi. Pomów ze mną raz jeszcze, a odbierzesz swą nagrodę.",
	["T"] = "Talizmany Zasługi",
  },
  [7922] = {
	["D"] = "Dowiodłeś swej wartości w naszych zmaganiach w Warsong Gulch. Nie ustawaj w swej furii przeciw Strażniczkom Silverwing! Przynoś mi kolejne Znaki Honoru!",
	["O"] = "Za swe ostatnie zadanie otrzymałeś Znak Honoru Warsong. Pomów ze mną raz jeszcze, a odbierzesz swą nagrodę.",
	["T"] = "Znak Honoru",
