  [7926] = {
    ["D"] = "Festyn Darkmoon nadciąga! Upewnij się, że doświadczysz wszystkich wspaniałości, gdy festyn zawita do miasta!$B$BJeśli będziesz działać już teraz, możesz wymienić ten voucher na darmowe kupony na nagrody! Po prostu przekaż swój kupon do Gelvasa będącego wewnątrz jarmarku.$B$BAktualnie wejście do festynu jest na zewnątrz Thunder Bluff w Mulgore! Nie przegap go! Ruszaj!",
    ["O"] = "Dostarcz Free Ticket Voucher do Gelvasa Grimegate, będącego wewnątrz Darkmoon Faire.",
    ["T"] = "Festyn Darkmoon",
  },
  [7927] = {
    ["D"] = "Teraz, kiedy $gzebrałeś:zebrałaś; wszystkie karty Portalu razem do talii, dziewiąta karta pojawia się w tajemniczy sposób z takim samym oznaczeniem co pozostałe osiem. Na karcie znajduje się napis, \"Zwróć te karty na festiwal Darkmoon, a zostaniesz $gwynagrodzony:wynagrodzona;.\" $gSłyszałeś:Słyszałaś;, że wejście na festyn pojawia się blisko Mulgore i Goldshire każdego miesiąca.",
    ["O"] = "Zwróć Portals Deck na Darkmoon Faire, kiedy się pojawi w mieście.",
    ["T"] = "Talia Portalu Darkmoon",
  },
  [7928] = {
    ["D"] = "Teraz, kiedy $gzebrałeś:zebrałaś; wszystkie karty Dowódców razem do talii, dziewiąta karta pojawia się w tajemniczy sposób z takim samym oznaczeniem co pozostałe osiem. Na karcie znajduje się napis, \"Zwróć te karty na festiwal Darkmoon, a zostaniesz $gwynagrodzony:wynagrodzona;.\" Słyszałeś, że wejście na festyn pojawia się blisko Mulgore i Goldshire każdego miesiąca.",
    ["O"] = "Zwróć Warlords Deck na Darkmoon Faire, kiedy się pojawi w mieście.",
    ["T"] = "Talia Dowódców Darkmoon",
  },
  [7929] = {
    ["D"] = "Teraz, kiedy $gzebrałeś:zebrałaś; wszystkie karty Żywiołów razem do talii, dziewiąta karta pojawia się w tajemniczy sposób z takim samym oznaczeniem co pozostałe osiem. Na karcie znajduje się napis, \"Zwróć te karty na festiwal Darkmoon, a zostaniesz $gwynagrodzony:wynagrodzona;.\" $gSłyszałeś:Słyszałaś;, że wejście na festyn pojawia się blisko Mulgore i Goldshire każdego miesiąca.",
    ["O"] = "Zwróć Elementals Deck na Darkmoon Faire, kiedy się pojawi w mieście.",
