  [7937] = {
    ["D"] = "\"Twoje przeznaczenie czeka na ciebie w Eastvale.\"$B$BWróżbita Sayge łapiąc cię, przekazuje pewne ciepło. Chwytając go mocno, widzisz obraz obozu wycinki Eastvale w lesie Elwynn. Skupiając się bardziej na obrazie, widzisz stóg siana znajdujący się obok stajni.",
    ["O"] = "Udaj się do Eastvale Logging Camp w Elwynn Forest i poszukaj swojego przeznaczenia.",
    ["T"] = "Twoje przeznaczenie czeka...",
  },
  [7938] = {
    ["D"] = "\"Twoja fortuna oczekuje ciebie wewnątrz Deadmines.\"$B$BFortuna Sayge wręczona tobie jest wyraźnie ciepła w dotyku. Trzymając mocno, widzisz obrazek, na którym widnieje Deadmines wewnątrz zrujnowanej wioski Moonbrook w Westfall. Skupiając się na obrazku, kręcisz się po krętych przejściach, aż dotrzesz do lśniącego portalu... prowadzi on do wnętrza serca kopalni. Przechodząc przez niego, dziwna skrzynia pojawia się znikąd.",
    ["O"] = "Podróżuj do Deadmines w Westfall i odszukaj swoją fortunę.",
    ["T"] = "Fortuna czeka na ciebie...",
  },
  [7939] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Więcej zwartych kamieni szlifierskich",
  },
  [7940] = {
