  [8053] = {
    ["D"] = "Jesteś poganinem. Poganie pełnią ważną funkcję w plemieniu. Poganie są wolnomyślicielami Zandalar. Wolnomyśliciele nie pozwalają, by zawładnął nimi strach. Wolnomyśliciele umierają w imię tego, w co wierzą. Wiemy, że ty jesteś gotów umrzeć w imię tego, w co wierzysz. W ten sposób zdobywa się nasze uznanie. W ten sposób możesz udowodnić swoją wartość.$B$BMusimy mieć Symbole Mocy. Idź do Zul\'Gurub. Zabij sługusów Hakkara. Wróć, gdy zdobędziesz to, czego szukam. Zdobądź pierwszy ekwipunek bojowy wolnomyśliciela Zandalar.$B$BIdź.",
    ["O"] = "Przynieś Jin\'rokhowi the Breaker Primal Hakkari Bindings. Twoja reputacja u plemienia Zandalar musi być równa lub większa Friendly.$B$BJin\'rokha the Breaker znajdziesz na Yojamba Isle, w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: karwasze wolnomyślicieli",
  },
  [8054] = {
    ["D"] = "Twe poglądy są nam obce, poganinie. Starożytni Zandalar byli niegdyś naznaczeni jako heretycy. Miało to miejsce, gdy Imperium Gurubashi było w pełni sił. Poganie mieli czelność kwestionować kapłana Hakkari. Zostali za to upolowani i zabici jak szkodniki. Ci poganie, jednakże, nigdy nie zawahali się podczas ich walki z Blood Godem. Oddajemy im honor za ich poświęcenie. Są oni wolnomyślicielami.$B$BZniszcz sługusów Hakkar w Zul\'Gurub. Przynieś mi Symbole Mocy, których poszukuję. Twój sukces zostanie hojnie nagrodzony.$B$BDo roboty.",
    ["O"] = "Dostarcz Jin\'rokh the Breaker Primal Hakkari Shawl. Musisz mieć także poziom reputacji równy lub większy niż Honored w Zandalari Tribe.$B$BJin\'rokh the Breaker znajduje się na Yojamba Isle, Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: pas wolnomyśliciela",
  },
  [8055] = {
    ["D"] = "Ekwipunek bitewny daje ci siłę w oczach plemienia. Wolnomyśliciele są honorowani w ten sposób. Oni są fanatykami. Ich napierśniki zaklinane są przez nich potężnymi inkantacjami. Jeżeli ich fanatyzm zachwiałby się w starciu z przeciwnikiem, ich napierśniki nie ulegną.$B$BPowiadam ci, musisz być czczony w naszych kręgach aby posiadać takowy pancerz. Idź do Zul\'Gurub. Zabierz Symbole Mocy, których potrzebuję. Zabierz Symbole ze szczególną bezwzględnością od tych głupców tam przebywających. Przynieś je do mnie. Udowodnij, iż jesteś Wolnomyślicielem raz i na zawsze.",
    ["O"] = "Przynieś Jin\'rokh the Breaker a Primal Hakkari Tabard. Musisz również posiadać reputację równą bądź większą od poziomu Revered u Zandalar Tribe.$B$BJin\'rokh the Breaker znajduje się na Yojamba Isle, Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: zbroja wolnomyśliciela",
  },
  [8056] = {
    ["D"] = "Wróżbici z naszego plemienia są cenieni za swój boski dar przewidywania przyszłości. To nie żadni czarownicy; spędzają czas na rzucaniu kośćmi albo na czytaniu liści, by coś zrozumieć - nie zajmują się rzucaniem uroków na ludzi. Jako szaman wiesz już co nieco na temat mocy przepowiedni; tutaj, w Zandalar, cenimy ich przenikliwość.$B$BPrzynieś mi ofiarę z Symboli Mocy z wnętrza Zul\'Gurub i udowodnij nam swoją wartość. Zrób to, a dam ci karawasze, które są cenione przez naszych wróżbitów bardziej, niż wszystko inne.",
    ["O"] = "Przynieś Maywiki Primal Hakkari Armsplint. Musisz mieć również reputację równą lub większą niż Friendly z plemieniem Zandalar. Maywiki z Zuldazar znajduje się na Yojamba Isle, w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: karwasze wróżbity",
  },
  [8057] = {
    ["D"] = "Haruspik to kluczowy członek naszego plemienia; dowiedziesz, żeś mądry, jeśli go wysłuchasz. Dzięki więzi ze zwierzętami i składaniu z nich ofiar duchom, gdy taka zachodzi potrzeba, zsyła nam boskie przewodnictwo. W minionych czasach, przenikliwość i mądrość haruspików dała nam przewagę nad podzielonymi plemionami Gurubashi.$B$BPrzynieś mi Symbole Mocy z wnętrza Zul\'Gurub i udowodnij nam, ile jesteś wart. Zrób to, a obdarzę cię ochraniaczami, jakich zapragnąłby każdy haruspik z Zandalaru.",
    ["O"] = "Przynieś Maywiki z Zuldazaru Primal Hakkari Stanchion. Ponadto, musisz posiadać wśród plemienia Zandalar reputację większą lub równą Przyjaznej.$B$BMaywiki z Zuldazaru znajdziesz na Yojamba Isle, w Stranglethorn Vale.",
    ["T"] = "Symbole mocy: naramienniki haruspika",
  },
  [8058] = {
    ["D"] = "Zemsta jest siłą. Winowajca Zandalar jest potężny. Plemię ma wielu wrogów. Winowajca wymusza na nich karę. Żadna zbrodnia przeciwko nam nie zostanie zlekceważona. Winowajca zostanie ukarany. Nasi wrogowie boją się naszej zemsty. Tak jak powinni. Na zawsze będą$B$BZostań naszym obrońcą. Poszukaj Symboli Mocy w środku Zul\'Gurub. Zgładź sługów Hakkar i dokonaj zemsty w imieniu plemienia. Zostaniesz nagrodzony.",
    ["O"] = "Przynieś Jin\'rokh the Breaker Primal Hakkari Armsplint. Twoja reputacja musi być równa, bądź większa niż przyjazna z plemieniem Zandalar.$B$BJin\'rokh the Breaker znajduje się na Yojamba Isle w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: naramiennik obrońcy",
  },
  [8059] = {
    ["D"] = "Czarnoksiężnicy podejmują ogromne ryzyko walcząc z demonami, ale walka z naszymi demoniakami to już niemal samobójstwo. Dzięki starożytnemu rytuałowi pozwalają demonowi na wejście do własnego ciała. Zamiast pozwolić im się opętać, przejmują kontrolę nad demonem od środka, przejmując jego moc i zmieniając go w swojego niewolnika. To sztuka, którą opanowało tylko kilku nielicznych czarnoksiężników.$B$BBy nauczyć się więcej o potędze demoniaków muszę zdobyć Symbole Mocy z Zul\'Gurub. Idź tam i przynieś to czego szukamy.",
    ["O"] = "Przynieś Al\'tabimowi Wszechwiedzącemu Primal Hakkari Stanchion. Ponadto musisz posiadać reputację Friendly z Zandalar Tribe.$B$BAl\'tabim Wszechwiedzący zasiada na Yojamba Isle, Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: ochraniacze demoniaka",
  },
  [8060] = {
    ["D"] = "Magów w naszym plemieniu nazywa się Iluzjonistami. Swoje inkantacje często wspomagają potężnym mojo, sprowadzając tym na wrogów plemienia ciemnotę i istne pomieszanie zmysłów!$B$B<Al\'tabim śmieje się szelmowsko.>$B$BAch,cóż to za widok, obserwowanie, jak potężny Iluzjonista sprawia, że nasi wrogowie w szaleństwie padają przed nami na kolana!$B$BŻebyś sam mógł poznać ścieżki naszych Iluzjonistów, idź do Zul\'Gurub i przynieś mi stamtąd Symbole Mocy, o których ci wspomniałem. W zamian otrzymasz ode mnie okrycia naramienne, których nasi Iluzjoniści używają do tkania swoich zaklęć.",
    ["O"] = "Przynieś Al\'tabimowi Wszechwidzącemu Prastare Wiązania Hakkari. Ponadto, twoja reputacja z plemieniem Zandalari musi być wyższa niż lub co najmniej Przyjazna.$B$BAl\'tabim Wszechwidzący znajduje się na wyspie Yojamba w Dolinie Dławiących Cierni.",
    ["T"] = "Symbole Mocy: ochraniacze iluzjonisty",
  },
  [8061] = {
    ["D"] = "My Zandalarianie przekazujemy naszą moc tym, którzy przemawiają z woli bożej. Nasi kapłani to coś więcej, niż tylko uzdrowiciele - to także nasi spowiednicy. Zło nadciąga nie tylko z zewnątrz - tak jak Hakkar - ale też z samego plemienia. Nasi spowiednicy działają jako sędziowie pośród nas, zapobiegając złu, które pochłonęło Gurubashiego od środka.$B$BUdaj się do Zul\'Gurub i przynieś Symbole Mocy od Gurubashiego. Przekonaj się, co to znaczy być spowiednikiem, i uchroń nas od złego.",
    ["O"] = "Przynieś Al\'tabimowi the All-Seeing Primal Hakkari Stanchion. Musisz też mieć reputację równą lub wyższą niż Friendly z Plemieniem Zandalar.$B$BAl\'tabim the All-Seeing znajduje się na Yojamba Isle w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: ochraniacze spowiedniczki",
  },
  [8062] = {
    ["D"] = "W mrocznych czasach po upadku Imperium Gurubashi, biegłość drapieżców Zandalaru zapewniała szczepowi utrzymanie. Łowcy twierdzą, że ich przypominają – to prawda, że poszukiwanie zwierzyny oznacza utożsamienie się z drapieżcą. Jednakże to polowanie w Zul\'Gurub wskaże ci twoje właściwe miejsce na liście naszych najwspanialszych drapieżców.$B$BPrzynieś mi okazy Symboli Mocy z Zul\'Gurub. Uczyń to, a postawisz pierwszy krok na drodze do zostania drugim drapieżcą od końca.",
    ["O"] = "Przynieś Falthir the Sightless następujące Paragons of Power z Zul\'Gurub - Primal Hakkari Bindings. Musisz się także cieszyć reputacją co najmniej Friendly u Zandalar Tribe.$B$BFalthir the Sightless przebywa na Yojamba Isle w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: karwasze drapieżcy",
  },
  [8063] = {
    ["D"] = "Szaleńcy z Zandalaru są podobni do łotrów, ale ponad wszystko są zwolennikami szaleństwa... chaosu... nieprzewidywalności istnienia. Są prawdziwym postrachem na polu bitwy; w mrocznych czasach po rozejściu się szczepów siali zamęt i chaos pośród naszych wrogów. Bez nich dziś by nas tu nie było.$B$BPrzynieś mi okazy Symboli Mocy z Zul\'Gurub, których poszukuję, a wręczę ci pierwszą z cenionych części zbroi szaleńców. Pogrąż się w szaleństwie!",
    ["O"] = "Przynieś Falthirowi the Sightless Primal Hakkari Armsplint. Musisz się także cieszyć reputacją co najmniej Friendly u Zandalar Tribe.$B$BFalthir the Sightless przebywa na Yojamba Isle w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: karwasze szaleńca",
  },
  [8064] = {
    ["D"] = "W Zandalarze nie chodzimy ścieżkami druidów; natura ma być kształtowana tak, jak tego chcemy, a nie na odwrót. Mimo to, haruspik żyje najbardziej w zgodzie z naturą, i słusznie. To, że poświęca ducha bestii oznacza dla niego zdobycie wiedzy na temat tego, jak to jest być jednym z tych stworzeń. To jest prawdziwa moc natury.$B$BPrzynieś mi z wnętrza Zul\'Gurub Symbole Mocy, udowadniając nam swoją lojalność. Zrób to, a dam ci potężny przedmiot - pas używany przez wielu haruspików z Zandalaru.$B$BPowodzenia!",
    ["O"] = "Przynieś Maywiki z Zuldazar Primal Hakkari Sash. Maywiki z Zuldazar znajduje się na Yojamba Isle, Stranglethorn Vale. Musisz się cieszyć co najmniej reputacją Honored u Zandalar.",
    ["T"] = "Symbole Mocy: pas haruspika",
  },
  [8065] = {
    ["D"] = "Najważniejszym symbolem mocy haruspika jest jego strój, $N. Tunika symbolizuje więź między nimi a boską mądrością, której haruspikowie poszukują. Często zawiera w sobie części stworzeń, które poświęcają; to przypomina im o więzi, która łączy ich z ich darami.$B$BPrzynieś mi Symbole Mocy z wnętrza Zul\'Gurub i dowiedź nam swej wartości. Zrób to, a tunika emanująca prawdziwą mocą haruspika będzie twoja.",
    ["O"] = "Przynieś Maywiki z Zuldazar Primal Hakkari Tabard. Maywiki z Zuldazar znajduje się na Yojamba Isle, w Stranglethorn Vale. Musisz też mieć status Revered z Zandalar.",
    ["T"] = "Symbole Mocy: tunika haruspika",
  },
  [8066] = {
    ["D"] = "Każdy drapieżca wie, jak śledzić swoją ofiarę, ale tylko umiejętny wie, jak uderzyć, kiedy znajdzie się wystarczająco blisko. Musisz opanować tę sztukę, aby mieć szansę na sukces w Zul\'Gurub... i szansę na dorównanie zandalarskim drapieżcom.$B$BPrzynieś mi wybrane okazy Symboli Mocy z Zul\'Gurub. Moją nagrodą będzie moc, którą dysponują te błyskotki, a twoją pas zandalarskiego drapieżcy – przedmiot wart swojej ceny.",
    ["O"] = "Przynieś Falthirowi the Sightless następujące Paragons of Power z Zul\'Gurub - Primal Hakkari Shawl. Musisz się także cieszyć reputacją co najmniej Honored u Zandalar Tribe.$B$BFalthir the Sightless przebywa na Yojamba Isle w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: pas drapieżcy",
  },
  [8067] = {
    ["D"] = "My, Zandalarczycy, cenimy nasz ubiór jako symbol naszych dokonań. Nie musisz widzieć, co ktoś ma na sobie, aby poczuć emanującą z tego moc – wykracza ona ponad zmysł wzroku. Takie właśnie są stroje zandalarskich drapieżców, a ich najbardziej cenionym elementem są noszone przez nich płaszcze. Taki płaszcz pozwala ukryć się przed zasięgiem wzroku... i ujawnić się wtedy, kiedy właściciel sobie tego zażyczy.$B$BSymbole Mocy czekają na ciebie w Zul\'Gurub. Przynieś mi te, których potrzebuję, a płaszcz drapieżcy będzie twój.",
    ["O"] = "Przynieś Falthirowi the Sightless następujące Paragons of Power z Zul\'Gurub - Primal Hakkari Aegis. Musisz się także cieszyć reputacją co najmniej Revered u Zandalar Tribe.$B$BFalthir the Sightless przebywa na Yojamba Isle w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: płaszcz drapieżcy",
  },
  [8068] = {
    ["D"] = "Magia to surowa, pierwotna moc, którą kształtują ci, którzy są wystarczająco silni, by to zrobić. Zaklęcia są przedłużeniem tej mocy, a jedną z potężnych manipulacji jest iluzja. Jak ktoś może mieć nadzieję że wygra z przeciwnikiem, którego nawet tu nie ma? My Zandalari, znamy moc tej umiejętności i dlatego iluzjoniści zajmują honorowe miejsce w naszym plemieniu.$B$BPrzynieś potrzebne Symbole Mocy z Zul\'Gurub - a poważanie naszego plemienia i potężny płaszcz, używany przez naszych najpotężniejszych iluzjonistów, będzie twój!",
    ["O"] = "Przynieś Al\'tabimowi Primal Hakkari Shawl. Musisz też mieć reputację równą lub wyższą niż Honored z Plemieniem Zandalar.$B$BAl\'tabim znajduje się na Yojamba Isle, w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: płaszcz iluzjonisty",
  },
  [8069] = {
    ["D"] = "Plemię rozpoznaje status i moc danego członka dzięki temu, co człek ów nosi. Nasze stroje zrobione są z najznamienitszych materiałów, a także połączone z zaklęciami, których używamy, po to, byśmy stali się potężniejsi. Iluzjoniści nie stanowią wyjątku; mówi się, że ich szaty zawierają esencję iluzji. Legendy głoszą, że ich pradawne szaty za każdym razem wyglądały inaczej.$B$BDam ci szaty iluzjonisty, $N... ale najpierw zasłuż na szacunek plemienia! Przynieś mi Symbole Mocy z Zul\'Gurub!",
    ["O"] = "Przynieś Al\'tabimowi Primal Hakkari Kossack. Musisz też mieć reputację równą lub wyższą niż Revered z Plemieniem Zandalar.$B$BAl\'tabim znajduje się na Yojamba Isle, w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: szaty iluzjonisty",
  },
  [8070] = {
    ["D"] = "Krótko po upadku Gurubashi, my Zandalarin niemal ostatecznie ulegliśmy przed złem wewnątrz naszego własnego plemienia. To właśnie wtedy spośród nas wyłonili się spowiednicy, którzy chronili plemię wyganiając tych, którzy zniszczyliby własny rodzaj. Nie tylko utrzymują nas w harmonii z naszym duchem, ale też chronią nasze ciało.$B$BRuszaj do Zul\'Gurub i osobiście doświadcz demoralizację Hakkara i Gurubashich. Odbierz im poszukiwane przez nas Symbole Mocy; sukces zostanie nagrodzony!",
    ["O"] = "Przynieś Al\'tabim the All-Seeing Primal Hakkari Sash. Musisz też mieć reputację równą lub wyższą niż Honored z Plemieniem Zandalar.$B$BAl\'tabim the All-Seeing znajduje się na Yojamba Isle, Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: wiązania spowiednika",
  },
  [8071] = {
    ["D"] = "Spowiednicy Zandalaru noszą charakterystyczny płaszcz pokazujący, że są duchowymi obrońcami plemienia. Te płaszcze tkaną są z potężnym mojo, które pomaga sądzić tych, którzy czynili krzywdy naszemu plemieniu. Jako kapłan, musisz spędzić wiele czasu na sądzeniu godności; taki płaszcz z pewnością byłby dla ciebie błogosławieństwem.$B$BW zamian za walkę ze sługami Hakkara w Zul\'Gurub i przyniesienie mi Symboli Mocy, dam ci płaszcz godny najlepszych spowiedników.",
    ["O"] = "Przynieś Al\'tabim the All-Seeing Primal Hakkari Aegis. Musisz mieć reputację równą lub wyższą niż Revered w Zandalar Tribe.$B$BAl\'tabim the All-Seeing jest na Yojamba Isle, w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: płaszcz spowiednika",
  },
  [8072] = {
    ["D"] = "Jednym z legendarnych szaleńców Zandalarczyków był Khar\'vaxal Stuknięty. Legenda głosi, że kiedy walczył z wrogami szczepu po raz pierwszy, użył swojego płaszcza utkanego specjalnie ze \"splotów szaleństwa\". Jego sylwetka rozmyła się nie tylko dzięki pelerynie, ale również dzięki oślepiającej szybkości jego bliźniaczych sztyletów. Dzisiejsi szaleńcy cenią sobie swoje płaszcze jako symbole ich pozycji w szczepie.$B$BPrzynieś mi Symbole Mocy, których szukam, a otrzymasz taki płaszcz, by oplatać szaleństwem umysły swoich wrogów.",
    ["O"] = "Przynieś Falthirowi the Sightless Primal Hakkari Girdle. Musisz się także cieszyć reputacją co najmniej Honored u Zandalar Tribe.$B$BFalthir the Sightless przebywa na Yojamba Isle w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: płaszcz szaleńca",
  },
  [8073] = {
    ["D"] = "Moje oczy zawiodły mnie dawno temu, ale nie tęsknię za nimi. Nawet w szczepie takim jak nasz – gdzie szaty wyrażają pozycję i intencje – najpotężniejszy strój emanuje mocą, której zwykłe oczy nie mogą dostrzec. Nie inaczej jest z cenioną tunika zandalarskich szaleńców, promieniującą surową mocą chaosu i szaleństwa, którą jej właściciele potrafią ukierunkować.$B$BPotrzebne mi Symbole Mocy spoczywają w Zul\'Gurub; przynieś mi, czego szukam, a w nagrodę otrzymasz na własność legendarną tunikę... odpowiednią dla kogoś splatającego szaleństwo.",
    ["O"] = "Przynieś Falthirowi the Sightless Primal Hakkari Aegis. Musisz się także cieszyć reputacją co najmniej Revered u Zandalar Tribe.$B$BFalthir the Sightless przebywa na Yojamba Isle w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: tunika szaleńca",
  },
  [8074] = {
    ["D"] = "Wróżbici znają magię żywiołów. Używają jej, aby prowadzić plemię do chwały. Podczas mrocznych dni, po tym jak Imperium Gurubashi rozpadło się, nasi wróżbici prowadzili nas do naszego schronienia w South Seas. Przyprowadzili nas z powrotem do Doliny, prosto do serca zła siedzącego w Zul\'Gurub.$B$BPrzynieś mi symbole mocy z Zul\'Gurub i udowodnij nam swoją wartość. Zrób to, a ja dam ci pasek, którego używają nasi wróżbici - z potężnym zaklęciem w środku!",
    ["O"] = "Przynieś Maywiki z Zuldazar Primal Hakkari Girdle. Musisz także mieć reputację równą, lub wyższą niż Uhonorowany (Honored) z plemieniem Zandalari.$B$BMaywiki z Zuldazar znajduje się na Yojamba Isle w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: pasek wróżbity",
  },
  [8075] = {
    ["D"] = "Wróble z Zandalaru noszą charakterystyczną kolczugę. Jest bogato zdobiona we wspaniałe jedwabne tkaniny przeplatane niezwykle mocnym łańcuchem. To symbol nie tylko ich boskości, ale także ich autorytetu, koleś. Nigdy nie należy wchodzić w drogę osobie, której przeznaczeniem jest słuchać głosu duchów. Przynieś mi ofiarę z Symboli Mocy z wnętrza Zul\'Gurub i udowodnij swoją wartość. Zrób to, a dam ci jedną z naszych najwspanialszych kolczug, jakie nasi Wróble mieli okazje nosić.",
    ["O"] = "Przynieś Maywiki z Zuldazaru Primal Hakkari Tabard. Musisz mieć reputację równą lub wyższą od Revered w frakcji Zandalar Tribe. Maywiki z Zuldazaru przebywa na Yojamba Isle w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: kolczuga wróżbity",
  },
  [8076] = {
    ["D"] = "Demoniaki nie chcą po prostu posiąść mocy, pragną ją wręcz uosabiać. Niejeden nasz demoniak przegrał walkę z demonem; ale od kiedy zagrażają nam wrogowie - zwłaszcza w Zul\'Gurub - moc, którą demoniak może uderzyć w naszych wrogów, jest warta poświęcenia. Nasze przetrwanie zależy od zmiażdżenia tych, którzy pragną nas unicestwić; nauczył nas tego upadek Imperium Gurubashi.$B$BUdaj się do Zul\'Gurub i posiądź Symbole Mocy, których potrzebujemy. Uczyń to, a cenny przedmiot demoniaka będzie twój.",
    ["O"] = "Przynieść Al\'tabimowi Primal Hakkari Sash. Musisz się także cieszyć reputacją co najmniej Honored u Zandalar Tribe.$B$BAl\'tabim znajduje się na Yojamba Isle, w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: płaszcz demoniaka",
  },
  [8077] = {
    ["D"] = "Ostatecznym symbolem mocy pośród plemienia jest ubiór, jaki przywdziewamy do walki. Szaty Opętańca połączyły runiczne sukno oraz niesamowicie potężne mojo w jeden materiał. Mówi się, że sam widok szaty napawa strachem umysły tych, którzy je zobaczą... zwłaszcza demony, które opętańcy w końcu zdominują.$B$BZ Zul\'Gurub musisz mi przynieść bardzo specyficzny zestaw Symboli Mocy. Będzie to trudne... ale twój sukces zapewni wejście w posiadanie własnych szat.",
    ["O"] = "Przynieś Al\'tabimowi the All-Seeing Primal Hakkari Kossack. Musisz też mieć reputację równą lub wyższą niż Revered z Plemieniem Zandalari.$B$BAl\'tabim the All-Seeing znajduje się na Yojamba Isle, w Stranglethorn Vale.",
    ["T"] = "Symbole mocy: Szaty Opętańca",
  },
  [8078] = {
    ["D"] = "Ostateczna zemsta czeka w Zul\'Gurub. Hakkar nie może znów powstać. Od wewnątrz zniszczył Imperium Gurubashi. Nie pomogła żadna ofiara. Trolle są cieniem dawnej chwały. Wiem, że to wszystko przez Hakkara.$B$BZostań obrońcą, którym $gmiałeś:miałaś; zostać. Siej spustoszenie wśród sług zła. Zul\'Gurub musi posmakować zemsty Zandalari. Jako dowód przynieś mi Symbole Mocy. Otrzymasz w zamian pas obrońcy. Zyskasz prawdziwą moc.$B$BIdź.",
    ["O"] = "Dostarcz Jin\'rokhowi Primal Hakkari Girdle. Musisz posiadać również reputację równą, bądź większą niż Honorowy z plemieniem Zandalar.$B$BJin\'rokh the Breaker znajduje się na Yojamba Isle, w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: pas obrońcy",
  },
  [8079] = {
    ["D"] = "Symbolem mocy obrońcy jest napierśnik. Jest wykuty przy użyciu potężnej magii. Można go powierzyć tylko tym, których otaczamy czcią. Jest to zandalariański symbol zemsty.$B$BBycie obrońcą to bycie zemstą. Zabierz potrzebne nam Symbole Mocy z Zul\'Gurub. Przynieś je do nas. Zabierzemy, to, co nam skradziono. Sprawimy, że sługusy Hakkara zapłacą. Nagrodzimy cię napierśnikiem obrońcy.$B$BIdź. Bądź naszym mścicielem, $N.",
    ["O"] = "Przynieś Jin\'rokhowi Primal Hakkari Kossack. Musisz także mieć reputację równą lub większą niż Czczony w Zandalar Tribe.$B$BJin\'rokh znajduje się na Yojamba Isle, w Stranglethorn Vale.",
    ["T"] = "Symbole Mocy: napierśnik obrońcy",
  },
  [8080] = {
    ["D"] = "Wojnę prowadzi się za pomocą armii, każdy żołdak ci to powie. Powie ci również, że walka przy użyciu kiepskiego sprzętu albo o pustym brzuchu jest z góry skazana na porażkę!$B$BDlatego Arathi Basin jest taki ważny. Znajdują się tam kluczowe obszary z niezbędnymi zasobami. Metale, broń, żarcie, drewno - to wszystko jest potrzebne i można to tam zdobyć.$B$BWłaśnie tego od ciebie oczekuję, $N. Udaj się do Arathi Basin, wygraj bitwę, utrzymując więcej baz niż przeciwnik, i wróć do mnie ze skrzynią zasobów.",
    ["O"] = "Wygraj bitwę w Arathi Basin, zdobądź tamtejsze zasoby i przynieś je do sierżant Maclear w Refuge Pointe.",
    ["T"] = "Zasoby Arathi Basin!",
  },
  [8081] = {
	["D"] = "Wojny nie wygrywa się inaczej jak żołnierzami, każdy wojak ci to powie. Powiedzą też, że bitwa stoczona z lichym rynsztunkiem lub o pustym żołądku jest przegrana, nim się zacznie!$B$BDlatego właśnie Arathi Basin ma tak wielkie znaczenie. W kotlinie tej znajdują się kluczowe miejsca, w których zgromadzono niezbędne zasoby. Metale, broń, żywność, drewno - wszystko to jest potrzebne i wszystko to można tam zdobyć.$B$BTego właśnie od ciebie żądam, $N. Wejdź do Arathi Basin, zwycięż w bitwie, utrzymując więcej baz niż nieprzyjaciel, a potem wróć do mnie ze skrzynią zasobów.",
	["O"] = "Wygraj bitwę o Arathi Basin, zdobądź Skrzynię Zasobów Arathi i przynieś ją sierżantowi Maclearowi w Refuge Pointe.",
	["T"] = "Więcej zasobów",
  },
  [8101] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Otoczak Kajaro",
  },
  [8102] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Otoczak Kajaro",
