  [8399] = {
    ["D"] = "Srebrnoskrzydli Strażnicy biorą udział w bitwie z Eskortą Wojennej Pieśni z powodu zniszczeń, które orkowie powodują w lesie. Istnieje jednak więcej powodów, aby bronić tego konkretnego lasu niż tylko zwykła miłość do natury.$B$BLas stanowi strategiczną barierę, która sprawia, że Ashenvale da się obronić przed atakiem na dużą skalę. Bez niego Astranaar zostałby zajęty w dzień lub dwa.$B$BBędziesz uczestniczyć w walce z Eskortą Wojennej Pieśni, $N! Dla Sojuszu!",
    ["O"] = "Przynieś 3 Warsong Gulch Marks of Honor do Alliance Brigadier General poza polami bitwy.",
    ["T"] = "Walcz o Wąwóz Wojennej Pieśni",
  },
  [8400] = {
    ["D"] = "Srebrnoskrzydli Strażnicy są w stanie wojny z Eskortą Wojennej Pieśni z powodu zniszczeń, jakie orkowie sieją w lesie. Jest jednakże o wiele więcej powodów, żeby chronić ów las, niż tylko zwykła miłość do natury.$B$BLas stanowi strategiczną barierę, która sprawia, że Ashenvale jest w stanie bronić się przed atakiem na dużą skalę. Bez niej Astraanar przetrwałby dzień czy dwa, zanim zostałby wcielony do Barrens.$B$BDołącz do walki z Warsong Outriders, $N! Za Przymierze!",
    ["O"] = "Przynieś 3 Warsong Gulch Marks of Honor jednemu z Alliance Brigadier General na zewnątrz battlegroundów.",
    ["T"] = "Walka o Warsong Gulch",
  },
  [8401] = {
    ["D"] = "Srebrnoskrzydli Strażnicy biorą udział w bitwie z Eskortą Wojennej Pieśni z powodu zniszczeń, które orkowie powodują w lesie. Istnieje jednak więcej powodów, aby bronić tego konkretnego lasu niż tylko zwykła miłość do natury.$B$BLas stanowi strategiczną barierę, która sprawia, że Ashenvale da się obronić przed atakiem na dużą skalę. Bez niego Astranaar zostałby zajęty w dzień lub dwa.$B$BBędziesz uczestniczyć w walce z Eskortą Wojennej Pieśni, $N! Dla Sojuszu!",
    ["O"] = "Przynieś 3 Warsong Gulch Marks of Honor do Alliance Brigadier General poza polami bitwy.",
