  },
  [8408] = {
    ["D"] = "Srebrnoskrzydli Strażnicy prowadzą wojnę z Eskortą Wojennej Pieśni ze względu na zniszczenia, jakie orkowie powodują w lesie. Istnieje jednak więcej powodów, dla których należy bronić tego konkretnego lasu niż zwykła miłość do natury.$B$BLas stanowi strategiczną barierę, która sprawia, że Ashenvale może bronić się przed atakami na dużą skalę. Bez niego, Astranaar przetrwałby może dzień lub dwa, zanim zostałby przyłączony do Barrens.$B$BWeź udział w walce z Eskortą Wojennej Pieśni,$N! Za Przymierze!",
    ["O"] = "Przynieś 3 Warsong Gulch Marks of Honor do Generała Brygady Sojuszu poza battlegroundami.",
    ["T"] = "Walka o Warsong Gulch",
  },
  [8409] = {
    ["D"] = "Zgniłe jaja zostały pomyślnie umieszczone w beczce. Następne partie piwa z Southshore Inn z pewnością zostaną zrujnowane!$B$B$gPowinieneś:Powinnaś; teraz zgłosić się do Przyzywającej Ciemność Yanki na Festiwalu Chochoła w Tirisfal Glade i zaraportować swój sukces.",
    ["O"] = "Wróć do Przyzywającej Ciemność Yanki na Festiwalu Chochoła w Tirisfal Glade.",
    ["T"] = "Zniszczone beczki",
  },
  [8410] = {
    ["D"] = "Bath\'rah, Strażnik Wiatru wystosował wezwanie do szamanów dysponujących twoim poziomem wiedzy. Prosi, by $gprzyniósł:przyniosła; próbkę każdego z żywiołów na dowód twej gotowości.$B$BBy znaleźć Bath\'raha, udaj się nad rzekę płynącą na wschód od Tarren Mill. Podążaj jej korytem na północ, aż dojdziesz do ruin, gdzie mieszka Bath\'rah.",
    ["O"] = "Zdobądź próbkę powietrza, ognia, ziemi i wody dla Bath\'rah the Windwatcher.",
    ["T"] = "Panowanie nad żywiołami",
  },
  [8411] = {
    ["D"] = "Witoj, $C. Przyniesiosz mnie żywioły, a wtedy pogodomy.$B$BNim ci uwierzo, potrzebujo ognia, powiotrza, wody i ziemi, koleś. Muszem wiedzieć, żeś ty $gpojętny:pojętna;.",
    ["O"] = "Przynieś próbkę żywiołu ziemi, powietrza, ognia i wody do Bath\'rah the Windwatcher.",
    ["T"] = "Mistrzostwo w ujarzmieniu żywiołów",
  },
  [8412] = {
    ["D"] = "Duchy żywiołów tego miejsco już mnie nie lubio.$B$BWiesz o totemoch więcej niż ktokolwiek, o jo potrzebuję totemu ducha, by mni strzegł. Mom już żywioły, teroz potrzeba nom czegoś jeszcze, bordziej naturalnego. Bordziej pierwotnego.$B$BNa Zachodnich Ziemiach Plagi możesz zdobyć pazury niedźwiedzi, i oczy pająków. A sępy jedzą wszystko, więc możosz w nich znaleźć każdo z tych rzeczy.",
    ["O"] = "Przynieś elementy do totemu ducha Bath\'rahowi the Windwatcher.",
    ["T"] = "Totem ducha",
  },
  [8413] = {
    ["D"] = "Totem ducha nie wystorczy. Potrzebujemy trochę mogii voodoo, by wszystko zodziołoło.$B$BTrolle z zotopionej świotyni moją pióra z silną magio voodoo. Idź tom i zabij Gashera, Mijana, Zolo, Hukku, Zul\'lora i Loro. Wtedy będziemy mieć dość magii do stworzenia prowdziwego totemu ducha.",
    ["O"] = "Przynieś pióra voodoo Bath\'rahowi the Windwatcher.",
    ["T"] = "Voodoo",
  },
  [8414] = {
    ["D"] = "$gBądź pozdrowiony:Bądź pozdrowiona;, $C. W tej spustoszonej krainie podobni tobie krzyżowcy stanowią pożądany widok.$B$BTwoja święta moc jest nam potrzebna w walce z niezliczonymi hordami nieumarłych. Chcielibyśmy, abyś $gzebrał:zebrała; znaczną ilość kamieni plagi służalców i $gzaniósł:zaniosła; je Wielkiemu Kapłanowi Thel\'danisowi. Strzeże on Grobowca Uthera w Sorrow Hill. To niedaleko stąd.$B$BTylko osoba posiadająca zlecenie Srebrzystego Świtu ma szansę na znalezienie Kamieni Plagi, więc jeśli nie $grozmawiałeś:rozmawiałaś; dotąd z oficerem Pureheart, czas najwyższy byś to $guczynił:uczyniła;.",
    ["O"] = "Zbierz 20 Minion\'s Scourgestones i zanieś je do Wielkiego Kapłana Thel\'danisa, przebywającego w Western Plaguelands.",
    ["T"] = "Rozpraszanie zła",
  },
  [8415] = {
    ["D"] = "Dowódca Ashlam Valorfist potrzebuje paladyna, którego cnota i męstwo równe są twoim, $N. Znajdziesz go w Obozie Mroźnego Wichru w południowej części Zachodnich Ziem Plagi. Odnajdź go i w imię Światłości wspomóż go w jego sprawie!",
    ["O"] = "Porozmawiaj z dowódcą Ashlamem Valorfistem w Chillwind Camp.",
    ["T"] = "Obóz Mroźnego Wichru",
  },
  [8416] = {
    ["D"] = "Te kamienie zostały oczyszczone ze zła, $N.$B$BZnam plany dowódcy Ashlama i wiem, że potrzebuje tylko jednego oczyszczonego kamienia. Zanieś mu go, aby za naszym pośrednictwem ogień sprawiedliwości pochłonął Plagę.",
    ["O"] = "Zanieś Inert Scourgestone do dowódcy Ashlana Valorfista z Chillwind Point.",
    ["T"] = "Oczyszczone Kamienie Plagi",
  },
  [8417] = {
    ["D"] = "W Blasted Lands. spotkasz niespokojnego ducha, będącego niegdyś wielkim bohaterem Hordy. Honor wojownika nie umiera razem z ciałem. Rozmowa z tym duchem wyjdzie ci na dobre.",
    ["O"] = "Porozmawiaj z Fallen Hero of the Horde u wejścia do Blasted Lands.",
    ["T"] = "Niespokojny duch",
  },
  [8418] = {
    ["D"] = "Teraz musimy połączyć oczyszczone kamienie plagi i stworzyć broń, która rozniesie w pył szeregi nieumarłych. Nie jest to proste zadanie, $N. Tylko trolle z Zatopionej Świątyni znają taki rzadki rodzaj magii, który sprawia, że zawarte w czymś zło zwraca się przeciwko sobie.$B$BTrolle ze świątyni znane są jako Gasher, Mijan, Zolo, Hukku, Zul\'lor i Loro. Nie miej wyrzutów sumienia z powodu ich zatrutych dusz... nie są wolne od zła.",
    ["O"] = "Zdobądź Amber, Blue, i Green Voodoo Feathers od trolli z Sunken Temple.",
    ["T"] = "Wykucie Kamienia Mocy",
  },
  [8419] = {
    ["D"] = "$N, imp z Felwood zwany Impsy prosi cię o przybycie. Co dziwne, chce także, abyś wziął ze sobą kawałek felowego materiału na znak dobrej woli. Biorąc pod uwagę moc, jaką zdobyłeś jako czarnoksiężnik, przypuszczam, że wiesz, iż taki materiał noszą jedynie satyry z Felwood.$B$BImpsy\'ego znajdziesz na północ od Bloodvenom Falls, które, jak słyszałem, są niezwykle piękne o tej porze roku.",
    ["O"] = "Przynieś Impsy\'emu z Felwood kawałek felowego materiału.",
    ["T"] = "Prośba impa",
  },
  [8420] = {
    ["D"] = "Może to dziwne słowa jak na impa, lecz chciałbym mieć własnego ulubieńca. Naprawdę bym chciał. To nie w porządku, że Niby ma mnie, a ja nic nie mam!$B$BWłaściwie, to nawet nie musi być żywe stworzenie. Potrzebowałbym czegoś na początek, może felowego materiału. Satyry tutaj w Felwood czasami mają go przy sobie, więc musisz po prostu mordować je do chwili, kiedy taki odnajdziesz. Nie brzmi tak źle, prawda?",
    ["O"] = "Przynieś fragment felowego materiału Impsy\'emu w głębi Felwood.",
    ["T"] = "Swędzący i gorący",
  },
  [8421] = {
    ["D"] = "Teraz, kiedy mam już plugawy materiał, mogę wreszcie zacząć tworzyć *moje* zwierzątko.$B$BBędzie potrzebowało oczu. Może mógłbyś przynieść mi nieco Rotting Wood z łażących żelaznych drzew, bym mógł wyrzeźbić kilka przepięknych oczu? Znajdziesz je na północy, w Irontree Woods.$B$BBędę też potrzebował trochę esencji krwawego jadu, aby nadać mojemu przyjacielowi demoniczny zapach. Plugawe szlamy zawierają taką esencję; snują się nieopodal Niby\'ego i mnie.",
    ["O"] = "Przynieś Impsy\'emu z Felwood 10 sztuk Rotting Wood i 4 Bloodvenom Essence",
    ["T"] = "Zły towar",
  },
  [8422] = {
    ["D"] = "Mój przyjaciel jest niemal gotowy. Teraz potrzebuję tylko jakiegoś pierza.$B$BNadają się tylko Voodoo Feathers będące w posiadaniu trolli z Sunken Temple. Trolle te to Gasher, Mijan, Zolo, Hukku, Zul\'lor i Loro. Zabij je. Zabij je wszystkie.$B$BTo niełatwe zadanie, $N, uczynię je więc wartym twojego trudu, dając ci coś należącego do Niby\'ego - i tak pewnie tego nie potrzebuje.",
    ["O"] = "Przynieś wszystkie 6 Voodoo Feathers od trolli z Sunken Temple.",
    ["T"] = "Opierzone trolle",
  },
  [8423] = {
    ["D"] = "<Bohater przygląda się tobie.>$B$BNie ma wątpliwości, że jesteś $C. Powierzę ci zaszczytne zadanie, ale najpierw muszę sprawdzić twoją siłę.$B$BMówi się, że Rexxar uznaje swój miecz za dostatecznie naostrzony, jeżeli jest w stanie zabić nim piekielnego dzika jednym szybkim cięciem. Teraz ja sprawdzę twoją siłę, karząc ci zabijać te dziki.",
    ["O"] = "Zabij 7 Helboar ze Blasted Lands i wróć do Fallen Hero of the Horde.",
    ["T"] = "Braterstwo wojowników",
  },
  [8424] = {
    ["D"] = "Nieustająca obecność Shadowsworn w Blasted Lands przysparza mi wielu cierpień. Ich mroczne rytuały i zaklęcia powodują ból, jakiego nigdy za życia nie zaznałem.$B$BZa twym pośrednictwem mogę przesłać im własną bolesną wiadomość. Ruszaj i przekaż mój gniew.",
    ["O"] = "Wyrżnij Shadowsworn z Blasted Lands i wróć do Fallen Hero of the Horde.",
    ["T"] = "Wojna z Cieniowiercami",
  },
  [8425] = {
    ["D"] = "Twoje męstwo ulżyło nieco memu cierpieniu. Stosownym uczynkiem jest ofiarować ci coś w zamian.$B$BZa mego życia moja broń i zbroja były doskonałe, a teraz już do niczego mi się nie przydadzą. W twoich rękach przyniosą więcej pożytku.$B$BUdaj się do Sunken Temple i zniszcz trollowych strażników: Gashera, Mijana, Hukku, Zul\'lora i Lora. Noszą magiczne pióra, które potrafią przywrócić mi materialne ciało na wystarczająco długą chwilę, bym mógł ci wręczyć nagrodę.",
    ["O"] = "Przynieś pióra Voodoo Feathers trolli z Sunken Temple do Fallen Hero of the Horde.",
    ["T"] = "Pióra voodoo",
  },
  [8426] = {
    ["D"] = "Bitwa w Wąwozie Wojennej Pieśni przeciwko Srebrnoskrzydłym Strażnikom ma ogromne znaczenie. Pod pozorem ochrony lasu, który do nich nie należy, Sojusz stara się odebrać Hordzie dostęp do jednego z naszych największych źródeł drewna.$B$BNie pozwól, aby tak się stało, $N! Wróć do mnie z dowodem, że godnie służysz Hordzie!",
    ["O"] = "Przynieś 3 Warsong Marks of Honor Piewcy Wojny Hordy znajdującemu się poza polem bitwy.",
    ["T"] = "Bitwa o Wąwóz Wojennej Pieśni",
  },
  [8427] = {
    ["D"] = "Bitwa w Wąwozie Wojennej Pieśni przeciwko Srebrnoskrzydłym Strażnikom jest niezwykle ważna. Pod pozorem ochrony lasu, który do nich nie należy, Sojusz stara się odebrać Hordzie jedno z największych źródeł drewna.$B$BNie pozwól, by do tego doszło, $N! Wróć do mnie z dowodem twojej godnej służby Hordzie!",
    ["O"] = "Przynieś 3 Warsong Gulch Marks of Honor do Piewcy Wojny Hordy znajdującego się poza polami bitwy.",
    ["T"] = "Bitwa o Wąwóz Wojennej Pieśni",
  },
