  [8687] = {
    ["D"] = "Wezwano posiłki, by dołączyły do ataku na Hive\'Zora. $gZostałeś wybrany:Zostałaś wybrana;, aby namierzyć kopaczy Hive\'Zora. Zgłoś się do dowódcy Mar\'alith po ukończeniu zadania.",
    ["O"] = "Zabij 30 Hive\'Zora Tunnelers i zgłoś się do Dowódcy Mar\'alith w Cenarion Hold, w Silithus. Musisz też przynieść Combat Task Briefing VII, aby ukończyć misję.",
    ["T"] = "Cel: kopacze tuneli Hive\'Zora",
  },
  [8688] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Starszy Windrun",
  },
  [8689] = {
    ["D"] = "Jestem rad słysząc, że pomagasz nam w naszym ataku na Ahn\'Qiraj, $N. Mogę stworzyć dla ciebie przedmiot, który pomoże ci w walkach przeciwko naszym wrogom, $C.$B$BPotrzebowałbym peleryny Qiraji, którą dostosuję do twoich rozmiarów. Potrzebować również będę posążków i skarabeuszy, by stworzyć odpowiednie klamry.$B$BObiecuję, że się nie zawiedziesz.",
    ["O"] = "Przynieś 1 Qiraji Martial Drape, 2 Jasper Idols, 5 Gold Scarabs i 5 Clay Scarabs do Keyl Swiftclaw w Silithus. Musisz również zdobyć reputację Revered z Cenarion Circle, by ukończyć to zadanie.",
    ["T"] = "Peleryna nieskończonej wiedzy",
  },
  [8690] = {
    ["D"] = "Jestem rad słysząc, że pomagasz nam w naszym ataku na Ahn\'Qiraj, $N. Mogę stworzyć dla ciebie przedmiot, który pomoże ci w walkach przeciwko naszym wrogom, $C.$B$BPotrzebowałbym peleryny Qiraji, którą dostosuję do twoich rozmiarów. Potrzebować również będę posążków i skarabeuszy, by stworzyć odpowiednie klamry.$B$BObiecuję, że się nie zawiedziesz.",
    ["O"] = "Przynieś 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Clay Scarabs i 5 Gold Scarabs do Keyl Swiftclaw w Silithus. Musisz również zdobyć reputację Revered z Cenarion Circle, by ukończyć to zadanie.",
    ["T"] = "Peleryna nadciągającej burzy",
  },
  [8691] = {
    ["D"] = "Jestem rad słysząc, że pomagasz nam w naszym ataku na Ahn\'Qiraj, $N. Mogę stworzyć dla ciebie przedmiot, który pomoże ci w walkach przeciwko naszym wrogom, $C.$B$BPotrzebowałbym peleryny Qiraji, którą dostosuję do twoich rozmiarów. Potrzebować również będę posążków i skarabeuszy, by stworzyć odpowiednie klamry.$B$BObiecuję, że się nie zawiedziesz.",
