  [8728] = {
    ["D"] = "O, zajęło ci to trochę więcej czasu niż myślałem. A teraz pozwól, że sprawdzę co mówi księga.$B$B<Narain w ciszy czyta księgę, co jakiś czas mamrocząc pod nosem.>$B$BDobra wiadomość jest taka, że jestem w 99% pewien, że jestem w stanie stworzyć arkanitową boję zgodnie z twoimi oczekiwaniami. Jednak jest to całkowicie zależne od złej wiadomości.$B$BZła wiadomość jest taka, że będę potrzebował ogromnych ilości arkanitu, rudy elementium i rzadkich kamieni.$B$BPrzynieś mi to, czego potrzebuję, a stworzę boję.",
    ["O"] = "Narain Soothfancy z Tanaris chce byś dostarczył mu 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds i 10 Blue Sapphires.",
    ["T"] = "Dobra i zła wiadomość",
  },
  [8729] = {
    ["D"] = "Wspomniałem już o złych wieściach? Te złe wieści to czeluści: 300 metrów zniszczenia i śmierci. Mogłem zapomnieć o tym małym szczególe.$B$BZgodnie z moim super telepatycznym jasnowidztwem, najlepsze miejsce do użycia boi znajdziesz na wybrzeżu Ashary, w Zatoce Burz.$B$BPoszukaj wiru wodnego, najlepiej pełnego wraków.$B$BPrzy okazji, mam nadzieję że masz przyjaciół.$B$BJeśli jakimś cudem ci się uda, zabierz fragment berła do Anachronosa.",
    ["O"] = "Użyj Arcanite Buoy na Swirling Maelstrom w Bay of Storms, w Azshara.",
    ["T"] = "Gniew Neptulona",
  },
  [8730] = {
    ["D"] = "Czempionie, to ty? Tysiąc lat minęło, od kiedy powierzono mi odłamek, a teraz, w mojej najczarniejszej godzinie, powinien pojawić się ktoś, kto uwolni mnie od niego... ale czymże byłaby tragedia bez okrucieństwa?$B$B<Vaelastrasz kaszle słabo.>$B$BNe... Nefarius ma teraz odłamek berła.$B$BTCzas ucieka. Nefarius chce go zniszczyć. Musisz się spieszyć!",
    ["O"] = "Zabij Nefariana i odzyskaj Red Scepter Shard. Zwróć go Anachronosowi z Caverns of Time w Tanaris. Masz pięć godzin na ukończenie tego zadania.",
    ["T"] = "Spaczenie Nefariusa",
  },
  [8731] = {
    ["D"] = "Witaj, $N. Nim przydzielę ci jakieś ważniejsze zajęcie, będziesz musiał odrobić swoją działkę służby polowej.$B$BNieopodal Hive\'Regal znajdziesz Legion Orgrimmarski Kapitana Skullsplita.$B$BZgłoś się do niego i wróć do mnie z dowodem wypełnienia służby polowej. Będę na ciebie czekał z bardziej skomplikowanymi zadaniami.$B$BAch, jeszcze jedno. Wyświadcz mi przysługę i nie zbliżaj się do Brygady Ironforge. Mamy do czynienia ze sporym napięciem pomiędzy ochotnikami z Hordy i Przymierza.",
    ["O"] = "Zamelduj się u Kruga Skullsplita na posterunku Legionu Orgrimmarskiego u wejścia do Hive\'Regal, podpisz swoje papiery i wróć do Windcallera Kaldona, z Cenarion Hold w Silithiusie.$B$BUwaga: Leczenie lub wzmacnianie zaklęciami członków Legionu Orgrimmarskiego oflaguje cię jako cel PvP.",
    ["T"] = "Służba w polu",
  },
  [8732] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Dokumenty Służbowe",
  },
  [8733] = {
    ["D"] = "To podróż odkupienia, $gbohaterze:bohaterko;. Gdyby mnie dziś zabito, umarłbym za słuszną sprawę. Musisz odzyskać zielony odłamek berła. Musisz oczyścić Eranikusa ze skażenia, którym obarczyli go Przedwieczni Bogowie.$B$BUdaj się do Darnassus. Poza granicami miasta znajdziesz jednego z moich agentów. Ten agent zajmie się wszystkim i poinformuje Tyrande o naszych planach bez alarmowania Staghelma.$B$B<Malfurion wzdycha.>$B$BPopadliśmy w niełaskę po tysiącu lat...",
    ["O"] = "Dostań się na Teldrassil i znajdź agenta Malfuriona gdzieś za granicami Darnassus.",
    ["T"] = "Eranikus, Tyran Snu",
  },
  [8734] = {
    ["D"] = "Tyrande zostanie powiadomiona, $gśmiertelniku:śmiertelniczko;. Shan\'do Stormrage przygotował mnie na taką sytuację.$B$BMusisz udać się do Moonglade i porozmawiać z Remulosem. Przekaże ci on dalsze instrukcje w kwestii przywołania Eranikusa.$B$BWszyscy życzymy ci powodzenia.",
    ["O"] = "Przybądź do Moonglade i pomów ze strażnikiem Remulosem.",
    ["T"] = "Tyrande i Remulos",
  },
  [8735] = {
    ["D"] = "Musisz udać się do czterech portalów snu na Azeroth. Z każdego portalu musisz zdobyć fragment spaczenia Koszmaru. Drakan, który zamieszkuje te obszary będzie posiadał ten fragment. Wróć do mnie, kiedy już zdobędziesz te fragmenty.",
    ["O"] = "Udaj się do czterech portalów Szmaragdowego Snu na Azeroth i przy każdym zbierz Fragment of the Nightmare\'s Corruption. Wróć do Opiekuna Remulosa w Moonglade kiedy już ukończysz zadanie.",
    ["T"] = "Korupcja Koszmaru",
  },
  [8736] = {
    ["D"] = "Musimy użyć powściągliwości przeciw Eranikusowi. Mamy go ocalić, a nie zniszczyć.$B$BTyrande jest już w drodze, by pomóc nam w tym zadaniu. Musimy przetrwać ataki smoka i uratować Nighthaven przed pewnym zniszczeniem.$B$BStrzeż się! Ty i twoi sojusznicy jesteście naszą jedyną nadzieją!",
    ["O"] = "Obroń Nighthaven przed Eranikusem. Nie pozwól, by Opiekun Remulos zginął. Nie zabijaj Eranikusa. Broń się. Czekaj na Tyrande.",
    ["T"] = "Manifestacja Koszmaru",
  },
  [8737] = {
    ["D"] = "Młot Zmierzchu i szlachta żywiołów, którą czczą, stanowią ogromne zagrożenie dla naszych działań w Silithus. Nie możemy sobie pozwolić na lekceważenie starych przeciwników, gdyż nowi już czekają na nas w Ahn\'Qiraj. Znajdź sposób na przywołanie i pokonanie Lazurowego Templariusza, i zgłoś się do Bora Wildmane\'a.",
    ["O"] = "Przyzwij i pokonaj Azure Templar i zamelduj się z powrotem u Bora Wildmane\'a w Cenarion Hold. Musisz także przynieść Tactical Task Briefing I, by zakończyć to zadanie.",
    ["T"] = "Lazurowy Templariusz",
  },
  [8738] = {
    ["D"] = "Wysłaliśmy swoich najlepszych zwiadowców głęboko do silithidowych uli, by zebrać informację. Zwiadowca Landion obserwował przez kilka dni ruchy silithidów w Hive\'Regal. Znajdź go i zdobądź pisemny raport. Musimy być w stanie działać na podstawie tych informacji tak szybko, jak to tylko możliwe, $N.",
    ["O"] = "Skontaktuj się ze zwiadowcą Landionem wewnątrz Hive\'Regal i zwróć Hive\'Regal Scout Report do Proudhorna w Cenarion Hold. Musisz również przynieść Tactical Task Briefing VII, aby ukończyć to zadanie.",
    ["T"] = "Raport o Hive\'Regal",
  },
  [8739] = {
    ["D"] = "W celu zebrania informacji wysłaliśmy naszych najlepszych zwiadowców w głąb uli silithidów. Zwiadowczyni Jalia obserwuje ruchy silithidów w Hive\'Ashi od kilku dni. Odszukaj ją i zdobądź pisemny raport. Będziemy musieli działać w oparciu o tę informację najszybciej jak tylko się da, $N.",
    ["O"] = "Skontaktuj się ze Zwiadowczynią Jalią w Hive\'Ashi i zwróć Hive\'Ashi Scout Report Proudhornowi w Cenarion Hold. Żeby ukończyć to zadanie musisz przynieść ze sobą również Tactical Task Briefing VIII.",
    ["T"] = "Raport o Hive\'Ashi",
  },
  [8740] = {
    ["D"] = "Bandy kultystów Młotu Zmierzchu zostały zauważone poza zasięgiem naszych sił w Cenarion Hold - zabijają nasze mniejsze patrole oraz karawany.$B$BZnajdź i pokonaj maruderów Zmierzchu wraz z ich przywódcą, straszną wojowniczką o imieniu Morna. Zgłoś się do zaklinacza wiatru Proudhorna po wykonaniu zadania.",
    ["O"] = "Zabij Twilight Marauder Morna oraz 2 Twilight Marauders. Zgłoś się do Proudhorna, kiedy ukończysz zadanie. Musisz również przynieść Tactical Task Briefing IX, by wykonać to zadanie.",
    ["T"] = "Maruderzy Zmierzchu",
  },
  [8741] = {
    ["D"] = "Opiekun oczekuje na twój powrót, $N. Zanieś Green Scepter Shard Anachronosowi w Grotach Czasu.",
    ["O"] = "Zanieś Green Scepter Shard Anachronosowi w Caverns of Time, w Tanaris.",
    ["T"] = "Powrót $gczempiona:czempionki;",
  },
