  },
  [8770] = {
    ["D"] = "W miarę nasilania działań wojennych, obecność silithidów w okolicy stanowi coraz większe zagrożenie dla naszych przedsięwzięć. $gZostałeś wybrany:Zostałaś wybrana; do wzięcia udziału w ataku na Hive\'Ashi, gdzie twoim głównym celem będą Obrońcy Hive\'Ashi.$B$BStaw się do dowódcy Mar\'alith po wypełnieniu zadania.",
    ["O"] = "Zabij 30 Hive\'Ashi Defenders i zgłoś się ponownie do Dowódcy Mar\'alith w Cenarion Hold, w Silithus. Musisz również przynieść Combat Task Briefing I, by zaliczyć to zadanie.",
    ["T"] = "Cel: Obrońcy Hive\'Ashi",
  },
  [8771] = {
    ["D"] = "Wraz ze wzrostem aktywności wojennej, obecność silithidów zagraża naszym operacjom. $gZostałeś przydzielony:Zostałaś przydzielona; do ataku na Hive\'Ashi. Twoim celem będzie rozprawienie się z piaskowymi łowcami Hive\'Ashi.$B$BPo wykonaniu zadania zgłoś się do dowódcy Mar\'alitha.",
    ["O"] = "Zabij 30 Hive\'Ashi Sandstalkers następnie zgłoś się do Dowódcy Mar\'alitha w Cenarion Hold, w Silithus. Aby zaliczyć to zadanie, musisz posiadać w ekwipunku Combat Task Briefing II.",
    ["T"] = "Cel: piaskowi łowcy Hive\'Ashi",
  },
  [8772] = {
    ["D"] = "Jednostki wsparcia zostały wezwane do dołączenia do ataku na Hive\'Zora. Twoim zadaniem jest wyeliminowanie strażników Hive\'Zora. Zgłoś się do dowódcy Mar\'alitha po ukończeniu zadania.",
    ["O"] = "Zabij 30 Hive\'Zora Waywatchers i zgłoś się do Dowódcy Mar\'alitha przebywającego w Cenarion Hold, w Silithus. Musisz również przynieść Combat Task Briefing VI w celu ukończenia tego zadania.",
    ["T"] = "Cel: strażnicy Hive\'Zora",
  },
  [8773] = {
    ["D"] = "Wezwano posiłki, by przyłączyły się do ataku na Hive\'Zora. Wybrano cię do namierzania rozbójników Hive\'Zora. Zgłoś się ponownie do dowódcy Mar\'alith po wykonaniu zadania.",
    ["O"] = "Zabij 30 Hive\'Zora Reavers i zgłoś się do dowódcy Mar\'alith w Twierdzy Cenarion w Silithus. Aby ukończyć to zadanie, musisz także przynieść Combat Task Briefing IV.",
    ["T"] = "Cel: Hive\'Zora Reavers",
  },
  [8774] = {
    ["D"] = "W miarę nasilania się działań wojennych, obecność silithidów na tym obszarze stanowi coraz większe zagrożenie dla naszych operacji. $gZostałeś wybrany:Zostałaś wybrana; do wzięcia udziału w ataku na Hive\'Regal, gdzie twym głównym celem będą Hive\'Regal Ambushers.$B$BPo wykonaniu zadania wróć z powrotem do dowódcy Mar\'alitha.",
    ["O"] = "Zabij 30 Hive\'Regal Ambushers i zgłoś się do dowódcy Mar\'alitha w Cenarion Hold w Silithus. Aby ukończyć to zadanie, musisz także przynieść Combat Task Briefing VIII.",
    ["T"] = "Cel: Hive\'Regal Ambushers",
  },
  [8775] = {
    ["D"] = "Podczas, gdy przygotowania wojenne nabierają tempa, obecność Silithidów w obszarze prezentuje się jako coraz szybciej narastające zagrożenie dla naszych operacji.$gZostałeś wybrany:Zostałaś wybrana;, aby wziąć udział w szturmie na Hive\'Regal, gdzie twoim głównym celem będą latające Hive\'Regal Spitfires.$B$BZgłoś się z powrotem do Commandera Mar\'alitha, gdy wykonasz swoje zadanie.",
    ["O"] = "Zabij 30 Hive\'Regal Spitfires i zgłoś się z powrotem do Commandera Mar\'alitha w Cenarion Hold w Silithus. Musisz również przynieść Combat Task Briefing IX, aby ukończyć to zadanie.",
    ["T"] = "Cel: Hive\'Regal Spitfires",
  },
  [8776] = {
    ["D"] = "Podczas, gdy przygotowania wojenne nabierają tempa, obecność Silithidów w obszarze prezentuje się jako coraz szybciej narastające zagrożenie dla naszych operacji. $gZostałeś wybrany:Zostałaś wybrana;, aby wziąć udział w szturmie na Hive\'Regal gdzie twoim głównym celem będą Hive\'Regal Slavemakers.$B$BZgłoś się z powrotem do Commandera Mar\'alitha, gdy wykonasz swoje zadanie.",
    ["O"] = "Zabij 30 Hive\'Regal Slavemakers i zgłoś się z powrotem do Commandera Mar\'alitha w Cenarion Hold w Silithus. Musisz również przynieść Combat Task Briefing X, aby ukończyć to zadanie.",
    ["T"] = "Cel: Hive\'Regal Slavemakers",
  },
  [8777] = {
    ["D"] = "Podczas, gdy przygotowania wojenne nabierają tempa, obecność silithidów w obszarze prezentuje się jako coraz szybciej narastające zagrożenie dla naszych operacji. $gZostałeś wybrany:Zostałaś wybrana;, aby wziąć udział w szturmie na Hive\'Regal gdzie twoim głównym celem będą Hive\'Regal Burrowers.$B$BZgłoś się z powrotem do Commandera Mar\'alitha, gdy wykonasz swoje zadanie.",
    ["O"] = "Zabij 30 Hive\'Regal Burrowers i zgłoś się z powrotem do Commandera Mar\'alitha w Cenarion Hold w Silithus. Musisz również przynieść Combat Task Briefing XI, aby ukończyć to zadanie.",
    ["T"] = "Cel: Hive\'Regal Burrowers",
  },
  [8778] = {
    ["D"] = "Brygada Ironforge zwróciła się do nas z niezwykłą prośbą o wysoce... niestabilne... komponenty. Zbierz je i zanieś Panu Nozzlespringowi z Brygady Ironforge.",
    ["O"] = "Przynieś 6 Oils of Immolation, 5 Goblin Rocket Fuel oraz 10 Dense Blasting Powder do Arkanisty Nozzlespringa w pobliżu Hive\'Zora w Silithus. Aby ukończyć to zadanie, musisz także przynieść Logistics Task Briefing IV.",
    ["T"] = "Brygada Ironforge potrzebuje materiałów wybuchowych!",
  },
  [8779] = {
    ["D"] = "Badania Geologist Larksbane okazały się nieocenione dla naszych działań w Silithiusie. Niedawno poprosiła o materiały obserwacyjne, których do nich potrzebuje.$B$BProszę, zdobądź je i dostarcz jej, aby mogła kontynuować swoją pracę.",
    ["O"] = "Przynieś Geologist Larksbane 1 Large Brilliant Shard, 1 Large Radiant Shard i 1 Huge Emerald. Znajdziesz ją w Cenarion Hold w Silithiusie. Aby ukończyć tę misję, musisz jej także oddać Rozkazy: Zadanie Logistyczne nr 5.",
    ["T"] = "Materiały obserwacyjne",
  },
  [8780] = {
    ["D"] = "Zapas zestawów ulepszających zbroje Brygady Ironforge na polu bitwy jest na drastycznie niskim poziomie. Zdobądź zestawy i dostarcz je Janeli Stouthamer w placówce Brygady Ironforge na zewnątrz Hive\'Zora.",
    ["O"] = "Przynieś 8 Rugged Armor Kits i 8 Heavy Armor Kits Janeli Stouthammer z Ironforge Brigade Outpost w pobliżu Hive\'Zora, w Silithus. Aby ukończyć to zadanie, musisz także przynieść Logistics Task Briefing VII.",
    ["T"] = "Zestawy ulepszające zbroje",
  },
  [8781] = {
    ["D"] = "Brygada Ironforge była godnym sojusznikiem w naszej walce w Silithus. Niestety, po drodze zginęło wiele ich zapasów. Zdobądź partię broni i dostarcz ją Janeli Stouthammer w pobliżu Hive\'Zora.",
    ["O"] = "Przynieś 2 Moonsteel Broadsword Janeli Stouthammer z Ironforge Brigade Outpost poza Hive\'Zora. Aby ukończyć to zadanie, musisz także przynieść Logistics Task Briefing VI.",
    ["T"] = "Broń na polu",
  },
  [8782] = {
    ["D"] = "Ostatni napływ ochotników spowodował brak mundurów. Zdobądź partię materiału i zanieś ją do zaklinacza wiatru Proudhorna.",
    ["O"] = "Przynieś 1 Mooncloth, 2 Bolts of Runecloth i 1 Ironweb Spider Silk do Zaklinacza Wiatru Proudhorna w Cenarion Hold w Silithus. Aby ukończyć to zadanie, musisz także przynieść Logistics Task Briefing VIII.",
    ["T"] = "Materiały na mundury",
  },
  [8783] = {
    ["D"] = "Vargus, kowal z Cenarionowej Stanicy, chce użyć zaczarowanych materiałów przy tworzeniu potężnej broni dla naszych sił. Zdobądź je i przynieś prosto do Vargusa, żeby żołnierze Cenarionowej Stanicy mogli nadal być dobrze wyposażeni.",
    ["O"] = "Przynieś 2 Enchanted Thorium Bary i 2 Enchanted Leathery do Vargusa w Cenarion Hold w Silithus. Musisz mieć ze sobą Logistics Task Briefing IX, żeby ukończyć zadanie.",
    ["T"] = "Niezwykłe materiały",
  },
  [8784] = {
    ["D"] = "$gOdkryłeś:Odkryłaś; starożytny artefakt Qiraji! Prawdopodobnie jedno ze smoków przy wejściu do świątyni byłoby zainteresowane tym reliktem.",
    ["O"] = "Zabierz Ancient Qiraji Artifact do smoków, niedaleko wejścia do świątyni.",
    ["T"] = "Sekrety Qiraji",
  },
  [8785] = {
    ["D"] = "Legion Orgrimmaru złożył zapotrzebowanie na kilka nietypowych składników. Mając na uwadze ich dokonania w Silithus, chcielibyśmy wypełnić ich prośbę tak szybko, jak to tylko możliwe. Zdobądź materiały i przynieś je do trolicy o imieniu Shai.",
    ["O"] = "Przynieś 6 Powerful Mojo, 6 Flasks of Big Mojo i 8 Oils of Immolation do Shadow Priestess Shai niedaleko Hive\'Regal w Silithus. Musisz mieć ze sobą Logistics Task Briefing IV, aby wykonać to zadanie.",
    ["T"] = "Legion Orgrimmar\'u potrzebuje mojo!",
  },
  [8786] = {
    ["D"] = "Legion Orgrimmar poprosił o dodatkową broń, niestety nie jesteśmy w stanie im jej zapewnić. Zdobądź broń, o którą prosili, i zanieś ją do Meroka Longstride w pobliżu Hive\'Regal.",
    ["O"] = "Przynieś 3 Massive Iron Axes Merokowi Longstride do obozu Legionu z Orgrimmaru w pobliżu Hive\'Regal. Aby ukończyć to zadanie, musisz także przynieść Logistics Task Briefing VI.",
    ["T"] = "Broń na pole bitwy",
  },
  [8787] = {
    ["D"] = "Dzielni ochotnicy z Regimentu Orgrimmaru przybyli do Silithus, by pomóc naszej sprawie. Ich zapasy zestawów zbroi w jakiś sposób zaginęły podczas podróży. Zdobądź partię zestawów zbroi i dostarcz je do Meroka Longstride, do obozu Regimentu Orgrimmaru.",
    ["O"] = "Przynieś 8 Rugged Armor Kits oraz 8 Heavy Armor Kits do Meroka Longstride niedaleko Hive\'Regal. Dodatkowo musisz przynieść Logistics Task Briefing VII, aby zakończyć to zadanie.",
    ["T"] = "Zestawy zbroi dla oddziału",
  },
  [8788] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "A Gently Shaken Gift",
  },
  [8789] = {
    ["D"] = "Nie siedzieliśmy tu bezczynnie przez milenia, $N.$B$BObserwowaliśmy te bestie, gdy zaczęły się nawzajem żreć, jak kończyły im się zapasy. Słuchaliśmy, jak knuli, by zniszczyć nasz świat i dowiedzieliśmy się o ich zdradzie wewnątrz.$B$BMają słabości i my wiemy jak ich użyć na naszą korzyść.$B$BZnajdż i przynieś mi ich ceremonialne uzbrojenia. Połączone z minerałem stworzonym przez niestabilność ich własnego Boga, staną się narzędziem osądu.",
    ["O"] = "Arygos w Świątyni Ahn\'Qiraj stworzy dla ciebie Elementium Infused Armaments, gdy przyniesiesz mu Imperial Qiraji Armaments i 3 Elementium Ingots.",
    ["T"] = "Królewskie regalia Qiraji",
  },
  [8790] = {
    ["D"] = "Arygos uważa, ze minerał zrodzony z konfliktu między Starymi Bogami i ich sługami jest również śmiertelny dla nich pod pewnymi warunkami. Mówię tu o elementium, $gśmiertelniku:śmiertelniczko;.$B$BZnajdź i przynieś mi królewskie regalia Qiraji i toksyczny minerał, a ja stworzę przedmiot o wielkiej mocy.",
    ["O"] = "Merithra of the Dream w Świątyni Ahn\'Qiraj stworzy dla ciebie Elementium Infused Armaments, jeśli przyniesiesz jej Imperial Qiraji Regalia i 3 Elementium Ingots.",
    ["T"] = "Królewskie regalia Qiraji",
  },
  [8791] = {
    ["D"] = "Okropne zagrożenie zostało pogrzebane. Okrutny Ossirian został pokonany.$B$BMieszkańcy Kalimdoru doznają ulgi, słysząc o tym zwycięstwie. Weź głowę Ossiriana i pokaż dowódcy Cenarion Hold, Mar\'alithowi.",
    ["O"] = "Dostarcz Head of Ossirian the Unscarred do dowódcy Mar\'alitha w Cenarion Hold, w Silithus.",
    ["T"] = "Upadek Ossirian",
  },
  [8792] = {
    ["D"] = "Witaj, cieszę się, że $gzechciałeś:zechciałaś; mnie wysłuchać. Horda potrzebuje każdego możliwego wsparcia, by przygotować się na wojnę z Ahn\'Qiraj, a to oznacza, że potrzebujemy właśnie ciebie! Przez cały czas nasi poborcy gromadzą surowce, bez których nie poradzimy sobie w nadchodzącej wojnie, ale nie uda nam się zrealizować planów bez twego wsparcia, $N!$B$BMusisz porozmawiać z osobą, która nadzoruje ten proces, władcą wojny Gorchukiem. Co ty na to, $c? Pomożesz nam w tych tak ważnych przygotowaniach?",
    ["O"] = "Porozmawiaj z Władcą Wojny Gorchukiem w Valley of Spirits w Orgrimmarze.",
    ["T"] = "Horda potrzebuje twej pomocy!",
  },
  [8793] = {
    ["D"] = "Witaj, cieszę się, że $gzechciałeś:zechciałaś; mnie wysłuchać. Horda potrzebuje każdego możliwego wsparcia, by przygotować się na wojnę z Ahn\'Qiraj, a to oznacza, że potrzebujemy właśnie ciebie! Przez cały czas nasi poborcy gromadzą surowce, bez których nie poradzimy sobie w nadchodzącej wojnie, ale nie uda nam się zrealizować planów bez twego wsparcia, $N!$B$BMusisz porozmawiać z osobą, która nadzoruje ten proces, władcą wojny Gorchukiem. Co ty na to, $C? Pomożesz nam w tych tak ważnych przygotowaniach?",
    ["O"] = "Porozmawiaj z Władcą Wojny Gorchukiem w Valley of Spirits w Orgrimmarze.",
    ["T"] = "Horda potrzebuje twej pomocy!",
  },
  [8794] = {
