  [8795] = {
    ["D"] = "Witaj, cieszę się, że $gzechciałeś:zechciałaś; mnie wysłuchać. Przymierze potrzebuje każdego możliwego wsparcia, by przygotować się na wojnę z Ahn\'Qiraj, a to oznacza, że potrzebujemy właśnie ciebie! Przez cały czas nasi poborcy gromadzą surowce, bez których nie poradzimy sobie w nadchodzącej wojnie, ale nie uda nam się zrealizować planów bez twego wsparcia, $N!$B$BMusisz porozmawiać z osobą, która nadzoruje ten proces, feldmarszałkiem Snowfallem. Co ty na to, $C? Pomożesz nam w tych tak ważnych przygotowaniach?",
    ["O"] = "Porozmawiaj z Feldmarszałkiem Snowfallem w Military Ward w Ironforge.",
    ["T"] = "Przymierze potrzebuje twej pomocy!",
  },
  [8796] = {
    ["D"] = "Witaj, cieszę się, że $gzechciałeś:zechciałaś; mnie wysłuchać. Przymierze potrzebuje każdego możliwego wsparcia, by przygotować się na wojnę z Ahn\'Qiraj, a to oznacza, że potrzebujemy właśnie ciebie! Przez cały czas nasi poborcy gromadzą surowce, bez których nie poradzimy sobie w nadchodzącej wojnie, ale nie uda nam się zrealizować planów bez twego wsparcia, $N!$B$BMusisz porozmawiać z osobą, która nadzoruje ten proces, feldmarszałkiem Snowfallem. Co ty na to, $c? Pomożesz nam w tych tak ważnych przygotowaniach?",
    ["O"] = "Porozmawiaj z Feldmarszałkiem Snowfallem w Military Ward w Ironforge.",
    ["T"] = "Przymierze potrzebuje twej pomocy!",
  },
  [8797] = {
    ["D"] = "Witaj, cieszę się, że $gzechciałeś:zechciałaś; mnie wysłuchać. Przymierze potrzebuje każdego możliwego wsparcia, by przygotować się na wojnę z Ahn\'Qiraj, a to oznacza, że potrzebujemy właśnie ciebie! Przez cały czas nasi poborcy gromadzą surowce, bez których nie poradzimy sobie w nadchodzącej wojnie, ale nie uda nam się zrealizować planów bez twego wsparcia, $N!$B$BMusisz porozmawiać z osobą, która nadzoruje ten proces, feldmarszałkiem Snowfallem. Co ty na to, $c? Pomożesz nam w tych tak ważnych przygotowaniach?",
    ["O"] = "Porozmawiaj z Feldmarszałkiem Snowfallem w Military Ward w Ironforge.",
    ["T"] = "Przymierze potrzebuje twej pomocy!",
  },
  [8798] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Twój własny yeti",
  },
  [8799] = {
    ["D"] = "Słuchaj... nie powinienem ci tego mówić, ale skoro jesteś bohaterem dnia i w ogóle...$B$BO tej porze roku wszędzie jest świeży ostrokrzew, ale nie na długo. Mamy maszynę, która konserwuje ostrokrzew - przez co nigdy się nie psuje! Używamy go, aby urozmaicić święta... i zyski w okresie letnim!$B$BPozwolę ci użyć maszyny, ale tylko jeśli jesteś mistrzem kucharskim. Będziesz potrzebować trochę deeprock salt i dwie, trzy, no powiedzmy pięć sztuk złota. Dzięki temu otrzymasz niezłą porcję, którą możesz zatrzymać.",
    ["O"] = "Przynieś 1 Deeprock Salt i 5 sztuk złota do maszyny Holly Preserver, po czym otrzymasz 5 Preserved Holly.",
    ["T"] = "Bohater dnia",
  },
  [8800] = {
    ["D"] = "Kiedy już uporasz się z zadaniami wojennymi, porozmawiaj z kowalem Vargusem. Pokaż mu wszystkie odznaki, które $gzdobyłeś:zdobyłaś;. W zamian za nie wyda ci on sprzęt, na jaki $gzasłużyłeś:zasłużyłaś; poświęcając się naszej sprawie.",
    ["O"] = "Porozmawiaj z Vargusem w Cenarion Hold, w Silithus",
    ["T"] = "Cenarionowe uzbrojenie",
  },
  [8801] = {
    ["D"] = "Ściany Ahn\'Qiraj drżą. Mroczna siła, starsza od samego świata, została zniszczona.$B$BGdy spoglądasz na gigantyczną abominację, twe serce prawie staje. Nawet po śmierci widzisz spuściznę, jaką zostawił wokół C\'Thun.$B$B$gZrobiłeś:Zrobiłaś; coś, co wydawało się być niemożliwym.$B$BPochwycasz oko i chowasz bezpiecznie w swej torbie.$B$BWeź oko C\'Thuna do smoków w kolejnej komnacie.",
    ["O"] = "Zabierz Eye of C\'Thun do Caelastraszy w Temple of Ahn\'Qiraj.",
    ["T"] = "Spuścizna C\'Thuna",
  },
  [8802] = {
    ["D"] = "Do Jaskiń Czasu idź, $gpanie:pani; $N. Anachronos czeka na twój powrót. Daj mu oko C\'Thuna, gdyż na pewno będzie chętny umieścić je w kolekcji swego mistrza.",
    ["O"] = "Zabierz Eye of C\'Thun do Anachronosa w Jaskiniach Czasu.",
    ["T"] = "Zbawiciel Kalimdoru",
  },
  [8803] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Świąteczny prezent",
  },
  [8804] = {
    ["D"] = "Wraz z przybyciem nowych rekrutów do Cenarion Hold pojawił się problem z utrzymaniem ich przy życiu na pustyni. Odwodnienie oraz liczne trujące stworzenia są poważnym zagrożeniem dla niedoświadczonych wolontariuszy. Zdobądź części niezbędne do stworzenia pustynnego zestawu przeżycia i przynieś je do Calandratha w Cenarion Hold.",
    ["O"] = "Przynieś 4 Globes of Water, 4 Powerful Anti-Venom i 4 Smoked Desert Dumplings do Calandratha do karczmy w Cenarion Hold, w Silithus. Musisz mieć ze sobą Logistics Task Briefing I, aby ukończyć to zadanie.",
    ["T"] = "Pustynne zestawy przeżycia",
  },
  [8805] = {
    ["D"] = "Konna dywizja straży Cenarionowej Strażnicy ma braki w zaopatrzeniu jeśli chodzi o zdobione mithrilowe buty. Zdobądź partię obuwia i natychmiast dostarcz ją do Kapitana Visha Kozusa w Cenarion Hold.",
    ["O"] = "Przynieś 3 Ornate Mithril Boots do Vish\'a Kozus\'a, Kapitana Straży w Cenarion Hold w Silithus. Musisz mieć ze sobą Logistics Task Briefing II, aby ukończyć to zadanie.",
    ["T"] = "Buty dla straży",
  },
  [8806] = {
    ["D"] = "Straż Cenarion Hold ma znikome zapasy kamieni szlifierskich. Zdobądź partię i dostarcz je natychmiast do Captaina Visha Kozusa w Cenarion Hold.",
    ["O"] = "Przynieś 10 Dense Grinding Stones, Solid Grinding Stones i 10 Heavy Grinding Stones do Visha Kozusa, Kapitana Straży w Cenarion Hold w Silithus. Dodatkowo musisz przynieść Logistics Task Briefing III, aby zakończyć to zadanie.",
    ["T"] = "Kamienie Szlifierskie dla Straży",
  },
  [8807] = {
    ["D"] = "Odkrycia Geologist Larksbane\'a okazały się mieć ogromną wartość dla naszych działań w Silithus. Niedawno poprosiła o wykorzystanie materiałów wróżbiarskich w jej badaniach.$B$BProszę, zbierz te materiały i dostarcz je do niej, aby mogła kontynuować swoje badania.",
    ["O"] = "Przynieś 1 Large Brilliant Shard, 1 Large Radiant Shard i 1 Huge Emerald do Geologist Larksbane w Cenarion Hold w Silithus. Dodatkowo musisz przynieść Logistics Task Briefing V, aby zakończyć to zadanie.",
    ["T"] = "Materiały Wróżbiarskie",
  },
  [8808] = {
    ["D"] = "Ostatni napływ ochotników spowodował brak mundurów. Zdobądź partię jednolitych materiałów i zanieś je do Windcallera Proudhorna.",
    ["O"] = "Przynieś 1 Mooncloth, 2 Bolts of Runecloth oraz 1 Ironweb Spider Silk do Windcallera Proudhorn w Cenarion Hold w Silithus. Dodatkowo musisz przynieść Logistics Task Briefing VIII aby zakończyć to zadanie.",
    ["T"] = "Materiały mundurowe",
  },
  [8809] = {
    ["D"] = "Vargus, kowal Cenarion Holdu, poprosił o użycie zaklętych materiałów do wytwarzania potężnej broni dla naszych oddziałów. Zdobądź je i zanieś bezpośrednio do Vargusa, aby wojska Cenarion Hold nadal były dobrze wyposażone.",
    ["O"] = "Przynieś 2 Enchanted Thorium Bars i 2 Enchanted Leather do Vargusa w Cenarion Hold w Silithus. Dodatkowo musisz przynieść Logistics Task Briefing IX aby zakończyć to zadanie.",
    ["T"] = "Nadzwyczajne Materiały",
  },
  [8810] = {
    ["D"] = "Nasze zapasy bandaży na polu bitwy niebezpiecznie wyczerpują się po ostatnich stratach, jakie ponieśliśmy. Zdobądź partię bandaży i dostarcz je Windcallera Proudhorna w Cenarion Hold.",
    ["O"] = "Przynieś 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages i 30 Heavy Mageweave Bandages do Windcallera Proudhorna w Cenarion Hold w Silithus. Dodatkowo musisz przynieść ze sobą Logistics Task Briefing X, aby zakończyć to zadanie.",
    ["T"] = "Bandaże dla oddziału",
  },
