  [8827] = {
    ["D"] = "Słyszałem, że Zimowy Dziadek - z hojną pomocą Smokeywood Pastures - położył prezenty dla każdego pod choinką w Ironforge. Chciałbym tam pójść, ale muszę się opiekować PX-238 Winter Wondervolt.$B$BAle ty $gpowinieneś:powinnaś; zdecydowanie to sprawdzić. Jestem pewny, że Zimowy Dziadek ma dla ciebie jakieś prezenty.",
    ["O"] = "Porozmawiaj z Greatfather Winter. Znajdziesz go blisko obszaru sprzedawców Smokywood Pastures w Ironforge.",
    ["T"] = "Zimowe prezenty",
  },
  [8828] = {
    ["D"] = "Słyszałem, że Zimowy Dziadek - z hojną pomocą Smokywood Pastures - położył prezenty dla każdego pod choinką w Orgrimmarze. Sam chciałbym pójść pójść, ale muszę się opiekować PX-238 Winter Wondervolt.$b$bAle ty $gpowinieneś:powinnaś; zdecydowanie to sprawdzić. Jestem pewny, że Zimowy Dziadek ma dla ciebie jakieś prezenty.",
    ["O"] = "Porozmawiaj z Greatfather Winter. Znajdziesz go blisko obszaru sprzedawców Smokywood Pastures w Orgrimmarze.",
    ["T"] = "Zimowe prezenty",
  },
  [8829] = {
    ["D"] = "Twilight Hammer działa poprzez niezliczone warstwy tajemnicy i oszustwa. Podczas gdy ich działania odbywają się w naszym świecie, to są one zaplanowane w miejscu, do którego jeszcze nie byliśmy w stanie dotrzeć.$B$BDoszliśmy do wniosku, że ​​kamienie, których używa Twilight Hammer do przywoływania swoich przełożonych pozwalają na dwukierunkową teleportację. Aby spróbować użyć ich w ten sposób, musimy odtworzyć - w najdrobniejszych szczegółach - szatę wysłannika zmierzchu.$B$BZbierz niezbędne materiały i zanieś je do Aureli Goldleaf, $N.",
    ["O"] = "Przynieś Skin of Shadow, 3 Frayed Abomination Stitchings oraz 1 Twilight Cultist Robe do Aureli Goldleaf w Cenarion Hold w Silithus. Dodatkowo musisz dostarczyć Logistics Task Briefing XI, aby zakończyć to zadanie.",
    ["T"] = "Ostateczne oszustwo",
  },
