  [8856] = {
    ["D"] = "Wraz z przybyciem nowych rekrutów do Cenarion Hold, pojawia się problem z utrzymaniem ich przy życiu na pustyni. Odwodnienie, a także liczne trujące stworzenia stanowią poważne zagrożenie dla niedoświadczonych ochotników. Zbierz zapasy potrzebne do zestawu przetrwania na pustyni i zanieś je do Calandratha w Cenarion Hold.",
    ["O"] = "Przynieś 4 Globes of Water, 4 Powerful Anti-Venom oraz 4 Baked Salmon do Calandratha, do karczmy w Cenarion Hold w Silithus.",
    ["T"] = "Zestawy do przetrwania na pustyni",
  },
  [8857] = {
    ["D"] = "Szukam zaprawionych w boju podróżników, którzy chcieliby zdobyć świeżą próbkę łuski upadłego Kolosa Ashi oraz dostarczyliby ją Oglethorpe\'owi w Booty Bay. Nie, nie, nie musisz zbliżać się do tego truchła. Weź moją próbkę, tylko się pospiesz. Ta próbka nie na da się, gdy będzie zepsuta!",
    ["O"] = "Zanieś Colossus of Ashi\'s Husk do Oglethorpe\'a Obnoticusa w Booty Bay.",
    ["T"] = "Sekrety Kolosa - Ashi",
  },
  [8858] = {
    ["D"] = "Chciałbym wepchać tę łuskę robala w tłustą twarz Oilfista... Ale utknąłem tu, zbierając próbki z tego przerośniętego karalucha. Będę tu do białego rana, biorąc pod uwagę jego rozmiar.$B$BZabierz tę próbkę do Oilfista, i to szybko, $C. On płaci DUŻO!$B$BThorium Point jest w Searin\' Gorge.",
    ["O"] = "Zabierz Colossus of Regal\'s Husk do Nadzorcy Oilfista w Searing Gorge.",
    ["T"] = "Sekrety Kolosa - Regal",
  },
  [8859] = {
    ["D"] = "Moi słudzy nieomal zostali zabici podczas próby zdobycia tej próbki. Musisz się pośpieszyć! Lord Maxwell Tyrosus niecierpliwie oczekuje na świeżą próbkę łuski. Wierzy, że sekrety, jakie skrywa ten Kolos, pomogą w wojnie z Plagą!NEW_lINE$BCzemu tu jeszcze jesteś?! Do Świątyni Nadziei! Tak, zostaniesz sowicie $gwynagrodzony:wynagrodzona; za twe starania...",
    ["O"] = "Zanieś Colossus of Zora\'s Husk Lordowi Maxwellowi Tyrosusowi w Light\'s Hope Chapel w Eastern Plaguelands.",
    ["T"] = "Sekrety Kolosa - Zora",
  },
  [8860] = {
    ["D"] = "Stormwind organizuje celebrację Nowego Roku! Przez cały dzień możesz dostać darmowy alkohol, a wieczorem odbędzie się pokaz fajerwerków! Powinno być pięknie... Booty Bay też organizuje imprezę i założę się, że tam będzie jeszcze lepsza!$B$BCóż, karczmarka Allison w Stormwind potrzebuje zapasu Wędzonych Przekąsek, by móc wykarmić wszystkich gości. Możesz mi zrobić przysługę i to dostarczyć?$B$BDzięki, $N! Karczmarka Allison znajduje się w \"Złotej Róży\", w Dzielnicy Handlowej.",
    ["O"] = "Przynieś Smokywood Supplies do karczmarki Allison w Stormwind.",
    ["T"] = "Sylwestrowa celebracja!",
  },
  [8861] = {
    ["D"] = "Thunder Bluff organizuje celebrację Nowego Roku! Przez cały dzień możesz dostać darmowy alkohol, a wieczorem odbędzie się pokaz fajerwerków! Powinno być pięknie... Booty Bay też organizuje imprezę i założę się, że tam będzie jeszcze lepsza!$B$BCóż, karczmarka Pala w Thunder Bluff potrzebuje zapasu Wędzonych Przekąsek, by móc wykarmić wszystkich gości. Możesz mi zrobić przysługę i to dostarczyć?$B$BDzięki, $N! Karczmarka znajduje się w karczmie niedaleko mostu prowadzącego do Wzniesienia Łowców.",
    ["O"] = "Przynieś Smokywood Supplies do karczmarki Pala w Thunder Bluff.",
    ["T"] = "Sylwestrowa celebracja!",
  },
  [8862] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Elune\'s Candle",
  },
  [8863] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Festival Dumplings",
  },
  [8864] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Festive Lunar Dresses",
  },
  [8865] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Festive Lunar Pant Suits",
  },
  [8866] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Starszy Bronzebeard",
  },
  [8867] = {
    ["D"] = "Każdego roku druidzi z Moonglade celebrują zwycięstwo naszego miasta nad wielkim złem.$B$BCzcimy mądrość naszych starszych, ucztujemy i oczywiście... wystrzeliwujemy fajerwerki!$B$BZa niewielką opłatą możesz kupić kolorowe rakiety od naszych kupców. Spróbuj użyć kilka z nich na działkach, $N.",
    ["O"] = "Wystrzel 8 Lunar Fireworks i 2 Cluster Fireworks i wróć do Lunar Festival Harbinger w jakiejkolwiek stolicy.",
    ["T"] = "Księżycowe fajerwerki",
  },
  [8868] = {
    ["D"] = "Bestia Omen niegdyś była bohaterem tego świata. Wilk o wielkiej sile i szczęściu, walczył u boku bohaterów, podczas Wojny Starożytnych, dopóki nie poddał się demonicznej magii. Zwrócony przeciwko swoim sojusznikom, przemierzał Azeroth, niosąc za sobą śmierć i zniszczenie.$B$BFinalnie poległ tutaj w Moonglade i Omen śpi w piachu jeziora Elune\'ara. Jednak każdego roku, podczas festiwalu się pojawia...$B$BZbierz ludzi, $N, przywołaj go i pokonaj bestię. Zdobądź błogosławieństwo Elune!",
    ["O"] = "Przywołaj Omena, pokonaj go i zdobądź błogosławieństwo Elune. Wróć do Valadara Starsonga w Nighthaven.",
    ["T"] = "Błogosławieństwo Elune",
  },
  [8869] = {
    ["D"] = "Wzdłuż granic Szkarłatnego Bastionu ukryte jest słodkie Ukojenie. Szkarłatny Kowal chroni tę formułę za wszelką cenę. Pokonaj go i przynieś mi jego fartuch, a nauczę cię, jak wyrabiać młoty.$B$BPamiętaj: jeśli wybierzesz tę ścieżkę, inne ścieżki nie będą już dostępne.",
    ["O"] = "Udaj się do Stratholme i zabij Crimson Hammersmith. Odzyskaj Crimson Hammersmith\'s Apron i wróć do Lilith.",
    ["T"] = "Słodkie Ukojenie",
  },
  [8870] = {
    ["D"] = "To jest ten czas w ciągu roku, $N! Krąg Cenariona zaprasza cały lud Azerothu do celebrowania Festiwalu Księżyca. Znajdziesz zwiastunów tego święta w każdym mieście, w lokacji oznaczonej błogosławionym kręgiem światła księżyca. Oni ci powiedzą więcej o tym święcie.",
    ["O"] = "Porozmawiaj z Lunar Festival Harbinger w Mystic Ward, w Ironforge. Możesz również porozmawiać z Lunar Festival Harbingers w innych stolicach.",
    ["T"] = "Święto Księżyca",
  },
  [8871] = {
    ["D"] = "To jest ten czas w ciągu roku, $N! Krąg Cenariona zaprasza cały lud Azeroth do celebrowania Festiwalu Księżyca. Znajdziesz zwiastunów tego święta w każdym mieście, w lokacji oznaczonej błogosławionym kręgiem światła księżyca. Oni ci powiedzą więcej o tym święcie.",
