  [8883] = {
    ["D"] = "Teraz, gdy masz zaproszenie, możesz udać się do Moonglade! Tam znajdziesz wielu biesiadników, a w wiosce Nighthaven Valadar Starsong i jego siostra Fariel, czekają na chętnych do przystąpienia w celebracji.$B$BPodąż do Moonglade poprzez wielkie światło księżycowe i porozmawiaj z Valadarem Starsong; sprawdź jakie nagrody będziesz w stanie otrzymać, podczas tego wydarzenia!",
    ["O"] = "Użyj Lunar Festival Invitation w świetle księżyca, by przeteleportować się do Moonglade. Porozmawiaj z Valadarem Starsong w Nighthaven, gdy tam dotrzesz.",
    ["T"] = "Valadar Starsong",
  },
  [8893] = {
    ["D"] = "Super Egg-O-Matic jest najnowszym wynalazkiem Curgle Cranklehop. To robiący wrażenie kawał maszynerii. $B$BKiedy zbliżasz się do panelu sterowania, Super Egg-O-Matic zaczyna wściekle warkotać.",
    ["O"] = "Przynieś 1 Jajo Hipogryfa do Jaj-O-Matu.",
    ["T"] = "Super Jaj-O-Mat",
  },
  [8897] = {
    ["D"] = "Muszę stać na straży przy bramie, ale ciągle martwię się o moją ukochaną, Colarę. Jeżeli mi się poszczęści, będę mógł się z nią zobaczyć tylko na kilka godzin, a spójrz tylko na mnie. Dostaję tylko drobne wynagrodzenie oficera i mogę zostać wysłany na front każdego dnia.$B$BMoże zapomniałaby o mnie? W mieście jest wielu mężczyzn. Wielu bogatych mężczyzn.$B$BTak czy inaczej, napisałem dla niej parę słów... nic wielkiego, ale byłbym wdzięczny za przekazanie jej tego.",
    ["O"] = "Dostarcz Lieutenant Heldric\'s Carefully Penned Note do Colary Dean przed bankiem w Stormwind.",
    ["T"] = "Najdroższa Colaro,",
  },
  [8898] = {
    ["D"] = "Spotkałem dziewczynę w Stormwind, kiedy ostatnim razem załatwiałem tam sprawy bankowe. Skradła moje serce. Teraz nie mogę przestać o niej myśleć! Chciałbym, żeby ta wiadomość do niej dotarła - przepisywałem ją dwanaście razy!$B$BPoczta jest teraz tak zajęta, a chciałbym mieć pewność, że liścik na pewno do niej trafi.$B$B$gMógłbyś:Mogłabyś; mi pomóc, jeżeli kierujesz się w tamtą stronę?",
    ["O"] = "Dostarcz Creased Letter do Colary Dean przed bankiem w Stormwind.",
    ["T"] = "Najdroższa Colaro,",
  },
  [8899] = {
    ["D"] = "Jak opisać jej piękno? Tysiące lat słów, a jestem w rozterce.$B$BCi śmiertelnicy mamią umysły i zmieniają nas w bełkoczących głupków.$B$BZbyt długo wpatrywałem się w te słowa. Nie wyciągnę z nich już ani krzty elokwentnego sensu więcej. Nie, ona musi to otrzymać teraz, lub inny zalotnik na pewno skradnie jej serce.",
    ["O"] = "Dostarcz Immaculate Letter do Colary Dean przed bankiem w Stormwind.",
    ["T"] = "Najdroższa Colaro,",
  },
  [8900] = {
    ["D"] = "Była taka smutna. Widziałem to po niej. To znaczy wydawała się smutna - prawda?$B$BAle po rozmowie z nią, poczułem pewną więź. Nie sądzę, żeby ktokolwiek mógł zrozumieć o czym myślałem, a jednak.$B$BKiedy opowiedziałem o tym reszcie, śmiali się ze mnie i przez to nigdy więcej już z nią nie rozmawiałem. Ale tęsknię za nią. $gMógłbyś:Mogłabyś; przekazać jej ode mnie ten list? Chcę mieć pewność, że do niej trafi.",
    ["O"] = "Dostarcz Slightly Creased Note do Elenii Haydon w pobliżu banku w Undercity.",
    ["T"] = "Najdroższa Elenio,",
  },
  [8901] = {
    ["D"] = "Czy kiedykolwiek $gdoświadczyłeś:doświadczyłaś; miłości, $gmłodzieniaszku:młoda;? Była ona dla mnie czymś nieznanym, aż do niedawna, kiedy spotkałem dziewczynę z Undercity, Elenię. Rzadko się zdarza, żeby ktoś z mojego rodzaju spojrzał na kogoś z zewnątrz, nie mówiąc już o kimś z Opuszczonych.$B$BLecz teraz myśli o niej zajmują moją głowę dniami i nocami.$B$B$gMógłbyś:Mogłabyś; przekazać jej ten list? Chciałbym, żeby przybyła do Mulgore. Mam nadzieję, że się zgodzi.",
    ["O"] = "Dostarcz Carefully Written Letter do Elenii Haydon w pobliżu banku w Undercity.",
    ["T"] = "Najdroższa Elenio,",
  },
  [8902] = {
    ["D"] = "Całe wieki temu miałem poślubić Elenię, moją ukochaną z dzieciństwa. Minęły już lata odkąd o niej myślałem, lecz ostatnio coraz częściej zajmuje moje myśli.$B$BByć może, pomimo upływu czasu, znajdzie się w naszych życiach miejsce na wzajemną miłość.$B$BOczywiście jestem pewny, że się zmieniła. $gMógłbyś:mogłabyś; przekazać jej ten list ode mnie? Boję się dać jej go osobiście.",
    ["O"] = "Dostarcz Lovingly Composed Letter do Elenii Haydon w pobliżu banku w Undercity.",
    ["T"] = "Najdroższa Elenio,",
  },
  [8903] = {
    ["D"] = "Ta epidemia miłości jest wręcz nienaturalna. To nie jest właściwe, to coś obrzydliwego, a co gorsza, może zagrażać bezpieczeństwu Przymierza.$B$BTylko pomyśl: co jeżeli strażnicy zostaną zwiedzeni przez tą dziwną przypadłość? Musimy coś z tym zrobić.$B$BIdź do jednego ze strażników w Stormwind i zobacz, czy został omamiony przez tę głupotę.",
    ["O"] = "Zdobądź Stormwind Guard\'s Card i oddaj Aristanowi Mottarowi w Stormwind.",
    ["T"] = "Niebezpieczna miłość",
  },
  [8904] = {
    ["D"] = "Ta epidemia miłości jest wręcz nienaturalna. To obrzydliwe, a przez fakt, że osłabia ona nasze szeregi, może być zagrożeniem dla nas wszystkich.$b$bWystarczy, że wielu naszych ludzi popadło w to absurdalne zachowanie. Lecz myślę, że szerzy się to również wśród strażników, którzy powinni być odporni na coś takiego.$b$bZnajdź jednego z naszych strażników i sprawdź, czy został omamiony przez tę głupotę.",
    ["O"] = "Zdobądź Guardian\'s Moldy Card i oddaj Fenstadowi Argyle\'owi w Undercity.",
    ["T"] = "Niebezpieczna miłość",
  },
  [8905] = {
    ["D"] = "Witaj, $C. Mam coś, co może cię zainteresować.$B$BJestem w posiadaniu zbroi bardzo podobnej do tej, którą noszą przedstawiciele twej profesji, ale o wiele lepszej jakości. Jestem skłonna wymienić te oto naramienniki na zwykłe w zamian za małą przysługę.$B$BKrew mroźnych panter i niedźwiedzi zamieszkujących Winterspring ma specjalne właściwości, których potrzebuję w tej chwili. Przynieś mi sporą próbkę owej krwi, razem z naramiennikami i niewielką ilością złota. Przekonasz się, że było warto.",
    ["O"] = "Zdobądź 15 Winterspring Blood Samples oraz 20 sztuk złota i przynieś je wraz z Wildheart Bracers do Deliany w Ironforge.",
    ["T"] = "Poważna propozycja",
  },
  [8906] = {
    ["D"] = "Witaj, $C. Mam tu coś, co może cię zainteresować.$B$BMam w posiadaniu zbroję podobną tym, które noszą przedstawiciele twej profesji, ale znacznie lepszej jakości. Mogę wymienić karawasze na zwykłe w zamian za niewielką przysługę.$B$BKrew mroźnych panter i niedźwiedzi zamieszkujących Winterspring ma właściwości, z których chętnie skorzystam. Przynieś mi pokaźny zapas krwi, karawasze i odrobinę złota, a zapewniam, że będzie ci się to opłacało.",
    ["O"] = "Zdobądź 15 Winterspring Blood Samples i 20 sztuk złota i zanieś je razem z Beaststalker\'s Bindings do Deliany w Ironforge.",
    ["T"] = "Poważna propozycja",
  },
