  },
  [8913] = {
    ["D"] = "Witaj, $C! Sądząc po twej posturze, z niejednego pieca chleb $gjadłeś:jadłaś;. Założę się jednak, że nie $gwidziałeś:widziałaś; takiej zbroi.$B$BMogę wymienić ten element zbroi na zwykły w zamian za niewielką przysługę.$B$BPotrzebuję sporej próbki jadu pobranego od pająków i skorpionów, które zamieszkują Silithus. Przynieś mi jad i odrobinę złota, a chętnie się wymienię.",
    ["O"] = "Zdobądź 15 Silithus Venom Samples i 20 sztuk złota i, zanieś je razem z Wildheart Bracers do Mokvara w Orgrimmarze.",
    ["T"] = "Poważna propozycja",
  },
  [8914] = {
    ["D"] = "Witaj, $C! Sądząc po twej posturze, z niejednego pieca chleb $gjadłeś:jadłaś;. Założę się jednak, że nie $gwidziałeś:widziałaś; takiej zbroi.$B$BMogę wymienić ten element zbroi na zwykły w zamian za niewielką przysługę.$B$BPotrzebuję sporej próbki jadu pobranego od pająków i skorpionów, które zamieszkują Silithus. Przynieś mi jad i odrobinę złota, a chętnie się wymienię.",
    ["O"] = "Zdobądź 15 Silithus Venom Samples i 20 sztuk złota, i zanieś je razem z Beaststalker\'s Bindings do Mokvara w Orgrimmarze.",
    ["T"] = "Poważna propozycja",
  },
