    ["O"] = "Wróć do Deliany w Ironforge z Beaststalker\'s Boots, Beaststalker\'s Pants i Beaststalker\'s Mantle.",
    ["T"] = "Pożegnalne słowa Anthiona",
  },
  [8953] = {
