  },
  [9113] = {
    ["D"] = "<Father Montoy makes some strange gestures in the air in front of you.>$B$BBlessed $g boy:girl;, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.$B$BBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.",
    ["O"] = "Father Inigo Montoy at Light\'s Hope Chapel in the Eastern Plaguelands will make a Circlet of Faith if you bring him the following: 1 Desecrated Circlet, 15 Wartorn Cloth Scraps, 3 Mooncloth and 3 Nexus Crystals.",
    ["T"] = "Circlet of Faith",
  },
  [9114] = {
    ["D"] = "<Father Montoy makes some strange gestures in the air in front of you.>$B$BBlessed $g boy:girl;, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.$B$BBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.",
    ["O"] = "Father Inigo Montoy at Light\'s Hope Chapel in the Eastern Plaguelands will make Shoulderpads of Faith if you bring him the following: 1 Desecrated Shoulderpads, 12 Wartorn Cloth Scraps, 2 Mooncloth and 3 Cured Rugged Hides.",
    ["T"] = "Shoulderpads of Faith",
  },
  [9115] = {
    ["D"] = "<Father Montoy makes some strange gestures in the air in front of you.>$B$BBlessed $g boy:girl;, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.$B$BBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.",
    ["O"] = "Father Inigo Montoy at Light\'s Hope Chapel in the Eastern Plaguelands will make Sandals of Faith if you bring him the following: 1 Desecrated Sandals, 12 Wartorn Cloth Scraps, 2 Mooncloth and 3 Cured Rugged Hides.",
    ["T"] = "Sandals of Faith",
  },
  [9116] = {
    ["D"] = "<Father Montoy makes some strange gestures in the air in front of you.>$B$BBlessed $g boy:girl;, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.$B$BBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.",
    ["O"] = "Father Inigo Montoy at Light\'s Hope Chapel in the Eastern Plaguelands will make Gloves of Faith if you bring him the following: 1 Desecrated Gloves, 8 Wartorn Cloth Scraps and 4 Mooncloth.",
    ["T"] = "Gloves of Faith",
  },
  [9117] = {
    ["D"] = "<Father Montoy makes some strange gestures in the air in front of you.>$B$BBlessed $g boy:girl;, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.$B$BBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.",
    ["O"] = "Father Inigo Montoy at Light\'s Hope Chapel in the Eastern Plaguelands will make a Belt of Faith if you bring him the following: 1 Desecrated Belt, 8 Wartorn Cloth Scraps, 2 Arcane Crystals and 2 Mooncloth.",
    ["T"] = "Belt of Faith",
  },
  [9118] = {
    ["D"] = "<Father Montoy makes some strange gestures in the air in front of you.>$B$BBlessed $g boy:girl;, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.$B$BBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.",
    ["O"] = "Father Inigo Montoy at Light\'s Hope Chapel in the Eastern Plaguelands will make Bindings of Faith if you bring him the following: 1 Desecrated Bindings, 6 Wartorn Cloth Scraps, 1 Arcane Crystal and 1 Nexus Crystal.",
    ["T"] = "Bindings of Faith",
  },
  [9120] = {
    ["D"] = "The phylactery is all that remains of the master of Naxxramas. Your better judgment dictates that you destroy the phylactery, preventing the lich from ever reforming. Thankfully, you seldom listen to that internal voice of reason.$B$BSomeone at Light\'s Hope will pay you hugely for this artifact. Who cares if Kel\'Thuzad regenerates to full power?",
    ["O"] = "Take the Phylactery of Kel\'Thuzad to Light\'s Hope Chapel in the Eastern Plaguelands.",
    ["T"] = "The Fall of Kel\'Thuzad",
  },
  [9121] = {
    ["D"] = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.$B$BWe have devised a way to gain entry via arcane cloaking - an old cantrip of the Kirin Tor with a few modifications of my own. Since your dedication to the cause of the Dawn is somewhat lacking, $N, the price will be high. You may decline and choose to return when you are revered or exalted for a discount.",
    ["O"] = "Archmage Angela Dosantos at Light\'s Hope Chapel in the Eastern Plaguelands wants 5 Arcane Crystals, 2 Nexus Crystals, 1 Righteous Orb and 60 gold pieces. You must also be Honored with the Argent Dawn.",
    ["T"] = "The Dread Citadel - Naxxramas",
  },
  [9122] = {
    ["D"] = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.$B$BWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly. Since your dedication to the cause of the Dawn is admirable, we are willing to incur some of those costs.",
    ["O"] = "Archmage Angela Dosantos at Light\'s Hope Chapel in the Eastern Plaguelands wants 2 Arcane Crystals, 1 Nexus Crystal and 30 gold pieces. You must also be Revered with the Argent Dawn.",
    ["T"] = "The Dread Citadel - Naxxramas",
  },
  [9123] = {
    ["D"] = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.$B$BWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.",
    ["O"] = "Archmage Angela Dosantos at Light\'s Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn.",
    ["T"] = "The Dread Citadel - Naxxramas",
  },
  [9124] = {
    ["D"] = "Jak chciałbyś zapracować na jedną z tych lśniących monet?$B$B<Leopold podnosi Insygnię Krucjaty.>$B$BMam mały problem, z którym mógłbyś mi pomóc, $N. Wiesz, robię Cryptstalker Armor dla tych, którzy są na tyle stuknięci, aby zapędzić się do Naxxramas. Podczas gdy dostarczają mi najważniejszych materiałów potrzebnych do stworzenia zbroji, zawsze kończą mi się kawałki Crypt Fiend. Dostarcz mi paczkę tych kawałków, a zapłace ci Insygnią - przydatną u kwatermistrza.",
    ["O"] = "Łowca Leopold w Light\'s Hope Chapel w Eastern Plaguelands potrzebuje 30 kawałków Crypt Fiend.",
    ["T"] = "Cryptstalker Armor nie zrobi się sam",
  },
  [9125] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Crypt Fiend Parts",
  },
  [9126] = {
    ["D"] = "Wzór pancerza Bonescythe Don Julia wymaga fragmentów kości - bardzo wielu fragmentów kości. Podczas gdy ci, którzy są wystarczająco szaleni, by zaryzykować zapuszczenie się do Naxxramas, dostarczają mi dość dużo podstawowych materiałów do stworzenia zbroi, zawsze szukam więcej fragmentów kości Plagi.$B$BWięc, co o tym myślisz? Zainteresowany pobrudzeniem sobie rączek i przy okazji zniszczeniem części Plagi? Wilk syty i owca cała.",
    ["O"] = "Rohan the Assassin w Light\'s Hope Chapel w Eastern Plaguelands potrzebuje 30 fragmentów kości.",
    ["T"] = "Bonescythe Digs",
  },
  [9127] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Bone Fragments",
  },
  [9128] = {
    ["D"] = "Bądź zdrów, poszukiwaczu przygód! Czy jesteś zainteresowany pewną pracą? Płacę tym, których zatrudniam, insygniami. Te insygnia mogą być użyte u kwatermistrza do zakupu przedmiotów mocy.$B$BWszystko, co musisz zrobić, to przynieść mi tyle rdzenii elementów, ile jesteś w stanie unieść. Im więcej, tym lepiej!$B$BZnajdziesz je w żywiołach o różnych kształtach i rozmiarach, które istnieją w naszym świecie.",
    ["O"] = "Arcymag Angela Dosantos w Light\'s Hope Chapel w Eastern Plaguelands potrzebuje 30 Core of Elements.",
    ["T"] = "The Elemental Equation",
  },
  [9129] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Core of Elements",
  },
  [9131] = {
    ["D"] = "Czy widziałeś kiedyś pancerz Dreadnoughta, $C? Nie, oczywiście że nie. Wciąż jesteś $gchłopcem:dziewczynką; - dzieciakiem. Mówię ci, jest wspaniała.$B$BPrawdopodobnie zadajesz sobie pytanie, co to ma z tobą wspólnego, prawda? Powiem ci co, pętaku; potrzebuję kawałków mrocznego żelaza i jestem gotów zapłacić, aby zdobyć tak wiele, jak to możliwe.$B$BPotrzebuję kawałków, by złożyć do kupy całe zbroje Dreadnoughta dla naszych czempionów. Przynieś mi żelazo i pobierz zapłatę.",
    ["O"] = "Korfax w Light\'s Hope Chapel w Eastern Plaguelands potrzebuje 30 Dark Iron Scraps.",
    ["T"] = "Binding the Dreadnaught",
  },
  [9132] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Dark Iron Scraps",
  },
  [9136] = {
    ["D"] = "Tworzę specjalną zbroję, znaną jako Dreamwalker, dla odważnych wojowników, którzy wkroczyli do Naxxramas. Dostarczają mi oni większość wymaganych materiałów, jednak zawsze poszukuję osób, które są w stanie przynieść mi dzikie liście roślin z naszego świata.$B$BMożesz sobie myśleć, że to poniżej twoich kwalifikacji, ale bez tych liści zbroja nie mogłaby powstać.$B$BMogę też zapłacić ci Symbolami, które sobie wybierzesz, jako że zarówno Świt, jak i Krucjata, dają mi na to środki.",
    ["O"] = "Rayne w Light\'s Hope Chapel, w Eastern Plaguelands, potrzebuje 30 Savage Fronds.",
    ["T"] = "Dzika flora",
  },
  [9137] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Savage Fronds",
  },
  [9141] = {
    ["D"] = "Chcesz zadanie? Co? Oczekujesz, że dam ci pożądane przez wszystkich zlecenie tylko za to, że się tu $gpokazałeś:pokazałaś;? Nie wydaje mi się, łamago. Rzemieślnicy z całego świata próbują zdobyć pracę na linii frontu.$B$BJeśli chcesz coś do roboty, będziesz $gmusiał:musiała; pokazać, że jesteś $ggotów:gotowa; poświęcić się dla sprawy. Przynieś mi symbol męstwa, a wtedy porozmawiamy.$B$BIstnieje tylko jedna droga, aby go zdobyć. Musisz zacząć zabijać.",
    ["O"] = "Przynieś Argent Dawn Valor Token do Dispatch Commander Metz w Light\'s Hope Chapel w Eastern Plaguelands.",
    ["T"] = "Zwą mnie \"Kogut\"",
  },
  [9142] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Pismo rzemieślnika",
  },
  [9153] = {
    ["D"] = "The floating necropolises of the Scourge plague the lands of Horde and Alliance alike. Tanaris, the Blasted Lands, Winterspring and the Burning Steppes are blanketed in the shadows of the flying fortresses.$b$bOnly through our combined efforts will they be turned away.$b$bThe necropolises are supported by magical circles at various points in the invaded areas. We have determined that destroying the mindless hordes that surround these circles will destroy their defenses.",
    ["O"] = "Check your map to find an area under Scourge attack. Go there and damage a necropolis by defeating the Scourge around them. Return 10 of their Necrotic Runes to Commander Thomas Helleran at Light\'s Hope Chapel in the Eastern Plaguelands.",
    ["T"] = "Under the Shadow",
  },
  [9154] = {
    ["D"] = "The Scourge have returned in greater numbers than we have seen before. The Argent Dawn is recruiting all willing and capable men and women to defend our lands.$b$bIf we share common cause, take this document to the Keeper of the Rolls at Light\'s Hope Chapel in the Eastern Plaguelands.",
    ["O"] = "Deliver the Call to Arms Announcement to the Keeper of the Rolls at Light\'s Hope Chapel in the Eastern Plaguelands.",
    ["T"] = "Light\'s Hope Chapel",
  },
  [9165] = {
    ["D"] = "Without the help of adventurers, my caravan would have never made it! Scourge were coming out of the woodwork to try and stop us from getting here.$B$B<Guard Didier wipes his brow.>$B$BNow we need to wait here for Field Marshal Chambers to arrive. He\'ll sign your writ of safe passage to take back to Dispatch Commander Metz at Light\'s Hope Chapel.$B$BAnd $N, watch what you say around Chambers. He\'s the \'bite off your head and spit down your wind pipe\' type of guy - except that he\'ll actually do it...",
    ["O"] = "Deliver the signed Writ of Safe Passage to Dispatch Commander Metz at Light\'s Hope Chapel in the Eastern Plaguelands.",
    ["T"] = "Writ of Safe Passage",
  },
  [9178] = {
    ["D"] = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.$B$BWork Order BS-091:$B$B120 Dense Weightstones.$B$BAll filled orders should be delivered to Packmaster Stonebruiser at Light\'s Hope Chapel in the Eastern Plaguelands.$B$BContract is null and void if tampered with or damaged.$B$B-Dispatch Commander Metz, The Argent Dawn",
    ["O"] = "Deliver 120 Dense Weightstones and the Craftsman\'s Writ - Dense Weightstone - to Packmaster Stonebruiser at Light\'s Hope Chapel in the Eastern Plaguelands.",
    ["T"] = "Craftsman\'s Writ - Dense Weightstone",
  },
  [9179] = {
    ["D"] = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.$B$BWork Order BS-428:$B$B3 Imperial Plate Chests.$B$BAll filled orders should be delivered to Packmaster Stonebruiser at Light\'s Hope Chapel in the Eastern Plaguelands.$B$BContract is null and void if tampered with or damaged.$B$B-Dispatch Commander Metz, The Argent Dawn",
    ["O"] = "Deliver 3 Imperial Plate Chests and the Craftsman\'s Writ - Imperial Plate Chest - to Packmaster Stonebruiser at Light\'s Hope Chapel in the Eastern Plaguelands.",
    ["T"] = "Craftsman\'s Writ - Imperial Plate Chest",
  },
  [9181] = {
    ["D"] = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.$B$BWork Order BS-697:$B$B3 Volcanic Hammers.$B$BAll filled orders should be delivered to Packmaster Stonebruiser at Light\'s Hope Chapel in the Eastern Plaguelands.$B$BContract is null and void if tampered with or damaged.$B$B-Dispatch Commander Metz, The Argent Dawn",
    ["O"] = "Deliver 3 Volcanic Hammers and the Craftsman\'s Writ - Volcanic Hammer - to Packmaster Stonebruiser at Light\'s Hope Chapel in the Eastern Plaguelands.",
    ["T"] = "Craftsman\'s Writ - Volcanic Hammer",
  },
  [9182] = {
    ["D"] = "Posiadacz tego pisma jest uprawniony do zapłaty w postaci wybranych przez siebie insygniów po zrealizowaniu zakontraktowanego zamówienia na pracę.$B$BWykonanie pracy BS-6020:$B$B3 Olbrzymie Topory Bojowe z Thorium.$B$BWszystkie wypełnione zlecenia należy dostarczyć do Stonebruisera przebywającego w Świątyni Nadziei Światłości na Wschodnich Ziemiach Plagi.$B$BKontrakt jest nieważny, jeśli zostanie naruszony lub uszkodzony.$B$B-Podpisano: Dowódca Metz, Srebrzysty Świt.",
    ["O"] = "Dostarcz 3 Huge Thorium Battleaxes oraz Craftsman\'s Writ - Huge Thorium Battleaxe - do Packmaster Stonebruiser przebywającego w Light\'s Hope Chapel, w Eastern Plaguelands.",
    ["T"] = "Nakaz rzemieślniczy - Olbrzymi Topór Bojowy z Thorium",
  },
  [9183] = {
    ["D"] = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.$B$BWork Order BS-80:$B$B3 Radiant Circlets.$B$BAll filled orders should be delivered to Packmaster Stonebruiser at Light\'s Hope Chapel in the Eastern Plaguelands.$B$BContract is null and void if tampered with or damaged.$B$B-Dispatch Commander Metz, The Argent Dawn",
    ["O"] = "Deliver 3 Radiant Circlets and the Craftsman\'s Writ - Radiant Circlet - to Packmaster Stonebruiser at Light\'s Hope Chapel in the Eastern Plaguelands.",
    ["T"] = "Craftsman\'s Writ - Radiant Circlet",
