  [9319] = {
    ["D"] = "We are not the only ones who celebrate this holiday, $n. All creatures, all cultures, are touched by the flame. Even in the darkest places, the fires are being lit.$b$bIf you wish to see them for yourself, travel into the depths. Seek out the bonfires burning within Stratholme, Scholomance, among the ogres of Dire Maul, and the halls of Blackrock Spire itself; I will await your return.",
    ["O"] = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then return to the Festival Flamekeeper.",
    ["T"] = "A Light in Dark Places",
  },
  [9320] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Major Mana Potion",
  },
  [9321] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "Major Healing Potion",
  },
  [9322] = {
    ["D"] = "The Midsummer Fire Festival is celebrated everywhere in Azeroth, and the diverse land of Kalimdor is no exception. You look fit to travel -- perhaps a journey is in order.$b$bMidsummer cannot be truly appreciated unless you\'ve seen the blistering blue fires abroad. The celebrants have lit fires in chilly western Winterspring, northeastern Azshara, near Valor\'s Rest in the wastes of Silithus, and by the entrance to lush Un\'Goro. Return once your journey is complete.",
    ["O"] = "Visit the Midsummer camps located in Azshara, Silithus, Un\'Goro Crater, and Winterspring, then return to the Festival Flamekeeper.",
    ["T"] = "Wild Fires in Kalimdor",
  },
  [9323] = {
    ["D"] = "Our celebration of the flame is spread throughout the land, $c. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue. Seek them out.$b$bYou\'ll find one just north of Blackrock Spire. The others are located deep within the Eastern Plaguelands near a decrepit town, along the road to the cliffs within the mountainous Hinterlands, and on the way to the Dark Portal within the Blasted Lands.$b$b Return once your journey is done.",
    ["O"] = "Visit the Fire Festival camps located in Blasted Lands, Eastern Plaguelands, the Hinterlands and Searing Gorge, then speak with the Festival Flamekeeper.",
    ["T"] = "Wild Fires in the Eastern Kingdoms",
  },
  [9324] = {
    ["D"] = "Ogień, skradziony z serca miasta Orgrimmaru wypełnia cię ciepłem. Jego czysta moc jest dla ciebie obca, może Wiedziciel wie o nim coś więcej...",
    ["O"] = "Przynieś Flame of Orgrimmar do Festival Loremaster.",
    ["T"] = "Kradzież ognia Orgrimmaru",
  },
  [9325] = {
    ["D"] = "Ogień, skradziony z serca miasta Thunder Bluff wypełnia cię ciepłem. Jego czysta moc jest dla ciebie obca, może Wiedziciel wie o nim coś więcej...",
    ["O"] = "Przynieś Flame of Thunder Bluff do Festival Loremaster.",
    ["T"] = "Kradzież ognia z Thunder Bluff",
  },
  [9326] = {
    ["D"] = "Ogień, skradziony z ruin nad miastem Undercity wypełnia cię ciepłem. Jego czysta moc jest dla ciebie obca, może Wiedziciel wie o nim coś więcej...",
    ["O"] = "Przynieś Flame of the Undercity do Festival Loremaster.",
    ["T"] = "Kradzież ognia z Undercity",
  },
  [9330] = {
    ["D"] = "Ogień, skradziony z serca miasta Stormwind wypełnia cię ciepłem. Jego czysta moc jest dla ciebie obca, może Gawędziarz wie o nim coś więcej...",
    ["O"] = "Przynieś Flame of Stormwind do Festival Talespinner.",
    ["T"] = "Kradzież ognia ze Stormwind",
  },
  [9331] = {
    ["D"] = "Ogień, skradziony z serca miasta Ironforge wypełnia cię ciepłem. Jego czysta moc jest dla ciebie obca, może Gawędziarz wie o nim coś więcej...",
    ["O"] = "Przynieś Flame of Ironforge do Festival Talespinner.",
    ["T"] = "Kradzież ognia z Ironforge",
  },
  [9332] = {
    ["D"] = "Ogień, skradziony z wybrzeża Darnassus wypełnia cię ciepłem. Jego czysta moc jest dla ciebie obca, może Gawędziarz wie o nim coś więcej...",
    ["O"] = "Przynieś Flame of Darnassus do Festival Talespinner.",
    ["T"] = "Kradzież ognia z Darnassus",
  },
