  },
  [9414] = {
    ["D"] = "",
    ["O"] = "",
    ["T"] = "<UNUSED>Infused Bandages",
  },
  [9415] = {
    ["D"] = "Jesteś nowym rekrutem marszałka Bluewall? Oczywiście, że jesteś.$B$BNa co czekasz? Poczciwi żołnierze umierają wśród piasków pustyni. Nie cieszysz się, że do nich dołączysz?$B$BA teraz, idź i nie odwodnij się po drodze.",
    ["O"] = "Porozmawiaj z Marszałkiem Bluewall w obozowisku Przymierza, niedaleko Hive\'Zora.",
    ["T"] = "Staw się u marszałka Bluewall",
  },
  [9416] = {
    ["D"] = "Ty musisz być nowym rekrutem generał Kiriki. $gPrzyszedłeś:Przyszłaś; rychło w czas. Na pustyni ludzie bardzo szybko tracą siły.$B$BKrasnoludy dostają codziennie wsparcie, a my nie możemy sobie pozwolić na to, by wygrali walkę o zasoby naturalne w Silithus.$B$BIdź do generał po dalsze rozkazy. Nie moim zadaniem jest cię przyuczać, tylko odnaleźć.",
    ["O"] = "Porozmawiaj z generał Kiriką w obozowisku Hordy niedaleko Hive\'Regal.",
    ["T"] = "Staw się u generał Kiriki",
  },
  [9419] = {
    ["D"] = "Ostatnio odkryliśmy, że Horda przeczesuje pustynię w poszukiwaniu zasobów, ale nie przykładaliśmy do tego zbytniej wagi. Myśleliśmy, że nie opłaca się nam wysyłać większej jednostki na tę patelnię.$B$BJednakże odkryliśmy, że te zasoby są bardzo cenne i teraz próbujemy dogonić Hordę w ich staraniach.$B$BJeśli $gchciałbyś:chciałabyś; pomóc, to musisz wyruszyć na pustynię, zdobyć silithyst i przynieść go tutaj.",
    ["O"] = "Znajdź i dostarcz Silithyst do Silithyst Extractor, następnie porozmawiaj z marszałkiem Bluewall w obozie Przymierza niedaleko Hive\'Zora.",
    ["T"] = "Przeszukiwanie pustyni",
  },
  [9422] = {
    ["D"] = "Od jakiegoś czasu wydobywamy kryształy z pustyni Silithus. Jedynymi zagrożeniami na tym terenie są dla nas stworzenia, które nazwały tę krainę swym domem, piasek, pył oraz upały.$B$BOkazuje się jednak, że Przymierze zorientowało się, co tu znaleźliśmy. Obecnie ścigamy się w zdobywaniu naturalnych zasobów, tak by zrobić to szybciej niż przeciwnik.$B$BPotrzebuję każdej możliwej pary rąk do pomocy. Mam nadzieję, że możemy liczyć na twoją pomoc.",
    ["O"] = "Znajdź i dostarcz Silithyst do Silithyst Extractor, następnie porozmawiaj z generałem Kirika w obozie Hordy niedaleko Hive\'Regal.",
    ["T"] = "Przeszukiwanie pustyni",
  },
